let passed = 0;
let failed = 0;

function assert(condition, message) {
  if (condition) {
    passed++;
  } else {
    failed++;
    console.error('FAIL: ' + message);
  }
}

// Scenario registry. Every top-level block below is a self-contained scenario: it owns
// its own fixtures and shares nothing with its neighbours but the pure helpers and these
// counters. Registering them through scenario() makes the list partitionable, so
// `--shard i/N` runs a disjoint stride of it in a worker process. WITHOUT --shard every
// scenario runs, in file order — a bare `node scripts/test-adaptive-node.js` is unchanged.
const shardLib = require('./test-shard-lib');
// Git FIXTURE arrangement routes through the shared library — one process-boundary
// decision for the repo instead of one per line. See scripts/test-git-fixture.js.
const G = require('./test-git-fixture');
const SHARD = shardLib.selector(process.argv);
let scenarioCount = 0;
let scenariosRun = 0;

function scenario(fn) {
  const ordinal = scenarioCount++;
  if (!SHARD.owns(ordinal)) return;
  scenariosRun++;
  shardLib.runScenario(ordinal, fn);
}

// Existing lifecycle fixtures exercise the byte-preserved legacy-v1 engine.
// Schema 2 deliberately refuses a newly authored field-absent draft, so these
// fixtures first materialize the historical verified-frozen state they mean to
// simulate, then run the same --freeze --repair transaction.
// #765 (Wave E2 cutover): the legacy `dag` grammar is retired at the freeze wall — `plan_form: spine`
// is the only authorable shape (a fully-known-at-freeze plan is an all-concrete spine, semantically
// equal to the old dag). Inject the discriminator into a fixture's ## Meta when absent, fence-aware so
// a decoy `## Meta` inside a code fence is skipped. No-op when plan_form is already declared.
function injectSpineForm(content) {
  if (/^[ \t]*plan_form[ \t]*:/m.test(content)) return content;
  const lines = content.split('\n');
  let fence = null;
  for (let i = 0; i < lines.length; i++) {
    const m = lines[i].match(/^([`~]{3,})/);
    if (m) {
      if (fence === null) fence = m[1][0].repeat(m[1].length);
      else if (m[1][0] === fence[0] && m[1].length >= fence.length) fence = null;
      continue;
    }
    if (fence === null && /^## Meta[ \t]*$/.test(lines[i])) {
      lines.splice(i + 1, 0, 'plan_form: spine');
      return lines.join('\n');
    }
  }
  return content;
}

// #790: a frozen plan requires a non-empty `## Design` section at the freeze wall. Legacy fixtures
// predate the section, so inject a minimal prose block when absent — the same normalization posture as
// injectSpineForm. Inserted BEFORE `## Node Ledger` (so the hash-NEUTRAL ledger remains the tail
// section — fixtures that append a ledger row / halt marker to the tail rely on that; `## Design` IS
// hash-covered and must not become the tail). No `## Node Ledger` ⇒ appended at the end. No-op when a
// `## Design` heading already exists.
function injectDesignSection(content) {
  if (/^##[ \t]+Design[ \t]*$/m.test(content)) return content;
  const block = '## Design\n\n'
    + 'Decompose the frozen spine into its concrete role nodes; every sequence edge is a real data '
    + 'dependency (S1 — the downstream node consumes the upstream node\'s change) or a gate ordering, '
    + 'and any co-opened write legs touch disjoint paths. Done means the review gate clears and '
    + 'validation_command passes.\n';
  const lines = content.split('\n');
  // Fence-aware scan for the FIRST GENUINE `## Node Ledger` (skip a decoy inside a ``` / ~~~ fence).
  let fence = null, ledgerIdx = -1;
  for (let i = 0; i < lines.length; i++) {
    const m = lines[i].match(/^([`~]{3,})/);
    if (m) { if (fence === null) fence = m[1][0].repeat(m[1].length); else if (m[1][0] === fence[0] && m[1].length >= fence.length) fence = null; continue; }
    if (fence === null && /^##[ \t]+Node Ledger[ \t]*$/.test(lines[i])) { ledgerIdx = i; break; }
  }
  if (ledgerIdx >= 0) {
    lines.splice(ledgerIdx, 0, block, '');
    return lines.join('\n');
  }
  return content.replace(/\n*$/, '\n') + '\n' + block;
}

function stampVerifiedLegacyPlan(planPath) {
  const raw = fs.readFileSync(planPath, 'utf8');
  if (/<!--\s*plan_hash:\s*[0-9a-f]{64}\s*-->/.test(raw)) return;
  const content = injectDesignSection(injectSpineForm(raw));
  const hash = planValidator.computePlanHash(content);
  fs.writeFileSync(planPath, '<!-- plan_hash: ' + hash + ' -->\n\n' + content);
}

function freezeLegacyFixture(execFn, command, validator, planPath, options) {
  stampVerifiedLegacyPlan(planPath);
  return execFn(command, [validator, planPath, '--freeze', '--repair', '--json'], options);
}

// Repair attempt n5-core-review:1 RED matrix (R1/R2/R4/R5).
scenario(() => {
  const src = fs.readFileSync(path.join(__dirname, 'kaola-workflow-adaptive-node.js'), 'utf8');
  const guardedSet = (src.match(/const SPLIT_GUARDED_SUBCOMMANDS = new Set\(\[([\s\S]*?)\]\);/) || [])[1] || '';
  assert(guardedSet.includes("'record-evidence'"),
    'R1-LOCK-RED: mutating record-evidence participates in the project-lock predicate');

  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-review-r1-'));
  try {
    const projectDir = path.join(tmp, 'kaola-workflow', 'issue-r1');
    const cacheDir = path.join(projectDir, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    const body = makePlan(['| writer | in_progress | |'], [
      '| writer | tdd-guide | — | scripts/a.js | 1 | sequence |',
    ]);
    const hash = planValidator.computePlanHash(body);
    const planPath = path.join(projectDir, 'workflow-plan.md');
    fs.writeFileSync(planPath, '<!-- plan_hash: ' + hash + ' -->\n' + body);
    fs.writeFileSync(path.join(cacheDir, 'barrier-base-writer'), 'currentnonce12-rest\n');
    let writes = 0;
    const unbound = runRecordEvidence({ planPath, project: 'issue-r1', nodeId: 'writer',
      stdinContent: 'RED: stale\nGREEN: stale\n', readFile: p => fs.readFileSync(p, 'utf8'),
      writeFile: () => { writes++; }, cacheExists: p => fs.existsSync(p), mkdirp: () => {} });
    assert(unbound.reason === 'evidence_generation_required' && writes === 0,
      'R1-GENERATION-RED: hashed plans reject unbound stdin instead of minting the current generation');
  } finally { fs.rmSync(tmp, { recursive: true, force: true }); }

  const hash = 'a'.repeat(64);
  assert(validateReviewJournal({ schema_version: 1, plan_hash: hash, attempts: [{ attempt_id: 'x:1' }] }, hash).ok === false,
    'R2-SCHEMA-RED: incomplete v1 attempts fail closed');
  const crypto = require('crypto');
  const gate = canonicalLogicalGateIdentity({ kind: 'sequence', id: 'review', origin: ['writer'], members: ['review'] });
  const generations = [{ member: 'review', nonce: 'nonce12345678' }];
  const digest = 'b'.repeat(64);
  const tx = crypto.createHash('sha256').update(JSON.stringify({ plan_hash: hash,
    logical_gate_key: gate.key, candidate_digest: digest, generations })).digest('hex');
  const body = 'evidence-binding: review nonce12345678\nverdict: fail\nfindings_blocking: 1\n';
  const forged = { attempt_id: 'review:1', ordinal: 1, plan_hash: hash, logical_gate: gate,
    transaction_key: tx, candidate_digest: digest,
    candidate_declared: {}, candidate_residue_digest: 'd'.repeat(64), generations, settlement_command: 'close-node',
    outcome: 'fail', reason: 'verdict_not_pass', lifecycle_settled: true,
    repair: { selected_writer: null, settled: null }, rebind: [], consumed_by: null, findings: [], route_candidates: [],
    receipts: [{ node_id: 'review', generation: 'nonce12345678',
      receipt_sha256: crypto.createHash('sha256').update(body).digest('hex'), body,
      effective_pass: true, verdict: 'pass', findings_blocking: 0 }],
  };
  assert(validateReviewJournal({ schema_version: 1, plan_hash: hash, attempts: [forged] }, hash).reason === 'review_journal_receipt_verdict_mismatch',
    'R2-FORGERY-RED: receipt verdict fields are recomputed from exact body');

  const findingRaw = 'id=F-1 scope=in_scope action=fix status=open severity=high file=scripts/shared.js fix_role=tdd-guide';
  const findingBody = 'evidence-binding: review nonce12345678\nverdict: fail\nfindings_blocking: 1\nfinding: ' + findingRaw + '\n';
  const canonicalFinding = { source_node: 'review', raw: findingRaw, id: 'F-1', scope: 'in_scope',
    action: 'fix', status: 'open', severity: 'high', file: 'scripts/shared.js', fix_role: 'tdd-guide' };
  const canonicalRoute = { source_node: 'review', finding_id: 'F-1', id: 'F-1', scope: 'in_scope',
    action: 'fix', status: 'open', severity: 'high', file: 'scripts/shared.js',
    ownership_candidates: ['writer-a', 'writer-b'], owning_node: null, fix_role: 'tdd-guide', raw: findingRaw };
  const authoritative = { ...forged, receipts: [{ node_id: 'review', generation: 'nonce12345678',
    receipt_sha256: crypto.createHash('sha256').update(findingBody).digest('hex'), body: findingBody,
    effective_pass: false, verdict: 'fail', findings_blocking: 1 }],
    findings: [canonicalFinding], route_candidates: [canonicalRoute] };
  assert(validateReviewJournal({ schema_version: 1, plan_hash: hash,
    attempts: [{ ...authoritative, outcome: 'pass', reason: null }] }, hash).reason === 'review_journal_outcome_mismatch',
  'R9-SCHEMA-RED: sequence outcome/reason must equal the exact effective receipt verdict');
  const staleBindingBody = 'evidence-binding: foreign stale-nonce\nverdict: fail\nfindings_blocking: 1\n';
  const staleBindingAttempt = { ...authoritative,
    receipts: [{ node_id: 'review', generation: 'nonce12345678', body: staleBindingBody,
      receipt_sha256: crypto.createHash('sha256').update(staleBindingBody).digest('hex'),
      effective_pass: false, verdict: 'fail', findings_blocking: 1 }],
    findings: [], route_candidates: [] };
  assert(validateReviewJournal({ schema_version: 1, plan_hash: hash,
    attempts: [staleBindingAttempt] }, hash).reason === 'review_journal_receipt_binding_mismatch',
  'R12-BINDING-RED: exact receipt body must bind once to receipt node and generation');

  const fanoutGate = canonicalLogicalGateIdentity({ kind: 'fanout', id: 'red-team',
    origin: ['writer'], members: ['skeptic-a', 'skeptic-b', 'skeptic-c'] });
  const fanoutGenerations = fanoutGate.members.map((member, i) => ({ member, nonce: 'fanoutnonce' + i }));
  const fanoutReceipt = (member, pass) => {
    const generation = fanoutGenerations.find(g => g.member === member).nonce;
    const body = 'evidence-binding: ' + member + ' ' + generation + '\nverdict: '
      + (pass ? 'pass' : 'fail') + '\nfindings_blocking: ' + (pass ? '0' : '1') + '\n';
    return { node_id: member, generation, body,
      receipt_sha256: crypto.createHash('sha256').update(body).digest('hex'),
      effective_pass: pass, verdict: pass ? 'pass' : 'fail', findings_blocking: pass ? 0 : 1 };
  };
  const fanoutAttempt = { attempt_id: 'fanout-' + crypto.createHash('sha256').update(fanoutGate.key).digest('hex') + ':1',
    ordinal: 1, plan_hash: hash, logical_gate: fanoutGate, candidate_digest: '6'.repeat(64),
    candidate_declared: {}, candidate_residue_digest: 'd'.repeat(64),
    generations: fanoutGenerations,
    transaction_key: crypto.createHash('sha256').update(JSON.stringify({ plan_hash: hash,
      logical_gate_key: fanoutGate.key, candidate_digest: '6'.repeat(64), generations: fanoutGenerations })).digest('hex'),
    settlement_command: 'close-node', outcome: null, reason: null,
    receipts: [fanoutReceipt('skeptic-a', true)], findings: [], route_candidates: [],
    lifecycle_settled: false, repair: { selected_writer: null, settled: null }, rebind: [], consumed_by: null };
  assert(validateReviewJournal({ schema_version: 1, plan_hash: hash,
    attempts: [fanoutAttempt] }, hash).ok === true,
  'R12-QUORUM-RED: partial receipt set remains legal only as provisional null outcome');
  assert(validateReviewJournal({ schema_version: 1, plan_hash: hash,
    attempts: [{ ...fanoutAttempt, outcome: 'pass', lifecycle_settled: true }] }, hash).reason === 'review_journal_fanout_quorum_mismatch',
  'R12-QUORUM-RED: settled/non-null fanout requires every exact member receipt');
  const minorityReceipts = [fanoutReceipt('skeptic-a', true), fanoutReceipt('skeptic-b', false), fanoutReceipt('skeptic-c', false)];
  assert(validateReviewJournal({ schema_version: 1, plan_hash: hash,
    attempts: [{ ...fanoutAttempt, receipts: minorityReceipts, outcome: 'pass', lifecycle_settled: true }] }, hash).reason === 'review_journal_outcome_mismatch',
  'R12-MAJORITY-RED: fanout pass cannot contradict strict majority of exact bodies');
  const majorityReceipts = [fanoutReceipt('skeptic-a', true), fanoutReceipt('skeptic-b', true), fanoutReceipt('skeptic-c', false)];
  assert(validateReviewJournal({ schema_version: 1, plan_hash: hash,
    attempts: [{ ...fanoutAttempt, receipts: majorityReceipts, outcome: 'pass', lifecycle_settled: true }] }, hash).ok === true,
  'R12-MAJORITY-RED: complete strict-majority quorum is valid');

  assert(validateReviewJournal({ schema_version: 1, plan_hash: hash,
    attempts: [{ ...authoritative, repair: { selected_writer: '', settled: true }, consumed_by: '' }] }, hash).ok === false,
  'R13-EMPTY-RED: empty selected/consumed writer cannot stop a failed-attempt fence');
  assert(validateReviewJournal({ schema_version: 1, plan_hash: hash,
    attempts: [{ ...authoritative, findings: [42] }] }, hash).ok === false,
  'R8-FINDINGS-RED: authoritative findings must equal canonical rows reparsed from receipt bodies');
  assert(validateReviewJournal({ schema_version: 1, plan_hash: hash,
    attempts: [{ ...authoritative, route_candidates: [{ ...canonicalRoute,
      ownership_candidates: ['writer-b', 'writer-a'], owning_node: 'writer-a' }] }] }, hash).ok === false,
  'R8-ROUTE-RED: routes reject unsorted multi-owner candidates and illegal owner selection');

  const routePlanBody = makePlan(['| writer-a | complete | |', '| writer-b | complete | |',
    '| review | complete | |', '| finalize | pending | |'], [
    '| writer-a | tdd-guide | — | scripts/shared.js | 1 | sequence |',
    '| writer-b | tdd-guide | — | scripts/shared.js | 1 | sequence |',
    '| review | code-reviewer | writer-a, writer-b | — | 1 | sequence |',
    '| finalize | finalize | review | — | 1 | sequence |',
  ]);
  const routeHash = planValidator.computePlanHash(routePlanBody);
  const routePlan = '<!-- plan_hash: ' + routeHash + ' -->\n' + routePlanBody;
  const routeGate = canonicalLogicalGateIdentity({ kind: 'sequence', id: 'review',
    origin: ['writer-a', 'writer-b'], members: ['review'] });
  const routeGenerations = [{ member: 'review', nonce: 'nonce12345678' }];
  const routeDigest = '9'.repeat(64);
  const routeAttempt = { ...authoritative, plan_hash: routeHash, logical_gate: routeGate,
    candidate_digest: routeDigest, generations: routeGenerations,
    transaction_key: crypto.createHash('sha256').update(JSON.stringify({ plan_hash: routeHash,
      logical_gate_key: routeGate.key, candidate_digest: routeDigest, generations: routeGenerations })).digest('hex'),
    route_candidates: [{ ...canonicalRoute, ownership_candidates: [], owning_node: null }] };
  const routeFiles = {
    '/p/workflow-plan.md': routePlan,
    '/p/.cache/review.md': findingBody,
    '/p/.cache/review-attempts.json': JSON.stringify({ schema_version: 1, plan_hash: routeHash, attempts: [routeAttempt] }),
    '/p/.cache/findings-route.json': 'sentinel-projection\n',
  };
  const projection = runRouteFindings({ nodeId: 'review', planPath: '/p/workflow-plan.md', repoRoot: '/p',
    readFile: p => { if (!(p in routeFiles)) throw new Error('ENOENT'); return routeFiles[p]; },
    writeFile: (p, c) => { routeFiles[p] = c; }, cacheExists: p => p in routeFiles }, 'test-project');
  assert(projection.result === 'refuse' && projection.reason === 'review_journal_route_mismatch'
    && routeFiles['/p/.cache/findings-route.json'] === 'sentinel-projection\n',
  'R8-PROJECTION-RED: frozen-plan ownership mismatch refuses without rewriting compatibility projection');

  const passBody = 'evidence-binding: review passnonce1234\nverdict: pass\nfindings_blocking: 0\n';
  const passGenerations = [{ member: 'review', nonce: 'passnonce1234' }];
  const passAttempt = { ...routeAttempt, attempt_id: 'review:2', ordinal: 2,
    generations: passGenerations,
    transaction_key: crypto.createHash('sha256').update(JSON.stringify({ plan_hash: routeHash,
      logical_gate_key: routeGate.key, candidate_digest: routeDigest, generations: passGenerations })).digest('hex'),
    outcome: 'pass', reason: null,
    receipts: [{ node_id: 'review', generation: 'passnonce1234', body: passBody,
      receipt_sha256: crypto.createHash('sha256').update(passBody).digest('hex'),
      effective_pass: true, verdict: 'pass', findings_blocking: 0 }],
    findings: [], route_candidates: [], lifecycle_settled: true,
    repair: { selected_writer: null, settled: null }, consumed_by: null };
  const latestFiles = { ...routeFiles,
    '/p/.cache/review-attempts.json': JSON.stringify({ schema_version: 1, plan_hash: routeHash,
      attempts: [passAttempt, { ...routeAttempt, route_candidates: [canonicalRoute] }] }),
    '/p/.cache/findings-route.json': 'stale-old-route\n' };
  const latestProjection = runRouteFindings({ nodeId: 'review', planPath: '/p/workflow-plan.md', repoRoot: '/p',
    readFile: p => { if (!(p in latestFiles)) throw new Error('ENOENT'); return latestFiles[p]; },
    writeFile: (p, c) => { latestFiles[p] = c; }, cacheExists: p => p in latestFiles }, 'test-project');
  assert(latestProjection.result === 'ok' && latestProjection.count === 0
    && latestFiles['/p/.cache/findings-route.json'] === '[]\n',
  'R10-LATEST-RED: highest authoritative ordinal projects empty routes despite journal array reorder');

  const finalizeGate = canonicalLogicalGateIdentity({ kind: 'sequence', id: 'forged-display',
    origin: ['review'], members: ['finalize'] });
  const finalizeBody = 'evidence-binding: finalize finalnonce123\nverdict: pass\nfindings_blocking: 0\n';
  const finalizeGenerations = [{ member: 'finalize', nonce: 'finalnonce123' }];
  const forgedGateAttempt = { ...passAttempt, attempt_id: 'not-derived-from-gate', ordinal: 1,
    logical_gate: finalizeGate, generations: finalizeGenerations,
    transaction_key: crypto.createHash('sha256').update(JSON.stringify({ plan_hash: routeHash,
      logical_gate_key: finalizeGate.key, candidate_digest: routeDigest, generations: finalizeGenerations })).digest('hex'),
    receipts: [{ node_id: 'finalize', generation: 'finalnonce123', body: finalizeBody,
      receipt_sha256: crypto.createHash('sha256').update(finalizeBody).digest('hex'),
      effective_pass: true, verdict: 'pass', findings_blocking: 0 }] };
  const forgedGateFiles = { '/p/workflow-plan.md': routePlan,
    '/p/.cache/review-attempts.json': JSON.stringify({ schema_version: 1, plan_hash: routeHash,
      attempts: [forgedGateAttempt] }) };
  const forgedGateState = readReviewJournal({ planPath: '/p/workflow-plan.md',
    readFile: p => { if (!(p in forgedGateFiles)) throw new Error('ENOENT'); return forgedGateFiles[p]; },
    cacheExists: p => p in forgedGateFiles }, routePlan);
  assert(forgedGateState.reason === 'review_journal_gate_identity_mismatch',
    'R11-GATE-RED: non-verdict member and forged display gate fail frozen-plan identity binding');

  const wrongAttemptFiles = { '/p/workflow-plan.md': routePlan,
    '/p/.cache/review-attempts.json': JSON.stringify({ schema_version: 1, plan_hash: routeHash,
      attempts: [{ ...passAttempt, attempt_id: 'arbitrary-id', ordinal: 2 }] }) };
  const wrongAttemptState = readReviewJournal({ planPath: '/p/workflow-plan.md',
    readFile: p => { if (!(p in wrongAttemptFiles)) throw new Error('ENOENT'); return wrongAttemptFiles[p]; },
    cacheExists: p => p in wrongAttemptFiles }, routePlan);
  assert(wrongAttemptState.reason === 'review_journal_attempt_identity_mismatch',
    'R11-ATTEMPT-RED: deterministic prefix and contiguous gate-local ordinal bind attempts to the plan');

  const repairPlanBody = makePlan(['| base | complete | |', '| writer | complete | |',
    '| review | pending | |', '| finalize | pending | |'], [
    '| base | implementer | — | scripts/base.js | 1 | sequence |',
    '| writer | tdd-guide | base | scripts/a.js | 1 | sequence |',
    '| review | code-reviewer | writer | — | 1 | sequence |',
    '| finalize | finalize | review | — | 1 | sequence |',
  ]);
  const repairHash = planValidator.computePlanHash(repairPlanBody);
  const repairPlan = '<!-- plan_hash: ' + repairHash + ' -->\n' + repairPlanBody;
  const repairGate = canonicalLogicalGateIdentity({ kind: 'sequence', id: 'review', origin: ['writer'], members: ['review'] });
  const repairGens = [{ member: 'review', nonce: 'repairnonce12' }];
  const repairBody = 'evidence-binding: review repairnonce12\nverdict: fail\nfindings_blocking: 1\n';
  const producerIdentity = { baseline: 'a'.repeat(40), anchored_ref: 'a'.repeat(40),
    open_token: 'b'.repeat(40), generation: 'a'.repeat(12),
    ref: 'refs/kaola-workflow/barrier/test/writer' };
  const repairAttemptBase = { attempt_id: 'review:1', ordinal: 1, plan_hash: repairHash,
    logical_gate: repairGate, candidate_digest: '8'.repeat(64),
    candidate_declared: {}, candidate_residue_digest: 'd'.repeat(64), rebind: [], generations: repairGens,
    transaction_key: crypto.createHash('sha256').update(JSON.stringify({ plan_hash: repairHash,
      logical_gate_key: repairGate.key, candidate_digest: '8'.repeat(64), generations: repairGens })).digest('hex'),
    settlement_command: 'close-node', outcome: 'fail', reason: 'verdict_not_pass',
    receipts: [{ node_id: 'review', generation: 'repairnonce12', body: repairBody,
      receipt_sha256: crypto.createHash('sha256').update(repairBody).digest('hex'),
      effective_pass: false, verdict: 'fail', findings_blocking: 1 }],
    findings: [], route_candidates: [], lifecycle_settled: true,
    producer_bindings: { base: producerIdentity, writer: producerIdentity },
    repair: { selected_writer: 'writer', settled: true }, consumed_by: 'writer' };
  const readRepairAttempt = attempt => {
    const files = { '/repair/workflow-plan.md': repairPlan,
      '/repair/.cache/review-attempts.json': JSON.stringify({ schema_version: 1, plan_hash: repairHash, attempts: [attempt] }) };
    return readReviewJournal({ planPath: '/repair/workflow-plan.md',
      readFile: p => { if (!(p in files)) throw new Error('ENOENT'); return files[p]; },
      cacheExists: p => p in files }, repairPlan);
  };
  assert(readRepairAttempt({ ...repairAttemptBase, producer_bindings: { foreign: producerIdentity },
    repair: { selected_writer: 'foreign', settled: true }, consumed_by: 'foreign' }).reason === 'review_journal_repair_identity_mismatch',
  'R13-FOREIGN-RED: consumed writer must exist as a frozen write-bearing producer');
  assert(readRepairAttempt({ ...repairAttemptBase, producer_bindings: { base: producerIdentity },
    repair: { selected_writer: 'base', settled: true }, consumed_by: 'base' }).reason === 'review_journal_repair_identity_mismatch',
  'R13-NONMAX-RED: consumed writer must be the unique maximal write-bearing producer');
  assert(readRepairAttempt({ ...repairAttemptBase, producer_bindings: {} }).reason === 'review_journal_repair_identity_mismatch',
  'R13-BINDING-RED: consumed writer requires its immutable producer binding');
  const validConsumedState = readRepairAttempt(repairAttemptBase);
  assert(validConsumedState.ok === true && reviewJournalBlocker(validConsumedState.journal) === null,
  'R13-CONTROL-RED: proven unique-maximal consumed writer legitimately clears its failed-attempt fence');

  assert(typeof captureWriterBarrierIdentity === 'function' && typeof verifyWriterBarrierIdentity === 'function',
    'R4-BINDING-RED: repair captures and verifies original baseline/ref/open-token/generation identity');
  const identityTmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-writer-identity-'));
  try {
    const planPath = path.join(identityTmp, 'issue-682', 'workflow-plan.md');
    const cacheDir = path.join(path.dirname(planPath), '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    const base = 'a'.repeat(40);
    fs.writeFileSync(path.join(cacheDir, 'barrier-base-writer'), base + '\n');
    fs.writeFileSync(path.join(cacheDir, 'barrier-open-writer'), 'b'.repeat(40) + '\n');
    const captured = captureWriterBarrierIdentity({ planPath,
      readFile: p => fs.readFileSync(p, 'utf8'), resolveBarrierRef: () => base }, 'writer');
    assert(captured && verifyWriterBarrierIdentity(captured, { ...captured }),
      'R4-BINDING: the complete original writer identity round-trips');
    for (const key of ['baseline', 'anchored_ref', 'open_token', 'generation', 'ref']) {
      assert(!verifyWriterBarrierIdentity(captured, { ...captured, [key]: captured[key] + '-tampered' }),
        'R4-BINDING: changed ' + key + ' refuses repair identity');
    }
  } finally { fs.rmSync(identityTmp, { recursive: true, force: true }); }
  assert(typeof readReviewJournal === 'function',
    'R5-HISTORY-RED: missing-history detection is exported for direct fail-closed fixtures');
  const historyTmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-review-history-'));
  try {
    const projectDir = path.join(historyTmp, 'issue-history');
    const cacheDir = path.join(projectDir, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    const historyBody = makePlan(['| review | complete | |'], [
      '| review | code-reviewer | — | — | 1 | sequence |',
    ]);
    const historyHash = planValidator.computePlanHash(historyBody);
    const planPath = path.join(projectDir, 'workflow-plan.md');
    const plan = '<!-- plan_hash: ' + historyHash + ' -->\n' + historyBody;
    fs.writeFileSync(planPath, plan);
    fs.writeFileSync(path.join(cacheDir, 'barrier-base-review'), 'cccccccccccc-rest\n');
    fs.writeFileSync(path.join(cacheDir, 'review.md'),
      'evidence-binding: review cccccccccccc\nverdict: pass\nfindings_blocking: 0\n');
    const missing = readReviewJournal({ planPath, readFile: p => fs.readFileSync(p, 'utf8'),
      cacheExists: p => fs.existsSync(p), allowReviewJournalCreate: true,
      creatingNodeId: 'review', creatingGeneration: 'cccccccccccc' }, plan);
    assert(missing.reason === 'review_journal_missing',
      'R5-HISTORY: close-time creation cannot launder a completed review witness');
  } finally { fs.rmSync(historyTmp, { recursive: true, force: true }); }

  // R7: two independent live review gates may both publish their current-generation receipts before
  // either lock holder closes.  The first close creates the journal; the second appends independently.
  const simultaneousTmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-review-simultaneous-'));
  try {
    const project = 'issue-r7';
    const projectDir = path.join(simultaneousTmp, 'kaola-workflow', project);
    const cacheDir = path.join(projectDir, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    fs.writeFileSync(path.join(simultaneousTmp, 'a.js'), '// a\n');
    fs.writeFileSync(path.join(simultaneousTmp, 'b.js'), '// b\n');
    const planPath = path.join(projectDir, 'workflow-plan.md');
    fs.writeFileSync(planPath, makePlan([
      '| writer-a | complete | |', '| writer-b | complete | |',
      '| review-a | pending | |', '| review-b | pending | |', '| finalize | pending | |',
    ], [
      '| writer-a | tdd-guide | — | a.js | 1 | sequence |',
      '| writer-b | tdd-guide | — | b.js | 1 | sequence |',
      '| review-a | code-reviewer | writer-a | — | 1 | sequence |',
      '| review-b | code-reviewer | writer-b | — | 1 | sequence |',
      '| finalize | finalize | review-a, review-b | — | 1 | sequence |',
    ]));
    fs.writeFileSync(path.join(projectDir, 'workflow-state.md'), '# State\n');
    const git = args => execFixtureFileSync('git', ['-C', simultaneousTmp, ...args], { stdio: 'ignore' });
    git(['init']); git(['config', 'user.email', 'kw@test']); git(['config', 'user.name', 'kw']);
    freezeLegacyFixture(execFixtureFileSync, process.execPath,
      path.join(__dirname, 'kaola-workflow-plan-validator.js'), planPath,
      { cwd: simultaneousTmp, stdio: 'pipe' });
    git(['add', '-A']); git(['commit', '-m', 'seed']);
    for (const writer of ['writer-a', 'writer-b']) {
      // --record-base writes a kernel record (the barrier baseline file AND its git ref) in its own
      // process and exits; the adaptive-node process that follows re-reads both from disk. A
      // hand-written baseline could not carry a real ref, so the handoff is the fixture.
      // spawn-class: durable-handoff
      execFixtureFileSync(process.execPath, [path.join(__dirname, 'kaola-workflow-plan-validator.js'),
        planPath, '--record-base', '--node-id', writer, '--json'], { cwd: simultaneousTmp, stdio: 'pipe' });
    }
    const cli = args => {
      try {
        // The per-scenario vehicle for the adaptive-node CLI. Every scenario drives it as a CHAIN:
        // one process writes the ledger row, the barrier baseline and the .cache evidence and EXITS,
        // and the next re-derives the whole run state from those bytes with no shared heap.
        // spawn-class: durable-handoff
        const stdout = execFixtureFileSync(process.execPath,
          [path.join(__dirname, 'kaola-workflow-adaptive-node.js'), ...args],
          { cwd: simultaneousTmp, encoding: 'utf8' });
        return { exitCode: 0, ...JSON.parse(stdout.trim().split('\n').pop()) };
      } catch (err) {
        let parsed = {}; try { parsed = JSON.parse(String(err.stdout || '').trim().split('\n').pop()); } catch (_) {}
        return { exitCode: err.status == null ? 1 : err.status, ...parsed };
      }
    };
    const opened = cli(['open-ready', '--project', project, '--json']);
    const byId = new Map((opened.opened || []).map(n => [n.id, n]));
    assert(byId.has('review-a') && byId.has('review-b'),
      'R7-SIMULTANEOUS-RED: real scheduler opens both independent review gates');
    for (const review of ['review-a', 'review-b']) {
      const nonce = byId.get(review).nonce;
      // record-evidence writes each gate's receipt in its own process and EXITS; the close-node
      // processes below re-read those receipts from disk, and their verdict is the assertion.
      // spawn-class: durable-handoff
      const recorded = require('child_process').spawnSync(process.execPath,
        [path.join(__dirname, 'kaola-workflow-adaptive-node.js'), 'record-evidence', '--project', project,
          '--node-id', review, '--stdin', '--json'],
        { cwd: simultaneousTmp, encoding: 'utf8', input: 'evidence-binding: ' + review + ' ' + nonce
          + '\nverdict: fail\nfindings_blocking: 1\n' });
      assert(recorded.status === 0, 'R7-SIMULTANEOUS-RED: records current receipt for ' + review);
    }
    const closeA = cli(['close-node', '--project', project, '--node-id', 'review-a', '--json']);
    const closeB = cli(['close-node', '--project', project, '--node-id', 'review-b', '--json']);
    const journal = fs.existsSync(path.join(cacheDir, 'review-attempts.json'))
      ? JSON.parse(fs.readFileSync(path.join(cacheDir, 'review-attempts.json'), 'utf8')) : { attempts: [] };
    const statuses = readLedgerStatuses(fs.readFileSync(planPath, 'utf8'));
    assert(closeA.result === 'review_failed' && closeB.result === 'review_failed'
      && journal.attempts.length === 2 && journal.attempts.every(a => a.lifecycle_settled === true),
      'R7-SIMULTANEOUS-RED: both first closes settle one independent authoritative attempt');
    assert(statuses['review-a'] === 'pending' && statuses['review-b'] === 'pending'
      && statuses.finalize === 'pending' && !fs.existsSync(path.join(cacheDir, 'running-set.json')),
      'R7-SIMULTANEOUS-RED: both gates return pending, running set drains, and successor stays hidden');
  } finally { fs.rmSync(simultaneousTmp, { recursive: true, force: true }); }
});

// ===========================================================================
// #827 — THE POST-DISCHARGE OWNER PROJECTION. A review gate settling AFTER its upstream expansion
// point discharged records route_candidates carrying the interior LEAF owners; discharge is the
// commitment point that changes the node view, so discharge owns the translation: expand-close
// writes a durable, digest-bound leaf -> owning-milestone projection into the barrier-invisible
// .cache/epoch-projections/ band, and BOTH journal route matchers canonicalize the recorded AND the
// recomputed rows through it before comparing. An owner in NEITHER the execution node table NOR the
// projection still refuses review_journal_route_mismatch (the tamper gate keeps its teeth), and the
// refusal now carries a TYPED detail: `tamper` vs `projection_missing` (the legacy pre-projection
// shape — the operator hint names the expand-close migration, never journal surgery).
// ===========================================================================

// #827-U — the projection primitives, direct-call: the digest-bound entry shape, the fail-closed
// fold, the route-row canonicalization, the idempotent append-only writer, the typed mismatch
// classifier, and the operator-hint registry entry.
scenario(() => {
  assert(typeof ensureOwnerProjection === 'function' && typeof loadOwnerProjection === 'function'
    && typeof routeMismatchDetail === 'function',
    '#827-U: the projection writer/read-fold/classifier are exported for direct pins');
  assert(typeof buildOwnerProjectionEntry === 'function' && typeof verifyOwnerProjectionEntry === 'function'
    && typeof foldOwnerProjection === 'function' && typeof canonicalizeRouteOwners === 'function'
    && EPOCH_PROJECTIONS_DIR === 'epoch-projections' && OWNER_PROJECTION_NAME === 'owner-projection.json',
    '#827-U: the schema-side entry/verify/fold/canonicalize primitives + band names are exported (drift anchor)');
  if (typeof ensureOwnerProjection !== 'function' || typeof buildOwnerProjectionEntry !== 'function') return;

  const H = 'a'.repeat(64);
  // buildOwnerProjectionEntry: leaves stored SORTED (byte-stable canonical form); the digest binds
  // { point, plan_hash, discharged_at, records, leaves } byte-for-byte; the plan hash lowercases.
  const entry = buildOwnerProjectionEntry({ point: 'm1', plan_hash: H.toUpperCase(),
    discharged_at: 'T1', records: ['m1#1'], leaves: ['m1-r1-u2', 'm1-r1-u1'] });
  assert(JSON.stringify(entry.leaves) === JSON.stringify(['m1-r1-u1', 'm1-r1-u2']),
    '#827-U: the entry stores leaves SORTED (canonical byte-stable form), got ' + JSON.stringify(entry.leaves));
  assert(entry.plan_hash === H && /^[0-9a-f]{64}$/.test(entry.projection_digest),
    '#827-U: the plan hash is lowercased and the projection digest is a 64-hex content address');
  assert(verifyOwnerProjectionEntry(entry) === true, '#827-U: a well-formed entry verifies');
  assert(verifyOwnerProjectionEntry({ ...entry, leaves: ['m1-r1-u2', 'm1-r1-u1'] }) === false,
    '#827-U: unsorted leaves fail verification (the canonical form is enforced)');
  assert(verifyOwnerProjectionEntry({ ...entry, records: ['m1#9'] }) === false,
    '#827-U: a tampered records list breaks the digest binding');
  assert(verifyOwnerProjectionEntry({ ...entry, projection_digest: 'b'.repeat(64) }) === false,
    '#827-U: a forged digest fails verification');

  // foldOwnerProjection: wrong plan hash / wrong schema version / unverifiable entries all fold to
  // the EMPTY projection (fail-closed: can only ever KEEP a refusal in place, never lift one); a
  // later entry for the same point SUPERSEDES (append-only per epoch).
  const foldInput = entries => ({ schema_version: OWNER_PROJECTION_SCHEMA_VERSION, plan_hash: H, entries });
  const e2 = buildOwnerProjectionEntry({ point: 'm1', plan_hash: H, discharged_at: 'T2',
    records: ['m1#1', 'm1#2'], leaves: ['m1-r1-u1', 'm1-r1-u2', 'm1-r2-fx'] });
  const folded = foldOwnerProjection(foldInput([entry, e2]), H);
  assert(folded.present === true && JSON.stringify(folded.points) === JSON.stringify(['m1'])
    && folded.leaf_to_milestone['m1-r1-u1'] === 'm1' && folded.leaf_to_milestone['m1-r2-fx'] === 'm1',
    '#827-U: the fold unions every verifiable current-epoch entry (the re-discharge supersedes), got '
    + JSON.stringify(folded));
  assert(foldOwnerProjection(foldInput([entry]), 'c'.repeat(64)).present === false,
    '#827-U: a wrong-epoch plan hash folds to the empty projection');
  assert(foldOwnerProjection({ schema_version: 999, plan_hash: H, entries: [entry] }, H).present === false,
    '#827-U: a foreign schema version folds to the empty projection');
  assert(foldOwnerProjection(foldInput([{ ...entry, point: 'ghost' }]), H).present === false,
    '#827-U: an entry whose digest no longer binds contributes NOTHING (fail-closed)');

  // canonicalizeRouteOwners: leaf ids map to their milestone (dedup + re-sort + owning_node
  // re-derived); spine ids and unknown ids map to themselves; non-owner fields carry over; PURE.
  const leafMap = { 'm1-r1-u1': 'm1', 'm1-r2-fx': 'm1' };
  const row = { finding_id: 'F-1', file: 'lib/composed.js', ownership_candidates: ['m1-r1-u1', 'm1-r2-fx'],
    owning_node: null, fix_role: 'implementer' };
  const canon = canonicalizeRouteOwners(row, leafMap);
  assert(JSON.stringify(canon.ownership_candidates) === JSON.stringify(['m1']) && canon.owning_node === 'm1',
    '#827-U: the whole leaf set collapses onto ONE milestone — uniquely milestone-owned, got ' + JSON.stringify(canon));
  assert(canon.file === 'lib/composed.js' && canon.fix_role === 'implementer'
    && row.ownership_candidates.length === 2 && row.owning_node === null,
    '#827-U: non-owner fields carry over and the input row is NOT mutated (pure)');
  const mixed = canonicalizeRouteOwners({ ownership_candidates: ['wall', 'm1-r1-u1', 'ghost'], owning_node: null }, leafMap);
  assert(JSON.stringify(mixed.ownership_candidates) === JSON.stringify(['ghost', 'm1', 'wall'])
    && mixed.owning_node === null,
    '#827-U: spine + unknown ids map to themselves (identity) and a multi-owner row stays unowned, got '
    + JSON.stringify(mixed));

  // ensureOwnerProjection (the discharge-side writer): appended -> present (idempotent re-ensure) ->
  // superseding APPEND on a re-discharge; loadOwnerProjection reads it back for the SAME hash only.
  const files = {};
  const pOpts = { planPath: '/p827u/workflow-plan.md',
    readFile: p => { if (!(p in files)) throw new Error('ENOENT'); return files[p]; },
    writeFile: (p, c) => { files[p] = c; }, mkdirp: () => {} };
  const PROJ_U = '/p827u/.cache/epoch-projections/owner-projection.json';
  const REC1 = [{ id: 'm1#1', units: [{ id: 'm1-r1-u1' }, { id: 'm1-r1-u2' }] }];
  const REC2 = [{ id: 'm1#1', units: [{ id: 'm1-r1-u1' }, { id: 'm1-r1-u2' }] },
    { id: 'm1#2', units: [{ id: 'm1-r2-fx' }] }];
  assert(ensureOwnerProjection(pOpts, H, 'm1', REC1, 'T1') === 'appended'
    && typeof files[PROJ_U] === 'string',
    '#827-U: the first discharge APPENDS the projection entry into the barrier-invisible band');
  const firstWrite = files[PROJ_U];
  assert(ensureOwnerProjection(pOpts, H, 'm1', REC1, 'T1') === 'present' && files[PROJ_U] === firstWrite,
    '#827-U: the identical re-ensure is idempotent (present, byte-untouched) — the crash-repair arm');
  assert(ensureOwnerProjection(pOpts, H, 'm1', REC2, 'T2') === 'appended',
    '#827-U: a re-discharge after re-expansion APPENDS a superseding entry (append-only, never a rewrite)');
  const parsedFile = JSON.parse(files[PROJ_U]);
  assert(parsedFile.schema_version === OWNER_PROJECTION_SCHEMA_VERSION && parsedFile.plan_hash === H
    && parsedFile.entries.length === 2,
    '#827-U: the durable file carries BOTH entries bound to the epoch plan hash, got '
    + JSON.stringify({ v: parsedFile.schema_version, entries: parsedFile.entries.length }));
  const loaded = loadOwnerProjection(pOpts, H);
  assert(loaded.present === true && loaded.points instanceof Set && loaded.points.has('m1')
    && loaded.leafToMilestone['m1-r1-u1'] === 'm1' && loaded.leafToMilestone['m1-r1-u2'] === 'm1'
    && loaded.leafToMilestone['m1-r2-fx'] === 'm1',
    '#827-U: loadOwnerProjection folds the durable band for the current epoch, got ' + JSON.stringify(loaded));
  assert(loadOwnerProjection(pOpts, 'd'.repeat(64)).present === false,
    '#827-U: a stale (wrong-hash) projection reads as EMPTY — identity canonicalization');
  assert(loadOwnerProjection({ planPath: '/nowhere/workflow-plan.md', readFile: pOpts.readFile }, H).present === false,
    '#827-U: an absent projection file reads as EMPTY (total, never throws)');
  assert(ensureOwnerProjection(pOpts, null, 'm1', REC1, 'T3') === 'skipped'
    && ensureOwnerProjection(pOpts, H, 'm1', [], 'T3') === 'skipped',
    '#827-U: no plan hash / no records => skipped (nothing to project)');

  // routeMismatchDetail: the TYPED distinction on the surviving refusal. projection_missing = the
  // rows reference a REAL unit of a DISCHARGED point no projection covers (the legacy pre-projection
  // shape) — the detail names the idempotent expand-close migration. tamper = everything else,
  // unchanged fail-closed.
  const DISCHARGED_PLAN = ['# Plan', '', '## Expansion Records', '',
    'record(m1#1):', '  point: m1', '  grain: g', '  path: p', '  join: j', '  probe: pr', '  serializer: none',
    '  unit: u1 | implementer | — | lib/composed.js | co_open | —', '',
    'open(m1#1):', '  at: T1', '',
    'discharge(m1):', '  at: T2', '  records: m1#1', ''].join('\n');
  const execIds = new Set(['probe', 'm1', 'wall', 'done', 'm1-r1-u1']);
  const legacy = routeMismatchDetail(
    [{ ownership_candidates: ['m1-r1-u1'], owning_node: 'm1-r1-u1' }],
    [{ ownership_candidates: ['m1-r1-u1'], owning_node: 'm1-r1-u1' }],
    { present: false, leafToMilestone: {}, points: new Set() }, DISCHARGED_PLAN, execIds);
  assert(legacy.route_mismatch_class === 'projection_missing' && legacy.point === 'm1'
    && /expand-close --node-id m1/.test(String(legacy.detail)) && /NEVER hand-edit the journal/.test(String(legacy.detail)),
    '#827-U: a discharged-but-uncovered leaf classifies projection_missing, naming the idempotent '
    + 'expand-close migration (never journal surgery), got ' + JSON.stringify(legacy));
  const tampered = routeMismatchDetail(
    [{ ownership_candidates: ['m1-r1-u9'], owning_node: 'm1-r1-u9' }], [],
    { present: true, leafToMilestone: { 'm1-r1-u1': 'm1' }, points: new Set(['m1']) }, DISCHARGED_PLAN, execIds);
  assert(tampered.route_mismatch_class === 'tamper' && !tampered.point && !tampered.detail,
    '#827-U: a leaf-shaped owner in NEITHER the node table NOR the projection classifies tamper '
    + '(the gate keeps its teeth), got ' + JSON.stringify(tampered));
  const covered = routeMismatchDetail(
    [{ ownership_candidates: ['m1-r1-u1'], owning_node: 'm1-r1-u1' }], [],
    { present: true, leafToMilestone: { 'm1-r1-u1': 'm1' }, points: new Set(['m1']) }, DISCHARGED_PLAN, execIds);
  assert(covered.route_mismatch_class === 'tamper',
    '#827-U: a COVERED leaf with a residual divergence is tamper, not projection_missing (disjoint classes)');
  const nonLeaf = routeMismatchDetail(
    [{ ownership_candidates: ['ghost'], owning_node: 'ghost' }], [],
    { present: false, leafToMilestone: {}, points: new Set() }, DISCHARGED_PLAN, execIds);
  assert(nonLeaf.route_mismatch_class === 'tamper',
    '#827-U: a non-leaf-shaped unknown owner stays tamper even with no projection present');

  // The OPERATOR_HINT_REGISTRY entry: the legacy class names the machine migration; the tamper class
  // stays a bare fail-closed integrity signal. NEITHER suggests hand-editing the journal.
  const legacyHint = getOperatorHint('review_journal_route_mismatch',
    { route_mismatch_class: 'projection_missing', point: 'm1' });
  assert(/expand-close --project <P> --node-id m1/.test(legacyHint) && /NEVER hand-edit the journal/.test(legacyHint),
    '#827-U: the projection_missing hint names the idempotent expand-close migration, got ' + JSON.stringify(legacyHint));
  const tamperHint = getOperatorHint('review_journal_route_mismatch', { route_mismatch_class: 'tamper' });
  assert(!/expand-close/.test(tamperHint) && /NEVER hand-edited/.test(tamperHint),
    '#827-U: the tamper hint names NO migration — a bare fail-closed integrity signal, got ' + JSON.stringify(tamperHint));
  const bareHint = getOperatorHint('review_journal_route_mismatch', {});
  assert(!/expand-close/.test(bareHint),
    '#827-U: an unclassified (legacy-caller) mismatch takes the tamper wording — fail closed by default');
});

// ---------------------------------------------------------------------------
// #827-GREEN — the legitimate post-discharge routing case, beside R8-PROJECTION-RED's tamper pin.
// The journal recorded interior-LEAF owners while m1's FIRST frontier was live; m1 then re-expanded
// (a fixer unit covering the SAME file) and DISCHARGED. Both sides canonicalize through the
// discharge owner projection (leaf -> m1): validation PASSES, and route-findings resolves the
// finding to its OWNING MILESTONE with route: reexpand-open — the cheap legal path, no journal
// surgery, no consent. The SAME fixture with the projection removed is the legacy pre-projection
// shape: the refusal returns, typed projection_missing, and threads through route-findings. A forged
// leaf (in neither the execution node table nor the projection) stays tamper-class.
// ---------------------------------------------------------------------------
scenario(() => {
  const crypto = require('crypto');
  assert(typeof ensureOwnerProjection === 'function' && typeof loadOwnerProjection === 'function',
    '#827-GREEN: the projection writer/read-fold are exported (the discharge-transaction surface)');
  const NODE_ROWS_827 = [
    '| probe | code-explorer | — | — | 1 | sequence |',
    '| m1 | expansion-point | probe | — | 1 | sequence |',
    '| wall | code-reviewer | m1 | — | 1 | sequence |',
    '| done | finalize | wall | CHANGELOG.md | 1 | sequence |',
  ];
  const LEDGER_827 = ['| probe | complete | |', '| m1 | complete | |', '| m1-r1-u1 | complete | |',
    '| m1-r2-fx | complete | |', '| wall | complete | |', '| done | pending | |'];
  const RECORDS_827 = ['## Expansion Records', '',
    'record(m1#1):', '  point: m1', '  grain: g', '  path: p', '  join: j', '  probe: pr', '  serializer: none',
    '  unit: u1 | implementer | — | lib/composed.js | co_open | —', '',
    'open(m1#1):', '  at: T1', '',
    'record(m1#2):', '  point: m1', '  grain: g', '  path: p', '  join: j', '  probe: pr', '  serializer: none',
    '  unit: fx | implementer | — | lib/composed.js | co_open | —', '',
    'open(m1#2):', '  at: T2', '',
    'discharge(m1):', '  at: T3', '  records: m1#1, m1#2', ''].join('\n');
  const planBody827 = makePlan(LEDGER_827, NODE_ROWS_827) + RECORDS_827;
  const hash827 = planValidator.computePlanHash(planBody827);
  const plan827 = '<!-- plan_hash: ' + hash827 + ' -->\n' + planBody827;

  // The fixture genuinely needs the projection: the discharge removed nothing from the RECORDS, so
  // the execution view still carries BOTH leaves — and the CURRENT recomputation names two owners
  // where the record named one. Only canonicalization reconciles them.
  const execNodes827 = planValidator.planNodesWithExpansions(plan827);
  assert(execNodes827.some(n => n.id === 'm1-r1-u1') && execNodes827.some(n => n.id === 'm1-r2-fx'),
    '#827-GREEN fixture: the execution view still carries BOTH discharged leaves');
  assert(JSON.stringify(resolveOwningNodes('lib/composed.js', execNodes827))
      === JSON.stringify(['m1-r1-u1', 'm1-r2-fx']),
    '#827-GREEN fixture: the CURRENT recomputation names TWO leaves (the re-expansion grew the '
    + 'interior) — only projection canonicalization reconciles it with the single-leaf record, got '
    + JSON.stringify(resolveOwningNodes('lib/composed.js', execNodes827)));

  const gate827 = canonicalLogicalGateIdentity({ kind: 'sequence', id: 'wall', origin: ['m1'], members: ['wall'] });
  const gens827 = [{ member: 'wall', nonce: 'wallnonce827a' }];
  const digest827 = '9'.repeat(64);
  const findingRaw827 = 'id=F-1 scope=in_scope action=fix status=open severity=high file=lib/composed.js fix_role=implementer';
  const findingBody827 = 'evidence-binding: wall wallnonce827a\nverdict: fail\nfindings_blocking: 1\nfinding: ' + findingRaw827 + '\n';
  const canonicalFinding827 = { source_node: 'wall', raw: findingRaw827, id: 'F-1', scope: 'in_scope',
    action: 'fix', status: 'open', severity: 'high', file: 'lib/composed.js', fix_role: 'implementer' };
  // RECORDED while only m1#1 was live: the single leaf owner of lib/composed.js.
  const recordedRoute827 = { source_node: 'wall', finding_id: 'F-1', id: 'F-1', scope: 'in_scope',
    action: 'fix', status: 'open', severity: 'high', file: 'lib/composed.js',
    ownership_candidates: ['m1-r1-u1'], owning_node: 'm1-r1-u1', fix_role: 'implementer', raw: findingRaw827 };
  const attempt827 = { attempt_id: 'wall:1', ordinal: 1, plan_hash: hash827, logical_gate: gate827,
    candidate_digest: digest827, candidate_declared: {}, candidate_residue_digest: 'd'.repeat(64),
    generations: gens827,
    transaction_key: crypto.createHash('sha256').update(JSON.stringify({ plan_hash: hash827,
      logical_gate_key: gate827.key, candidate_digest: digest827, generations: gens827 })).digest('hex'),
    settlement_command: 'close-node', outcome: 'fail', reason: 'verdict_not_pass',
    receipts: [{ node_id: 'wall', generation: 'wallnonce827a', body: findingBody827,
      receipt_sha256: crypto.createHash('sha256').update(findingBody827).digest('hex'),
      effective_pass: false, verdict: 'fail', findings_blocking: 1 }],
    findings: [canonicalFinding827], route_candidates: [recordedRoute827], lifecycle_settled: true,
    repair: { selected_writer: null, settled: null }, rebind: [], consumed_by: null };

  const PROJ_827 = '/p827/.cache/epoch-projections/owner-projection.json';
  const files827 = {
    '/p827/workflow-plan.md': plan827,
    '/p827/.cache/wall.md': findingBody827,
    '/p827/.cache/review-attempts.json': JSON.stringify({ schema_version: 1, plan_hash: hash827, attempts: [attempt827] }),
  };
  const io827 = { planPath: '/p827/workflow-plan.md', repoRoot: '/p827',
    readFile: p => { if (!(p in files827)) throw new Error('ENOENT'); return files827[p]; },
    writeFile: (p, c) => { files827[p] = c; }, cacheExists: p => p in files827, mkdirp: () => {} };
  // The durable projection, in the discharge transaction's own entry format (built here with the
  // PRE-EXISTING schema primitives so every behavioral assertion below stays a clean RED — never a
  // throw — on a checkout where the fix is absent).
  {
    const core = { point: 'm1', plan_hash: hash827, discharged_at: 'T3',
      records: ['m1#1', 'm1#2'], leaves: ['m1-r1-u1', 'm1-r2-fx'] };
    const digest827p = crypto.createHash('sha256')
      .update(require('./kaola-workflow-adaptive-schema').canonicalJson(core)).digest('hex');
    files827[PROJ_827] = JSON.stringify({ schema_version: 1, plan_hash: hash827,
      entries: [{ ...core, projection_digest: digest827p }] }, null, 2) + '\n';
  }
  // ...and the discharge transaction's writer produces the IDENTICAL bytes through the same seam
  // (the ONLY writer — no orchestrator-facing verb).
  if (typeof ensureOwnerProjection === 'function') {
    const before827 = files827[PROJ_827];
    const ensured = ensureOwnerProjection(io827, hash827, 'm1',
      [{ id: 'm1#1', units: [{ id: 'm1-r1-u1' }] }, { id: 'm1#2', units: [{ id: 'm1-r2-fx' }] }], 'T3');
    assert(ensured === 'present' && files827[PROJ_827] === before827,
      '#827-GREEN: the discharge writer covers EXACTLY this discharge, idempotently (present), got ' + ensured);
  }

  // GREEN — the leaf-recorded journal VALIDATES post-discharge (canonicalized through the projection
  // on BOTH sides of the comparison).
  const state827 = readReviewJournal(io827, plan827);
  assert(state827.ok === true,
    '#827-GREEN: the leaf-recorded journal VALIDATES post-discharge — the post-discharge routing case '
    + 'passes without mutation, got ' + JSON.stringify({ ok: state827.ok, reason: state827.reason }));

  // TAMPER — a forged leaf (in neither the execution node table nor the projection) still refuses,
  // typed tamper. Complements R8-PROJECTION-RED, which pins the refusal without the class.
  const tamperAttempt827 = { ...attempt827, route_candidates: [{ ...recordedRoute827,
    ownership_candidates: ['m1-r1-u9'], owning_node: 'm1-r1-u9' }] };
  const filesTamper827 = { ...files827, '/p827/.cache/review-attempts.json':
    JSON.stringify({ schema_version: 1, plan_hash: hash827, attempts: [tamperAttempt827] }) };
  const tamperState827 = readReviewJournal({ ...io827,
    readFile: p => { if (!(p in filesTamper827)) throw new Error('ENOENT'); return filesTamper827[p]; },
    cacheExists: p => p in filesTamper827 }, plan827);
  assert(tamperState827.ok === false && tamperState827.reason === 'review_journal_route_mismatch'
    && tamperState827.route_mismatch_class === 'tamper' && !tamperState827.point,
    '#827-TAMPER: an owner in NEITHER the table NOR the projection still refuses — tamper-class, the '
    + 'gate keeps its teeth, got ' + JSON.stringify(tamperState827));

  // GREEN routing — route-findings resolves the interior-owned finding to its OWNING MILESTONE.
  const routed827 = runRouteFindings({ nodeId: 'wall', ...io827 }, 'test-project');
  assert(routed827.result === 'ok' && routed827.count === 1,
    '#827-GREEN: route-findings PASSES post-discharge (no journal surgery, no consent), got '
    + JSON.stringify({ result: routed827.result, reason: routed827.reason }));
  const row827 = (routed827.findings || [])[0] || {};
  assert(JSON.stringify(row827.ownership_candidates) === JSON.stringify(['m1'])
    && row827.owning_node === 'm1' && row827.route === 'reexpand-open',
    '#827-GREEN: the interior-owned finding resolves to its OWNING MILESTONE with route: reexpand-open, '
    + 'got ' + JSON.stringify(row827));
  const persisted827 = JSON.parse(files827['/p827/.cache/findings-route.json'] || 'null') || [];
  assert(persisted827.length === 1 && persisted827[0].owning_node === 'm1'
    && persisted827[0].route === 'reexpand-open',
    '#827-GREEN: the durable findings-route.json carries the same milestone resolution');

  // LEGACY — the SAME journal with NO projection (a discharge/journal pair recorded before the
  // projection existed): the refusal returns, typed projection_missing, and threads through
  // route-findings with ZERO routing write.
  const filesLegacy827 = { ...files827 };
  delete filesLegacy827[PROJ_827];
  delete filesLegacy827['/p827/.cache/findings-route.json'];
  const ioLegacy827 = { ...io827,
    readFile: p => { if (!(p in filesLegacy827)) throw new Error('ENOENT'); return filesLegacy827[p]; },
    writeFile: (p, c) => { filesLegacy827[p] = c; }, cacheExists: p => p in filesLegacy827 };
  const legacyState827 = readReviewJournal(ioLegacy827, plan827);
  assert(legacyState827.ok === false && legacyState827.reason === 'review_journal_route_mismatch'
    && legacyState827.route_mismatch_class === 'projection_missing' && legacyState827.point === 'm1'
    && /expand-close --node-id m1/.test(String(legacyState827.detail)),
    '#827-LEGACY: with no projection the SAME journal is the pre-fix legacy shape — the refusal '
    + 'returns, typed projection_missing with the migration in the detail, got ' + JSON.stringify(legacyState827));
  const routedLegacy827 = runRouteFindings({ nodeId: 'wall', ...ioLegacy827 }, 'test-project');
  assert(routedLegacy827.result === 'refuse' && routedLegacy827.reason === 'review_journal_route_mismatch'
    && routedLegacy827.route_mismatch_class === 'projection_missing' && routedLegacy827.point === 'm1',
    '#827-LEGACY: the typed detail threads readReviewJournal -> route-findings (the fence refuses '
    + 'BEFORE any routing write), got ' + JSON.stringify(routedLegacy827));
  assert(typeof filesLegacy827['/p827/.cache/findings-route.json'] === 'undefined',
    '#827-LEGACY: the refused route-findings wrote NOTHING');
});

// ---------------------------------------------------------------------------
// #827-V2 — the schema-2 matcher twin, direct-call (the incident's own lane: a schema-2 journal
// validated by reviewJournalV2MatchesPlan). The route recomputation ranges over the EXECUTION view
// and BOTH sides canonicalize through the projection; the producer re-derivation stays the FREEZE
// view (the #783 pin is untouched by this issue). RED-provable: pre-fix the recomputation ranged
// over the SPINE ONLY, so a legitimately leaf-recorded attempt mismatched by construction.
// ---------------------------------------------------------------------------
scenario(() => {
  assert(typeof loadOwnerProjection === 'function' && typeof routeMismatchDetail === 'function',
    '#827-V2: the projection read-fold + typed classifier are exported (the fix\'s surface)');
  const NODE_ROWS_827V = [
    '| probe | code-explorer | — | — | 1 | sequence |',
    '| m1 | expansion-point | probe | — | 1 | sequence |',
    '| wall | code-reviewer | m1 | — | 1 | sequence |',
    '| done | finalize | wall | CHANGELOG.md | 1 | sequence |',
  ];
  const LEDGER_827V = ['| probe | complete | |', '| m1 | complete | |', '| m1-r1-u1 | complete | |',
    '| m1-r2-fx | complete | |', '| wall | complete | |', '| done | pending | |'];
  const REC1_827V = ['## Expansion Records', '',
    'record(m1#1):', '  point: m1', '  grain: g', '  path: p', '  join: j', '  probe: pr', '  serializer: none',
    '  unit: u1 | implementer | — | lib/composed.js | co_open | —', '',
    'open(m1#1):', '  at: T1', ''].join('\n');
  const BOTH_827V = REC1_827V + '\n' + ['record(m1#2):', '  point: m1', '  grain: g', '  path: p',
    '  join: j', '  probe: pr', '  serializer: none',
    '  unit: fx | implementer | — | lib/composed.js | co_open | —', '',
    'open(m1#2):', '  at: T2', '',
    'discharge(m1):', '  at: T3', '  records: m1#1, m1#2', ''].join('\n');
  const preReexpPlan827V = makePlan(LEDGER_827V, NODE_ROWS_827V) + REC1_827V;
  const dischargedPlan827V = makePlan(LEDGER_827V, NODE_ROWS_827V) + BOTH_827V;

  const spineNodes827V = planValidator.parseNodes(dischargedPlan827V);
  const gate827V = reviewLogicalGate(spineNodes827V, spineNodes827V.find(n => n.id === 'wall'));
  const gateCore827V = { key: gate827V.key, kind: gate827V.kind, members: gate827V.members,
    claim_digest: gate827V.claim_digest, surface_digests: gate827V.surface_digests,
    aggregation: gate827V.aggregation, certified_producers: gate827V.certified_producers };
  const finding827V = { uid: 'F-1', scope: 'in_scope', action: 'fix', status: 'open', severity: 'high',
    primary_anchor: { path: 'lib/composed.js' } };
  // RECORDED pre-re-expansion (only m1#1 live): the single leaf owner.
  const recorded827V = schema2RouteCandidates([finding827V],
    planValidator.planNodesWithExpansions(preReexpPlan827V), 'wall');
  assert(recorded827V.length === 1
    && JSON.stringify(recorded827V[0].ownership_candidates) === JSON.stringify(['m1-r1-u1'])
    && recorded827V[0].owning_node === 'm1-r1-u1',
    '#827-V2 fixture: the attempt recorded the interior LEAF owner, got ' + JSON.stringify(recorded827V));
  // ...while the CURRENT execution view names TWO owners for the same file (post-record growth).
  const recomputed827V = schema2RouteCandidates([finding827V],
    planValidator.planNodesWithExpansions(dischargedPlan827V), 'wall');
  assert(JSON.stringify(recomputed827V[0].ownership_candidates) === JSON.stringify(['m1-r1-u1', 'm1-r2-fx']),
    '#827-V2 fixture: the current recomputation names BOTH leaves — only canonicalization reconciles, got '
    + JSON.stringify(recomputed827V));

  const attempt827V = { attempt_id: 'wall:1', ordinal: 1, logical_gate: gateCore827V, gate_mode: 'change_gate',
    outcome: 'fail', lifecycle_settled: true, consumed_by: null,
    repair: { selected_writer: null, settled: null }, producer_bindings: {},
    receipts: [{ node_id: 'wall', findings: [finding827V] }],
    route_candidates: recorded827V };
  const journal827V = { schema_version: 2, attempts: [attempt827V] };
  const projection827V = { present: true,
    leafToMilestone: { 'm1-r1-u1': 'm1', 'm1-r2-fx': 'm1' }, points: new Set(['m1']) };

  const withProj827V = reviewJournalV2MatchesPlan(journal827V, dischargedPlan827V, projection827V);
  assert(withProj827V.ok === true,
    '#827-V2-GREEN: the schema-2 matcher validates the leaf-recorded attempt through the projection, '
    + 'got ' + JSON.stringify(withProj827V));
  const noProj827V = reviewJournalV2MatchesPlan(journal827V, dischargedPlan827V);
  assert(noProj827V.ok === false && noProj827V.reason === 'review_journal_route_mismatch'
    && noProj827V.route_mismatch_class === 'projection_missing' && noProj827V.point === 'm1',
    '#827-V2-LEGACY: without the projection the schema-2 twin refuses, typed projection_missing, got '
    + JSON.stringify(noProj827V));
  const tampered827V = { schema_version: 2, attempts: [{ ...attempt827V,
    route_candidates: recorded827V.map(r => ({ ...r,
      ownership_candidates: ['ghost-writer'], owning_node: 'ghost-writer' })) }] };
  const tamperResult827V = reviewJournalV2MatchesPlan(tampered827V, dischargedPlan827V, projection827V);
  assert(tamperResult827V.ok === false && tamperResult827V.reason === 'review_journal_route_mismatch'
    && tamperResult827V.route_mismatch_class === 'tamper' && !tamperResult827V.point,
    '#827-V2-TAMPER: an owner in neither the table nor the projection refuses tamper-class in the '
    + 'schema-2 twin too, got ' + JSON.stringify(tamperResult827V));
  // The #783 invariance pin still holds: the producer re-derivation ranges over the FREEZE view, so
  // this plan's (empty) spine producer set is what the attempt's bindings are matched against — a
  // re-expansion can never grow a settled attempt into an identity mismatch.
  assert(spineNodes827V.map(n => n.id).join(',') === 'probe,m1,wall,done',
    '#827-V2: the producer re-derivation stays the FREEZE view (spine only) — the #783 pin is untouched');
});

// ---------------------------------------------------------------------------
// #827-CLOSE — the discharge transaction itself writes the projection: expand-close returns
// owner_projection:'appended' and the durable band covers every unit leaf of every record on the
// point; the alreadyDischarged re-run is the crash-repair re-ensure ('present', byte-untouched; a
// deleted file is re-appended byte-identically from the point's own discharge block).
// ---------------------------------------------------------------------------
scenario(() => {
  const { runExpandClose } = require('./kaola-workflow-adaptive-node');
  assert(typeof runExpandClose === 'function' && typeof loadOwnerProjection === 'function',
    '#827-CLOSE: runExpandClose + the projection read-fold are exported');
  if (typeof runExpandClose !== 'function') return;
  // Folds to the EMPTY projection where the read side is absent, so the pins below fail as clean RED
  // assertions (never a throw) on a pre-fix checkout.
  const load827 = typeof loadOwnerProjection === 'function' ? loadOwnerProjection
    : () => ({ present: false, points: new Set(), leafToMilestone: {} });
  const PLAN827C = rows => ['# Plan — 827c', '',
    '## Meta', '', 'plan_form: spine', '',
    'expansion(m1):', '  milestone_goal: g', '  expected_surfaces: lib/',
    '  join_constraints: none', '  review_class: code-reviewer', '',
    '## Nodes', '',
    '| id | role | depends_on | declared_write_set | cardinality | shape |',
    '|---|---|---|---|---|---|',
    '| probe | code-explorer | — | — | 1 | sequence |',
    '| m1 | expansion-point | probe | — | 1 | sequence |',
    '| wall | code-reviewer | m1 | — | 1 | sequence |',
    '| done | finalize | wall | — | 1 | sequence |', '',
    '## Node Ledger', '', '| id | status |', '|---|---|', ...rows, '',
    '## Expansion Records', '',
    'record(m1#1):', '  point: m1', '  grain: g', '  path: p', '  join: j', '  probe: pr', '  serializer: none',
    '  unit: u1 | implementer | standard | lib/a.js | co_open | —',
    '  unit: u2 | implementer | standard | lib/b.js | co_open | —', '',
    'open(m1#1):', '  at: T0', ''].join('\n');
  const mk827c = () => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-827c-'));
    const projectDir = path.join(tmp, 'kaola-workflow', 'issue-827c');
    fs.mkdirSync(path.join(projectDir, '.cache'), { recursive: true });
    const planPath = path.join(projectDir, 'workflow-plan.md');
    const body = PLAN827C(['| probe | complete |', '| m1 | pending |', '| m1-r1-u1 | complete |',
      '| m1-r1-u2 | complete |', '| wall | pending |', '| done | pending |']);
    const hash = planValidator.computePlanHash(body);
    fs.writeFileSync(planPath, '<!-- plan_hash: ' + hash + ' -->\n' + body);
    fs.writeFileSync(path.join(projectDir, 'workflow-state.md'), 'project: issue-827c\nbranch: wf/827c\n');
    return {
      tmp, planPath, hash,
      projPath: path.join(projectDir, '.cache', 'epoch-projections', 'owner-projection.json'),
      opts: { planPath, project: 'issue-827c',
        shell: () => ({ exitCode: 0, ok: true, result: 'ok' }),
        readFile: p => fs.readFileSync(p, 'utf8'), writeFile: (p, c) => fs.writeFileSync(p, c),
        cacheExists: p => fs.existsSync(p),
        mkdirp: d => { try { fs.mkdirSync(d, { recursive: true }); } catch (_) {} },
        unlink: p => { try { fs.unlinkSync(p); } catch (_) {} },
        now: () => 'T1' },
      cleanup: () => fs.rmSync(tmp, { recursive: true, force: true }),
    };
  };
  const f = mk827c();
  try {
    const r1 = runExpandClose({ ...f.opts, nodeId: 'm1' });
    assert(r1.result === 'ok' && JSON.stringify(r1.discharged) === JSON.stringify(['m1#1']),
      '#827-CLOSE: the settled point discharges, got ' + JSON.stringify({ result: r1.result, reason: r1.reason }));
    assert(r1.owner_projection === 'appended',
      '#827-CLOSE: the discharge transaction itself writes the owner projection (owner_projection: '
      + 'appended), got ' + JSON.stringify(r1.owner_projection));
    assert(fs.existsSync(f.projPath),
      '#827-CLOSE: the durable projection file exists at .cache/epoch-projections/owner-projection.json');
    const firstWrite = fs.readFileSync(f.projPath, 'utf8');
    const folded1 = load827({ planPath: f.planPath, readFile: f.opts.readFile }, f.hash);
    assert(folded1.present === true && folded1.points.has('m1')
      && folded1.leafToMilestone['m1-r1-u1'] === 'm1' && folded1.leafToMilestone['m1-r1-u2'] === 'm1',
      '#827-CLOSE: the projection covers EVERY unit leaf of the discharged record, got ' + JSON.stringify(folded1));
    assert(load827({ planPath: f.planPath, readFile: f.opts.readFile }, 'e'.repeat(64)).present === false,
      '#827-CLOSE: the projection is epoch-bound — a foreign plan hash reads it as EMPTY');

    const r2 = runExpandClose({ ...f.opts, nodeId: 'm1' });
    assert(r2.result === 'ok' && r2.alreadyDischarged === true && r2.owner_projection === 'present'
      && fs.readFileSync(f.projPath, 'utf8') === firstWrite,
      '#827-CLOSE: the alreadyDischarged re-ensure is idempotent (present, byte-untouched), got '
      + JSON.stringify({ already: r2.alreadyDischarged, owner_projection: r2.owner_projection }));

    // The crash repair: a projection lost between the committed discharge and the write is re-appended
    // by the same alreadyDischarged branch, byte-identical (the stamp comes from the point's OWN
    // discharge block, not the wall clock).
    fs.unlinkSync(f.projPath);
    const r3 = runExpandClose({ ...f.opts, nodeId: 'm1' });
    assert(r3.result === 'ok' && r3.alreadyDischarged === true && r3.owner_projection === 'appended'
      && fs.readFileSync(f.projPath, 'utf8') === firstWrite,
      '#827-CLOSE: a lost projection is re-appended BYTE-IDENTICALLY by the re-ensure (the crash-repair '
      + 'heal), got ' + JSON.stringify({ owner_projection: r3.owner_projection }));
  } finally { f.cleanup(); }

  // A point with NO expansion record (nothing discharged, no interior) has nothing to project.
  const PLAN827C_NOREC = ['# Plan — 827c2', '',
    '## Meta', '', 'plan_form: spine', '',
    '## Nodes', '',
    '| id | role | depends_on | declared_write_set | cardinality | shape |',
    '|---|---|---|---|---|---|',
    '| m1 | expansion-point | — | — | 1 | sequence |', '',
    '## Node Ledger', '', '| id | status |', '|---|---|', '| m1 | complete |', ''].join('\n');
  const tmp2 = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-827c2-'));
  try {
    const projectDir = path.join(tmp2, 'kaola-workflow', 'issue-827c2');
    fs.mkdirSync(path.join(projectDir, '.cache'), { recursive: true });
    const planPath = path.join(projectDir, 'workflow-plan.md');
    const hash2 = planValidator.computePlanHash(PLAN827C_NOREC);
    fs.writeFileSync(planPath, '<!-- plan_hash: ' + hash2 + ' -->\n' + PLAN827C_NOREC);
    fs.writeFileSync(path.join(projectDir, 'workflow-state.md'), 'project: issue-827c2\nbranch: wf/827c2\n');
    const r = runExpandClose({ planPath, project: 'issue-827c2', nodeId: 'm1',
      shell: () => ({ exitCode: 0, ok: true, result: 'ok' }),
      readFile: p => fs.readFileSync(p, 'utf8'), writeFile: (p, c) => fs.writeFileSync(p, c),
      cacheExists: p => fs.existsSync(p), mkdirp: () => {}, unlink: () => {}, now: () => 'T1' });
    assert(r.result === 'ok' && r.alreadyDischarged === true && r.owner_projection === 'skipped'
      && !fs.existsSync(path.join(projectDir, '.cache', 'epoch-projections')),
      '#827-CLOSE: no records => no interior => owner_projection: skipped (no band created), got '
      + JSON.stringify({ owner_projection: r.owner_projection }));
  } finally { fs.rmSync(tmp2, { recursive: true, force: true }); }
});

// ===========================================================================
// #839 — THE POST-DISCHARGE RE-EXPANSION WINDOW. #827's projection closes the straight-line
// post-discharge routing case, but its OWN designed follow-on re-opens the same hole one step later.
// `route-findings` resolves an interior-owned finding to `route: reexpand-open`; `reexpand-open`
// appends the fixer unit's expansion record; and from that instant the execution view names the NEW
// fixer as a route owner while the discharge projection still covers only the FIRST record's leaves.
// Recorded `[leaf]` vs recomputed `[leaf, fixer]` mismatches, and the classifier reads the point as
// projection-COVERED, so the divergence is typed `tamper` — the class that names no route at all.
//
// That is not a cosmetic misclassification. `readReviewJournal` returns ok:false, so EVERY consumer
// hard-refuses inside the window — including `record-evidence` for the fixer itself. The fixer
// cannot record, so it cannot close; `expand-close` cannot re-discharge an unsettled point; the
// projection therefore never gains the fixer, and the window never closes. `reexpand-open` itself is
// caught by its own window: its Phase-1 record append opens the window, and the Phase-2 frontier open
// then reads the journal it just invalidated and refuses — leaving the record appended, the unit row
// `pending`, and NO `open()` proof, which `expand-close` refuses as `expansion_open_incomplete` and a
// retried `reexpand-open` refuses as `reexpansion_point_not_discharged`. A permanent wedge with no
// in-grammar exit.
//
// The window is STRUCTURAL, not a race: `ensureOwnerProjection` has exactly one caller
// (`runExpandClose`), so nothing on the re-expansion path can advance the projection.
//
// Two fix directions close it and the pins below are deliberately blind to WHICH is taken: either
// `reexpand-open` appends the superseding projection entry inside its own Phase-1 transaction (the
// projection is append-only per epoch and the fold UNIONS entries, so one more write through the
// existing writer suffices), or the matchers canonicalize units recorded on a projection-COVERED
// point through the point's coverage rather than only through exact leaf entries. The assertions
// name only the observable arc and the typed class, never the mechanism.
// ===========================================================================

// #839-ARC — the wedge as a GREEN ARC, driven end to end through the production verbs on a real
// tmpdir: discharge -> a settled review carrying an interior-owned finding -> reexpand-open -> the
// FIXER records its own evidence -> the fixer closes -> re-discharge, with the review journal
// readable at every step. The review settles PASS carrying a non-blocking `action=note` finding, so
// the unresolved-attempt fence (`review_attempt_unresolved`, a separate and correctly-typed gate
// with its own repair route) is not in play and the ONLY thing standing between this run and a clean
// re-expansion is the window itself.
scenario(() => {
  const { runExpandClose, runReExpandOpen, runCloseNode } = require('./kaola-workflow-adaptive-node');
  const crypto = require('crypto');
  assert(typeof runReExpandOpen === 'function' && typeof runExpandClose === 'function'
    && typeof loadOwnerProjection === 'function',
    '#839-ARC: the re-open verb, the discharge verb and the projection read-fold are exported');
  if (typeof runReExpandOpen !== 'function' || typeof runExpandClose !== 'function') return;

  const PLAN839 = ['# Plan — 839', '',
    '## Meta', '', 'plan_form: spine', '',
    'expansion(m1):', '  milestone_goal: g', '  expected_surfaces: lib/',
    '  join_constraints: none', '  review_class: code-reviewer', '',
    '## Nodes', '',
    '| id | role | depends_on | declared_write_set | cardinality | shape |',
    '|---|---|---|---|---|---|',
    '| probe | code-explorer | — | — | 1 | sequence |',
    '| m1 | expansion-point | probe | — | 1 | sequence |',
    '| wall | code-reviewer | m1 | — | 1 | sequence |',
    '| done | finalize | wall | — | 1 | sequence |', '',
    '## Node Ledger', '', '| id | status |', '|---|---|',
    '| probe | complete |', '| m1 | pending |', '| m1-r1-u1 | complete |',
    '| wall | pending |', '| done | pending |', '',
    '## Required Agent Compliance', '', '| requirement | status | evidence |', '| --- | --- | --- |', '',
    '## Expansion Records', '',
    'record(m1#1):', '  point: m1', '  grain: g', '  path: p', '  join: j', '  probe: pr', '  serializer: none',
    '  unit: u1 | implementer | standard | lib/composed.js | co_open | —', '',
    'open(m1#1):', '  at: T0', ''].join('\n');

  const tmp839 = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-839-'));
  try {
    const projectDir = path.join(tmp839, 'kaola-workflow', 'issue-839');
    const cacheDir = path.join(projectDir, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    const planPath = path.join(projectDir, 'workflow-plan.md');
    const hash839 = planValidator.computePlanHash(PLAN839);
    fs.writeFileSync(planPath, '<!-- plan_hash: ' + hash839 + ' -->\n' + PLAN839);
    fs.writeFileSync(path.join(projectDir, 'workflow-state.md'), 'project: issue-839\nbranch: wf/839\n');

    const BASE839 = 'b'.repeat(40);
    const opts839 = {
      planPath, project: 'issue-839',
      shell: (scriptPath, args) => {
        const base = path.basename(String(scriptPath));
        const argv = args || [];
        const at = argv.indexOf('--node-id');
        const nid = at >= 0 ? argv[at + 1] : null;
        if (base === 'kaola-workflow-next-action.js') {
          return { exitCode: 0, result: 'ok', allDone: false,
            readyPending: [{ id: 'm1-r2-fx', role: 'implementer', model: 'standard',
              declared_write_set: 'lib/composed.js', kind: 'write' }] };
        }
        if (base === 'kaola-workflow-task-mirror.js') return { exitCode: 0, result: 'ok' };
        // --start / --record-base own the barrier baseline, and the evidence-binding nonce every
        // record-evidence is checked against is that file's SHA prefix — so the stub must WRITE it,
        // or the fixer's record-evidence refuses for a reason that has nothing to do with #839.
        if ((argv.includes('--start') || argv.includes('--record-base')) && nid) {
          const basePath = path.join(cacheDir, 'barrier-base-' + nid);
          if (!fs.existsSync(basePath)) fs.writeFileSync(basePath, BASE839 + '\n');
          return { exitCode: 0, ok: true, result: 'ok', nodeId: nid,
            recordBase: { result: 'ok', nodeId: nid, base: BASE839 } };
        }
        return { exitCode: 0, ok: true, result: 'ok', overallOk: true,
          recordBase: { base: BASE839 } };
      },
      readFile: p => fs.readFileSync(p, 'utf8'),
      writeFile: (p, c) => fs.writeFileSync(p, c),
      cacheExists: p => fs.existsSync(p),
      mkdirp: d => { try { fs.mkdirSync(d, { recursive: true }); } catch (_) {} },
      unlink: p => { try { fs.unlinkSync(p); } catch (_) {} },
      now: () => 'T1',
      sinkProgressProbe: () => ({ state: 'pristine', evidence: 'test' }),
    };
    const livePlan = () => fs.readFileSync(planPath, 'utf8');

    // --- (1) PRECONDITION: the first discharge commits and projects its own interior. ---
    const discharged839 = runExpandClose({ ...opts839, nodeId: 'm1' });
    assert(discharged839.result === 'ok' && discharged839.owner_projection === 'appended',
      '#839-ARC PRECONDITION: the first discharge commits and writes its owner projection, got '
      + JSON.stringify({ result: discharged839.result, reason: discharged839.reason,
        owner_projection: discharged839.owner_projection }));

    // --- (2) PRECONDITION: the wall settles carrying an interior-owned finding, and the journal
    //     reads GREEN post-discharge (this is #827's shipped behaviour — the arc starts healthy). ---
    const gate839 = canonicalLogicalGateIdentity({ kind: 'sequence', id: 'wall',
      origin: ['m1'], members: ['wall'] });
    const gens839 = [{ member: 'wall', nonce: 'wallnonce839a' }];
    const digest839 = '9'.repeat(64);
    const raw839 = 'id=F-1 scope=in_scope action=note status=resolved severity=low '
      + 'file=lib/composed.js fix_role=implementer';
    const wallBody839 = 'evidence-binding: wall wallnonce839a\nverdict: pass\nfindings_blocking: 0\n'
      + 'finding: ' + raw839 + '\n';
    fs.writeFileSync(path.join(cacheDir, 'wall.md'), wallBody839);
    const canonical839 = { source_node: 'wall', raw: raw839, id: 'F-1', scope: 'in_scope',
      action: 'note', status: 'resolved', severity: 'low', file: 'lib/composed.js',
      fix_role: 'implementer' };
    // RECORDED while only m1#1 existed: the single interior leaf that owned lib/composed.js.
    const route839 = { source_node: 'wall', finding_id: 'F-1', id: 'F-1', scope: 'in_scope',
      action: 'note', status: 'resolved', severity: 'low', file: 'lib/composed.js',
      ownership_candidates: ['m1-r1-u1'], owning_node: 'm1-r1-u1', fix_role: 'implementer',
      raw: raw839 };
    const attempt839 = { attempt_id: 'wall:1', ordinal: 1, plan_hash: hash839, logical_gate: gate839,
      candidate_digest: digest839, candidate_declared: {}, candidate_residue_digest: 'd'.repeat(64),
      generations: gens839,
      transaction_key: crypto.createHash('sha256').update(JSON.stringify({ plan_hash: hash839,
        logical_gate_key: gate839.key, candidate_digest: digest839, generations: gens839 })).digest('hex'),
      settlement_command: 'close-node', outcome: 'pass', reason: null,
      receipts: [{ node_id: 'wall', generation: 'wallnonce839a', body: wallBody839,
        receipt_sha256: crypto.createHash('sha256').update(wallBody839).digest('hex'),
        effective_pass: true, verdict: 'pass', findings_blocking: 0 }],
      findings: [canonical839], route_candidates: [route839], lifecycle_settled: true,
      repair: { selected_writer: null, settled: null }, rebind: [], consumed_by: null };
    fs.writeFileSync(path.join(cacheDir, 'review-attempts.json'),
      JSON.stringify({ schema_version: 1, plan_hash: hash839, attempts: [attempt839] }, null, 2) + '\n');
    const preState839 = readReviewJournal(opts839, livePlan());
    assert(preState839.ok === true,
      '#839-ARC PRECONDITION: the leaf-recorded journal reads GREEN after the discharge (#827), got '
      + JSON.stringify({ ok: preState839.ok, reason: preState839.reason,
        route_mismatch_class: preState839.route_mismatch_class }));

    // --- (3) THE PIN: reexpand-open must COMMIT. Today its Phase-1 record append opens the window
    //     and its own Phase-2 frontier open then refuses over the journal it just invalidated,
    //     half-committing the transaction. ---
    const reopen839 = runReExpandOpen({ ...opts839, nodeId: 'm1',
      composition: { derivation: { grain: 'g', path: 'p', join: 'j', probe: 'pr', serializer: 'none' },
        units: [{ name: 'fx', role: 'implementer', model: 'standard',
          write_set: 'lib/composed.js', mode: 'co_open' }] } });
    assert(reopen839.reason !== 'review_journal_route_mismatch',
      '#839-ARC: reexpand-open must not be fenced by the window its OWN record append opens — it '
      + 'refused review_journal_route_mismatch after half-committing, got '
      + JSON.stringify({ result: reopen839.result, reason: reopen839.reason,
        route_mismatch_class: reopen839.route_mismatch_class }));
    assert(reopen839.result === 'ok' && reopen839.reopened === true,
      '#839-ARC: the routed re-expansion COMMITS, got '
      + JSON.stringify({ result: reopen839.result, reason: reopen839.reason, detail: reopen839.detail }));
    const openedIds839 = (reopen839.opened || []).map(o => o.id);
    assert(openedIds839.includes('m1-r2-fx')
      && readLedgerStatuses(livePlan())['m1-r2-fx'] === 'in_progress',
      '#839-ARC: the fixer unit is OPENED (in_progress), not stranded pending, got '
      + JSON.stringify({ opened: openedIds839, ledger: readLedgerStatuses(livePlan()) }));

    // --- (4) THE PIN: inside the window every readReviewJournal consumer must still work — most of
    //     all record-evidence for the FIXER ITSELF, which is what makes the wedge permanent. ---
    const windowState839 = readReviewJournal(opts839, livePlan());
    assert(windowState839.ok === true,
      '#839-ARC: the review journal stays READABLE while the re-expansion is in flight — the '
      + 'recomputed fixer owner must reconcile against the discharge projection, got '
      + JSON.stringify({ ok: windowState839.ok, reason: windowState839.reason,
        route_mismatch_class: windowState839.route_mismatch_class, point: windowState839.point }));
    const nonce839 = ((reopen839.opened || [])[0] || {}).nonce
      || readNonce(planPath, 'm1-r2-fx', opts839.readFile) || '';
    const recorded839 = runRecordEvidence({ ...opts839, nodeId: 'm1-r2-fx',
      stdinContent: 'evidence-binding: m1-r2-fx ' + nonce839 + '\ntests-green: 12 passing\n' });
    assert(recorded839.result === 'ok',
      '#839-ARC: the FIXER records its own evidence inside the window — the refusal that makes the '
      + 'wedge permanent (it can never close, so the point can never re-discharge, so the projection '
      + 'can never gain it), got ' + JSON.stringify({ result: recorded839.result,
        reason: recorded839.reason, detail: recorded839.detail }));
    const routedWindow839 = runRouteFindings({ ...opts839, nodeId: 'wall' }, 'issue-839');
    assert(routedWindow839.result === 'ok',
      '#839-ARC: route-findings still resolves inside the window, got '
      + JSON.stringify({ result: routedWindow839.result, reason: routedWindow839.reason,
        route_mismatch_class: routedWindow839.route_mismatch_class }));

    // --- (5) THE PIN: the arc CLOSES. The fixer closes, the point re-discharges, and the journal is
    //     green on the far side — the projection now covers the fixer through the ordinary writer. ---
    const closedFixer839 = runCloseNode({ ...opts839, nodeId: 'm1-r2-fx' });
    assert(closedFixer839.result === 'ok',
      '#839-ARC: the fixer unit closes, got ' + JSON.stringify({ result: closedFixer839.result,
        reason: closedFixer839.reason, detail: closedFixer839.detail }));
    const redischarged839 = runExpandClose({ ...opts839, nodeId: 'm1' });
    assert(redischarged839.result === 'ok',
      '#839-ARC: the milestone RE-discharges, got ' + JSON.stringify({ result: redischarged839.result,
        reason: redischarged839.reason }));
    const finalProjection839 = loadOwnerProjection({ planPath, readFile: opts839.readFile }, hash839);
    assert(finalProjection839.present === true
      && finalProjection839.leafToMilestone['m1-r1-u1'] === 'm1'
      && finalProjection839.leafToMilestone['m1-r2-fx'] === 'm1',
      '#839-ARC: after the re-discharge the projection covers BOTH interiors, got '
      + JSON.stringify(finalProjection839.leafToMilestone));
    const finalState839 = readReviewJournal(opts839, livePlan());
    assert(finalState839.ok === true,
      '#839-ARC: the journal is green on the far side of the whole arc, got '
      + JSON.stringify({ ok: finalState839.ok, reason: finalState839.reason }));
  } finally { fs.rmSync(tmp839, { recursive: true, force: true }); }
});

// ---------------------------------------------------------------------------
// #839-CLASS — the typed classifier, direct-call. A mismatch whose EXTRA owners are all expansion
// units of a projection-COVERED point that carries an OPENED, UN-DISCHARGED record is the
// re-expansion window, not forgery: it must carry a typed NON-tamper class, name the point, and
// route to the re-discharge that closes it. Every neighbouring class stays exactly where #827 put
// it — this narrows `tamper`, it never widens the relief. In particular the #827-U disjointness pin
// (a COVERED leaf with a residual divergence on a point carrying NO open record) stays `tamper`, so
// the new class turns on the OPEN, un-discharged record, never on coverage alone.
// ---------------------------------------------------------------------------
scenario(() => {
  assert(typeof routeMismatchDetail === 'function',
    '#839-CLASS: the typed route-mismatch classifier is exported for direct pins');
  if (typeof routeMismatchDetail !== 'function') return;

  const RECORD1_839 = ['# Plan', '', '## Expansion Records', '',
    'record(m1#1):', '  point: m1', '  grain: g', '  path: p', '  join: j', '  probe: pr',
    '  serializer: none', '  unit: u1 | implementer | — | lib/composed.js | co_open | —', '',
    'open(m1#1):', '  at: T1', '',
    'discharge(m1):', '  at: T2', '  records: m1#1', ''].join('\n');
  // THE WINDOW: reexpand-open appended a SECOND record + its open proof; no discharge covers it yet.
  const WINDOW_839 = RECORD1_839 + '\n' + ['record(m1#2):', '  point: m1', '  grain: g', '  path: p',
    '  join: j', '  probe: pr', '  serializer: none',
    '  unit: fx | implementer | — | lib/composed.js | co_open | —', '',
    'open(m1#2):', '  at: T3', ''].join('\n');
  const execIds839 = new Set(['probe', 'm1', 'wall', 'done', 'm1-r1-u1', 'm1-r2-fx']);
  // The projection as it exists in the window: written by the FIRST discharge, covering m1#1 only.
  const windowProjection839 = { present: true, leafToMilestone: { 'm1-r1-u1': 'm1' },
    points: new Set(['m1']) };

  const windowClass839 = routeMismatchDetail(
    [{ ownership_candidates: ['m1-r1-u1'], owning_node: 'm1-r1-u1' }],
    [{ ownership_candidates: ['m1-r1-u1', 'm1-r2-fx'], owning_node: null }],
    windowProjection839, WINDOW_839, execIds839);
  assert(windowClass839.route_mismatch_class !== 'tamper',
    '#839-CLASS: the re-expansion window is NOT forgery — an extra owner that is an expansion unit '
    + 'of a projection-covered point carrying an OPENED, un-discharged record must not classify '
    + 'tamper (the class that names no route), got ' + JSON.stringify(windowClass839));
  assert(typeof windowClass839.route_mismatch_class === 'string'
    && windowClass839.route_mismatch_class.length > 0,
    '#839-CLASS: the window carries a TYPED class (callers classify structurally, never by prose), '
    + 'got ' + JSON.stringify(windowClass839));
  assert(windowClass839.point === 'm1',
    '#839-CLASS: the window names the owning expansion point, got ' + JSON.stringify(windowClass839));
  assert(typeof windowClass839.detail === 'string'
    && /expand-close/.test(windowClass839.detail) && /\bm1\b/.test(windowClass839.detail),
    '#839-CLASS: the detail routes to the RE-DISCHARGE that closes the window (expand-close on the '
    + 'point), got ' + JSON.stringify(windowClass839.detail));
  assert(!/hand-edit/i.test(String(windowClass839.detail))
    || /NEVER hand-edit/i.test(String(windowClass839.detail)),
    '#839-CLASS: the detail never invites journal surgery, got ' + JSON.stringify(windowClass839.detail));
  const windowHint839 = getOperatorHint('review_journal_route_mismatch', windowClass839);
  assert(typeof windowHint839 === 'string' && !/finish or discard runs/.test(windowHint839),
    '#839-CLASS: the operator hint stops affirmatively MISDIRECTING (the tamper wording tells the '
    + 'operator to finish or discard the run), got ' + JSON.stringify(windowHint839));

  // --- The tamper pins that must SURVIVE the narrowing. ---
  const forged839 = routeMismatchDetail(
    [{ ownership_candidates: ['m1-r9-ghost'], owning_node: 'm1-r9-ghost' }], [],
    windowProjection839, WINDOW_839, execIds839);
  assert(forged839.route_mismatch_class === 'tamper' && !forged839.point,
    '#839-CLASS: a FORGED owner — in neither the execution node table nor the projection — still '
    + 'refuses tamper-class even while a window is open on the same point, got '
    + JSON.stringify(forged839));
  const settled839 = routeMismatchDetail(
    [{ ownership_candidates: ['m1-r1-u1'], owning_node: 'm1-r1-u1' }], [],
    windowProjection839, RECORD1_839, new Set(['probe', 'm1', 'wall', 'done', 'm1-r1-u1']));
  assert(settled839.route_mismatch_class === 'tamper',
    '#839-CLASS: with NO open un-discharged record on the point, a covered leaf with a residual '
    + 'divergence is still tamper — the new class turns on the OPEN record, never on coverage alone '
    + '(the #827-U disjointness pin), got ' + JSON.stringify(settled839));
  const legacy839 = routeMismatchDetail(
    [{ ownership_candidates: ['m1-r1-u1'], owning_node: 'm1-r1-u1' }],
    [{ ownership_candidates: ['m1-r1-u1'], owning_node: 'm1-r1-u1' }],
    { present: false, leafToMilestone: {}, points: new Set() }, RECORD1_839,
    new Set(['probe', 'm1', 'wall', 'done', 'm1-r1-u1']));
  assert(legacy839.route_mismatch_class === 'projection_missing' && legacy839.point === 'm1',
    '#839-CLASS: the #827 projection_missing class is untouched by the narrowing, got '
    + JSON.stringify(legacy839));
});

// ---------------------------------------------------------------------------
// #839-V2 — the schema-2 twin. The V2 route arm recomputes over the SAME execution view through the
// SAME classifier, so the window reaches it identically and the fix must reach both lanes. Pinned on
// the classification (mechanism-blind: whichever direction closes the window, a route divergence that
// IS the window may never be typed `tamper`), with the V2 forgery pin held in place beside it.
// ---------------------------------------------------------------------------
scenario(() => {
  assert(typeof reviewJournalV2MatchesPlan === 'function' && typeof schema2RouteCandidates === 'function',
    '#839-V2: the schema-2 matcher + its route recomputation are exported');
  if (typeof reviewJournalV2MatchesPlan !== 'function') return;

  const NODE_ROWS_839V = [
    '| probe | code-explorer | — | — | 1 | sequence |',
    '| m1 | expansion-point | probe | — | 1 | sequence |',
    '| wall | code-reviewer | m1 | — | 1 | sequence |',
    '| done | finalize | wall | CHANGELOG.md | 1 | sequence |',
  ];
  const LEDGER_839V = ['| probe | complete | |', '| m1 | pending | |', '| m1-r1-u1 | complete | |',
    '| m1-r2-fx | in_progress | |', '| wall | pending | |', '| done | pending | |'];
  const REC1_839V = ['## Expansion Records', '',
    'record(m1#1):', '  point: m1', '  grain: g', '  path: p', '  join: j', '  probe: pr',
    '  serializer: none', '  unit: u1 | implementer | — | lib/composed.js | co_open | —', '',
    'open(m1#1):', '  at: T1', '',
    'discharge(m1):', '  at: T2', '  records: m1#1', ''].join('\n');
  const WINDOW_839V = REC1_839V + '\n' + ['record(m1#2):', '  point: m1', '  grain: g', '  path: p',
    '  join: j', '  probe: pr', '  serializer: none',
    '  unit: fx | implementer | — | lib/composed.js | co_open | —', '',
    'open(m1#2):', '  at: T3', ''].join('\n');
  const dischargedPlan839V = makePlan(LEDGER_839V, NODE_ROWS_839V) + REC1_839V;
  const windowPlan839V = makePlan(LEDGER_839V, NODE_ROWS_839V) + WINDOW_839V;

  const spine839V = planValidator.parseNodes(windowPlan839V);
  const gate839V = reviewLogicalGate(spine839V, spine839V.find(n => n.id === 'wall'));
  const gateCore839V = { key: gate839V.key, kind: gate839V.kind, members: gate839V.members,
    claim_digest: gate839V.claim_digest, surface_digests: gate839V.surface_digests,
    aggregation: gate839V.aggregation, certified_producers: gate839V.certified_producers };
  const finding839V = { uid: 'F-1', scope: 'in_scope', action: 'fix', status: 'open',
    severity: 'high', primary_anchor: { path: 'lib/composed.js' } };
  // RECORDED at settle time (post-discharge, pre-re-expansion): the single interior leaf.
  const recorded839V = schema2RouteCandidates([finding839V],
    planValidator.planNodesWithExpansions(dischargedPlan839V), 'wall');
  assert(JSON.stringify(recorded839V.map(r => r.ownership_candidates)) === JSON.stringify([['m1-r1-u1']]),
    '#839-V2 fixture: the attempt recorded the single interior leaf, got '
    + JSON.stringify(recorded839V.map(r => r.ownership_candidates)));
  // ...while the WINDOW execution view already names the fixer the re-expansion just composed.
  const recomputed839V = schema2RouteCandidates([finding839V],
    planValidator.planNodesWithExpansions(windowPlan839V), 'wall');
  assert(JSON.stringify(recomputed839V.map(r => r.ownership_candidates))
      === JSON.stringify([['m1-r1-u1', 'm1-r2-fx']]),
    '#839-V2 fixture: the window recomputation already names the UN-DISCHARGED fixer, got '
    + JSON.stringify(recomputed839V.map(r => r.ownership_candidates)));

  const attempt839V = { attempt_id: 'wall:1', ordinal: 1, logical_gate: gateCore839V,
    gate_mode: 'change_gate', outcome: 'fail', lifecycle_settled: true, consumed_by: null,
    repair: { selected_writer: null, settled: null }, producer_bindings: {},
    receipts: [{ node_id: 'wall', findings: [finding839V] }], route_candidates: recorded839V };
  const journal839V = { schema_version: 2, attempts: [attempt839V] };
  // The projection as it exists in the window: the FIRST discharge's entry only.
  const windowProjection839V = { present: true, leafToMilestone: { 'm1-r1-u1': 'm1' },
    points: new Set(['m1']) };

  const windowV2 = reviewJournalV2MatchesPlan(journal839V, windowPlan839V, windowProjection839V);
  assert(windowV2.route_mismatch_class !== 'tamper',
    '#839-V2: the schema-2 lane reaches the window through the same execution-view recomputation, '
    + 'so it must not type it tamper either, got ' + JSON.stringify(windowV2));
  assert(windowV2.ok === true
    || (typeof windowV2.route_mismatch_class === 'string' && windowV2.point === 'm1'),
    '#839-V2: the schema-2 lane either reconciles the window or names it with a typed class + its '
    + 'point, got ' + JSON.stringify(windowV2));

  const forgedV2 = { schema_version: 2, attempts: [{ ...attempt839V,
    route_candidates: recorded839V.map(r => ({ ...r,
      ownership_candidates: ['ghost-writer'], owning_node: 'ghost-writer' })) }] };
  const forgedResultV2 = reviewJournalV2MatchesPlan(forgedV2, windowPlan839V, windowProjection839V);
  assert(forgedResultV2.ok === false && forgedResultV2.reason === 'review_journal_route_mismatch'
    && forgedResultV2.route_mismatch_class === 'tamper' && !forgedResultV2.point,
    '#839-V2: a forged owner still refuses tamper-class in the schema-2 twin even with a window open '
    + 'on the same point, got ' + JSON.stringify(forgedResultV2));
});

// ===========================================================================
// #839R — THE PROJECTION-WRITE-FAILURE ARM RE-CREATES THE #839 WEDGE.
//
// #839 closed the window by having `reexpand-open` write the superseding owner-projection entry
// inside its OWN Phase-1 transaction, BEFORE the plan write. That write is FAIL-OPEN
// (`ensureOwnerProjection` never throws; it returns `'write_failed'`), and the call site's comment
// asserts the consolation prize: "a `write_failed` leaves the classifier's typed
// reexpansion_in_flight class as the operator route."
//
// THAT CLAIM IS FALSE, and the falsity is the whole finding. Traced:
//   1. Phase-1 `ensureOwnerProjection` fails (transient ENOSPC / an EACCES on
//      .cache/epoch-projections/) and returns 'write_failed'. Nothing is fenced.
//   2. The plan write nonetheless SUCCEEDS — record m1#2 plus the unit's ledger row are committed.
//   3. Phase-2 `runOpenReady` re-reads the now-mismatched journal and refuses BEFORE
//      `openExpansionFrontier` gets to append the `open(m1#2)` proof.
//   4. From that instant every `readReviewJournal` consumer refuses `review_journal_route_mismatch`
//      with class **`tamper`** — NOT `reexpansion_in_flight` — because `reExpansionWindowUnits`
//      requires `expansionRecordOpened`, and the proof block is exactly what step 3 skipped.
//   5. The `tamper` hint tells the operator to "finish or discard runs that predate the current
//      release", which is affirmatively WRONG for a current-release run that hit a disk error.
//   6. No verb re-attempts the projection append: a retried `reexpand-open` refuses
//      `reexpansion_point_not_discharged` (the cascade already flipped the point to `pending`),
//      `expand-close` refuses `expansion_open_incomplete`, and `reconcile-running-set`'s
//      `rollForwardExpansions` re-runs only Phases 2+3 — which refuse on the same journal.
//   7. The run is PERMANENTLY WEDGED short of discard+restart: the exact wedge #839 was filed to
//      close, re-created one fault-injection away.
//
// A second consequence: because the healthy path writes the projection first, the typed
// `reexpansion_in_flight` class is emitted by NO production sequence at all. The `write_failed` arm
// is the only sequence that can reach it, and it reaches `tamper` instead — so #839's migration half
// currently serves no reachable state.
//
// The pins below are blind to WHICH direction closes it (re-attempt the projection on a recovery
// verb; make the classifier admit a committed-but-unopened record; make Phase 1 fail CLOSED and roll
// the record back). They assert only observable outcomes: the run is recoverable, the residue is not
// slandered as forgery, the class the comment names is reachable, and real forgery still refuses.
// ===========================================================================

// #839R-ARC — the wedge driven end to end on a real tmpdir through the production verbs, with ONE
// fault injected: `opts.writeFile` throws ENOSPC for the owner-projection path, and ONLY for the
// duration of the `reexpand-open` call (a TRANSIENT fault — the disk is fine again by recovery
// time). Everything else is the shipped #839-ARC fixture, so any failure here is the fault arm and
// nothing else.
scenario(() => {
  const { runExpandClose, runReExpandOpen, runCloseNode } = require('./kaola-workflow-adaptive-node');
  const crypto = require('crypto');
  assert(typeof runReExpandOpen === 'function' && typeof runExpandClose === 'function'
    && typeof runReconcileRunningSet === 'function' && typeof runOpenReady === 'function',
    '#839R-ARC: the re-open verb, the discharge verb and both recovery verbs are exported');
  if (typeof runReExpandOpen !== 'function' || typeof runExpandClose !== 'function') return;

  const PLAN839R = ['# Plan — 839R', '',
    '## Meta', '', 'plan_form: spine', '',
    'expansion(m1):', '  milestone_goal: g', '  expected_surfaces: lib/',
    '  join_constraints: none', '  review_class: code-reviewer', '',
    '## Nodes', '',
    '| id | role | depends_on | declared_write_set | cardinality | shape |',
    '|---|---|---|---|---|---|',
    '| probe | code-explorer | — | — | 1 | sequence |',
    '| m1 | expansion-point | probe | — | 1 | sequence |',
    '| wall | code-reviewer | m1 | — | 1 | sequence |',
    '| done | finalize | wall | — | 1 | sequence |', '',
    '## Node Ledger', '', '| id | status |', '|---|---|',
    '| probe | complete |', '| m1 | pending |', '| m1-r1-u1 | complete |',
    '| wall | pending |', '| done | pending |', '',
    '## Required Agent Compliance', '', '| requirement | status | evidence |', '| --- | --- | --- |', '',
    '## Expansion Records', '',
    'record(m1#1):', '  point: m1', '  grain: g', '  path: p', '  join: j', '  probe: pr', '  serializer: none',
    '  unit: u1 | implementer | standard | lib/composed.js | co_open | —', '',
    'open(m1#1):', '  at: T0', ''].join('\n');

  const tmp839R = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-839R-'));
  try {
    const projectDir = path.join(tmp839R, 'kaola-workflow', 'issue-839r');
    const cacheDir = path.join(projectDir, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    const planPath = path.join(projectDir, 'workflow-plan.md');
    const hash839R = planValidator.computePlanHash(PLAN839R);
    fs.writeFileSync(planPath, '<!-- plan_hash: ' + hash839R + ' -->\n' + PLAN839R);
    fs.writeFileSync(path.join(projectDir, 'workflow-state.md'), 'project: issue-839r\nbranch: wf/839r\n');

    // THE FAULT SEAM. Path-scoped + window-scoped, the same posture as the T-776 rotation faults:
    // only the owner-projection write fails, and only while `faultArmed` is true, so the plan write
    // in the SAME transaction succeeds exactly as a real partial-disk failure would leave it.
    let faultArmed = false;
    let faultFired = 0;
    const BASE839R = 'b'.repeat(40);
    const opts839R = {
      planPath, project: 'issue-839r',
      shell: (scriptPath, args) => {
        const base = path.basename(String(scriptPath));
        const argv = args || [];
        const at = argv.indexOf('--node-id');
        const nid = at >= 0 ? argv[at + 1] : null;
        if (base === 'kaola-workflow-next-action.js') {
          return { exitCode: 0, result: 'ok', allDone: false,
            readyPending: [{ id: 'm1-r2-fx', role: 'implementer', model: 'standard',
              declared_write_set: 'lib/composed.js', kind: 'write' }] };
        }
        if (base === 'kaola-workflow-task-mirror.js') return { exitCode: 0, result: 'ok' };
        if ((argv.includes('--start') || argv.includes('--record-base')) && nid) {
          const basePath = path.join(cacheDir, 'barrier-base-' + nid);
          if (!fs.existsSync(basePath)) fs.writeFileSync(basePath, BASE839R + '\n');
          return { exitCode: 0, ok: true, result: 'ok', nodeId: nid,
            recordBase: { result: 'ok', nodeId: nid, base: BASE839R } };
        }
        return { exitCode: 0, ok: true, result: 'ok', overallOk: true,
          recordBase: { base: BASE839R } };
      },
      readFile: p => fs.readFileSync(p, 'utf8'),
      writeFile: (p, c) => {
        if (faultArmed && String(p).endsWith(OWNER_PROJECTION_NAME)) {
          faultFired++;
          const err = new Error('T-839R injected fault: ENOSPC on the owner-projection write');
          err.code = 'ENOSPC';
          throw err;
        }
        return fs.writeFileSync(p, c);
      },
      cacheExists: p => fs.existsSync(p),
      mkdirp: d => { try { fs.mkdirSync(d, { recursive: true }); } catch (_) {} },
      unlink: p => { try { fs.unlinkSync(p); } catch (_) {} },
      now: () => 'T1',
      sinkProgressProbe: () => ({ state: 'pristine', evidence: 'test' }),
    };
    const livePlan = () => fs.readFileSync(planPath, 'utf8');
    const COMPOSITION839R = {
      derivation: { grain: 'g', path: 'p', join: 'j', probe: 'pr', serializer: 'none' },
      units: [{ name: 'fx', role: 'implementer', model: 'standard',
        write_set: 'lib/composed.js', mode: 'co_open' }],
    };

    // --- (1) PRECONDITION: the first discharge commits and projects its own interior. ---
    const discharged839R = runExpandClose({ ...opts839R, nodeId: 'm1' });
    assert(discharged839R.result === 'ok' && discharged839R.owner_projection === 'appended',
      '#839R-ARC PRECONDITION: the first discharge commits and writes its owner projection, got '
      + JSON.stringify({ result: discharged839R.result, reason: discharged839R.reason,
        owner_projection: discharged839R.owner_projection }));

    // --- (2) PRECONDITION: the wall settles PASS carrying a non-blocking interior-owned finding,
    //     and the journal reads GREEN post-discharge. The arc starts healthy. ---
    const gate839R = canonicalLogicalGateIdentity({ kind: 'sequence', id: 'wall',
      origin: ['m1'], members: ['wall'] });
    const gens839R = [{ member: 'wall', nonce: 'wallnonce839r' }];
    const digest839R = '9'.repeat(64);
    const raw839R = 'id=F-1 scope=in_scope action=note status=resolved severity=low '
      + 'file=lib/composed.js fix_role=implementer';
    const wallBody839R = 'evidence-binding: wall wallnonce839r\nverdict: pass\nfindings_blocking: 0\n'
      + 'finding: ' + raw839R + '\n';
    fs.writeFileSync(path.join(cacheDir, 'wall.md'), wallBody839R);
    const canonical839R = { source_node: 'wall', raw: raw839R, id: 'F-1', scope: 'in_scope',
      action: 'note', status: 'resolved', severity: 'low', file: 'lib/composed.js',
      fix_role: 'implementer' };
    const route839R = { source_node: 'wall', finding_id: 'F-1', id: 'F-1', scope: 'in_scope',
      action: 'note', status: 'resolved', severity: 'low', file: 'lib/composed.js',
      ownership_candidates: ['m1-r1-u1'], owning_node: 'm1-r1-u1', fix_role: 'implementer',
      raw: raw839R };
    const attempt839R = { attempt_id: 'wall:1', ordinal: 1, plan_hash: hash839R,
      logical_gate: gate839R, candidate_digest: digest839R, candidate_declared: {},
      candidate_residue_digest: 'd'.repeat(64), generations: gens839R,
      transaction_key: crypto.createHash('sha256').update(JSON.stringify({ plan_hash: hash839R,
        logical_gate_key: gate839R.key, candidate_digest: digest839R, generations: gens839R })).digest('hex'),
      settlement_command: 'close-node', outcome: 'pass', reason: null,
      receipts: [{ node_id: 'wall', generation: 'wallnonce839r', body: wallBody839R,
        receipt_sha256: crypto.createHash('sha256').update(wallBody839R).digest('hex'),
        effective_pass: true, verdict: 'pass', findings_blocking: 0 }],
      findings: [canonical839R], route_candidates: [route839R], lifecycle_settled: true,
      repair: { selected_writer: null, settled: null }, rebind: [], consumed_by: null };
    const journalPath839R = path.join(cacheDir, 'review-attempts.json');
    fs.writeFileSync(journalPath839R,
      JSON.stringify({ schema_version: 1, plan_hash: hash839R, attempts: [attempt839R] }, null, 2) + '\n');
    assert(readReviewJournal(opts839R, livePlan()).ok === true,
      '#839R-ARC PRECONDITION: the leaf-recorded journal reads GREEN after the discharge (#827)');

    // --- (3) THE FAULT: reexpand-open runs with the projection write failing. ---
    faultArmed = true;
    const reopen839R = runReExpandOpen({ ...opts839R, nodeId: 'm1', composition: COMPOSITION839R });
    faultArmed = false;
    assert(faultFired >= 1,
      '#839R-ARC: the injected owner-projection write fault actually fired — this scenario is NOT '
      + 'vacuous, got faultFired=' + faultFired);

    // The residue as the fault left it. `residueCommitted` is what makes the arm dangerous: the plan
    // write landed even though the projection write did not, so the execution view names a unit the
    // projection cannot cover. Captured (not asserted) — a fix that makes Phase 1 fail CLOSED and
    // rolls the record back is a legitimate direction, and PIN C admits it explicitly.
    const residueCommitted839R = /^record\(m1#2\):/m.test(livePlan());
    const residueState839R = readReviewJournal(opts839R, livePlan());
    const residueHint839R = getOperatorHint('review_journal_route_mismatch', residueState839R);
    const residueSnapshot = () => JSON.stringify({
      reopen: { result: reopen839R.result, reason: reopen839R.reason,
        owner_projection: reopen839R.owner_projection },
      residue_committed: residueCommitted839R,
      record_opened: (() => { try {
        return planValidator.expansionRecordOpened(planValidator.parseExpansionRecords(livePlan()), 'm1#2');
      } catch (_) { return 'parse_failed'; } })(),
      journal: { ok: residueState839R.ok, reason: residueState839R.reason,
        route_mismatch_class: residueState839R.route_mismatch_class, point: residueState839R.point },
      ledger: readLedgerStatuses(livePlan()),
    });

    // --- PIN A (CLASSIFICATION): the residue of a FAILED PROJECTION WRITE on a current-release run
    //     is not forgery. It may never carry the `tamper` class, and the operator hint may never
    //     tell this run it predates the current release. ---
    assert(residueState839R.ok === true || residueState839R.route_mismatch_class !== 'tamper',
      '#839R-ARC PIN A: a transient owner-projection write failure must NOT be classified as '
      + '`tamper`. The run is current-release and the divergence is its OWN uncommitted projection, '
      + 'not a forged owner, got ' + residueSnapshot());
    assert(residueState839R.ok === true
      || !/finish or discard runs that predate the current release/.test(String(residueHint839R)),
      '#839R-ARC PIN A: the operator hint must not affirmatively MISDIRECT a current-release run '
      + 'into "finish or discard runs that predate the current release", got '
      + JSON.stringify(residueHint839R));

    // --- PIN C (THE COMMENT PROMISE): the call site claims a `write_failed` "leaves the
    //     classifier's typed reexpansion_in_flight class as the operator route". Either that class
    //     is genuinely what this sequence produces, or the sequence commits no residue at all (a
    //     fail-closed Phase 1, in which case there is nothing to classify). Today it is neither: the
    //     record is committed AND the class is `tamper`, so the promise is false and
    //     `reexpansion_in_flight` is reachable from no production sequence whatsoever. ---
    assert(residueCommitted839R === false
      || residueState839R.route_mismatch_class === 'reexpansion_in_flight',
      '#839R-ARC PIN C: the typed class the call-site comment NAMES must be the class this sequence '
      + 'actually produces (or the residue must not be committed at all). Otherwise '
      + '`reexpansion_in_flight` is dead in production and the comment is false, got '
      + residueSnapshot());

    // --- PIN B (RECOVERABILITY): there must exist an in-grammar verb that re-attempts the
    //     projection append and lets the run PROCEED — no discard+restart. The fault is CLEARED
    //     (transient), so nothing but the code stands in the way. Mechanism-blind: every documented
    //     recovery verb is offered, in order, and the assertion is on the OUTCOME only. ---
    const liveFixer839R = () => {
      const led = readLedgerStatuses(livePlan());
      const ids = Object.keys(led).filter(id => /^m1-r[0-9]+-fx$/.test(id));
      return ids.find(id => led[id] === 'in_progress') || null;
    };
    const unwedged839R = () => readReviewJournal(opts839R, livePlan()).ok === true
      && liveFixer839R() !== null;
    const recovery839R = [
      ['reconcile-running-set', () => runReconcileRunningSet({ ...opts839R })],
      ['expand-close (the route the in-flight class names)', () => runExpandClose({ ...opts839R, nodeId: 'm1' })],
      ['reexpand-open (retry after the transient fault cleared)',
        () => runReExpandOpen({ ...opts839R, nodeId: 'm1', composition: COMPOSITION839R })],
      ['open-ready', () => runOpenReady({ ...opts839R })],
    ];
    const tried839R = [];
    for (const [verb, run] of recovery839R) {
      if (unwedged839R()) break;
      let out = null;
      try { out = run(); } catch (err) { out = { threw: String(err && err.message) }; }
      tried839R.push({ verb, result: out && out.result, reason: out && out.reason,
        threw: out && out.threw });
    }
    assert(unwedged839R(),
      '#839R-ARC PIN B: after a transient owner-projection write failure the run must be RECOVERABLE '
      + 'in grammar — some verb re-attempts the projection append and the run proceeds, WITHOUT '
      + 'discard+restart. Every documented recovery verb refused. residue=' + residueSnapshot()
      + ' recovery=' + JSON.stringify(tried839R));

    // --- PIN B (continued): "proceeds" means the arc actually CLOSES. The fixer records, closes,
    //     the point re-discharges, and the journal is green on the far side.
    //
    //     GATED, and deliberately so: none of what follows can execute while the run is wedged, so
    //     these assertions (PIN E included) go live only once PIN B is satisfied. The today-
    //     executable twin of PIN E is the direct-call forgery pin in #839R-CLASS, which runs and
    //     passes on the current tree — it is a REGRESSION guard, not a red pin. ---
    const fixer839R = liveFixer839R();
    if (fixer839R) {
      // --- PIN E (THE NEGATIVE), placed at the moment the relief is ACTIVELY IN EFFECT: the run is
      //     recovered but the point is not re-discharged yet, so whatever mechanism relieves the
      //     write-failure residue is switched on RIGHT NOW. A genuinely forged owner — in neither
      //     the execution node table nor the projection — must still refuse tamper-class here. The
      //     journal bytes are restored afterwards so the arc continues on the real fixture. ---
      const journalBytes839R = fs.readFileSync(journalPath839R, 'utf8');
      const forgedJournal839R = JSON.parse(journalBytes839R);
      forgedJournal839R.attempts[0].route_candidates = [{ ...route839R,
        ownership_candidates: ['m1-r9-ghost'], owning_node: 'm1-r9-ghost' }];
      fs.writeFileSync(journalPath839R, JSON.stringify(forgedJournal839R, null, 2) + '\n');
      const forgedState839R = readReviewJournal(opts839R, livePlan());
      fs.writeFileSync(journalPath839R, journalBytes839R);
      assert(forgedState839R.ok === false
        && forgedState839R.reason === 'review_journal_route_mismatch'
        && forgedState839R.route_mismatch_class === 'tamper',
        '#839R-ARC PIN E: with the write-failure relief ACTIVE, a genuinely forged route owner must '
        + 'still refuse tamper-class — the relief may never blunt real tamper detection, got '
        + JSON.stringify({ ok: forgedState839R.ok, reason: forgedState839R.reason,
          route_mismatch_class: forgedState839R.route_mismatch_class }));
      assert(readReviewJournal(opts839R, livePlan()).ok === true,
        '#839R-ARC PIN E: the real journal is restored byte-for-byte after the forgery probe');

      const nonce839R = readNonce(planPath, fixer839R, opts839R.readFile) || '';
      const recorded839R = runRecordEvidence({ ...opts839R, nodeId: fixer839R,
        stdinContent: 'evidence-binding: ' + fixer839R + ' ' + nonce839R + '\ntests-green: 12 passing\n' });
      assert(recorded839R.result === 'ok',
        '#839R-ARC PIN B: the recovered fixer records its own evidence, got '
        + JSON.stringify({ node: fixer839R, result: recorded839R.result, reason: recorded839R.reason,
          detail: recorded839R.detail }));
      const closedFixer839R = runCloseNode({ ...opts839R, nodeId: fixer839R });
      assert(closedFixer839R.result === 'ok',
        '#839R-ARC PIN B: the recovered fixer closes, got '
        + JSON.stringify({ node: fixer839R, result: closedFixer839R.result,
          reason: closedFixer839R.reason, detail: closedFixer839R.detail }));
      const redischarged839R = runExpandClose({ ...opts839R, nodeId: 'm1' });
      assert(redischarged839R.result === 'ok',
        '#839R-ARC PIN B: the milestone RE-discharges after the recovery, got '
        + JSON.stringify({ result: redischarged839R.result, reason: redischarged839R.reason }));
      const finalProjection839R = loadOwnerProjection({ planPath, readFile: opts839R.readFile }, hash839R);
      assert(finalProjection839R.present === true
        && finalProjection839R.leafToMilestone['m1-r1-u1'] === 'm1'
        && finalProjection839R.leafToMilestone[fixer839R] === 'm1',
        '#839R-ARC PIN B: the projection the failed write dropped is recovered — after the '
        + 're-discharge it covers BOTH interiors, got ' + JSON.stringify(finalProjection839R.leafToMilestone));
      assert(readReviewJournal(opts839R, livePlan()).ok === true,
        '#839R-ARC PIN B: the journal is green on the far side of the whole recovered arc, got '
        + JSON.stringify(readReviewJournal(opts839R, livePlan())));
    }
  } finally { fs.rmSync(tmp839R, { recursive: true, force: true }); }
});

// ---------------------------------------------------------------------------
// #839R-CLASS — the classifier, direct-call, on the EXACT residue shape the failed projection write
// leaves behind: a committed `record(m1#2)` on a projection-COVERED point, its unit already in the
// execution node table, and NO `open(m1#2)` proof (Phase 2 refused before appending it). #839's
// `reExpansionWindowUnits` requires `expansionRecordOpened`, so this shape falls straight through to
// `tamper` — the class that names no route and misdirects the operator.
//
// The neighbouring tamper pins are re-stated over the SAME residue plan, so a fix that relaxes the
// opened-proof requirement cannot buy the relief by widening it: a forged owner and a residual
// divergence on a point carrying no un-discharged record must both stay `tamper`.
// ---------------------------------------------------------------------------
scenario(() => {
  assert(typeof routeMismatchDetail === 'function',
    '#839R-CLASS: the typed route-mismatch classifier is exported for direct pins');
  if (typeof routeMismatchDetail !== 'function') return;

  const RECORD1_839R = ['# Plan', '', '## Expansion Records', '',
    'record(m1#1):', '  point: m1', '  grain: g', '  path: p', '  join: j', '  probe: pr',
    '  serializer: none', '  unit: u1 | implementer | — | lib/composed.js | co_open | —', '',
    'open(m1#1):', '  at: T1', '',
    'discharge(m1):', '  at: T2', '  records: m1#1', ''].join('\n');
  // THE RESIDUE: the record + its ledger row committed, NO `open(m1#2)` proof — because the Phase-2
  // frontier open refused on the very journal this record invalidated.
  const RESIDUE_839R = RECORD1_839R + '\n' + ['record(m1#2):', '  point: m1', '  grain: g',
    '  path: p', '  join: j', '  probe: pr', '  serializer: none',
    '  unit: fx | implementer | — | lib/composed.js | co_open | —', ''].join('\n');
  assert(!planValidator.expansionRecordOpened(
    planValidator.parseExpansionRecords(RESIDUE_839R), 'm1#2'),
    '#839R-CLASS fixture: the residue record carries NO open() proof (that is the whole shape)');

  const execIds839R = new Set(['probe', 'm1', 'wall', 'done', 'm1-r1-u1', 'm1-r2-fx']);
  // The projection as the FAILED write left it: the first discharge's entry, and only that.
  const staleProjection839R = { present: true, leafToMilestone: { 'm1-r1-u1': 'm1' },
    points: new Set(['m1']) };

  const residueClass839R = routeMismatchDetail(
    [{ ownership_candidates: ['m1-r1-u1'], owning_node: 'm1-r1-u1' }],
    [{ ownership_candidates: ['m1-r1-u1', 'm1-r2-fx'], owning_node: null }],
    staleProjection839R, RESIDUE_839R, execIds839R);
  assert(residueClass839R.route_mismatch_class !== 'tamper',
    '#839R-CLASS: a committed-but-unopened re-expansion record on a projection-covered point is the '
    + 'run\'s OWN half-landed append — a failed projection write, not forgery. It must not classify '
    + 'tamper, got ' + JSON.stringify(residueClass839R));
  assert(residueClass839R.point === 'm1',
    '#839R-CLASS: the residue names the owning expansion point so the operator hint can route, got '
    + JSON.stringify(residueClass839R));
  assert(typeof residueClass839R.detail === 'string' && residueClass839R.detail.length > 0
    && (!/hand-edit/i.test(residueClass839R.detail) || /NEVER hand-edit/i.test(residueClass839R.detail)),
    '#839R-CLASS: the residue carries a route-bearing detail that never invites journal surgery, got '
    + JSON.stringify(residueClass839R.detail));
  const residueHint839R = getOperatorHint('review_journal_route_mismatch', residueClass839R);
  assert(typeof residueHint839R === 'string'
    && !/finish or discard runs that predate the current release/.test(residueHint839R),
    '#839R-CLASS: the operator hint stops telling a current-release run that it predates the current '
    + 'release, got ' + JSON.stringify(residueHint839R));

  // --- The tamper pins that must SURVIVE the relief, re-stated over the residue plan. ---
  const forged839R = routeMismatchDetail(
    [{ ownership_candidates: ['m1-r9-ghost'], owning_node: 'm1-r9-ghost' }], [],
    staleProjection839R, RESIDUE_839R, execIds839R);
  assert(forged839R.route_mismatch_class === 'tamper' && !forged839R.point,
    '#839R-CLASS: an owner in NEITHER the execution node table NOR the projection still refuses '
    + 'tamper-class while the residue sits on the same point, got ' + JSON.stringify(forged839R));
  const settled839R = routeMismatchDetail(
    [{ ownership_candidates: ['m1-r1-u1'], owning_node: 'm1-r1-u1' }], [],
    staleProjection839R, RECORD1_839R, new Set(['probe', 'm1', 'wall', 'done', 'm1-r1-u1']));
  assert(settled839R.route_mismatch_class === 'tamper',
    '#839R-CLASS: with NO un-discharged record on the point at all, a covered leaf with a residual '
    + 'divergence is still tamper — the relief turns on the record, never on coverage alone, got '
    + JSON.stringify(settled839R));
});

// #699 schema-2 code/security fanouts are one runtime review transaction, not
// independent sequence attempts. A replicated majority may carry one
// non-blocking dissent; blocker/fix veto and partitioned-all stay fail-closed.
scenario(() => {
  assert(typeof reduceLogicalReviewAttempt === 'function',
    '#699 logical review reducer is exported for exact aggregation regression coverage');
  if (typeof reduceLogicalReviewAttempt === 'function') {
    const reducerNodes = [
      { id: 'review-a', role: 'code-reviewer', dependsOn: ['writer'],
        shape: { kind: 'fanout', group: 'replicas' }, gateAggregation: 'replicated_majority' },
      { id: 'review-b', role: 'code-reviewer', dependsOn: ['writer'],
        shape: { kind: 'fanout', group: 'replicas' }, gateAggregation: 'replicated_majority' },
      { id: 'review-c', role: 'code-reviewer', dependsOn: ['writer'],
        shape: { kind: 'fanout', group: 'replicas' }, gateAggregation: 'replicated_majority' },
    ];
    const gate = canonicalLogicalGateIdentity({ kind: 'fanout', id: 'replicas',
      origin: ['writer'], members: reducerNodes.map(node => node.id) });
    const receipt = (id, verdict, extra = '') => ({ node_id: id,
      body: `evidence-binding: ${id} nonce-${id}\nverdict: ${verdict}\nfindings_blocking: 0\n${extra}` });
    const majority = reduceLogicalReviewAttempt(reducerNodes, gate, [
      receipt('review-a', 'pass'), receipt('review-b', 'pass'), receipt('review-c', 'fail'),
    ]);
    assert(majority.complete === true && majority.pass === true,
      '#699 replicated-majority reducer accepts one non-blocking dissent');
    const veto = reduceLogicalReviewAttempt(reducerNodes, gate, [
      receipt('review-a', 'pass'), receipt('review-b', 'pass'),
      receipt('review-c', 'pass', 'finding: id=R1 scope=in_scope action=fix status=open severity=high file=x.js fix_role=tdd-guide\n'),
    ]);
    assert(veto.complete === true && veto.pass === false && veto.blocker_veto === true,
      '#699 replicated-majority reducer cannot outvote an unresolved in-scope fix');
    const partitions = reducerNodes.map((node, index) => ({ ...node,
      gateAggregation: 'partitioned_all', gateSurface: 'partition-' + index }));
    const partitioned = reduceLogicalReviewAttempt(partitions, gate, [
      receipt('review-a', 'pass'), receipt('review-b', 'pass'), receipt('review-c', 'fail'),
    ]);
    assert(partitioned.complete === true && partitioned.pass === false,
      '#699 partitioned-all reducer requires every exact member approval');
    const legacyAdversarial = reducerNodes.map(node => ({ ...node,
      role: 'adversarial-verifier', gateAggregation: '' }));
    const legacyMajority = reduceLogicalReviewAttempt(legacyAdversarial, gate, [
      receipt('review-a', 'pass'), receipt('review-b', 'pass'),
      { node_id: 'review-c', body: 'evidence-binding: review-c nonce-review-c\nverdict: fail\nfindings_blocking: 1\n' },
    ]);
    assert(legacyMajority.complete === true && legacyMajority.pass === true,
      '#699 code/security blocker veto does not tighten verified legacy AV majority semantics');
  }

  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-schema2-review-majority-'));
  try {
    const project = 'issue-699-majority';
    const projectDir = path.join(tmp, 'kaola-workflow', project);
    const cacheDir = path.join(projectDir, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    const rows = [
      '| writer | tdd-guide | — | product.js | 1 | sequence | standard | — | — | — | — |',
      '| review-a | code-reviewer | writer | — | 1 | fanout(replicas) | reasoning | candidate approved | full candidate | replicated_majority | — |',
      '| review-b | code-reviewer | writer | — | 1 | fanout(replicas) | reasoning | candidate approved | full candidate | replicated_majority | — |',
      '| review-c | code-reviewer | writer | — | 1 | fanout(replicas) | reasoning | candidate approved | full candidate | replicated_majority | — |',
      '| finalize | finalize | review-a,review-b,review-c | — | 1 | sequence | — | — | — | — | — |',
    ];
    const body = [
      '# Workflow Plan', '', '## Meta', 'project: ' + project, 'plan_schema_version: 2',
      'epoch_schema_version: 2', '', '## Nodes', '',
      '| id | role | depends_on | declared_write_set | cardinality | shape | model | gate_claim | gate_surface | gate_aggregation | certifies |',
      '| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |', ...rows,
      '', '## Node Ledger', '', '| id | status |', '| --- | --- |',
      '| writer | complete |', '| review-a | in_progress |', '| review-b | in_progress |',
      '| review-c | pending |', '| finalize | pending |', '',
    ].join('\n');
    const hash = planValidator.computePlanHash(body);
    const planPath = path.join(projectDir, 'workflow-plan.md');
    fs.writeFileSync(planPath, '<!-- plan_hash: ' + hash + ' -->\n' + body);
    const votes = { 'review-a': 'pass', 'review-b': 'pass', 'review-c': 'fail' };
    for (const [index, id] of ['review-a', 'review-b'].entries()) {
      const base = String(index + 1).repeat(40);
      fs.writeFileSync(path.join(cacheDir, 'barrier-base-' + id), base + '\n');
      fs.writeFileSync(path.join(cacheDir, id + '.md'),
        `evidence-binding: ${id} ${base.slice(0, 12)}\nverdict: ${votes[id]}\nfindings_blocking: 0\n`);
    }
    fs.writeFileSync(path.join(cacheDir, 'running-set.json'), JSON.stringify({ state: 'open', nodes:
      ['review-a', 'review-b'].map(id => ({ id, role: 'code-reviewer', kind: 'read' })) }));
    const writerIdentity = { baseline: 'a'.repeat(40), anchored_ref: 'a'.repeat(40),
      open_token: 'writer-open', generation: 'a'.repeat(12),
      ref: 'refs/kaola-workflow/barrier/' + project + '/writer' };
    const reservedC = '3'.repeat(40);
    const reservedRefs = new Map();
    const droppedReservations = [];
    const shell = (_script, args) => {
      if (args.includes('--resume-check')) return { exitCode: 0, ok: true, result: 'ok' };
      const nodeIdIndex = args.indexOf('--node-id');
      const nodeId = nodeIdIndex >= 0 ? args[nodeIdIndex + 1] : null;
      if (args.includes('--record-base')) {
        const basePath = path.join(cacheDir, 'barrier-base-' + nodeId);
        const openPath = path.join(cacheDir, 'barrier-open-' + nodeId);
        if (!fs.existsSync(basePath)) {
          fs.writeFileSync(basePath, reservedC + '\n');
          fs.writeFileSync(openPath, 'head-at-reservation\n');
          reservedRefs.set(nodeId, reservedC);
        }
        return { exitCode: 0, result: 'ok', nodeId, base: fs.readFileSync(basePath, 'utf8').trim() };
      }
      if (args.includes('--drop-base')) {
        droppedReservations.push(nodeId);
        for (const name of ['barrier-base-', 'barrier-open-']) {
          try { fs.unlinkSync(path.join(cacheDir, name + nodeId)); } catch (_) {}
        }
        reservedRefs.delete(nodeId);
        return { exitCode: 0, result: 'ok', nodeId };
      }
      if (args.includes('--start')) {
        const base = fs.readFileSync(path.join(cacheDir, 'barrier-base-' + nodeId), 'utf8').trim();
        return { exitCode: 0, result: 'ok', ok: true, recordBase: { result: 'ok', nodeId, base, reused: true } };
      }
      return { exitCode: 0, result: 'ok', ok: true, overallOk: true, allDone: false,
        readyPending: [{ id: 'review-c', role: 'code-reviewer', model: 'reasoning',
          declared_write_set: '—', dependsOn: ['writer'] }],
        selectorCheck: { isSelector: false, ok: true } };
    };
    const common = { planPath, project, shell,
      readFile: p => fs.readFileSync(p, 'utf8'), writeFile: (p, value) => fs.writeFileSync(p, value),
      cacheExists: p => fs.existsSync(p), unlink: p => fs.unlinkSync(p), readdir: p => fs.readdirSync(p),
      mkdirp: p => fs.mkdirSync(p, { recursive: true }),
      resolveBarrierRef: (_ref, id) => reservedRefs.get(id) || '',
      computeReviewCandidateDigest: () => 'd'.repeat(64),
      captureWriterBarrierIdentity: id => id === 'writer' ? writerIdentity : null };
    let crashedAfterReservation = false;
    try {
      runCloseNode({ ...common, nodeId: 'review-a', shell: (script, args) => {
        const result = shell(script, args);
        if (args.includes('--record-base') && args.includes('review-c')) {
          throw new Error('simulated_crash_after_review_generation_reservation');
        }
        return result;
      } });
    } catch (err) {
      crashedAfterReservation = String(err && err.message)
        .includes('simulated_crash_after_review_generation_reservation');
    }
    assert(crashedAfterReservation
      && !fs.existsSync(path.join(cacheDir, 'review-attempts.json'))
      && fs.existsSync(path.join(cacheDir, 'barrier-base-review-c'))
      && fs.existsSync(path.join(cacheDir, 'barrier-open-review-c'))
      && reservedRefs.get('review-c') === reservedC,
    '#699 crash after a pending-member reservation leaves no partial journal and retryable full identity');
    let crashedAfterJournal = false;
    try { runCloseNode({ ...common, nodeId: 'review-a', reviewFailpoint: 'attempt_written' }); }
    catch (err) { crashedAfterJournal = String(err && err.message).includes('review_failpoint:attempt_written'); }
    const journalCrashRead = readReviewJournal(common, fs.readFileSync(planPath, 'utf8'));
    assert(crashedAfterJournal && journalCrashRead.ok === true
      && readLedgerStatuses(fs.readFileSync(planPath, 'utf8'))['review-a'] === 'in_progress'
      && journalCrashRead.journal.attempts[0].receipts.length === 1,
    '#699 crash after journal write rereads validly and leaves the receipt-bearing close retryable');
    const first = runCloseNode({ ...common, nodeId: 'review-a' });
    const afterFirstPlan = fs.readFileSync(planPath, 'utf8');
    const afterFirstRead = readReviewJournal(common, afterFirstPlan);
    const afterFirstStatuses = readLedgerStatuses(afterFirstPlan);
    assert(first.provisional === true && afterFirstRead.ok === true
      && afterFirstRead.journal.attempts[0].generations.every(row => row.nonce)
      && afterFirstStatuses['review-a'] === 'complete'
      && afterFirstStatuses['review-b'] === 'in_progress'
      && afterFirstStatuses['review-c'] === 'pending',
    '#699 rolling fanout reserves every exact generation and rereads after a provisional close: '
      + JSON.stringify({ first, afterFirstRead }));
    assert(fs.existsSync(path.join(cacheDir, 'barrier-base-review-c'))
      && fs.existsSync(path.join(cacheDir, 'barrier-open-review-c'))
      && reservedRefs.get('review-c') === reservedC,
    '#699 pending-member reservation owns the base, anchored ref, and freshness token as one identity');
    const reconciled = runReconcileRunningSet(common);
    assert(reconciled.result === 'ok' && !droppedReservations.includes('review-c')
      && fs.existsSync(path.join(cacheDir, 'barrier-base-review-c'))
      && fs.existsSync(path.join(cacheDir, 'barrier-open-review-c')),
    '#699 reconcile preserves the journal-owned pending generation instead of orphan-sweeping it');
    const oriented = runOrient({ ...common, statePath: path.join(projectDir, 'workflow-state.md') });
    assert(oriented.result === 'ok' && oriented.reviewTopUp
      && oriented.reviewTopUp.pending_members.join(',') === 'review-c',
    '#699 orient exposes the bounded provisional-fanout top-up instead of dead-ending on the journal fence');
    const planBeforeDrift = fs.readFileSync(planPath, 'utf8');
    const runningBeforeDrift = fs.readFileSync(path.join(cacheDir, 'running-set.json'), 'utf8');
    const drifted = runOpenReady({ ...common, fanoutCapReadonly: 2,
      computeReviewCandidateDigest: () => 'e'.repeat(64) });
    assert(drifted.reason === 'review_candidate_changed'
      && fs.readFileSync(planPath, 'utf8') === planBeforeDrift
      && fs.readFileSync(path.join(cacheDir, 'running-set.json'), 'utf8') === runningBeforeDrift
      && !fs.existsSync(path.join(cacheDir, 'review-c.md')),
    '#699 candidate drift refuses top-up before ledger, running-set, or evidence mutation');
    let crashedAfterOpeningManifest = false;
    try {
      runOpenReady({ ...common, fanoutCapReadonly: 2, writeFile: (file, value) => {
        fs.writeFileSync(file, value);
        if (file === path.join(cacheDir, 'running-set.json')
            && JSON.parse(value).state === 'opening') {
          throw new Error('simulated_crash_after_review_topup_opening_manifest');
        }
      } });
    } catch (err) {
      crashedAfterOpeningManifest = String(err && err.message)
        .includes('simulated_crash_after_review_topup_opening_manifest');
    }
    const recoveredTopUp = runReconcileRunningSet(common);
    assert(crashedAfterOpeningManifest && recoveredTopUp.result === 'ok'
      && (recoveredTopUp.rolledBack || []).includes('review-c')
      && !droppedReservations.includes('review-c')
      && fs.existsSync(path.join(cacheDir, 'barrier-base-review-c'))
      && fs.existsSync(path.join(cacheDir, 'barrier-open-review-c'))
      && reservedRefs.get('review-c') === reservedC,
    '#699 opening-manifest crash rollback preserves the journal-owned generation identity for retry');
    const topUp = runOpenReady({ ...common, fanoutCapReadonly: 2 });
    const openedC = (topUp.opened || []).find(node => node.id === 'review-c');
    assert(topUp.result === 'ok' && openedC && openedC.nonce === reservedC.slice(0, 12)
      && readLedgerStatuses(fs.readFileSync(planPath, 'utf8'))['review-c'] === 'in_progress',
    '#699 unresolved provisional fanout permits only its reserved missing member to top up');
    fs.writeFileSync(path.join(cacheDir, 'review-c.md'),
      `evidence-binding: review-c ${reservedC.slice(0, 12)}\nverdict: ${votes['review-c']}\nfindings_blocking: 0\n`);
    const second = runCloseNode({ ...common, nodeId: 'review-b' });
    const afterSecondRead = readReviewJournal(common, fs.readFileSync(planPath, 'utf8'));
    assert(second.provisional === true && afterSecondRead.ok === true
      && afterSecondRead.journal.attempts[0].receipts.length === 2,
    '#699 rolling fanout rereads after the second provisional close');
    const third = runCloseNode({ ...common, nodeId: 'review-c' });
    const plan = fs.readFileSync(planPath, 'utf8');
    const reread = readReviewJournal(common, plan);
    const statuses = readLedgerStatuses(plan);
    const attempts = reread.ok ? reread.journal.attempts : [];
    assert(first.provisional === true && second.provisional === true && third.result === 'ok'
      && attempts.length === 1 && attempts[0].receipts.length === 3
      && attempts[0].outcome === 'pass' && attempts[0].lifecycle_settled === true,
    '#699 real close-node lifecycle reduces 2 pass + 1 nonblocking dissent as one settled attempt: '
      + JSON.stringify({ first, second, third, reread }));
    assert(reread.ok === true && reviewJournalBlocker(reread.journal) === null
      && ['review-a', 'review-b', 'review-c'].every(id => statuses[id] === 'complete'),
    '#699 legal replicated-majority dissent rereads without repair blocker and leaves all members complete');
  } finally { fs.rmSync(tmp, { recursive: true, force: true }); }
});

// A schema-1 review journal that merely CARRIES a legacy_import key — with NO committed replan-transaction
// backing it — is a FORGED cross-epoch child. Bare key presence is not provenance: it must never route a
// schema-2 review close onto the schema-1 (V2-binding-free) path. readReviewJournal fails closed with the
// typed transaction-invalid reason, and the close refuses instead of dropping the V2 review_context/
// candidate_digest/profile binding.
scenario(() => {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-forged-legacy-import-'));
  try {
    const project = 'issue-forged';
    const projectDir = path.join(tmp, 'kaola-workflow', project);
    const cacheDir = path.join(projectDir, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    const rows = [
      '| writer | tdd-guide | — | product.js | 1 | sequence | standard | — | — | — | — |',
      '| review-a | code-reviewer | writer | — | 1 | sequence | reasoning | candidate approved | full candidate | sequence | — |',
      '| finalize | finalize | review-a | — | 1 | sequence | — | — | — | — | — |',
    ];
    const body = [
      '# Workflow Plan', '', '## Meta', 'project: ' + project, 'plan_schema_version: 2',
      'epoch_schema_version: 2', '', '## Nodes', '',
      '| id | role | depends_on | declared_write_set | cardinality | shape | model | gate_claim | gate_surface | gate_aggregation | certifies |',
      '| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |', ...rows,
      '', '## Node Ledger', '', '| id | status |', '| --- | --- |',
      '| writer | complete |', '| review-a | in_progress |', '| finalize | pending |', '',
    ].join('\n');
    const hash = planValidator.computePlanHash(body);
    const planPath = path.join(projectDir, 'workflow-plan.md');
    fs.writeFileSync(planPath, '<!-- plan_hash: ' + hash + ' -->\n' + body);
    // FORGED journal: schema_version 1, correct plan_hash, empty attempts, a bare attacker-controlled
    // legacy_import key, and NO replan-transaction.json anywhere under .cache/.
    fs.writeFileSync(path.join(cacheDir, 'review-attempts.json'),
      JSON.stringify({ schema_version: 1, plan_hash: hash, attempts: [],
        legacy_import: { forged: true, whatever: 'attacker-controlled' } }, null, 2) + '\n');
    fs.writeFileSync(path.join(cacheDir, 'barrier-base-review-a'), 'a'.repeat(40) + '\n');
    fs.writeFileSync(path.join(cacheDir, 'review-a.md'),
      'evidence-binding: review-a ' + 'a'.repeat(12) + '\nverdict: pass\nfindings_blocking: 0\n');
    fs.writeFileSync(path.join(cacheDir, 'running-set.json'), JSON.stringify({ state: 'open',
      nodes: [{ id: 'review-a', role: 'code-reviewer', kind: 'read' }] }));
    const common = { planPath, project,
      shell: (_script, args) => args.includes('--resume-check')
        ? { exitCode: 0, ok: true, result: 'ok' }
        : { exitCode: 0, result: 'ok', ok: true, overallOk: true, selectorCheck: { isSelector: false, ok: true } },
      readFile: p => fs.readFileSync(p, 'utf8'), writeFile: (p, value) => fs.writeFileSync(p, value),
      cacheExists: p => fs.existsSync(p), unlink: p => fs.unlinkSync(p), readdir: p => fs.readdirSync(p),
      computeReviewCandidateDigest: () => 'd'.repeat(64),
      captureWriterBarrierIdentity: id => id === 'writer' ? { baseline: 'a'.repeat(40),
        anchored_ref: 'a'.repeat(40), open_token: 'w', generation: 'a'.repeat(12),
        ref: 'refs/kaola-workflow/barrier/' + project + '/writer' } : null };
    const forgedRead = readReviewJournal(common, fs.readFileSync(planPath, 'utf8'));
    assert(forgedRead.ok === false
      && forgedRead.reason === 'review_journal_legacy_import_transaction_invalid',
    'a bare legacy_import key with no committed replan-transaction fails the journal read closed');
    const forgedClose = runCloseNode({ ...common, nodeId: 'review-a' });
    assert(forgedClose.result === 'refuse' && forgedClose.provisional !== true
      && forgedClose.reason === 'review_context_mismatch',
    'a forged legacy_import journal cannot route a schema-2 review close onto the schema-1 path');
  } finally { fs.rmSync(tmp, { recursive: true, force: true }); }
});

// REPAIR-DIGEST-DRIFT: exclude only this run's control tree and .kw bookkeeping.
scenario(() => {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-review-digest-'));
  try {
    fs.mkdirSync(path.join(tmp, 'kaola-workflow', 'issue-682'), { recursive: true });
    fs.mkdirSync(path.join(tmp, 'kaola-workflow', 'other-project'), { recursive: true });
    fs.mkdirSync(path.join(tmp, '.kw'), { recursive: true });
    fs.writeFileSync(path.join(tmp, 'code.js'), 'one\n');
    fs.writeFileSync(path.join(tmp, 'kaola-workflow', 'issue-682', 'workflow-state.md'), 'active-one\n');
    fs.writeFileSync(path.join(tmp, 'kaola-workflow', 'other-project', 'state.md'), 'other-one\n');
    fs.writeFileSync(path.join(tmp, '.gitignore'), '.kw/\n');
    G.exec(tmp, ['init'], { stdio: 'ignore' });
    G.exec(tmp, ['config', 'user.email', 'kw@test']);
    G.exec(tmp, ['config', 'user.name', 'kw']);
    G.exec(tmp, ['add', '-A']);
    G.exec(tmp, ['commit', '-m', 'base'], { stdio: 'ignore' });
    // #683: the candidate is now a TRIPLE (whole-tree digest + declared blob map + residue digest). The
    // whole-tree `digest` field keeps its exact pre-#683 meaning and is what these assertions pin.
    const declaredUnion683 = new Set(['code.js']);
    const cand683 = () => computeReviewCandidateDigest('', 'issue-682', tmp, declaredUnion683);
    const base = cand683().digest;
    const baseResidue = cand683().residue_digest;
    fs.writeFileSync(path.join(tmp, 'kaola-workflow', 'issue-682', 'workflow-state.md'), 'active-two\n');
    fs.writeFileSync(path.join(tmp, '.kw', 'bookkeeping'), 'changed\n');
    assert(cand683().digest === base,
      'REPAIR-DIGEST-DRIFT: active control state and .kw bookkeeping are excluded');
    fs.writeFileSync(path.join(tmp, 'code.js'), 'two\n');
    assert(cand683().digest !== base,
      'REPAIR-DIGEST-DRIFT: product code drift changes candidate digest');
    // #683 P1/P2 partition: a DECLARED path's drift moves the declared blob map but NOT the residue.
    assert(cand683().declared['code.js'] && cand683().residue_digest === baseResidue,
      'REPAIR-TRIPLE: a declared-path edit moves candidate_declared and leaves the residue byte-equal');
    fs.writeFileSync(path.join(tmp, 'code.js'), 'one\n');
    fs.writeFileSync(path.join(tmp, 'kaola-workflow', 'other-project', 'state.md'), 'other-two\n');
    assert(cand683().digest !== base,
      'REPAIR-DIGEST-DRIFT: another workflow project remains candidate-relevant');
    // #683 P1: an UNDECLARED path's drift moves the residue digest — the rogue-edit detector.
    assert(cand683().residue_digest !== baseResidue,
      'REPAIR-TRIPLE: an undeclared-path edit moves candidate_residue_digest (the rogue-edit detector)');
  } finally { fs.rmSync(tmp, { recursive: true, force: true }); }
});

// FANOUT-PROVISIONAL-LAST: non-last votes stay provisional; only the last member settles the group.
scenario(() => {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-review-fanout-'));
  try {
    const projectDir = path.join(tmp, 'kaola-workflow', 'issue-682');
    const cacheDir = path.join(projectDir, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    const body = makePlan([
      '| writer | complete | |', '| skeptic-a | in_progress | |', '| skeptic-b | in_progress | |',
      '| finalize | pending | |',
    ], [
      '| writer | tdd-guide | — | scripts/a.js | 1 | sequence |',
      '| skeptic-a | adversarial-verifier | writer | — | 1 | fanout(red-team) |',
      '| skeptic-b | adversarial-verifier | writer | — | 1 | fanout(red-team) |',
      '| finalize | finalize | skeptic-a, skeptic-b | — | 1 | sequence |',
    ]);
    const hash = planValidator.computePlanHash(body);
    const planPath = path.join(projectDir, 'workflow-plan.md');
    fs.writeFileSync(planPath, '<!-- plan_hash: ' + hash + ' -->\n' + body);
    fs.writeFileSync(path.join(cacheDir, 'barrier-base-skeptic-a'), 'aaaaaaaaaaaa-rest\n');
    fs.writeFileSync(path.join(cacheDir, 'barrier-base-skeptic-b'), 'bbbbbbbbbbbb-rest\n');
    fs.writeFileSync(path.join(cacheDir, 'skeptic-a.md'),
      'evidence-binding: skeptic-a aaaaaaaaaaaa\nverdict: pass\nfindings_blocking: 0\n');
    fs.writeFileSync(path.join(cacheDir, 'skeptic-b.md'),
      'evidence-binding: skeptic-b bbbbbbbbbbbb\nverdict: fail\nfindings_blocking: 1\n');
    fs.writeFileSync(path.join(cacheDir, 'running-set.json'), JSON.stringify({ state: 'open', nodes: [
      { id: 'skeptic-a', role: 'adversarial-verifier', kind: 'read' },
      { id: 'skeptic-b', role: 'adversarial-verifier', kind: 'read' },
    ] }, null, 2));
    const opts = id => ({
      planPath, project: 'issue-682', nodeId: id,
      shell: (_p, args) => args.includes('--resume-check')
        ? ({ exitCode: 0, ok: true, result: 'ok' }) : ({ exitCode: 0, result: 'ok', allDone: false, readyPending: [] }),
      readFile: p => fs.readFileSync(p, 'utf8'), writeFile: (p, c) => fs.writeFileSync(p, c),
      cacheExists: p => fs.existsSync(p), unlink: p => fs.unlinkSync(p),
      computeReviewCandidateDigest: () => 'e'.repeat(64),
      captureWriterBarrierIdentity: () => ({ baseline: '1'.repeat(40), anchored_ref: '1'.repeat(40),
        open_token: '2'.repeat(40), generation: '1'.repeat(12),
        ref: 'refs/kaola-workflow/barrier/issue-682/writer' }),
    });
    const first = runCloseNode(opts('skeptic-a'));
    if (!fs.existsSync(path.join(cacheDir, 'review-attempts.json'))) {
      throw new Error('fanout first close did not create journal: ' + JSON.stringify(first));
    }
    let journal = JSON.parse(fs.readFileSync(path.join(cacheDir, 'review-attempts.json'), 'utf8'));
    assert(first.result === 'ok' && first.provisional === true && journal.attempts[0].outcome === null
      && journal.attempts[0].lifecycle_settled === false,
      'FANOUT-PROVISIONAL-LAST: non-last vote closes provisionally without certifying successors');
    let crashedAtOutcome = false;
    try { runCloseNode({ ...opts('skeptic-b'), reviewFailpoint: 'outcome_written' }); }
    catch (err) { crashedAtOutcome = String(err && err.message).includes('review_failpoint:outcome_written'); }
    journal = JSON.parse(fs.readFileSync(path.join(cacheDir, 'review-attempts.json'), 'utf8'));
    assert(crashedAtOutcome && journal.attempts[0].outcome === 'fail'
      && journal.attempts[0].lifecycle_settled === false,
      'FANOUT-CRASH-RETRY: aggregate outcome is durable before a simulated process crash');
    const beforeCorrection = fs.readFileSync(path.join(cacheDir, 'skeptic-b.md'), 'utf8');
    const corrected = runRecordEvidence({ ...opts('skeptic-b'), mkdirp: () => {},
      stdinContent: 'evidence-binding: skeptic-b bbbbbbbbbbbb\nverdict: pass\nfindings_blocking: 0\n' });
    assert(corrected.reason === 'review_outcome_receipts_immutable'
      && fs.readFileSync(path.join(cacheDir, 'skeptic-b.md'), 'utf8') === beforeCorrection,
      'R14-FAIL-TO-PASS-RED: post-outcome current receipt replacement refuses with zero evidence mutation');
    const journalPath = path.join(cacheDir, 'review-attempts.json');
    const runningPath = path.join(cacheDir, 'running-set.json');
    const directJournalBefore = fs.readFileSync(journalPath, 'utf8');
    const directPlanBefore = fs.readFileSync(planPath, 'utf8');
    const directRunningBefore = fs.readFileSync(runningPath, 'utf8');
    fs.writeFileSync(path.join(cacheDir, 'skeptic-b.md'),
      'evidence-binding: skeptic-b bbbbbbbbbbbb\nverdict: pass\nfindings_blocking: 0\n');
    const directReplacement = runCloseNode(opts('skeptic-b'));
    const directNoMutation = fs.readFileSync(journalPath, 'utf8') === directJournalBefore
      && fs.readFileSync(planPath, 'utf8') === directPlanBefore
      && fs.existsSync(runningPath) && fs.readFileSync(runningPath, 'utf8') === directRunningBefore;
    fs.writeFileSync(journalPath, directJournalBefore);
    fs.writeFileSync(planPath, directPlanBefore);
    fs.writeFileSync(runningPath, directRunningBefore);
    fs.writeFileSync(path.join(cacheDir, 'skeptic-b.md'), beforeCorrection);
    assert(directReplacement.reason === 'review_outcome_receipts_immutable' && directNoMutation,
      'R15-DIRECT-FAIL-TO-PASS-RED: direct evidence write after fail outcome refuses before journal/ledger/running mutation');
    let crashedAfterFold = false;
    try { runCloseNode({ ...opts('skeptic-b'), reviewFailpoint: 'plan_folded' }); }
    catch (err) { crashedAfterFold = String(err && err.message).includes('review_failpoint:plan_folded'); }
    assert(crashedAfterFold && readLedgerStatuses(fs.readFileSync(planPath, 'utf8'))['skeptic-a'] === 'pending',
      'FANOUT-CRASH-RETRY: a crash after the plan fold leaves a retryable durable fail outcome');
    let crashedAfterRunning = false;
    try { runCloseNode({ ...opts('skeptic-b'), reviewFailpoint: 'running_removed' }); }
    catch (err) { crashedAfterRunning = String(err && err.message).includes('review_failpoint:running_removed'); }
    assert(crashedAfterRunning && !fs.existsSync(path.join(cacheDir, 'running-set.json')),
      'FANOUT-CRASH-RETRY: a crash after running-set removal remains retryable');
    const second = runCloseNode(opts('skeptic-b'));
    journal = JSON.parse(fs.readFileSync(path.join(cacheDir, 'review-attempts.json'), 'utf8'));
    assert(second.result === 'review_failed' && journal.attempts.length === 1
      && journal.attempts[0].outcome === 'fail' && journal.attempts[0].receipts.length === 2
      && validateReviewJournal(journal, hash).ok === true,
      'FANOUT-PROVISIONAL-LAST: last member rereads both receipts and a tie refutes one logical-group attempt');
    assert(readLedgerStatuses(fs.readFileSync(planPath, 'utf8'))['skeptic-a'] === 'pending'
      && readLedgerStatuses(fs.readFileSync(planPath, 'utf8'))['skeptic-b'] === 'pending',
      'FANOUT-PROVISIONAL-LAST: refutation returns the exact resolved group to pending');
    const late = runRecordEvidence({ ...opts('skeptic-a'), stdinContent: 'verdict: pass\n', mkdirp: () => {} });
    assert(late.reason === 'evidence_generation_stale',
      'FANOUT-PROVISIONAL-LAST: late evidence for a non-current generation is refused');
  } finally { fs.rmSync(tmp, { recursive: true, force: true }); }
});

// R16: a fan-out failure is already committed when settled_written is durable. Both public close
// commands must replay that terminal result after the group has returned to pending, without writes.
// R25: a non-last fan-out member closes provisionally, but it is still a completed node and must
// receive the same compliance, timing, and provenance bookkeeping as an ordinary close. The
// bookkeeping is replay-safe when a process crashes immediately after the plan/compliance write.
scenario(() => {
for (const closeKind of ['close-node', 'close-and-open-next']) {
for (const crashAfterPlanWrite of [false, true]) {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-review-provisional-bookkeeping-'));
  try {
    const projectDir = path.join(tmp, 'kaola-workflow', 'issue-r25');
    const cacheDir = path.join(projectDir, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    const body = makePlan([
      '| writer | complete | |', '| skeptic-a | in_progress | |',
      '| skeptic-b | in_progress | |', '| finalize | pending | |',
    ], [
      '| writer | tdd-guide | — | scripts/a.js | 1 | sequence |',
      '| skeptic-a | adversarial-verifier | writer | — | 1 | fanout(red-team) |',
      '| skeptic-b | adversarial-verifier | writer | — | 1 | fanout(red-team) |',
      '| finalize | finalize | skeptic-a, skeptic-b | — | 1 | sequence |',
    ]);
    const hash = planValidator.computePlanHash(body);
    const planPath = path.join(projectDir, 'workflow-plan.md');
    const statePath = path.join(projectDir, 'workflow-state.md');
    const runningPath = path.join(cacheDir, 'running-set.json');
    const timingPath = path.join(cacheDir, 'node-timings.jsonl');
    const provenancePath = path.join(cacheDir, 'provenance-log.jsonl');
    fs.writeFileSync(planPath, '<!-- plan_hash: ' + hash + ' -->\n' + body);
    fs.writeFileSync(statePath, '# State\n');
    fs.writeFileSync(path.join(cacheDir, 'barrier-base-skeptic-a'), 'aaaaaaaaaaaa-rest\n');
    fs.writeFileSync(path.join(cacheDir, 'barrier-base-skeptic-b'), 'bbbbbbbbbbbb-rest\n');
    fs.writeFileSync(path.join(cacheDir, 'skeptic-a.md'),
      'evidence-binding: skeptic-a aaaaaaaaaaaa\nverdict: pass\nfindings_blocking: 0\n');
    fs.writeFileSync(path.join(cacheDir, 'skeptic-b.md'),
      'evidence-binding: skeptic-b bbbbbbbbbbbb\nverdict: pass\nfindings_blocking: 0\n');
    fs.writeFileSync(runningPath, JSON.stringify({ state: 'open', nodes: [
      { id: 'skeptic-a', role: 'adversarial-verifier', kind: 'read' },
      { id: 'skeptic-b', role: 'adversarial-verifier', kind: 'read' },
    ] }, null, 2));
    fs.writeFileSync(timingPath,
      JSON.stringify({ node: 'skeptic-a', event: 'opened', ts: new Date().toISOString() }) + '\n'
      + JSON.stringify({ node: 'skeptic-b', event: 'opened', ts: new Date().toISOString() }) + '\n');
    const shell = (_scriptPath, args) => args.includes('--resume-check')
      ? ({ exitCode: 0, ok: true, result: 'ok' })
      : ({ exitCode: 0, result: 'ok', allDone: false, readyPending: [], readySet: [] });
    let crashArmed = crashAfterPlanWrite;
    const writeFile = (p, c) => {
      fs.writeFileSync(p, c);
      if (crashArmed && p === planPath && c.includes('| skeptic-a | complete |')) {
        crashArmed = false;
        throw new Error('simulated_crash_after_provisional_plan_write');
      }
    };
    const common = { planPath, statePath, project: 'issue-r25', nodeId: 'skeptic-a', shell,
      readFile: p => fs.readFileSync(p, 'utf8'), writeFile, cacheExists: p => fs.existsSync(p),
      unlink: p => fs.unlinkSync(p), computeReviewCandidateDigest: () => '9'.repeat(64),
      captureWriterBarrierIdentity: () => ({ baseline: '1'.repeat(40), anchored_ref: '1'.repeat(40),
        open_token: '2'.repeat(40), generation: '1'.repeat(12),
        ref: 'refs/kaola-workflow/barrier/issue-r25/writer' }) };
    const closeFn = closeKind === 'close-node' ? runCloseNode : runCloseAndOpenNext;
    let crashed = false;
    let first;
    try { first = closeFn(common); }
    catch (err) { crashed = String(err && err.message).includes('simulated_crash_after_provisional_plan_write'); }
    const retry = closeFn(common);
    const retryAgain = closeFn(common);
    const finalPlan = fs.readFileSync(planPath, 'utf8');
    // #833: the retried close must write NO compliance row at all — the anti-duplicate guard this
    // pin was built around (`complianceRowExists`) is gone because the row is gone. What replaces
    // it is stronger: the DERIVED table has exactly one row for the node no matter how many times
    // the close is replayed, because the row set IS the node set.
    const complianceRows = finalPlan.split('\n')
      .filter(line => line.includes('| adversarial-verifier (skeptic-a) |'));
    const derivedRows = planValidator.deriveAgentCompliance(finalPlan).rows
      .filter(row => row.node_id === 'skeptic-a');
    const timings = fs.readFileSync(timingPath, 'utf8').trim().split('\n').map(line => JSON.parse(line));
    const provenance = fs.existsSync(provenancePath)
      ? fs.readFileSync(provenancePath, 'utf8').trim().split('\n').filter(Boolean).map(line => JSON.parse(line)) : [];
    assert((crashAfterPlanWrite ? crashed : first && first.provisional === true)
      && retry.provisional === true && retryAgain.provisional === true,
    'R25-PROVISIONAL-BOOKKEEPING-RED: ' + closeKind + ' ' + (crashAfterPlanWrite ? 'crash retry' : 'ordinary retry')
      + ' preserves the provisional close result');
    assert(complianceRows.length === 0 && derivedRows.length === 1
      && timings.filter(e => e.node === 'skeptic-a' && e.event === 'closed').length === 1
      && provenance.filter(e => e.nodeId === 'skeptic-a' && e.event === 'close'
        && e.nonce === 'aaaaaaaaaaaa').length === 1,
    'R25-PROVISIONAL-BOOKKEEPING-RED: ' + closeKind + ' ' + (crashAfterPlanWrite ? 'crash retry' : 'ordinary retry')
      + ' writes NO compliance row (derives exactly one) and records exactly one close timing and '
      + 'generation-bound provenance entry');
  } finally { fs.rmSync(tmp, { recursive: true, force: true }); }
}
}
});

