// Issue 682 RED: the review transaction's pure policy must be shared by every close path.
// These tests intentionally precede runtime integration so a missing helper is a genuine pre-impl RED.
scenario(() => {
  assert(typeof evaluateEffectiveVerdict === 'function',
    'REV-PREDICATE-PARITY: schema exports the canonical effective-verdict helper');
  if (typeof evaluateEffectiveVerdict === 'function') {
    const cases = [
      ['verdict: pass\n', true, null],
      ['verdict: fail\nfindings_blocking: 0\n', false, 'verdict_not_pass'],
      ['verdict: pass\nfindings_blocking: 2\n', false, 'blocking_findings'],
      ['verdict: pass\nfindings_blocking: 0\nfinding: id=F-1 scope=in_scope action=fix status=open\n', false, 'unresolved_in_scope_fix'],
    ];
    for (const [receipt, pass, reason] of cases) {
      const actual = evaluateEffectiveVerdict(receipt);
      assert(actual.pass === pass && actual.reason === reason,
        'REV-PREDICATE-PARITY: receipt evaluates canonically: ' + JSON.stringify({ actual, pass, reason }));
    }
  }

  assert(typeof canonicalLogicalGateIdentity === 'function',
    'STATE-BOUNDARY: schema exports canonical logical-gate identity');
  if (typeof canonicalLogicalGateIdentity === 'function') {
    const a = canonicalLogicalGateIdentity({ kind: 'fanout', id: 'reusable', origin: ['review'], members: ['b', 'a'] });
    const b = canonicalLogicalGateIdentity({ kind: 'fanout', id: 'renamed', origin: ['review'], members: ['a', 'b'] });
    assert(a.key === b.key && a.id !== b.id,
      'FANOUT-PROVISIONAL-LAST: identity uses resolved origin + sorted members, not reusable label');
  }

  assert(typeof validateReviewJournal === 'function',
    'STATE-BOUNDARY: schema exports fail-closed review-journal validation');
  if (typeof validateReviewJournal === 'function') {
    const hash = 'a'.repeat(64);
    assert(validateReviewJournal({ schema_version: 1, plan_hash: hash, attempts: [] }, hash).ok === true,
      'STATE-BOUNDARY: empty v1 journal for current plan is valid');
    for (const journal of [
      null,
      { schema_version: 2, plan_hash: hash, attempts: [] },
      { schema_version: 1, plan_hash: 'b'.repeat(64), attempts: [] },
      { schema_version: 1, plan_hash: hash, attempts: [{ attempt_id: 'x:1' }, { attempt_id: 'x:1' }] },
    ]) {
      assert(validateReviewJournal(journal, hash).ok === false,
        'STATE-BOUNDARY: malformed/version/hash/duplicate journal fails closed: ' + JSON.stringify(journal));
    }
  }
});

// #658: explicit cardinality-1 adversarial fan-outs use their frozen node ids as the
// authoritative receipt identities.  Membership is scoped to (fanout label, origin),
// never to a role-prefix glob shared by the whole project.
scenario(() => {
  const verdictPlan = makePlan([
    '| impl | complete | |', '| review | complete | |',
    '| skeptic-a | complete | |', '| skeptic-b | complete | |',
    '| other-skeptic | complete | |', '| finalize | complete | |',
  ], [
    '| impl | tdd-guide | — | scripts/a.js | 1 | sequence |',
    '| review | code-reviewer | impl | — | 1 | sequence |',
    '| skeptic-a | adversarial-verifier | review | — | 1 | fanout(red-team) |',
    '| skeptic-b | adversarial-verifier | review | — | 1 | fanout(red-team) |',
    '| other-skeptic | adversarial-verifier | impl | — | 1 | fanout(red-team) |',
    '| finalize | finalize | skeptic-a, skeptic-b, other-skeptic | — | 1 | sequence |',
  ]);
  const fresh = {
    'barrier-base-skeptic-a': 'aaaaaaaaaaaa9999\n',
    'barrier-base-skeptic-b': 'bbbbbbbbbbbb9999\n',
    'barrier-base-other-skeptic': 'cccccccccccc9999\n',
    'skeptic-a.md': 'evidence-binding: skeptic-a aaaaaaaaaaaa\nverdict: pass\n',
    'skeptic-b.md': 'evidence-binding: skeptic-b bbbbbbbbbbbb\nverdict: pass\n',
    'other-skeptic.md': 'evidence-binding: other-skeptic cccccccccccc\nverdict: fail\nfindings_blocking: 1\n',
    'adversarial-verifier-bridge.md': 'verdict: fail\nfindings_blocking: 1\n',
  };
  const check = files => planValidator.verifyVerdictBlock(verdictPlan, {
    nodeId: 'skeptic-a', readCache: f => Object.prototype.hasOwnProperty.call(files, f) ? files[f] : null,
    globCache: prefix => Object.keys(files).filter(f => f.startsWith(prefix) && f.endsWith('.md')),
  });
  let r = check(fresh);
  assert(r.ok === true && JSON.stringify(r.members) === JSON.stringify(['skeptic-a', 'skeptic-b']),
    '#658 exact group: independent same-label/different-origin receipt and legacy bridge never enter tally, got ' + JSON.stringify(r));

  const missing = Object.assign({}, fresh); delete missing['skeptic-b.md'];
  r = check(missing);
  assert(r.ok === false && /missing|absent/.test(r.reason), '#658 missing canonical member refuses structurally, got ' + JSON.stringify(r));

  const foreign = Object.assign({}, fresh, { 'skeptic-b.md': 'evidence-binding: foreign bbbbbbbbbbbb\nverdict: pass\n' });
  r = check(foreign);
  assert(r.ok === false && /foreign|binding/.test(r.reason), '#658 foreign member binding refuses structurally, got ' + JSON.stringify(r));

  const duplicate = Object.assign({}, fresh, { 'skeptic-b.md': 'evidence-binding: skeptic-a bbbbbbbbbbbb\nverdict: pass\n' });
  r = check(duplicate);
  assert(r.ok === false && /duplicate|binding/.test(r.reason), '#658 duplicate member injection refuses structurally, got ' + JSON.stringify(r));

  const stale = Object.assign({}, fresh, { 'skeptic-b.md': 'evidence-binding: skeptic-b stale0000000\nverdict: pass\n' });
  r = check(stale);
  assert(r.ok === false && /stale|binding/.test(r.reason), '#658 stale member nonce refuses structurally, got ' + JSON.stringify(r));

  const tied = Object.assign({}, fresh, { 'skeptic-a.md': 'evidence-binding: skeptic-a aaaaaaaaaaaa\nverdict: fail\nfindings_blocking: 1\n' });
  r = check(tied);
  assert(r.ok === false && /1\/2/.test(r.reason), '#658 one-pass/one-fail tie remains refuted, got ' + JSON.stringify(r));

  const singletonPlan = verdictPlan.replace('| skeptic-b | adversarial-verifier | review | — | 1 | fanout(red-team) |', '| skeptic-b | adversarial-verifier | impl | — | 1 | fanout(red-team) |');
  r = planValidator.verifyVerdictBlock(singletonPlan, { nodeId: 'skeptic-a', readCache: f => fresh[f] || null, globCache: () => [] });
  assert(r.ok === true && JSON.stringify(r.members) === JSON.stringify(['skeptic-a']),
    '#658 cardinality-1 singleton control preserves precise group identity, got ' + JSON.stringify(r));

  const legacyPlan = makePlan(['| impl | complete | |', '| av | complete | |', '| finalize | complete | |'], [
    '| impl | tdd-guide | — | scripts/a.js | 1 | sequence |',
    '| av | adversarial-verifier | impl | — | 3 | fanout(legacy) |',
    '| finalize | finalize | av | — | 1 | sequence |',
  ]);
  r = planValidator.verifyVerdictBlock(legacyPlan, { nodeId: 'av',
    readCache: f => ({ 'adversarial-verifier-0.md': 'verdict: pass\n', 'adversarial-verifier-1.md': 'verdict: pass\n' })[f] || null,
    globCache: p => p === 'adversarial-verifier-' ? ['adversarial-verifier-0.md', 'adversarial-verifier-1.md'] : [],
  });
  assert(r.ok === true, '#658 archived cardinality>1 role-prefix receipts remain read-only compatible, got ' + JSON.stringify(r));

  const ambiguousLegacyPlan = makePlan([
    '| impl | complete | |', '| av-red | complete | |', '| av-blue | complete | |', '| finalize | complete | |',
  ], [
    '| impl | tdd-guide | — | scripts/a.js | 1 | sequence |',
    '| av-red | adversarial-verifier | impl | — | 3 | fanout(red) |',
    '| av-blue | adversarial-verifier | impl | — | 3 | fanout(blue) |',
    '| finalize | finalize | av-red, av-blue | — | 1 | sequence |',
  ]);
  const pooledLegacy = {
    'adversarial-verifier-red-0.md': 'verdict: fail\nfindings_blocking: 1\n',
    'adversarial-verifier-red-1.md': 'verdict: fail\nfindings_blocking: 1\n',
    'adversarial-verifier-red-2.md': 'verdict: pass\nfindings_blocking: 0\n',
    'adversarial-verifier-blue-0.md': 'verdict: pass\nfindings_blocking: 0\n',
    'adversarial-verifier-blue-1.md': 'verdict: pass\nfindings_blocking: 0\n',
    'adversarial-verifier-blue-2.md': 'verdict: pass\nfindings_blocking: 0\n',
  };
  const ambiguousOpts = {
    readCache: f => pooledLegacy[f] || null,
    globCache: p => p === 'adversarial-verifier-' ? Object.keys(pooledLegacy) : [],
  };
  r = planValidator.verifyVerdictBlock(ambiguousLegacyPlan, Object.assign({ nodeId: 'av-red' }, ambiguousOpts));
  assert(r.ok === false && /legacy.*ambiguous|multiple legacy/i.test(r.reason || ''),
    'R1 per-node legacy multi-group receipts must fail closed before global pooling, got ' + JSON.stringify(r));
  r = planValidator.verifyVerdictBlock(ambiguousLegacyPlan, ambiguousOpts);
  assert(r.ok === false && r.failures && r.failures.some(f => /legacy.*ambiguous|multiple legacy/i.test(f.reason || '')),
    'R1 whole-plan legacy multi-group receipts must fail closed before global pooling, got ' + JSON.stringify(r));
});

// #649: write populated fixture evidence to the same authoritative cache path the runtime resolves.
// A live isolated write member owns its leg-local copy; every other node owns the parent cache copy.
// Token lines are generated from the production registry so future evidence-contract tightening cannot
// leave real-git fixtures writing a hollow tracked seed or a stale bare token.
function writeLegAwareEvidence(cacheDir, id, role, extraLines) {
  const baseFile = path.join(cacheDir, 'barrier-base-' + String(id).replace(/[^A-Za-z0-9_-]/g, '_'));
  let nonce = '';
  try { nonce = fs.readFileSync(baseFile, 'utf8').trim().slice(0, 12); } catch (_) { nonce = ''; }

  const lines = ['evidence-binding: ' + id + ' ' + nonce];
  for (const tokenClass of (ROLE_TOKEN_REGISTRY[role] || []).filter(t => t !== 'evidence-binding')) {
    const token = tokenClass.split('|')[0];
    if (token === 'RED') lines.push('RED: fixture fails before implementation');
    // The test author's fail-on-baseline RECEIPT: it must name THIS open's recorded baseline, so
    // the fixture echoes the nonce (its 12-char prefix) rather than a constant.
    else if (token === 'red_baseline') lines.push('red_baseline: ' + nonce);
    else if (token === 'GREEN') lines.push('GREEN: fixture passes after implementation');
    else if (token === 'verdict') lines.push('verdict: pass');
    else if (token === 'findings_blocking') lines.push('findings_blocking: 0');
    else lines.push(token + ': fixture');
  }
  if (role === 'main-session-gate') lines.push('instrumentation: none');
  if (extraLines) lines.push(...extraLines);

  let evidencePath = path.join(cacheDir, id + '.md');
  let running = null;
  try { running = JSON.parse(fs.readFileSync(path.join(cacheDir, 'running-set.json'), 'utf8')); } catch (_) {}
  const leg = running && running.lane_group && running.lane_group.legs
    ? running.lane_group.legs[id]
    : null;
  if (leg && leg.legPath) {
    const root = G.exec(cacheDir, ['rev-parse', '--show-toplevel'], { encoding: 'utf8' }).trim();
    evidencePath = path.join(leg.legPath,
      path.relative(fs.realpathSync(root), fs.realpathSync(cacheDir)), id + '.md');
  }
  fs.mkdirSync(path.dirname(evidencePath), { recursive: true });
  fs.writeFileSync(evidencePath, lines.join('\n') + '\n');
  return evidencePath;
}

// #542 (D-542-01): in-process unit calls (runOpenReady / runCloseNode) read
// parallelWritesDefaultOn(process.env) directly. Co-open is DEFAULT-ON; the only deterministic
// serial-single-open path is KAOLA_PARALLEL_WRITES=0. This helper forces that env around an
// in-process call and always restores the prior value (subprocess runNode tests pass the env
// through extraEnv instead).
function withParallelWrites(value, fn) {
  const saved = process.env.KAOLA_PARALLEL_WRITES;
  if (value === undefined) delete process.env.KAOLA_PARALLEL_WRITES;
  else process.env.KAOLA_PARALLEL_WRITES = value;
  try {
    return fn();
  } finally {
    if (saved === undefined) delete process.env.KAOLA_PARALLEL_WRITES;
    else process.env.KAOLA_PARALLEL_WRITES = saved;
  }
}

// ---------------------------------------------------------------------------
// Helpers: plan builders
// ---------------------------------------------------------------------------

function makePlan(ledgerRows, extraNodes) {
  const defaultNodes = [
    '| impl-core | tdd-guide | — | scripts/adaptive-node.js | 1 | sequence |',
    '| impl-other | implementer | impl-core | scripts/other.js | 1 | sequence |',
    '| review | code-reviewer | impl-other | — | 1 | sequence |',
    '| finalize | finalize | review | CHANGELOG.md | 1 | sequence |',
  ];
  const nodes = extraNodes || defaultNodes;
  return [
    '# Workflow Plan — test-project',
    '',
    '## Meta',
    'plan_form: spine', // #765: all-concrete spine — the legacy dag grammar is retired at the freeze wall
    'labels: area:scripts',
    '',
    '## Nodes',
    '',
    '| id | role | depends_on | declared_write_set | cardinality | shape |',
    '| --- | --- | --- | --- | --- | --- |',
    ...nodes,
    '',
    '## Design',
    '',
    'Decompose the frozen spine into its concrete role nodes; each sequence edge is a real data dependency (S1 — the downstream node consumes the upstream node\'s change). Done means the review gate clears and validation passes.',
    '',
    '## Node Ledger',
    '',
    '| id | status | notes |',
    '| --- | --- | --- |',
    ...ledgerRows,
    '',
  ].join('\n') + '\n';
}

function makeWaitPlan(ledgerRows, nodes) {
  return [
    '# Workflow Plan — wait-budget-test', '', '## Meta', 'plan_form: spine', 'labels: area:scripts', '',
    '## Nodes', '',
    '| id | role | depends_on | declared_write_set | cardinality | shape | model | wait_budget_minutes |',
    '| --- | --- | --- | --- | --- | --- | --- | --- |',
    ...nodes, '', '## Node Ledger', '', '| id | status | notes |', '| --- | --- | --- |',
    ...ledgerRows, '',
  ].join('\n') + '\n';
}

function authoredNext(content) {
  const out = computeNextAction(content, { resolveModel: role => ({
    'code-reviewer': 'opus', 'adversarial-verifier': 'opus', 'tdd-guide': 'sonnet', implementer: 'sonnet',
  })[role] || 'sonnet' });
  return { exitCode: out.result === 'refuse' ? 1 : 0, ...out };
}

function legacyFreezeUnknownWait(cell, role = 'implementer', model = 'standard', metaExtra = []) {
  const content = [
    '# Legacy frozen plan', '', '## Meta', 'labels: enhancement', ...metaExtra, '', '## Nodes', '',
    '| id | role | depends_on | declared_write_set | cardinality | shape | model | wait_budget_minutes |',
    '| --- | --- | --- | --- | --- | --- | --- | --- |',
    `| work | ${role} | — | ${role === 'code-reviewer' ? '—' : 'src/x.js'} | 1 | sequence | ${model} | ${cell} |`,
    '| done | finalize | work | — | 1 | sequence | — | — |', '',
    '## Node Ledger', '', '| id | status |', '| --- | --- |', '| work | pending |', '| done | pending |', '',
  ].join('\n');
  return '<!-- plan_hash: ' + planValidator.computePlanHash(content) + ' -->\n' + content;
}

function makeState(opts) {
  opts = opts || {};
  const lines = [
    '# Kaola-Workflow State',
    '',
    '## Project',
    'name: test-project',
    'status: active',
    '',
    '## Current Position',
    'phase: adaptive',
    'next_command: /kaola-workflow-plan-run test-project',
    '',
    '## Last Evidence',
    'phase_file: N/A',
    'last_command: claim',
    '',
  ];
  if (opts.escalated) {
    lines.push('escalated_to_full: ' + opts.escalated);
    lines.push('');
  }
  lines.push('## Sink');
  lines.push('issue_number: 42');
  lines.push('branch: workflow/test-project');
  return lines.join('\n') + '\n';
}

// ---------------------------------------------------------------------------
// T1: spliceLedgerNode — pending → in_progress (basic open path)
// ---------------------------------------------------------------------------
scenario(() => {
  const plan = makePlan([
    '| impl-core | pending | |',
    '| impl-other | pending | |',
  ]);

  const r = spliceLedgerNode(plan, 'impl-core', 'in_progress', { allowFrom: ['pending'] });
  assert(r.found === true, 'T1: found===true for existing node');
  assert(r.changed === true, 'T1: changed===true when status flipped');
  assert(r.alreadyAtTarget === false, 'T1: alreadyAtTarget===false (not already in_progress)');
  assert(r.content.includes('| impl-core | in_progress | |'), 'T1: ledger row updated to in_progress');
  assert(r.content.includes('| impl-other | pending | |'), 'T1: sibling row unmodified');
});

// ---------------------------------------------------------------------------
// T2: spliceLedgerNode — idempotent (already at target status)
// ---------------------------------------------------------------------------
scenario(() => {
  const plan = makePlan([
    '| impl-core | in_progress | |',
    '| impl-other | pending | |',
  ]);

  const r = spliceLedgerNode(plan, 'impl-core', 'in_progress', { allowFrom: ['pending', 'in_progress'] });
  assert(r.found === true, 'T2: found===true');
  assert(r.alreadyAtTarget === true, 'T2: alreadyAtTarget===true when already in_progress');
  assert(r.changed === false, 'T2: changed===false on idempotent');
  assert(r.content === plan, 'T2: content byte-identical on no-op');
});

// ---------------------------------------------------------------------------
// T3: spliceLedgerNode — refuse out-of-allowFrom (node is complete, only pending allowed)
// ---------------------------------------------------------------------------
scenario(() => {
  const plan = makePlan([
    '| impl-core | complete | |',
    '| impl-other | pending | |',
  ]);

  const r = spliceLedgerNode(plan, 'impl-core', 'in_progress', { allowFrom: ['pending'] });
  assert(r.found === true, 'T3: found===true for complete node');
  assert(r.changed === false, 'T3: changed===false — complete ∉ allowFrom(pending)');
  assert(r.alreadyAtTarget === false, 'T3: alreadyAtTarget===false (target is in_progress, not complete)');
  assert(r.content === plan, 'T3: content unmodified — refuse to touch out-of-allowFrom');
});

// ---------------------------------------------------------------------------
// T4: spliceLedgerNode — in_progress → complete (close path)
// ---------------------------------------------------------------------------
scenario(() => {
  const plan = makePlan([
    '| impl-core | in_progress | |',
    '| impl-other | pending | |',
  ]);

  const r = spliceLedgerNode(plan, 'impl-core', 'complete', { allowFrom: ['in_progress'] });
  assert(r.found === true, 'T4: found===true');
  assert(r.changed === true, 'T4: changed===true on close path');
  assert(r.content.includes('| impl-core | complete | |'), 'T4: row updated to complete');
  assert(r.content.includes('| impl-other | pending | |'), 'T4: sibling unmodified');
});

// ---------------------------------------------------------------------------
// T5: spliceLedgerNode — node not found
// ---------------------------------------------------------------------------
scenario(() => {
  const plan = makePlan([
    '| impl-core | pending | |',
  ]);

  const r = spliceLedgerNode(plan, 'nonexistent-node', 'in_progress', { allowFrom: ['pending'] });
  assert(r.found === false, 'T5: found===false for absent node');
  assert(r.changed === false, 'T5: changed===false when not found');
});

// ---------------------------------------------------------------------------
// T6 (#354): UPSTREAM-FENCED `## Node Ledger` decoy — the single fence-aware locateSection makes
// every reader/writer target the REAL ledger, not a fenced decoy heading appearing earlier in the
// file (strengthens beyond the existing decoy-outside / fenced-inside walkthrough scenarios, which
// did not cover an upstream-fenced HEADING). Mutation-style: a fence-blind indexOf would target the
// decoy and either mis-flip nothing or corrupt the fenced block.
scenario(() => {
  // A plan whose ## Nodes section contains a FENCED markdown example that itself has a
  // `## Node Ledger` heading + `consent_halt: pending` line — upstream of the REAL ledger.
  const decoyPlan = [
    '# Plan',
    '## Meta',
    'plan_hash: x',
    '## Nodes',
    '| id | role | depends_on | declared_write_set | est | shape |',
    '|----|------|-----------|--------------------|-----|-------|',
    '| impl-core | tdd-guide | — | scripts/x.js | 1 | sequence |',
    '',
    'Example (illustrative, fenced — NOT the real ledger):',
    '```markdown',
    '## Node Ledger',
    '| id | status |',
    '| impl-core | complete |',
    'consent_halt: pending',
    '```',
    '## Node Ledger',
    '| id | status |',
    '|----|--------|',
    '| impl-core | pending |',
    '## Required Agent Compliance',
    '',
    '| Requirement | Status | Evidence | Skip Reason |',
    '|-------------|--------|----------|-------------|',
    '',
  ].join('\n');

  // locateSection finds the REAL ledger (after the fence), not the decoy inside it.
  const loc = locateSection(decoyPlan, 'Node Ledger');
  assert(loc.start >= 0, 'T6: locateSection finds a ledger');
  assert(decoyPlan.slice(loc.start, loc.next).includes('| impl-core | pending |'),
    'T6: locateSection targets the REAL ledger (pending), not the fenced decoy (complete)');
  assert(!decoyPlan.slice(loc.start, loc.next).includes('```'),
    'T6: the located section excludes the fenced decoy block');

  // readLedgerStatuses reads the REAL row (pending), ignoring the fenced decoy (complete).
  const statuses = readLedgerStatuses(decoyPlan);
  assert(statuses['impl-core'] === 'pending',
    'T6: readLedgerStatuses reads the REAL row (pending), not the fenced decoy (complete), got ' + statuses['impl-core']);

  // spliceLedgerNode flips the REAL row; the fenced decoy is untouched.
  const flip = spliceLedgerNode(decoyPlan, 'impl-core', 'in_progress', { allowFrom: ['pending'] });
  assert(flip.changed === true && flip.found === true, 'T6: spliceLedgerNode flips the real row');
  assert(/```markdown[\s\S]*\| impl-core \| complete \|[\s\S]*```/.test(flip.content),
    'T6: the fenced decoy block is left byte-intact (still shows complete)');
  assert(readLedgerStatuses(flip.content)['impl-core'] === 'in_progress',
    'T6: after flip, the REAL ledger row is in_progress');

  // readDurableConsentHalt is NOT fooled by the fenced `consent_halt: pending` decoy (real ledger has none).
  assert(readDurableConsentHalt(decoyPlan) === false,
    'T6: readDurableConsentHalt ignores the fenced-decoy consent_halt (real ledger has none)');

  // #833: adaptive-node's spliceComplianceRow wrapper is gone with the rest of the compliance
  // writers; the fence-awareness property it proved belongs to the KERNEL helper it delegated to,
  // which is retained as the archive-time renderer's row producer. Pin it there.
  const withRow = spliceComplianceSection(decoyPlan, '| code-reviewer | subagent-invoked | ok | |');
  assert(withRow.includes('| code-reviewer | subagent-invoked | ok | |'),
    'T6: spliceComplianceSection appended the row');
  // exactly one real compliance heading (the fenced decoy has none here); row lands after the real ledger.
  assert(withRow.indexOf('| code-reviewer | subagent-invoked | ok | |') > withRow.lastIndexOf('```'),
    'T6: the compliance row lands in the REAL section (after the fenced decoy)');
});

// ---------------------------------------------------------------------------
// T6c (#665): locateSection's fence closer was FAMILY-ONLY (no run-length / empty-suffix check), so
// a SHORTER same-family fence nested inside a LONGER one closed it early, exposing a fenced decoy
// heading as "unfenced". Reproduces the exact plan: a 5-backtick `## Node Briefs` fence enclosing a
// single stray 3-backtick line, then a fenced `## Node Ledger` DECOY — driven END-TO-END through
// open -> splice -> close -> resume, proving there is no hash-mismatch wedge.
// ---------------------------------------------------------------------------
scenario(() => {
  // Direct unit check: locateSection must agree with classifier.sectionBody (ground truth) on
  // which `## Node Ledger` is genuine, once the run-length-aware closer is applied.
  const classifier = require('./kaola-workflow-classifier');
  const decoyPlan665 = [
    '# Workflow Plan — test-project', '',
    '## Meta', 'labels: area:scripts', 'sink: CHANGELOG.md', '',
    '## Nodes', '',
    '| id | role | depends_on | declared_write_set | cardinality | shape |',
    '| --- | --- | --- | --- | --- | --- |',
    '| impl-core | tdd-guide | — | scripts/x.js | 1 | sequence |',
    '| review | code-reviewer | impl-core | — | 1 | sequence |',
    '| finalize | finalize | review | — | 1 | sequence |',
    '',
    '## Node Briefs', '',
    '### impl-core',
    'Illustrative fenced example (NOT the real ledger):',
    '`````',
    'Some brief text with a stray triple-backtick marker below:',
    '```',
    '## Node Ledger',
    '| id | status |',
    '| --- | --- |',
    '| impl-core | pending |',
    '`````',
    '',
    '## Node Ledger', '',
    '| id | status |',
    '| --- | --- |',
    '| impl-core | pending |',
    '| review | pending |',
    '| finalize | pending |',
    '',
  ].join('\n') + '\n';

  const loc665 = locateSection(decoyPlan665, 'Node Ledger');
  assert(loc665.start >= 0, 'T6c: locateSection finds a ledger despite the run-length decoy');
  const sliced665 = decoyPlan665.slice(loc665.start, loc665.next >= 0 ? loc665.next : decoyPlan665.length);
  const groundTruth665 = classifier.sectionBodyState(decoyPlan665, 'Node Ledger');
  assert(groundTruth665.status === 'present', 'T6c: classifier ground truth finds the genuine ledger present');
  assert(sliced665.replace(/^\n## Node Ledger\n/, '') === groundTruth665.body,
    'T6c: locateSection agrees with classifier.sectionBody on the genuine (not decoy) ledger body, got ' + JSON.stringify(sliced665));
  assert(!sliced665.includes('`````') && !sliced665.includes('Illustrative fenced example'),
    'T6c: the located section excludes the 5-backtick decoy block entirely (a shorter interior fence no longer closes it early)');

  // End-to-end: real subprocess open -> splice -> close -> resume proves no hash-mismatch wedge.
  const { execFileSync: exec665, spawnSync: spawn665 } = require('child_process');
  const planValidator665 = require('./kaola-workflow-plan-validator');
  const NODE_CLI_665 = path.join(__dirname, 'kaola-workflow-adaptive-node.js');
  const VALIDATOR_665 = path.join(__dirname, 'kaola-workflow-plan-validator.js');
  const hash665 = planValidator665.computePlanHash(decoyPlan665);
  const frozen665 = '<!-- plan_hash: ' + hash665 + ' -->\n' + decoyPlan665;

  const repoRoot665 = fs.mkdtempSync(path.join(os.tmpdir(), 'd665-fence-'));
  const project665 = 'test-project';
  const projDir665 = path.join(repoRoot665, 'kaola-workflow', project665);
  fs.mkdirSync(path.join(projDir665, '.cache'), { recursive: true });
  const planPath665 = path.join(projDir665, 'workflow-plan.md');
  fs.writeFileSync(planPath665, frozen665);
  fs.writeFileSync(path.join(projDir665, 'workflow-state.md'), '# State\n');
  const g665 = (a) => exec665('git', ['-C', repoRoot665, ...a], { encoding: 'utf8', stdio: ['ignore', 'ignore', 'ignore'] });
  g665(['init']); g665(['config', 'user.email', 'kw@test']); g665(['config', 'user.name', 'kw']); g665(['config', 'commit.gpgsign', 'false']);
  fs.writeFileSync(path.join(repoRoot665, '.gitignore'), '.kw/\n');
  g665(['add', '-A']); g665(['commit', '-m', 'init']);

  const run665 = (args) => {
    let out = {}; let exit = 0;
    // The per-scenario vehicle for the adaptive-node CLI. Every scenario drives it as a CHAIN:
    // one process writes the ledger row, the barrier baseline and the .cache evidence and EXITS,
    // and the next re-derives the whole run state from those bytes with no shared heap.
    // spawn-class: durable-handoff
    try { out = JSON.parse(exec665('node', args, { cwd: repoRoot665, encoding: 'utf8' }).trim().split('\n').pop()); }
    catch (err) { exit = (err.status == null) ? 1 : err.status; try { out = JSON.parse(String(err.stdout || '').trim().split('\n').pop()); } catch (_) {} }
    return { out, exit };
  };

  // Control: the hand-frozen plan resume-checks clean before anything opens.
  let r665 = run665([VALIDATOR_665, planPath665, '--resume-check', '--json']);
  assert(r665.exit === 0 && r665.out.ok === true, 'T6c: control — the frozen decoy plan passes --resume-check, got ' + JSON.stringify(r665.out));

  // open: the real open-next opens impl-core (the sole ready node).
  r665 = run665([NODE_CLI_665, 'open-next', '--project', project665, '--json']);
  assert(r665.out.result === 'ok' && r665.out.opened && r665.out.opened.id === 'impl-core',
    'T6c: open-next opens impl-core, got ' + JSON.stringify(r665.out));
  const implCoreNonce665 = r665.out.nonce;

  // splice + resume: opening flips the ledger status via the (now fixed) locateSection; the write
  // must land OUTSIDE the hash-covered ## Node Briefs body, so --resume-check still passes.
  r665 = run665([VALIDATOR_665, planPath665, '--resume-check', '--json']);
  assert(r665.exit === 0 && r665.out.ok === true,
    'T6c: after open, --resume-check still passes — no plan_hash_mismatch wedge from a mis-targeted splice, got ' + JSON.stringify(r665.out));

  // close: record the test author's baseline-bound RED evidence for impl-core, then
  // close-and-open-next opens review.
  // record-evidence writes .cache/impl-core.md and EXITS; the close-and-open-next process
  // below re-reads those exact bytes with no shared heap.
  // spawn-class: durable-handoff
  const rec665 = spawn665(process.execPath, [NODE_CLI_665, 'record-evidence', '--project', project665, '--node-id', 'impl-core', '--stdin', '--json'], {
    cwd: repoRoot665, encoding: 'utf8', input: 'evidence-binding: impl-core ' + implCoreNonce665
      + '\nRED: impl-core failed before implementation\nred_baseline: ' + implCoreNonce665 + '\n',
  });
  assert(rec665.status === 0, 'T6c: impl-core evidence records: ' + rec665.stderr + rec665.stdout);
  r665 = run665([NODE_CLI_665, 'close-and-open-next', '--project', project665, '--node-id', 'impl-core', '--json']);
  assert(r665.out.result === 'ok' && r665.out.opened && r665.out.opened.id === 'review',
    'T6c: close-and-open-next closes impl-core and opens review, got ' + JSON.stringify(r665.out));

  // resume: the plan still resume-checks clean after the close-time splice too.
  r665 = run665([VALIDATOR_665, planPath665, '--resume-check', '--json']);
  assert(r665.exit === 0 && r665.out.ok === true,
    'T6c: after close, --resume-check still passes — sustained stability across open+close, got ' + JSON.stringify(r665.out));

  // The GENUINE ledger reflects both transitions; the decoy inside ## Node Briefs is never the target.
  const finalContent665 = fs.readFileSync(planPath665, 'utf8');
  const finalLedger665 = classifier.sectionBody(finalContent665, 'Node Ledger');
  assert(finalLedger665.includes('| impl-core | complete |') && finalLedger665.includes('| review | in_progress |'),
    'T6c: the genuine ledger shows impl-core complete / review in_progress, got ' + JSON.stringify(finalLedger665));

  try { fs.rmSync(repoRoot665, { recursive: true, force: true }); } catch (_) {}
});

// ---------------------------------------------------------------------------
// T6d (#670): CommonMark fence-detection PARITY — locateSection's fence regex/closer check ran on
// `ln.trim()`, so a 4-SPACE-INDENTED backtick run (an INDENTED CODE BLOCK per CommonMark, never a
// fence) was misread as a fence CLOSER (trim strips the indent). The oracle classifier
// (markdownFenceTransition, kaola-workflow-classifier.js) anchors `^\s{0,3}(...)` on the RAW line —
// 4+ spaces disqualifies a fence marker. Reproduces: a 0-indent opener, a 4-space-indented pseudo-
// closer (closes the fence early under the buggy `ln.trim()` code, keeps it open under the fixed
// raw-line anchor), a fenced `## Node Ledger` DECOY, a genuine 0-indent closer, then the GENUINE
// (truly unfenced) `## Node Ledger`. Driven END-TO-END through open -> resume, proving no
// plan_hash_mismatch wedge.
// ---------------------------------------------------------------------------
scenario(() => {
  // Direct unit check: locateSection must agree with classifier.sectionBodyState (ground truth) on
  // which `## Node Ledger` is genuine, once the RAW-LINE fence anchor is applied.
  const classifier = require('./kaola-workflow-classifier');
  const decoyPlan670 = [
    '# Workflow Plan — test-project', '',
    '## Meta', 'labels: area:scripts', 'sink: CHANGELOG.md', '',
    '## Nodes', '',
    '| id | role | depends_on | declared_write_set | cardinality | shape |',
    '| --- | --- | --- | --- | --- | --- |',
    '| impl-core | tdd-guide | — | scripts/x.js | 1 | sequence |',
    '| review | code-reviewer | impl-core | — | 1 | sequence |',
    '| finalize | finalize | review | — | 1 | sequence |',
    '',
    '## Node Briefs', '',
    '### impl-core',
    'Illustrative fenced example (NOT the real ledger):',
    '```',
    'Some brief text with an indented pseudo-closer below (NOT a real fence marker —',
    '4-space indent makes it an indented code block per CommonMark):',
    '    ```',
    '## Node Ledger',
    '| id | status |',
    '| --- | --- |',
    '| impl-core | pending |',
    '```',
    '',
    '## Node Ledger', '',
    '| id | status |',
    '| --- | --- |',
    '| impl-core | pending |',
    '| review | pending |',
    '| finalize | pending |',
    '',
  ].join('\n') + '\n';

  const loc670 = locateSection(decoyPlan670, 'Node Ledger');
  assert(loc670.start >= 0, 'T6d: locateSection finds a ledger despite the indented pseudo-closer');
  const sliced670 = decoyPlan670.slice(loc670.start, loc670.next >= 0 ? loc670.next : decoyPlan670.length);
  const groundTruth670 = classifier.sectionBodyState(decoyPlan670, 'Node Ledger');
  assert(groundTruth670.status === 'present', 'T6d: classifier ground truth finds the genuine ledger present');
  assert(sliced670.replace(/^\n## Node Ledger\n/, '') === groundTruth670.body,
    'T6d: locateSection agrees with classifier.sectionBodyState on the genuine (not decoy) ledger body, got ' + JSON.stringify(sliced670));
  assert(sliced670.includes('| review | pending |') && sliced670.includes('| finalize | pending |'),
    'T6d: sanity — the genuine slice does carry the real review/finalize rows, got ' + JSON.stringify(sliced670));
  assert(!sliced670.includes('Illustrative fenced example'),
    'T6d: the located section excludes the fenced ## Node Briefs decoy block entirely (a 4-space-indented line no longer closes the fence early)');

  // End-to-end: real subprocess open -> resume proves no hash-mismatch wedge (the write must land
  // on the GENUINE ledger, outside the hash-covered ## Node Briefs body).
  const { execFileSync: exec670, spawnSync: spawn670 } = require('child_process');
  const planValidator670 = require('./kaola-workflow-plan-validator');
  const NODE_CLI_670 = path.join(__dirname, 'kaola-workflow-adaptive-node.js');
  const VALIDATOR_670 = path.join(__dirname, 'kaola-workflow-plan-validator.js');
  const hash670 = planValidator670.computePlanHash(decoyPlan670);
  const frozen670 = '<!-- plan_hash: ' + hash670 + ' -->\n' + decoyPlan670;

  const repoRoot670 = fs.mkdtempSync(path.join(os.tmpdir(), 'd670-fence-'));
  const project670 = 'test-project';
  const projDir670 = path.join(repoRoot670, 'kaola-workflow', project670);
  fs.mkdirSync(path.join(projDir670, '.cache'), { recursive: true });
  const planPath670 = path.join(projDir670, 'workflow-plan.md');
  fs.writeFileSync(planPath670, frozen670);
  fs.writeFileSync(path.join(projDir670, 'workflow-state.md'), '# State\n');
  const g670 = (a) => exec670('git', ['-C', repoRoot670, ...a], { encoding: 'utf8', stdio: ['ignore', 'ignore', 'ignore'] });
  g670(['init']); g670(['config', 'user.email', 'kw@test']); g670(['config', 'user.name', 'kw']); g670(['config', 'commit.gpgsign', 'false']);
  fs.writeFileSync(path.join(repoRoot670, '.gitignore'), '.kw/\n');
  g670(['add', '-A']); g670(['commit', '-m', 'init']);

  const run670 = (args) => {
    let out = {}; let exit = 0;
    // The per-scenario vehicle for the adaptive-node CLI. Every scenario drives it as a CHAIN:
    // one process writes the ledger row, the barrier baseline and the .cache evidence and EXITS,
    // and the next re-derives the whole run state from those bytes with no shared heap.
    // spawn-class: durable-handoff
    try { out = JSON.parse(exec670('node', args, { cwd: repoRoot670, encoding: 'utf8' }).trim().split('\n').pop()); }
    catch (err) { exit = (err.status == null) ? 1 : err.status; try { out = JSON.parse(String(err.stdout || '').trim().split('\n').pop()); } catch (_) {} }
    return { out, exit };
  };

  // Control: the hand-frozen plan resume-checks clean before anything opens.
  let r670 = run670([VALIDATOR_670, planPath670, '--resume-check', '--json']);
  assert(r670.exit === 0 && r670.out.ok === true, 'T6d: control — the frozen decoy plan passes --resume-check, got ' + JSON.stringify(r670.out));

  // open: the real open-next opens impl-core (the sole ready node); this splices the ledger.
  r670 = run670([NODE_CLI_670, 'open-next', '--project', project670, '--json']);
  assert(r670.out.result === 'ok' && r670.out.opened && r670.out.opened.id === 'impl-core',
    'T6d: open-next opens impl-core, got ' + JSON.stringify(r670.out));

  // resume: the write must land OUTSIDE the hash-covered ## Node Briefs body, so --resume-check
  // still passes (the bug's mis-targeted splice into ## Node Briefs would break the plan_hash).
  r670 = run670([VALIDATOR_670, planPath670, '--resume-check', '--json']);
  assert(r670.exit === 0 && r670.out.ok === true,
    'T6d: after open, --resume-check still passes — no plan_hash_mismatch wedge from a mis-targeted splice, got ' + JSON.stringify(r670.out));

  // The GENUINE ledger reflects the transition; the decoy inside ## Node Briefs is never the target.
  const finalContent670 = fs.readFileSync(planPath670, 'utf8');
  const finalLedger670 = classifier.sectionBody(finalContent670, 'Node Ledger');
  assert(finalLedger670.includes('| impl-core | in_progress |'),
    'T6d: the genuine ledger shows impl-core in_progress, got ' + JSON.stringify(finalLedger670));
  // The decoy embedded ledger row inside ## Node Briefs stays byte-intact (still shows pending).
  assert(finalContent670.includes('Illustrative fenced example') && /```[\s\S]*## Node Ledger[\s\S]*\| impl-core \| pending \|[\s\S]*```/.test(finalContent670),
    'T6d: the fenced ## Node Briefs decoy block is left byte-intact (still shows pending), got ' + JSON.stringify(finalContent670));

  try { fs.rmSync(repoRoot670, { recursive: true, force: true }); } catch (_) {}
});

// ---------------------------------------------------------------------------
// T6e (#673): HEADING-MATCH parity (the #670 sibling channel) — locateSection's heading match was a
// loose `startsWith('## ' + heading)` PREFIX test at the opener and a bare `startsWith('## ')` at the
// next-heading terminator; the classifier's oracle (classifier.sectionBodyState / headRe) uses an
// ANCHORED `^##\s+<heading>\s*$` opener and an `^##\s` terminator. Four divergence channels:
//   (a) forward suffix   — `## Node Ledger Extra` prefix-matches the loose opener (false positive).
//   (b) two-space        — `##  Node Ledger` fails the loose opener's single-space prefix (false negative).
//   (c) tab (terminator) — `##\tAppendix` fails the loose `startsWith('## ')` terminator, so a
//                           following tab-heading section bleeds into the prior section's slice.
//   (d) line-0           — a heading at absolute offset 0 has no leading '\n' to report as `start`;
//                           this collides with locateSection's `-1 = absent` sentinel regardless of
//                           match style, so it is NOT reconcilable without breaking the offset
//                           contract every caller depends on (see the T6e-d comment below).
// ---------------------------------------------------------------------------
scenario(() => {
  const classifier673 = require('./kaola-workflow-classifier');

  // (a) forward-suffix decoy: an UNFENCED '## Node Ledger Extra' line precedes the genuine
  // '## Node Ledger' heading. The loose prefix opener false-positives on it (a decoy superstring);
  // the anchored opener correctly skips it and finds the genuine heading further down.
  const decoyPlanA = [
    '# Workflow Plan — test-project', '',
    '## Meta', 'labels: area:scripts', 'sink: CHANGELOG.md', '',
    '## Nodes', '',
    '| id | role | depends_on | declared_write_set | cardinality | shape |',
    '| --- | --- | --- | --- | --- | --- |',
    '| impl-core | tdd-guide | — | scripts/x.js | 1 | sequence |',
    '| review | code-reviewer | impl-core | — | 1 | sequence |',
    '| finalize | finalize | review | — | 1 | sequence |',
    '',
    '## Node Briefs', '',
    '### impl-core',
    'Some prose mentioning an unrelated decoy heading below (NOT the real ledger — extra suffix):',
    '## Node Ledger Extra',
    'This decoy section body must never be read as the real ledger.',
    '',
    '## Node Ledger', '',
    '| id | status |',
    '| --- | --- |',
    '| impl-core | pending |',
    '| review | pending |',
    '| finalize | pending |',
    '',
  ].join('\n') + '\n';

  const locA = locateSection(decoyPlanA, 'Node Ledger');
  const groundTruthA = classifier673.sectionBodyState(decoyPlanA, 'Node Ledger');
  assert(groundTruthA.status === 'present', 'T6e-a: classifier ground truth finds the genuine ledger present');
  assert(locA.start >= 0, 'T6e-a (#673): locateSection finds a ledger despite the forward-suffix decoy');
  const slicedA = locA.start >= 0 ? decoyPlanA.slice(locA.start, locA.next >= 0 ? locA.next : decoyPlanA.length) : '';
  assert(slicedA.replace(/^\n## Node Ledger\n/, '') === groundTruthA.body,
    'T6e-a (#673): locateSection agrees with classifier.sectionBodyState on the genuine (not the "Extra" suffix decoy) ledger body, got ' + JSON.stringify(slicedA));
  assert(!slicedA.includes('This decoy section body'),
    'T6e-a (#673): the located section excludes the forward-suffix decoy heading/body entirely, got ' + JSON.stringify(slicedA));

  // (b) two-space heading: `##  Node Ledger` (two spaces after `##`) is the SOLE ledger heading.
  // The loose opener's single-space prefix `'## ' + heading` fails to match it (false negative —
  // locateSection reports the section entirely absent); the anchored `\s+` opener matches it.
  const decoyPlanB = [
    '# Workflow Plan — test-project', '',
    '## Meta', 'labels: area:scripts', 'sink: CHANGELOG.md', '',
    '## Nodes', '',
    '| id | role | depends_on | declared_write_set | cardinality | shape |',
    '| --- | --- | --- | --- | --- | --- |',
    '| impl-core | tdd-guide | — | scripts/x.js | 1 | sequence |',
    '| review | code-reviewer | impl-core | — | 1 | sequence |',
    '| finalize | finalize | review | — | 1 | sequence |',
    '',
    '##  Node Ledger', '',
    '| id | status |',
    '| --- | --- |',
    '| impl-core | pending |',
    '| review | pending |',
    '| finalize | pending |',
    '',
  ].join('\n') + '\n';

  const locB = locateSection(decoyPlanB, 'Node Ledger');
  const groundTruthB = classifier673.sectionBodyState(decoyPlanB, 'Node Ledger');
  assert(groundTruthB.status === 'present', 'T6e-b: classifier ground truth accepts a two-space `##  Node Ledger` heading');
  assert(locB.start >= 0, 'T6e-b (#673): locateSection finds the two-space `##  Node Ledger` heading, got ' + JSON.stringify(locB));
  const slicedB = locB.start >= 0 ? decoyPlanB.slice(locB.start, locB.next >= 0 ? locB.next : decoyPlanB.length) : '';
  assert(slicedB.replace(/^\n##  Node Ledger\n/, '') === groundTruthB.body,
    'T6e-b (#673): locateSection agrees with classifier.sectionBodyState on the two-space heading body, got ' + JSON.stringify(slicedB));

  // (c) tab heading as the NEXT-HEADING TERMINATOR: a genuine (normal single-space) `## Node Ledger`
  // is immediately followed by a `##\tAppendix` section. The loose terminator `startsWith('## ')`
  // fails on the tab (not a literal space), so the Appendix content bleeds into the ledger slice;
  // the anchored `^##\s` terminator recognizes the tab and correctly ends the ledger section there.
  const decoyPlanC = [
    '# Workflow Plan — test-project', '',
    '## Meta', 'labels: area:scripts', 'sink: CHANGELOG.md', '',
    '## Nodes', '',
    '| id | role | depends_on | declared_write_set | cardinality | shape |',
    '| --- | --- | --- | --- | --- | --- |',
    '| impl-core | tdd-guide | — | scripts/x.js | 1 | sequence |',
    '| review | code-reviewer | impl-core | — | 1 | sequence |',
    '| finalize | finalize | review | — | 1 | sequence |',
    '',
    '## Node Ledger', '',
    '| id | status |',
    '| --- | --- |',
    '| impl-core | pending |',
    '| review | pending |',
    '| finalize | pending |',
    '##\tAppendix',
    'Appendix content that must NOT be included in the Node Ledger section slice.',
    '',
  ].join('\n') + '\n';

  const locC = locateSection(decoyPlanC, 'Node Ledger');
  const groundTruthC = classifier673.sectionBodyState(decoyPlanC, 'Node Ledger');
  assert(groundTruthC.status === 'present', 'T6e-c: classifier ground truth finds the ledger present, correctly terminated by the tab heading');
  assert(locC.start >= 0, 'T6e-c (#673): locateSection finds the ledger, got ' + JSON.stringify(locC));
  const slicedC = locC.start >= 0 ? decoyPlanC.slice(locC.start, locC.next >= 0 ? locC.next : decoyPlanC.length) : '';
  assert(slicedC.replace(/^\n## Node Ledger\n/, '') === groundTruthC.body,
    'T6e-c (#673): locateSection agrees with classifier.sectionBodyState — the tab heading correctly terminates the ledger slice, got ' + JSON.stringify(slicedC));
  assert(!slicedC.includes('Appendix content'),
    'T6e-c (#673): the tab-heading `##\\tAppendix` section is excluded from the Node Ledger slice (terminator anchored to `^##\\s`), got ' + JSON.stringify(slicedC));

  // (d) #673: a heading at absolute file offset 0 (no leading '\n'). The classifier's line-index
  // scan treats it as present (it has no notion of "the newline before the heading line"). But
  // locateSection's {start,next} CONTRACT reports `start` as the char offset of the '\n' BEFORE the
  // heading line — mirroring the pre-#354 legacy `content.indexOf('\n## ' + heading)` lookup, which
  // ALSO required a leading '\n' and therefore ALSO could never match a heading at position 0. This
  // is not a NEW divergence introduced by the opener/terminator match-style fix: at position 0 the
  // offset arithmetic collapses `start` to `off - 1 === -1`, which is INDISTINGUISHABLE from the
  // "-1 = absent" sentinel regardless of whether the opener uses `startsWith` or an anchored regex —
  // parity is structurally unreachable without redefining the offset contract, which every caller
  // (e.g. `materializeSpeculativePolicy`'s `headingStart = start + 1`) depends on. Reconciliation:
  // the `i > 0` guard is KEPT — removing it would not achieve parity (a line-0 "match" still
  // degrades to start=-1) and would introduce a WORSE divergence: the scan loop would `break`
  // immediately on the line-0 hit instead of continuing to find a genuine non-zero-line heading
  // elsewhere in the same content. Unreachable in practice: every real plan file opens with a
  // `# Workflow Plan — {project}` title line before any `##` section.
  const lineZeroContent = [
    '## Node Ledger', '',
    '| id | status |',
    '| --- | --- |',
    '| impl-core | pending |',
    '',
  ].join('\n') + '\n';
  const locD = locateSection(lineZeroContent, 'Node Ledger');
  const groundTruthD = classifier673.sectionBodyState(lineZeroContent, 'Node Ledger');
  assert(groundTruthD.status === 'present', 'T6e-d: classifier ground truth treats a line-0 heading as present (line-index scan, no offset contract)');
  assert(locD.start === -1 && locD.next === -1,
    'T6e-d (#673): locateSection cannot represent a line-0 heading under its "-1 = absent" offset contract (documented, structurally unreachable — see comment above), got ' + JSON.stringify(locD));

  // End-to-end (mirrors #670's T6d/T6c): a real subprocess open -> resume proves the forward-suffix
  // decoy (a) does not wedge the plan_hash — the write must land on the GENUINE ledger, matched by
  // the anchored opener, not the loose-prefix decoy.
  const { execFileSync: exec673 } = require('child_process');
  const NODE_CLI_673 = path.join(__dirname, 'kaola-workflow-adaptive-node.js');
  const VALIDATOR_673 = path.join(__dirname, 'kaola-workflow-plan-validator.js');
  const hash673 = planValidator.computePlanHash(decoyPlanA);
  const frozen673 = '<!-- plan_hash: ' + hash673 + ' -->\n' + decoyPlanA;

  const repoRoot673 = fs.mkdtempSync(path.join(os.tmpdir(), 'd673-heading-'));
  const project673 = 'test-project';
  const projDir673 = path.join(repoRoot673, 'kaola-workflow', project673);
  fs.mkdirSync(path.join(projDir673, '.cache'), { recursive: true });
  const planPath673 = path.join(projDir673, 'workflow-plan.md');
  fs.writeFileSync(planPath673, frozen673);
  fs.writeFileSync(path.join(projDir673, 'workflow-state.md'), '# State\n');
  const g673 = (a) => exec673('git', ['-C', repoRoot673, ...a], { encoding: 'utf8', stdio: ['ignore', 'ignore', 'ignore'] });
  g673(['init']); g673(['config', 'user.email', 'kw@test']); g673(['config', 'user.name', 'kw']); g673(['config', 'commit.gpgsign', 'false']);
  fs.writeFileSync(path.join(repoRoot673, '.gitignore'), '.kw/\n');
  g673(['add', '-A']); g673(['commit', '-m', 'init']);

  const run673 = (args) => {
    let out = {}; let exit = 0;
    // The per-scenario vehicle for the adaptive-node CLI. Every scenario drives it as a CHAIN:
    // one process writes the ledger row, the barrier baseline and the .cache evidence and EXITS,
    // and the next re-derives the whole run state from those bytes with no shared heap.
    // spawn-class: durable-handoff
    try { out = JSON.parse(exec673('node', args, { cwd: repoRoot673, encoding: 'utf8' }).trim().split('\n').pop()); }
    catch (err) { exit = (err.status == null) ? 1 : err.status; try { out = JSON.parse(String(err.stdout || '').trim().split('\n').pop()); } catch (_) {} }
    return { out, exit };
  };

  // Control: the hand-frozen plan resume-checks clean before anything opens.
  let r673 = run673([VALIDATOR_673, planPath673, '--resume-check', '--json']);
  assert(r673.exit === 0 && r673.out.ok === true, 'T6e: control — the frozen decoy plan passes --resume-check, got ' + JSON.stringify(r673.out));

  // open: the real open-next opens impl-core (the sole ready node); this splices the ledger.
  r673 = run673([NODE_CLI_673, 'open-next', '--project', project673, '--json']);
  assert(r673.out.result === 'ok' && r673.out.opened && r673.out.opened.id === 'impl-core',
    'T6e: open-next opens impl-core, got ' + JSON.stringify(r673.out));

  // resume: the write must land on the GENUINE ledger (outside the hash-covered ## Node Briefs decoy
  // body), so --resume-check still passes — the bug's decoy-targeted splice would break the plan_hash.
  r673 = run673([VALIDATOR_673, planPath673, '--resume-check', '--json']);
  assert(r673.exit === 0 && r673.out.ok === true,
    'T6e (#673): after open, --resume-check still passes — no plan_hash_mismatch wedge from a decoy-targeted splice, got ' + JSON.stringify(r673.out));

  const finalContent673 = fs.readFileSync(planPath673, 'utf8');
  const finalLedger673 = classifier673.sectionBody(finalContent673, 'Node Ledger');
  assert(finalLedger673.includes('| impl-core | in_progress |'),
    'T6e (#673): the genuine ledger shows impl-core in_progress, got ' + JSON.stringify(finalLedger673));
  assert(finalContent673.includes('This decoy section body must never be read as the real ledger.'),
    'T6e (#673): the forward-suffix decoy prose is left byte-intact, got ' + JSON.stringify(finalContent673));

  try { fs.rmSync(repoRoot673, { recursive: true, force: true }); } catch (_) {}
});

// ---------------------------------------------------------------------------
// T6b (#354, AC3): `## Nodes` row-walk PARITY — validator.parseNodes(content) and
// classifier.readPlanNodes(path) must extract the same id/role/depends_on set (both delegate
// section-slicing to the fence-aware classifier.sectionBody; this pins the row-walk against drift).
// ---------------------------------------------------------------------------
scenario(() => {
  const validator = require('./kaola-workflow-plan-validator');
  const classifier = require('./kaola-workflow-classifier');
  // #382: the fixture carries the optional `model` column (opus / sonnet / absent) so the parity
  // signature also pins `model` — validator.parseNodes and classifier.readPlanNodes must agree on it.
  const plan = [
    '## Meta', 'plan_hash: x', '',
    '## Nodes',
    '| id | role | depends_on | declared_write_set | est | shape | model |',
    '|----|------|-----------|--------------------|-----|-------|-------|',
    '| a | code-explorer | — | — | 1 | sequence | sonnet |',
    '| b | implementer | a | scripts/b.js | 1 | sequence | opus |',
    '| c | code-reviewer | b | — | 1 | sequence | |',
    '## Node Ledger', '| id | status |', '|----|--------|', '| a | pending |', '',
  ].join('\n');
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-nodes-parity-'));
  const planPath = path.join(tmp, 'workflow-plan.md');
  fs.writeFileSync(planPath, plan);
  const vNodes = validator.parseNodes(plan);
  const cNodes = classifier.readPlanNodes(planPath);
  const sig = n => n.id + ':' + n.role + ':' + (n.dependsOn || []).join(',') + ':' + (n.model || '');
  const vSig = vNodes.map(sig).join('|');
  const cSig = cNodes.map(sig).join('|');
  assert(vSig === 'a:code-explorer::sonnet|b:implementer:a:opus|c:code-reviewer:b:',
    'T6b: validator.parseNodes id/role/deps/model as expected, got ' + vSig);
  assert(vSig === cSig,
    'T6b (AC3 / #382): validator.parseNodes and classifier.readPlanNodes agree on id/role/deps/model (parity), v=' + vSig + ' c=' + cSig);
  try { fs.rmSync(tmp, { recursive: true, force: true }); } catch (_) {}
});

// ---------------------------------------------------------------------------
// T6: checkEvidenceShape — the TEST AUTHOR proves RED on the recorded baseline.
// Custody, not order: this role OWNS the test artifact and never writes production code, so it
// no longer carries GREEN (a passing suite is a verdict about the implementation, and the writer
// of the tests is not the grader of the code). In exchange RED gains its receipt — `red_baseline`,
// the baseline the failing test was captured on, checked against THIS open's recorded baseline.
// ---------------------------------------------------------------------------
scenario(() => {
  const NONCE = 'abc123def456';
  const bound = (body) => 'evidence-binding: impl-core ' + NONCE + '\n' + body;
  const opts = { expectedNonce: NONCE, expectedNodeId: 'impl-core' };

  // RED alone, with NO GREEN, closes: GREEN authority moved to the gate side.
  const r1 = checkEvidenceShape('tdd-guide', 'impl-core',
    bound('RED: test failed as expected\nred_baseline: ' + NONCE + '\n'), opts);
  assert(r1.ok === true, 'T6a: tdd-guide RED + red_baseline with no GREEN → ok (GREEN authority is gate-side), got ' + JSON.stringify(r1));

  // A missing red_baseline refuses — fail-on-baseline is a receipt, not a self-description.
  const r1b = checkEvidenceShape('tdd-guide', 'impl-core', bound('RED: test failed as expected\n'), opts);
  assert(r1b.ok === false && r1b.kind === 'shape' && r1b.missingTokenClass === 'red_baseline',
    'T6a2: tdd-guide missing red_baseline → shape/red_baseline, got ' + JSON.stringify(r1b));

  // A red_baseline naming ANOTHER baseline refuses — a RED signature cannot survive a reopen.
  const r1c = checkEvidenceShape('tdd-guide', 'impl-core',
    bound('RED: test failed\nred_baseline: 999999999999\n'), opts);
  assert(r1c.ok === false && r1c.missingTokenClass === 'red_baseline',
    'T6a3: tdd-guide red_baseline bound to another baseline → refused, got ' + JSON.stringify(r1c));

  // A legacy artifact read with NO expected nonce (offline / pre-rule) is tolerated, GREEN and all.
  const r2 = checkEvidenceShape('tdd-guide', 'impl-core', 'RED: test failed\nGREEN: test passed\n');
  assert(r2.ok === true, 'T6b: a legacy tdd-guide artifact read without a nonce is tolerated');

  // Seed-only scaffolding names every token in comments and leaves the values empty.
  const hollowSeed = 'evidence-binding: impl-core abc123\n<!-- RED: paste RED here -->\nRED: \n<!-- red_baseline: paste red_baseline here -->\nred_baseline: \n';
  const rHollow = checkEvidenceShape('tdd-guide', 'impl-core', hollowSeed);
  assert(rHollow.ok === false && rHollow.missingTokenClass === 'RED',
    'T6b-seed: tdd-guide hollow seed cannot satisfy evidence verification');

  // Bare colon-less token-name-only lines (#652 Gap 1): the matcher's column-0 regex requires
  // `<TOKEN>:` PLUS a non-empty value — a body carrying the BARE token name with no colon at all
  // must still refuse. Guards against a future weakening that accepts a bare token while still
  // refusing an empty `TOKEN: ` value (the T6b-seed case above) — the "partial-weakening hole".
  const bareRed = 'RED\nred_baseline: ' + NONCE + '\n';
  const rBareRed = checkEvidenceShape('tdd-guide', 'impl-core', bareRed);
  assert(rBareRed.ok === false && rBareRed.missingTokenClass === 'RED',
    'T6b-bare: tdd-guide with bare colon-less RED (no colon) → refused, missingTokenClass RED');

  const bareBaseline = checkEvidenceShape('tdd-guide', 'impl-core', bound('RED: test failed\nred_baseline\n'), opts);
  assert(bareBaseline.ok === false && bareBaseline.missingTokenClass === 'red_baseline',
    'T6b-bare2: tdd-guide with bare colon-less red_baseline (no colon) → refused, missingTokenClass red_baseline');

  // n/a skip reason
  const evidenceNa = 'n/a: no new code paths added, only documentation changes';
  const r3 = checkEvidenceShape('tdd-guide', 'impl-core', evidenceNa);
  assert(r3.ok === true, 'T6c: tdd-guide with n/a reason → ok');
});

// ---------------------------------------------------------------------------
// T7: checkEvidenceShape — the UNIVERSAL implementing role records a verification tier.
// `non_tdd_reason` retires with the test-first/no-test dichotomy that justified it: the implementer
// now takes over ALL behavioral logic, so there is no longer a category to justify. What survives is
// the tier it actually reached — `tests-green` for behavioral work (LOCAL working evidence; the
// authoritative verdict is gate-side) or one of the three non-behavioral tiers.
// ---------------------------------------------------------------------------
scenario(() => {
  // The tier ALONE closes — no non_tdd_reason required.
  const r1 = checkEvidenceShape('implementer', 'impl-other', 'regression-green: npm test passed');
  assert(r1.ok === true, 'T7a: implementer with a tier and no non_tdd_reason → ok (non_tdd_reason retired), got ' + JSON.stringify(r1));

  // The behavioral tier is first-class for the universal implementing role.
  const r1b = checkEvidenceShape('implementer', 'impl-other', 'tests-green: 12/12 assertions green against the authored suite');
  assert(r1b.ok === true, 'T7a2: implementer with tests-green → ok (the behavioral tier), got ' + JSON.stringify(r1b));

  // A legacy artifact still carrying the retired non_tdd_reason closes unchanged (tolerated on read).
  const r2 = checkEvidenceShape('implementer', 'impl-other', 'non_tdd_reason: config-only\nbuild-green: builds pass');
  assert(r2.ok === true, 'T7b: a legacy implementer artifact (non_tdd_reason + tier) is tolerated on read');

  // No tier at all still refuses — the tier is not optional.
  const r2b = checkEvidenceShape('implementer', 'impl-other', 'non_tdd_reason: config-only change, no logic paths');
  assert(r2b.ok === false && r2b.kind === 'shape' && r2b.missingTokenClass === 'change-type',
    'T7b2 (#319): implementer missing the verification tier → shape/change-type, got ' + JSON.stringify(r2b));

  // Every surviving alternative satisfies the tier on its own.
  for (const tier of ['tests-green', 'regression-green', 'build-green', 'smoke-integration']) {
    const rt = checkEvidenceShape('implementer', 'impl-other', tier + ': verified');
    assert(rt.ok === true, 'T7c: implementer with ' + tier + ' → ok');
  }

  // Seed-only scaffolding carries empty keys plus a comment naming every alternative.
  const hollowSeed = 'evidence-binding: impl-other abc123\n<!-- tests-green|regression-green|build-green|smoke-integration -->\ntests-green: \n';
  const rHollow = checkEvidenceShape('implementer', 'impl-other', hollowSeed);
  assert(rHollow.ok === false && rHollow.missingTokenClass === 'change-type',
    'T7e-seed: implementer hollow seed cannot satisfy evidence verification');

  // Bare colon-less change-type token (#652 Gap 1): the alternation regex requires `<token>:` PLUS
  // a non-empty value — a body carrying the BARE token name (e.g. "build-green") with no colon at
  // all must still refuse. Guards against a future weakening that accepts a bare token while still
  // refusing an empty `<token>: ` value (the T7e-seed case above) — the "partial-weakening hole".
  const bareChangeType = 'build-green\n';
  const rBareChangeType = checkEvidenceShape('implementer', 'impl-other', bareChangeType);
  assert(rBareChangeType.ok === false && rBareChangeType.missingTokenClass === 'change-type',
    'T7e-bare: implementer with bare colon-less change-type token (no colon) → refused, missingTokenClass change-type');

  // n/a skip
  const evidenceNa = 'n/a: no functional change';
  const r6 = checkEvidenceShape('implementer', 'impl-other', evidenceNa);
  assert(r6.ok === true, 'T7f: implementer with n/a → ok');
});

// ---------------------------------------------------------------------------
// T7g: a current nonce-bound generic role must satisfy its full registry row.
// Compact/free-form prose cannot replace the seeded body; legacy calls without a nonce retain the
// absent-key exemption for old in-flight artifacts.
// ---------------------------------------------------------------------------
scenario(() => {
  const compact = 'evidence-binding: explore abc123def456\nexplore code-explorer: done; evidence=.cache/explore.md\n';
  const strict = checkEvidenceShape('code-explorer', 'explore', compact,
    { expectedNonce: 'abc123def456', expectedNodeId: 'explore' });
  assert(strict.ok === false && strict.missingTokenClass === 'findings',
    'T7g: nonce-bound generic evidence refuses a compact body with no findings token');
  assert(checkEvidenceShape('code-explorer', 'explore', compact).ok === true,
    'T7g: a legacy/offline generic call without expectedNonce keeps the absent-key exemption');
  const complete = 'evidence-binding: explore abc123def456\nfindings: mapped affected files\n';
  assert(checkEvidenceShape('code-explorer', 'explore', complete,
    { expectedNonce: 'abc123def456', expectedNodeId: 'explore' }).ok === true,
  'T7g: nonce-bound generic evidence passes with its non-empty registry token');
});

// ---------------------------------------------------------------------------
// T7m (#634): checkEvidenceShape — metric-optimizer needs NON-EMPTY D6 tokens.
// A hollow seeded stub (token KEYS present, VALUES empty) must be REFUSED —
// the generic file-present-and-non-empty tail would wrongly accept it, so a
// metric node could close COMPLETE on a hollow stub with zero ratchet log.
// ---------------------------------------------------------------------------
scenario(() => {
  // Hollow seeded stub exactly as seedEvidenceFile emits it: every D6 token key
  // present (as a comment + a column-0 line) but with an EMPTY value.
  const hollowStub = [
    'evidence-binding: n2-opt opt123456789',
    '<!-- metric_baseline: paste metric_baseline here -->',
    'metric_baseline: ',
    '<!-- metric_final: paste metric_final here -->',
    'metric_final: ',
    '<!-- iterations_used: paste iterations_used here -->',
    'iterations_used: ',
    '<!-- regression-green: paste regression-green here -->',
    'regression-green: ',
  ].join('\n') + '\n';
  const rHollow = checkEvidenceShape('metric-optimizer', 'n2-opt', hollowStub);
  assert(rHollow.ok === false, 'T7m-a: metric-optimizer hollow stub (empty D6 values) → REFUSED');
  assert(rHollow.kind === 'shape' && rHollow.missingTokenClass === 'metric_baseline',
    'T7m-a: kind shape + missingTokenClass names the first empty D6 token (metric_baseline)');

  // Partial fill: baseline present, but metric_final still empty → refused AT metric_final.
  const partial = [
    'evidence-binding: n2-opt opt123456789',
    'metric_baseline: 4200ms p50',
    'metric_final: ',
    'iterations_used: 12',
    'regression-green: npm test passed',
  ].join('\n') + '\n';
  const rPartial = checkEvidenceShape('metric-optimizer', 'n2-opt', partial);
  assert(rPartial.ok === false && rPartial.missingTokenClass === 'metric_final',
    'T7m-b: metric-optimizer with one empty D6 token → refused, names that token');

  // Fully filled: all four D6 tokens carry non-empty values → ok.
  const filled = [
    'evidence-binding: n2-opt opt123456789',
    'metric_baseline: 4200ms p50 (node bench.js --emit-metric, 3 repeats)',
    'metric_final: 3100ms p50 (26% faster)',
    'iterations_used: 12 of 20 (patience-stopped at 5 no-improve)',
    'regression-green: npm test passed, 0 failures',
  ].join('\n') + '\n';
  const rFilled = checkEvidenceShape('metric-optimizer', 'n2-opt', filled);
  assert(rFilled.ok === true, 'T7m-c: metric-optimizer with all D6 values non-empty → ok');

  // Absent evidence → not ok (kind absent), mirroring the tdd-guide/implementer branches.
  const rAbsent = checkEvidenceShape('metric-optimizer', 'n2-opt', null);
  assert(rAbsent.ok === false && rAbsent.kind === 'absent',
    'T7m-d: metric-optimizer with null evidence → not ok (absent)');
});

// ---------------------------------------------------------------------------
// T8: checkEvidenceShape — other roles: file present is sufficient
// ---------------------------------------------------------------------------
scenario(() => {
  const evidencePresent = 'Reviewed the changes. LGTM.';
  const r1 = checkEvidenceShape('code-reviewer', 'review', evidencePresent);
  assert(r1.ok === true, 'T8a: code-reviewer with file present → ok');

  const r2 = checkEvidenceShape('finalize', 'finalize', evidencePresent);
  assert(r2.ok === true, 'T8b: finalize with file present → ok');

  // Missing/empty evidence → not ok
  const r3 = checkEvidenceShape('code-reviewer', 'review', null);
  assert(r3.ok === false, 'T8c: code-reviewer with null evidence → not ok');
  assert(r3.kind === 'absent', 'T8c (#319): null evidence → kind absent');

  const r4 = checkEvidenceShape('code-reviewer', 'review', '');
  assert(r4.ok === false, 'T8d: code-reviewer with empty evidence → not ok');
  assert(r4.kind === 'absent', 'T8d (#319): empty evidence → kind absent');
});

// ---------------------------------------------------------------------------
// T8g (#334): checkEvidenceShape — main-session-gate requires a column-0 verdict and
// REFUSES the universal 'n/a' self-skip (the inversion vs every other role).
// ---------------------------------------------------------------------------
scenario(() => {
  // absent evidence → kind absent, missingTokenClass non-empty
  const rAbsent = checkEvidenceShape('main-session-gate', 'vgate', null);
  assert(rAbsent.ok === false, 'T8g-a: main-session-gate absent evidence → not ok');
  assert(rAbsent.kind === 'absent', 'T8g-a: absent → kind absent');
  assert(rAbsent.missingTokenClass === 'non-empty', 'T8g-a: absent → missingTokenClass non-empty');

  const rEmpty = checkEvidenceShape('main-session-gate', 'vgate', '   ');
  assert(rEmpty.ok === false && rEmpty.kind === 'absent', 'T8g-b: whitespace-only → absent');

  // present but verdict-less → kind shape, missingTokenClass verdict
  const rNoVerdict = checkEvidenceShape('main-session-gate', 'vgate', 'looked at the screen, looks fine\n');
  assert(rNoVerdict.ok === false, 'T8g-c: verdict-less → not ok');
  assert(rNoVerdict.kind === 'shape', 'T8g-c: verdict-less → kind shape');
  assert(rNoVerdict.missingTokenClass === 'verdict', 'T8g-c: verdict-less → missingTokenClass verdict');

  // 'n/a ...' content → REFUSED for this role (the inversion: every OTHER role would skip)
  const rNa = checkEvidenceShape('main-session-gate', 'vgate', 'n/a — not a visual issue\n');
  assert(rNa.ok === false, 'T8g-d: n/a content REFUSED for main-session-gate (inversion vs other roles)');
  assert(rNa.kind === 'shape' && rNa.missingTokenClass === 'verdict', 'T8g-d: n/a content → shape/verdict');
  // (sanity: the SAME n/a content passes for a non-gate role)
  assert(checkEvidenceShape('code-reviewer', 'review', 'n/a — not a visual issue\n').ok === true,
    'T8g-d: same n/a content is a legal skip for code-reviewer');

  // verdict: pass / verdict: fail → ok (a fail verdict still CLOSES the node, parity with reviewers).
  // #607: a main-session-gate now ALSO requires the column-0 `instrumentation:` attestation token.
  const rPass = checkEvidenceShape('main-session-gate', 'vgate', 'verdict: pass\ninstrumentation: none\nfindings_blocking: 0\nGPU true-black confirmed\n');
  assert(rPass.ok === true, 'T8g-e: verdict: pass + instrumentation: none → ok');
  const rFail = checkEvidenceShape('main-session-gate', 'vgate', 'verdict: fail\ninstrumentation: none\nfindings_blocking: 1\nblacks looked grey\n');
  assert(rFail.ok === true, 'T8g-f: verdict: fail → ok (closes the node; blocking is at Finalization)');
  // last-match-wins + case-insensitive
  const rLast = checkEvidenceShape('main-session-gate', 'vgate', 'verdict: fail\ninstrumentation: none\nre-checked\nverdict: PASS\n');
  assert(rLast.ok === true, 'T8g-g: last-match-wins + case-insensitive verdict → ok');
});

// ---------------------------------------------------------------------------
// T9: runOrient — read-only w.r.t. plan/ledger/state; #763 the ONE legal write is the
// regenerable .cache/context-packet.md side artifact.
// ---------------------------------------------------------------------------
scenario(() => {
  const writeFilePaths = [];

  const plan = makePlan([
    '| impl-core | in_progress | |',
    '| impl-other | pending | |',
    '| review | pending | |',
    '| finalize | pending | |',
  ]);
  const state = makeState();
  const cacheContent = 'RED: failed\nGREEN: passed';

  const shellStub = function(scriptPath, args) {
    const base = path.basename(scriptPath);
    const argsArr = args || [];
    if (base === 'kaola-workflow-plan-validator.js') {
      return { exitCode: 0, ok: true, planHash: 'abc123' };
    }
    if (base === 'kaola-workflow-next-action.js') {
      return {
        exitCode: 0,
        result: 'ok',
        readySet: [{ id: 'impl-core', role: 'tdd-guide', model: 'sonnet', declared_write_set: 'scripts/adaptive-node.js', dependsOn: [] }],
        nextNode: { id: 'impl-core', role: 'tdd-guide', model: 'sonnet', declared_write_set: 'scripts/adaptive-node.js' },
        allDone: false,
      };
    }
    return { exitCode: 1 };
  };

  const result = runOrient({
    planPath: '/fake/kaola-workflow/test-project/workflow-plan.md',
    statePath: '/fake/kaola-workflow/test-project/workflow-state.md',
    project: 'test-project',
    shell: shellStub,
    readFile: (fpath) => {
      if (fpath.endsWith('workflow-plan.md')) return plan;
      if (fpath.endsWith('workflow-state.md')) return state;
      if (fpath.includes('.cache/')) return cacheContent;
      throw new Error('ENOENT: ' + fpath);
    },
    writeFile: (fpath, content) => { writeFilePaths.push(fpath); },
    cacheExists: (fpath) => fpath.includes('impl-core'),
  });

  assert(writeFilePaths.every(p => p.endsWith(path.join('.cache', 'context-packet.md'))),
    'T9: orient never calls writeFile on plan/ledger/state — only .cache/context-packet.md, got ' + JSON.stringify(writeFilePaths));
  assert(result.result === 'ok', 'T9: orient returns result ok');
  assert(result.inProgressNode === 'impl-core', 'T9: inProgressNode detected');
  assert(result.consentHalt === false, 'T9: consentHalt===false when no consent_halt marker');
  assert(result.escalatedToFull === null || result.escalatedToFull === undefined, 'T9: escalatedToFull null/undefined without marker');
});

// ---------------------------------------------------------------------------
// T10: runOpenNext — first open: in_progress + baseline recorded
// ---------------------------------------------------------------------------
scenario(() => {
  let writtenFiles = {};
  let shellCalls = [];

  const plan = makePlan([
    '| impl-core | pending | |',
    '| impl-other | pending | |',
    '| review | pending | |',
    '| finalize | pending | |',
  ]);
  const state = makeState();

  const shellStub = function(scriptPath, args) {
    const base = path.basename(scriptPath);
    const argsArr = args || [];
    shellCalls.push({ base, args: argsArr.slice() });

    // #499: open-next now runs the integrity layer (validator --resume-check); a clean frozen plan passes.
    if (base === 'kaola-workflow-plan-validator.js' && argsArr.includes('--resume-check')) return { exitCode: 0, ok: true };
    if (base === 'kaola-workflow-next-action.js') {
      return {
        exitCode: 0,
        result: 'ok',
        readySet: [{ id: 'impl-core', role: 'tdd-guide', model: 'sonnet', declared_write_set: 'scripts/adaptive-node.js', dependsOn: [] }],
        nextNode: { id: 'impl-core', role: 'tdd-guide', model: 'sonnet', declared_write_set: 'scripts/adaptive-node.js' },
        allDone: false,
      };
    }
    if (base === 'kaola-workflow-commit-node.js') {
      return { exitCode: 0, result: 'ok', mode: 'per-node-start', nodeId: 'impl-core', overallOk: true };
    }
    return { exitCode: 1, result: 'refuse', errors: ['stub: unexpected ' + base] };
  };

  let planContent = plan;

  const result = runOpenNext({
    planPath: '/fake/kaola-workflow/test-project/workflow-plan.md',
    statePath: '/fake/kaola-workflow/test-project/workflow-state.md',
    project: 'test-project',
    nodeId: null,
    shell: shellStub,
    readFile: (fpath) => {
      if (fpath.endsWith('workflow-plan.md')) return planContent;
      if (fpath.endsWith('workflow-state.md')) return state;
      throw new Error('ENOENT: ' + fpath);
    },
    writeFile: (fpath, content) => {
      writtenFiles[fpath] = content;
      if (fpath.endsWith('workflow-plan.md')) planContent = content;
    },
  });

  assert(result.result === 'ok', 'T10: open-next result===ok');
  assert(result.allDone === false, 'T10: allDone===false');
  assert(result.opened !== null, 'T10: opened !== null');
  assert(result.opened && result.opened.id === 'impl-core', 'T10: opened.id===impl-core');
  assert(result.baselineRecorded === true, 'T10: baselineRecorded===true');

  // Plan must have been written with in_progress
  const writtenPlan = writtenFiles['/fake/kaola-workflow/test-project/workflow-plan.md'];
  assert(writtenPlan !== undefined, 'T10: plan was written');
  assert(writtenPlan.includes('| impl-core | in_progress | |'), 'T10: ledger row set to in_progress');

  // commit-node --start was called
  const commitStartCall = shellCalls.find(c => c.base === 'kaola-workflow-commit-node.js' && c.args.includes('--start'));
  assert(commitStartCall !== undefined, 'T10: commit-node --start was called for baseline');
});

// ---------------------------------------------------------------------------
// T11: runOpenNext — allDone short-circuit
// ---------------------------------------------------------------------------
scenario(() => {
  let shellCalls = [];
  let writeFileCalled = false;

  const shellStub = function(scriptPath, args) {
    const base = path.basename(scriptPath);
    shellCalls.push(base);
    // #499: open-next integrity layer — a clean frozen plan passes --resume-check.
    if (base === 'kaola-workflow-plan-validator.js' && (args || []).includes('--resume-check')) return { exitCode: 0, ok: true };
    if (base === 'kaola-workflow-next-action.js') {
      return {
        exitCode: 0,
        result: 'ok',
        readySet: [],
        nextNode: null,
        allDone: true,
      };
    }
    return { exitCode: 1 };
  };

  const plan = makePlan([
    '| impl-core | complete | |',
    '| impl-other | complete | |',
    '| review | complete | |',
    '| finalize | complete | |',
  ]);

  const result = runOpenNext({
    planPath: '/fake/kaola-workflow/test-project/workflow-plan.md',
    statePath: '/fake/kaola-workflow/test-project/workflow-state.md',
    project: 'test-project',
    nodeId: null,
    shell: shellStub,
    readFile: (fpath) => {
      if (fpath.endsWith('workflow-plan.md')) return plan;
      return makeState();
    },
    writeFile: (fpath, content) => { writeFileCalled = true; },
  });

  assert(result.result === 'ok', 'T11: allDone open-next result===ok');
  assert(result.allDone === true, 'T11: allDone===true short-circuit');
  assert(result.opened === null, 'T11: opened===null when allDone');
  assert(writeFileCalled === false, 'T11: writeFile not called on allDone');
});

