// D444-GUARDS: deriveGuards exported and computes correct guards
// ---------------------------------------------------------------------------
scenario(() => {
  assert(typeof deriveGuards === 'function', 'D444-GUARDS: deriveGuards exported as function');

  // Gate roles → read-only
  for (const gateRole of ['code-reviewer', 'security-reviewer', 'adversarial-verifier', 'main-session-gate']) {
    const g = deriveGuards({ id: 'r1', role: gateRole, declared_write_set: '—' });
    assert(Array.isArray(g) && g.includes('read-only'),
      'D444-GUARDS: ' + gateRole + ' gets read-only guard, got ' + JSON.stringify(g));
  }

  // tdd-guide → RED-fixture-in-$TMPDIR
  const gTdd = deriveGuards({ id: 't1', role: 'tdd-guide', declared_write_set: 'scripts/x.js' });
  assert(gTdd.includes('RED-fixture-in-$TMPDIR'), 'D444-GUARDS: tdd-guide gets RED-fixture-in-$TMPDIR');

  // plain implementer with no generated port → no sync:editions
  const gImpl = deriveGuards({ id: 'i1', role: 'implementer', declared_write_set: 'CHANGELOG.md' });
  assert(!gImpl.includes('sync:editions'), 'D444-GUARDS: plain implementer → no sync:editions');
  assert(!gImpl.includes('read-only'), 'D444-GUARDS: implementer → no read-only');

  // implementer with generated-port write set → sync:editions
  const gGen = deriveGuards({
    id: 'g1', role: 'implementer',
    declared_write_set: 'scripts/kaola-workflow-adaptive-node.js, plugins/kaola-workflow/scripts/kaola-workflow-adaptive-node.js',
  });
  assert(gGen.includes('sync:editions'), 'D444-GUARDS: node with generated-port write set gets sync:editions guard');
});

// ===========================================================================
// #437-LANE-GROUP (D-419 Part 2) — open-ready co-open + close-node group barrier.
//
// Under KAOLA_LANE_CONTAINMENT, open-ready co-opens a ≥2 disjoint write frontier as a
// LANE GROUP (a lane_group key in running-set.json + a shared group baseline), and
// close-node DEFERS the per-member barrier to a single GROUP barrier at the last close.
// Tests drive the REAL adaptive-node + plan-validator subprocesses in a REAL git repo
// under $TMPDIR (#292 io-shim trap: a direct-call test with an injected git is a false-green).
// ===========================================================================
{
  const { execFileSync } = require('child_process');
  const NODE_CLI = path.join(__dirname, 'kaola-workflow-adaptive-node.js');
  const VALIDATOR = path.join(__dirname, 'kaola-workflow-plan-validator.js');

  // Build a frozen plan with a 2-write antichain frontier A(decl aSet) B(decl bSet) under a real git
  // repo: a `seed` (complete) so A,B are both ready-pending, a code-reviewer gate, a finalize sink.
  // Returns { repoRoot, project, planPath, projDir, cacheDir, g }.
  function makeLaneRepo(opts) {
    opts = opts || {};
    const aSet = opts.aSet || 'ax.js';
    const bSet = opts.bSet || 'by.js';
    // #588: optional EXTRA frontier members appended after A,B (each { id, role?, set? }; role defaults to
    //   tdd-guide, set defaults to '—' for a read member). review depends on A,B + every extra id. Absent /
    //   empty ⇒ the plan bytes are IDENTICAL to the original A,B-only fixture (all existing tests unaffected).
    const extra = Array.isArray(opts.extraMembers) ? opts.extraMembers : [];
    const extraIds = extra.map(m => m.id);
    const waitBudgets = opts.waitBudgets || null;
    const waitTail = id => waitBudgets ? ' standard | ' + waitBudgets[id] + ' |' : '';
    const reviewRow = extra.length
      ? '| review   | code-reviewer | ' + ['A', 'B'].concat(extraIds).join(',') + ' | — | 1 | sequence |'
      : '| review   | code-reviewer | A,B   | —     | 1 | sequence |';
    const repoRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'd437-lane-'));
    const project = 'test-project';
    const projDir = path.join(repoRoot, 'kaola-workflow', project);
    const cacheDir = path.join(projDir, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    const planPath = path.join(projDir, 'workflow-plan.md');
    const plan = [
      '# Workflow Plan — test-project', '',
      '## Meta', 'labels: area:scripts', 'sink: CHANGELOG.md',
      ...(opts.writeOverlapPolicy ? ['write_overlap_policy: ' + opts.writeOverlapPolicy] : []),
      '',
      '## Nodes', '',
      waitBudgets
        ? '| id | role | depends_on | declared_write_set | cardinality | shape | model | wait_budget_minutes |'
        : '| id | role | depends_on | declared_write_set | cardinality | shape |',
      waitBudgets
        ? '| --- | --- | --- | --- | --- | --- | --- | --- |'
        : '| --- | --- | --- | --- | --- | --- |',
      '| seed     | code-explorer | —     | —     | 1 | sequence |',
      '| A        | tdd-guide     | seed  | ' + aSet + ' | 1 | sequence |' + waitTail('A'),
      '| B        | tdd-guide     | seed  | ' + bSet + ' | 1 | sequence |' + waitTail('B'),
      ...extra.map(m => '| ' + m.id + ' | ' + (m.role || 'tdd-guide') + ' | seed | ' + (m.set || '—') + ' | 1 | sequence |' + waitTail(m.id)),
      reviewRow,
      '| finalize | finalize      | review| —     | 1 | sequence |', '',
      '## Node Ledger', '',
      '| id | status |', '| --- | --- |',
      '| seed | complete |',
      '| A | pending |',
      '| B | pending |',
      ...extra.map(m => '| ' + m.id + ' | pending |'),
      '| review | pending |',
      '| finalize | pending |', '',
    ].join('\n') + '\n';
    fs.writeFileSync(planPath, plan);
    fs.writeFileSync(path.join(projDir, 'workflow-state.md'), '# State\n');
    fs.writeFileSync(path.join(cacheDir, 'review.md'), 'verdict: pass\nfindings_blocking: 0\n');
    const g = (args) => execFileSync('git', ['-C', repoRoot, ...args], { encoding: 'utf8', stdio: ['ignore', 'ignore', 'ignore'] });
    g(['init']);
    g(['config', 'user.email', 'kw@test']);
    g(['config', 'user.name', 'kw']);
    g(['config', 'commit.gpgsign', 'false']);
    // Freeze in place so plan_hash exists (open-ready's integrity --resume-check needs a valid freeze).
    // An overlapping fixture (T-OR-2) cannot freeze (the antichain pair-loop refuses two siblings
    // writing the same file) — those tests serial-degrade BEFORE the group barrier, so a freeze failure
    // there is non-fatal (handled in the test).
    try { freezeLegacyFixture(execFileSync, 'node', VALIDATOR, planPath, { cwd: repoRoot, encoding: 'utf8' }); } catch (_) {}
    // #674a: optional consumer-repo convention — gitignore `.cache/` too (a common pattern for cache
    // dirs). Absent ⇒ byte-identical '.kw/\n' fixture every other caller relies on.
    fs.writeFileSync(path.join(repoRoot, '.gitignore'), opts.gitignoreCache ? '.kw/\n.cache/\n' : '.kw/\n');
    g(['add', '-A']);
    g(['commit', '-m', 'init']);
    return { repoRoot, project, planPath, projDir, cacheDir, g };
  }

  // Run the adaptive-node CLI as a REAL subprocess rooted at repoRoot. env carries the toggle.
  function runNode(repoRoot, subArgs, extraEnv) {
    const env = Object.assign({}, process.env, extraEnv || {});
    try {
      // The per-scenario vehicle for the adaptive-node CLI. Every scenario drives it as a CHAIN:
      // one process writes the ledger row, the barrier baseline and the .cache evidence and EXITS,
      // and the next re-derives the whole run state from those bytes with no shared heap.
      // spawn-class: durable-handoff
      const stdout = execFileSync('node', [NODE_CLI, ...subArgs], { cwd: repoRoot, encoding: 'utf8', env });
      let parsed = {};
      try { parsed = JSON.parse(stdout.trim().split('\n').pop()); } catch (_) {}
      return { exitCode: 0, ...parsed };
    } catch (err) {
      const status = (err.status == null) ? 1 : err.status;
      let parsed = {};
      try { parsed = JSON.parse(String(err.stdout || '').trim().split('\n').pop()); } catch (_) {}
      return { exitCode: status, ...parsed };
    }
  }

  function readRS(cacheDir) {
    try { return JSON.parse(fs.readFileSync(path.join(cacheDir, 'running-set.json'), 'utf8')); } catch (_) { return null; }
  }
  function ledgerStatus(planPath, id) {
    const txt = fs.readFileSync(planPath, 'utf8');
    // Scope to the ## Node Ledger section so the 6-column ## Nodes row (| A | tdd-guide | ...) is not
    // mistaken for the 2-column ledger row (| A | in_progress |).
    const start = txt.indexOf('## Node Ledger');
    const body = start >= 0 ? txt.slice(start) : txt;
    const re = new RegExp('^\\|\\s*' + id + '\\s*\\|\\s*(\\S+)\\s*\\|', 'm');
    const m = body.match(re);
    return m ? m[1] : null;
  }
  // Write an evidence file for a tdd-guide node carrying its open-time nonce (barrier-base SHA prefix)
  // + the RED/GREEN token classes its role requires (so the close-side evidence-shape check passes).
  function writeEvidence(cacheDir, id, extraLines) {
    return writeLegAwareEvidence(cacheDir, id, 'tdd-guide', extraLines);
  }
  function cleanup(root) { try { fs.rmSync(root, { recursive: true, force: true }); } catch (_) {} }
  const ON = { KAOLA_LANE_CONTAINMENT: '1' };
  const OFF = { KAOLA_LANE_CONTAINMENT: '0' };
  // #542 (D-542-01): co-open for planner-proven-disjoint write frontiers is DEFAULT-ON — no operator
  // toggle. The retired KAOLA_LANE_CONTAINMENT / KAOLA_LEG_ISOLATION toggles no longer suppress co-open.
  // The ONLY serial-degrade path is the explicit kill-switch KAOLA_PARALLEL_WRITES=0. DEFAULT is the
  // bare env (co-open). SERIAL forces the single-write serial fallback.
  const SERIAL = { KAOLA_PARALLEL_WRITES: '0' };
  const DEFAULT = {}; // bare env ⇒ default-on co-open

  // R4: real open-ready → dispatch evidence paths → close both skeptics → real whole-plan verdict.
  // No role-prefix bridge is authored anywhere in this project.
  scenario(() => {
    const repoRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-r4-skeptic-e2e-'));
    const project = 'skeptic-e2e';
    const projDir = path.join(repoRoot, 'kaola-workflow', project);
    const cacheDir = path.join(projDir, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    const planPath = path.join(projDir, 'workflow-plan.md');
    const plan = [
      '# Workflow Plan — skeptic-e2e', '', '## Meta', 'labels: area:scripts', '',
      '## Nodes', '',
      '| id | role | depends_on | declared_write_set | cardinality | shape |',
      '| --- | --- | --- | --- | --- | --- |',
      '| impl | tdd-guide | — | scripts/a.js | 1 | sequence |',
      '| review | code-reviewer | impl | — | 1 | sequence |',
      '| skeptic-a | adversarial-verifier | review | — | 1 | fanout(red-team) |',
      '| skeptic-b | adversarial-verifier | review | — | 1 | fanout(red-team) |',
      '| finalize | finalize | skeptic-a, skeptic-b | — | 1 | sequence |', '',
      '## Node Briefs', '', '### skeptic-a', 'verify', '', '### skeptic-b', 'verify', '',
      '## Node Ledger', '', '| id | status |', '| --- | --- |',
      '| impl | complete |', '| review | complete |', '| skeptic-a | pending |',
      '| skeptic-b | pending |', '| finalize | pending |', '',
    ].join('\n');
    fs.writeFileSync(planPath, plan);
    fs.writeFileSync(path.join(projDir, 'workflow-state.md'), '# State\n');
    const g = args => execFileSync('git', ['-C', repoRoot, ...args], { stdio: 'ignore' });
    try {
      g(['init']); g(['config', 'user.email', 'kw@test']); g(['config', 'user.name', 'kw']); g(['config', 'commit.gpgsign', 'false']);
      freezeLegacyFixture(execFileSync, 'node', VALIDATOR, planPath, { cwd: repoRoot, stdio: 'pipe' });
      g(['add', '-A']); g(['commit', '-m', 'seed']);
      // --record-base writes a kernel record (the barrier baseline file AND its git ref) in its own
      // process and exits; the adaptive-node process that follows re-reads both from disk. A
      // hand-written baseline could not carry a real ref, so the handoff is the fixture.
      // spawn-class: durable-handoff
      execFileSync('node', [VALIDATOR, planPath, '--record-base', '--node-id', 'impl', '--json'], { cwd: repoRoot, stdio: 'pipe' });
      const opened = runNode(repoRoot, ['open-ready', '--project', project, '--json'], DEFAULT);
      assert(opened.result === 'ok' && opened.opened.length === 2, 'R4 real open-ready opens both explicit skeptics, got ' + JSON.stringify(opened));
      for (const item of opened.opened) {
        assert(item.dispatch && item.dispatch.evidence_file, 'R4 dispatch carries authoritative evidence_file for ' + item.id);
        const evidencePath = path.join(repoRoot, item.dispatch.evidence_file);
        fs.mkdirSync(path.dirname(evidencePath), { recursive: true });
        fs.writeFileSync(evidencePath, 'evidence-binding: ' + item.id + ' ' + item.nonce + '\nverdict: pass\nfindings_blocking: 0\n');
        const closed = runNode(repoRoot, ['close-node', '--project', project, '--node-id', item.id, '--json'], DEFAULT);
        assert(closed.result === 'ok', 'R4 real close-node accepts dispatch.evidence_file-only receipt for ' + item.id + ', got ' + JSON.stringify(closed));
      }
      assert(!fs.readdirSync(cacheDir).some(f => /^adversarial-verifier-/.test(f)), 'R4 integration authors no role-prefix bridge');
      fs.writeFileSync(path.join(cacheDir, 'review.md'), 'verdict: pass\nfindings_blocking: 0\n');
      // --verdict-check re-reads, in a fresh process, the receipts that the earlier close-node
      // processes wrote to .cache and exited.
      // spawn-class: durable-handoff
      const verdict = JSON.parse(execFileSync('node', [VALIDATOR, planPath, '--verdict-check', '--json'], { cwd: repoRoot, encoding: 'utf8' }).trim());
      assert(verdict.ok === true || verdict.result === 'pass', 'R4 real whole-plan verdict-check passes canonical receipts, got ' + JSON.stringify(verdict));
    } finally { cleanup(repoRoot); }
  });

  // -------------------------------------------------------------------------
  // RETIRED for #498: D437-OPEN-READY-GROUP asserted ON-alone (KAOLA_LANE_CONTAINMENT only) FORMS a lane
  // group — the exact buggy behavior #498 removes. After the fix, co-open ⟺ legs provisioned (the full
  // containment + leg-isolation + consent conjunction), so the ON-alone positive is migrated to
  // #498-COOPEN-FULL-CONJUNCTION (below) and to LEG-PROVISION-ON (full leg manifest coverage). The
  // ON-alone serial-degrade is now asserted by #498-COOPEN-REQUIRES-LEGS.

  // -------------------------------------------------------------------------
  // D437-OPEN-READY-SERIAL-DEGRADE-OVERLAP: flag ON, two OVERLAPPING write nodes → serial degrade
  //   (one write opened, NO lane_group). (Overlapping plan cannot freeze; open-ready still degrades.)
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir } = makeLaneRepo({ aSet: 'ax.js', bSet: 'ax.js' });
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], ON);
    // The overlapping fixture fails to freeze, so open-ready's integrity gate may refuse; if it opens,
    // it must DEGRADE to a single serial write with NO lane_group. Assert no co-open either way.
    assert(!r.laneGroup, 'D437-OPEN-READY-SERIAL-DEGRADE-OVERLAP: NO laneGroup on overlap, got ' + JSON.stringify(r.laneGroup));
    const rs = readRS(cacheDir);
    assert(!rs || !rs.lane_group, 'D437-OPEN-READY-SERIAL-DEGRADE-OVERLAP: running-set has no lane_group');
    cleanup(repoRoot);
  });

  // Exact read-top-up image from the adversarial probe: stable r2 plus newly
  // opening r3, both ledger-in-progress at cap 2.
  scenario(() => {
    const repoRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-655-read-topup-'));
    const projDir = path.join(repoRoot, 'kaola-workflow', 'test-project');
    const cacheDir = path.join(projDir, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    const planPath = path.join(projDir, 'workflow-plan.md');
    fs.writeFileSync(planPath, [
      '# Plan', '', '## Meta', 'labels: enhancement', '', '## Nodes', '',
      '| id | role | depends_on | declared_write_set | cardinality | shape | model | wait_budget_minutes |',
      '| --- | --- | --- | --- | --- | --- | --- | --- |',
      '| r2 | code-explorer | — | — | 1 | fanout(reads) | standard | 240 |',
      '| r3 | code-explorer | — | — | 1 | fanout(reads) | standard | 300 |',
      '| finalize | finalize | r2,r3 | — | 1 | sequence | — | — |', '',
      '## Node Ledger', '', '| id | status |', '| --- | --- |',
      '| r2 | in_progress |', '| r3 | in_progress |', '| finalize | pending |', '',
    ].join('\n'));
    fs.writeFileSync(path.join(projDir, 'workflow-state.md'), '# State\n');
    G.exec(repoRoot, ['init'], { stdio: ['ignore', 'ignore', 'ignore'] });
    G.exec(repoRoot, ['config', 'user.email', 'kw@test']);
    G.exec(repoRoot, ['config', 'user.name', 'kw']);
    freezeLegacyFixture(execFileSync, 'node', VALIDATOR, planPath, { cwd: repoRoot, stdio: ['ignore', 'ignore', 'ignore'] });
    fs.writeFileSync(path.join(cacheDir, 'running-set.json'), JSON.stringify({
      state: 'opening', max_concurrent: 2,
      nodes: [
        { id: 'r2', role: 'code-explorer', kind: 'read', model: 'standard', wait_budget_minutes: 240, wait_budget_source: 'planner_override', baseline: 'recorded' },
        { id: 'r3', role: 'code-explorer', kind: 'read', model: 'standard', wait_budget_minutes: 300, wait_budget_source: 'planner_override', baseline: 'recorded', opening: true },
      ],
    }, null, 2));
    G.exec(repoRoot, ['add', '-A']);
    G.exec(repoRoot, ['commit', '-m', 'init'], { stdio: ['ignore', 'ignore', 'ignore'] });
    const rec = runNode(repoRoot, ['reconcile-running-set', '--project', 'test-project', '--json'], ON);
    const rs = readRS(cacheDir);
    assert(rec.result === 'ok' && rs.nodes.map(n => n.id).join(',') === 'r2,r3', '#655-MIXED-READ: exact stable r2 + opening r3 retained');
    assert(rs.nodes[0].wait_budget_minutes === 240 && rs.nodes[1].wait_budget_minutes === 300
      && rs.nodes.every(n => n.wait_budget_source === 'planner_override'), '#655-MIXED-READ: exact read budgets/source retained');
    const again = runNode(repoRoot, ['reconcile-running-set', '--project', 'test-project', '--json'], ON);
    const orient = runNode(repoRoot, ['orient', '--project', 'test-project', '--json'], ON);
    assert(again.reconciled === false && again.reason === 'not_opening' && orient.result === 'ok', '#655-MIXED-READ: repeat reconcile idempotent and orient healthy');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // D437-OPEN-READY-SERIAL (#542 kill-switch): KAOLA_PARALLEL_WRITES=0 forces the single-serial
  //   write_node path — NO lane_group, NO laneGroup descriptor. Opens exactly ONE write node; the
  //   other stays pending. (This was the OLD default-OFF behavior; after #542 it is reachable ONLY by
  //   the explicit kill-switch, since co-open is default-on.)
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir, planPath } = makeLaneRepo();
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], SERIAL);
    assert(r.result === 'ok', 'D437-OPEN-READY-SERIAL: open-ready ok, got ' + JSON.stringify(r));
    assert(!r.laneGroup, 'D437-OPEN-READY-SERIAL: NO laneGroup descriptor under KAOLA_PARALLEL_WRITES=0');
    assert(Array.isArray(r.opened) && r.opened.length === 1, 'D437-OPEN-READY-SERIAL: exactly ONE write opened (serial), got ' + JSON.stringify(r.opened && r.opened.map(n => n.id)));
    const rs = readRS(cacheDir);
    assert(!rs || !rs.lane_group, 'D437-OPEN-READY-SERIAL: running-set has no lane_group key');
    // The single opened node is in_progress; the other write stays pending (serial).
    const openedId = r.opened[0].id;
    assert(ledgerStatus(planPath, openedId) === 'in_progress', 'D437-OPEN-READY-SERIAL: the one opened write is in_progress');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // D437-OPEN-READY-DEFAULT-COOPEN (#542 default-on): with NO env (bare default), a ≥2 disjoint write
  //   frontier CO-OPENS as a lane group AND provisions legs — no operator toggle required. This is the
  //   inversion of the old default-OFF assertion above. Disjoint declared sets (ax.js / by.js) need NO
  //   --write-overlap-consent (the validator short-circuits green before the overlap-relax check).
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir, planPath } = makeLaneRepo();
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(r.result === 'ok', 'D437-OPEN-READY-DEFAULT-COOPEN: open-ready ok, got ' + JSON.stringify(r));
    assert(r.laneGroup && Array.isArray(r.laneGroup.members) && r.laneGroup.members.includes('A') && r.laneGroup.members.includes('B'),
      'D437-OPEN-READY-DEFAULT-COOPEN: bare-default co-opens a lane group [A,B], got ' + JSON.stringify(r.laneGroup));
    assert(Array.isArray(r.opened) && r.opened.length === 2, 'D437-OPEN-READY-DEFAULT-COOPEN: >=2 writes co-opened, got ' + JSON.stringify(r.opened && r.opened.map(n => n.id)));
    const rs = readRS(cacheDir);
    // #498 regression guard (co-open ⟹ legs): a co-opened lane group MUST carry a per-member legs
    // manifest — never the legless attribution-blind union barrier.
    assert(rs && rs.lane_group && rs.lane_group.legs && rs.lane_group.legs.A && rs.lane_group.legs.B,
      'D437-OPEN-READY-DEFAULT-COOPEN: co-open ⟹ legs provisioned for every member (the safe close path), got ' + JSON.stringify(rs && rs.lane_group));
    assert(ledgerStatus(planPath, 'A') === 'in_progress' && ledgerStatus(planPath, 'B') === 'in_progress', 'D437-OPEN-READY-DEFAULT-COOPEN: both A and B in_progress (co-opened)');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #546-G2-OPEN-READY-SHARED-INFRA-DEFAULT-COOPEN (DECISION B, accuracy-first): a ≥2 write frontier
  //   whose declared sets are EXACT-FILE-DISJOINT but share a SHARED_INFRA area (both under scripts/) is
  //   classifier-verdict {yellow, shared-infra}. Before #546-G2 this serial-degraded by default (no
  //   lane_group) because writeOverlapRelaxable required write_overlap_policy:'coarse' + consent. After
  //   #546-G2 it CO-OPENS BY DEFAULT — the validator's --parallel-safe (called WITHOUT
  //   --write-overlap-consent by tryFormLaneGroup) now relaxes shared-infra on the retained net
  //   (post-dominating code-reviewer gate over the legs + no PROTECTED file). The validator verdict
  //   drives the executor; NO adaptive-node change. This is the direct executor counterpart to the
  //   validator T546G2-* GREEN-NEW scenario. RED-provable against pre-#546-G2 (serial degrade → no
  //   lane_group → this block fails).
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir, planPath } = makeLaneRepo({ aSet: 'scripts/sa.js', bSet: 'scripts/sb.js' });
    // DEFAULT env (no toggle), NO --write-overlap-consent, NO write_overlap_policy in the plan.
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(r.result === 'ok', '#546-G2-OPEN-READY-SHARED-INFRA-DEFAULT-COOPEN: open-ready ok, got ' + JSON.stringify(r));
    assert(r.laneGroup && Array.isArray(r.laneGroup.members) && r.laneGroup.members.includes('A') && r.laneGroup.members.includes('B'),
      '#546-G2-OPEN-READY-SHARED-INFRA-DEFAULT-COOPEN: a gated shared-infra-disjoint frontier co-opens [A,B] BY DEFAULT (no consent), got ' + JSON.stringify(r.laneGroup));
    assert(Array.isArray(r.opened) && r.opened.length === 2,
      '#546-G2-OPEN-READY-SHARED-INFRA-DEFAULT-COOPEN: both scripts/ writes co-opened, got ' + JSON.stringify(r.opened && r.opened.map(n => n.id)));
    const rs = readRS(cacheDir);
    // co-open ⟹ legs (the safe close path); the retained net never lands the legless union barrier.
    assert(rs && rs.lane_group && rs.lane_group.legs && rs.lane_group.legs.A && rs.lane_group.legs.B,
      '#546-G2-OPEN-READY-SHARED-INFRA-DEFAULT-COOPEN: co-open ⟹ legs provisioned for every member, got ' + JSON.stringify(rs && rs.lane_group));
    assert(ledgerStatus(planPath, 'A') === 'in_progress' && ledgerStatus(planPath, 'B') === 'in_progress',
      '#546-G2-OPEN-READY-SHARED-INFRA-DEFAULT-COOPEN: both A and B in_progress (co-opened)');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #498-COOPEN-REQUIRES-LEGS (regression guard, open-side — #542 inverted premise): the #498
  //   invariant is "co-open ⟹ legs" — co-open NEVER lands the legless attribution-blind snapshot UNION
  //   barrier (`:4429`, liveLegs===null) that passes a cross-member overwrite. Under #542 (D-542-01)
  //   co-open is DEFAULT-ON: gated on legCoupled (parallelWritesDefaultOn, default TRUE), which is the
  //   SAME local that provisions legs (:3976). So groupForm ⟺ legCoupled ⟺ legs provisioned ⟺ the safe
  //   (parent-clean fence + commit-based) close path. We assert the invariant DIRECTLY across every
  //   co-open-eligible env (bare default + the legacy toggles, all of which now co-open): WHENEVER the
  //   running-set carries a lane_group, it MUST carry lane_group.legs with one leg per member. This is
  //   the #498 regression guard, now expressed as "co-open ⟹ legs, default-on". (RED-provable against a
  //   regressed gate that set groupForm with legs=null → the legless union barrier → this block fails.)
  // -------------------------------------------------------------------------
  scenario(() => {
    const coopenEnvs = [
      { label: 'bare default (no toggle, no consent)', env: DEFAULT, args: ['open-ready', '--project', 'test-project', '--json'] },
      { label: 'legacy containment toggle (now a no-op for co-open)', env: ON, args: ['open-ready', '--project', 'test-project', '--json'] },
      { label: 'legacy leg-isolation toggle (now a no-op for co-open)', env: { KAOLA_LANE_CONTAINMENT: '1', KAOLA_LEG_ISOLATION: '1' }, args: ['open-ready', '--project', 'test-project', '--json'] },
    ];
    for (const c of coopenEnvs) {
      const { repoRoot, cacheDir, planPath } = makeLaneRepo();
      const r = runNode(repoRoot, c.args, c.env);
      assert(r.result === 'ok', '#498-COOPEN-REQUIRES-LEGS [' + c.label + ']: open-ready ok, got ' + JSON.stringify(r));
      // Default-on: a ≥2 disjoint write frontier co-opens regardless of the legacy toggles.
      assert(r.laneGroup && Array.isArray(r.laneGroup.members) && r.laneGroup.members.includes('A') && r.laneGroup.members.includes('B'),
        '#498-COOPEN-REQUIRES-LEGS [' + c.label + ']: bare-default co-opens [A,B] (default-on), got ' + JSON.stringify(r.laneGroup));
      assert(Array.isArray(r.opened) && r.opened.length === 2, '#498-COOPEN-REQUIRES-LEGS [' + c.label + ']: both writes co-opened, got ' + JSON.stringify(r.opened && r.opened.map(n => n.id)));
      const rs = readRS(cacheDir);
      // ★ #498 REGRESSION GUARD (co-open ⟹ legs): whenever the running-set has a lane_group it MUST
      //   have lane_group.legs with one leg per member — co-open is NEVER legless. This is the #498
      //   invariant, now guarded by "co-open ⟹ legs, default-on".
      assert(rs && rs.lane_group && rs.lane_group.legs && rs.lane_group.members.every(m => rs.lane_group.legs[m]),
        '#498-COOPEN-REQUIRES-LEGS [' + c.label + ']: co-open is NEVER legless — lane_group.legs carries one leg per member, got ' + JSON.stringify(rs && rs.lane_group));
      assert(ledgerStatus(planPath, 'A') === 'in_progress' && ledgerStatus(planPath, 'B') === 'in_progress', '#498-COOPEN-REQUIRES-LEGS [' + c.label + ']: both A and B in_progress (co-opened)');
      cleanup(repoRoot);
    }
  });

  // -------------------------------------------------------------------------
  // #498-COOPEN-FULL-CONJUNCTION (positive — unchanged): with the FULL explicit toggles (containment +
  //   leg-isolation + consent) a ≥2 disjoint write frontier DOES co-open as a lane group AND provisions
  //   legs. Under #542 (D-542-01) default-on this is now a SUPERSET case (the bare default already
  //   co-opens — see D437-OPEN-READY-DEFAULT-COOPEN); the explicit toggles must remain a no-op overlay
  //   that still co-opens. The positive co-open ⟺ legs invariant is asserted directly here. (The
  //   detailed leg manifest assertions live in LEG-PROVISION-ON below.)
  // -------------------------------------------------------------------------
  scenario(() => {
    const LEG_ON_LOCAL = { KAOLA_LANE_CONTAINMENT: '1', KAOLA_LEG_ISOLATION: '1' };
    const { repoRoot, cacheDir, planPath } = makeLaneRepo();
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], LEG_ON_LOCAL);
    assert(r.result === 'ok', '#498-COOPEN-FULL-CONJUNCTION: open-ready ok, got ' + JSON.stringify(r));
    assert(r.laneGroup && Array.isArray(r.laneGroup.members) && r.laneGroup.members.includes('A') && r.laneGroup.members.includes('B'),
      '#498-COOPEN-FULL-CONJUNCTION: co-open forms a lane group [A,B] under the full conjunction, got ' + JSON.stringify(r.laneGroup));
    const rs = readRS(cacheDir);
    assert(rs && rs.lane_group && rs.lane_group.legs && rs.lane_group.legs.A && rs.lane_group.legs.B,
      '#498-COOPEN-FULL-CONJUNCTION: co-open ⟺ legs provisioned (the safe close path), got ' + JSON.stringify(rs && rs.lane_group));
    assert(ledgerStatus(planPath, 'A') === 'in_progress' && ledgerStatus(planPath, 'B') === 'in_progress',
      '#498-COOPEN-FULL-CONJUNCTION: both A and B in_progress (co-opened)');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // RETIRED for #498: the legless (containment-only co-open) group close tests — D437-CLOSE-NODE-DEFERRED,
  // D437-CLOSE-NODE-GROUP-PASS, D437-CLOSE-NODE-VACUITY-REFUSE, D437-CLOSE-NODE-CROSS-LANE-STRAY — and the
  // ON-alone positive D437-OPEN-READY-GROUP. PREMISE NOW UNREACHABLE: after #498 co-open ⟺ legs provisioned,
  // so a legless group is no longer a producible state via open-ready (every co-open provisions legs —
  // see #498-COOPEN-REQUIRES-LEGS). The snapshot union barrier (`:4429`, liveLegs===null) those tests
  // exercised is now reachable only by manual running-set surgery; pinning it would test dead code on the
  // out-of-scope plan-validator union barrier. No coverage lost:
  //   - group OPEN (default-on) → D437-OPEN-READY-DEFAULT-COOPEN / LEG-PROVISION-ON / #498-COOPEN-FULL-CONJUNCTION
  //   - group CLOSE (deferred + group_passed via the legs-live synthesizer) → LEG-CLEAN-COMPLETION-NO-LEAK
  //   - the SERIAL close now lives under the explicit kill-switch → D437-CLOSE-NODE-SERIAL
  //     (KAOLA_PARALLEL_WRITES=0 forces the single-serial write path).

  // -------------------------------------------------------------------------
  // D437-CLOSE-NODE-SERIAL (#542 kill-switch): KAOLA_PARALLEL_WRITES=0 forces the single-serial open,
  //   so close-node runs the normal per-node barrier path (no deferred/group). Closing the one node
  //   returns the serial shape (no `barrier` field set to deferred/group).
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir, planPath } = makeLaneRepo();
    const open = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], SERIAL);
    const openedId = open.opened[0].id;
    writeEvidence(cacheDir, openedId);
    fs.writeFileSync(path.join(repoRoot, openedId === 'A' ? 'ax.js' : 'by.js'), '// serial in-lane\n');
    const r = runNode(repoRoot, ['close-node', '--node-id', openedId, '--project', 'test-project', '--json'], SERIAL);
    assert(r.result === 'ok', 'D437-CLOSE-NODE-SERIAL: serial close ok, got ' + JSON.stringify(r));
    assert(r.barrier !== 'deferred_to_group' && r.barrier !== 'group_passed',
      'D437-CLOSE-NODE-SERIAL: NO deferred/group barrier marker on the serial path, got ' + r.barrier);
    assert(r.closed === openedId, 'D437-CLOSE-NODE-SERIAL: serial close returns closed id');
    assert(ledgerStatus(planPath, openedId) === 'complete', 'D437-CLOSE-NODE-SERIAL: node complete via serial per-node barrier');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #674a (D-674-01 a): a consumer repo that gitignores `.cache/` (a common convention) must NOT abort
  //   the lane-group co-open. The seeded member evidence stubs are explicitly enumerated paths (never a
  //   glob), so `git add -f` on them is safe and required — an unforced add refuses on a gitignored
  //   path, which since #802 D7 serial-degrades the authored parallel-write antichain
  //   (`seam_checkpoint_declined`) rather than refusing outright. Either way the antichain is lost.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir, planPath } = makeLaneRepo({ gitignoreCache: true });
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(r.result === 'ok' && Array.isArray(r.opened) && r.opened.length === 2,
      '#674a: gitignored .cache/ must not abort the co-open (the stub add needs -f), got ' + JSON.stringify({ result: r.result, reason: r.reason, opened: r.opened }));
    assert(r.laneGroup && Array.isArray(r.laneGroup.members) && r.laneGroup.members.includes('A') && r.laneGroup.members.includes('B'),
      '#674a: the lane group [A,B] still forms despite gitignored .cache/, got ' + JSON.stringify(r.laneGroup));
    const rs = readRS(cacheDir);
    assert(rs && rs.state === 'open' && rs.lane_group && rs.lane_group.legs && rs.lane_group.legs.A && rs.lane_group.legs.B,
      '#674a: running set reaches open state with both legs provisioned, got ' + JSON.stringify(rs));
    assert(ledgerStatus(planPath, 'A') === 'in_progress' && ledgerStatus(planPath, 'B') === 'in_progress',
      '#674a: both A and B in_progress (co-opened, not serial-degraded)');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #674b (D-674-01 b): a group-form abort AFTER the member-baseline loop has recorded a baseline for
  //   every `toOpen` member must transactionally DROP those baselines — otherwise a LATER serial open of
  //   the SAME member id REUSES the stale pre-abort snapshot (--record-base's crash-resume idempotent
  //   reuse), so the member's close barrier misattributes a SIBLING's uncommitted write (landed in the
  //   shared, leg-less tree between the abort and the re-open) as an out-of-declared-set overflow.
  //   Repro (mirrors the vrpai-cli#948 incident): force B's leg provisioning to fail — pre-checkout B's
  //   deterministic leg branch in a decoy worktree so provisionLeg's branch-reuse
  //   `git worktree add -- <legPath> <legBranch>` collides with git's "already checked out" refusal —
  //   AFTER the member loop has already recorded baselines for BOTH A and B at a clean pre-run tree T0.
  //   Land B's declared file (a sibling diff) into the shared tree, THEN open A serially (doc-index
  //   tie-break picks A first — see makeLaneRepo's A-before-B declaration order), THEN close A.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, project, cacheDir, g } = makeLaneRepo();
    const legBranchB = 'kw/legs/' + project + '/B';
    // Decoy worktree lives OUTSIDE repoRoot (a sibling tmpdir) so it never shows up as untracked dirt in
    // the parent tree's `git status` (parentCarriesProductionDirt would otherwise misclassify the fixture
    // itself as dirty and route open-ready down the unrelated R2b legless-degrade path).
    const decoyPath = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-674-decoy-'));
    fs.rmdirSync(decoyPath);
    g(['worktree', 'add', '-b', legBranchB, '--', decoyPath, 'HEAD']);

    const aborted = runNode(repoRoot, ['open-ready', '--project', project, '--json'], DEFAULT);
    assert(aborted.result === 'refuse' && aborted.reason === 'leg_provision_failed',
      '#674b: forced group-form abort (leg_provision_failed) AFTER the member-baseline loop recorded both baselines, got ' + JSON.stringify(aborted));
    // The fix drops the baseline TRANSACTIONALLY as part of the same abort — so by the time this call
    // RETURNS, A's stale baseline must already be gone (not left stranded for a later serial reuse).
    assert(!fs.existsSync(path.join(cacheDir, 'barrier-base-A')),
      '#674b: A\'s member baseline is DROPPED as part of the group-form abort (never left stranded for a later stale reuse)');

    // A sibling's diff lands in the SAME shared (leg-less) worktree after the aborted co-open.
    fs.writeFileSync(path.join(repoRoot, 'by.js'), '// sibling diff landed after the aborted co-open\n');

    const opened = runNode(repoRoot, ['open-ready', '--project', project, '--json'], SERIAL);
    assert(opened.result === 'ok' && opened.opened && opened.opened[0] && opened.opened[0].id === 'A',
      '#674b: the later serial open picks A first, got ' + JSON.stringify(opened));

    writeEvidence(cacheDir, 'A');
    fs.writeFileSync(path.join(repoRoot, 'ax.js'), '// A in-lane serial write\n');
    const closed = runNode(repoRoot, ['close-node', '--node-id', 'A', '--project', project, '--json'], SERIAL);
    assert(closed.result === 'ok' && closed.closed === 'A',
      '#674b: A\'s close must NOT false-positive write_set_overflow on the sibling\'s (B\'s) landed diff — the reused stale baseline must not misattribute it, got ' + JSON.stringify(closed));
    cleanup(repoRoot);
    try { fs.rmSync(decoyPath, { recursive: true, force: true }); } catch (_) {}
  });

  // -------------------------------------------------------------------------
  // #678 R1 (the #674 symmetric gap): a group-form abort AFTER the SHARED GROUP baseline was recorded
  //   (once, before the member loop — see the `if (groupForm)` block that precedes the leg-provisioning
  //   loop) must ALSO drop that group baseline on every one of the 5 abort paths — #674 only dropped the
  //   per-MEMBER baselines (dropRecordedBaselines), leaving the group's OWN `barrier-base-lg-<...>` file
  //   + `refs/kaola-workflow/barrier/<project>/lg-<...>` ref stranded. Repro: reuse #674b's exact
  //   leg_provision_failed forcing (decoy worktree pre-checks-out B's deterministic leg branch so
  //   provisionLeg's `git worktree add` collides), which fires strictly AFTER the group baseline was
  //   already recorded. Assert the group baseline file+ref are BOTH gone post-abort, and that the ledger
  //   + lane_group descriptor (no running-set.json was ever written — the abort fires before Phase 1)
  //   stay untouched.
  // -------------------------------------------------------------------------
  function groupBaselineFile678(cacheDir, groupId) {
    return path.join(cacheDir, 'barrier-base-' + groupId.replace(/[^A-Za-z0-9_-]/g, '_'));
  }
  function groupBaselineRefExists678(repoRoot, project, groupId) {
    try {
      G.exec(repoRoot, ['rev-parse', '--verify', '--quiet', 'refs/kaola-workflow/barrier/' + project + '/' + groupId.replace(/[^A-Za-z0-9_-]/g, '_') + '^{commit}'], { stdio: ['ignore', 'ignore', 'ignore'] });
      return true;
    } catch (_) { return false; }
  }
  scenario(() => {
    const { repoRoot, project, planPath, cacheDir, g } = makeLaneRepo();
    const groupId = 'lg-A-B';
    const legBranchB = 'kw/legs/' + project + '/B';
    const decoyPath = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-678-decoy-'));
    fs.rmdirSync(decoyPath);
    g(['worktree', 'add', '-b', legBranchB, '--', decoyPath, 'HEAD']);

    const aborted = runNode(repoRoot, ['open-ready', '--project', project, '--json'], DEFAULT);
    assert(aborted.result === 'refuse' && aborted.reason === 'leg_provision_failed',
      '#678: forced group-form abort (leg_provision_failed) AFTER the group baseline was recorded, got ' + JSON.stringify(aborted));

    // Pre-fix: both of these survive the abort (the strand this issue fixes). Post-fix: both are gone.
    assert(!fs.existsSync(groupBaselineFile678(cacheDir, groupId)),
      '#678: the SHARED GROUP baseline FILE must be dropped as part of the group-form abort (was stranded pre-fix), got file exists=' + fs.existsSync(groupBaselineFile678(cacheDir, groupId)));
    assert(!groupBaselineRefExists678(repoRoot, project, groupId),
      '#678: the SHARED GROUP baseline REF must be dropped as part of the group-form abort (was stranded pre-fix), got ref exists=' + groupBaselineRefExists678(repoRoot, project, groupId));

    // The ledger + lane_group descriptor stay untouched: the abort fires inside the leg-provisioning
    // block, strictly BEFORE Phase 1 writes running-set.json, so no running set / lane_group is ever
    // created and both A and B are still `pending`.
    assert(ledgerStatus(planPath, 'A') === 'pending' && ledgerStatus(planPath, 'B') === 'pending',
      '#678: A and B stay pending on the aborted group-form open (ledger untouched), got ' + JSON.stringify({ A: ledgerStatus(planPath, 'A'), B: ledgerStatus(planPath, 'B') }));
    assert(!readRS(cacheDir),
      '#678: no running-set.json (and therefore no lane_group descriptor) was ever written by the aborted open, got ' + JSON.stringify(readRS(cacheDir)));

    cleanup(repoRoot);
    try { fs.rmSync(decoyPath, { recursive: true, force: true }); } catch (_) {}
  });

  // -------------------------------------------------------------------------
  // #680 Part A (the Phase-2 non-drop): a group co-open that ABORTS in Phase 2 (the ledger-seeding/
  //   promotion loop, AFTER the Phase-1 group + member baseline record + leg provisioning) must drop BOTH
  //   the shared GROUP baseline (barrier-base-lg-<...> file + ref) AND every per-MEMBER baseline — NOT
  //   strand them. The two Phase-2 aborts are `baseline_failed` and `node_not_in_ledger`; pre-fix neither
  //   dropped anything (the drop helpers were block-scoped to the Phase-1 leg-provisioning block). --drop-
  //   base IS legal at both aborts: the ledger flip to in_progress is spliced into planContent in memory
  //   and written to disk only AFTER the whole Phase-2 loop, so every member's on-disk ledger row is still
  //   `pending` at the abort (a group_id has no ledger row at all).
  //   Drive the REAL runOpenReady in-process against a REAL git repo (so the barrier-base files + anchored
  //   refs are real and directly assertable), with a shell wrapper that forces the SECOND (Phase-2) commit-
  //   node --start for member A to fail → baseline_failed. Phase 1's group + member baselines are recorded
  //   by passthrough to the real shellNode FIRST, so all three baselines exist on disk at the abort point.
  // -------------------------------------------------------------------------
  scenario(() => {
    const lane = makeLaneRepo();
    const project = lane.project;
    const groupId = 'lg-A-B';
    // #292 io-shim trap: getRoot() inside runOpenReady resolves the repo toplevel via `git rev-parse`
    // (realpath form), while mkdtemp hands back the /var symlink form on macOS. path.relative(root, ...)
    // over the two forms yields a bogus ../../.. path and the stub `git add` fails BEFORE Phase 2. Pin
    // EVERYTHING to the realpath'd root so getRoot() and the injected planPath agree.
    const repoRoot = fs.realpathSync(lane.repoRoot);
    const planPath = path.join(repoRoot, path.relative(lane.repoRoot, lane.planPath));
    const cacheDir = path.join(repoRoot, path.relative(lane.repoRoot, lane.cacheDir));
    // Wrapper over the real shellNode: count commit-node --start calls per node id and force the 2nd
    // start for A (its Phase-2 idempotent-reuse call) to fail. Everything else passes through, so the
    // Phase-1 group baseline (lg-A-B) + member baselines (A, B) land on disk as REAL files + refs.
    const startCounts = {};
    const forcedShell = (scriptPath, args) => {
      const a = args || [];
      if (path.basename(scriptPath) === 'kaola-workflow-commit-node.js' && a.includes('--start')) {
        const idIdx = a.indexOf('--node-id');
        const id = idIdx >= 0 ? a[idIdx + 1] : null;
        startCounts[id] = (startCounts[id] || 0) + 1;
        if (id === 'A' && startCounts[id] === 2) {
          return { exitCode: 1, result: 'refuse', reason: 'baseline_failed_forced' };
        }
      }
      return shellNode(scriptPath, a);
    };
    const savedCwd = process.cwd();
    let aborted;
    try {
      process.chdir(repoRoot);
      aborted = runOpenReady({
        planPath, project, max: null, fanoutCapReadonly: 8,
        shell: forcedShell,
        readFile: (f) => fs.readFileSync(f, 'utf8'),
        writeFile: (f, c) => { try { fs.mkdirSync(path.dirname(f), { recursive: true }); } catch (_) {} fs.writeFileSync(f, c); },
        cacheExists: (f) => fs.existsSync(f),
        mkdirp: (d) => { try { fs.mkdirSync(d, { recursive: true }); } catch (_) {} },
        now: () => new Date().toISOString(),
      });
    } finally { process.chdir(savedCwd); }
    assert(aborted && aborted.result === 'refuse' && aborted.reason === 'baseline_failed',
      '#680-A: a forced Phase-2 baseline abort refuses baseline_failed, got ' + JSON.stringify(aborted));
    // GROUP baseline (file + ref) dropped — pre-fix this stranded.
    assert(!fs.existsSync(groupBaselineFile678(cacheDir, groupId)),
      '#680-A: the Phase-2 abort drops the shared GROUP baseline FILE (was stranded pre-fix), got exists=' + fs.existsSync(groupBaselineFile678(cacheDir, groupId)));
    assert(!groupBaselineRefExists678(repoRoot, project, groupId),
      '#680-A: the Phase-2 abort drops the shared GROUP baseline REF (was stranded pre-fix)');
    // Per-MEMBER baselines (file + ref) dropped — pre-fix these stranded too.
    assert(!fs.existsSync(path.join(cacheDir, 'barrier-base-A')) && !fs.existsSync(path.join(cacheDir, 'barrier-base-B')),
      '#680-A: the Phase-2 abort drops BOTH member baseline FILES (were stranded pre-fix)');
    assert(!groupBaselineRefExists678(repoRoot, project, 'A') && !groupBaselineRefExists678(repoRoot, project, 'B'),
      '#680-A: the Phase-2 abort drops BOTH member baseline REFS (were stranded pre-fix)');
    // Ledger untouched: the on-disk plan is never written on a Phase-2 abort, so A and B stay pending.
    assert(ledgerStatus(planPath, 'A') === 'pending' && ledgerStatus(planPath, 'B') === 'pending',
      '#680-A: the durable ledger rows stay pending on the aborted Phase-2 open (ledger + lane_group untouched), got ' + JSON.stringify({ A: ledgerStatus(planPath, 'A'), B: ledgerStatus(planPath, 'B') }));
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #680 Part B positive (the pre-journal SIGKILL window): a baseline recorded with NO 'opening' journal
  //   ever written (a hard crash between open-ready's baseline record and its Phase-1 running-set journal
  //   write) has NO ledger in_progress row AND NO running-set owner — an orphan unreachable by any refusal-
  //   return path. reconcile-running-set's additive orphan-baseline sweep (hoisted above the no_running_set
  //   early-return) must detect and drop it (file + ref). Pre-fix (no sweep) the orphan survives forever.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, project, planPath, cacheDir } = makeLaneRepo();
    // Record a REAL orphan baseline (file + ref) for an id in NO ledger row and NO running set.
    // --record-base writes a kernel record (the barrier baseline file AND its git ref) in its own
    // process and exits; the adaptive-node process that follows re-reads both from disk. A
    // hand-written baseline could not carry a real ref, so the handoff is the fixture.
    // spawn-class: durable-handoff
    execFileSync('node', [VALIDATOR, planPath, '--record-base', '--node-id', 'orphan', '--json'], { cwd: repoRoot, encoding: 'utf8' });
    assert(fs.existsSync(path.join(cacheDir, 'barrier-base-orphan')) && groupBaselineRefExists678(repoRoot, project, 'orphan'),
      '#680-B: the orphan baseline (file + ref) is seeded before reconcile');
    // No running-set.json exists (the crash predated the Phase-1 journal write) → reconcile takes the
    // no_running_set path, and the hoisted orphan sweep still reclaims the strand.
    const rec = runNode(repoRoot, ['reconcile-running-set', '--project', project, '--json'], DEFAULT);
    assert(rec.result === 'ok', '#680-B: reconcile-running-set ok, got ' + JSON.stringify(rec));
    assert(Array.isArray(rec.orphanBaselinesDropped) && rec.orphanBaselinesDropped.includes('orphan'),
      '#680-B: reconcile reports the orphan baseline dropped, got ' + JSON.stringify(rec.orphanBaselinesDropped));
    assert(!fs.existsSync(path.join(cacheDir, 'barrier-base-orphan')),
      '#680-B: the pre-journal orphan baseline FILE is dropped by the sweep (survived pre-fix)');
    assert(!groupBaselineRefExists678(repoRoot, project, 'orphan'),
      '#680-B: the pre-journal orphan baseline REF is dropped by the sweep (survived pre-fix)');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #680 Part B negative (the false-positive guard): the sweep must NOT drop a LIVE baseline. A baseline
  //   owned by an in_progress ledger member AND a live lane_group's group baseline must SURVIVE (the
  //   survives-checks hold both pre- and post-fix). A co-present orphan is dropped in the SAME run, so the
  //   sweep is proven active and discriminating — a buggy over-reaping sweep would drop the live baselines
  //   and fail the survives-checks.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, project, planPath, cacheDir } = makeLaneRepo();
    const groupId = 'lg-A-B';
    // A is a genuinely-live in_progress member; stand up a live 'open' lane_group with A as a live node.
    fs.writeFileSync(planPath, fs.readFileSync(planPath, 'utf8').replace('| A | pending |', '| A | in_progress |'));
    // --record-base writes a kernel record (the barrier baseline file AND its git ref) in its own
    // process and exits; the adaptive-node process that follows re-reads both from disk. A
    // hand-written baseline could not carry a real ref, so the handoff is the fixture.
    // spawn-class: durable-handoff
    execFileSync('node', [VALIDATOR, planPath, '--record-base', '--node-id', 'A', '--json'], { cwd: repoRoot, encoding: 'utf8' });
    // --record-base writes a kernel record (the barrier baseline file AND its git ref) in its own
    // process and exits; the adaptive-node process that follows re-reads both from disk. A
    // hand-written baseline could not carry a real ref, so the handoff is the fixture.
    // spawn-class: durable-handoff
    execFileSync('node', [VALIDATOR, planPath, '--record-base', '--node-id', groupId, '--json'], { cwd: repoRoot, encoding: 'utf8' });
    // --record-base writes a kernel record (the barrier baseline file AND its git ref) in its own
    // process and exits; the adaptive-node process that follows re-reads both from disk. A
    // hand-written baseline could not carry a real ref, so the handoff is the fixture.
    // spawn-class: durable-handoff
    execFileSync('node', [VALIDATOR, planPath, '--record-base', '--node-id', 'orphan', '--json'], { cwd: repoRoot, encoding: 'utf8' });
    fs.writeFileSync(path.join(cacheDir, 'running-set.json'), JSON.stringify({
      state: 'open', max_concurrent: 2,
      lane_group: { group_id: groupId, members: ['A', 'B'], baseline: 'recorded', write_union: ['ax.js', 'by.js'] },
      nodes: [ { id: 'A', role: 'tdd-guide', kind: 'write', group_id: groupId, baseline: 'recorded' } ],
    }, null, 2));
    const rec = runNode(repoRoot, ['reconcile-running-set', '--project', project, '--json'], DEFAULT);
    assert(rec.result === 'ok', '#680-B-neg: reconcile-running-set ok, got ' + JSON.stringify(rec));
    // Discrimination: the orphan is dropped, the live member/group baselines are NOT in the drop list.
    assert(Array.isArray(rec.orphanBaselinesDropped) && rec.orphanBaselinesDropped.includes('orphan')
      && !rec.orphanBaselinesDropped.includes('A') && !rec.orphanBaselinesDropped.includes(groupId),
      '#680-B-neg: only the orphan is dropped; the live member/group baselines are NOT, got ' + JSON.stringify(rec.orphanBaselinesDropped));
    // False-positive guard (holds pre- AND post-fix): the LIVE in_progress member baseline survives.
    assert(fs.existsSync(path.join(cacheDir, 'barrier-base-A')) && groupBaselineRefExists678(repoRoot, project, 'A'),
      '#680-B-neg: the LIVE in_progress member baseline (A, file + ref) is KEPT by the sweep');
    // False-positive guard: the LIVE lane_group group baseline survives.
    assert(fs.existsSync(groupBaselineFile678(cacheDir, groupId)) && groupBaselineRefExists678(repoRoot, project, groupId),
      '#680-B-neg: the LIVE lane_group group baseline (file + ref) is KEPT by the sweep');
    // And the co-present orphan really is gone (sweep active in the presence of live owners).
    assert(!fs.existsSync(path.join(cacheDir, 'barrier-base-orphan')),
      '#680-B-neg: the co-present orphan baseline is dropped while the live baselines are kept');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #680 Part B REPAIR (adversary R1 — the torn-Phase-3 LIVE-group-baseline drop): the orphan-baseline
  //   sweep gave the GROUP baseline exactly ONE keep-source — `running.lane_group.group_id`, added only
  //   inside `if (running)`. A group_id has NO ledger row, so the in_progress-ledger keep loop never
  //   covers it. Reproduced failing path: open-ready co-opens {A,B} → Phase-1 records the group baseline
  //   `barrier-base-lg-A-B` + both member baselines; Phase-2 flips A,B → in_progress AND persists the
  //   ledger; Phase-3 promotes the running-set journal via a NON-atomic writeFileSync (O_TRUNC). A crash
  //   during that Phase-3 write TRUNCATES running-set.json AFTER the ledger flip persisted → readRunningSet
  //   returns null. reconcile then keeps A,B member baselines (in_progress ledger) but — `running` null —
  //   never adds `lg-A-B`, so it DROPS the LIVE group baseline (file + ref). A,B stay in_progress and their
  //   eventual group barrier refuses `no_group_base` → corrupted in-flight run. This is NET-NEW sweep
  //   behavior → a regression. FIX: a `barrier-base-lg-*` candidate is dropped only when its deadness is
  //   authoritative — (`running` non-null and not the live group) OR (zero in_progress rows). When running
  //   is null AND ≥1 in_progress row exists, its group_id (`lg-<memberIds…>`) is unrecoverable (member ids
  //   contain hyphens), so the group baseline is KEPT (fail-safe under-reap).
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, project, planPath, cacheDir } = makeLaneRepo();
    const groupId = 'lg-A-B';
    // Phase-2 already flipped A,B → in_progress and persisted the ledger before the crash.
    let plan = fs.readFileSync(planPath, 'utf8');
    plan = plan.replace('| A | pending |', '| A | in_progress |').replace('| B | pending |', '| B | in_progress |');
    fs.writeFileSync(planPath, plan);
    // Phase-1 recorded the LIVE group baseline (file + ref) + both member baselines — all on disk.
    // --record-base writes a kernel record (the barrier baseline file AND its git ref) in its own
    // process and exits; the adaptive-node process that follows re-reads both from disk. A
    // hand-written baseline could not carry a real ref, so the handoff is the fixture.
    // spawn-class: durable-handoff
    execFileSync('node', [VALIDATOR, planPath, '--record-base', '--node-id', groupId, '--json'], { cwd: repoRoot, encoding: 'utf8' });
    // --record-base writes a kernel record (the barrier baseline file AND its git ref) in its own
    // process and exits; the adaptive-node process that follows re-reads both from disk. A
    // hand-written baseline could not carry a real ref, so the handoff is the fixture.
    // spawn-class: durable-handoff
    execFileSync('node', [VALIDATOR, planPath, '--record-base', '--node-id', 'A', '--json'], { cwd: repoRoot, encoding: 'utf8' });
    // --record-base writes a kernel record (the barrier baseline file AND its git ref) in its own
    // process and exits; the adaptive-node process that follows re-reads both from disk. A
    // hand-written baseline could not carry a real ref, so the handoff is the fixture.
    // spawn-class: durable-handoff
    execFileSync('node', [VALIDATOR, planPath, '--record-base', '--node-id', 'B', '--json'], { cwd: repoRoot, encoding: 'utf8' });
    // Torn Phase-3: running-set.json is ABSENT (the O_TRUNC write left no readable manifest).
    assert(!readRS(cacheDir), '#680-B-repair: precondition — running-set.json is absent (torn Phase-3 write)');
    assert(fs.existsSync(groupBaselineFile678(cacheDir, groupId)) && groupBaselineRefExists678(repoRoot, project, groupId),
      '#680-B-repair: precondition — the live group baseline (file + ref) is seeded before reconcile');

    const rec = runNode(repoRoot, ['reconcile-running-set', '--project', project, '--json'], DEFAULT);
    assert(rec.result === 'ok', '#680-B-repair: reconcile-running-set ok, got ' + JSON.stringify(rec));

    // POST-fix the LIVE group baseline (file + ref) SURVIVES (RED pre-fix: it was dropped → no_group_base
    // corruption on the eventual group barrier). running is torn + A,B are in_progress → the sweep cannot
    // prove the group dead, so it must KEEP `barrier-base-lg-A-B`.
    assert(fs.existsSync(groupBaselineFile678(cacheDir, groupId)) && groupBaselineRefExists678(repoRoot, project, groupId),
      '#680-B-repair: the LIVE group baseline (file + ref) is KEPT when running is torn but members are in_progress (dropped pre-fix → no_group_base corruption), got file=' + fs.existsSync(groupBaselineFile678(cacheDir, groupId)) + ' ref=' + groupBaselineRefExists678(repoRoot, project, groupId));
    assert(!(Array.isArray(rec.orphanBaselinesDropped) && rec.orphanBaselinesDropped.includes(groupId)),
      '#680-B-repair: the live group baseline is NOT reported dropped, got ' + JSON.stringify(rec.orphanBaselinesDropped));
    // The in_progress member baselines stay kept too (protected by the in_progress-ledger keep, unchanged).
    assert(fs.existsSync(path.join(cacheDir, 'barrier-base-A')) && fs.existsSync(path.join(cacheDir, 'barrier-base-B')),
      '#680-B-repair: the in_progress member baselines (A, B) are KEPT');
    assert(groupBaselineRefExists678(repoRoot, project, 'A') && groupBaselineRefExists678(repoRoot, project, 'B'),
      '#680-B-repair: the in_progress member baseline REFS (A, B) are KEPT');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // D437-MUTATION-GUARD-NOT-VACUOUS (#542 kill-switch): the kill-switch is NOT vacuous —
  //   KAOLA_PARALLEL_WRITES=0 must SUPPRESS the default-on co-open and fall back to the serial single
  //   open (one write, no group), so the second write never enters a group. Without an effective
  //   kill-switch this would co-open (default-on); asserting exactly-one-open proves the switch bites.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir } = makeLaneRepo();
    const open = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], SERIAL);
    assert(!open.laneGroup, 'D437-MUTATION-GUARD-NOT-VACUOUS: KAOLA_PARALLEL_WRITES=0 does NOT co-open a group');
    assert(Array.isArray(open.opened) && open.opened.length === 1, 'D437-MUTATION-GUARD-NOT-VACUOUS: kill-switch opens exactly one write (serial)');
    const rs = readRS(cacheDir);
    assert(!rs || !rs.lane_group, 'D437-MUTATION-GUARD-NOT-VACUOUS: no lane_group under the kill-switch — co-open is suppressed, not vacuous');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #666-ENOBUFS-TREE-HASH: computeCodeTreeHash (the finalize-check freshness key) walks
  //   snapshotWorktree -> `git ls-tree -r <tree>` over the FULL landable tree. Node's execFileSync
  //   defaults to a 1 MB maxBuffer on stdout; a tree whose ls-tree listing exceeds that (many
  //   tracked paths, or a few long ones) overflows it. The overflow is ENOBUFS, caught by
  //   computeCodeTreeHash's own try/catch, so it degrades SILENTLY to `null` (fail-closed to
  //   "stale, re-run") rather than crashing loudly — a real repo of this size just never gets a
  //   freshness hit. Build a synthetic tree whose ls-tree listing is just past 1 MB (many small
  //   empty files under long-ish names, no commit needed — computeCodeTreeHash only needs a git
  //   repo + a working tree) and assert a stable 64-hex sha256 comes back, not null.
  // -------------------------------------------------------------------------
  scenario(() => {
    const repoRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-666-enobufs-'));
    G.exec(repoRoot, ['init'], { stdio: ['ignore', 'ignore', 'ignore'] });
    G.exec(repoRoot, ['config', 'user.email', 'kw@test']);
    G.exec(repoRoot, ['config', 'user.name', 'kw']);
    G.exec(repoRoot, ['config', 'commit.gpgsign', 'false']);
    // 4200 empty files with a 196-char name each puts the `ls-tree -r` listing at ~1.05 MB — just
    // past Node's 1 MB default maxBuffer, not far past (fast to build: well under a second).
    const bigDir = path.join(repoRoot, 'bigdir');
    fs.mkdirSync(bigDir);
    for (let i = 0; i < 4200; i++) {
      fs.writeFileSync(path.join(bigDir, 'a'.repeat(190) + String(i).padStart(6, '0') + '.txt'), '');
    }
    const hash1 = planValidator.computeCodeTreeHash(repoRoot, 'test-project');
    assert(typeof hash1 === 'string' && /^[0-9a-f]{64}$/.test(hash1),
      '#666-ENOBUFS-TREE-HASH: computeCodeTreeHash returns a stable 64-hex sha256 over a >1MB ls-tree listing, got ' + JSON.stringify(hash1));
    // Stable across repeated calls (same tree -> same hash; also proves the run is deterministic,
    // not a fluke pass caused by OS-level buffer slack).
    const hash2 = planValidator.computeCodeTreeHash(repoRoot, 'test-project');
    assert(hash1 === hash2, '#666-ENOBUFS-TREE-HASH: repeated computeCodeTreeHash calls over the same big tree agree, got ' + JSON.stringify([hash1, hash2]));
    cleanup(repoRoot);
  });

  // =========================================================================
  // #463-LEG-PROVISION (Slice 2) — DORMANT per-leg `.kw` worktree provisioning for the write-lane
  // scheduler. Reuses the D-437 REAL-git harness above (makeLaneRepo / runNode / readRS / ledgerStatus
  // / cleanup; makeLaneRepo seeds .gitignore with `.kw/` so snapshotWorktree's `git add -A` never
  // stages a sibling leg). Legs are PROVISIONED (a real `git worktree add` per co-opened write member)
  // + telemetered + reconcile/teardown-aware, but NOTHING is written into them (S2 dormant). The
  // non-negotiable deliverable: legs require BOTH the KAOLA_LEG_ISOLATION toggle AND the per-run
  // --write-overlap-consent flag AND a formed lane group; absent any ⇒ flag-OFF byte-identical.
  // =========================================================================
  const LEG_ON = { KAOLA_LANE_CONTAINMENT: '1', KAOLA_LEG_ISOLATION: '1' };
  // Read `git worktree list --porcelain` at a repo and return the set of worktree paths.
  function worktreePaths(repoRoot) {
    let out = '';
    try { out = G.exec(repoRoot, ['worktree', 'list', '--porcelain'], { encoding: 'utf8' }); } catch (_) { return []; }
    return String(out).split('\n').filter(l => l.indexOf('worktree ') === 0).map(l => l.slice('worktree '.length).trim());
  }
  function branchExists(repoRoot, branch) {
    try { G.exec(repoRoot, ['rev-parse', '--verify', '--quiet', 'refs/heads/' + branch], { stdio: ['ignore', 'ignore', 'ignore'] }); return true; }
    catch (_) { return false; }
  }
  function timingsHas(cacheDir, id, event) {
    let txt = '';
    try { txt = fs.readFileSync(path.join(cacheDir, 'node-timings.jsonl'), 'utf8'); } catch (_) { return false; }
    for (const line of txt.split('\n')) {
      const s = line.trim(); if (!s) continue;
      let e; try { e = JSON.parse(s); } catch (_) { continue; }
      if (e && e.node === id && e.event === event) return true;
    }
    return false;
  }

  // -------------------------------------------------------------------------
  // LEG-PROVISION-ON: toggle + consent + a formed group ⇒ a real .kw leg per member (A,B), a kw/legs
  //   branch per member, a running-set lane_group.legs manifest with {legPath,legBranch,baseline}, and
  //   a `leg_opened` timing for each.  (RED-provable: drop the provisioning block ⇒ this block fails.)
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir } = makeLaneRepo();
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], LEG_ON);
    assert(r.result === 'ok', 'LEG-PROVISION-ON: open-ready ok, got ' + JSON.stringify(r));
    const wts = worktreePaths(repoRoot);
    const legA = path.join('.kw', 'legs', 'test-project', 'A');
    const legB = path.join('.kw', 'legs', 'test-project', 'B');
    assert(wts.some(p => p.endsWith(legA)), 'LEG-PROVISION-ON: .kw/legs/test-project/A worktree provisioned, got ' + JSON.stringify(wts));
    assert(wts.some(p => p.endsWith(legB)), 'LEG-PROVISION-ON: .kw/legs/test-project/B worktree provisioned, got ' + JSON.stringify(wts));
    assert(branchExists(repoRoot, 'kw/legs/test-project/A'), 'LEG-PROVISION-ON: branch kw/legs/test-project/A exists');
    assert(branchExists(repoRoot, 'kw/legs/test-project/B'), 'LEG-PROVISION-ON: branch kw/legs/test-project/B exists');
    const rs = readRS(cacheDir);
    assert(rs && rs.lane_group && rs.lane_group.legs, 'LEG-PROVISION-ON: running-set lane_group.legs present, got ' + JSON.stringify(rs && rs.lane_group));
    for (const id of ['A', 'B']) {
      const leg = rs.lane_group.legs[id];
      assert(leg && typeof leg.legPath === 'string' && leg.legPath.length > 0, 'LEG-PROVISION-ON: legs.' + id + '.legPath present');
      assert(leg && leg.legBranch === 'kw/legs/test-project/' + id, 'LEG-PROVISION-ON: legs.' + id + '.legBranch correct, got ' + (leg && leg.legBranch));
      assert(leg && typeof leg.baseline === 'string' && leg.baseline.length > 0, 'LEG-PROVISION-ON: legs.' + id + '.baseline present');
    }
    assert(timingsHas(cacheDir, 'A', 'leg_opened'), 'LEG-PROVISION-ON: leg_opened timing for A');
    assert(timingsHas(cacheDir, 'B', 'leg_opened'), 'LEG-PROVISION-ON: leg_opened timing for B');
    // S2 dormant (FIX-2, RED-provable): working_dir STAYS parent-side. Assert directly that NO opened
    // member's dispatch working_dir equals the leg path that WAS provisioned for that member (the real
    // S3-regression guard — the prior `indexOf('.kw')` check was vacuous because working_dir is always
    // null here). If a future edit set working_dir = legs[id].legPath, this fails.
    const provisionedLegPaths = new Set(['A', 'B'].map(id => rs.lane_group.legs[id] && rs.lane_group.legs[id].legPath).filter(Boolean));
    assert(provisionedLegPaths.size === 2, 'LEG-PROVISION-ON: two leg paths recorded for the dormancy guard');
    for (const n of (r.opened || [])) {
      const wd = n.dispatch && n.dispatch.working_dir;
      assert(!(wd && provisionedLegPaths.has(wd)), 'LEG-PROVISION-ON: ' + n.id + ' dispatch working_dir is NOT its provisioned leg path (S2 dormant), got ' + JSON.stringify(wd));
    }
    // #591: each opened co-open member's dispatch card carries ITS OWN leg_path + leg_branch (the routing
    //   fact lives in the per-member payload, not only the top-level laneGroup descriptor). Assert equal to
    //   the provisioned worktree/branch from the running-set legs manifest. (RED-provable: pre-#591 the
    //   dispatch was built with only the shared working_dir, so leg_path/leg_branch are absent.)
    assert((r.opened || []).length === 2, '#591: two co-open members opened');
    for (const n of (r.opened || [])) {
      const leg = rs.lane_group.legs[n.id];
      assert(leg && typeof leg.legPath === 'string', '#591: leg manifest present for ' + n.id);
      assert(n.dispatch && n.dispatch.leg_path === leg.legPath,
        '#591: ' + n.id + ' dispatch.leg_path == provisioned legPath, got ' + JSON.stringify(n.dispatch && n.dispatch.leg_path) + ' vs ' + JSON.stringify(leg.legPath));
      assert(n.dispatch && n.dispatch.leg_branch === leg.legBranch,
        '#591: ' + n.id + ' dispatch.leg_branch == provisioned legBranch, got ' + JSON.stringify(n.dispatch && n.dispatch.leg_branch) + ' vs ' + JSON.stringify(leg.legBranch));
      assert(n.dispatch.leg_branch === 'kw/legs/test-project/' + n.id, '#591: ' + n.id + ' dispatch.leg_branch canonical form');
    }
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #591-SERIAL-READ-NO-LEG-FIELDS (byte-identity guard): on the serial/read path (no lane group) an
  //   opened member's dispatch card carries NEITHER leg_path NOR leg_branch — conditionally attached like
  //   laneGroup, so serial/read open-ready output stays byte-identical to pre-#591. Raw-string probe on the
  //   opened array (no leg field ANYWHERE) plus a key-presence check on the dispatch object.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot } = makeLaneRepo();
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], SERIAL);
    assert(r.result === 'ok' && Array.isArray(r.opened) && r.opened.length === 1, '#591-SERIAL-READ-NO-LEG-FIELDS: serial open ok (single write), got ' + JSON.stringify(r.opened && r.opened.map(n => n.id)));
    const d = r.opened[0].dispatch;
    assert(d && !('leg_path' in d), '#591-SERIAL-READ-NO-LEG-FIELDS: serial dispatch has NO leg_path key, got ' + JSON.stringify(Object.keys(d)));
    assert(d && !('leg_branch' in d), '#591-SERIAL-READ-NO-LEG-FIELDS: serial dispatch has NO leg_branch key, got ' + JSON.stringify(Object.keys(d)));
    assert(JSON.stringify(r.opened).indexOf('"leg_path"') === -1 && JSON.stringify(r.opened).indexOf('"leg_branch"') === -1,
      '#591-SERIAL-READ-NO-LEG-FIELDS: no leg_path/leg_branch anywhere in the serial opened payload');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #821-LEG-EVIDENCE-FILE-ABS (lane-group dispatch card): a co-opened member's AUTHORITATIVE evidence
  //   artifact is the LEG's own copy (record-evidence --verify resolves it evidence_source:"leg"; the
  //   close measures it), but the card's bare project-relative evidence_file resolves against whatever
  //   worktree the reader is in — resolved against the PARENT it strands the deliverable there and the
  //   close fails evidence_shape_failed against the still-seeded leg copy. The card now carries
  //   evidence_file_abs (the leg copy as an ABSOLUTE path under leg_path) plus an
  //   evidence_cwd_resolution note (record-evidence --stdin persists the copy its cwd resolves).
  //   (RED-provable: pre-fix the card carries neither key.)
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir } = makeLaneRepo();
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], LEG_ON);
    assert(r.result === 'ok' && r.laneGroup, '#821 setup: {A,B} co-open into legs, got ' + JSON.stringify(r));
    const rs = readRS(cacheDir);
    assert((r.opened || []).length === 2, '#821: two co-open members opened');
    for (const n of (r.opened || [])) {
      const leg = rs.lane_group.legs[n.id];
      const relEvidence = 'kaola-workflow/test-project/.cache/' + n.id + '.md';
      // The project-relative hint is RETAINED (byte-compat); the absolute path is ADDITIVE.
      assert(n.dispatch.evidence_file === relEvidence,
        '#821: ' + n.id + ' evidence_file stays the project-qualified hint, got ' + JSON.stringify(n.dispatch.evidence_file));
      const abs = n.dispatch.evidence_file_abs;
      // Guard every subsequent use on abs being a string: on the pre-fix card the key is ABSENT, and
      // a RED-by-design assertion must FAIL, never THROW (an uncaught TypeError would abort the shard
      // and hide every other signal in it).
      const absOk = typeof abs === 'string' && path.isAbsolute(abs);
      assert(absOk,
        '#821: ' + n.id + ' evidence_file_abs is an ABSOLUTE path (absent pre-fix), got ' + JSON.stringify(abs));
      assert(absOk && abs === path.join(leg.legPath, relEvidence),
        '#821: ' + n.id + ' evidence_file_abs resolves under the member\'s OWN leg_path (leg_path + evidence_file), got '
        + JSON.stringify(abs) + ' want ' + JSON.stringify(path.join(leg.legPath, relEvidence)));
      assert(absOk && abs.indexOf(leg.legPath + path.sep) === 0,
        '#821: ' + n.id + ' evidence_file_abs is under leg_path ' + JSON.stringify(leg.legPath) + ', got ' + JSON.stringify(abs));
      // open-ready's kw-stub commit seeds the evidence stub BEFORE each leg branches, so the card's
      // absolute target is a REAL tracked file inside the leg the member can edit in place.
      assert(absOk && fs.existsSync(abs),
        '#821: ' + n.id + ' the seeded leg evidence copy EXISTS at evidence_file_abs (the kw-stub seed the leg inherits)');
      // The failure this issue filed: resolving the relative hint against the PARENT strands the deliverable.
      assert(absOk && abs !== path.join(repoRoot, relEvidence),
        '#821: ' + n.id + ' evidence_file_abs is NOT the parent-worktree resolution that stranded the deliverable');
      const note = n.dispatch.evidence_cwd_resolution;
      assert(typeof note === 'string' && note.length > 0,
        '#821: ' + n.id + ' evidence_cwd_resolution note present (absent pre-fix)');
      assert(/record-evidence --stdin/.test(String(note)) && /cwd/.test(String(note)),
        '#821: ' + n.id + ' the note documents the record-evidence --stdin cwd-resolution contract, got ' + JSON.stringify(note));
    }
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #821-SERIAL-NO-LEG-EVIDENCE-ABS (byte-identity guard): on the serial/read path (no lane group, no
  //   leg) an opened member's card carries NEITHER evidence_file_abs NOR evidence_cwd_resolution —
  //   both attach conditionally under leg_path (like #591's leg fields), so serial/read open-ready
  //   output stays byte-identical to pre-#821. Raw-string probe on the opened payload plus a
  //   key-presence check on the dispatch object.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot } = makeLaneRepo();
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], SERIAL);
    assert(r.result === 'ok' && Array.isArray(r.opened) && r.opened.length === 1, '#821-SERIAL: serial open ok (single write), got ' + JSON.stringify(r.opened && r.opened.map(n => n.id)));
    const d = r.opened[0].dispatch;
    assert(d && !('evidence_file_abs' in d), '#821-SERIAL: serial dispatch has NO evidence_file_abs key, got ' + JSON.stringify(Object.keys(d)));
    assert(d && !('evidence_cwd_resolution' in d), '#821-SERIAL: serial dispatch has NO evidence_cwd_resolution key, got ' + JSON.stringify(Object.keys(d)));
    assert(JSON.stringify(r.opened).indexOf('"evidence_file_abs"') === -1 && JSON.stringify(r.opened).indexOf('"evidence_cwd_resolution"') === -1,
      '#821-SERIAL: no evidence_file_abs/evidence_cwd_resolution anywhere in the serial opened payload');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #821-BUILDDISPATCH-UNIT: the derivation itself, direct-call — relative join under leg_path,
  //   absolute passthrough, the evidence_file-absent conditional shape, and the no-leg byte-identity arm.
  // -------------------------------------------------------------------------
  scenario(() => {
    const nodeInfo = { id: 'A', role: 'tdd-guide', model: 'standard', declared_write_set: 'ax.js' };
    const legPath = path.join(os.tmpdir(), 'kw-821-leg', 'A');
    const rel = 'kaola-workflow/test-project/.cache/A.md';
    const d1 = buildDispatch(nodeInfo, { nonce: 'nonce12345678', evidence_file: rel, leg_path: legPath, leg_branch: 'kw/legs/test-project/A' });
    assert(d1.evidence_file_abs === path.join(legPath, rel),
      '#821-UNIT: a project-relative evidence_file joins UNDER leg_path, got ' + JSON.stringify(d1.evidence_file_abs));
    assert(typeof d1.evidence_cwd_resolution === 'string' && d1.evidence_cwd_resolution.length > 0,
      '#821-UNIT: the cwd-resolution note rides the leg_path arm');
    const absTarget = path.join(legPath, rel);
    const d2 = buildDispatch(nodeInfo, { nonce: 'nonce12345678', evidence_file: absTarget, leg_path: legPath, leg_branch: 'kw/legs/test-project/A' });
    assert(d2.evidence_file_abs === absTarget,
      '#821-UNIT: an ALREADY-absolute evidence_file passes through unchanged, got ' + JSON.stringify(d2.evidence_file_abs));
    const d3 = buildDispatch(nodeInfo, { nonce: 'nonce12345678', leg_path: legPath, leg_branch: 'kw/legs/test-project/A' });
    assert(!('evidence_file_abs' in d3),
      '#821-UNIT: no evidence_file ⇒ NO evidence_file_abs key (conditionally attached, never null-valued)');
    assert(typeof d3.evidence_cwd_resolution === 'string' && d3.evidence_cwd_resolution.length > 0,
      '#821-UNIT: the cwd-resolution note attaches with leg_path even without an evidence_file');
    const d4 = buildDispatch(nodeInfo, { nonce: 'nonce12345678', evidence_file: rel });
    assert(!('evidence_file_abs' in d4) && !('evidence_cwd_resolution' in d4),
      '#821-UNIT: no leg_path ⇒ NEITHER #821 key (serial/read byte-identity)');
  });

  // -------------------------------------------------------------------------
  // #692-LEG-UPSTREAM-EVIDENCE-ABSOLUTE: a co-opened WRITE member provisioned INTO an isolated leg
  //   carries a PARENT-sourced upstream_evidence pointer (seed = a COMPLETE producer, code-explorer,
  //   merged into the parent tree — NOT a live leg). Its dispatch.upstream_evidence[].path MUST be an
  //   ABSOLUTE path under the PARENT worktree: a fresh leg worktree carries no sibling .cache evidence,
  //   so the pre-#692 project-relative hint ('kaola-workflow/test-project/.cache/seed.md') resolved
  //   (empty) from the briefed `cd <leg_path>` cwd, and a strict leg agent could not bind the upstream
  //   nonce. (RED-provable: revert the openIntoLeg absolutization ⇒ up.path is the project-relative
  //   string ⇒ isAbsolute / under-parent / not-under-leg assertions all fail.) Distinct from #622-MIXED,
  //   which covers a LIVE-leg upstream (evidenceSource='leg'); this is the parent-merged upstream on the
  //   leg-OPEN side — the exact default co-open-with-upstream shape the field bug hit.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir } = makeLaneRepo();
    // seed is a COMPLETE producer — its evidence lives in the PARENT worktree .cache by construction.
    // makeLaneRepo does not seed it; write it so the "file exists at that path" assertion is real.
    fs.writeFileSync(path.join(cacheDir, 'seed.md'), 'evidence-binding: seed 0123456789ab\nfindings: seed producer output\n');
    // getRoot() (git rev-parse --show-toplevel) realpath-resolves symlinks (macOS /var → /private/var),
    // so the CLI-emitted parent path is under realpath(repoRoot). Compare against the same resolution.
    const parentRoot = fs.realpathSync(repoRoot);
    const expectedParentSeed = path.join(parentRoot, 'kaola-workflow', 'test-project', '.cache', 'seed.md');
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(r.result === 'ok' && r.laneGroup && Array.isArray(r.opened) && r.opened.length === 2,
      '#692-LEG-UPSTREAM-EVIDENCE-ABSOLUTE: {A,B} co-open into legs, got ' + JSON.stringify(r));
    const rs = readRS(cacheDir);
    for (const n of r.opened) {
      const leg = rs.lane_group.legs[n.id];
      assert(leg && typeof leg.legPath === 'string' && leg.legPath.length > 0, '#692: leg provisioned for ' + n.id);
      const ue = n.dispatch && Array.isArray(n.dispatch.upstream_evidence) ? n.dispatch.upstream_evidence : null;
      const up = ue && ue.find(e => e.node_id === 'seed');
      assert(up, '#692: ' + n.id + ' dispatch carries upstream_evidence for the completed producer seed, got ' + JSON.stringify(ue));
      assert(up.role === 'code-explorer', '#692: seed upstream is a producer role (makes the upstream_read binding load-bearing), got ' + JSON.stringify(up.role));
      // ★ THE #692 FIX: the parent-sourced upstream path is ABSOLUTE, under the PARENT worktree — never
      //   the project-relative hint that a leg cwd cannot resolve.
      assert(path.isAbsolute(up.path), '#692: ' + n.id + ' upstream_evidence.path is ABSOLUTE (was project-relative pre-fix), got ' + JSON.stringify(up.path));
      assert(up.path === expectedParentSeed, '#692: ' + n.id + ' upstream_evidence.path points at the PARENT worktree evidence, got ' + JSON.stringify(up.path) + ' want ' + JSON.stringify(expectedParentSeed));
      assert(up.path !== 'kaola-workflow/test-project/.cache/seed.md', '#692: ' + n.id + ' upstream_evidence.path is NOT the leg-unresolvable project-relative string');
      assert(!up.path.startsWith(leg.legPath + path.sep), '#692: ' + n.id + ' upstream_evidence.path does NOT resolve under its own leg (the leg carries no sibling .cache), got ' + JSON.stringify(up.path));
      assert(fs.existsSync(up.path), '#692: ' + n.id + ' upstream_evidence file EXISTS at the parent path, got ' + JSON.stringify(up.path));
    }
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // ★ LEG-SERIAL-NO-LEGS-BYTE-IDENTITY (#542 kill-switch, non-negotiable): the serial path provisions
  //   NO legs. After #542 (D-542-01) co-open + legs are DEFAULT-ON; the leg-free serial path is reached
  //   only via the kill-switch KAOLA_PARALLEL_WRITES=0. Run the same repo/plan under the kill-switch with
  //   the legacy toggles/consent varied — all must serial-degrade with NEITHER any leg: no .kw/legs
  //   worktree, no lane_group.legs key (raw-string probe), no leg_opened timing. (The legacy toggles are
  //   no-ops for co-open now; only the kill-switch suppresses it.)
  // -------------------------------------------------------------------------
  scenario(() => {
    const cases = [
      { label: 'kill-switch, no toggle, no consent', env: SERIAL, args: ['open-ready', '--project', 'test-project', '--json'] },
      { label: 'kill-switch + legacy leg-isolation toggle (no-op), NO consent', env: { KAOLA_PARALLEL_WRITES: '0', KAOLA_LANE_CONTAINMENT: '1', KAOLA_LEG_ISOLATION: '1' }, args: ['open-ready', '--project', 'test-project', '--json'] },
      // The symmetric off-combo — kill-switch with the consent flag present (still no legs: serial wins).
      { label: 'kill-switch + consent flag (still serial)', env: SERIAL, args: ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'] },
    ];
    for (const c of cases) {
      const { repoRoot, cacheDir } = makeLaneRepo();
      const r = runNode(repoRoot, c.args, c.env);
      assert(r.result === 'ok', 'LEG-SERIAL-NO-LEGS [' + c.label + ']: open-ready ok, got ' + JSON.stringify(r));
      const wts = worktreePaths(repoRoot);
      assert(!wts.some(p => p.indexOf(path.join('.kw', 'legs')) !== -1), 'LEG-SERIAL-NO-LEGS [' + c.label + ']: NO .kw/legs worktree provisioned, got ' + JSON.stringify(wts));
      const rs = readRS(cacheDir);
      // Raw-string probe: the serial byte-identity guarantee is "no `legs` key anywhere in running-set.json".
      assert(JSON.stringify(rs).indexOf('"legs"') === -1, 'LEG-SERIAL-NO-LEGS [' + c.label + ']: running-set.json carries NO "legs" key');
      assert(!(rs && rs.lane_group && rs.lane_group.legs), 'LEG-SERIAL-NO-LEGS [' + c.label + ']: lane_group has no legs manifest');
      assert(!timingsHas(cacheDir, 'A', 'leg_opened') && !timingsHas(cacheDir, 'B', 'leg_opened'), 'LEG-SERIAL-NO-LEGS [' + c.label + ']: no leg_opened timing');
      cleanup(repoRoot);
    }
  });

  // -------------------------------------------------------------------------
  // LEG-RECONCILE-TEARDOWN: provision legs (ON), then DROP one member from running-set (so reconcile
  //   rolls it back) and run reconcile-running-set — assert the dropped member's worktree AND branch
  //   are gone (strict-order teardown) and the survivor's leg remains.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir } = makeLaneRepo();
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], LEG_ON);
    assert(r.result === 'ok' && r.laneGroup, 'LEG-RECONCILE-TEARDOWN: setup co-open ok');
    // Simulate a member drop: mark B's ledger row back to pending and flag B `opening` so reconcile
    // treats the set as mid-open and rolls B back (its ledger no longer in_progress).
    const planPath = path.join(repoRoot, 'kaola-workflow', 'test-project', 'workflow-plan.md');
    let plan = fs.readFileSync(planPath, 'utf8');
    const ledgerStart = plan.indexOf('## Node Ledger');
    const head = plan.slice(0, ledgerStart), tail = plan.slice(ledgerStart);
    plan = head + tail.replace(/^\|\s*B\s*\|\s*in_progress\s*\|/m, '| B | pending |');
    fs.writeFileSync(planPath, plan);
    const rs0 = readRS(cacheDir);
    rs0.state = 'opening';
    rs0.nodes = rs0.nodes.map(n => (n.id === 'B' ? { ...n, opening: true } : n));
    fs.writeFileSync(path.join(cacheDir, 'running-set.json'), JSON.stringify(rs0, null, 2));
    const rec = runNode(repoRoot, ['reconcile-running-set', '--project', 'test-project', '--json'], LEG_ON);
    assert(rec.result === 'ok', 'LEG-RECONCILE-TEARDOWN: reconcile ok, got ' + JSON.stringify(rec));
    const wts = worktreePaths(repoRoot);
    assert(!wts.some(p => p.endsWith(path.join('.kw', 'legs', 'test-project', 'B'))), 'LEG-RECONCILE-TEARDOWN: B leg worktree torn down, got ' + JSON.stringify(wts));
    assert(!branchExists(repoRoot, 'kw/legs/test-project/B'), 'LEG-RECONCILE-TEARDOWN: B leg branch -D (strict-order teardown)');
    assert(wts.some(p => p.endsWith(path.join('.kw', 'legs', 'test-project', 'A'))), 'LEG-RECONCILE-TEARDOWN: survivor A leg worktree remains');
    assert(branchExists(repoRoot, 'kw/legs/test-project/A'), 'LEG-RECONCILE-TEARDOWN: survivor A leg branch remains');
    const rs1 = readRS(cacheDir);
    assert(rs1 && rs1.lane_group && rs1.lane_group.legs && rs1.lane_group.legs.A && !rs1.lane_group.legs.B,
      'LEG-RECONCILE-TEARDOWN: legs manifest keeps A, drops B, got ' + JSON.stringify(rs1 && rs1.lane_group && rs1.lane_group.legs));
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // LEG-ORPHAN-SWEEP: provision legs (ON, healthy set), then manually `git worktree add` an extra
  //   .kw/legs/test-project/orphan with NO running-set member; run reconcile and assert the orphan is
  //   swept (worktree + branch gone) while the live legs A,B remain. (The sweep is HOISTED above the
  //   not_opening early-return so it runs on a healthy set.)
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir } = makeLaneRepo();
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], LEG_ON);
    assert(r.result === 'ok' && r.laneGroup, 'LEG-ORPHAN-SWEEP: setup co-open ok');
    // Manually provision an orphan leg under the same band with no running-set member.
    const orphanPath = path.join(repoRoot, '.kw', 'legs', 'test-project', 'orphan');
    G.exec(repoRoot, ['worktree', 'add', '-b', 'kw/legs/test-project/orphan', '--', orphanPath, 'HEAD'], { stdio: ['ignore', 'ignore', 'ignore'] });
    assert(worktreePaths(repoRoot).some(p => p.endsWith(path.join('.kw', 'legs', 'test-project', 'orphan'))), 'LEG-ORPHAN-SWEEP: orphan provisioned for the test');
    const rec = runNode(repoRoot, ['reconcile-running-set', '--project', 'test-project', '--json'], LEG_ON);
    assert(rec.result === 'ok', 'LEG-ORPHAN-SWEEP: reconcile ok, got ' + JSON.stringify(rec));
    const wts = worktreePaths(repoRoot);
    assert(!wts.some(p => p.endsWith(path.join('.kw', 'legs', 'test-project', 'orphan'))), 'LEG-ORPHAN-SWEEP: orphan leg worktree swept, got ' + JSON.stringify(wts));
    assert(!branchExists(repoRoot, 'kw/legs/test-project/orphan'), 'LEG-ORPHAN-SWEEP: orphan leg branch swept');
    assert(wts.some(p => p.endsWith(path.join('.kw', 'legs', 'test-project', 'A'))), 'LEG-ORPHAN-SWEEP: live leg A retained');
    assert(wts.some(p => p.endsWith(path.join('.kw', 'legs', 'test-project', 'B'))), 'LEG-ORPHAN-SWEEP: live leg B retained');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // LEG-DANGLING-BRANCH-REUSE: provisionLeg must REUSE a dangling leg branch (worktree gone, branch
  //   still present from a swallowed fail-soft `branch -D`) instead of refusing — the crash-resume
  //   no-wedge guarantee. Simulate: provision A's branch + worktree, remove ONLY the worktree (leave
  //   the branch), then re-provision the SAME leg via the exported provisionLeg seam.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot } = makeLaneRepo();
    const node = require(path.join(__dirname, 'kaola-workflow-adaptive-node.js'));
    const legPath = path.join(repoRoot, '.kw', 'legs', 'test-project', 'A');
    const legBranch = 'kw/legs/test-project/A';
    const base = G.exec(repoRoot, ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim();
    const first = node.provisionLeg(repoRoot, legPath, legBranch, base);
    assert(first.ok, 'LEG-DANGLING-BRANCH-REUSE: first provision ok');
    // Remove the worktree but leave the branch dangling (the swallowed `branch -D` scenario).
    G.exec(repoRoot, ['worktree', 'remove', '--force', legPath], { stdio: ['ignore', 'ignore', 'ignore'] });
    assert(branchExists(repoRoot, legBranch), 'LEG-DANGLING-BRANCH-REUSE: branch dangles after worktree-only removal');
    const second = node.provisionLeg(repoRoot, legPath, legBranch, base);
    assert(second.ok && second.reusedBranch, 'LEG-DANGLING-BRANCH-REUSE: re-provision REUSES the dangling branch (no wedge), got ' + JSON.stringify(second));
    assert(worktreePaths(repoRoot).some(p => p.endsWith(path.join('.kw', 'legs', 'test-project', 'A'))), 'LEG-DANGLING-BRANCH-REUSE: worktree re-attached to the reused branch');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // ★ LEG-CLEAN-COMPLETION-NO-LEAK (FIX-1a, RED-provable): provision legs (ON), close A (deferred) then
  //   close B (last → group_passed). On the clean group completion the lane_group key is cleared, so the
  //   reconcile-gated sweep can never reclaim these legs — close-node MUST tear them down primarily.
  //   Assert NO leg worktree AND NO kw/legs branch survives after the group completes. (RED-provable:
  //   drop the close-node teardown ⇒ the leg worktrees/branches leak ⇒ this block fails.)
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir, planPath } = makeLaneRepo();
    const open = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], LEG_ON);
    assert(open.result === 'ok' && open.laneGroup, 'LEG-CLEAN-COMPLETION-NO-LEAK: setup co-open ok');
    assert(worktreePaths(repoRoot).filter(p => p.indexOf(path.join('.kw', 'legs')) !== -1).length === 2, 'LEG-CLEAN-COMPLETION-NO-LEAK: two legs provisioned at setup');
    writeEvidence(cacheDir, 'A');
    writeEvidence(cacheDir, 'B');
    // #463 Slice 4: routing is LIVE — each member's work lands in its OWN leg (not the parent). The
    // synthesizer merges the legs at the last-member close → group_passed via the COMMIT-based union barrier.
    fs.writeFileSync(path.join(repoRoot, '.kw', 'legs', 'test-project', 'A', 'ax.js'), '// A in-lane (leg)\n');
    fs.writeFileSync(path.join(repoRoot, '.kw', 'legs', 'test-project', 'B', 'by.js'), '// B in-lane (leg)\n');
    const rA = runNode(repoRoot, ['close-node', '--node-id', 'A', '--project', 'test-project', '--json'], LEG_ON);
    assert(rA.result === 'ok' && rA.barrier === 'deferred_to_group', 'LEG-CLEAN-COMPLETION-NO-LEAK: A deferred ok, got ' + JSON.stringify(rA));
    const rB = runNode(repoRoot, ['close-node', '--node-id', 'B', '--project', 'test-project', '--json'], LEG_ON);
    assert(rB.result === 'ok' && rB.barrier === 'group_passed', 'LEG-CLEAN-COMPLETION-NO-LEAK: B group_passed, got ' + JSON.stringify(rB));
    assert(rB.synthesized === true && typeof rB.mergeCommit === 'string' && rB.mergeCommit.length >= 7, 'LEG-CLEAN-COMPLETION-NO-LEAK: B reports the synthesizer merge commit, got ' + JSON.stringify(rB));
    assert(ledgerStatus(planPath, 'A') === 'complete' && ledgerStatus(planPath, 'B') === 'complete', 'LEG-CLEAN-COMPLETION-NO-LEAK: both complete');
    const wts = worktreePaths(repoRoot);
    assert(!wts.some(p => p.indexOf(path.join('.kw', 'legs')) !== -1), 'LEG-CLEAN-COMPLETION-NO-LEAK: NO leg worktree survives clean completion, got ' + JSON.stringify(wts));
    assert(!branchExists(repoRoot, 'kw/legs/test-project/A'), 'LEG-CLEAN-COMPLETION-NO-LEAK: A leg branch torn down on completion');
    assert(!branchExists(repoRoot, 'kw/legs/test-project/B'), 'LEG-CLEAN-COMPLETION-NO-LEAK: B leg branch torn down on completion');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #593-AC1 (RED→GREEN, real-git co-open lifecycle): a two-node write antichain whose sets are
  //   exact-file-DISJOINT but share a NON-shared coarse area (both under plugins/, area 'plugins' ∉
  //   SHARED_INFRA ⇒ classifier {red, coarse}). Pre-#593 writeOverlapRelaxable required policy+consent
  //   for coarse, so open-ready SERIAL-DEGRADED (no lane_group). Post-#593 coarse co-opens BY DEFAULT
  //   under the SAME retained net as shared-infra (post-dominating code-reviewer gate + no PROTECTED
  //   file), with NO --write-overlap-consent. Full lifecycle: co-open → per-leg work → close A
  //   (deferred) → close B (last ⇒ octopus-merge union barrier / group_passed) → BOTH legs on HEAD.
  //   RED-provable: on pre-#593 code the setup co-open assert fails (open.laneGroup is falsy).
  // -------------------------------------------------------------------------
  scenario(() => {
    const COARSE_A = 'plugins/kaola-workflow-gitlab/scripts/pa.js';
    const COARSE_B = 'plugins/kaola-workflow-gitea/scripts/pb.js';
    const { repoRoot, cacheDir, planPath } = makeLaneRepo({ aSet: COARSE_A, bSet: COARSE_B });
    // DEFAULT env (no toggle), NO --write-overlap-consent, NO write_overlap_policy in the plan.
    const open = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(open.result === 'ok' && open.laneGroup && Array.isArray(open.laneGroup.members) && open.laneGroup.members.includes('A') && open.laneGroup.members.includes('B'),
      '#593-AC1: coarse exact-disjoint (both plugins/) co-opens [A,B] BY DEFAULT (no consent) under the net, got ' + JSON.stringify(open.laneGroup || open));
    assert(Array.isArray(open.opened) && open.opened.length === 2, '#593-AC1: both writes co-opened, got ' + JSON.stringify(open.opened && open.opened.map(n => n.id)));
    const rsOpen = readRS(cacheDir);
    assert(rsOpen && rsOpen.lane_group && rsOpen.lane_group.legs && rsOpen.lane_group.legs.A && rsOpen.lane_group.legs.B,
      '#593-AC1: co-open ⟹ legs provisioned for every member, got ' + JSON.stringify(rsOpen && rsOpen.lane_group));
    // Per-leg work → close A (deferred) → close B (octopus-merge union barrier at the last close).
    writeEvidence(cacheDir, 'A');
    writeEvidence(cacheDir, 'B');
    for (const [id, rel] of [['A', COARSE_A], ['B', COARSE_B]]) {
      const legFile = path.join(repoRoot, '.kw', 'legs', 'test-project', id, rel);
      fs.mkdirSync(path.dirname(legFile), { recursive: true });
      fs.writeFileSync(legFile, '// ' + id + ' in-lane (leg)\n');
    }
    const rA = runNode(repoRoot, ['close-node', '--node-id', 'A', '--project', 'test-project', '--json'], DEFAULT);
    assert(rA.result === 'ok' && rA.barrier === 'deferred_to_group', '#593-AC1: A deferred to the group barrier, got ' + JSON.stringify(rA));
    const rB = runNode(repoRoot, ['close-node', '--node-id', 'B', '--project', 'test-project', '--json'], DEFAULT);
    assert(rB.result === 'ok' && rB.barrier === 'group_passed' && rB.synthesized === true,
      '#593-AC1: B closes via the group (octopus-merge) union barrier ⇒ group_passed + synthesized, got ' + JSON.stringify(rB));
    const head = G.exec(repoRoot, ['ls-tree', '-r', '--name-only', 'HEAD'], { encoding: 'utf8' });
    assert(head.includes(COARSE_A) && head.includes(COARSE_B),
      '#593-AC1: BOTH legs\' files reach HEAD after the union barrier merge, got ' + JSON.stringify(head.split('\n').filter(Boolean)));
    assert(ledgerStatus(planPath, 'A') === 'complete' && ledgerStatus(planPath, 'B') === 'complete', '#593-AC1: both members complete');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #593-AC6 (serial byte-identity): the SAME coarse frontier under KAOLA_PARALLEL_WRITES=0 forces the
  //   serial single-write path — NO lane_group, exactly ONE write opened, the other stays pending. The
  //   #593 default-relax is fully suppressed by the explicit kill-switch (byte-identical serial shape).
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir, planPath } = makeLaneRepo({ aSet: 'plugins/kaola-workflow-gitlab/scripts/qa.js', bSet: 'plugins/kaola-workflow-gitea/scripts/qb.js' });
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], SERIAL);
    assert(r.result === 'ok', '#593-AC6: open-ready ok under KAOLA_PARALLEL_WRITES=0, got ' + JSON.stringify(r));
    assert(!r.laneGroup, '#593-AC6: NO laneGroup for a coarse frontier under KAOLA_PARALLEL_WRITES=0 (serial kill-switch)');
    assert(Array.isArray(r.opened) && r.opened.length === 1, '#593-AC6: exactly ONE write opened (serial), got ' + JSON.stringify(r.opened && r.opened.map(n => n.id)));
    const rs = readRS(cacheDir);
    assert(!rs || !rs.lane_group, '#593-AC6: running-set has no lane_group key (serial byte-identity)');
    assert(ledgerStatus(planPath, r.opened[0].id) === 'in_progress', '#593-AC6: the one opened write is in_progress');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #593-AC2-NET2 (runtime net): a coarse frontier with a PROTECTED concrete file in one set does NOT
  //   co-open even BY DEFAULT — NET-2 blocks at every tier — so open-ready SERIAL-DEGRADES (no
  //   lane_group, exactly one write opened). PROTECTED stays blocking; no default-relax bypasses it.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir } = makeLaneRepo({ aSet: 'plugins/kaola-workflow-gitlab/package-lock.json', bSet: 'plugins/kaola-workflow-gitea/scripts/rb.js' });
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(r.result === 'ok', '#593-AC2-NET2: open-ready ok (serial-degrade), got ' + JSON.stringify(r));
    assert(!r.laneGroup, '#593-AC2-NET2: a PROTECTED file in the coarse pair blocks co-open (NET-2) ⇒ NO laneGroup, got ' + JSON.stringify(r.laneGroup));
    assert(Array.isArray(r.opened) && r.opened.length === 1, '#593-AC2-NET2: serial-degrade opens exactly ONE write, got ' + JSON.stringify(r.opened && r.opened.map(n => n.id)));
    const rs = readRS(cacheDir);
    assert(!rs || !rs.lane_group, '#593-AC2-NET2: running-set has no lane_group (serial-degrade)');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // ★ #552-CRASH-WINDOW-LEDGER-ISLAST (RED-provable on the ledger-derived isLast fix): closeGroupMember
  //   flips the closing member's ledger row to `complete` in ONE write, THEN records closed_members +
  //   drops the node from the running set in a SECOND, non-atomic write. A crash between them leaves a
  //   member ledger-TERMINAL but ABSENT from closed_members (and still in running.nodes). Reading isLast
  //   from closed_members would then make the GENUINE last member mis-compute isLast=false, DEFER forever,
  //   and NEVER run the synthesizer → the other legs' committed work is silently never merged. The fix
  //   derives isLast from the LEDGER, so the last member still detects it is last. This scenario resumes
  //   WITHOUT reconcile (the ledger is the only consistent signal) and asserts B still synthesizes.
  //   RED-provable: revert the ledger-derived isLast ⇒ rB.barrier === 'deferred_to_group' ⇒ this fails.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir, planPath } = makeLaneRepo();
    const open = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], LEG_ON);
    assert(open.result === 'ok' && open.laneGroup, '#552-CRASH-WINDOW-LEDGER-ISLAST: setup co-open ok');
    const rsOpen = readRS(cacheDir);
    const aNode = (rsOpen.nodes || []).find(n => n.id === 'A');
    assert(aNode, '#552-CRASH-WINDOW-LEDGER-ISLAST: A present in the open running set');
    writeEvidence(cacheDir, 'A');
    writeEvidence(cacheDir, 'B');
    fs.writeFileSync(path.join(repoRoot, '.kw', 'legs', 'test-project', 'A', 'ax.js'), '// A in-lane (leg) — must survive the crash window\n');
    fs.writeFileSync(path.join(repoRoot, '.kw', 'legs', 'test-project', 'B', 'by.js'), '// B in-lane (leg)\n');
    // Close A → deferred (the COMPLETED close: ledger A complete, closed_members=[A], A dropped from nodes).
    const rA = runNode(repoRoot, ['close-node', '--node-id', 'A', '--project', 'test-project', '--json'], LEG_ON);
    assert(rA.result === 'ok' && rA.barrier === 'deferred_to_group', '#552-CRASH-WINDOW-LEDGER-ISLAST: A deferred ok, got ' + JSON.stringify(rA));
    // SIMULATE THE CRASH WINDOW: roll the running-set BACK to the pre-2nd-write state (A still in nodes,
    // closed_members WITHOUT A) while A's ledger row stays `complete` and A's leg stays in the manifest.
    const rsCrash = readRS(cacheDir);
    rsCrash.nodes = [aNode, ...(rsCrash.nodes || []).filter(n => n.id !== 'A')];
    if (rsCrash.lane_group) rsCrash.lane_group.closed_members = (rsCrash.lane_group.closed_members || []).filter(id => id !== 'A');
    fs.writeFileSync(path.join(cacheDir, 'running-set.json'), JSON.stringify(rsCrash, null, 2));
    assert(ledgerStatus(planPath, 'A') === 'complete', '#552-CRASH-WINDOW-LEDGER-ISLAST: A ledger stays complete across the window');
    assert(!(rsCrash.lane_group.closed_members || []).includes('A'), '#552-CRASH-WINDOW-LEDGER-ISLAST: closed_members is stale (A stripped) for the test');
    // Close B with the stale closed_members — the ledger-derived isLast must still mark B as LAST.
    const rB = runNode(repoRoot, ['close-node', '--node-id', 'B', '--project', 'test-project', '--json'], LEG_ON);
    assert(rB.result === 'ok' && rB.barrier === 'group_passed',
      '#552-CRASH-WINDOW-LEDGER-ISLAST: B detected LAST via the LEDGER despite stale closed_members ⇒ group_passed (NOT deferred), got ' + JSON.stringify(rB));
    assert(rB.synthesized === true && typeof rB.mergeCommit === 'string' && rB.mergeCommit.length >= 7,
      '#552-CRASH-WINDOW-LEDGER-ISLAST: B synthesizes + merges (no silent loss), got ' + JSON.stringify(rB));
    // The commit-union group barrier (group_passed) already enforces per-leg-head ancestor inclusion for
    // BOTH legs; cross-check concretely that A's committed leg file reached HEAD (the no-loss invariant).
    const head1 = G.exec(repoRoot, ['ls-tree', '-r', '--name-only', 'HEAD'], { encoding: 'utf8' });
    assert(head1.includes('ax.js') && head1.includes('by.js'),
      '#552-CRASH-WINDOW-LEDGER-ISLAST: BOTH legs\' files on HEAD after synthesis (ax.js from the crash-window member), got ' + JSON.stringify(head1.split('\n').filter(Boolean)));
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // ★ #552-CRASH-WINDOW-RECONCILE-HEAL (RED-provable on the reconcile self-heal + leg-retention fix): the
  //   normal resume path runs reconcile-running-set first. For the SAME crash window, reconcile must (a)
  //   SELF-HEAL closed_members (re-add the close-direction terminal member) and (b) RETAIN that member's
  //   leg (NOT tear it down) so the eventual last-member synthesizer can merge it. Pre-fix, reconcile's
  //   surviving-group teardown loop tore down the close-direction member's leg + dropped it from the
  //   manifest → the synthesizer omits it → committed work permanently lost. RED-provable: re-add `...closed`
  //   to the reconcile `departing` set ⇒ A's leg is torn down ⇒ ax.js missing from HEAD ⇒ this fails.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir, planPath } = makeLaneRepo();
    const open = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], LEG_ON);
    assert(open.result === 'ok' && open.laneGroup, '#552-CRASH-WINDOW-RECONCILE-HEAL: setup co-open ok');
    const rsOpen = readRS(cacheDir);
    const aNode = (rsOpen.nodes || []).find(n => n.id === 'A');
    writeEvidence(cacheDir, 'A');
    writeEvidence(cacheDir, 'B');
    fs.writeFileSync(path.join(repoRoot, '.kw', 'legs', 'test-project', 'A', 'ax.js'), '// A in-lane (leg) — must survive reconcile\n');
    fs.writeFileSync(path.join(repoRoot, '.kw', 'legs', 'test-project', 'B', 'by.js'), '// B in-lane (leg)\n');
    const rA = runNode(repoRoot, ['close-node', '--node-id', 'A', '--project', 'test-project', '--json'], LEG_ON);
    assert(rA.result === 'ok' && rA.barrier === 'deferred_to_group', '#552-CRASH-WINDOW-RECONCILE-HEAL: A deferred ok, got ' + JSON.stringify(rA));
    // Crash window: A back in nodes, A stripped from closed_members, ledger A complete, A leg retained.
    const rsCrash = readRS(cacheDir);
    rsCrash.nodes = [aNode, ...(rsCrash.nodes || []).filter(n => n.id !== 'A')];
    if (rsCrash.lane_group) rsCrash.lane_group.closed_members = (rsCrash.lane_group.closed_members || []).filter(id => id !== 'A');
    fs.writeFileSync(path.join(cacheDir, 'running-set.json'), JSON.stringify(rsCrash, null, 2));
    assert(rsCrash.lane_group.legs && rsCrash.lane_group.legs.A, '#552-CRASH-WINDOW-RECONCILE-HEAL: A leg in the manifest pre-reconcile');
    // RECONCILE: self-heal closed_members + RETAIN A's leg.
    const rec = runNode(repoRoot, ['reconcile-running-set', '--project', 'test-project', '--json'], LEG_ON);
    assert(rec.result === 'ok', '#552-CRASH-WINDOW-RECONCILE-HEAL: reconcile ok, got ' + JSON.stringify(rec));
    const rsHealed = readRS(cacheDir);
    assert(rsHealed && rsHealed.lane_group && Array.isArray(rsHealed.lane_group.closed_members) && rsHealed.lane_group.closed_members.includes('A'),
      '#552-CRASH-WINDOW-RECONCILE-HEAL: reconcile SELF-HEALS closed_members (A re-added), got ' + JSON.stringify(rsHealed && rsHealed.lane_group && rsHealed.lane_group.closed_members));
    assert(rsHealed.lane_group.legs && rsHealed.lane_group.legs.A && rsHealed.lane_group.legs.B,
      '#552-CRASH-WINDOW-RECONCILE-HEAL: reconcile RETAINS both legs (A NOT torn down), got ' + JSON.stringify(rsHealed.lane_group.legs));
    assert(worktreePaths(repoRoot).some(p => p.endsWith(path.join('.kw', 'legs', 'test-project', 'A'))), '#552-CRASH-WINDOW-RECONCILE-HEAL: A leg worktree survives reconcile (work not lost)');
    assert(branchExists(repoRoot, 'kw/legs/test-project/A'), '#552-CRASH-WINDOW-RECONCILE-HEAL: A leg branch survives reconcile');
    // Close B → group_passed; both legs merged.
    const rB = runNode(repoRoot, ['close-node', '--node-id', 'B', '--project', 'test-project', '--json'], LEG_ON);
    assert(rB.result === 'ok' && rB.barrier === 'group_passed' && rB.synthesized === true,
      '#552-CRASH-WINDOW-RECONCILE-HEAL: B group_passed + synthesized after the healed reconcile, got ' + JSON.stringify(rB));
    const head2 = G.exec(repoRoot, ['ls-tree', '-r', '--name-only', 'HEAD'], { encoding: 'utf8' });
    assert(head2.includes('ax.js') && head2.includes('by.js'),
      '#552-CRASH-WINDOW-RECONCILE-HEAL: BOTH legs\' files on HEAD (A leg retained through reconcile), got ' + JSON.stringify(head2.split('\n').filter(Boolean)));
    assert(ledgerStatus(planPath, 'A') === 'complete' && ledgerStatus(planPath, 'B') === 'complete', '#552-CRASH-WINDOW-RECONCILE-HEAL: both complete');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // LEG-CRASH-LOST-MANIFEST-RECLAIM (FIX-1b): provision legs (ON), then UNLINK running-set.json
  //   entirely (a crash that lost the manifest). Run reconcile-running-set with the toggle ON; the
  //   hoisted sweep — gated on resolveLegIsolation, NOT on a present manifest — reclaims the now-orphan
  //   legs (no keep-paths to protect them). Assert both leg worktrees + branches are gone.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir } = makeLaneRepo();
    const open = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], LEG_ON);
    assert(open.result === 'ok' && open.laneGroup, 'LEG-CRASH-LOST-MANIFEST-RECLAIM: setup co-open ok');
    assert(worktreePaths(repoRoot).filter(p => p.indexOf(path.join('.kw', 'legs')) !== -1).length === 2, 'LEG-CRASH-LOST-MANIFEST-RECLAIM: two legs provisioned at setup');
    // Crash: lose the running-set manifest entirely.
    fs.unlinkSync(path.join(cacheDir, 'running-set.json'));
    const rec = runNode(repoRoot, ['reconcile-running-set', '--project', 'test-project', '--json'], LEG_ON);
    assert(rec.result === 'ok', 'LEG-CRASH-LOST-MANIFEST-RECLAIM: reconcile ok (no_running_set), got ' + JSON.stringify(rec));
    assert(rec.reason === 'no_running_set', 'LEG-CRASH-LOST-MANIFEST-RECLAIM: reconcile returns no_running_set, got ' + rec.reason);
    const wts = worktreePaths(repoRoot);
    assert(!wts.some(p => p.indexOf(path.join('.kw', 'legs')) !== -1), 'LEG-CRASH-LOST-MANIFEST-RECLAIM: orphan legs reclaimed despite lost manifest, got ' + JSON.stringify(wts));
    assert(!branchExists(repoRoot, 'kw/legs/test-project/A') && !branchExists(repoRoot, 'kw/legs/test-project/B'), 'LEG-CRASH-LOST-MANIFEST-RECLAIM: orphan leg branches reclaimed');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // LEG-CRASH-LOST-MANIFEST-SERIAL (#542 kill-switch byte-identity): the SAME lost-manifest reconcile
  //   under the kill-switch KAOLA_PARALLEL_WRITES=0 must NOT sweep — the hoisted sweep is now gated on
  //   parallelWritesDefaultOn (DEFAULT-ON), so only the explicit kill-switch suppresses it. Under the
  //   kill-switch the run does zero git worktree teardown and the (manually planted) leg survives
  //   untouched. (The DEFAULT/legacy-toggle reclaim path is LEG-CRASH-LOST-MANIFEST-RECLAIM above —
  //   default-on now sweeps.)
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir } = makeLaneRepo();
    // Plant a leg directly (simulating a leftover) without any running set.
    const legPath = path.join(repoRoot, '.kw', 'legs', 'test-project', 'A');
    G.exec(repoRoot, ['worktree', 'add', '-b', 'kw/legs/test-project/A', '--', legPath, 'HEAD'], { stdio: ['ignore', 'ignore', 'ignore'] });
    try { fs.unlinkSync(path.join(cacheDir, 'running-set.json')); } catch (_) {}
    const rec = runNode(repoRoot, ['reconcile-running-set', '--project', 'test-project', '--json'], SERIAL); // kill-switch suppresses the sweep
    assert(rec.result === 'ok', 'LEG-CRASH-LOST-MANIFEST-SERIAL: reconcile ok, got ' + JSON.stringify(rec));
    assert(worktreePaths(repoRoot).some(p => p.endsWith(path.join('.kw', 'legs', 'test-project', 'A'))), 'LEG-CRASH-LOST-MANIFEST-SERIAL: planted leg UNTOUCHED under kill-switch (no sweep), still present');
    assert(branchExists(repoRoot, 'kw/legs/test-project/A'), 'LEG-CRASH-LOST-MANIFEST-SERIAL: planted leg branch UNTOUCHED under kill-switch');
    cleanup(repoRoot);
  });

  // =========================================================================
  // #463-LEG-BARRIER (Slice 3) — the PER-LEG write-isolation barrier. Drives the REAL validator
  // --leg-barrier subprocess + the close-path wiring in a REAL git repo with REAL leg writes (the unit
  // walkthrough cannot touch worktrees). Producer (adaptive-node ref-anchor at provision) + consumer
  // (validator --leg-barrier) land together; these prove the ref RESOLVES end-to-end (no silent
  // no_leg_base — the advisor landmine), the in-lane/overflow gate, committed-in-leg detection, and the
  // #368 anti-laundering cross-check + ancestor backstop. In S3 production legs stay EMPTY (routing is
  // S4); these tests write into legs DIRECTLY to exercise the barrier — the S2 dormant-but-tested pattern.
  // =========================================================================
  const STDIO_Q = { stdio: ['ignore', 'ignore', 'ignore'] };
  // Run the validator CLI as a REAL subprocess; parse the trailing JSON line like runNode.
  // #669: a --parent-clean-check refuse over a large dirty set echoes every offending path into the
  // JSON payload (dirty/errors/operator_hint), so a post-#669 (64 MB probe cap) SUCCESSFUL detection
  // over a large synthetic fixture produces a response well past THIS harness's own execFileSync
  // default 1 MB capture buffer — a distinct boundary from the production probe under test. Raise it
  // to the same GIT_MAX_BUFFER ceiling so the test's own capture is never the accidental bottleneck.
  function runVal(repoRoot, subArgs) {
    const VAL_MAX_BUFFER = 64 * 1024 * 1024;
    try {
      // The validator vehicle for this harness: it re-derives leg baselines and plan state from the
      // refs and files the adaptive-node processes wrote and exited.
      // spawn-class: durable-handoff
      const stdout = execFileSync('node', [VALIDATOR, ...subArgs], { cwd: repoRoot, encoding: 'utf8', maxBuffer: VAL_MAX_BUFFER });
      let parsed = {}; try { parsed = JSON.parse(stdout.trim().split('\n').pop()); } catch (_) {}
      return { exitCode: 0, ...parsed };
    } catch (err) {
      const status = (err.status == null) ? 1 : err.status;
      let parsed = {}; try { parsed = JSON.parse(String(err.stdout || '').trim().split('\n').pop()); } catch (_) {}
      return { exitCode: status, ...parsed };
    }
  }
  function gitOut(cwd, args) {
    try { return execFileSync('git', ['-C', cwd, ...args], { encoding: 'utf8' }).trim(); } catch (_) { return ''; }
  }
  // #652 (Gap 2): mirrors production isBarrierInvisible's project-scoped kaola-workflow/{project}/**
  // band — a diff-tree merge-diff equality filter must ignore ONLY the active project's own workflow
  // state tree as churn, not the whole kaola-workflow/ prefix. A stray write leaked into ANOTHER
  // project's tree (kaola-workflow/other-project/**) is barrier-invisible at the leg level
  // (isWorkflowArtifactPath exempts the whole prefix) but must still surface in the diff-tree
  // equality check below — SYNTH-CROSS-PROJECT-LEAK pins this.
  function isProjectWorkflowChurn(s, project) {
    return s === 'kaola-workflow/' + project || s.startsWith('kaola-workflow/' + project + '/');
  }
  const legRefName = id => 'refs/kaola-workflow/leg-base/test-project/' + id;
  const planP = repoRoot => path.join(repoRoot, 'kaola-workflow', 'test-project', 'workflow-plan.md');
  function refResolves(repoRoot, id) { return gitOut(repoRoot, ['rev-parse', '--verify', '--quiet', legRefName(id) + '^{commit}']); }
  // Provision legs (LEG_ON + consent) and return { repoRoot, cacheDir, legA, legB, rs }.
  function provisionedRepo() {
    const { repoRoot, cacheDir } = makeLaneRepo();
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], LEG_ON);
    assert(r.result === 'ok' && r.laneGroup, 'LEG-BARRIER setup: co-open ok, got ' + JSON.stringify(r));
    const rs = readRS(cacheDir);
    return {
      repoRoot, cacheDir, rs,
      legA: path.join(repoRoot, '.kw', 'legs', 'test-project', 'A'),
      legB: path.join(repoRoot, '.kw', 'legs', 'test-project', 'B'),
    };
  }
  // #702: same as provisionedRepo but A/B declare EXACT-FILE-DISJOINT docs/** surfaces (the population the
  // file-granular allowband co-open unblocks). The plan freezes in-grammar (exact-file docs under the
  // code-reviewer gate) and open-ready co-opens the legs — proving the docs frontier is a real leg group,
  // not a serial degrade. Used to exercise the leg-scoped docs write-set-overflow barrier.
  function provisionedDocsRepo() {
    const { repoRoot, cacheDir } = makeLaneRepo({ aSet: 'docs/a.md', bSet: 'docs/b.md' });
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], LEG_ON);
    assert(r.result === 'ok' && r.laneGroup, 'LEG-BARRIER-DOCS setup: exact-file-disjoint docs frontier co-opens as a leg group, got ' + JSON.stringify(r));
    const rs = readRS(cacheDir);
    return {
      repoRoot, cacheDir, rs,
      legA: path.join(repoRoot, '.kw', 'legs', 'test-project', 'A'),
      legB: path.join(repoRoot, '.kw', 'legs', 'test-project', 'B'),
    };
  }

  // LEG-BARRIER-REF-ANCHORED (advisor landmine: producer + consumer ref names must AGREE). The ref the
  // provision side anchored must RESOLVE under the name the validator derives, and equal the manifest base.
  scenario(() => {
    const { repoRoot, rs } = provisionedRepo();
    const refA = refResolves(repoRoot, 'A');
    assert(refA && refA.length >= 7, 'LEG-BARRIER-REF-ANCHORED: leg-base ref for A RESOLVES (producer anchored it under the consumer name), got ' + JSON.stringify(refA));
    assert(refA === rs.lane_group.legs.A.baseline, 'LEG-BARRIER-REF-ANCHORED: anchored ref A == manifest baseline (cross-check anchor agrees), got ref ' + refA + ' vs manifest ' + rs.lane_group.legs.A.baseline);
    cleanup(repoRoot);
  });

  // LEG-BARRIER-IN-LANE (uncommitted): a declared write inside the leg → --leg-barrier passes.
  scenario(() => {
    const { repoRoot, legA, rs } = provisionedRepo();
    fs.writeFileSync(path.join(legA, 'ax.js'), '// A in-lane leg write\n');
    const r = runVal(repoRoot, [planP(repoRoot), '--leg-barrier', '--node-id', 'A', '--project', 'test-project', '--leg-root', legA, '--expect-base', rs.lane_group.legs.A.baseline, '--json']);
    assert(r.result === 'pass', 'LEG-BARRIER-IN-LANE: in-lane leg write passes, got ' + JSON.stringify(r));
    cleanup(repoRoot);
  });

  // LEG-BARRIER-OVERFLOW (uncommitted): an OUT-OF-declared write inside the leg → write_set_overflow.
  scenario(() => {
    const { repoRoot, legA, rs } = provisionedRepo();
    fs.writeFileSync(path.join(legA, 'ax.js'), '// in-lane\n');
    fs.writeFileSync(path.join(legA, 'zz.js'), '// OVERFLOW (not in A declared set {ax.js})\n');
    const r = runVal(repoRoot, [planP(repoRoot), '--leg-barrier', '--node-id', 'A', '--project', 'test-project', '--leg-root', legA, '--expect-base', rs.lane_group.legs.A.baseline, '--json']);
    assert(r.result === 'refuse' && r.reason === 'write_set_overflow', 'LEG-BARRIER-OVERFLOW: leg overflow refuses write_set_overflow, got ' + JSON.stringify(r));
    cleanup(repoRoot);
  });

  // LEG-BARRIER-COMMITTED: COMMIT the writes IN the leg (not just uncommitted) — snapshotWorktree's
  // read-tree HEAD path must still attribute them. In-lane commit → pass; an overflow commit → refuse.
  scenario(() => {
    const { repoRoot, legA, rs } = provisionedRepo();
    fs.writeFileSync(path.join(legA, 'ax.js'), '// committed in leg\n');
    G.exec(legA, ['add', '-A'], STDIO_Q);
    G.exec(legA, ['commit', '-m', 'leg work'], STDIO_Q);
    const rOk = runVal(repoRoot, [planP(repoRoot), '--leg-barrier', '--node-id', 'A', '--project', 'test-project', '--leg-root', legA, '--expect-base', rs.lane_group.legs.A.baseline, '--json']);
    assert(rOk.result === 'pass', 'LEG-BARRIER-COMMITTED: committed in-lane leg write passes (read-tree HEAD path), got ' + JSON.stringify(rOk));
    fs.writeFileSync(path.join(legA, 'zz.js'), '// committed overflow\n');
    G.exec(legA, ['add', '-A'], STDIO_Q);
    G.exec(legA, ['commit', '-m', 'leg overflow'], STDIO_Q);
    const rBad = runVal(repoRoot, [planP(repoRoot), '--leg-barrier', '--node-id', 'A', '--project', 'test-project', '--leg-root', legA, '--expect-base', rs.lane_group.legs.A.baseline, '--json']);
    assert(rBad.result === 'refuse' && rBad.reason === 'write_set_overflow', 'LEG-BARRIER-COMMITTED: committed overflow still refuses, got ' + JSON.stringify(rBad));
    cleanup(repoRoot);
  });

  // #702 LEG-BARRIER-DOCS-DECLARED: a leg that writes its OWN declared docs/** file closes clean. The
  // #702 leg-scope drops the docs allowband from the barrier exemption, but the DECLARED file is in the
  // node's write set, so it is attributed to the leg, not overflow.
  scenario(() => {
    const { repoRoot, legA, rs } = provisionedDocsRepo();
    fs.mkdirSync(path.join(legA, 'docs'), { recursive: true });
    fs.writeFileSync(path.join(legA, 'docs', 'a.md'), '# A declared docs write\n');
    const r = runVal(repoRoot, [planP(repoRoot), '--leg-barrier', '--node-id', 'A', '--project', 'test-project', '--leg-root', legA, '--expect-base', rs.lane_group.legs.A.baseline, '--json']);
    assert(r.result === 'pass', 'LEG-BARRIER-DOCS-DECLARED: an in-lane DECLARED docs write passes the leg barrier, got ' + JSON.stringify(r));
    cleanup(repoRoot);
  });

  // ★ #702 LEG-BARRIER-DOCS-OVERFLOW (the leg-visibility fix): a leg writing an UNDECLARED docs/** file —
  // which the per-node barrier used to EXEMPT (docs are barrier-invisible), silently both-applying it at
  // the synthesis merge — now refuses write_set_overflow in LEG scope. This is the runtime half of the
  // file-granular allowband co-open: declared docs are attributed per-leg; a stray docs write is caught.
  scenario(() => {
    const { repoRoot, legA, rs } = provisionedDocsRepo();
    fs.mkdirSync(path.join(legA, 'docs'), { recursive: true });
    fs.writeFileSync(path.join(legA, 'docs', 'a.md'), '# in-lane declared\n');
    fs.writeFileSync(path.join(legA, 'docs', 'stray.md'), '# STRAY undeclared docs (not in A set {docs/a.md})\n');
    const r = runVal(repoRoot, [planP(repoRoot), '--leg-barrier', '--node-id', 'A', '--project', 'test-project', '--leg-root', legA, '--expect-base', rs.lane_group.legs.A.baseline, '--json']);
    assert(r.result === 'refuse' && r.reason === 'write_set_overflow', 'LEG-BARRIER-DOCS-OVERFLOW: an UNDECLARED docs write in a leg refuses write_set_overflow (no silent both-apply), got ' + JSON.stringify(r));
    assert((r.outOfAllow || []).some(p => p === 'docs/stray.md'), 'LEG-BARRIER-DOCS-OVERFLOW: the stray docs file is named in outOfAllow, got ' + JSON.stringify(r.outOfAllow));
    cleanup(repoRoot);
  });

  // #702 LEG-BARRIER-DOCS-MODE-PARITY (the anti-leak guard): the leg-scope docs-visibility change is keyed
  // STRICTLY on opts.legScoped, set ONLY by the --leg-barrier CLI. The GROUP/union barrier
  // (opts.groupMembers) and the WHOLE-PLAN barrier (no nodeId, no legScoped) must STILL exempt docs — a
  // stray docs write stays barrier-invisible in those modes (they back every serial close + finalize
  // check). barrierCheck is a PURE function (no fs, no git — immune to the #292 io-shim trap), so a direct
  // call is the exact mode-parity pin: same content + same stray docs path, docs visible ONLY when
  // legScoped. The kaola-workflow/{project}/** state band stays exempt in leg scope too.
  scenario(() => {
    const pv = require('./kaola-workflow-plan-validator');
    const planContent = [
      '# Plan', '', '## Meta', 'labels: area:scripts', '',
      '## Nodes', '',
      '| id | role | depends_on | declared_write_set | cardinality | shape |',
      '| --- | --- | --- | --- | --- | --- |',
      '| A | tdd-guide | — | docs/a.md | 1 | sequence |',
      '| B | tdd-guide | — | docs/b.md | 1 | sequence |',
      '| review | code-reviewer | A,B | — | 1 | sequence |',
      '| done | finalize | review | — | 1 | sequence |', '',
      '## Node Ledger', '', '| id | status |', '| --- | --- |',
      '| A | in_progress |', '| B | pending |', '| review | pending |', '| done | pending |', '',
    ].join('\n') + '\n';
    const stray = ['docs/stray.md'];
    const legScoped = pv.barrierCheck(planContent, stray, { nodeId: 'A', project: 'test-project', legScoped: true });
    assert(legScoped.result === 'refuse' && legScoped.reason === 'write_set_overflow', 'LEG-BARRIER-DOCS-MODE-PARITY: leg-scoped per-node barrier refuses a stray docs write, got ' + JSON.stringify(legScoped));
    const perNode = pv.barrierCheck(planContent, stray, { nodeId: 'A', project: 'test-project' });
    assert(perNode.result === 'pass', 'LEG-BARRIER-DOCS-MODE-PARITY: the plain per-node barrier (no legScoped) STILL exempts docs, got ' + JSON.stringify(perNode));
    const group = pv.barrierCheck(planContent, stray, { groupMembers: ['A', 'B'], project: 'test-project' });
    assert(group.result === 'pass', 'LEG-BARRIER-DOCS-MODE-PARITY: the group/union barrier STILL exempts docs (no leak), got ' + JSON.stringify(group));
    const wholePlan = pv.barrierCheck(planContent, stray, { project: 'test-project' });
    assert(wholePlan.result === 'pass', 'LEG-BARRIER-DOCS-MODE-PARITY: the whole-plan barrier STILL exempts docs (no leak), got ' + JSON.stringify(wholePlan));
    // and the workflow-state band stays exempt EVEN in leg scope (per-leg .cache evidence differs).
    const legState = pv.barrierCheck(planContent, ['kaola-workflow/test-project/.cache/A.md'], { nodeId: 'A', project: 'test-project', legScoped: true });
    assert(legState.result === 'pass', 'LEG-BARRIER-DOCS-MODE-PARITY: leg scope still exempts the kaola-workflow/{project}/** state band, got ' + JSON.stringify(legState));
  });

  // ★ LEG-BARRIER-VACUOUS-BASE (adversarial, the #368 cross-check): the laundering attack is to claim
  //   base = the leg's POST-WRITE tree so the diff empties. The validator resolves base from the ANCHORED
  //   ref (so the diff can't empty), and the manifest --expect-base cross-check trips the tamper:
  //   --expect-base = a post-write commit != the ref ⇒ barrier_base_mismatch.
  scenario(() => {
    const { repoRoot, legA, rs } = provisionedRepo();
    fs.writeFileSync(path.join(legA, 'zz.js'), '// overflow a free base would launder\n');
    G.exec(legA, ['add', '-A'], STDIO_Q);
    G.exec(legA, ['commit', '-m', 'overflow committed'], STDIO_Q);
    const postWrite = gitOut(legA, ['rev-parse', 'HEAD']);
    assert(postWrite && postWrite !== rs.lane_group.legs.A.baseline, 'LEG-BARRIER-VACUOUS-BASE: post-write HEAD differs from the anchored base');
    const r = runVal(repoRoot, [planP(repoRoot), '--leg-barrier', '--node-id', 'A', '--project', 'test-project', '--leg-root', legA, '--expect-base', postWrite, '--json']);
    assert(r.result === 'refuse' && r.reason === 'barrier_base_mismatch', 'LEG-BARRIER-VACUOUS-BASE: a tampered (post-write) --expect-base refuses barrier_base_mismatch (the #368 cross-check defeats the laundering base), got ' + JSON.stringify(r));
    cleanup(repoRoot);
  });

  // LEG-BARRIER-NO-REF: --leg-barrier with NO anchored leg-base ref → no_leg_base (not a silent pass).
  scenario(() => {
    const { repoRoot } = makeLaneRepo();
    const legX = path.join(repoRoot, '.kw', 'legs', 'test-project', 'A');
    G.exec(repoRoot, ['worktree', 'add', '-b', 'kw/legs/test-project/A', '--', legX, 'HEAD'], STDIO_Q);
    const r = runVal(repoRoot, [planP(repoRoot), '--leg-barrier', '--node-id', 'A', '--project', 'test-project', '--leg-root', legX, '--json']);
    assert(r.result === 'refuse' && r.reason === 'no_leg_base', 'LEG-BARRIER-NO-REF: missing anchored ref refuses no_leg_base (no vacuous pass), got ' + JSON.stringify(r));
    cleanup(repoRoot);
  });

  // LEG-BARRIER-ANCESTOR-BACKSTOP: a ref re-pointed FORWARD (not an ancestor of legHEAD) → the diff base
  //   does not sit in the leg's history → leg_base_unreachable (the backstop behind the cross-check).
  scenario(() => {
    const { repoRoot, legA } = provisionedRepo();
    fs.writeFileSync(path.join(repoRoot, 'forward.txt'), 'f\n');
    G.exec(repoRoot, ['add', '-A'], STDIO_Q);
    G.exec(repoRoot, ['commit', '-m', 'forward'], STDIO_Q);
    const forward = gitOut(repoRoot, ['rev-parse', 'HEAD']); // descendant of baseRev ⇒ NOT an ancestor of legHEAD(=baseRev)
    G.exec(repoRoot, ['update-ref', legRefName('A'), forward], STDIO_Q);
    const r = runVal(repoRoot, [planP(repoRoot), '--leg-barrier', '--node-id', 'A', '--project', 'test-project', '--leg-root', legA, '--expect-base', forward, '--json']);
    assert(r.result === 'refuse' && r.reason === 'leg_base_unreachable', 'LEG-BARRIER-ANCESTOR-BACKSTOP: a forward (non-ancestor) base refuses leg_base_unreachable, got ' + JSON.stringify(r));
    cleanup(repoRoot);
  });

  // LEG-BARRIER-ARG-VALIDATION: missing --node-id / --leg-root / --project → typed refusals.
  scenario(() => {
    const { repoRoot, legA } = provisionedRepo();
    const noNode = runVal(repoRoot, [planP(repoRoot), '--leg-barrier', '--project', 'test-project', '--leg-root', legA, '--json']);
    assert(noNode.result === 'refuse' && noNode.reason === 'missing_node_id', 'LEG-BARRIER-ARG: missing --node-id, got ' + JSON.stringify(noNode));
    const noRoot = runVal(repoRoot, [planP(repoRoot), '--leg-barrier', '--node-id', 'A', '--project', 'test-project', '--json']);
    assert(noRoot.result === 'refuse' && noRoot.reason === 'missing_leg_root', 'LEG-BARRIER-ARG: missing --leg-root, got ' + JSON.stringify(noRoot));
    const noProj = runVal(repoRoot, [planP(repoRoot), '--leg-barrier', '--node-id', 'A', '--leg-root', legA, '--json']);
    assert(noProj.result === 'refuse' && noProj.reason === 'missing_project', 'LEG-BARRIER-ARG: missing --project, got ' + JSON.stringify(noProj));
    cleanup(repoRoot);
  });

  // LEG-BARRIER-LEG-ROOT-INVALID: --leg-root pointing at a non-worktree dir (its git toplevel != itself).
  scenario(() => {
    const { repoRoot } = makeLaneRepo();
    const notWt = path.join(repoRoot, 'not-a-worktree');
    fs.mkdirSync(notWt, { recursive: true });
    const r = runVal(repoRoot, [planP(repoRoot), '--leg-barrier', '--node-id', 'A', '--project', 'test-project', '--leg-root', notWt, '--json']);
    assert(r.result === 'refuse' && r.reason === 'leg_root_invalid', 'LEG-BARRIER-LEG-ROOT-INVALID: non-worktree leg-root refuses leg_root_invalid, got ' + JSON.stringify(r));
    cleanup(repoRoot);
  });

  // ★ LEG-BARRIER-CLOSE-PATH-GATES (the PRODUCTION wiring GATES): #463 S4 routing is live, so the member's
  //   work lands in its LEG. An in-lane write (ax.js, satisfies the leg-aware vacuity guard) + an OVERFLOW
  //   (zz.js, not declared) both in the leg → close-node REFUSES at the pre-wired per-leg barrier (proves
  //   the wiring is not a vacuous empty-leg pass). Ledger stays in_progress.
  scenario(() => {
    const { repoRoot, cacheDir, legA } = provisionedRepo();
    writeEvidence(cacheDir, 'A');
    fs.writeFileSync(path.join(legA, 'ax.js'), '// A in-lane in LEG (vacuity)\n');
    fs.writeFileSync(path.join(legA, 'zz.js'), '// OVERFLOW in A leg\n');
    const r = runNode(repoRoot, ['close-node', '--node-id', 'A', '--project', 'test-project', '--json'], LEG_ON);
    assert(r.result === 'refuse' && r.reason === 'write_set_overflow', 'LEG-BARRIER-CLOSE-PATH-GATES: close-node refuses a leg overflow via the pre-wired barrier, got ' + JSON.stringify(r));
    assert(ledgerStatus(planP(repoRoot), 'A') === 'in_progress', 'LEG-BARRIER-CLOSE-PATH-GATES: A ledger stays in_progress on refusal, got ' + ledgerStatus(planP(repoRoot), 'A'));
    cleanup(repoRoot);
  });

  // LEG-BARRIER-CLOSE-PATH-CLEAN: in-lane to the PARENT (vacuity) + a REAL in-lane write to the LEG →
  //   close-node A passes the leg-barrier (not just the empty-leg trivial pass) and defers to the group.
  scenario(() => {
    const { repoRoot, cacheDir, legA } = provisionedRepo();
    writeEvidence(cacheDir, 'A');
    fs.writeFileSync(path.join(repoRoot, 'ax.js'), '// parent in-lane (vacuity)\n');
    fs.writeFileSync(path.join(legA, 'ax.js'), '// leg in-lane (declared)\n');
    const r = runNode(repoRoot, ['close-node', '--node-id', 'A', '--project', 'test-project', '--json'], LEG_ON);
    assert(r.result === 'ok' && r.barrier === 'deferred_to_group', 'LEG-BARRIER-CLOSE-PATH-CLEAN: close A passes the leg-barrier on a real in-lane leg write + defers, got ' + JSON.stringify(r));
    cleanup(repoRoot);
  });

  // RETIRED for #498: LEG-BARRIER-CLOSE-PATH-FLAG-OFF asserted that ON-alone (containment only) co-opens
  // a group and the legless close returns barrier:'deferred_to_group'. PREMISE NOW UNREACHABLE: after #498
  // co-open ⟺ legs provisioned, so ON-alone serial-degrades (opens ONE node, no group) — closing it takes
  // the SERIAL per-node barrier path, not the group close. Its real intent (a legless close SKIPS the
  // leg-barrier block, byte-identical to pre-S3) is covered by D437-CLOSE-NODE-FLAG-OFF-SERIAL (the legless
  // serial close) and the leg-barrier itself by the real-leg LEG-BARRIER-IN-LANE / -OVERFLOW / -COMMITTED
  // tests below. (Its body never planted a leg-overflow, so it never exercised its own skip claim anyway.)

  // LEG-BARRIER-TEARDOWN-DROPS-REF: on clean group completion the leg-base refs are deleted alongside the
  //   worktree + branch (no ref leak). #463 S4: an end-to-end close-path run with REAL in-leg writes that
  //   the synthesizer merges (group_passed via the commit-based union barrier), then teardown.
  scenario(() => {
    const { repoRoot, cacheDir, legA, legB } = provisionedRepo();
    assert(refResolves(repoRoot, 'A') !== '' && refResolves(repoRoot, 'B') !== '', 'LEG-BARRIER-TEARDOWN-DROPS-REF: refs A,B anchored at provision');
    writeEvidence(cacheDir, 'A'); writeEvidence(cacheDir, 'B');
    fs.writeFileSync(path.join(legA, 'ax.js'), '// a (leg)\n');
    fs.writeFileSync(path.join(legB, 'by.js'), '// b (leg)\n');
    const rA = runNode(repoRoot, ['close-node', '--node-id', 'A', '--project', 'test-project', '--json'], LEG_ON);
    assert(rA.result === 'ok', 'LEG-BARRIER-TEARDOWN-DROPS-REF: close A ok, got ' + JSON.stringify(rA));
    const rB = runNode(repoRoot, ['close-node', '--node-id', 'B', '--project', 'test-project', '--json'], LEG_ON);
    assert(rB.result === 'ok' && rB.barrier === 'group_passed', 'LEG-BARRIER-TEARDOWN-DROPS-REF: close B group_passed, got ' + JSON.stringify(rB));
    assert(refResolves(repoRoot, 'A') === '' && refResolves(repoRoot, 'B') === '', 'LEG-BARRIER-TEARDOWN-DROPS-REF: leg-base refs deleted on teardown (no ref leak)');
    cleanup(repoRoot);
  });

  // =========================================================================
  // #463-SYNTHESIZER (Slice 4) — the SYNTHESIZER execution + COMMIT-based union barrier + parent-clean
  // fence + level commit barrier + singleton fast-path, in a REAL git repo (the unit walkthrough cannot
  // touch worktrees/merges). The B1 fix is the load-bearing claim: the union barrier measures the merge
  // COMMIT (diff base→M), NOT a working-tree snapshot, so a floated own-lane slip cannot false-green and a
  // dropped leg (silent loss) is caught by per-leg-head ancestor inclusion. Disjoint merges are mechanical.
  // =========================================================================

  // SYNTH-DISJOINT-END-TO-END (AC6/AC9 core): two legs, disjoint declared files written IN the legs; close
  //   A (deferred) then B (last) → the synthesizer octopus-merges both into the feature branch → M; the
  //   commit-based union barrier passes; HEAD advanced to M; M contains BOTH files; legs torn down.
  scenario(() => {
    const { repoRoot, cacheDir, legA, legB, rs } = provisionedRepo();
    const base = rs.lane_group.legs.A.baseline;
    writeEvidence(cacheDir, 'A'); writeEvidence(cacheDir, 'B');
    fs.writeFileSync(path.join(legA, 'ax.js'), '// A leg work\n');
    fs.writeFileSync(path.join(legB, 'by.js'), '// B leg work\n');
    const rA = runNode(repoRoot, ['close-node', '--node-id', 'A', '--project', 'test-project', '--json'], LEG_ON);
    assert(rA.result === 'ok' && rA.barrier === 'deferred_to_group', 'SYNTH-DISJOINT: A deferred, got ' + JSON.stringify(rA));
    const rB = runNode(repoRoot, ['close-node', '--node-id', 'B', '--project', 'test-project', '--json'], LEG_ON);
    assert(rB.result === 'ok' && rB.barrier === 'group_passed' && rB.synthesized === true, 'SYNTH-DISJOINT: B group_passed + synthesized, got ' + JSON.stringify(rB));
    const M = rB.mergeCommit;
    assert(typeof M === 'string' && M.length >= 7, 'SYNTH-DISJOINT: B carries mergeCommit M, got ' + JSON.stringify(rB));
    assert(gitOut(repoRoot, ['rev-parse', 'HEAD']) === M, 'SYNTH-DISJOINT: HEAD advanced to M (the dependency-level commit)');
    const parents = gitOut(repoRoot, ['rev-list', '--parents', '-n', '1', M]).split(/\s+/).slice(1);
    assert(parents.length >= 3, 'SYNTH-DISJOINT: M is the octopus merge (≥3 parents = feature + legA + legB), got ' + parents.length);
    assert(gitOut(repoRoot, ['rev-parse', M + ':ax.js']) !== '' && gitOut(repoRoot, ['rev-parse', M + ':by.js']) !== '', 'SYNTH-DISJOINT: M contains BOTH legs\' files');
    const mDiff = gitOut(repoRoot, ['diff-tree', '-r', '--name-only', base, M]).split('\n')
      .map(s => s.trim()).filter(s => s && !isProjectWorkflowChurn(s, 'test-project')).sort();
    assert(JSON.stringify(mDiff) === JSON.stringify(['ax.js', 'by.js']), 'SYNTH-DISJOINT: diff base→M == union(declared), got ' + JSON.stringify(mDiff));
    const timings = fs.existsSync(path.join(cacheDir, 'node-timings.jsonl')) ? fs.readFileSync(path.join(cacheDir, 'node-timings.jsonl'), 'utf8') : '';
    assert(/level_merged/.test(timings), 'SYNTH-DISJOINT: a level_merged telemetry event was recorded');
    // #463 Slice 6 (AC17): the synthesizer emits leg_committed PER leg (the leg-lifecycle telemetry
    // leg_opened → leg_committed → level_merged). The live AC18 probe caught its absence; this pins it.
    assert((timings.match(/leg_committed/g) || []).length === 2, 'SYNTH-DISJOINT: leg_committed emitted once per leg (AC17), got ' + (timings.match(/leg_committed/g) || []).length);
    assert(worktreePaths(repoRoot).filter(p => p.indexOf(path.join('.kw', 'legs')) !== -1).length === 0, 'SYNTH-DISJOINT: legs torn down after the merge');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // SYNTH-CROSS-PROJECT-LEAK (#652 Gap 2): a stray write under a DIFFERENT project's
  // kaola-workflow/ tree (kaola-workflow/other-project/**) — barrier-invisible at the leg-barrier
  // level (isWorkflowArtifactPath exempts the whole kaola-workflow/ prefix, not just the active
  // project's own band) — is committed via the leg's `git add -A` and lands in the merge commit M
  // like any other churn. The diff-tree equality check's own churn filter must NOT swallow it: only
  // the ACTIVE project's (test-project) own kaola-workflow/ tree is legitimate churn to ignore, not
  // the whole kaola-workflow/ prefix. A leak into ANOTHER project's tree must still surface in mDiff.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir, legA, legB, rs } = provisionedRepo();
    const base = rs.lane_group.legs.A.baseline;
    writeEvidence(cacheDir, 'A'); writeEvidence(cacheDir, 'B');
    fs.writeFileSync(path.join(legA, 'ax.js'), '// A leg work\n');
    fs.writeFileSync(path.join(legB, 'by.js'), '// B leg work\n');
    // Synthetic cross-project leak, written into leg A's tree (picked up by the leg's `git add -A`
    // like any other stray write; the leg-barrier does not flag it — kaola-workflow/** is exempt).
    fs.mkdirSync(path.join(legA, 'kaola-workflow', 'other-project'), { recursive: true });
    fs.writeFileSync(path.join(legA, 'kaola-workflow', 'other-project', 'leaked.md'), '// cross-project leak\n');
    const rA = runNode(repoRoot, ['close-node', '--node-id', 'A', '--project', 'test-project', '--json'], LEG_ON);
    assert(rA.result === 'ok' && rA.barrier === 'deferred_to_group', 'SYNTH-CROSS-PROJECT-LEAK: A deferred, got ' + JSON.stringify(rA));
    const rB = runNode(repoRoot, ['close-node', '--node-id', 'B', '--project', 'test-project', '--json'], LEG_ON);
    assert(rB.result === 'ok' && rB.barrier === 'group_passed' && rB.synthesized === true, 'SYNTH-CROSS-PROJECT-LEAK: B group_passed + synthesized, got ' + JSON.stringify(rB));
    const M = rB.mergeCommit;
    const mDiff = gitOut(repoRoot, ['diff-tree', '-r', '--name-only', base, M]).split('\n')
      .map(s => s.trim()).filter(s => s && !isProjectWorkflowChurn(s, 'test-project')).sort();
    // The project-scoped churn filter must NOT swallow the other-project leak — it stays visible in
    // mDiff, so an equality check against the declared set correctly flags it instead of going quiet.
    assert(mDiff.includes('kaola-workflow/other-project/leaked.md'),
      'SYNTH-CROSS-PROJECT-LEAK: the cross-project leak survives the churn filter and surfaces in mDiff, got ' + JSON.stringify(mDiff));
    // The active project's OWN kaola-workflow tree is still correctly filtered as legitimate churn.
    assert(!mDiff.some(s => s.startsWith('kaola-workflow/test-project/')),
      'SYNTH-CROSS-PROJECT-LEAK: the active project\'s own kaola-workflow tree stays filtered as churn, got ' + JSON.stringify(mDiff));
    cleanup(repoRoot);
  });

  // SYNTH-PARENT-DIRTY-FENCE (AC4): a floated own-lane slip — a PRODUCTION file written to the PARENT (not
  //   exempt) — is caught by the parent-clean fence at the last-member close, BEFORE the merge. parent_dirty;
  //   no merge happened (HEAD unchanged); B stays in_progress.
  scenario(() => {
    const { repoRoot, cacheDir, legA, legB, rs } = provisionedRepo();
    const base = rs.lane_group.legs.A.baseline;
    writeEvidence(cacheDir, 'A'); writeEvidence(cacheDir, 'B');
    fs.writeFileSync(path.join(legA, 'ax.js'), '// A leg work\n');
    fs.writeFileSync(path.join(legB, 'by.js'), '// B leg work\n');
    fs.writeFileSync(path.join(repoRoot, 'leaked.js'), '// FLOATED own-lane slip into the PARENT\n');
    const rA = runNode(repoRoot, ['close-node', '--node-id', 'A', '--project', 'test-project', '--json'], LEG_ON);
    assert(rA.result === 'ok' && rA.barrier === 'deferred_to_group', 'SYNTH-PARENT-DIRTY: A deferred, got ' + JSON.stringify(rA));
    const rB = runNode(repoRoot, ['close-node', '--node-id', 'B', '--project', 'test-project', '--json'], LEG_ON);
    assert(rB.result === 'refuse' && rB.reason === 'parent_dirty', 'SYNTH-PARENT-DIRTY: B refused parent_dirty (floated slip caught), got ' + JSON.stringify(rB));
    assert(gitOut(repoRoot, ['rev-parse', 'HEAD']) === base, 'SYNTH-PARENT-DIRTY: HEAD NOT advanced (no merge on a dirty parent)');
    assert(ledgerStatus(planP(repoRoot), 'B') === 'in_progress', 'SYNTH-PARENT-DIRTY: B stays in_progress on refusal');
    cleanup(repoRoot);
  });

  // PARENT-CLEAN-CHECK-DIRECT: the fence reuses the EXACT barrier allowband — workflow churn (.cache /
  //   running-set / plan) NEVER trips it (the advisor's #1: else it ships inert), only a production path does.
  scenario(() => {
    const { repoRoot } = provisionedRepo(); // open-ready left .cache churn dirty in the parent
    const clean = runVal(repoRoot, [planP(repoRoot), '--parent-clean-check', '--project', 'test-project', '--json']);
    assert(clean.result === 'pass', 'PARENT-CLEAN-DIRECT: workflow churn alone is clean (allowband reused), got ' + JSON.stringify(clean));
    fs.writeFileSync(path.join(repoRoot, 'prod.js'), '// production dirty\n');
    const dirty = runVal(repoRoot, [planP(repoRoot), '--parent-clean-check', '--project', 'test-project', '--json']);
    assert(dirty.result === 'refuse' && dirty.reason === 'parent_dirty' && (dirty.dirty || []).indexOf('prod.js') !== -1, 'PARENT-CLEAN-DIRECT: a production dirty path trips parent_dirty, got ' + JSON.stringify(dirty));
    cleanup(repoRoot);
  });

  // ★ PARENT-CLEAN-CHECK-UALL (adversarial review caught): a NON-exempt file inside a WHOLLY-NEW untracked
  //   subdir whose name is exempt-by-prefix is MASKED by `git status --porcelain`'s dir-collapse (`??
  //   kaola-workflow/archive/`) → classified by the collapsed dir name → EVADES the fence. The fence now
  //   uses --untracked-files=all so each file is classified precisely. Concrete vector: a FOREIGN-archive
  //   write into a fresh kaola-workflow/archive/<other>/ subdir (archive/ is new under the tracked
  //   kaola-workflow/, so default porcelain collapses it; the full path is foreignArchive → NOT exempt).
  scenario(() => {
    const { repoRoot } = provisionedRepo();
    fs.mkdirSync(path.join(repoRoot, 'kaola-workflow', 'archive', 'OTHER-PROJECT'), { recursive: true });
    fs.writeFileSync(path.join(repoRoot, 'kaola-workflow', 'archive', 'OTHER-PROJECT', 'leak.js'), '// foreign-archive production leak masked by dir-collapse\n');
    const r = runVal(repoRoot, [planP(repoRoot), '--parent-clean-check', '--project', 'test-project', '--json']);
    assert(r.result === 'refuse' && r.reason === 'parent_dirty' && (r.dirty || []).some(p => /archive\/OTHER-PROJECT\/leak\.js/.test(p)), 'PARENT-CLEAN-UALL: a foreign-archive leak in a new collapsed subdir trips parent_dirty (RED without -uall: collapses to kaola-workflow/archive/ → exempt → false pass), got ' + JSON.stringify(r));
    cleanup(repoRoot);
  });

  // ★ PARENT-CLEAN-CHECK-ENOBUFS (#669): the dirty-fence's own `git status --porcelain -uall` probe is
  //   UNBOUNDED in dirty/untracked path COUNT. A huge out-of-allowband PRODUCTION untracked fan-out
  //   (thousands of paths under a long shared prefix, NOT allowband kaola-workflow/** paths — the fence
  //   only flags out-of-allowband paths as dirty in the first place) blows past Node's 1 MB
  //   execFileSync default maxBuffer. Pre-#669 the exec throws ENOBUFS -> `catch (_) { porcelain = ''; }`
  //   collapses to ZERO dirty paths -> the fence returns a false PASS on a tree that is DEMONSTRABLY not
  //   clean (fail-OPEN — the crux this node fixes). Post-#669 the SAME probe now carries
  //   maxBuffer:GIT_MAX_BUFFER (64 MB), so this particular (~1.26 MB) fixture no longer overflows the
  //   probe itself — it succeeds and CORRECTLY classifies the dirt as parent_dirty (the strictly better
  //   outcome: real detection, not just a generic "can't tell" refuse). Either way the invariant under
  //   test — NEVER a bare "pass" on a demonstrably non-clean tree — holds both pre- and post-fix, so
  //   this fixture stays a valid RED->GREEN regression across the fix (RED: false pass; GREEN: refuse).
  scenario(() => {
    const { repoRoot } = makeLaneRepo(); // fully-committed baseline (no open-ready — legs not needed here)
    // Long shared path prefix so far fewer files are needed to clear 1 MB (build-time budget: seconds,
    // not the file COUNT). Deeply-nested production dir, NOT under kaola-workflow/ (would be allowband-
    // exempt and never register as dirty at all — the fence would just as validly report clean).
    const bigDir = path.join(repoRoot, 'src', 'generated', 'a'.repeat(60), 'b'.repeat(60), 'c'.repeat(60));
    fs.mkdirSync(bigDir, { recursive: true });
    // Each porcelain line ≈ "?? " + relPath + "\n" ≈ 210 bytes (relPath ≈ 14 + 182 + 1 + 9 chars). 6000
    // files ≈ 1.26 MB of porcelain text — comfortably (~20%) over Node's 1,048,576-byte default
    // maxBuffer, reliably tripping ENOBUFS on the unpatched (no maxBuffer option) exec call.
    const FILE_COUNT = 6000;
    for (let i = 0; i < FILE_COUNT; i++) {
      fs.writeFileSync(path.join(bigDir, 'f' + String(i).padStart(5, '0') + '.js'), '');
    }
    const r = runVal(repoRoot, [planP(repoRoot), '--parent-clean-check', '--project', 'test-project', '--json']);
    assert(r.result !== 'pass', 'PARENT-CLEAN-ENOBUFS: a >1MB dirty tree must NEVER fall through to a "pass" verdict (fail-OPEN), got ' + JSON.stringify(r));
    assert(r.result === 'refuse' && (r.reason === 'parent_dirty' || r.reason === 'cannot_prove_clean') && r.exitCode !== 0,
      'PARENT-CLEAN-ENOBUFS: fails CLOSED with a typed refuse (exitCode!=0), got ' + JSON.stringify(r));
    cleanup(repoRoot);
  });

  // ★ PARENT-CLEAN-CHECK-CANNOT-PROVE-CLEAN (#669): the fail-closed flip is UNCONDITIONAL — it must
  //   trip on ANY probe failure, not only a size-driven ENOBUFS (an adversary could otherwise construct
  //   a non-buffer git fault and find the fence still silently passes). Corrupt `.git/index` so `git
  //   status --porcelain` itself fails (a real git error, unrelated to output size) and assert the
  //   fence refuses `cannot_prove_clean` — the DISTINCT reason for "the probe itself is unreadable",
  //   never conflated with `parent_dirty` (which asserts REAL, ENUMERATED dirty paths).
  scenario(() => {
    const { repoRoot } = makeLaneRepo();
    fs.writeFileSync(path.join(repoRoot, '.git', 'index'), 'not a valid git index\n');
    const r = runVal(repoRoot, [planP(repoRoot), '--parent-clean-check', '--project', 'test-project', '--json']);
    assert(r.result === 'refuse' && r.reason === 'cannot_prove_clean' && r.exitCode !== 0,
      'PARENT-CLEAN-CANNOT-PROVE-CLEAN: a non-buffer git fault (corrupt index) fails CLOSED with the typed cannot_prove_clean refuse, got ' + JSON.stringify(r));
    cleanup(repoRoot);
  });

  // ★ SYNTH-SERIAL-CLOSE-FENCED (adversarial review caught — silent-loss): close-and-open-next (the SERIAL
  //   close path) has NO isMember routing — unlike close-node → closeGroupMember — so closing a live
  //   lane-group member out-of-band here would skip the synthesizer + barriers and ORPHAN the leg's
  //   committed work (the per-node barrier passes vacuously on the empty PARENT diff). The S4 scheduler
  //   fence (excl:['scheduler']) makes it refuse scheduler_active fail-closed; the member stays in_progress.
  scenario(() => {
    const { repoRoot, cacheDir, legA } = provisionedRepo();
    writeEvidence(cacheDir, 'A');
    fs.writeFileSync(path.join(legA, 'ax.js'), '// A leg work that a serial close would orphan\n');
    const r = runNode(repoRoot, ['close-and-open-next', '--node-id', 'A', '--project', 'test-project', '--json'], LEG_ON);
    assert(r.result === 'refuse' && r.reason === 'scheduler_active', 'SYNTH-SERIAL-CLOSE-FENCED: close-and-open-next on a live lane-group member refuses scheduler_active (no out-of-band silent close), got ' + JSON.stringify(r));
    assert(ledgerStatus(planP(repoRoot), 'A') === 'in_progress', 'SYNTH-SERIAL-CLOSE-FENCED: A stays in_progress (not silently closed), got ' + ledgerStatus(planP(repoRoot), 'A'));
    cleanup(repoRoot);
  });

  // SYNTH-OMISSION (advisor #2, no-silent-loss): commit work in BOTH legs but merge ONLY legA → M. The
  //   commit-based union barrier catches legB's omission via per-leg-head ancestor inclusion (subset alone
  //   would FALSE-PASS — legA's files ⊆ union — and legB's committed work would be lost on teardown).
  scenario(() => {
    const { repoRoot, legA, legB } = provisionedRepo();
    fs.writeFileSync(path.join(legA, 'ax.js'), '// a\n');
    G.exec(legA, ['add', '-A'], STDIO_Q); G.exec(legA, ['commit', '-m', 'la'], STDIO_Q);
    fs.writeFileSync(path.join(legB, 'by.js'), '// b\n');
    G.exec(legB, ['add', '-A'], STDIO_Q); G.exec(legB, ['commit', '-m', 'lb'], STDIO_Q);
    G.exec(repoRoot, ['merge', '--no-ff', '-m', 'partial: only legA', 'kw/legs/test-project/A'], STDIO_Q);
    const M = gitOut(repoRoot, ['rev-parse', 'HEAD']);
    const r = runVal(repoRoot, [planP(repoRoot), '--group-barrier', '--group-id', 'lg-A-B', '--merge-commit', M, '--project', 'test-project', '--json']);
    assert(r.result === 'refuse' && r.reason === 'leg_omitted_from_merge', 'SYNTH-OMISSION: a dropped leg (legB not in M) is caught leg_omitted_from_merge, got ' + JSON.stringify(r));
    cleanup(repoRoot);
  });

  // SYNTH-UNION-ESCAPE (B1 belt-and-suspenders): a COMMITTED out-of-union path in M is caught by the
  //   commit diff (write_set_overflow) — the union barrier rejects an escape even if it slipped a per-leg gate.
  scenario(() => {
    const { repoRoot, legA, legB } = provisionedRepo();
    fs.writeFileSync(path.join(legA, 'ax.js'), '// a\n');
    fs.writeFileSync(path.join(legA, 'zz.js'), '// OUT OF UNION committed\n');
    G.exec(legA, ['add', '-A'], STDIO_Q); G.exec(legA, ['commit', '-m', 'la+escape'], STDIO_Q);
    fs.writeFileSync(path.join(legB, 'by.js'), '// b\n');
    G.exec(legB, ['add', '-A'], STDIO_Q); G.exec(legB, ['commit', '-m', 'lb'], STDIO_Q);
    G.exec(repoRoot, ['merge', '--no-ff', '-m', 'synth', 'kw/legs/test-project/A', 'kw/legs/test-project/B'], STDIO_Q);
    const M = gitOut(repoRoot, ['rev-parse', 'HEAD']);
    const r = runVal(repoRoot, [planP(repoRoot), '--group-barrier', '--group-id', 'lg-A-B', '--merge-commit', M, '--project', 'test-project', '--json']);
    assert(r.result === 'refuse' && r.reason === 'write_set_overflow', 'SYNTH-UNION-ESCAPE: an out-of-union committed path in M refuses write_set_overflow, got ' + JSON.stringify(r));
    cleanup(repoRoot);
  });

  // SYNTH-MERGE-COMMIT-ARG-VALIDATION: --merge-commit must resolve to a commit, must descend from base,
  //   and requires --project.
  scenario(() => {
    const { repoRoot, legA, legB } = provisionedRepo();
    fs.writeFileSync(path.join(legA, 'ax.js'), '// a\n');
    G.exec(legA, ['add', '-A'], STDIO_Q); G.exec(legA, ['commit', '-m', 'la'], STDIO_Q);
    fs.writeFileSync(path.join(legB, 'by.js'), '// b\n');
    G.exec(legB, ['add', '-A'], STDIO_Q); G.exec(legB, ['commit', '-m', 'lb'], STDIO_Q);
    const bad = runVal(repoRoot, [planP(repoRoot), '--group-barrier', '--group-id', 'lg-A-B', '--merge-commit', 'deadbeefdeadbeefdeadbeefdeadbeefdeadbeef', '--project', 'test-project', '--json']);
    assert(bad.result === 'refuse' && bad.reason === 'merge_commit_invalid', 'SYNTH-ARG: a non-resolving --merge-commit refuses merge_commit_invalid, got ' + JSON.stringify(bad));
    // an UNRELATED commit (legA head — not a descendant merging BOTH; base is its ancestor but legB isn't)
    // exercises the leg inclusion path; an unrelated-to-base commit exercises merge_base_unreachable. Build
    // a detached commit with no relation to base by committing on an orphan-ish state: use legB head as M —
    // base IS its ancestor, but legA is NOT in it → leg_omitted_from_merge (the inclusion guard fires first).
    const legBhead = gitOut(repoRoot, ['rev-parse', 'kw/legs/test-project/B']);
    const omit = runVal(repoRoot, [planP(repoRoot), '--group-barrier', '--group-id', 'lg-A-B', '--merge-commit', legBhead, '--project', 'test-project', '--json']);
    assert(omit.result === 'refuse' && omit.reason === 'leg_omitted_from_merge', 'SYNTH-ARG: legB head as M omits legA, got ' + JSON.stringify(omit));
    const noProj = runVal(repoRoot, [planP(repoRoot), '--group-barrier', '--group-id', 'lg-A-B', '--merge-commit', legBhead, '--json']);
    assert(noProj.result === 'refuse' && noProj.reason === 'missing_project', 'SYNTH-ARG: --merge-commit without --project refuses missing_project, got ' + JSON.stringify(noProj));
    cleanup(repoRoot);
  });

  // SYNTH-MERGE-BASE-UNREACHABLE (adversarial review: covers a previously-untested fail-closed guard): an M
  //   that does NOT descend from the legs' shared branch-point (a tamper/corruption M) → merge_base_unreachable.
  scenario(() => {
    const { repoRoot, legA, legB } = provisionedRepo();
    fs.writeFileSync(path.join(legA, 'ax.js'), '// a\n');
    G.exec(legA, ['add', '-A'], STDIO_Q); G.exec(legA, ['commit', '-m', 'la'], STDIO_Q);
    fs.writeFileSync(path.join(legB, 'by.js'), '// b\n');
    G.exec(legB, ['add', '-A'], STDIO_Q); G.exec(legB, ['commit', '-m', 'lb'], STDIO_Q);
    // an ORPHAN commit (commit-tree with NO parent) — base is not an ancestor of it.
    const tree = gitOut(repoRoot, ['write-tree']);
    const orphan = G.exec(repoRoot, ['commit-tree', tree, '-m', 'orphan'], { encoding: 'utf8' }).trim();
    const r = runVal(repoRoot, [planP(repoRoot), '--group-barrier', '--group-id', 'lg-A-B', '--merge-commit', orphan, '--project', 'test-project', '--json']);
    assert(r.result === 'refuse' && r.reason === 'merge_base_unreachable', 'SYNTH-MERGE-BASE-UNREACHABLE: an M not descending from base refuses merge_base_unreachable, got ' + JSON.stringify(r));
    cleanup(repoRoot);
  });

  // SYNTH-LEG-BASELINE-SPLIT (adversarial review: covers a previously-untested fail-closed guard): the legs
  //   of one level must share ONE branch-point; if leg B's anchored ref + manifest baseline both diverge from
  //   leg A's, the validator detects the split (legs branched from different HEADs) → leg_baseline_split.
  scenario(() => {
    const { repoRoot, cacheDir, legA, legB } = provisionedRepo();
    fs.writeFileSync(path.join(legA, 'ax.js'), '// a\n');
    G.exec(legA, ['add', '-A'], STDIO_Q); G.exec(legA, ['commit', '-m', 'la'], STDIO_Q);
    fs.writeFileSync(path.join(legB, 'by.js'), '// b\n');
    G.exec(legB, ['add', '-A'], STDIO_Q); G.exec(legB, ['commit', '-m', 'lb'], STDIO_Q);
    const M = (() => { G.exec(repoRoot, ['merge', '--no-ff', '-m', 'synth', 'kw/legs/test-project/A', 'kw/legs/test-project/B'], STDIO_Q); return gitOut(repoRoot, ['rev-parse', 'HEAD']); })();
    // make a DIVERGENT branch-point commit, re-anchor leg B's ref to it AND match its manifest baseline (so
    // B's #368 cross-check passes) — now A's base (baseRev) != B's base → split. Leg A's head is a real
    // commit != baseRev, so it serves as the divergent baseline for B.
    const divergent = gitOut(repoRoot, ['rev-parse', 'kw/legs/test-project/A']);
    G.exec(repoRoot, ['update-ref', legRefName('B'), divergent], STDIO_Q);
    const rs = readRS(cacheDir);
    rs.lane_group.legs.B.baseline = divergent;
    fs.writeFileSync(path.join(cacheDir, 'running-set.json'), JSON.stringify(rs, null, 2));
    const r = runVal(repoRoot, [planP(repoRoot), '--group-barrier', '--group-id', 'lg-A-B', '--merge-commit', M, '--project', 'test-project', '--json']);
    assert(r.result === 'refuse' && r.reason === 'leg_baseline_split', 'SYNTH-LEG-BASELINE-SPLIT: legs disagreeing on branch-point refuse leg_baseline_split, got ' + JSON.stringify(r));
    cleanup(repoRoot);
  });

  // SYNTH-SINGLETON-FAST-PATH (AC8): a single-write-node frontier forms NO lane group (tryFormLaneGroup
  //   needs ≥2) → NO leg worktree → runs serial in the parent with the normal per-node barrier.
  scenario(() => {
    const repoRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'd463-singleton-'));
    const projDir = path.join(repoRoot, 'kaola-workflow', 'test-project');
    const cacheDir = path.join(projDir, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    const planPath = path.join(projDir, 'workflow-plan.md');
    fs.writeFileSync(planPath, [
      '# Workflow Plan — test-project', '',
      '## Meta', 'labels: area:scripts', 'sink: CHANGELOG.md', '',
      '## Nodes', '',
      '| id | role | depends_on | declared_write_set | cardinality | shape |',
      '| --- | --- | --- | --- | --- | --- |',
      '| seed | code-explorer | — | — | 1 | sequence |',
      '| solo | tdd-guide | seed | solo.js | 1 | sequence |',
      '| review | code-reviewer | solo | — | 1 | sequence |',
      '| finalize | finalize | review | — | 1 | sequence |', '',
      '## Node Ledger', '',
      '| id | status |', '| --- | --- |',
      '| seed | complete |', '| solo | pending |', '| review | pending |', '| finalize | pending |', '',
    ].join('\n') + '\n');
    fs.writeFileSync(path.join(projDir, 'workflow-state.md'), '# State\n');
    const gs = (a) => execFileSync('git', ['-C', repoRoot, ...a], { stdio: ['ignore', 'ignore', 'ignore'] });
    gs(['init']); gs(['config', 'user.email', 'kw@test']); gs(['config', 'user.name', 'kw']); gs(['config', 'commit.gpgsign', 'false']);
    try { freezeLegacyFixture(execFileSync, 'node', VALIDATOR, planPath, { cwd: repoRoot, encoding: 'utf8' }); } catch (_) {}
    fs.writeFileSync(path.join(repoRoot, '.gitignore'), '.kw/\n');
    gs(['add', '-A']); gs(['commit', '-m', 'init']);
    const open = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], LEG_ON);
    assert(open.result === 'ok' && !open.laneGroup, 'SYNTH-SINGLETON: a single write node forms NO lane group, got ' + JSON.stringify(open));
    assert(worktreePaths(repoRoot).filter(p => p.indexOf(path.join('.kw', 'legs')) !== -1).length === 0, 'SYNTH-SINGLETON: NO leg worktree provisioned for a singleton');
    writeEvidence(cacheDir, 'solo');
    fs.writeFileSync(path.join(repoRoot, 'solo.js'), '// solo work in the PARENT (no leg)\n');
    const rc = runNode(repoRoot, ['close-node', '--node-id', 'solo', '--project', 'test-project', '--json'], LEG_ON);
    assert(rc.result === 'ok' && !rc.synthesized, 'SYNTH-SINGLETON: close runs the normal per-node barrier in the parent (no synthesizer), got ' + JSON.stringify(rc));
    cleanup(repoRoot);
  });

  // =========================================================================
  // #463-MERGE-CONFLICT (Slice 5) — the merge_conflict PRODUCERS + the bounded-repair envelope. The
  // textual-conflict tier is FREEZE-REFUSED (a same-file overlap can't co-open in a valid frozen plan), so
  // the octopus conflict bail is a DEFENSIVE catch exercised by calling synthesizeLevel directly (exactly the
  // path S6's injected-conflict live probe drives). The close-node-reachable producer is the NO-OP leg.
  // =========================================================================

  // S5-MERGE-CONFLICT-BAIL (codifies the spike; AC10 producer): two legs write CONFLICTING regions of the
  //   SAME file → synthesizeLevel's octopus BAILS → merge_conflict; the abort is CLEAN (HEAD unchanged, no
  //   MERGE_HEAD, tracked tree clean of conflict markers); the leg branches SURVIVE (capture committed them →
  //   recoverable for the repair). NO bad M lands on HEAD (the abort precedes any advance).
  scenario(() => {
    const { repoRoot, legA, legB, rs } = provisionedRepo();
    const base = rs.lane_group.legs.A.baseline;
    fs.writeFileSync(path.join(legA, 'conflict.txt'), 'AAA\nshared-2\nshared-3\n');
    fs.writeFileSync(path.join(legB, 'conflict.txt'), 'BBB\nshared-2\nshared-3\n');
    const synth = synthesizeLevel(repoRoot, rs.lane_group.legs, 'lg-A-B');
    assert(synth && synth.ok === false && synth.reason === 'merge_conflict', 'S5-MERGE-CONFLICT-BAIL: a same-file conflict bails merge_conflict, got ' + JSON.stringify(synth));
    assert(gitOut(repoRoot, ['rev-parse', 'HEAD']) === base, 'S5-MERGE-CONFLICT-BAIL: HEAD unchanged after the abort (no half-merge advance), got ' + gitOut(repoRoot, ['rev-parse', 'HEAD']) + ' vs base ' + base);
    const gitDir = gitOut(repoRoot, ['rev-parse', '--git-dir']);
    const mh = path.isAbsolute(gitDir) ? path.join(gitDir, 'MERGE_HEAD') : path.join(repoRoot, gitDir, 'MERGE_HEAD');
    assert(!fs.existsSync(mh), 'S5-MERGE-CONFLICT-BAIL: no MERGE_HEAD left (abort cleaned merge state)');
    // `git ls-files -u` (unmerged index entries) is the churn-independent clean-abort signal: a half-merge
    // leaves unmerged entries; the abort clears them. (The plan/.cache workflow churn in the parent is
    // expected — the run never commits per-node — so a porcelain check would false-fail here.)
    assert(gitOut(repoRoot, ['ls-files', '-u']) === '', 'S5-MERGE-CONFLICT-BAIL: no unmerged index entries after abort (clean, no conflict state)');
    assert(gitOut(repoRoot, ['rev-parse', 'kw/legs/test-project/A']) !== base && gitOut(repoRoot, ['rev-parse', 'kw/legs/test-project/B']) !== base, 'S5-MERGE-CONFLICT-BAIL: both leg branches survived past base (work recoverable for repair)');
    cleanup(repoRoot);
  });

  // S5-NOOP-LEG-VACUITY (AC10 first-detection producer): a leg that produced NO changes is caught by the
  //   leg-aware member_vacuity guard at THAT member's OWN close — BEFORE the last-member synthesis, where the
  //   evidence (and a possible no_op: declaration) is visible. This IS the "a leg that produced no changes"
  //   producer the AC names; merge_conflict is what it escalates TO after K=3 (NOT a new detector — a
  //   synthesizeLevel detector there would false-positive a sanctioned no_op member). B stays in_progress.
  scenario(() => {
    const { repoRoot, cacheDir, legA } = provisionedRepo();
    writeEvidence(cacheDir, 'A'); writeEvidence(cacheDir, 'B');
    fs.writeFileSync(path.join(legA, 'ax.js'), '// A leg work\n');
    // legB: untouched → no-op leg.
    const rA = runNode(repoRoot, ['close-node', '--node-id', 'A', '--project', 'test-project', '--json'], LEG_ON);
    assert(rA.result === 'ok' && rA.barrier === 'deferred_to_group', 'S5-NOOP-LEG: A deferred, got ' + JSON.stringify(rA));
    const rB = runNode(repoRoot, ['close-node', '--node-id', 'B', '--project', 'test-project', '--json'], LEG_ON);
    assert(rB.result === 'refuse' && rB.reason === 'member_vacuity', 'S5-NOOP-LEG: a no-op leg refuses member_vacuity at the member close (the no-op-leg producer), got ' + JSON.stringify(rB));
    assert(ledgerStatus(planP(repoRoot), 'B') === 'in_progress', 'S5-NOOP-LEG: B stays in_progress on refusal');
    cleanup(repoRoot);
  });

  // S5-NOOP-LEG-REPAIR-THEN-SUCCESS (the bounded-repair loop CLOSES): after a member_vacuity refuse the
  //   orchestrator re-dispatches legB (writes its declared file); re-running close now defers, and the
  //   last-member close synthesizes + advances. Proves the no-op producer is repairable, not a dead end.
  scenario(() => {
    const { repoRoot, cacheDir, legA, legB } = provisionedRepo();
    writeEvidence(cacheDir, 'A'); writeEvidence(cacheDir, 'B');
    fs.writeFileSync(path.join(legA, 'ax.js'), '// A leg work\n');
    const rApre = runNode(repoRoot, ['close-node', '--node-id', 'A', '--project', 'test-project', '--json'], LEG_ON);
    assert(rApre.result === 'ok', 'S5-NOOP-REPAIR: A deferred, got ' + JSON.stringify(rApre));
    const refuse = runNode(repoRoot, ['close-node', '--node-id', 'B', '--project', 'test-project', '--json'], LEG_ON);
    assert(refuse.result === 'refuse' && refuse.reason === 'member_vacuity', 'S5-NOOP-REPAIR: precondition member_vacuity, got ' + JSON.stringify(refuse));
    // REPAIR: re-dispatch legB — it now writes its declared file.
    fs.writeFileSync(path.join(legB, 'by.js'), '// B leg work (re-dispatched)\n');
    const rB = runNode(repoRoot, ['close-node', '--node-id', 'B', '--project', 'test-project', '--json'], LEG_ON);
    assert(rB.result === 'ok' && rB.barrier === 'group_passed' && rB.synthesized === true, 'S5-NOOP-REPAIR: after re-dispatch the last-member close synthesizes + advances, got ' + JSON.stringify(rB));
    cleanup(repoRoot);
  });

  // S5-CAPTURE-UNCOMMITTED (synthesizeLevel robustness): a leg with UNCOMMITTED work (agent forgot to
  //   commit) is CAPTURED (add -A + commit) before the octopus → the merge sees it. Proves the script-owned
  //   capture is robust to an un-committing agent.
  scenario(() => {
    const { repoRoot, legA, legB, rs } = provisionedRepo();
    fs.writeFileSync(path.join(legA, 'ax.js'), '// A uncommitted\n');
    fs.writeFileSync(path.join(legB, 'by.js'), '// B uncommitted\n');
    const synth = synthesizeLevel(repoRoot, rs.lane_group.legs, 'lg-A-B');
    assert(synth && synth.ok === true && typeof synth.mergeCommit === 'string', 'S5-CAPTURE-UNCOMMITTED: uncommitted leg work is captured + merged, got ' + JSON.stringify(synth));
    assert(gitOut(repoRoot, ['rev-parse', synth.mergeCommit + ':ax.js']) !== '' && gitOut(repoRoot, ['rev-parse', synth.mergeCommit + ':by.js']) !== '', 'S5-CAPTURE-UNCOMMITTED: M contains both captured files');
    cleanup(repoRoot);
  });

  // #820-TELEMETRY-EXCLUDED-OCTOPUS (the original add/add defect, real-git two-leg reproduction): run
  //   telemetry (.cache/node-timings.jsonl) is PARENT-OWNED — a leg-side invocation dirties the leg's
  //   OWN copy, and the per-leg capture sweep must EXCLUDE it. Pre-fix each leg's `add -A` swept it in,
  //   so BOTH leg branches ADDed the same path independently and the octopus merge failed add/add on
  //   scheduler residue (the #819 group needed hand repair). Post-fix the sweep still captures every
  //   real write, the merge is clean, and the parent copy takes its leg_committed appends untracked.
  //   (RED-provable: pre-fix synthesizeLevel returns {ok:false, reason:'merge_conflict'} here.)
  scenario(() => {
    const { repoRoot, cacheDir, legA, legB, rs } = provisionedRepo();
    const telRel = 'kaola-workflow/test-project/.cache/node-timings.jsonl';
    // Leg-side telemetry residue in BOTH legs (untracked in each — the legs branched off the kw-stub
    // commit, which tracks only the evidence seeds, never the run telemetry).
    fs.appendFileSync(path.join(legA, telRel), JSON.stringify({ node: 'A', event: 'opened', ts: '2026-01-01T00:00:00.000Z' }) + '\n');
    fs.appendFileSync(path.join(legB, telRel), JSON.stringify({ node: 'B', event: 'opened', ts: '2026-01-01T00:00:01.000Z' }) + '\n');
    fs.writeFileSync(path.join(legA, 'ax.js'), '// A uncommitted\n');
    fs.writeFileSync(path.join(legB, 'by.js'), '// B uncommitted\n');
    const synth = synthesizeLevel(repoRoot, rs.lane_group.legs, 'lg-A-B', planP(repoRoot));
    assert(synth && synth.ok === true && typeof synth.mergeCommit === 'string',
      '#820-TELEMETRY-EXCLUDED: leg-side telemetry residue no longer fails the octopus merge add/add (pre-fix: merge_conflict), got ' + JSON.stringify(synth));
    assert(gitOut(repoRoot, ['rev-parse', synth.mergeCommit + ':' + telRel]) === '',
      '#820-TELEMETRY-EXCLUDED: the telemetry path is ABSENT from the merge commit tree (parent-owned, never leg-carried)');
    assert(gitOut(repoRoot, ['rev-parse', synth.mergeCommit + ':ax.js']) !== '' && gitOut(repoRoot, ['rev-parse', synth.mergeCommit + ':by.js']) !== '',
      '#820-TELEMETRY-EXCLUDED: both legs\' REAL writes are still captured into M');
    const legATree = gitOut(repoRoot, ['ls-tree', '-r', '--name-only', 'kw/legs/test-project/A']);
    const legBTree = gitOut(repoRoot, ['ls-tree', '-r', '--name-only', 'kw/legs/test-project/B']);
    assert(legATree.split('\n').indexOf(telRel) === -1 && legBTree.split('\n').indexOf(telRel) === -1,
      '#820-TELEMETRY-EXCLUDED: NEITHER leg branch tracks the telemetry path (the add/add vector itself is gone)');
    // The parent-owned copy is where the run's telemetry lives: the capture's leg_committed appends
    // land there, and it stays UNTRACKED — the merge never carries a path that would collide with it.
    assert(timingsHas(cacheDir, 'A', 'leg_committed') && timingsHas(cacheDir, 'B', 'leg_committed'),
      '#820-TELEMETRY-EXCLUDED: leg_committed appends land in the PARENT-owned telemetry copy');
    assert(gitOut(repoRoot, ['status', '--porcelain', '--', telRel]) === '?? ' + telRel,
      '#820-TELEMETRY-EXCLUDED: the parent telemetry copy stays UNTRACKED after the merge, got '
      + JSON.stringify(gitOut(repoRoot, ['status', '--porcelain', '--', telRel])));
    cleanup(repoRoot);
  });

  // #820-SKIP-EMPTY-CAPTURE: when the member committed its own work and the ONLY leg residue is the
  //   excluded telemetry sidecar, the excluded sweep leaves NOTHING staged — pre-fix the capture swept
  //   the sidecar in (the add/add vector, branch head advanced with scheduler residue); post-fix it
  //   SKIPS the empty commit (the leg is, correctly, already fully committed) and the merge stays clean.
  scenario(() => {
    const { repoRoot, legA, legB, rs } = provisionedRepo();
    const telRel = 'kaola-workflow/test-project/.cache/node-timings.jsonl';
    fs.writeFileSync(path.join(legA, 'ax.js'), '// a\n');
    G.exec(legA, ['add', '-A'], STDIO_Q); G.exec(legA, ['commit', '-m', 'la'], STDIO_Q);
    fs.writeFileSync(path.join(legB, 'by.js'), '// b\n');
    G.exec(legB, ['add', '-A'], STDIO_Q); G.exec(legB, ['commit', '-m', 'lb'], STDIO_Q);
    const headA = gitOut(repoRoot, ['rev-parse', 'kw/legs/test-project/A']);
    const headB = gitOut(repoRoot, ['rev-parse', 'kw/legs/test-project/B']);
    // ONLY the excluded telemetry residue remains uncommitted in each leg.
    fs.appendFileSync(path.join(legA, telRel), JSON.stringify({ node: 'A', event: 'closed', ts: '2026-01-01T00:01:00.000Z' }) + '\n');
    fs.appendFileSync(path.join(legB, telRel), JSON.stringify({ node: 'B', event: 'closed', ts: '2026-01-01T00:01:01.000Z' }) + '\n');
    const synth = synthesizeLevel(repoRoot, rs.lane_group.legs, 'lg-A-B', planP(repoRoot));
    assert(synth && synth.ok === true && typeof synth.mergeCommit === 'string',
      '#820-SKIP-EMPTY-CAPTURE: telemetry-only residue still merges clean (pre-fix: the swept sidecar failed add/add), got ' + JSON.stringify(synth));
    assert(gitOut(repoRoot, ['rev-parse', 'kw/legs/test-project/A']) === headA && gitOut(repoRoot, ['rev-parse', 'kw/legs/test-project/B']) === headB,
      '#820-SKIP-EMPTY-CAPTURE: NO residue-only capture commit lands on either leg branch (skip-empty-commit), heads unchanged');
    assert(gitOut(repoRoot, ['rev-parse', synth.mergeCommit + ':' + telRel]) === '',
      '#820-SKIP-EMPTY-CAPTURE: the telemetry path is ABSENT from the merge commit tree');
    assert(gitOut(repoRoot, ['rev-parse', synth.mergeCommit + ':ax.js']) !== '' && gitOut(repoRoot, ['rev-parse', synth.mergeCommit + ':by.js']) !== '',
      '#820-SKIP-EMPTY-CAPTURE: the pre-committed leg work still merges');
    cleanup(repoRoot);
  });

  // #820-CLOSE-NODE-E2E (the full reported path): close-node's last-member synthesis no longer blocks
  //   on telemetry — neither the add/add between leg branches nor the untracked parent copy the merge
  //   would have overwritten. Both legs carry real work + evidence + leg-side telemetry residue; the
  //   parent copy holds the run's appends untracked. Pre-fix the last-member close refused
  //   merge_conflict; post-fix the group closes group_passed and the merged tree carries NO telemetry.
  scenario(() => {
    const { repoRoot, cacheDir, legA, legB } = provisionedRepo();
    const telRel = 'kaola-workflow/test-project/.cache/node-timings.jsonl';
    writeEvidence(cacheDir, 'A'); writeEvidence(cacheDir, 'B');
    fs.writeFileSync(path.join(legA, 'ax.js'), '// A leg work\n');
    fs.writeFileSync(path.join(legB, 'by.js'), '// B leg work\n');
    fs.appendFileSync(path.join(legA, telRel), JSON.stringify({ node: 'A', event: 'opened', ts: '2026-01-01T00:02:00.000Z' }) + '\n');
    fs.appendFileSync(path.join(legB, telRel), JSON.stringify({ node: 'B', event: 'opened', ts: '2026-01-01T00:02:01.000Z' }) + '\n');
    const rA = runNode(repoRoot, ['close-node', '--node-id', 'A', '--project', 'test-project', '--json'], LEG_ON);
    assert(rA.result === 'ok' && rA.barrier === 'deferred_to_group', '#820-CLOSE-E2E: A deferred, got ' + JSON.stringify(rA));
    const rB = runNode(repoRoot, ['close-node', '--node-id', 'B', '--project', 'test-project', '--json'], LEG_ON);
    assert(rB.result === 'ok' && rB.barrier === 'group_passed' && rB.synthesized === true,
      '#820-CLOSE-E2E: the last-member close synthesizes + advances despite leg-side telemetry residue (pre-fix: merge_conflict refuse), got ' + JSON.stringify(rB));
    assert(gitOut(repoRoot, ['rev-parse', 'HEAD:' + telRel]) === '',
      '#820-CLOSE-E2E: the merged HEAD tree carries NO telemetry path (parent-owned, never leg-carried)');
    assert(gitOut(repoRoot, ['rev-parse', 'HEAD:ax.js']) !== '' && gitOut(repoRoot, ['rev-parse', 'HEAD:by.js']) !== '',
      '#820-CLOSE-E2E: both legs\' real work merged');
    assert(ledgerStatus(planP(repoRoot), 'A') === 'complete' && ledgerStatus(planP(repoRoot), 'B') === 'complete',
      '#820-CLOSE-E2E: both members closed complete');
    cleanup(repoRoot);
  });

  // S5-IDEMPOTENT-RESUME (codifies the spike; S4 carry-over): re-running synthesizeLevel over the SAME
  //   already-merged disjoint legs (a crash after M committed but before the ledger advanced) is a NO-OP —
  //   it returns the SAME mergeCommit with a STABLE HEAD, never a spurious second merge or merge_conflict.
  scenario(() => {
    const { repoRoot, legA, legB, rs } = provisionedRepo();
    fs.writeFileSync(path.join(legA, 'ax.js'), '// a\n');
    fs.writeFileSync(path.join(legB, 'by.js'), '// b\n');
    const r1 = synthesizeLevel(repoRoot, rs.lane_group.legs, 'lg-A-B');
    assert(r1 && r1.ok === true, 'S5-IDEMPOTENT-RESUME: first synth ok, got ' + JSON.stringify(r1));
    const head1 = gitOut(repoRoot, ['rev-parse', 'HEAD']);
    const r2 = synthesizeLevel(repoRoot, rs.lane_group.legs, 'lg-A-B');
    assert(r2 && r2.ok === true && r2.mergeCommit === r1.mergeCommit, 'S5-IDEMPOTENT-RESUME: re-synth returns the SAME mergeCommit, got ' + JSON.stringify(r2) + ' vs ' + JSON.stringify(r1));
    assert(gitOut(repoRoot, ['rev-parse', 'HEAD']) === head1, 'S5-IDEMPOTENT-RESUME: HEAD stable across re-synth (no spurious second merge)');
    cleanup(repoRoot);
  });

  // S5-PROBE-FAILED-REFUSE (#672 fail-closed): the leg-dirty probe (`git status --porcelain` in the
  //   leg) can itself FAIL (a broken git invocation on the leg, a >maxBuffer porcelain, ...). That
  //   must NEVER be read as "leg is clean" — real leg content (here, A's uncommitted ax.js) would be
  //   silently OMITTED from the octopus merge (never committed, never folded into M). synthesizeLevel
  //   must refuse loudly instead of guessing clean. legA's worktree git-link is corrupted (a broken
  //   invocation, not a genuinely-missing leg) so `git -C legA status --porcelain` throws.
  scenario(() => {
    const { repoRoot, legA, legB, rs } = provisionedRepo();
    const base = rs.lane_group.legs.A.baseline;
    fs.writeFileSync(path.join(legA, 'ax.js'), '// A real work that must never be silently dropped\n');
    fs.writeFileSync(path.join(legB, 'by.js'), '// B work\n');
    fs.writeFileSync(path.join(legA, '.git'), 'gitdir: /nonexistent/broken/gitdir/path\n');
    const synth = synthesizeLevel(repoRoot, rs.lane_group.legs, 'lg-A-B');
    assert(synth && synth.ok === false && synth.reason === 'leg_dirty_probe_failed' && synth.leg === 'A',
      'S5-PROBE-FAILED-REFUSE: a leg-dirty probe failure refuses loudly (never silently treated clean), got ' + JSON.stringify(synth));
    assert(gitOut(repoRoot, ['rev-parse', 'HEAD']) === base,
      'S5-PROBE-FAILED-REFUSE: HEAD unchanged after the refuse (no partial merge landed, dropping A silently), got ' + gitOut(repoRoot, ['rev-parse', 'HEAD']) + ' vs base ' + base);
    cleanup(repoRoot);
  });

  // S5-REPAIR-LIMIT-CONSTANT (contract): the K=3 cap is a schema constant (×4 byte, route-like-test_thrash)
  //   and the merge_conflict operator_hint interpolates it (so the bound is operator-visible, not buried).
  scenario(() => {
    assert(MERGE_CONFLICT_REPAIR_LIMIT === 3, 'S5-REPAIR-LIMIT-CONSTANT: MERGE_CONFLICT_REPAIR_LIMIT === 3, got ' + MERGE_CONFLICT_REPAIR_LIMIT);
    const hint = OPERATOR_HINT_REGISTRY.merge_conflict({ group_id: 'g1', nodeId: 'B' });
    assert(hint.indexOf(String(MERGE_CONFLICT_REPAIR_LIMIT) + ' repair attempts') !== -1 && /write-halt/.test(hint), 'S5-REPAIR-LIMIT-CONSTANT: the merge_conflict hint names the K cap + the write-halt escalation, got ' + JSON.stringify(hint));
  });

  // S5-MULTI-LEVEL (AC7, S4 carry-over): TWO sequential fan-out levels. Level 1 {A,B} synthesizes → M1 (HEAD
  //   advances); level 2 {C,D} then provisions its legs OFF M1 (their branch-point baseline == M1) and
  //   synthesizes → M2 with M1 in its ancestry. The dependency-level commit chains: M2 descends from M1.
  scenario(() => {
    const repoRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'd463-multilevel-'));
    const projDir = path.join(repoRoot, 'kaola-workflow', 'test-project');
    const cacheDir = path.join(projDir, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    const planPath = path.join(projDir, 'workflow-plan.md');
    fs.writeFileSync(planPath, [
      '# Workflow Plan — test-project', '',
      '## Meta', 'labels: area:scripts', 'sink: CHANGELOG.md', '',
      '## Nodes', '',
      '| id | role | depends_on | declared_write_set | cardinality | shape |',
      '| --- | --- | --- | --- | --- | --- |',
      '| seed | code-explorer | — | — | 1 | sequence |',
      '| A | tdd-guide | seed | ax.js | 1 | sequence |',
      '| B | tdd-guide | seed | by.js | 1 | sequence |',
      '| C | tdd-guide | A,B | cx.js | 1 | sequence |',
      '| D | tdd-guide | A,B | dy.js | 1 | sequence |',
      '| review | code-reviewer | C,D | — | 1 | sequence |',
      '| finalize | finalize | review | — | 1 | sequence |', '',
      '## Node Ledger', '',
      '| id | status |', '| --- | --- |',
      '| seed | complete |', '| A | pending |', '| B | pending |', '| C | pending |', '| D | pending |',
      '| review | pending |', '| finalize | pending |', '',
    ].join('\n') + '\n');
    fs.writeFileSync(path.join(projDir, 'workflow-state.md'), '# State\n');
    const gs = (a) => execFileSync('git', ['-C', repoRoot, ...a], { stdio: ['ignore', 'ignore', 'ignore'] });
    gs(['init']); gs(['config', 'user.email', 'kw@test']); gs(['config', 'user.name', 'kw']); gs(['config', 'commit.gpgsign', 'false']);
    try { freezeLegacyFixture(execFileSync, 'node', VALIDATOR, planPath, { cwd: repoRoot, encoding: 'utf8' }); } catch (_) {}
    fs.writeFileSync(path.join(repoRoot, '.gitignore'), '.kw/\n');
    gs(['add', '-A']); gs(['commit', '-m', 'init']);
    // LEVEL 1: open {A,B}, close both → M1.
    const open1 = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], LEG_ON);
    assert(open1.result === 'ok' && open1.laneGroup, 'S5-MULTI-LEVEL: level-1 {A,B} co-opens, got ' + JSON.stringify(open1));
    const leg1A = path.join(repoRoot, '.kw', 'legs', 'test-project', 'A');
    const leg1B = path.join(repoRoot, '.kw', 'legs', 'test-project', 'B');
    writeEvidence(cacheDir, 'A'); writeEvidence(cacheDir, 'B');
    fs.writeFileSync(path.join(leg1A, 'ax.js'), '// A1\n');
    fs.writeFileSync(path.join(leg1B, 'by.js'), '// B1\n');
    runNode(repoRoot, ['close-node', '--node-id', 'A', '--project', 'test-project', '--json'], LEG_ON);
    const rB = runNode(repoRoot, ['close-node', '--node-id', 'B', '--project', 'test-project', '--json'], LEG_ON);
    assert(rB.result === 'ok' && rB.barrier === 'group_passed', 'S5-MULTI-LEVEL: level-1 synthesizes, got ' + JSON.stringify(rB));
    const M1 = gitOut(repoRoot, ['rev-parse', 'HEAD']);
    assert(M1 === rB.mergeCommit, 'S5-MULTI-LEVEL: HEAD advanced to M1');
    // LEVEL 2: open {C,D} — legs must branch OFF M1.
    const open2 = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], LEG_ON);
    assert(open2.result === 'ok' && open2.laneGroup, 'S5-MULTI-LEVEL: level-2 {C,D} co-opens off M1, got ' + JSON.stringify(open2));
    const rs2 = readRS(cacheDir);
    // #633 (D-622-01): the leg branch-point is no longer BYTE-EQUAL to M1 — open-ready now commits a
    // TRACKED evidence-stub seed (the #633 fix) on the parent branch BEFORE each leg branches off, so the
    // legs branch from a commit ONE STEP AHEAD of M1 (M1 is its parent). Assert the WEAKER, still-
    // meaningful invariant the #633 fix preserves: M1 is an ANCESTOR of (not necessarily equal to) each
    // leg's recorded baseline — legs still branch off the prior level's commit chain, just past the
    // stub-seed commit the fix inserts.
    let m1AncestorOfC = false, m1AncestorOfD = false;
    try { G.exec(repoRoot, ['merge-base', '--is-ancestor', M1, rs2.lane_group.legs.C.baseline], STDIO_Q); m1AncestorOfC = true; } catch (_) { m1AncestorOfC = false; }
    try { G.exec(repoRoot, ['merge-base', '--is-ancestor', M1, rs2.lane_group.legs.D.baseline], STDIO_Q); m1AncestorOfD = true; } catch (_) { m1AncestorOfD = false; }
    assert(m1AncestorOfC && m1AncestorOfD, 'S5-MULTI-LEVEL: level-2 leg baselines descend from M1 (legs branch off the prior level\'s commit chain, past the #633 stub-seed commit), got ' + JSON.stringify({ C: rs2.lane_group.legs.C.baseline, D: rs2.lane_group.legs.D.baseline, M1 }));
    const leg2C = path.join(repoRoot, '.kw', 'legs', 'test-project', 'C');
    const leg2D = path.join(repoRoot, '.kw', 'legs', 'test-project', 'D');
    writeEvidence(cacheDir, 'C'); writeEvidence(cacheDir, 'D');
    fs.writeFileSync(path.join(leg2C, 'cx.js'), '// C2\n');
    fs.writeFileSync(path.join(leg2D, 'dy.js'), '// D2\n');
    runNode(repoRoot, ['close-node', '--node-id', 'C', '--project', 'test-project', '--json'], LEG_ON);
    const rD = runNode(repoRoot, ['close-node', '--node-id', 'D', '--project', 'test-project', '--json'], LEG_ON);
    assert(rD.result === 'ok' && rD.barrier === 'group_passed', 'S5-MULTI-LEVEL: level-2 synthesizes → M2, got ' + JSON.stringify(rD));
    const M2 = gitOut(repoRoot, ['rev-parse', 'HEAD']);
    // `merge-base --is-ancestor` signals via EXIT CODE only (0 = ancestor, 1 = not) and emits NO stdout in
    // either direction — so a `gitOut(...) === ''` (stdout) check would be a tautology (both directions →
    // '' → always passes). Key on the exit code, exactly as the production validator does (plan-validator.js).
    let m2DescendsM1 = false;
    try { G.exec(repoRoot, ['merge-base', '--is-ancestor', M1, M2], STDIO_Q); m2DescendsM1 = true; } catch (_) { m2DescendsM1 = false; }
    assert(m2DescendsM1, 'S5-MULTI-LEVEL: M2 descends from M1 (the dependency-level commit chain), got is-ancestor=false for M1=' + M1 + ' M2=' + M2);
    cleanup(repoRoot);
  });

  // =========================================================================
  // #500-SHARED-INFRA-COARSE (leg-couple wire) — shared-infra + coarse co-open under the retained net.
  //
  // The formation gate (tryFormLaneGroup) calls the validator's --parallel-safe so an overlapping pair
  // can RELAX and co-open. #546-G2 (DECISION B) shifted the SHARED-INFRA class to relax BY DEFAULT under
  // the structural net (a post-dominating code-reviewer gate over the legs + no PROTECTED file); #593
  // extends the SAME default-relax to the NON-shared COARSE class (two different top-level dirs,
  // exact-file-disjoint) — NO write_overlap_policy, NO --write-overlap-consent (both vestigial); #760
  // further extends coarse to relax even when disjointness is UNPROVABLE (a directory/glob entry —
  // genuinely uncertain, not a named serializer). What STILL serial-degrades: a genuine PROVEN overlap
  // (exact / case-collision), a PROTECTED file (NET-2), or a missing gate (NET-1). Tests drive the REAL
  // adaptive-node + plan-validator subprocesses in a REAL git repo.
  // =========================================================================
  scenario(() => {
    // SHARED-INFRA FIXTURE: scripts/aa.js + scripts/bb.js → both areaForPath === 'scripts' ∈
    // SHARED_INFRA → disjointWriteSets verdict:yellow/kind:'shared-infra'. Under #546-G2 this relaxes
    // BY DEFAULT (no policy / no consent) once the gate net holds. makeLaneRepo always builds the
    // post-dominating code-reviewer `review` gate, so gatePresent is true.
    const sharedInfraRepo = () => makeLaneRepo({ aSet: 'scripts/aa.js', bSet: 'scripts/bb.js' });
    // COARSE FIXTURE (#593 default-relax): crates/a/x.rs + crates/b/y.rs share the NON-shared coarse
    // area "crates" → disjointWriteSets verdict:red/kind:'coarse'. Under #593 this relaxes BY DEFAULT
    // under the SAME net as shared-infra (no policy / no consent) — write_overlap_policy is vestigial.
    const coarseRepo = () => makeLaneRepo({ writeOverlapPolicy: 'coarse', aSet: 'crates/a/x.rs', bSet: 'crates/b/y.rs' });

    // -----------------------------------------------------------------------
    // #500-DISCRIMINATOR: direct validator --parallel-safe probe (NOT in production code). Proves the
    // RELAXATION path (writeOverlapRelaxable) — not the green short-circuit — for BOTH classes, both of
    // which now relax BY DEFAULT under the retained net (#546-G2 shared-infra + #593 coarse):
    //   • shared-infra: result==='ok' AND relaxed[0].kind==='shared-infra' WITHOUT consent.
    //   • coarse: result==='ok' AND relaxed[0].kind==='coarse' WITHOUT consent (the #593 delta) — and
    //     identically WITH consent (policy/consent vestigial).
    // -----------------------------------------------------------------------
    {
      // shared-infra: relaxes by default (NO consent).
      const { repoRoot, planPath } = sharedInfraRepo();
      const rDefault = runVal(repoRoot, [planPath, '--parallel-safe', '--nodes', 'A,B', '--json']);
      assert(rDefault.result === 'ok', '#500-DISCRIMINATOR shared-infra: --parallel-safe ok BY DEFAULT (no consent, #546-G2), got ' + JSON.stringify(rDefault));
      assert(Array.isArray(rDefault.relaxed) && rDefault.relaxed.length > 0 && rDefault.relaxed[0].kind === 'shared-infra',
        '#500-DISCRIMINATOR shared-infra: relaxed[0].kind==="shared-infra" by default (relaxation path, not green short-circuit), got ' + JSON.stringify(rDefault.relaxed));
      cleanup(repoRoot);
    }
    {
      // coarse (non-shared): relaxes BY DEFAULT under the net (#593), identically with/without consent.
      const { repoRoot, planPath } = coarseRepo();
      const rPos = runVal(repoRoot, [planPath, '--parallel-safe', '--nodes', 'A,B', '--write-overlap-consent', '--json']);
      assert(rPos.result === 'ok', '#500-DISCRIMINATOR coarse (with consent): --parallel-safe ok, got ' + JSON.stringify(rPos));
      assert(Array.isArray(rPos.relaxed) && rPos.relaxed.length > 0 && rPos.relaxed[0].kind === 'coarse',
        '#500-DISCRIMINATOR coarse (with consent): relaxed[0].kind==="coarse" (relaxation path), got ' + JSON.stringify(rPos.relaxed));
      const rNeg = runVal(repoRoot, [planPath, '--parallel-safe', '--nodes', 'A,B', '--json']);
      assert(rNeg.result === 'ok', '#500-DISCRIMINATOR coarse (NO consent, #593): --parallel-safe relaxes BY DEFAULT under the net, got ' + JSON.stringify(rNeg));
      assert(Array.isArray(rNeg.relaxed) && rNeg.relaxed.some(x => x.kind === 'coarse'),
        '#500-DISCRIMINATOR coarse (NO consent, #593): relaxed[] carries kind coarse (default-relax, consent vestigial), got ' + JSON.stringify(rNeg.relaxed));
      cleanup(repoRoot);
    }

    // -----------------------------------------------------------------------
    // ★ #500-POSITIVE-E2E (#546-G2 default-on): a shared-infra pair group FORMS via relaxation BY
    //   DEFAULT (NO --write-overlap-consent), legs provisioned, disjoint writes synthesized end-to-end.
    //   (Translated from SYNTH-DISJOINT with shared-infra fixture + scripts/ subdir.)
    // -----------------------------------------------------------------------
    {
      const { repoRoot, cacheDir, planPath } = sharedInfraRepo();
      // Open: shared-infra pair co-opens BY DEFAULT (the gate net relaxes it — no consent flag).
      const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], LEG_ON);
      assert(r.result === 'ok', '#500-POSITIVE-E2E: open-ready ok, got ' + JSON.stringify(r));
      assert(r.laneGroup && Array.isArray(r.laneGroup.members), '#500-POSITIVE-E2E: laneGroup formed (shared-infra relaxed by default), got ' + JSON.stringify(r.laneGroup));
      assert(r.laneGroup.members.includes('A') && r.laneGroup.members.includes('B'), '#500-POSITIVE-E2E: members [A,B]');
      // Running-set: legs provisioned.
      const rs = readRS(cacheDir);
      assert(rs && rs.lane_group && rs.lane_group.legs, '#500-POSITIVE-E2E: running-set lane_group.legs present');
      for (const id of ['A', 'B']) {
        const leg = rs.lane_group.legs[id];
        assert(leg && typeof leg.legPath === 'string', '#500-POSITIVE-E2E: legs.' + id + '.legPath present');
        assert(leg && typeof leg.baseline === 'string', '#500-POSITIVE-E2E: legs.' + id + '.baseline present');
      }
      // Write declared files INTO legs (scripts/ subdir must exist under each leg).
      const legA = rs.lane_group.legs.A.legPath;
      const legB = rs.lane_group.legs.B.legPath;
      fs.mkdirSync(path.join(legA, 'scripts'), { recursive: true });
      fs.mkdirSync(path.join(legB, 'scripts'), { recursive: true });
      writeEvidence(cacheDir, 'A');
      writeEvidence(cacheDir, 'B');
      fs.writeFileSync(path.join(legA, 'scripts', 'aa.js'), '// A shared-infra leg work\n');
      fs.writeFileSync(path.join(legB, 'scripts', 'bb.js'), '// B shared-infra leg work\n');
      const base = rs.lane_group.legs.A.baseline;
      // Close A (non-last) → deferred.
      const rA = runNode(repoRoot, ['close-node', '--node-id', 'A', '--project', 'test-project', '--json'], LEG_ON);
      assert(rA.result === 'ok' && rA.barrier === 'deferred_to_group', '#500-POSITIVE-E2E: close A deferred, got ' + JSON.stringify(rA));
      // Close B (last) → group_passed + synthesized.
      const rB = runNode(repoRoot, ['close-node', '--node-id', 'B', '--project', 'test-project', '--json'], LEG_ON);
      assert(rB.result === 'ok' && rB.barrier === 'group_passed' && rB.synthesized === true,
        '#500-POSITIVE-E2E: close B group_passed + synthesized, got ' + JSON.stringify(rB));
      const M = rB.mergeCommit;
      assert(typeof M === 'string' && M.length >= 7, '#500-POSITIVE-E2E: B carries mergeCommit M, got ' + JSON.stringify(rB));
      // HEAD advanced to M.
      assert(gitOut(repoRoot, ['rev-parse', 'HEAD']) === M, '#500-POSITIVE-E2E: HEAD advanced to M');
      // M contains BOTH files.
      assert(gitOut(repoRoot, ['rev-parse', M + ':scripts/aa.js']) !== '' && gitOut(repoRoot, ['rev-parse', M + ':scripts/bb.js']) !== '',
        '#500-POSITIVE-E2E: M contains BOTH scripts/aa.js and scripts/bb.js');
      // diff base→M == exactly the two declared files.
      const mDiff = gitOut(repoRoot, ['diff-tree', '-r', '--name-only', base, M]).split('\n')
        .map(s => s.trim()).filter(s => s && !isProjectWorkflowChurn(s, 'test-project')).sort();
      assert(JSON.stringify(mDiff) === JSON.stringify(['scripts/aa.js', 'scripts/bb.js']),
        '#500-POSITIVE-E2E: diff base→M == union declared {scripts/aa.js, scripts/bb.js}, got ' + JSON.stringify(mDiff));
      // Legs torn down.
      const wts = worktreePaths(repoRoot);
      assert(!wts.some(p => p.indexOf(path.join('.kw', 'legs')) !== -1),
        '#500-POSITIVE-E2E: no .kw/legs worktree survives clean completion, got ' + JSON.stringify(wts));
      cleanup(repoRoot);
    }

    // -----------------------------------------------------------------------
    // ★ #500-NEGATIVE-A (#542 default-on + the kill-switch guard): the coarseRepo fixture is a NON-shared
    //   coarse (crates/a/x.rs + crates/b/y.rs share dir "crates" ∉ SHARED_INFRA), exact-file-disjoint
    //   pair. Under #593 it co-opens BY DEFAULT under the net (with OR without consent — consent is
    //   vestigial); the shared-infra class likewise (see #500-DISCRIMINATOR + #500-POSITIVE-E2E). Under
    //   #542 (D-542-01) the legacy toggles no longer gate co-open. The ONLY serial path is the explicit
    //   kill-switch KAOLA_PARALLEL_WRITES=0 — which forces serial EVEN with consent. Both halves
    //   asserted: (a) bare default ⇒ co-open (default-on); (b) kill-switch ⇒ serial-degrade.
    // -----------------------------------------------------------------------
    {
      // (a) Default-on: the coarse pair co-opens WITHOUT any legacy toggle (bare default; consent kept
      //     here for back-compat but vestigial post-#593).
      const { repoRoot, cacheDir, planPath } = coarseRepo();
      const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], DEFAULT);
      assert(r.laneGroup && Array.isArray(r.laneGroup.members) && r.laneGroup.members.includes('A') && r.laneGroup.members.includes('B'),
        '#500-NEGATIVE-A(a): consent + bare default → co-open [A,B] (default-on, no legacy toggle needed), got ' + JSON.stringify(r.laneGroup));
      const rs = readRS(cacheDir);
      // #498 regression guard (co-open ⟹ legs): the consenting overlap co-open is NEVER legless.
      assert(rs && rs.lane_group && rs.lane_group.legs && rs.lane_group.legs.A && rs.lane_group.legs.B,
        '#500-NEGATIVE-A(a): co-open ⟹ legs provisioned for the consenting overlap, got ' + JSON.stringify(rs && rs.lane_group));
      assert(Array.isArray(r.opened) && r.opened.length === 2, '#500-NEGATIVE-A(a): both writes co-opened, got ' + JSON.stringify(r.opened && r.opened.map(n => n.id)));
      assert(ledgerStatus(planPath, 'A') === 'in_progress' && ledgerStatus(planPath, 'B') === 'in_progress', '#500-NEGATIVE-A(a): both A and B in_progress');
      cleanup(repoRoot);
    }
    {
      // (b) Kill-switch bites even WITH consent: KAOLA_PARALLEL_WRITES=0 → serial-degrade to ONE write.
      const { repoRoot, cacheDir } = coarseRepo();
      const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], SERIAL);
      assert(!r.laneGroup, '#500-NEGATIVE-A(b): kill-switch + consent → NO laneGroup (serial degrade), got ' + JSON.stringify(r.laneGroup));
      const rs = readRS(cacheDir);
      assert(!rs || !rs.lane_group, '#500-NEGATIVE-A(b): running-set has no lane_group (kill-switch)');
      assert(Array.isArray(r.opened) && r.opened.length === 1, '#500-NEGATIVE-A(b): exactly ONE write opened (serial degrade), got ' + JSON.stringify(r.opened && r.opened.map(n => n.id)));
      cleanup(repoRoot);
    }

    // -----------------------------------------------------------------------
    // ★ #500-NEGATIVE-B (a genuine blocker STILL serial-degrades under #593 default-relax): the coarse
    //   default-relax (#593) is gated on the retained net — a coarse pair carrying a PROTECTED concrete
    //   file (NET-2) is NEVER relaxed, even by default, even with consent. So it must STILL serial-degrade
    //   to ONE write. (Pre-#593 this class serial-degraded for lack of consent; post-#593 it serial-
    //   degrades because NET-2 blocks — the "not everything relaxes" guard survives the default-relax.)
    // -----------------------------------------------------------------------
    {
      // Coarse pair (both under "crates") but one leg writes a PROTECTED lockfile → NET-2 blocks co-open.
      const { repoRoot, cacheDir } = makeLaneRepo({ aSet: 'crates/a/package-lock.json', bSet: 'crates/b/y.rs' });
      const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], DEFAULT);
      assert(!r.laneGroup, '#500-NEGATIVE-B: a PROTECTED file in a coarse pair (NET-2) blocks co-open ⇒ NO laneGroup, even with consent, got ' + JSON.stringify(r.laneGroup));
      const rs = readRS(cacheDir);
      assert(!rs || !rs.lane_group, '#500-NEGATIVE-B: running-set has no lane_group (NET-2 blocked)');
      assert(Array.isArray(r.opened) && r.opened.length === 1, '#500-NEGATIVE-B: exactly ONE write opened (serial degrade), got ' + JSON.stringify(r.opened && r.opened.map(n => n.id)));
      cleanup(repoRoot);
    }
  });

  // =========================================================================
  // #588 — write co-open WIDTH/MIX coverage (the width-2-only gap). Real-git cases at the LEG-*/SYNTH-*
  // quality bar: durable artifacts (ledger rows, running-set.json, worktree/branch existence, octopus
  // parent count, diff-tree vs union of declared sets) — never stdout sentinels. Reuses the D-437 harness
  // (makeLaneRepo now takes extraMembers) + runNode/readRS/ledgerStatus/worktreePaths/branchExists/gitOut.
  // =========================================================================

  // #655 adversarial mixed top-up crash: A is an already-stable member and B is
  // the newly appended opening member. Both ledger rows flipped and cap=2, so
  // reconcile must retain both without double-counting A against B's admission.
  scenario(() => {
    const { repoRoot, cacheDir } = makeLaneRepo({ waitBudgets: { A: 240, B: 300 } });
    const opened = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--max', '2', '--json'], LEG_ON);
    assert(opened.result === 'ok' && opened.opened.length === 2, '#655-MIXED-CRASH: initial real-git open admits two');
    const rs0 = readRS(cacheDir);
    rs0.state = 'opening';
    rs0.max_concurrent = 2;
    rs0.nodes = rs0.nodes.map(n => n.id === 'B' ? { ...n, opening: true } : (() => { const c = { ...n }; delete c.opening; return c; })());
    fs.writeFileSync(path.join(cacheDir, 'running-set.json'), JSON.stringify(rs0, null, 2));
    const rec = runNode(repoRoot, ['reconcile-running-set', '--project', 'test-project', '--json'], LEG_ON);
    const rs1 = readRS(cacheDir);
    assert(rec.result === 'ok' && rs1.nodes.map(n => n.id).sort().join(',') === 'A,B', '#655-MIXED-CRASH: stable+opening survivors both retained at cap2, got ' + JSON.stringify(rs1.nodes));
    const memberA = rs1.nodes.find(n => n.id === 'A');
    const memberB = rs1.nodes.find(n => n.id === 'B');
    assert(memberA && memberB && memberA.wait_budget_minutes === 240 && memberA.wait_budget_source === 'planner_override'
      && memberB.wait_budget_minutes === 300 && memberB.wait_budget_source === 'planner_override',
      '#655-MIXED-CRASH: exact values/source survive mixed reconcile');
    const again = runNode(repoRoot, ['reconcile-running-set', '--project', 'test-project', '--json'], LEG_ON);
    assert(again.result === 'ok' && again.reconciled === false && again.reason === 'not_opening', '#655-MIXED-CRASH: repeated reconcile is idempotent');
    const orient = runNode(repoRoot, ['orient', '--project', 'test-project', '--json'], LEG_ON);
    assert(orient.result === 'ok' && orient.reason !== 'orphan_multi_in_progress', '#655-MIXED-CRASH: orient recovers without orphan wedge, got ' + JSON.stringify(orient));
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #588-3LEG-OCTOPUS-END-TO-END (case a): a 3-leg DISJOINT write co-open → provision 3 legs → per-leg
  //   barriers (A,B deferred; C last) → octopus merge (feature + 3 legs = EXACTLY 4 parents) → commit-union
  //   barrier → group close. Extends SYNTH-DISJOINT (width 2) to width 3. Behavior PINNED as correct.
  // -------------------------------------------------------------------------
  scenario(() => {
    const setOf = { A: 'ax.js', B: 'by.js', C: 'cz.js' };
    const { repoRoot, cacheDir, planPath } = makeLaneRepo({ extraMembers: [{ id: 'C', set: 'cz.js' }] });
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], LEG_ON);
    assert(r.result === 'ok', '#588-3LEG: open-ready ok, got ' + JSON.stringify(r));
    assert(r.laneGroup && r.laneGroup.members.slice().sort().join(',') === 'A,B,C', '#588-3LEG: 3-member lane group [A,B,C], got ' + JSON.stringify(r.laneGroup && r.laneGroup.members));
    assert(Array.isArray(r.opened) && r.opened.length === 3, '#588-3LEG: all 3 writes co-opened, got ' + JSON.stringify(r.opened && r.opened.map(n => n.id)));
    const rs = readRS(cacheDir);
    for (const id of ['A', 'B', 'C']) {
      assert(rs.lane_group.legs[id], '#588-3LEG: leg manifest for ' + id);
      assert(worktreePaths(repoRoot).some(p => p.endsWith(path.join('.kw', 'legs', 'test-project', id))), '#588-3LEG: leg worktree provisioned for ' + id);
      assert(branchExists(repoRoot, 'kw/legs/test-project/' + id), '#588-3LEG: leg branch for ' + id);
      assert(ledgerStatus(planPath, id) === 'in_progress', '#588-3LEG: ' + id + ' in_progress');
      const on = r.opened.find(n => n.id === id);
      assert(on.dispatch.leg_path === rs.lane_group.legs[id].legPath && on.dispatch.leg_branch === 'kw/legs/test-project/' + id, '#588-3LEG: ' + id + ' dispatch carries its own leg routing (#591 at width 3)');
    }
    const base = rs.lane_group.legs.A.baseline;
    for (const id of ['A', 'B', 'C']) {
      writeEvidence(cacheDir, id);
      fs.writeFileSync(path.join(repoRoot, '.kw', 'legs', 'test-project', id, setOf[id]), '// ' + id + ' leg work\n');
    }
    const rA = runNode(repoRoot, ['close-node', '--node-id', 'A', '--project', 'test-project', '--json'], LEG_ON);
    assert(rA.result === 'ok' && rA.barrier === 'deferred_to_group', '#588-3LEG: A deferred, got ' + JSON.stringify(rA));
    const rB = runNode(repoRoot, ['close-node', '--node-id', 'B', '--project', 'test-project', '--json'], LEG_ON);
    assert(rB.result === 'ok' && rB.barrier === 'deferred_to_group', '#588-3LEG: B deferred, got ' + JSON.stringify(rB));
    const rC = runNode(repoRoot, ['close-node', '--node-id', 'C', '--project', 'test-project', '--json'], LEG_ON);
    assert(rC.result === 'ok' && rC.barrier === 'group_passed' && rC.synthesized === true, '#588-3LEG: C (last) group_passed + synthesized, got ' + JSON.stringify(rC));
    const M = rC.mergeCommit;
    assert(gitOut(repoRoot, ['rev-parse', 'HEAD']) === M, '#588-3LEG: HEAD advanced to M');
    const parents = gitOut(repoRoot, ['rev-list', '--parents', '-n', '1', M]).split(/\s+/).slice(1);
    assert(parents.length === 4, '#588-3LEG: octopus merge has EXACTLY 4 parents (feature + 3 legs), got ' + parents.length);
    const mDiff = gitOut(repoRoot, ['diff-tree', '-r', '--name-only', base, M]).split('\n')
      .map(s => s.trim()).filter(s => s && !isProjectWorkflowChurn(s, 'test-project')).sort();
    assert(JSON.stringify(mDiff) === JSON.stringify(['ax.js', 'by.js', 'cz.js']), '#588-3LEG: diff base→M == union(declared) {ax,by,cz}, got ' + JSON.stringify(mDiff));
    for (const id of ['A', 'B', 'C']) assert(gitOut(repoRoot, ['rev-parse', M + ':' + setOf[id]]) !== '', '#588-3LEG: M contains ' + setOf[id]);
    assert(ledgerStatus(planPath, 'A') === 'complete' && ledgerStatus(planPath, 'B') === 'complete' && ledgerStatus(planPath, 'C') === 'complete', '#588-3LEG: all 3 members complete');
    assert(worktreePaths(repoRoot).filter(p => p.indexOf(path.join('.kw', 'legs')) !== -1).length === 0, '#588-3LEG: all legs torn down after the merge');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #588-WIDE-CAP (case b, part 1): a 5-wide DISJOINT write antichain vs the default write FANOUT_CAP (4).
  //   Documented cap behavior PINNED: co-open EXACTLY 4, queue the 5th (still pending, no leg); running-set
  //   max_concurrent == the write cap (4). Then reconcile of a crashed-open honors that ceiling at width 4
  //   (rolls all 4 forward — ceiling==width admits the full set — and preserves max_concurrent==4).
  // -------------------------------------------------------------------------
  scenario(() => {
    const waitBudgets = { A: 180, B: 181, C: 182, D: 183, E: 184 };
    const { repoRoot, cacheDir, planPath } = makeLaneRepo({ extraMembers: [{ id: 'C', set: 'cz.js' }, { id: 'D', set: 'dz.js' }, { id: 'E', set: 'ez.js' }], waitBudgets });
    const allIds = ['A', 'B', 'C', 'D', 'E'];
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], LEG_ON);
    assert(r.result === 'ok', '#588-WIDE-CAP: open-ready ok, got ' + JSON.stringify(r));
    assert(Array.isArray(r.opened) && r.opened.length === 4, '#588-WIDE-CAP: FANOUT_CAP=4 co-opens EXACTLY 4 of 5, got ' + JSON.stringify(r.opened && r.opened.map(n => n.id)));
    const openedIds = r.opened.map(n => n.id);
    const pendingId = allIds.find(id => !openedIds.includes(id));
    assert(pendingId && ledgerStatus(planPath, pendingId) === 'pending', '#588-WIDE-CAP: the 5th (' + pendingId + ') stays pending (queued past the cap)');
    for (const id of openedIds) assert(ledgerStatus(planPath, id) === 'in_progress', '#588-WIDE-CAP: opened ' + id + ' in_progress');
    const rs = readRS(cacheDir);
    for (const id of openedIds) {
      const card = r.opened.find(n => n.id === id).dispatch;
      const member = rs.nodes.find(n => n.id === id);
      assert(card.wait_budget_minutes === waitBudgets[id] && card.wait_budget_source === 'planner_override', '#655-R1: write-leg dispatch ' + id + ' keeps authored override/source');
      assert(member.wait_budget_minutes === waitBudgets[id] && member.wait_budget_source === 'planner_override', '#655-R1: write-leg durable member ' + id + ' keeps authored override/source');
    }
    assert(rs.max_concurrent === 4, '#588-WIDE-CAP: running-set max_concurrent == write cap (4), got ' + rs.max_concurrent);
    assert(rs.lane_group && Object.keys(rs.lane_group.legs).sort().join(',') === openedIds.slice().sort().join(','), '#588-WIDE-CAP: legs manifest covers EXACTLY the 4 opened, got ' + JSON.stringify(Object.keys(rs.lane_group.legs)));
    assert(!rs.lane_group.legs[pendingId], '#588-WIDE-CAP: no leg manifest entry for the queued 5th');
    assert(!worktreePaths(repoRoot).some(p => p.endsWith(path.join('.kw', 'legs', 'test-project', pendingId))), '#588-WIDE-CAP: no leg worktree for the queued 5th');
    // Reconcile ceiling at width 4: craft a crashed-open (state:opening, all 4 opening:true).
    const rs0 = readRS(cacheDir);
    rs0.state = 'opening';
    rs0.nodes = rs0.nodes.map(n => ({ ...n, opening: true }));
    fs.writeFileSync(path.join(cacheDir, 'running-set.json'), JSON.stringify(rs0, null, 2));
    const rec = runNode(repoRoot, ['reconcile-running-set', '--project', 'test-project', '--json'], LEG_ON);
    assert(rec.result === 'ok' && rec.reconciled === true, '#588-WIDE-CAP: reconcile ok, got ' + JSON.stringify(rec));
    const rs1 = readRS(cacheDir);
    assert(rs1.state === 'open', '#588-WIDE-CAP: reconcile promotes to open');
    assert(rs1.max_concurrent === 4, '#588-WIDE-CAP: max_concurrent==4 survives reconcile at width 4, got ' + rs1.max_concurrent);
    assert(rs1.nodes.length === 4, '#588-WIDE-CAP: reconcile rolls ALL 4 forward (ceiling==width==4), got ' + rs1.nodes.length);
    assert(rs1.nodes.every(n => n.wait_budget_minutes === waitBudgets[n.id] && n.wait_budget_source === 'planner_override'), '#655-R1: write-leg crash reconcile retains exact authored values/source');
    assert(rs1.lane_group && Object.keys(rs1.lane_group.legs).length === 4, '#588-WIDE-CAP: all 4 legs retained through reconcile, got ' + JSON.stringify(rs1.lane_group && Object.keys(rs1.lane_group.legs)));
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #588-WIDE-DRAIN (case b, part 2): after the width-4 group closes (octopus, feature + 4 legs = 5 parents),
  //   a subsequent open-ready DRAINS the queued 5th — a single remaining write opens serially (no group, no
  //   leg). Pins the top-up-drain half of the documented cap behavior.
  // -------------------------------------------------------------------------
  scenario(() => {
    const setOf = { A: 'ax.js', B: 'by.js', C: 'cz.js', D: 'dz.js', E: 'ez.js' };
    const allIds = ['A', 'B', 'C', 'D', 'E'];
    const waitBudgets = { A: 180, B: 181, C: 182, D: 183, E: 184 };
    const { repoRoot, cacheDir, planPath } = makeLaneRepo({ extraMembers: [{ id: 'C', set: 'cz.js' }, { id: 'D', set: 'dz.js' }, { id: 'E', set: 'ez.js' }], waitBudgets });
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], LEG_ON);
    assert(r.result === 'ok' && r.opened.length === 4, '#588-WIDE-DRAIN: co-open 4, got ' + JSON.stringify(r.opened && r.opened.map(n => n.id)));
    const openedIds = r.opened.map(n => n.id);
    const pendingId = allIds.find(id => !openedIds.includes(id));
    const rs = readRS(cacheDir);
    const base = rs.lane_group.legs[openedIds[0]].baseline;
    for (const id of openedIds) {
      writeEvidence(cacheDir, id);
      fs.writeFileSync(path.join(repoRoot, '.kw', 'legs', 'test-project', id, setOf[id]), '// ' + id + ' leg work\n');
    }
    let last;
    for (let i = 0; i < openedIds.length; i++) {
      last = runNode(repoRoot, ['close-node', '--node-id', openedIds[i], '--project', 'test-project', '--json'], LEG_ON);
      if (i < openedIds.length - 1) assert(last.result === 'ok' && last.barrier === 'deferred_to_group', '#588-WIDE-DRAIN: ' + openedIds[i] + ' deferred, got ' + JSON.stringify(last));
    }
    assert(last.result === 'ok' && last.barrier === 'group_passed' && last.synthesized === true, '#588-WIDE-DRAIN: last member synthesizes, got ' + JSON.stringify(last));
    const M = last.mergeCommit;
    const parents = gitOut(repoRoot, ['rev-list', '--parents', '-n', '1', M]).split(/\s+/).slice(1);
    assert(parents.length === 5, '#588-WIDE-DRAIN: octopus has EXACTLY 5 parents (feature + 4 legs), got ' + parents.length);
    const mDiff = gitOut(repoRoot, ['diff-tree', '-r', '--name-only', base, M]).split('\n')
      .map(s => s.trim()).filter(s => s && !isProjectWorkflowChurn(s, 'test-project')).sort();
    assert(JSON.stringify(mDiff) === JSON.stringify(openedIds.map(id => setOf[id]).sort()), '#588-WIDE-DRAIN: diff base→M == union of the 4 opened declared sets, got ' + JSON.stringify(mDiff));
    for (const id of openedIds) assert(ledgerStatus(planPath, id) === 'complete', '#588-WIDE-DRAIN: ' + id + ' complete');
    assert(worktreePaths(repoRoot).filter(p => p.indexOf(path.join('.kw', 'legs')) !== -1).length === 0, '#588-WIDE-DRAIN: legs torn down after the width-4 merge');
    const r2 = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], LEG_ON);
    assert(r2.result === 'ok', '#588-WIDE-DRAIN: drain open-ready ok, got ' + JSON.stringify(r2));
    assert(Array.isArray(r2.opened) && r2.opened.length === 1 && r2.opened[0].id === pendingId, '#588-WIDE-DRAIN: the queued 5th (' + pendingId + ') drains, got ' + JSON.stringify(r2.opened && r2.opened.map(n => n.id)));
    assert(r2.opened[0].dispatch.wait_budget_minutes === waitBudgets[pendingId] && r2.opened[0].dispatch.wait_budget_source === 'planner_override', '#655-R1: queued write top-up/drain keeps authored override/source');
    assert(!r2.laneGroup, '#588-WIDE-DRAIN: single remaining write opens serially (no lane group)');
    const rs2 = readRS(cacheDir);
    assert(!rs2.lane_group, '#588-WIDE-DRAIN: running-set has no lane_group for the serial drain');
    assert(ledgerStatus(planPath, pendingId) === 'in_progress', '#588-WIDE-DRAIN: the drained 5th is in_progress');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #588-MIXED-FRONTIER (case c): a ready frontier with BOTH read members (v1,v2) AND a disjoint write pair
  //   (A,B). TICK 1 opens ONLY the reads (the G1 read-first partition — reads-first is DELIBERATE, and
  //   UNCHANGED by #641). TICK 2 — a write-only frontier {A,B} behind the live reads — is the exact case
  //   #641 R1 relaxes: instead of write_awaits_drain, the disjoint LEG-CAPABLE writers CO-OPEN as a
  //   leg-contained lane group behind the live reads (the mirror of #622's read-direction relaxation). The
  //   #588 LEGLESS pin still holds under KAOLA_PARALLEL_WRITES=0 (covered by #641-R1-A).
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir, planPath } = makeLaneRepo({ extraMembers: [{ id: 'v1', role: 'code-explorer', set: '—' }, { id: 'v2', role: 'knowledge-lookup', set: '—' }] });
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], LEG_ON);
    assert(r.result === 'ok', '#588-MIXED: open-ready ok, got ' + JSON.stringify(r));
    const openedIds = (r.opened || []).map(n => n.id).sort();
    assert(openedIds.join(',') === 'v1,v2', '#588-MIXED: tick1 opens ONLY the read members [v1,v2] (G1 read-first), got ' + JSON.stringify(openedIds));
    assert(!r.laneGroup, '#588-MIXED: no lane group while opening reads');
    assert(ledgerStatus(planPath, 'v1') === 'in_progress' && ledgerStatus(planPath, 'v2') === 'in_progress', '#588-MIXED: both reads in_progress');
    assert(ledgerStatus(planPath, 'A') === 'pending' && ledgerStatus(planPath, 'B') === 'pending', '#588-MIXED: writes A,B DEFERRED at tick1 (still pending)');
    const rs = readRS(cacheDir);
    assert(rs.nodes.map(n => n.id).sort().join(',') === 'v1,v2', '#588-MIXED: running-set reflects EXACTLY the opened read set, got ' + JSON.stringify(rs.nodes.map(n => n.id)));
    assert(!rs.lane_group, '#588-MIXED: running-set has no lane_group (reads only)');
    assert(!worktreePaths(repoRoot).some(p => p.indexOf(path.join('.kw', 'legs')) !== -1), '#588-MIXED: no legs provisioned for a read frontier');
    // TICK 2 (post-#641 R1): the disjoint leg-capable writers CO-OPEN behind the live reads (mixed running
    // set), instead of holding on write_awaits_drain.
    const r2 = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], LEG_ON);
    assert(r2.result === 'ok' && Array.isArray(r2.opened) && r2.opened.map(n => n.id).sort().join(',') === 'A,B' && r2.laneGroup,
      '#588-MIXED (post-#641 R1): the disjoint writers CO-OPEN as a leg group behind the live reads, got ' + JSON.stringify({ opened: r2.opened && r2.opened.map(n => n.id), reason: r2.reason, laneGroup: r2.laneGroup }));
    const rs2 = readRS(cacheDir);
    assert(rs2.lane_group && rs2.lane_group.legs && rs2.lane_group.legs.A && rs2.lane_group.legs.B, '#588-MIXED (post-#641 R1): legs provisioned for the co-opened writers');
    assert(rs2.nodes.some(n => n.id === 'v1' && n.kind === 'read') && rs2.nodes.some(n => n.id === 'A' && n.kind === 'write'),
      '#588-MIXED (post-#641 R1): MIXED running set — the live reads alongside the leg-writes, got ' + JSON.stringify(rs2.nodes.map(n => ({ id: n.id, kind: n.kind }))));
    cleanup(repoRoot);
  });
  // #588-MIXED-LEGLESS-PIN (post-#641 R1): the #588 pin is PRESERVED for LEGLESS writers — under
  //   KAOLA_PARALLEL_WRITES=0 the write frontier {A,B} behind the live reads STILL holds (write_awaits_drain),
  //   labeled serialDegradeReason:parallel_writes_off. (A legless writer mutating the shared parent tree
  //   would be observed mid-write by a live read — G3 stays; the operator serial kill-switch is byte-identical.)
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir, planPath } = makeLaneRepo({ extraMembers: [{ id: 'v1', role: 'code-explorer', set: '—' }, { id: 'v2', role: 'knowledge-lookup', set: '—' }] });
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], SERIAL);
    assert(r.result === 'ok' && (r.opened || []).map(n => n.id).sort().join(',') === 'v1,v2', '#588-MIXED-LEGLESS-PIN: tick1 opens the reads');
    const r2 = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], SERIAL);
    assert(r2.result === 'ok' && Array.isArray(r2.opened) && r2.opened.length === 0 && r2.reason === 'write_awaits_drain',
      '#588-MIXED-LEGLESS-PIN: a LEGLESS write frontier still holds behind live reads (write_awaits_drain), got ' + JSON.stringify({ opened: r2.opened, reason: r2.reason }));
    assert(r2.serialDegradeReason === 'parallel_writes_off', '#588-MIXED-LEGLESS-PIN: the legless hold is labeled parallel_writes_off, got ' + JSON.stringify(r2.serialDegradeReason));
    assert(ledgerStatus(planPath, 'A') === 'pending' && ledgerStatus(planPath, 'B') === 'pending', '#588-MIXED-LEGLESS-PIN: ZERO mutation — A,B stay pending');
    assert(!readRS(cacheDir).lane_group, '#588-MIXED-LEGLESS-PIN: no lane_group under the legless hold');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #588-TASKMIRROR-FAILOPEN (case d): the durable task-mirror refresh is FAIL-OPEN on the running-set
  //   scheduler path — a mirror write failure must NEVER roll back a correct ledger transition (the #317
  //   fail-open contract, tested for the batch path, now pinned for open-ready + close-node). Force the
  //   mirror write to fail (workflow-tasks.json is a DIRECTORY ⇒ EISDIR ⇒ non-zero task-mirror exit) and
  //   assert the ledger STILL advances with taskMirror.status === 'failed'. Behavior PINNED as correct.
  // -------------------------------------------------------------------------
  scenario(() => {
    // OPEN path: co-open with the mirror-write forced to fail.
    const { repoRoot, cacheDir, projDir, planPath } = makeLaneRepo();
    fs.mkdirSync(path.join(projDir, 'workflow-tasks.json'), { recursive: true });
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--write-overlap-consent', '--json'], LEG_ON);
    assert(r.result === 'ok', '#588-TASKMIRROR-OPEN: open-ready still ok despite mirror failure, got ' + JSON.stringify(r));
    assert(r.taskMirror && r.taskMirror.status === 'failed', '#588-TASKMIRROR-OPEN: taskMirror reports failed (fail-open), got ' + JSON.stringify(r.taskMirror));
    assert(ledgerStatus(planPath, 'A') === 'in_progress' && ledgerStatus(planPath, 'B') === 'in_progress', '#588-TASKMIRROR-OPEN: ledger STILL advanced despite mirror failure');
    const rs = readRS(cacheDir);
    assert(rs && rs.lane_group && rs.lane_group.legs.A && rs.lane_group.legs.B, '#588-TASKMIRROR-OPEN: running-set + legs written despite mirror failure');
    cleanup(repoRoot);
  });
  scenario(() => {
    // CLOSE path: serial open (writes the mirror as a file), then force the mirror to fail at close-node.
    const { repoRoot, cacheDir, projDir, planPath } = makeLaneRepo();
    const open = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], SERIAL);
    assert(open.result === 'ok' && open.opened.length === 1, '#588-TASKMIRROR-CLOSE: serial open ok, got ' + JSON.stringify(open));
    const openedId = open.opened[0].id;
    writeEvidence(cacheDir, openedId);
    fs.writeFileSync(path.join(repoRoot, openedId === 'A' ? 'ax.js' : 'by.js'), '// serial in-lane\n');
    const tasksPath = path.join(projDir, 'workflow-tasks.json');
    try { fs.rmSync(tasksPath, { force: true }); } catch (_) {}
    fs.mkdirSync(tasksPath, { recursive: true });
    const r = runNode(repoRoot, ['close-node', '--node-id', openedId, '--project', 'test-project', '--json'], SERIAL);
    assert(r.result === 'ok', '#588-TASKMIRROR-CLOSE: close-node still ok despite mirror failure, got ' + JSON.stringify(r));
    assert(r.taskMirror && r.taskMirror.status === 'failed', '#588-TASKMIRROR-CLOSE: taskMirror reports failed (fail-open), got ' + JSON.stringify(r.taskMirror));
    assert(ledgerStatus(planPath, openedId) === 'complete', '#588-TASKMIRROR-CLOSE: ledger advanced to complete despite mirror failure');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #671-MIRROR-CRASH-OBSERVABILITY: the durable task-mirror CLI must fail-CLOSED at the SUBPROCESS
  //   boundary with a concise ONE-LINE machine-readable refusal — never an uncaught-exception stack
  //   trace. The #588 fixtures above already force workflow-tasks.json to collide with a DIRECTORY
  //   (EISDIR on fs.writeFileSync) and pin the CALLER's fail-OPEN (ledger still advances); THIS test
  //   pins the CHILD's OWN crash surface directly (single-hop CLI invocation, no adaptive-node relay):
  //   no raw stack-trace noise, a typed `mirror_write_failed` envelope on stdout. RED (pre-fix): the
  //   CLI has no try/catch around writeFileSync, so Node's uncaught-exception handler dumps a
  //   multi-line stack trace to stderr and stdout is EMPTY (no envelope) — every assertion below
  //   fails against the current code.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { spawnSync } = require('child_process');
    const taskMirrorPath = path.join(__dirname, 'kaola-workflow-task-mirror.js');
    const { repoRoot, projDir } = makeLaneRepo();
    fs.mkdirSync(path.join(projDir, 'workflow-tasks.json'), { recursive: true });
    // The whole assertion is the envelope: a non-zero exit, stdout carrying EXACTLY one line, that
    // line being a {result:refuse, reason:mirror_write_failed} object, and stderr carrying no raw
    // stack frames. Streams and exit codes exist only at the process boundary.
    // spawn-class: cli-contract
    const res = spawnSync(process.execPath, [taskMirrorPath, '--project', 'test-project', '--json'], { cwd: repoRoot, encoding: 'utf8' });
    const combined = (res.stdout || '') + (res.stderr || '');
    assert(res.status !== 0, '#671-MIRROR-CRASH-OBSERVABILITY: EISDIR collision still exits non-zero, got ' + JSON.stringify(res.status));
    assert(!/at Object\.<anonymous>/.test(combined) && !/at Module\./.test(combined),
      '#671-MIRROR-CRASH-OBSERVABILITY: NO raw stack-trace frames (at Object.<anonymous> / at Module.) in output, got ' + JSON.stringify(combined));
    assert(!/Error: EISDIR[^\n]*\n\s+at /.test(combined),
      '#671-MIRROR-CRASH-OBSERVABILITY: NO bare "Error: EISDIR" immediately followed by a stack frame, got ' + JSON.stringify(combined));
    const stdoutLines = (res.stdout || '').trim().split('\n').filter(Boolean);
    assert(stdoutLines.length === 1, '#671-MIRROR-CRASH-OBSERVABILITY: stdout carries exactly ONE line (the machine envelope), got ' + JSON.stringify(res.stdout));
    let envelope = null;
    try { envelope = JSON.parse(stdoutLines[0] || ''); } catch (_) {}
    assert(envelope && envelope.result === 'refuse' && envelope.reason === 'mirror_write_failed',
      '#671-MIRROR-CRASH-OBSERVABILITY: stdout is a concise machine-readable {result:refuse, reason:mirror_write_failed} envelope, got ' + JSON.stringify({ stdout: res.stdout, envelope }));
    assert(envelope && typeof envelope.message === 'string' && envelope.message.indexOf('\n') === -1,
      '#671-MIRROR-CRASH-OBSERVABILITY: envelope message is a single line (no embedded stack dump), got ' + JSON.stringify(envelope && envelope.message));
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #615-MIXED-SERIAL-LANE-DEGRADE (D-615-01) — the mixed serial-write + lane-group deadlock, dissolved
  //   at the SCHEDULING boundary. A plan whose DAG is two SERIAL write nodes (sA→sB) followed by a
  //   disjoint PARALLEL write frontier (pA,pB) is the canonical trap: the serial siblings run first and,
  //   per the finalize-owned-commit contract, never commit — their production writes sit UNCOMMITTED in
  //   the parent tree. If a lane group co-opens over that dirt, its last-member close is unsatisfiable
  //   (Horn A: --parent-clean-check refuses parent_dirty on the uncommitted serial file; Horn B:
  //   committing it to clear the fence lands it in the merge commit → write_set_overflow at the
  //   commit-based group barrier). The #615 fix gates group formation on parent cleanliness (reusing the
  //   EXACT --parent-clean-check the last-member close applies) and DEGRADES to a single serial write
  //   when the parent carries out-of-allowband production dirt.
  //   RED (pre-fix): with sA's production file uncommitted, open-ready over {pA,pB} STILL forms a lane
  //     group (opened.length===2, a laneGroup descriptor, legs provisioned) — the unsatisfiable state.
  //   GREEN (post-fix): open-ready DEGRADES — opened.length===1, opened[0].kind==='write', NO laneGroup
  //     descriptor, NO lane_group key in running-set.json. The serial per-node barrier tolerates prior
  //     dirt (its base is a full-worktree snapshot at open), so the run completes correctly, serially.
  //   Falsification: a pure-parallel/group-first plan has NO prior production dirt → the fence passes →
  //     the group STILL forms (D437-OPEN-READY-DEFAULT-COOPEN above proves that path is unbroken). The
  //     degrade bites ONLY the genuinely-mixed dirty-parent shape.
  // -------------------------------------------------------------------------
  // Build a mixed serial-write→parallel-write repo (mirrors makeLaneRepo's git-init + freeze pattern,
  // but with the serial prefix makeLaneRepo's fixed DAG cannot express). sA,sB are complete; pA,pB are
  // the ready parallel frontier; review (code-reviewer) post-dominates every write; finalize is the sink.
  // opts.extraDirty: additional {path, body} written UNCOMMITTED into the parent (the unattributable-dirt
  // probe). opts.preCommitSeam: commit the serial dirt UP FRONT under the checkpoint's own message (the
  // crash-between-commit-and-open resume shape).
  // #802 (D7 repair) — the FOUR independent hostility knobs. Each models one class of consumer-owned
  // git configuration that a scheduler commit can meet mid-schedule. They are separate because the
  // correct response differs by class: a CONTENT-INSPECTING hook must be honored (and its veto degraded
  // around), whereas an ATTRIBUTION config (identity, signing) must simply not be able to stop a run.
  // opts.hostilePreCommit: a repo-local `pre-commit` hook that vetoes EVERY commit (a consumer lint /
  //   policy gate). Content-inspecting ⇒ never bypassed; the seam DEGRADES to serial instead.
  // opts.secretScanner: a repo-local `pre-commit` hook that greps the STAGED diff for an AWS access-key
  //   shape and vetoes on a hit. The security probe: the checkpoint's bytes must still reach it.
  // opts.hostilePrepareCommitMsg: a `prepare-commit-msg` hook exiting 1 — the hook class `--no-verify`
  //   never covered in the first place. Also degrades.
  // opts.keylessSigning: `commit.gpgsign true` with an unusable `user.signingkey`. Attribution-only ⇒
  //   overridden by `-c commit.gpgsign=false`, so the checkpoint still lands.
  // opts.noIdentity: the repo configures NO `user.email`/`user.name` (the fixture's own setup commits
  //   pass an inline identity instead). Attribution-only ⇒ the scheduler injects its own identity.
  //   Drive with NO_AMBIENT_GIT_IDENTITY so a host-global identity cannot mask the probe.
  // opts.postCommitWriter: a `post-commit` hook that drops a foreign file into the worktree — a
  //   deterministic stand-in for a CONCURRENT writer landing bytes between the checkpoint's two fence
  //   spawns (git ignores a post-commit hook's exit status, so the commit still lands and only the
  //   RE-fence fails). This is the only reachable way to drive the post-commit-fence halt end-to-end.
  function makeMixedRepo(opts) {
      opts = opts || {};
      const repoRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'd615-mixed-'));
      const project = 'test-project';
      const projDir = path.join(repoRoot, 'kaola-workflow', project);
      const cacheDir = path.join(projDir, '.cache');
      fs.mkdirSync(cacheDir, { recursive: true });
      const planPath = path.join(projDir, 'workflow-plan.md');
      const plan = [
        '# Workflow Plan — test-project', '',
        '## Meta', 'labels: area:scripts', 'sink: CHANGELOG.md', '',
        '## Nodes', '',
        '| id | role | depends_on | declared_write_set | cardinality | shape |',
        '| --- | --- | --- | --- | --- | --- |',
        '| sA       | tdd-guide     | —       | src/serial_a.js | 1 | sequence |',
        '| sB       | tdd-guide     | sA      | src/serial_b.js | 1 | sequence |',
        '| pA       | tdd-guide     | sB      | par_a.js        | 1 | sequence |',
        '| pB       | tdd-guide     | sB      | par_b.js        | 1 | sequence |',
        '| review   | code-reviewer | pA,pB   | —               | 1 | sequence |',
        '| finalize | finalize      | review  | —               | 1 | sequence |', '',
        '## Node Ledger', '',
        '| id | status |', '| --- | --- |',
        '| sA | complete |',
        '| sB | complete |',
        '| pA | pending |',
        '| pB | pending |',
        '| review | pending |',
        '| finalize | pending |', '',
      ].join('\n') + '\n';
      fs.writeFileSync(planPath, plan);
      fs.writeFileSync(path.join(projDir, 'workflow-state.md'), '# State\n');
      // The fixture's OWN setup commits always carry an inline identity + signing-off, so `noIdentity`
      // (which leaves the repo with no configured identity at all) does not break repo construction.
      const FIXTURE_ID = ['-c', 'user.email=kw@test', '-c', 'user.name=kw', '-c', 'commit.gpgsign=false'];
      const g = (args) => execFileSync('git',
        ['-C', repoRoot, ...(args[0] === 'commit' ? FIXTURE_ID : []), ...args],
        { encoding: 'utf8', stdio: ['ignore', 'ignore', 'ignore'] });
      g(['init']);
      if (opts.noIdentity) {
        // `user.useConfigOnly` is git's own switch for "never guess an identity from the environment".
        // Without it git happily synthesizes `user@host` on many boxes, so a bare missing-identity repo
        // would not actually refuse anything and the probe would be vacuous. With it, the repo refuses
        // every commit that does not carry a CONFIGURED identity — which is exactly the state N2 is
        // about, and which the scheduler's own `-c user.email/-c user.name` satisfies.
        g(['config', 'user.useConfigOnly', 'true']);
      } else {
        g(['config', 'user.email', 'kw@test']);
        g(['config', 'user.name', 'kw']);
      }
      g(['config', 'commit.gpgsign', 'false']);
      const froze = freezeLegacyFixture(execFileSync, 'node', VALIDATOR, planPath, { cwd: repoRoot, encoding: 'utf8' });
      // The disjoint mixed plan MUST freeze cleanly (open-ready's integrity --resume-check needs it).
      assert(JSON.parse(froze.trim().split('\n').pop()).result !== 'refuse', '#615-MIXED: fixture must freeze, got ' + froze);
      fs.writeFileSync(path.join(repoRoot, '.gitignore'), '.kw/\n');
      g(['add', '-A']);
      g(['commit', '-m', 'init']);
      // The serial-accumulation state: sA ran and produced its declared file, but serial nodes never
      // commit (finalize-owned-commit contract). Leave it UNCOMMITTED in the parent worktree.
      fs.mkdirSync(path.join(repoRoot, 'src'), { recursive: true });
      fs.writeFileSync(path.join(repoRoot, 'src', 'serial_a.js'),
        '// uncommitted serial production from sA\n'
        // The secret probe plants its payload in the ATTRIBUTED serial path — i.e. in exactly the bytes
        // the seam checkpoint commits. Assembled from fragments so this source file itself never
        // contains a scannable key literal.
        + (opts.secretScanner ? 'const k = "' + 'AKIA' + 'IOSFODNN7EXAMPLE' + '";\n' : ''));
      for (const extra of (opts.extraDirty || [])) {
        fs.mkdirSync(path.dirname(path.join(repoRoot, extra.path)), { recursive: true });
        fs.writeFileSync(path.join(repoRoot, extra.path), extra.body);
      }
      if (opts.preCommitSeam) {
        g(['add', '--', 'src/serial_a.js']);
        g(['commit', '-m', 'kaola-checkpoint(test-project): serial→parallel seam — nodes sA, sB', '--', 'src/serial_a.js']);
      }
      // Hooks are installed LAST so the fixture's own init/pre-seam commits above are unaffected.
      const hooksDir = path.join(repoRoot, '.git', 'hooks');
      const installHook = (name, body) => {
        fs.mkdirSync(hooksDir, { recursive: true });
        const hook = path.join(hooksDir, name);
        fs.writeFileSync(hook, body);
        fs.chmodSync(hook, 0o755);
      };
      if (opts.hostilePreCommit) {
        installHook('pre-commit', '#!/bin/sh\necho "hostile repo-local pre-commit hook" >&2\nexit 1\n');
      }
      if (opts.secretScanner) {
        // A minimal stand-in for a consumer's staged-content secret scanner. It reads the STAGED diff —
        // the only way it can see what a commit is about to record — and leaves a WITNESS naming the
        // paths it inspected, so a test can prove the scanner actually SAW the checkpoint's bytes
        // rather than merely inferring it from a failed commit.
        installHook('pre-commit', [
          '#!/bin/sh',
          'git diff --cached --name-only >> "$(git rev-parse --git-dir)/scanner-witness"',
          'if git diff --cached -U0 | grep -Eq "AKIA[0-9A-Z]{16}"; then',
          '  echo "secret-scanner: AWS access key id in staged content" >&2',
          '  exit 1',
          'fi',
          'exit 0', '',
        ].join('\n'));
      }
      if (opts.hostilePrepareCommitMsg) {
        // The hook class `--no-verify` NEVER covered: git skips only `pre-commit` and `commit-msg`
        // under that flag, so a `prepare-commit-msg` veto halted the seam even with the bypass in place.
        installHook('prepare-commit-msg', '#!/bin/sh\necho "hostile prepare-commit-msg hook" >&2\nexit 1\n');
      }
      if (opts.keylessSigning) {
        g(['config', 'commit.gpgsign', 'true']);
        g(['config', 'user.signingkey', 'NOSUCHKEYEXISTS']);
      }
      if (opts.postCommitWriter) {
        fs.mkdirSync(hooksDir, { recursive: true });
        const hook = path.join(hooksDir, 'post-commit');
        fs.writeFileSync(hook, '#!/bin/sh\nprintf "// bytes from a concurrent writer\\n" > concurrent.js\n');
        fs.chmodSync(hook, 0o755);
      }
      return { repoRoot, project, planPath, projDir, cacheDir, g };
  }
  function headSha(repoRoot) {
    return G.exec(repoRoot, ['rev-parse', 'HEAD'], { encoding: 'utf8' }).trim();
  }
  // Commit subjects on HEAD's first-parent history, newest first.
  function gitSubjects(repoRoot) {
    try {
      return G.exec(repoRoot, ['log', '--format=%s'], { encoding: 'utf8' })
        .split('\n').map(s => s.trim()).filter(Boolean);
    } catch (_) { return []; }
  }
  function seamCommitCount(repoRoot) {
    return gitSubjects(repoRoot).filter(s => s.startsWith('kaola-checkpoint(')).length;
  }

  // -------------------------------------------------------------------------
  // #802-SEAM-CHECKPOINT-COOPEN (D1/D2 normal co-open site) — the SAME mixed shape, now REPAIRED
  //   instead of degraded. Attributed serial dirt is a REMOVABLE BLOCKER the orchestrator itself
  //   created — none of the three named serializers — so open-ready commits it at the seam and the
  //   frontier co-opens. The commit lands BEFORE the group baseline, so the serial work sits outside
  //   the group diff (Horn B dissolves) and the legs branch off it (input freshness dissolves).
  //   RED (pre-#802): open-ready serial-degrades — opened.length===1, no laneGroup,
  //     serialDegradeReason:'parent_dirty', and NO kaola-checkpoint commit exists.
  //   GREEN: exactly ONE kaola-checkpoint commit whose content is EXACTLY the closed nodes' dirty
  //     paths, a formed lane group over {pA,pB}, and a clean parent afterwards.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir, planPath } = makeMixedRepo();
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(r.result === 'ok', '#802-SEAM-COOPEN: open-ready ok, got ' + JSON.stringify(r));
    assert(r.seamCheckpoint && Array.isArray(r.seamCheckpoint.committed),
      '#802-SEAM-COOPEN: the envelope surfaces the seam checkpoint it performed, got ' + JSON.stringify(r.seamCheckpoint));
    assert(JSON.stringify(r.seamCheckpoint.committed.slice().sort()) === JSON.stringify(['src/serial_a.js']),
      '#802-SEAM-COOPEN: the checkpoint committed EXACTLY the closed nodes\' dirty paths, got ' + JSON.stringify(r.seamCheckpoint.committed));
    assert((r.seamCheckpoint.nodes || []).includes('sA'),
      '#802-SEAM-COOPEN: the checkpoint names the closed write-capable nodes it attributed to, got ' + JSON.stringify(r.seamCheckpoint.nodes));
    assert(seamCommitCount(repoRoot) === 1,
      '#802-SEAM-COOPEN: EXACTLY one kaola-checkpoint commit, got ' + JSON.stringify(gitSubjects(repoRoot)));
    // The checkpoint commit's content is exactly the dirty paths — nothing else rode along. (Resolve it
    // by SUBJECT: leg provisioning commits the tracked evidence stubs afterwards, so HEAD has moved on.)
    const seamSha = G.exec(repoRoot, ['log', '--format=%H %s'], { encoding: 'utf8' })
      .split('\n').map(s => s.trim()).filter(s => s.indexOf(' kaola-checkpoint(') > 0)[0].split(' ')[0];
    const touched = G.exec(repoRoot, ['show', '--name-only', '--format=', seamSha], { encoding: 'utf8' })
      .split('\n').map(s => s.trim()).filter(Boolean).sort();
    assert(JSON.stringify(touched) === JSON.stringify(['src/serial_a.js']),
      '#802-SEAM-COOPEN: the checkpoint commit touches ONLY the attributed dirty paths, got ' + JSON.stringify(touched));
    assert(r.laneGroup && Array.isArray(r.laneGroup.members) && r.laneGroup.members.length === 2,
      '#802-SEAM-COOPEN: the repaired seam co-opens the write frontier as a lane group, got ' + JSON.stringify(r.laneGroup));
    assert(JSON.stringify((r.opened || []).map(n => n.id).sort()) === JSON.stringify(['pA', 'pB']),
      '#802-SEAM-COOPEN: BOTH parallel writes opened, got ' + JSON.stringify((r.opened || []).map(n => n.id)));
    assert(r.serialDegradeReason === undefined,
      '#802-SEAM-COOPEN: NO serial degrade label — the blocker was repaired, not cited as evidence, got ' + JSON.stringify(r.serialDegradeReason));
    const rs = readRS(cacheDir);
    assert(rs && rs.lane_group && rs.lane_group.legs && rs.lane_group.legs.pA && rs.lane_group.legs.pB,
      '#802-SEAM-COOPEN: both legs provisioned, got ' + JSON.stringify(rs && rs.lane_group));
    assert(ledgerStatus(planPath, 'pA') === 'in_progress' && ledgerStatus(planPath, 'pB') === 'in_progress',
      '#802-SEAM-COOPEN: both frontier members are in_progress');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #802-SEAM-CHECKPOINT-TOGGLE-OFF (AC1/AC3d) — KAOLA_SEAM_CHECKPOINT=0 restores the `parent_dirty`
  //   SERIAL DEGRADE at this site: one serial write, no lane group, serialDegradeReason 'parent_dirty',
  //   and NO commit of any kind. This is the operator recovery posture, mirroring KAOLA_PARALLEL_WRITES=0.
  //   SCOPE (stated exactly, because "restores the prior behavior" would be false): the toggle restores
  //   the serial degrade ONLY. It does NOT resurrect the legless single-writer co-open that used to fire
  //   over a dirty parent at the write-awaits-drain seam — that path is retired UNCONDITIONALLY, as a
  //   separate deliberate tightening. #802-DRAIN-SEAM-OFF (below, the drain site) is the pin for that
  //   half: under the same opt-out a seam that once legless-co-opened now HOLDS.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir, planPath } = makeMixedRepo();
    const before = gitSubjects(repoRoot).length;
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], { KAOLA_SEAM_CHECKPOINT: '0' });
    assert(r.result === 'ok', '#802-TOGGLE-OFF: open-ready ok, got ' + JSON.stringify(r));
    assert(!r.laneGroup && Array.isArray(r.opened) && r.opened.length === 1 && r.opened[0].kind === 'write' && !r.opened[0].group_id,
      '#802-TOGGLE-OFF: the pre-repair single serial write returns, got ' + JSON.stringify({ laneGroup: r.laneGroup, opened: r.opened && r.opened.map(n => n.id) }));
    assert(r.serialDegradeReason === 'parent_dirty',
      '#802-TOGGLE-OFF: the pre-repair parent_dirty label returns under the opt-out, got ' + JSON.stringify(r.serialDegradeReason));
    assert(!r.seamCheckpoint, '#802-TOGGLE-OFF: no seamCheckpoint field under the opt-out, got ' + JSON.stringify(r.seamCheckpoint));
    assert(gitSubjects(repoRoot).length === before && seamCommitCount(repoRoot) === 0,
      '#802-TOGGLE-OFF: NOTHING was committed, got ' + JSON.stringify(gitSubjects(repoRoot)));
    const rs = readRS(cacheDir);
    assert(!rs || !rs.lane_group, '#802-TOGGLE-OFF: running-set.json carries NO lane_group');
    const openedId = r.opened[0].id;
    assert((openedId === 'pA' || openedId === 'pB') && ledgerStatus(planPath, openedId) === 'in_progress',
      '#802-TOGGLE-OFF: one parallel write opened serially, got ' + openedId);
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #802-SEAM-CHECKPOINT-UNATTRIBUTABLE (AC2/AC3b) — a dirty PRODUCTION path that NO closed
  //   write-capable node declared is FOREIGN (a user edit, an escaped write). The checkpoint refuses to
  //   vouch for it: a loud typed halt naming the paths — NO commit, NO lane group, and critically NO
  //   silent serial open (today's behavior buried the integrity signal under serialization).
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir, planPath } = makeMixedRepo({ extraDirty: [{ path: 'rogue.js', body: '// foreign bytes\n' }] });
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(r.result === 'refuse' && r.reason === 'seam_checkpoint_unattributable',
      '#802-UNATTRIBUTABLE: the halt is typed seam_checkpoint_unattributable, got ' + JSON.stringify({ result: r.result, reason: r.reason }));
    assert(Array.isArray(r.unattributed) && r.unattributed.includes('rogue.js') && !r.unattributed.includes('src/serial_a.js'),
      '#802-UNATTRIBUTABLE: the halt names ONLY the unattributed paths, got ' + JSON.stringify(r.unattributed));
    assert(typeof r.operator_hint === 'string' && r.operator_hint.length > 0,
      '#802-UNATTRIBUTABLE: the typed halt carries an operator hint, got ' + JSON.stringify(r.operator_hint));
    assert(seamCommitCount(repoRoot) === 0,
      '#802-UNATTRIBUTABLE: NO commit was made, got ' + JSON.stringify(gitSubjects(repoRoot)));
    // The zero-mutation halt shapes carry NO `commit` disclosure — the field's PRESENCE is the signal
    // that HEAD advanced, so it must be absent exactly when it did not (the negative half of the
    // post-commit-fence pin below).
    assert(r.commit === undefined && r.committed === undefined,
      '#802-UNATTRIBUTABLE: a pre-commit halt discloses NO commit (HEAD never moved), got ' + JSON.stringify({ commit: r.commit, committed: r.committed }));
    assert(!readRS(cacheDir), '#802-UNATTRIBUTABLE: NO running set was written (zero mutation)');
    assert(ledgerStatus(planPath, 'pA') === 'pending' && ledgerStatus(planPath, 'pB') === 'pending',
      '#802-UNATTRIBUTABLE: NO serial open either — both frontier members stay pending');
    // The index must be left clean (a partially-staged index is reset before halting).
    const staged = G.exec(repoRoot, ['diff', '--cached', '--name-only'], { encoding: 'utf8' }).trim();
    assert(staged === '', '#802-UNATTRIBUTABLE: the index is left unstaged, got ' + JSON.stringify(staged));
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #802-SEAM-CHECKPOINT-CRASH-RESUME (AC3c) — a crash AFTER the checkpoint commit but BEFORE the
  //   group opens leaves a CLEAN parent. The next open-ready re-runs the fence, finds `pass`, forms
  //   the group, and re-commits NOTHING — idempotent by construction, no journal file needed.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir } = makeMixedRepo({ preCommitSeam: true });
    assert(seamCommitCount(repoRoot) === 1, '#802-CRASH-RESUME precondition: the crashed run left exactly one checkpoint commit');
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(r.result === 'ok' && r.laneGroup && r.laneGroup.members.length === 2,
      '#802-CRASH-RESUME: the resumed open forms the group over the already-clean parent, got ' + JSON.stringify({ result: r.result, laneGroup: r.laneGroup }));
    assert(!r.seamCheckpoint,
      '#802-CRASH-RESUME: NO second checkpoint was performed (the fence already passes), got ' + JSON.stringify(r.seamCheckpoint));
    assert(seamCommitCount(repoRoot) === 1,
      '#802-CRASH-RESUME: still exactly ONE checkpoint commit — nothing re-committed, got ' + JSON.stringify(gitSubjects(repoRoot)));
    const rs = readRS(cacheDir);
    assert(rs && rs.lane_group && rs.lane_group.legs && rs.lane_group.legs.pA && rs.lane_group.legs.pB,
      '#802-CRASH-RESUME: both legs provisioned on the resume');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #802-SEAM-CHECKPOINT-END-TO-END (AC3a) — the repaired group closes GREEN all the way through the
  //   last-member octopus merge. This is the claim the two-horned deadlock said was impossible: with
  //   the serial dirt committed BEFORE the group baseline, the last-member parent-clean fence PASSES
  //   (Horn A gone) and the merge commit's union diff carries only the group's declared files, so the
  //   commit-based group barrier does NOT see the serial work (Horn B gone).
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir, planPath } = makeMixedRepo();
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(r.result === 'ok' && r.laneGroup, '#802-E2E: co-open, got ' + JSON.stringify(r));
    const rs = readRS(cacheDir);
    const legPA = rs.lane_group.legs.pA.legPath;
    const legPB = rs.lane_group.legs.pB.legPath;
    fs.writeFileSync(path.join(legPA, 'par_a.js'), '// pA leg work\n');
    fs.writeFileSync(path.join(legPB, 'par_b.js'), '// pB leg work\n');
    writeEvidence(cacheDir, 'pA'); writeEvidence(cacheDir, 'pB');
    const cA = runNode(repoRoot, ['close-node', '--node-id', 'pA', '--project', 'test-project', '--json'], DEFAULT);
    assert(cA.result === 'ok' && cA.barrier === 'deferred_to_group', '#802-E2E: pA defers to the group, got ' + JSON.stringify(cA));
    const cB = runNode(repoRoot, ['close-node', '--node-id', 'pB', '--project', 'test-project', '--json'], DEFAULT);
    assert(cB.result === 'ok' && cB.barrier === 'group_passed' && cB.synthesized === true,
      '#802-E2E: the LAST-member close passes the parent-clean fence AND the commit-based group barrier and merges, got ' + JSON.stringify(cB));
    assert(ledgerStatus(planPath, 'pA') === 'complete' && ledgerStatus(planPath, 'pB') === 'complete',
      '#802-E2E: both members closed complete');
    // The serial work survives on the branch (it was committed at the seam, never reverted) and BOTH
    // legs' declared files landed in the merge.
    for (const p of ['src/serial_a.js', 'par_a.js', 'par_b.js']) {
      let ok = true;
      try { G.exec(repoRoot, ['cat-file', '-e', 'HEAD:' + p], { stdio: ['ignore', 'ignore', 'ignore'] }); }
      catch (_) { ok = false; }
      assert(ok, '#802-E2E: ' + p + ' is reachable from HEAD after the merge');
    }
    cleanup(repoRoot);
  });

  // ==========================================================================
  // #802 AC6 — THE TERMINAL AUDITS. The seam checkpoint puts a MID-RUN commit on the feature
  // branch, which is a new input for two terminal transitions that previously only ever saw
  // uncommitted production dirt: FINALIZE (which must still attribute what remains on the branch)
  // and DISCARD (which must still reset the committed work). Both are driven here through their
  // REAL production entry points over a branch a REAL open-ready checkpointed.
  // ==========================================================================

  const CLAIM_CLI = path.join(__dirname, 'kaola-workflow-claim.js');

  // Put the mixed fixture on a FEATURE branch so `git diff <base>...HEAD` is a real, non-empty
  // branch diff (the sweep is vacuous when base === HEAD). Returns the surviving base branch name.
  function branchOffBase(repoRoot, feature) {
    const base = G.exec(repoRoot, ['rev-parse', '--abbrev-ref', 'HEAD'], { encoding: 'utf8' }).trim();
    G.exec(repoRoot, ['checkout', '-q', '-b', feature], { encoding: 'utf8', stdio: ['ignore', 'ignore', 'ignore'] });
    return base;
  }
  function headBranch(repoRoot) {
    try { return G.exec(repoRoot, ['rev-parse', '--abbrev-ref', 'HEAD'], { encoding: 'utf8' }).trim(); } catch (_) { return null; }
  }
  function reachableFromHead(repoRoot, p) {
    try { G.exec(repoRoot, ['cat-file', '-e', 'HEAD:' + p], { stdio: ['ignore', 'ignore', 'ignore'] }); return true; }
    catch (_) { return false; }
  }
  function branchNames(repoRoot) {
    try {
      return G.exec(repoRoot, ['for-each-ref', '--format=%(refname:short)', 'refs/heads'], { encoding: 'utf8' })
        .split('\n').map(s => s.trim()).filter(Boolean);
    } catch (_) { return []; }
  }
  // Drive the whole repaired group to its last-member merge (the #802-E2E choreography, reused).
  function driveGroupToMerge(repoRoot, cacheDir) {
    const rs = readRS(cacheDir);
    fs.writeFileSync(path.join(rs.lane_group.legs.pA.legPath, 'par_a.js'), '// pA leg work\n');
    fs.writeFileSync(path.join(rs.lane_group.legs.pB.legPath, 'par_b.js'), '// pB leg work\n');
    writeEvidence(cacheDir, 'pA'); writeEvidence(cacheDir, 'pB');
    runNode(repoRoot, ['close-node', '--node-id', 'pA', '--project', 'test-project', '--json'], DEFAULT);
    return runNode(repoRoot, ['close-node', '--node-id', 'pB', '--project', 'test-project', '--json'], DEFAULT);
  }
  // Seed the CONSUMER-mode finalize validation gate (the tmp fixture has no package.json, so
  // --finalize-check takes the final-validation.md arm). Computed AFTER the tree settles so the
  // recorded candidate hash binds the tree the sweep will recompute over.
  function seedFinalValidation(repoRoot, projDir, planPath) {
    let cand = '';
    try {
      // The candidate hash is computed by one process over the on-disk tree and written into
      // final-validation.md, which the finalize-check process below re-reads from disk.
      // spawn-class: durable-handoff
      cand = JSON.parse(execFileSync('node', [VALIDATOR, planPath, '--candidate-hash', '--json'],
        { cwd: repoRoot, encoding: 'utf8' }).trim().split('\n').pop()).validated_candidate_hash || '';
    } catch (_) { cand = ''; }
    fs.writeFileSync(path.join(projDir, '.cache', 'final-validation.md'),
      'verdict: pass\nfindings_blocking: 0\nvalidated_candidate_hash: ' + cand + '\n');
  }
  // The EXACT subprocess cmdFinalize shells before any irreversible side effect (claim.js:
  // `[validatorScript, authorityPlanPath, '--finalize-check', '--json']`, plus the forwarded --base).
  function finalizeCheck(repoRoot, planPath, base) {
    try {
      // The EXACT subprocess cmdFinalize shells before any irreversible side effect: a fresh
      // process re-derives the finalize verdict from the plan, the receipts and the tree alone.
      // spawn-class: durable-handoff
      const out = execFileSync('node', [VALIDATOR, planPath, '--finalize-check', '--json', '--base', base],
        { cwd: repoRoot, encoding: 'utf8' });
      return JSON.parse(out.trim().split('\n').pop());
    } catch (e) {
      try { return JSON.parse(String(e.stdout || '').trim().split('\n').pop()); } catch (_) { return { result: 'crash' }; }
    }
  }
  function setLedger(planPath, id, status) {
    const txt = fs.readFileSync(planPath, 'utf8');
    const start = txt.indexOf('## Node Ledger');
    const head = txt.slice(0, start), body = txt.slice(start);
    const re = new RegExp('^(\\|\\s*' + id + '\\s*\\|\\s*)\\S+(\\s*\\|)', 'm');
    fs.writeFileSync(planPath, head + body.replace(re, '$1' + status + '$2'));
  }

  // -------------------------------------------------------------------------
  // #802-AC6-FINALIZE-SWEEP-OVER-CHECKPOINT — FINALIZE MUST SWEEP WHAT REMAINS. A mid-run
  //   checkpoint commit changes WHERE the serial work lives: before #802 it sat UNCOMMITTED and was
  //   therefore INVISIBLE to the finalize attribution sweep (which enumerates `git diff <base>...HEAD`);
  //   after #802 it is a real commit ON the branch and the sweep DOES range over it. That is the whole
  //   audit: the checkpoint must not smuggle bytes past the sweep, and must not trip it either.
  //   Driven through the EXACT `--finalize-check` subprocess cmdFinalize shells (the gate that runs
  //   BEFORE any irreversible finalize side effect), over a branch a REAL open-ready checkpointed and a
  //   REAL lane group merged.
  //   GREEN: the sweep enumerates src/serial_a.js (proved directly against the branch diff) and PASSES,
  //     because sA — the node that declared it — is `complete`. The checkpoint is attributed by exactly
  //     the same rule that vouched for it at the seam; no new exemption, no allowband widening.
  //   RED (the same tree, one mutation): flip sA's ledger row back to `pending` and the identical sweep
  //     REFUSES `unattributed_change` naming src/serial_a.js. So the pass above is NOT vacuous, and a
  //     checkpoint commit is NOT self-authorizing — had the checkpoint ever committed a path no closed
  //     node declared, finalize would catch it here. Zero-mutation transition: nothing the sweep does
  //     touches the tree, so the RED and GREEN runs differ only in the ledger byte.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, projDir, cacheDir, planPath } = makeMixedRepo();
    const base = branchOffBase(repoRoot, 'workflow/seam-finalize');
    const open = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(open.result === 'ok' && open.laneGroup && open.seamCheckpoint,
      '#802-AC6-FINALIZE precondition: open-ready checkpointed and co-opened, got ' + JSON.stringify({ result: open.result, seamCheckpoint: open.seamCheckpoint }));
    const close = driveGroupToMerge(repoRoot, cacheDir);
    assert(close.result === 'ok' && close.barrier === 'group_passed',
      '#802-AC6-FINALIZE precondition: the group merged green, got ' + JSON.stringify(close));
    assert(seamCommitCount(repoRoot) === 1,
      '#802-AC6-FINALIZE precondition: the branch carries exactly one mid-run checkpoint commit');
    // The sweep's own input: the checkpointed path IS in the branch diff (pre-#802 it was uncommitted
    // and absent from it). Without this the pass below would prove nothing.
    const branchDiff = G.exec(repoRoot, ['diff', base + '...HEAD', '--name-only'], { encoding: 'utf8' })
      .split('\n').map(s => s.trim()).filter(Boolean);
    assert(branchDiff.includes('src/serial_a.js'),
      '#802-AC6-FINALIZE: the checkpointed serial path is IN the finalize sweep\'s branch diff, got ' + JSON.stringify(branchDiff));
    seedFinalValidation(repoRoot, projDir, planPath);
    const green = finalizeCheck(repoRoot, planPath, base);
    assert(green.result === 'pass',
      '#802-AC6-FINALIZE (GREEN): the finalize gate passes over the checkpoint-carrying branch, got ' + JSON.stringify(green));
    // RED: the checkpoint commit is NOT self-authorizing — remove the attributing node's `complete`
    // status and the identical sweep refuses on exactly that path.
    setLedger(planPath, 'sA', 'pending');
    seedFinalValidation(repoRoot, projDir, planPath);
    const red = finalizeCheck(repoRoot, planPath, base);
    assert(red.result === 'refuse' && red.reason === 'unattributed_change',
      '#802-AC6-FINALIZE (RED): with sA no longer complete the sweep refuses unattributed_change, got ' + JSON.stringify(red));
    assert(Array.isArray(red.unattributed) && red.unattributed.includes('src/serial_a.js'),
      '#802-AC6-FINALIZE (RED): the refusal names the checkpointed path, got ' + JSON.stringify(red.unattributed));
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #802-AC6-DISCARD-RESETS-CHECKPOINT — DISCARD MUST RESET THE COMMITTED WORK. A discard is a
  //   user-consented abandon: nothing the run produced may survive on the surviving base branch. The
  //   seam checkpoint is the first mechanism that COMMITS production bytes mid-run, so this is the
  //   audit that the abandon still reverses everything — the checkpoint must ride the feature branch
  //   to deletion, not leak onto the base. Driven through the REAL `kaola-workflow-claim.js release`
  //   subprocess (KAOLA_WORKFLOW_OFFLINE=1 so the advisory claim-label clearing is a local no-op).
  //   RED-then-GREEN in ONE run: the pre-discard assertions establish that the committed serial work
  //     really IS reachable from the feature-branch HEAD (the state a broken discard would strand on
  //     the base branch); the post-discard assertions prove the base branch carries neither the
  //     checkpoint commit nor the file. Falsification: if release merely archived the folder and left
  //     the branch, `src/serial_a.js` would still be reachable from HEAD after the call.
  //   The checkpoint here is the REAL `runSeamCheckpoint` transaction (the same function open-ready
  //   calls), driven directly rather than through `open-ready`, so the branch carries the checkpoint
  //   commit WITHOUT a live lane group: group formation force-adds tracked evidence stubs INSIDE the
  //   project folder, and archiving that folder then leaves tracked deletions that trip release's own
  //   tree-dirty gate — a pre-existing property of discarding mid-group, unrelated to the checkpoint
  //   under audit and one that would mask it.
  // -------------------------------------------------------------------------
  scenario(() => {
    const nodeMod = require('./kaola-workflow-adaptive-node.js');
    const { repoRoot, projDir, planPath, g } = makeMixedRepo();
    // Model an in-place run the way discard actually meets one: the run's own `kaola-workflow/`
    // state is NOT tracked on the branch (it is committed only at finalize), so the archive move
    // leaves no tracked deletion behind. Without this the release's own tree-dirty gate would skip
    // the base restore for a reason that has nothing to do with the checkpoint under audit.
    g(['rm', '-r', '-q', '--cached', 'kaola-workflow']);
    fs.appendFileSync(path.join(repoRoot, '.gitignore'), 'kaola-workflow/\n');
    g(['add', '.gitignore']);
    g(['commit', '-m', 'chore: untrack run state']);
    const base = branchOffBase(repoRoot, 'workflow/seam-discard');
    fs.writeFileSync(path.join(projDir, 'workflow-state.md'), [
      '# Kaola-Workflow State', '',
      '## Project', 'name: test-project', 'status: active', '',
      '## Sink', 'branch: workflow/seam-discard', 'base_branch: ' + base,
      'issue_number: 802', 'sink: merge', 'run_posture: in-place', ''
    ].join('\n'));
    // The real repair transaction, run against this repo (it resolves its git root from cwd).
    const prevCwd = process.cwd();
    let cp;
    try {
      process.chdir(repoRoot);
      cp = nodeMod.runSeamCheckpoint(planPath, 'test-project', nodeMod.shellNode, (p) => fs.readFileSync(p, 'utf8'));
    } finally { process.chdir(prevCwd); }
    assert(cp && cp.ok === true && JSON.stringify(cp.committed) === JSON.stringify(['src/serial_a.js']),
      '#802-AC6-DISCARD precondition: the real seam checkpoint committed the attributed serial path, got ' + JSON.stringify(cp));
    assert(seamCommitCount(repoRoot) === 1,
      '#802-AC6-DISCARD precondition: the branch carries exactly one mid-run checkpoint commit, got ' + JSON.stringify(gitSubjects(repoRoot)));
    // PRE: the committed serial work is genuinely on the branch — this is what discard must undo.
    assert(reachableFromHead(repoRoot, 'src/serial_a.js'),
      '#802-AC6-DISCARD (pre): the checkpointed serial file IS reachable from the feature-branch HEAD');
    assert(headBranch(repoRoot) === 'workflow/seam-discard',
      '#802-AC6-DISCARD (pre): the run is on its feature branch');
    const rel = (() => {
      const env = Object.assign({}, process.env, { KAOLA_WORKFLOW_OFFLINE: '1' });
      try {
        return JSON.parse(execFileSync('node', [CLAIM_CLI, 'release', '--project', 'test-project'],
          { cwd: repoRoot, encoding: 'utf8', env }).trim().split('\n').pop());
      } catch (e) {
        try { return JSON.parse(String(e.stdout || '').trim().split('\n').pop()); } catch (_) { return { released: false, crash: String(e && e.message) }; }
      }
    })();
    assert(rel.released === true,
      '#802-AC6-DISCARD: release succeeded over the checkpoint-carrying branch, got ' + JSON.stringify(rel));
    // POST: the base branch survives, the feature branch (and its checkpoint commit) is gone.
    assert(headBranch(repoRoot) === base,
      '#802-AC6-DISCARD: the base branch was restored, got ' + JSON.stringify(headBranch(repoRoot)));
    assert(!branchNames(repoRoot).includes('workflow/seam-discard'),
      '#802-AC6-DISCARD: the feature branch was deleted, got ' + JSON.stringify(branchNames(repoRoot)));
    assert(seamCommitCount(repoRoot) === 0,
      '#802-AC6-DISCARD: NO kaola-checkpoint commit survives on the base branch, got ' + JSON.stringify(gitSubjects(repoRoot)));
    assert(!reachableFromHead(repoRoot, 'src/serial_a.js'),
      '#802-AC6-DISCARD: the committed serial work is NOT reachable from the surviving base branch');
    assert(!fs.existsSync(planPath),
      '#802-AC6-DISCARD: the live project folder was archived away');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #802-AC6-EPOCH-LINEAGE-FAIL-CLOSED — EPOCH-LINEAGE ATTRIBUTION UNDER A LIVE CHILD EPOCH. A
  //   re-plan is claim-preserving: under a schema-2 CHILD epoch the parent epochs' uncommitted
  //   production work is still in THIS worktree, so attribution must union the SEALED ancestors'
  //   closed rows. The safety-critical half is the failure mode: when the lineage cannot be resolved,
  //   the checkpoint must FAIL CLOSED — never fall back to the child-only union, because that would
  //   silently narrow the attributed set (a parent-epoch path reading as foreign) or, worse, vouch
  //   for bytes on a lineage nothing proved.
  //   This fixture is the SHARPEST form of that: the ONLY dirty path (src/serial_a.js) IS attributable
  //   by the CHILD ledger alone, so a fail-OPEN implementation — one that shrugged off an unresolvable
  //   lineage and used the child union — would happily checkpoint and co-open. It must not.
  //   RED (fail-open): result 'ok', a kaola-checkpoint commit, a formed lane group.
  //   GREEN: typed `seam_checkpoint_failed` whose detail names the epoch-lineage cause, zero commits,
  //     zero mutation, and NO silent serial substitute either.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir, planPath } = makeMixedRepo();
    // Promote the frozen plan to a schema-2 CHILD epoch (plan_epoch >= 2 + a parent_plan_hash makes
    // resolveEpochLineagePlans APPLICABLE) while leaving .cache/epochs/ absent — the lineage is
    // applicable but unresolvable, exactly the state a half-completed / tampered replan leaves behind.
    // Re-stamp plan_hash over the edited body — the integrity prologue runs BEFORE the seam repair,
    // so a tampered hash would refuse plan_integrity_failed and never reach the lineage at all.
    const raw = fs.readFileSync(planPath, 'utf8');
    const body = raw.replace(/^<!--\s*plan_hash:\s*[0-9a-f]{64}\s*-->\n\n?/, '')
      .replace(/^## Meta$/m, '## Meta\nepoch_schema_version: 2\nplan_epoch: 2\nparent_plan_hash: ' + 'a'.repeat(64));
    fs.writeFileSync(planPath, '<!-- plan_hash: ' + planValidator.computePlanHash(body) + ' -->\n\n' + body);
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(r.result === 'refuse' && r.reason === 'seam_checkpoint_failed',
      '#802-AC6-EPOCH-FAILCLOSED: an unresolvable lineage is a typed seam_checkpoint_failed halt, got ' + JSON.stringify({ result: r.result, reason: r.reason, detail: r.detail }));
    assert(typeof r.detail === 'string' && /epoch_lineage|snapshot|state_epoch/.test(r.detail),
      '#802-AC6-EPOCH-FAILCLOSED: the halt names the LINEAGE cause (never a generic git failure), got ' + JSON.stringify(r.detail));
    assert(seamCommitCount(repoRoot) === 0,
      '#802-AC6-EPOCH-FAILCLOSED: NOTHING was committed — the child-only union was NOT used as a fallback, got ' + JSON.stringify(gitSubjects(repoRoot)));
    assert(!readRS(cacheDir), '#802-AC6-EPOCH-FAILCLOSED: no running set was written (zero mutation)');
    assert(ledgerStatus(planPath, 'pA') === 'pending' && ledgerStatus(planPath, 'pB') === 'pending',
      '#802-AC6-EPOCH-FAILCLOSED: NO serial open either — the frontier stays pending');
    const staged = G.exec(repoRoot, ['diff', '--cached', '--name-only'], { encoding: 'utf8' }).trim();
    assert(staged === '', '#802-AC6-EPOCH-FAILCLOSED: the index is left unstaged, got ' + JSON.stringify(staged));
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #802-AC6-EPOCH-LINEAGE-UNION — the POSITIVE half of the same audit, pinned directly on the
  //   exported attribution proof. The lineage WALKER itself (seals, projection, contiguity) is the
  //   validator's own verified machinery with its own suite; what must be pinned HERE is that
  //   seamCheckpointAttribution CONSUMES it correctly. The resolver is stubbed on the shared validator
  //   exports (the same module object the function resolves at call time) so the three consumption
  //   rules are isolated from snapshot-fixture mechanics:
  //     (a) a sealed ancestor's COMPLETE write-capable row widens the union (its declared path becomes
  //         attributable, and its id is named on the checkpoint);
  //     (b) an ancestor row that is NOT complete does NOT widen it — unioning DECLARATIONS without
  //         ATTRIBUTION would be a laundering primitive (a parent node that never ran carrying its
  //         file through unreviewed);
  //     (c) an applicable-but-unverified lineage returns ok:false, so the caller halts instead of
  //         falling back to the child-only union.
  //   RED for (a): without the lineage branch the parent path is absent from the union (asserted
  //     directly by the not-applicable control below, which is the same call with the resolver off).
  // -------------------------------------------------------------------------
  scenario(() => {
    const nodeMod = require('./kaola-workflow-adaptive-node.js');
    const pv = require('./kaola-workflow-plan-validator.js');
    const childPlan = [
      '# Workflow Plan — test-project', '',
      '## Meta', 'labels: area:scripts', '',
      '## Nodes', '',
      '| id | role | depends_on | declared_write_set | cardinality | shape |',
      '| --- | --- | --- | --- | --- | --- |',
      '| c1 | tdd-guide | — | child_only.js | 1 | sequence |',
      '| c2 | tdd-guide | c1 | later.js | 1 | sequence |', '',
      '## Node Ledger', '', '| id | status |', '| --- | --- |',
      '| c1 | complete |', '| c2 | pending |', '',
    ].join('\n') + '\n';
    const mkLineage = (ledgerRows) => ({
      applicable: true, ok: true,
      lineagePlans: [{
        epoch: 1,
        // Same shape the validator's own walker yields (parseNodes rows carry role + writeSetRaw).
        // p3 is the WRITE-CAPABILITY probe: a CLOSED ancestor row whose role may not legally declare a
        // write set at all, so its declaration must not widen the union either (case (d)).
        nodes: [
          { id: 'p1', role: 'implementer', writeSetRaw: 'parent_epoch.js' },
          { id: 'p2', role: 'implementer', writeSetRaw: 'parent_never_ran.js' },
          { id: 'p3', role: 'code-reviewer', writeSetRaw: 'parent_readonly_row.js' },
        ],
        ledger: new Map(ledgerRows),
      }],
    });
    const original = pv.resolveEpochLineagePlans;
    try {
      // Control: lineage NOT applicable ⇒ child-only union (the pre-lineage behavior, and the RED
      // baseline for (a) — the parent path is simply not there).
      pv.resolveEpochLineagePlans = () => ({ applicable: false });
      const childOnly = nodeMod.seamCheckpointAttribution(childPlan, '/p/workflow-plan.md');
      assert(childOnly.ok && childOnly.union.has('child_only.js') && !childOnly.union.has('parent_epoch.js'),
        '#802-AC6-EPOCH-UNION (control): a non-child plan attributes child rows ONLY, got ' + JSON.stringify([...(childOnly.union || [])]));
      // (a) + (b): a COMPLETE ancestor row widens the union; a non-complete one never does.
      pv.resolveEpochLineagePlans = () => mkLineage([['p1', 'complete'], ['p2', 'pending'], ['p3', 'complete']]);
      const unioned = nodeMod.seamCheckpointAttribution(childPlan, '/p/workflow-plan.md');
      assert(unioned.ok && unioned.union.has('parent_epoch.js'),
        '#802-AC6-EPOCH-UNION (a): a sealed ancestor\'s COMPLETE row widens the attributed set, got ' + JSON.stringify([...(unioned.union || [])]));
      assert(unioned.union.has('child_only.js'),
        '#802-AC6-EPOCH-UNION (a): the child rows are still attributed alongside the lineage');
      assert(!unioned.union.has('parent_never_ran.js'),
        '#802-AC6-EPOCH-UNION (b): an ancestor row that is NOT complete never widens the set — declarations without attribution would be a laundering primitive');
      assert(unioned.nodeIds.includes('p1') && !unioned.nodeIds.includes('p2'),
        '#802-AC6-EPOCH-UNION (b): the checkpoint names only the ancestors it actually attributed to, got ' + JSON.stringify(unioned.nodeIds));
      assert(!unioned.union.has('parent_readonly_row.js') && !unioned.nodeIds.includes('p3'),
        '#802-AC6-EPOCH-UNION (d): a CLOSED ancestor row whose ROLE may not declare a write set widens nothing either — the write-capability wall applies across the lineage, not just to the child, got ' + JSON.stringify({ union: [...(unioned.union || [])], nodeIds: unioned.nodeIds }));
      // (c) applicable but UNVERIFIED ⇒ ok:false, so the caller halts rather than misattributes.
      pv.resolveEpochLineagePlans = () => ({ applicable: true, ok: false, reason: 'snapshot_manifest_invalid' });
      const unverified = nodeMod.seamCheckpointAttribution(childPlan, '/p/workflow-plan.md');
      assert(unverified.ok === false && /^epoch_lineage_/.test(String(unverified.reason)),
        '#802-AC6-EPOCH-UNION (c): an unverified lineage returns a typed ok:false — never the child-only fallback, got ' + JSON.stringify(unverified));
      // (c') a THROWING resolver is also fail-closed, not a swallowed pass.
      pv.resolveEpochLineagePlans = () => { throw new Error('boom'); };
      const threw = nodeMod.seamCheckpointAttribution(childPlan, '/p/workflow-plan.md');
      assert(threw.ok === false && threw.reason === 'epoch_lineage_unreadable',
        '#802-AC6-EPOCH-UNION (c\'): a crashing lineage resolver fails closed, got ' + JSON.stringify(threw));
    } finally {
      pv.resolveEpochLineagePlans = original;
    }
  });

  // -------------------------------------------------------------------------
  // #802-QUOTED-PATH-NO-PARTIAL-CHECKPOINT — the git-quoted (non-ASCII) dirty path. The parent-clean
  //   fence's porcelain parser strips a path's SURROUNDING double quotes but does NOT decode git's
  //   C-style escapes, so `src/café.js` arrives as the literal `src/caf\303\251.js`. Two things must
  //   hold, and only the second was ever obvious:
  //     1. NO SILENT PARTIAL CHECKPOINT. The frontier here carries BOTH an ordinary attributable path
  //        (src/serial_a.js) and a quoted one. A partial repair — committing the attributable half and
  //        proceeding, or committing it and then failing — would leave the run's own bytes half-landed
  //        with no journal saying so. Nothing may be committed and nothing may be staged.
  //     2. NO MISATTRIBUTION. See the unit pin below for the sharp case; here the quoted path must not
  //        be silently dropped from the dirty set either (dropping it is "assume clean" by omission).
  //   The outcome is a LOUD typed halt naming the quoted path — acceptable per the fail-closed rule —
  //   and emphatically NOT a serial degrade.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir, planPath } = makeMixedRepo({ extraDirty: [{ path: 'src/café.js', body: '// non-ASCII production path\n' }] });
    const before = gitSubjects(repoRoot).length;
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(r.result === 'refuse' && r.reason === 'seam_checkpoint_failed',
      '#802-QUOTED-PATH: a git-quoted dirty path is a typed seam_checkpoint_failed halt, got ' + JSON.stringify({ result: r.result, reason: r.reason, detail: r.detail }));
    assert(typeof r.detail === 'string' && r.detail.indexOf('quoted_path_unsupported') === 0,
      '#802-QUOTED-PATH: the halt says WHY in its own vocabulary (not a raw git pathspec error), got ' + JSON.stringify(r.detail));
    assert(r.detail.indexOf('caf') !== -1,
      '#802-QUOTED-PATH: the halt names the offending path, got ' + JSON.stringify(r.detail));
    // 1. NO PARTIAL CHECKPOINT: the attributable sibling was NOT committed on its own.
    assert(seamCommitCount(repoRoot) === 0 && gitSubjects(repoRoot).length === before,
      '#802-QUOTED-PATH: NOTHING was committed — no partial checkpoint of the attributable half, got ' + JSON.stringify(gitSubjects(repoRoot)));
    const staged = G.exec(repoRoot, ['diff', '--cached', '--name-only'], { encoding: 'utf8' }).trim();
    assert(staged === '', '#802-QUOTED-PATH: the index is left unstaged, got ' + JSON.stringify(staged));
    assert(!reachableFromHead(repoRoot, 'src/serial_a.js'),
      '#802-QUOTED-PATH: the attributable serial path is still UNCOMMITTED (it was not half-landed)');
    // and NOT a silent serial degrade.
    assert(!readRS(cacheDir), '#802-QUOTED-PATH: no running set was written (zero mutation)');
    assert(ledgerStatus(planPath, 'pA') === 'pending' && ledgerStatus(planPath, 'pB') === 'pending',
      '#802-QUOTED-PATH: NO serial open either — the frontier stays pending');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #802-QUOTED-PATH-NO-MISATTRIBUTION — the sharp case, pinned on the exported repair directly.
  //   A real file named `src/a<TAB>b.js` is reported by the fence as the literal `src/a\tb.js`. The
  //   attribution comparison normalizes every backslash to `/`, so that string COMPARES EQUAL to a
  //   declared `src/a/tb.js` — i.e. a FOREIGN file would be vouched for by a node that never wrote it.
  //   Before the guard, that misattribution was real and was only prevented from landing because the
  //   same undecoded string matched no file when `git add` ran — fail-closed by coincidence, one step
  //   downstream, with a raw git error as the operator's only signal.
  //   RED (asserted here, not merely narrated): the normalized form IS in the attributed union, so the
  //     attribution step alone WOULD have vouched for it.
  //   GREEN: runSeamCheckpoint refuses at the quoted-path guard BEFORE attribution runs — a typed
  //     `quoted_path_unsupported`, so the misattribution never enters the attributed set at all.
  // -------------------------------------------------------------------------
  scenario(() => {
    const nodeMod = require('./kaola-workflow-adaptive-node.js');
    const planText = [
      '# Workflow Plan — test-project', '',
      '## Meta', 'labels: area:scripts', '',
      '## Nodes', '',
      '| id | role | depends_on | declared_write_set | cardinality | shape |',
      '| --- | --- | --- | --- | --- | --- |',
      '| sA | tdd-guide | — | src/a/tb.js | 1 | sequence |',
      '| pA | tdd-guide | sA | par_a.js | 1 | sequence |', '',
      '## Node Ledger', '', '| id | status |', '| --- | --- |',
      '| sA | complete |', '| pA | pending |', '',
    ].join('\n') + '\n';
    // RED: the normalization really does fold the escaped tab onto the declared path.
    const attributed = nodeMod.seamCheckpointAttribution(planText, '/p/workflow-plan.md');
    assert(attributed.ok && attributed.union.has('src/a/tb.js'),
      '#802-QUOTED-MISATTR (RED): the declared path IS in the attributed union, so the escaped form would normalize onto it');
    // GREEN: the guard refuses the whole checkpoint before attribution can vouch for it.
    const fenceShell = () => ({ exitCode: 1, result: 'refuse', reason: 'parent_dirty', dirty: ['src/a\\tb.js'] });
    const out = nodeMod.runSeamCheckpoint('/p/workflow-plan.md', 'test-project', fenceShell, () => planText);
    assert(out.ok === false && out.reason === 'seam_checkpoint_failed',
      '#802-QUOTED-MISATTR (GREEN): the repair refuses rather than vouching for a quoted path, got ' + JSON.stringify(out));
    assert(String(out.detail).indexOf('quoted_path_unsupported') === 0,
      '#802-QUOTED-MISATTR (GREEN): the refusal is the quoted-path guard, NOT a downstream git failure, got ' + JSON.stringify(out.detail));
    assert(out.unattributed === undefined,
      '#802-QUOTED-MISATTR (GREEN): the guard preempts attribution entirely — no unattributable verdict is rendered on an undecodable path, got ' + JSON.stringify(out.unattributed));
  });

  // -------------------------------------------------------------------------
  // #802 D7 — THE SEAM MUST NOT HALT ON A CONSUMER'S GIT CONFIG, AND MUST NOT BYPASS IT EITHER.
  //
  // The checkpoint fires MID-SCHEDULE (unlike every finalize-time commit), so a repo-local hook or a
  // key-less `commit.gpgsign true` could convert a routine seam repair into a hard
  // `seam_checkpoint_failed` — a state that merely serial-degraded before the repair existed, i.e. a
  // regression introduced by the repair itself. The FIRST attempt at this fix added `--no-verify`, on
  // the reasoning "this is internal scheduler bookkeeping". That reasoning does not hold: the seam
  // checkpoint is the ONLY scheduler commit that lands USER PRODUCTION SOURCE (`kw-stub` is an empty
  // `.cache` stub commit; `kw-leg`/`kw-synth` are in-lane/merge commits), so bypassing `pre-commit`
  // disarmed the consumer's CONTENT INSPECTION on exactly the bytes it exists to see — permanently,
  // since nothing re-examines them once they are in history.
  //
  // The corrected design splits the two config classes by what they actually assert:
  //   ATTRIBUTION (identity, signing) — overridden. `-c user.email/user.name` inject the scheduler's own
  //     identity; `-c commit.gpgsign=false` disables signing. Neither says anything about the BYTES, so
  //     neither may halt a run.
  //   CONTENT INSPECTION (`pre-commit`, `commit-msg`, `prepare-commit-msg`) — honored, never bypassed.
  //     A veto DEGRADES the seam to the pre-#802 serial path under the typed, visible label
  //     `serialDegradeReason: 'seam_checkpoint_declined'`. A labeled degrade to a known-good path is
  //     the fail-safe the doctrine wants; wedging a run that would otherwise complete is strictly worse.
  //
  // Every scenario below PROVES ITS OWN HOSTILITY FIRST (an ordinary `git commit` is shown to fail, or
  // the absence of an identity is shown to fail a commit) before asserting how the seam behaves —
  // without that the greens would prove nothing.
  // -------------------------------------------------------------------------

  // Strip any ambient (global/system) git identity from a driven run, so `noIdentity` is a real probe
  // on a developer box that has one configured. GIT_CONFIG_GLOBAL=/dev/null + GIT_CONFIG_NOSYSTEM=1 is
  // git's own supported way to say "repo config only".
  const NO_AMBIENT_GIT_IDENTITY = { GIT_CONFIG_GLOBAL: '/dev/null', GIT_CONFIG_NOSYSTEM: '1' };
  // PROVE a fixture bites: an ordinary commit in this repo is vetoed. `--allow-empty` so the probe
  // leaves nothing behind whichever guard trips.
  function ordinaryCommitRefused(repoRoot, extraEnv) {
    try {
      G.exec(repoRoot, ['commit', '--allow-empty', '-m', 'hostility probe'], { stdio: ['ignore', 'ignore', 'ignore'], env: Object.assign({}, process.env, extraEnv || {}) });
      return false;
    } catch (_) { return true; }
  }

  // -------------------------------------------------------------------------
  // #802-D7-PRE-COMMIT-DEGRADES (demonstration (a); closes regression N1) — A HOSTILE `pre-commit` HOOK
  //   DEGRADES THE SEAM, IT DOES NOT WEDGE THE RUN. Pre-#802 this mixed dirty-parent shape serial-
  //   degraded and closed green. The `--no-verify` fix made it CO-OPEN instead, and the very next
  //   scheduler commit inside the group (`kw-leg`, which carries no bypass) then hard-failed at the
  //   last-member close with `leg_capture_failed` — a live lane group that can never merge. The fix had
  //   moved the halt from the open seam to the close seam, where it is strictly worse.
  //   RED (the `--no-verify` tree): result ok + laneGroup formed; driving the group to its last-member
  //     close returns `leg_capture_failed` and the run is wedged.
  //   GREEN: NO group forms at all — the checkpoint is refused by the hook, the open degrades to a
  //     single serial write labeled `seam_checkpoint_declined`, nothing is committed, and the run
  //     CONTINUES (the serial member closes green). `leg_capture_failed` is structurally unreachable
  //     because no leg is ever provisioned.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir, planPath } = makeMixedRepo({ hostilePreCommit: true });
    assert(ordinaryCommitRefused(repoRoot),
      '#802-D7-PRE-COMMIT precondition: the fixture\'s pre-commit hook really does veto an ordinary commit');
    const before = gitSubjects(repoRoot).length;
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(r.result === 'ok',
      '#802-D7-PRE-COMMIT: the hook veto is a DEGRADE, not a halt, got ' + JSON.stringify({ result: r.result, reason: r.reason, detail: r.detail }));
    assert(r.serialDegradeReason === 'seam_checkpoint_declined',
      '#802-D7-PRE-COMMIT: the degrade is LABELED with its own typed cause (never silent, never the bare parent_dirty), got ' + JSON.stringify(r.serialDegradeReason));
    assert(r.seamCheckpointDeclined && typeof r.seamCheckpointDeclined.detail === 'string' && r.seamCheckpointDeclined.detail.indexOf('git:') === 0,
      '#802-D7-PRE-COMMIT: the response names WHICH refusal produced the degrade, got ' + JSON.stringify(r.seamCheckpointDeclined));
    assert(!r.laneGroup && Array.isArray(r.opened) && r.opened.length === 1 && r.opened[0].kind === 'write' && !r.opened[0].group_id,
      '#802-D7-PRE-COMMIT: the known-good single serial write is what we degraded ONTO, got ' + JSON.stringify({ laneGroup: r.laneGroup, opened: r.opened && r.opened.map(n => n.id) }));
    assert(!r.seamCheckpoint,
      '#802-D7-PRE-COMMIT: no checkpoint is claimed, got ' + JSON.stringify(r.seamCheckpoint));
    assert(gitSubjects(repoRoot).length === before && seamCommitCount(repoRoot) === 0,
      '#802-D7-PRE-COMMIT: the vetoed commit did NOT land — git never advances the ref on a failed commit, got ' + JSON.stringify(gitSubjects(repoRoot)));
    const rs = readRS(cacheDir);
    assert(rs && !rs.lane_group,
      '#802-D7-PRE-COMMIT: no lane_group ⇒ no leg ⇒ `leg_capture_failed` is structurally unreachable, got ' + JSON.stringify(rs && rs.lane_group));
    // THE PIN THE REGRESSION IS ABOUT: the run keeps going. Close the serial member the degrade opened.
    const openedId = r.opened[0].id;
    fs.writeFileSync(path.join(repoRoot, openedId === 'pA' ? 'par_a.js' : 'par_b.js'), '// ' + openedId + ' serial work\n');
    writeEvidence(cacheDir, openedId);
    const close = runNode(repoRoot, ['close-node', '--node-id', openedId, '--project', 'test-project', '--json'], DEFAULT);
    assert(close.result === 'ok' && close.reason !== 'leg_capture_failed',
      '#802-D7-PRE-COMMIT: the degraded run CONTINUES — the serial member closes green, got ' + JSON.stringify({ result: close.result, reason: close.reason }));
    assert(ledgerStatus(planPath, openedId) === 'complete',
      '#802-D7-PRE-COMMIT: the closed member is complete, got ' + ledgerStatus(planPath, openedId));
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #802-D7-NO-IDENTITY-PROCEEDS (demonstration (b); closes regression N2) — A REPO WITH NO
  //   `user.email`/`user.name` PROCEEDS. Identity is ATTRIBUTION, not content: the scheduler's commits
  //   are the scheduler's, so it names itself (`kaola-workflow <kaola-workflow@local>`) exactly as every
  //   other scheduler commit already did, instead of inheriting nothing and hard-refusing at a seam
  //   where pre-#802 the run simply proceeded.
  //   RED (pre-fix): the checkpoint commit inherited no identity → git's "Please tell me who you are"
  //     → seam_checkpoint_failed, a hard halt on a repo that used to run.
  //   GREEN: the checkpoint lands, authored/committed by the scheduler identity, and the frontier
  //     co-opens. NON-VACUOUS: an ordinary identity-less commit in this same repo is proved to fail.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir, planPath } = makeMixedRepo({ noIdentity: true });
    assert(ordinaryCommitRefused(repoRoot, NO_AMBIENT_GIT_IDENTITY),
      '#802-D7-NO-IDENTITY precondition: with no repo identity and no ambient one, an ordinary commit really does fail');
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'],
      Object.assign({}, DEFAULT, NO_AMBIENT_GIT_IDENTITY));
    assert(r.result === 'ok',
      '#802-D7-NO-IDENTITY: a repo with no configured identity does NOT halt at the seam, got ' + JSON.stringify({ result: r.result, reason: r.reason, detail: r.detail }));
    assert(r.seamCheckpoint && JSON.stringify(r.seamCheckpoint.committed) === JSON.stringify(['src/serial_a.js']),
      '#802-D7-NO-IDENTITY: the checkpoint committed the attributed serial path, got ' + JSON.stringify(r.seamCheckpoint));
    const who = G.exec(repoRoot, ['log', '-1', '--format=%an <%ae>|%cn <%ce>', r.seamCheckpoint.commit], { encoding: 'utf8' }).trim();
    assert(who === 'kaola-workflow <kaola-workflow@local>|kaola-workflow <kaola-workflow@local>',
      '#802-D7-NO-IDENTITY: the checkpoint is attributed to the INJECTED scheduler identity, got ' + JSON.stringify(who));
    assert(r.laneGroup && r.laneGroup.members.length === 2 && !r.serialDegradeReason,
      '#802-D7-NO-IDENTITY: the frontier co-opens (kw-stub carries the same injected identity), got ' + JSON.stringify({ laneGroup: r.laneGroup, serialDegradeReason: r.serialDegradeReason }));
    assert(ledgerStatus(planPath, 'pA') === 'in_progress' && ledgerStatus(planPath, 'pB') === 'in_progress',
      '#802-D7-NO-IDENTITY: both frontier members opened');
    const rs = readRS(cacheDir);
    assert(rs && rs.lane_group && rs.lane_group.legs && rs.lane_group.legs.pA && rs.lane_group.legs.pB,
      '#802-D7-NO-IDENTITY: both legs provisioned');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #802-D7-SECRET-SCANNER-STILL-INSPECTS (demonstration (c); closes regression N3, SECURITY) —
  //   A CONSUMER'S `pre-commit` SECRET SCANNER STILL SEES THE CHECKPOINT'S BYTES. The seam checkpoint is
  //   the only scheduler commit that lands user production source, so `--no-verify` there did not DEFER
  //   the scanner, it DEFEATED it: an ordinary commit of those bytes was blocked, the checkpoint
  //   committed the very same bytes anyway, and the key was then in `git log -p --all` forever —
  //   `kaola-workflow-claim.js` uses no `--no-verify`, so finalize would otherwise have surfaced it.
  //   RED (the `--no-verify` tree): result ok, the checkpoint lands, and the AKIA key is reachable from
  //     the branch — `git log -p --branches` contains it, permanently.
  //   GREEN: the scanner is HANDED the checkpoint's staged content (proved directly, via a witness the
  //     hook writes naming the paths it inspected — not merely inferred from a failed commit), it
  //     vetoes, the seam degrades to serial, and the key never reaches the branch. NON-VACUOUS on both
  //     sides — the scanner is proved to block an ordinary commit of the same bytes first, and the key
  //     is proved present in the WORKING TREE afterwards, so the branch assertion is about the commit
  //     and not about a missing file.
  //   SCOPE, stated honestly: the assertion is over BRANCH history (`--branches`), not `--all`. The
  //     per-node barrier baseline anchors a full-worktree snapshot commit under
  //     `refs/kaola-workflow/barrier/**` at EVERY node open — pre-#802, on the serial path, identically
  //     — so `--all` reaches uncommitted worktree bytes by construction, for reasons that have nothing
  //     to do with this seam and that this fix neither creates nor changes. What the checkpoint could
  //     newly do, and must not, is put them on the BRANCH, which is what gets pushed and finalized.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir } = makeMixedRepo({ secretScanner: true });
    const SECRET = 'AKIA' + 'IOSFODNN7EXAMPLE';
    const witnessPath = path.join(repoRoot, '.git', 'scanner-witness');
    // PROVE hostility on the EXACT bytes under audit: stage the attributed serial path and try to commit.
    let scannerBlockedOrdinaryCommit = false;
    G.exec(repoRoot, ['add', '--', 'src/serial_a.js'], { stdio: ['ignore', 'ignore', 'ignore'] });
    try {
      G.exec(repoRoot, ['commit', '-m', 'ordinary commit of the same bytes', '--', 'src/serial_a.js'], { stdio: ['ignore', 'ignore', 'ignore'] });
    } catch (_) { scannerBlockedOrdinaryCommit = true; }
    // Restore the untracked/uncommitted state the seam is supposed to meet, and clear the witness so
    // whatever it records next is unambiguously the SCHEDULER's commit.
    G.exec(repoRoot, ['reset', '-q', '--', 'src/serial_a.js'], { stdio: ['ignore', 'ignore', 'ignore'] });
    assert(scannerBlockedOrdinaryCommit,
      '#802-D7-SECRET-SCANNER precondition: the scanner really does block an ordinary commit of these bytes');
    assert(seamCommitCount(repoRoot) === 0,
      '#802-D7-SECRET-SCANNER precondition: the probe committed nothing');
    fs.writeFileSync(witnessPath, '');
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    // THE PIN THE ISSUE ASKS FOR: the content-inspecting hook SAW the checkpoint's bytes.
    const witness = fs.readFileSync(witnessPath, 'utf8').split('\n').map(s => s.trim()).filter(Boolean);
    assert(witness.includes('src/serial_a.js'),
      '#802-D7-SECRET-SCANNER: the repo-local pre-commit scanner was HANDED the checkpoint\'s staged content, got ' + JSON.stringify(witness));
    assert(r.result === 'ok' && r.serialDegradeReason === 'seam_checkpoint_declined',
      '#802-D7-SECRET-SCANNER: the scanner vetoed the checkpoint and the seam DEGRADED, got ' + JSON.stringify({ result: r.result, reason: r.reason, serialDegradeReason: r.serialDegradeReason }));
    assert(!r.laneGroup && !r.seamCheckpoint,
      '#802-D7-SECRET-SCANNER: nothing was checkpointed and no group formed, got ' + JSON.stringify({ laneGroup: r.laneGroup, seamCheckpoint: r.seamCheckpoint }));
    // THE SECURITY PIN: the key is in the working tree (so the check below is not vacuous) and on NO
    // branch — no commit, no branch tip, no leg branch.
    assert(fs.readFileSync(path.join(repoRoot, 'src', 'serial_a.js'), 'utf8').indexOf(SECRET) !== -1,
      '#802-D7-SECRET-SCANNER: the payload really is in the working tree');
    const branchHistory = G.exec(repoRoot, ['log', '-p', '--branches'], { encoding: 'utf8', maxBuffer: 64 * 1024 * 1024 });
    assert(branchHistory.indexOf(SECRET) === -1,
      '#802-D7-SECRET-SCANNER: the scanner was NOT defeated — the key never reached the branch');
    assert(!readRS(cacheDir) || !readRS(cacheDir).lane_group,
      '#802-D7-SECRET-SCANNER: no lane group, so no leg branch carries it either');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #802-D7-PREPARE-COMMIT-MSG-DEGRADES (demonstration (d); closes regression N4) — THE HOOK CLASS
  //   `--no-verify` NEVER COVERED. `--no-verify` skips only `pre-commit` and `commit-msg`; a
  //   `prepare-commit-msg` hook exiting 1 still halted the seam. So the in-code comment that enumerated
  //   what was "already inert" was an OVERCLAIM, and the audit it supported was wrong. With the bypass
  //   removed the claim is moot for bypass purposes — but the behavior still has to be right, and the
  //   answer is the same one every environment refusal gets: DEGRADE, LABELED.
  //   RED (the `--no-verify` tree): result refuse / seam_checkpoint_failed — the run halts even though
  //     the bypass was supposed to have covered "the hooks".
  //   GREEN: result ok, `serialDegradeReason: 'seam_checkpoint_declined'`, nothing committed.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, planPath } = makeMixedRepo({ hostilePrepareCommitMsg: true });
    assert(ordinaryCommitRefused(repoRoot),
      '#802-D7-PREPARE-MSG precondition: the prepare-commit-msg hook really does veto an ordinary commit');
    // And it is genuinely the class `--no-verify` does not cover — prove it against git itself.
    let survivesNoVerify = false;
    try {
      G.exec(repoRoot, ['commit', '--no-verify', '--allow-empty', '-m', 'bypass probe'], { stdio: ['ignore', 'ignore', 'ignore'] });
    } catch (_) { survivesNoVerify = true; }
    assert(survivesNoVerify,
      '#802-D7-PREPARE-MSG precondition: `--no-verify` does NOT disable prepare-commit-msg (the N4 overclaim)');
    const before = gitSubjects(repoRoot).length;
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(r.result === 'ok' && r.serialDegradeReason === 'seam_checkpoint_declined',
      '#802-D7-PREPARE-MSG: a prepare-commit-msg veto degrades, it does not halt, got ' + JSON.stringify({ result: r.result, reason: r.reason, serialDegradeReason: r.serialDegradeReason }));
    assert(!r.laneGroup && r.opened.length === 1,
      '#802-D7-PREPARE-MSG: degraded onto the single serial write, got ' + JSON.stringify(r.opened && r.opened.map(n => n.id)));
    assert(gitSubjects(repoRoot).length === before && seamCommitCount(repoRoot) === 0,
      '#802-D7-PREPARE-MSG: nothing landed, got ' + JSON.stringify(gitSubjects(repoRoot)));
    assert(ledgerStatus(planPath, r.opened[0].id) === 'in_progress',
      '#802-D7-PREPARE-MSG: the serial member really opened');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #802-D7-KEYLESS-SIGNING-STILL-LANDS (demonstration (e); closes the other half of N1) — SIGNING IS
  //   ATTRIBUTION, SO IT IS OVERRIDDEN AT EVERY SCHEDULER COMMIT SITE. `commit.gpgsign true` with an
  //   unusable key says nothing about the bytes; letting it halt a run buys no safety at all. This is
  //   the case that proves the override reaches ALL FOUR sites, because the group runs to completion:
  //   checkpoint → `kw-stub` → `kw-leg` (×2) → `kw-synth`. `kw-leg`/`kw-synth` carried NO override
  //   before this fix, so the group co-opened and then died at the last-member close.
  //   RED (the `--no-verify` tree, which hardened only the first two sites): open ok + group formed,
  //     then the last-member close returns `leg_capture_failed` — a live group that can never merge.
  //   GREEN: the checkpoint lands, the group co-opens, and the last-member close merges
  //     (`barrier: 'group_passed'`). NON-VACUOUS: an ordinary commit in this repo is proved to fail.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir, planPath } = makeMixedRepo({ keylessSigning: true });
    assert(ordinaryCommitRefused(repoRoot),
      '#802-D7-KEYLESS precondition: key-less `commit.gpgsign true` really does veto an ordinary commit');
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(r.result === 'ok' && !r.serialDegradeReason,
      '#802-D7-KEYLESS: signing config never halts NOR degrades the seam, got ' + JSON.stringify({ result: r.result, reason: r.reason, serialDegradeReason: r.serialDegradeReason }));
    assert(r.seamCheckpoint && JSON.stringify(r.seamCheckpoint.committed) === JSON.stringify(['src/serial_a.js']),
      '#802-D7-KEYLESS: the checkpoint landed, got ' + JSON.stringify(r.seamCheckpoint));
    assert(seamCommitCount(repoRoot) === 1 && r.laneGroup && r.laneGroup.members.length === 2,
      '#802-D7-KEYLESS: exactly one checkpoint commit and a formed lane group, got ' + JSON.stringify({ subjects: gitSubjects(repoRoot), laneGroup: r.laneGroup }));
    // THE N1 PIN: drive the group to its LAST-MEMBER CLOSE. This is the seam the `--no-verify` fix
    // wedged — `kw-leg` and `kw-synth` had no signing override, so the capture died here.
    const close = driveGroupToMerge(repoRoot, cacheDir);
    assert(close.result === 'ok' && close.barrier === 'group_passed',
      '#802-D7-KEYLESS: the last-member close MERGES over key-less signing, got ' + JSON.stringify(close));
    assert(close.reason !== 'leg_capture_failed',
      '#802-D7-KEYLESS: the close is not the leg-capture wedge, got ' + JSON.stringify(close.reason));
    assert(ledgerStatus(planPath, 'pA') === 'complete' && ledgerStatus(planPath, 'pB') === 'complete',
      '#802-D7-KEYLESS: both members completed');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #802-SEAM-POST-COMMIT-FENCE-DISCLOSES-HEAD — THE ONE HALT THAT IS NOT ZERO-MUTATION. Steps 1-3 of
  //   the repair halt before or without a landed commit; the step-4 RE-FENCE halts AFTER the checkpoint
  //   commit is already in history. Reporting that as a bare `seam_checkpoint_failed` told the caller
  //   "the operation refused" over a tree whose HEAD had moved — contradicting the design, the in-code
  //   contract, the ADR and the operator hint, all of which claimed zero mutation.
  //   Driven end-to-end through the REAL open-ready over a REAL repo. The concurrent writer is modelled
  //   by a `post-commit` hook (git ignores its exit status, so the checkpoint commit lands normally and
  //   only the RE-fence sees the new bytes) — the same shape as a real writer landing a file between
  //   the two fence spawns.
  //   RED (pre-fix): result refuse / seam_checkpoint_failed with NO `commit` field, while HEAD advanced
  //     and a kaola-checkpoint commit exists.
  //   GREEN: the refusal carries `commit` (= the new HEAD) and `committed` (the paths), and the operator
  //     hint says HEAD advanced and names the commit. Still a HALT: no lane group, no running set, the
  //     ledger untouched — and the concurrent writer's bytes are NOT destroyed (no auto-rollback).
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot, cacheDir, planPath } = makeMixedRepo({ postCommitWriter: true });
    const before = headSha(repoRoot);
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    const after = headSha(repoRoot);
    assert(r.result === 'refuse' && r.reason === 'seam_checkpoint_failed',
      '#802-POST-FENCE: the re-fence failure is the typed halt, got ' + JSON.stringify({ result: r.result, reason: r.reason, detail: r.detail }));
    assert(typeof r.detail === 'string' && r.detail.indexOf('post_commit_fence:') === 0,
      '#802-POST-FENCE: the halt names the POST-COMMIT fence (not a step-3 git failure), got ' + JSON.stringify(r.detail));
    // The fixture really did advance HEAD — without this the disclosure below would be untested.
    assert(after !== before && seamCommitCount(repoRoot) === 1,
      '#802-POST-FENCE precondition: the checkpoint commit LANDED and HEAD advanced, got ' + JSON.stringify({ before, after, subjects: gitSubjects(repoRoot) }));
    // THE PIN: the refusal discloses the mutation it left behind.
    assert(r.commit === after,
      '#802-POST-FENCE: the refusal carries the LANDED commit (the advanced HEAD), got ' + JSON.stringify({ commit: r.commit, head: after }));
    assert(Array.isArray(r.committed) && JSON.stringify(r.committed) === JSON.stringify(['src/serial_a.js']),
      '#802-POST-FENCE: the refusal names what went into that commit, got ' + JSON.stringify(r.committed));
    assert(typeof r.operator_hint === 'string' && /HEAD HAS ADVANCED/.test(r.operator_hint) && r.operator_hint.indexOf(after) !== -1,
      '#802-POST-FENCE: the operator hint says HEAD advanced and names the commit, got ' + JSON.stringify(r.operator_hint));
    // Still a HALT, and still no rollback: the concurrent writer's bytes survive.
    assert(!r.laneGroup && !readRS(cacheDir),
      '#802-POST-FENCE: no lane group and no running set — the frontier did NOT open, got ' + JSON.stringify({ laneGroup: r.laneGroup, rs: readRS(cacheDir) }));
    assert(ledgerStatus(planPath, 'pA') === 'pending' && ledgerStatus(planPath, 'pB') === 'pending',
      '#802-POST-FENCE: the ledger is untouched');
    assert(fs.existsSync(path.join(repoRoot, 'concurrent.js')),
      '#802-POST-FENCE: the concurrent writer\'s bytes were NOT auto-reset away — disclosure, not silent data loss');
    assert(G.exec(repoRoot, ['cat-file', '-p', after + ':src/serial_a.js'], { encoding: 'utf8' }).length > 0,
      '#802-POST-FENCE: the attributed serial path really is inside the disclosed commit');
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #802-SEAM-ATTRIBUTION-WRITE-CAPABLE — ATTRIBUTION IS A GATE ON A PRIMITIVE THAT COMMITS, so it
  //   enforces its OWN stated contract ("every dirty path must be vouched for by a CLOSED WRITE-CAPABLE
  //   row") instead of inheriting it from the freeze validator. Accepting any `complete` row with a
  //   non-empty declared set let a read-only role's stray declaration vouch for production bytes.
  //   RED (pre-fix): a `complete` code-reviewer row declaring src/reviewer-owned.js put that path in the
  //     attributed union, and runSeamCheckpoint reported committed:["src/reviewer-owned.js"].
  //   GREEN: the read-only row contributes nothing (not to the union, not to nodeIds), the write-capable
  //     sibling still does, and a dirty path vouched for only by the read-only row is a loud
  //     seam_checkpoint_unattributable halt.
  // -------------------------------------------------------------------------
  scenario(() => {
    const nodeMod = require('./kaola-workflow-adaptive-node.js');
    const planText = [
      '# Workflow Plan — test-project', '',
      '## Meta', 'labels: area:scripts', '',
      '## Nodes', '',
      '| id | role | depends_on | declared_write_set | cardinality | shape |',
      '| --- | --- | --- | --- | --- | --- |',
      '| rv   | code-reviewer | —  | src/reviewer-owned.js | 1 | sequence |',
      '| ex   | code-explorer | —  | src/explorer-owned.js | 1 | sequence |',
      '| impl | implementer   | rv | src/impl-owned.js     | 1 | sequence |',
      '| pA   | tdd-guide     | impl | par_a.js            | 1 | sequence |', '',
      '## Node Ledger', '', '| id | status |', '| --- | --- |',
      '| rv | complete |', '| ex | complete |', '| impl | complete |', '| pA | pending |', '',
    ].join('\n') + '\n';
    const a = nodeMod.seamCheckpointAttribution(planText, '/p/workflow-plan.md');
    assert(a.ok === true, '#802-WRITE-CAPABLE: attribution resolves, got ' + JSON.stringify(a));
    assert(!a.union.has('src/reviewer-owned.js') && !a.nodeIds.includes('rv'),
      '#802-WRITE-CAPABLE: a COMPLETE read-only (code-reviewer) row vouches for NOTHING, got ' + JSON.stringify({ union: [...a.union], nodeIds: a.nodeIds }));
    assert(!a.union.has('src/explorer-owned.js') && !a.nodeIds.includes('ex'),
      '#802-WRITE-CAPABLE: the same holds for a read-PRODUCER role, got ' + JSON.stringify({ union: [...a.union], nodeIds: a.nodeIds }));
    assert(a.union.has('src/impl-owned.js') && a.nodeIds.includes('impl'),
      '#802-WRITE-CAPABLE: a write-capable role\'s CLOSED row still attributes normally, got ' + JSON.stringify({ union: [...a.union], nodeIds: a.nodeIds }));
    // End-to-end: dirt vouched for ONLY by the read-only row is a loud halt, never a commit. The fence is
    // stubbed (the halt lands at step 2, before any git write) so this needs no repo.
    const fenceShell = () => ({ exitCode: 1, result: 'refuse', reason: 'parent_dirty', dirty: ['src/reviewer-owned.js'] });
    const out = nodeMod.runSeamCheckpoint('/p/workflow-plan.md', 'test-project', fenceShell, () => planText);
    assert(out.ok === false && out.reason === 'seam_checkpoint_unattributable',
      '#802-WRITE-CAPABLE: the repair refuses to vouch for a read-only row\'s declaration, got ' + JSON.stringify(out));
    assert(Array.isArray(out.unattributed) && out.unattributed.includes('src/reviewer-owned.js'),
      '#802-WRITE-CAPABLE: the halt names the path it would have wrongly committed, got ' + JSON.stringify(out.unattributed));
  });

  // -------------------------------------------------------------------------
  // #802-SEAM-WRITE-CAPABLE-ROLES-DRIFT — the write-capability list is a RESTATEMENT of the validator's
  //   own authoring rule ("a role outside WRITE_ROLES, other than the sink role, may not declare a write
  //   set"), because the validator does not export WRITE_ROLES. A restatement is only safe while it is
  //   mutation-proven, so this pin reads the validator's SOURCE and asserts set equality: adding a role
  //   to WRITE_ROLES without adding it here (or vice versa) turns this RED. It also asserts the anchors
  //   it reads still exist, so the pin can never pass vacuously by failing to find them.
  // -------------------------------------------------------------------------
  scenario(() => {
    const nodeMod = require('./kaola-workflow-adaptive-node.js');
    const src = fs.readFileSync(path.join(__dirname, 'kaola-workflow-plan-validator.js'), 'utf8');
    const m = src.match(/const WRITE_ROLES = new Set\(\[([^\]]*)\]\);/);
    assert(m, '#802-ROLES-DRIFT: the validator still declares `const WRITE_ROLES = new Set([...]);` — the anchor this pin reads');
    const tm = src.match(/const TERMINAL_ROLE = '([^']+)';/);
    assert(tm, '#802-ROLES-DRIFT: the validator still declares `const TERMINAL_ROLE = \'...\';` — the sink-role anchor');
    const rule = src.match(/if \(n\.role !== TERMINAL_ROLE && !WRITE_ROLES\.has\(n\.role\) && n\.writeSet\.size\)/);
    assert(rule, '#802-ROLES-DRIFT: the validator still refuses a write set on a role outside WRITE_ROLES ∪ {TERMINAL_ROLE} — the RULE this list restates');
    const expected = m[1].split(',').map(s => s.trim().replace(/^['"]|['"]$/g, '')).filter(Boolean)
      .concat([tm[1]]).sort();
    const actual = [...nodeMod.SEAM_WRITE_CAPABLE_ROLES].sort();
    assert(JSON.stringify(actual) === JSON.stringify(expected),
      '#802-ROLES-DRIFT: SEAM_WRITE_CAPABLE_ROLES equals the validator\'s WRITE_ROLES ∪ {TERMINAL_ROLE}, got ' + JSON.stringify({ actual, expected }));
  });

  // -------------------------------------------------------------------------
  // #802-LIVE-SCRATCH-GATES-FAIL-CLOSED — the drain-site READ precondition quantifies over every live
  //   MEMBER, not over the read subset. Filtering to kind:'read' and separately rejecting kind:'gate'
  //   made a live kind:'write' member INVISIBLE, so the predicate answered TRUE for a running set
  //   containing one — i.e. the checkpoint could have swept a LIVE writer's in-flight bytes into a
  //   commit attributed to CLOSED nodes. Unreachable behind the callers' earlier guards today, so this
  //   is the defensive floor the docstring promises, pinned on the predicate itself.
  //   RED (pre-fix): liveReadsAllScratchGates([{id:'g1',kind:'read'},{id:'w9',kind:'write'}], …) === true.
  //   GREEN: ANY non-read member ⇒ false; the all-scratch-reads control still ⇒ true.
  // -------------------------------------------------------------------------
  scenario(() => {
    const nodeMod = require('./kaola-workflow-adaptive-node.js');
    const plan = [
      '# Workflow Plan — test-project', '',
      '## Meta', 'labels: area:scripts', '',
      '## Nodes', '',
      '| id | role | depends_on | declared_write_set | cardinality | shape | observes |',
      '| --- | --- | --- | --- | --- | --- | --- |',
      '| g1 | adversarial-verifier | — | —          | 1 | sequence | scratch |',
      '| g2 | adversarial-verifier | — | —          | 1 | sequence | scratch |',
      '| gx | code-reviewer        | — | —          | 1 | sequence | —       |',
      '| w9 | doc-updater          | — | docs/x.md  | 1 | sequence | —       |', '',
      '## Node Ledger', '', '| id | status |', '| --- | --- |',
      '| g1 | in_progress |', '| g2 | in_progress |', '| gx | pending |', '| w9 | pending |', '',
    ].join('\n') + '\n';
    const rf = () => plan;
    const P = '/p/workflow-plan.md';
    // Control: every live member IS a scratch-observation read ⇒ the repair may be attempted.
    assert(nodeMod.liveReadsAllScratchGates([{ id: 'g1', kind: 'read' }, { id: 'g2', kind: 'read' }], P, rf) === true,
      '#802-SCRATCH-FAIL-CLOSED (control): an all-scratch-read running set still qualifies');
    // RED→GREEN: a live WRITE member is no longer invisible.
    assert(nodeMod.liveReadsAllScratchGates([{ id: 'g1', kind: 'read' }, { id: 'w9', kind: 'write' }], P, rf) === false,
      '#802-SCRATCH-FAIL-CLOSED: a live WRITE member fails the precondition closed');
    // The pre-existing gate rejection still holds, and now so does anything else.
    assert(nodeMod.liveReadsAllScratchGates([{ id: 'g1', kind: 'read' }, { id: 'gx', kind: 'gate' }], P, rf) === false,
      '#802-SCRATCH-FAIL-CLOSED: a live main-session gate still fails closed');
    assert(nodeMod.liveReadsAllScratchGates([{ id: 'g1', kind: 'read' }, { id: 'g2' }], P, rf) === false,
      '#802-SCRATCH-FAIL-CLOSED: a member with NO kind fails closed (unrecognized ⇒ not a read)');
    assert(nodeMod.liveReadsAllScratchGates([{ id: 'g1', kind: 'read' }, null], P, rf) === false,
      '#802-SCRATCH-FAIL-CLOSED: a malformed member fails closed');
    // A non-scratch read is still rejected (the role/annotation half of the predicate is untouched).
    assert(nodeMod.liveReadsAllScratchGates([{ id: 'gx', kind: 'read' }], P, rf) === false,
      '#802-SCRATCH-FAIL-CLOSED: an un-annotated read gate still fails the precondition');
    assert(nodeMod.liveReadsAllScratchGates([], P, rf) === false,
      '#802-SCRATCH-FAIL-CLOSED: an EMPTY running set is not a qualifying observer set');
  });

  // -------------------------------------------------------------------------
  // #616-PLAIN-SERIAL-DEGRADE (D-616-01) — the ORDINARY single-write serial degrade (unrelated to
  //   parent dirt: the explicit KAOLA_PARALLEL_WRITES=0 kill-switch short-circuits legCoupled to false
  //   BEFORE parentCarriesProductionDirt is ever invoked) must NOT be mislabeled parent_dirty. This is
  //   the negative-space companion to #616-SERIAL-DEGRADE-TELEMETRY above — proves the two serial-degrade
  //   causes stay distinguishable rather than collapsed onto one always-on field.
  //   RED (pre-fix): serialDegradeReason is simply absent everywhere (no such field exists yet), so this
  //     assertion is vacuously true pre-fix — it only becomes a meaningful guard AFTER the field is wired,
  //     which is why it is verified alongside (not instead of) the positive #616 case above.
  //   GREEN (post-fix): serialDegradeReason is present (positive case) XOR absent-or-non-parent_dirty here.
  // -------------------------------------------------------------------------
  scenario(() => {
    const { repoRoot } = makeLaneRepo();
    const r = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], SERIAL);
    assert(r.result === 'ok' && Array.isArray(r.opened) && r.opened.length === 1,
      '#616-PLAIN-SERIAL-DEGRADE: KAOLA_PARALLEL_WRITES=0 degrades to a single serial write, got ' + JSON.stringify(r));
    assert(r.serialDegradeReason !== 'parent_dirty',
      '#616-PLAIN-SERIAL-DEGRADE: an ordinary serial-write choice (clean parent, kill-switch forced) must NOT carry serialDegradeReason:"parent_dirty", got ' + JSON.stringify(r.serialDegradeReason));
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #622-MIXED-READ-COOPEN-AND-MERGE-FENCE (D-622-01) — a REAL end-to-end proof of BOTH #622 halves:
  //   (1) a READ becomes ready WHILE a leg-contained write lane_group is STILL LIVE (a non-last member
  //       already deferred; the last member has not closed yet) — open-ready must co-open the read
  //       instead of refusing write_node_exclusive (the bug: it blocked ALL reads while ANY lane-group
  //       member was live, forcing a two-wave [reads-then-writes] serialization).
  //   (2) the group's LAST-member merge must not race that live read — closeGroupMember refuses
  //       merge_awaits_read_drain (zero mutation, no merge attempted) until the read drains, THEN
  //       succeeds cleanly once it closes.
  // Plan: seed(complete) -> A,B (disjoint writes, depend on seed) -> probe (a NON-gate read,
  // code-explorer, depends on A ONLY — becomes ready as soon as A defers, while B, the LAST group
  // member, is still live) -> review (code-reviewer, depends on A,B,probe — satisfies the G1
  // post-dominance requirement without gating probe's early readiness) -> finalize.
  // -------------------------------------------------------------------------
  scenario(() => {
    function make622Repo() {
      const repoRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'd622-mixed-'));
      const project = 'test-project';
      const projDir = path.join(repoRoot, 'kaola-workflow', project);
      const cacheDir = path.join(projDir, '.cache');
      fs.mkdirSync(cacheDir, { recursive: true });
      const planPath = path.join(projDir, 'workflow-plan.md');
      const plan = [
        '# Workflow Plan — test-project', '',
        '## Meta', 'labels: area:scripts', 'sink: CHANGELOG.md', '',
        '## Nodes', '',
        '| id | role | depends_on | declared_write_set | cardinality | shape |',
        '| --- | --- | --- | --- | --- | --- |',
        '| seed     | code-explorer | —         | —          | 1 | sequence |',
        '| A        | tdd-guide     | seed      | ax622.js   | 1 | sequence |',
        '| B        | tdd-guide     | seed      | by622.js   | 1 | sequence |',
        '| probe    | code-explorer | A         | —          | 1 | sequence |',
        '| review   | code-reviewer | A,B,probe | —          | 1 | sequence |',
        '| finalize | finalize      | review    | —          | 1 | sequence |', '',
        '## Node Ledger', '',
        '| id | status |', '| --- | --- |',
        '| seed | complete |',
        '| A | pending |',
        '| B | pending |',
        '| probe | pending |',
        '| review | pending |',
        '| finalize | pending |', '',
      ].join('\n') + '\n';
      fs.writeFileSync(planPath, plan);
      fs.writeFileSync(path.join(projDir, 'workflow-state.md'), '# State\n');
      const g = (args) => execFileSync('git', ['-C', repoRoot, ...args], { encoding: 'utf8', stdio: ['ignore', 'ignore', 'ignore'] });
      g(['init']); g(['config', 'user.email', 'kw@test']); g(['config', 'user.name', 'kw']); g(['config', 'commit.gpgsign', 'false']);
      const froze = freezeLegacyFixture(execFileSync, 'node', VALIDATOR, planPath, { cwd: repoRoot, encoding: 'utf8' });
      assert(JSON.parse(froze.trim().split('\n').pop()).result !== 'refuse', '#622-MIXED: fixture must freeze, got ' + froze);
      fs.writeFileSync(path.join(repoRoot, '.gitignore'), '.kw/\n');
      g(['add', '-A']); g(['commit', '-m', 'init']);
      return { repoRoot, project, planPath, projDir, cacheDir };
    }

    const { repoRoot, cacheDir, planPath } = make622Repo();

    // Open {A,B} as a co-opened write lane group (no reads ready yet — probe depends on A, not seed).
    const open1 = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(open1.result === 'ok' && open1.laneGroup && open1.opened.length === 2,
      '#622-MIXED: {A,B} co-open as a write lane group, got ' + JSON.stringify(open1));
    const legA = open1.laneGroup.legs.A.legPath;
    const legB = open1.laneGroup.legs.B.legPath;
    fs.writeFileSync(path.join(legA, 'ax622.js'), '// A in-lane\n');
    fs.writeFileSync(path.join(legB, 'by622.js'), '// B in-lane\n');
    writeLegAwareEvidence(cacheDir, 'A', 'tdd-guide');
    writeLegAwareEvidence(cacheDir, 'B', 'tdd-guide');

    // Close A (non-last member) — defers to the group; A's ledger flips to complete, so `probe`
    // (depends on A) becomes ready WHILE B (the group's last member) is still live.
    const rA = runNode(repoRoot, ['close-node', '--project', 'test-project', '--node-id', 'A', '--json'], DEFAULT);
    assert(rA.result === 'ok' && rA.barrier === 'deferred_to_group', '#622-MIXED: A deferred ok, got ' + JSON.stringify(rA));
    assert(ledgerStatus(planPath, 'A') === 'complete' && ledgerStatus(planPath, 'B') === 'in_progress',
      '#622-MIXED: A complete, B still in_progress (the live group member)');

    // #622 (1): open-ready must co-open `probe` (a read) WHILE B is still a live lane-group member —
    // NOT refuse write_node_exclusive (the pre-#622 two-wave-forcing bug).
    const open2 = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(open2.result === 'ok' && open2.kind === 'read' && Array.isArray(open2.opened) && open2.opened.length === 1 && open2.opened[0].id === 'probe',
      '#622-MIXED: probe co-opens alongside the LIVE leg-contained write group B (not blocked by write_node_exclusive), got ' + JSON.stringify(open2));
    const expectedAPath = path.join(legA, 'kaola-workflow', 'test-project', '.cache', 'A.md');
    const upstreamA = open2.opened[0].dispatch && open2.opened[0].dispatch.upstream_evidence
      && open2.opened[0].dispatch.upstream_evidence.find(e => e.node_id === 'A');
    // The needle proves the read sees A's FULL written body, not the open-time stub. `red_baseline`
    // with a NON-EMPTY value is exactly that discriminator under test custody: the seed writes the
    // key with an empty value, so only the test author's own write can satisfy `\S`.
    assert(upstreamA && upstreamA.path === expectedAPath && /^red_baseline:[ \t]*\S/m.test(fs.readFileSync(upstreamA.path, 'utf8')),
      '#622-MIXED: dependent read points to A\'s full live leg evidence before group merge, got ' + JSON.stringify(upstreamA));
    assert(ledgerStatus(planPath, 'probe') === 'in_progress', '#622-MIXED: probe ledger flipped in_progress');
    const rsAfterProbeOpen = readRS(cacheDir);
    assert(rsAfterProbeOpen.lane_group && rsAfterProbeOpen.lane_group.group_id === open1.laneGroup.group_id,
      '#622-MIXED: the live write lane_group SURVIVES the read co-open, got ' + JSON.stringify(rsAfterProbeOpen.lane_group));
    assert(rsAfterProbeOpen.nodes.some(n => n.id === 'B') && rsAfterProbeOpen.nodes.some(n => n.id === 'probe'),
      '#622-MIXED: running-set carries BOTH the live write B and the newly-opened read probe, got ' + JSON.stringify(rsAfterProbeOpen.nodes.map(n => n.id)));

    // #622 (2) MERGE FENCE: closing B (the LAST member) WHILE probe is STILL live must be HELD — refuse
    // merge_awaits_read_drain, zero mutation (no merge attempted, B stays in_progress, lane_group intact).
    const headBeforeFence = gitOut(repoRoot, ['rev-parse', 'HEAD']);
    const rB1 = runNode(repoRoot, ['close-node', '--project', 'test-project', '--node-id', 'B', '--json'], DEFAULT);
    assert(rB1.result === 'refuse' && rB1.reason === 'merge_awaits_read_drain',
      '#622-MIXED: B\'s last-member merge is HELD while probe is live (merge_awaits_read_drain), got ' + JSON.stringify(rB1));
    assert(Array.isArray(rB1.liveReads) && rB1.liveReads.includes('probe'),
      '#622-MIXED: the refusal names the live read(s) holding the merge, got ' + JSON.stringify(rB1.liveReads));
    assert(ledgerStatus(planPath, 'B') === 'in_progress', '#622-MIXED: B ledger UNCHANGED (still in_progress) after the held merge attempt');
    assert(gitOut(repoRoot, ['rev-parse', 'HEAD']) === headBeforeFence, '#622-MIXED: HEAD unchanged — NO merge was attempted while the read was live');
    const rsAfterFence = readRS(cacheDir);
    assert(rsAfterFence.lane_group && rsAfterFence.lane_group.group_id === open1.laneGroup.group_id,
      '#622-MIXED: lane_group untouched by the held merge attempt, got ' + JSON.stringify(rsAfterFence.lane_group));

    // Close probe (the live read drains) — then the retried B close must succeed cleanly.
    const probeNonce = (() => { try { return fs.readFileSync(path.join(cacheDir, 'barrier-base-probe'), 'utf8').trim().slice(0, 12); } catch (_) { return ''; } })();
    fs.writeFileSync(path.join(cacheDir, 'probe.md'), 'evidence-binding: probe ' + probeNonce + '\nfindings: consumed A live-leg evidence\n');
    const rProbe = runNode(repoRoot, ['close-node', '--project', 'test-project', '--node-id', 'probe', '--json'], DEFAULT);
    assert(rProbe.result === 'ok', '#622-MIXED: probe closes ok once done, got ' + JSON.stringify(rProbe));
    assert(ledgerStatus(planPath, 'probe') === 'complete', '#622-MIXED: probe ledger complete');

    const rB2 = runNode(repoRoot, ['close-node', '--project', 'test-project', '--node-id', 'B', '--json'], DEFAULT);
    assert(rB2.result === 'ok' && rB2.barrier === 'group_passed' && rB2.synthesized === true,
      '#622-MIXED: once probe drains, B\'s retried close-node merges cleanly (group_passed), got ' + JSON.stringify(rB2));
    const headTree = G.exec(repoRoot, ['ls-tree', '-r', '--name-only', 'HEAD'], { encoding: 'utf8' });
    assert(headTree.includes('ax622.js') && headTree.includes('by622.js'), '#622-MIXED: both in-lane files reach HEAD after the drained merge, got ' + JSON.stringify(headTree.split('\n').filter(Boolean)));
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // #633-SELF-WRITTEN-LEG-EVIDENCE-MERGE (D-622-01) — the lane-group synthesizer octopus-merge
  // collision: BOTH members self-write REAL (non-empty) evidence INSIDE their own leg — mirroring the
  // TRUE field mechanism (commands/kaola-workflow-plan-run.md's evidence-persistence contract: a
  // write-role agent SELF-WRITES its `.cache` evidence via its dispatch's absolute `leg_path`, never
  // synced back to the parent). Before the #633 fix, the parent's `seedEvidenceFile` stub is an
  // UNTRACKED plain-fs write while each leg's real content is freshly committed on its OWN branch —
  // the last-member octopus merge then refuses "Untracked working tree file … would be overwritten by
  // merge" (a structural collision, not a real content conflict). After the fix (the stub is committed
  // TRACKED on the parent BEFORE the legs branch off, and the close-side evidence read prefers each
  // leg's own copy), the last-member close reaches barrier:'group_passed' with NO manual intervention.
  // -------------------------------------------------------------------------
  scenario(() => {
    function selfWriteEvidenceInLeg(legPath, cacheDir, id) {
      const legCacheDir = path.join(legPath, 'kaola-workflow', 'test-project', '.cache');
      fs.mkdirSync(legCacheDir, { recursive: true });
      let nonce = '';
      try { nonce = fs.readFileSync(path.join(cacheDir, 'barrier-base-' + id), 'utf8').trim().slice(0, 12); } catch (_) {}
      fs.writeFileSync(path.join(legCacheDir, id + '.md'),
        'evidence-binding: ' + id + ' ' + nonce + '\nRED: test_' + id + ' — AssertionError: expected throw (pre-impl)\nred_baseline: ' + nonce + '\n');
    }

    const { repoRoot, cacheDir, planPath } = makeLaneRepo();
    const open = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(open.result === 'ok' && open.laneGroup, '#633: setup co-open ok, got ' + JSON.stringify(open));
    const legA = open.laneGroup.legs.A.legPath;
    const legB = open.laneGroup.legs.B.legPath;

    // BOTH members self-write REAL evidence INSIDE their own leg (never at the parent).
    selfWriteEvidenceInLeg(legA, cacheDir, 'A');
    selfWriteEvidenceInLeg(legB, cacheDir, 'B');
    fs.writeFileSync(path.join(legA, 'ax.js'), '// A in-lane\n');
    fs.writeFileSync(path.join(legB, 'by.js'), '// B in-lane\n');

    // A declared leg never falls back to the parent artifact. Even a valid parent decoy must not
    // hide a missing leg file from --verify.
    const legBFile = path.join(legB, 'kaola-workflow', 'test-project', '.cache', 'B.md');
    const parentBFile = path.join(cacheDir, 'B.md');
    const legBContent = fs.readFileSync(legBFile, 'utf8');
    const parentBContent = fs.readFileSync(parentBFile, 'utf8');
    fs.unlinkSync(legBFile);
    fs.writeFileSync(parentBFile, legBContent);
    const missingLeg = runNode(repoRoot, ['record-evidence', '--project', 'test-project', '--node-id', 'B', '--verify', '--json'], DEFAULT);
    assert(missingLeg.result === 'refuse' && missingLeg.reason === 'evidence_absent'
      && missingLeg.evidence_source === 'leg',
    '#633: a missing declared leg artifact refuses instead of falling back to valid parent evidence, got ' + JSON.stringify(missingLeg));
    fs.writeFileSync(parentBFile, parentBContent);
    fs.writeFileSync(legBFile, legBContent);

    // The mandatory pre-close verification must resolve the same leg copy as close-node. The parent
    // copies remain hollow tracked stubs and would fail under the strict seed-only wall above.
    const vA = runNode(repoRoot, ['record-evidence', '--project', 'test-project', '--node-id', 'A', '--verify', '--json'], DEFAULT);
    const vB = runNode(repoRoot, ['record-evidence', '--project', 'test-project', '--node-id', 'B', '--verify', '--json'], DEFAULT);
    assert(vA.result === 'ok' && vA.evidence_source === 'leg'
      && vB.result === 'ok' && vB.evidence_source === 'leg',
    '#633: record-evidence --verify prefers each member leg copy, got A=' + JSON.stringify(vA) + ' B=' + JSON.stringify(vB));

    // The parent's `.cache/A.md` / `.cache/B.md` are NEVER written by this test — they stay whatever
    // open-ready's #633 fix left them (the TRACKED stub, untouched). The evidence-shape check for BOTH
    // closes must read each member's OWN leg copy instead.
    const rA = runNode(repoRoot, ['close-node', '--project', 'test-project', '--node-id', 'A', '--json'], DEFAULT);
    assert(rA.result === 'ok' && rA.barrier === 'deferred_to_group',
      '#633: A deferred ok reading its OWN leg-resident evidence (parent copy never touched), got ' + JSON.stringify(rA));

    const rB = runNode(repoRoot, ['close-node', '--project', 'test-project', '--node-id', 'B', '--json'], DEFAULT);
    assert(rB.result === 'ok' && rB.barrier === 'group_passed' && rB.synthesized === true,
      '#633: last-member close reaches group_passed with NO manual intervention (the untracked-vs-tracked evidence-file merge collision does not resurface), got ' + JSON.stringify(rB));
    assert(ledgerStatus(planPath, 'A') === 'complete' && ledgerStatus(planPath, 'B') === 'complete',
      '#633: both A and B ledger complete');
    const headTree = G.exec(repoRoot, ['ls-tree', '-r', '--name-only', 'HEAD'], { encoding: 'utf8' }).split('\n').filter(Boolean);
    assert(headTree.includes('ax.js') && headTree.includes('by.js'), '#633: both in-lane files reach HEAD after the merge, got ' + JSON.stringify(headTree));
    const wts = worktreePaths(repoRoot);
    assert(!wts.some(p => p.indexOf(path.join('.kw', 'legs')) !== -1), '#633: leg worktrees torn down on clean completion, got ' + JSON.stringify(wts));
    cleanup(repoRoot);
  });

  // -------------------------------------------------------------------------
  // R4-REGRESSION (adversarial-verifier finding, repair pass on the #622 fix) — the #622 relaxation
  // (a read co-opens alongside a still-live LEG-CONTAINED write lane group) interacts badly with the
  // PRE-EXISTING #596 speculative-write fallback. Sequence:
  //   1. {A,B} co-open as a write lane group.
  //   2. A closes (defers to the group) → gateR (a code-reviewer gate depending on A alone) co-opens
  //      as a READ alongside the still-live group member B (the #622 relaxation working as intended).
  //   3. On the NEXT open-ready tick the normal frontier is empty (gateR still open), but W2 — a write
  //      node whose ONLY unsatisfied dependency is the open gateR — is speculativePending. Pre-fix, the
  //      #596 speculative-write fallback fires for W2 WHILE B is still live: W2 forms its OWN size-1
  //      speculative lane group, and the running-set write-descriptor assignment (groupForm truthy)
  //      UNCONDITIONALLY REPLACES the live lane_group descriptor — losing B's membership entirely.
  //      When B (now orphaned from any lane_group) later tries to close, it can no longer be recognized
  //      as a group member, falls through to the serial close path, and its committed in-lane leg work
  //      never reaches HEAD (silently lost) while the leg worktree leaks.
  // Fixed behavior asserted here: a speculative write candidate is EXCLUDED (reason: 'lane_group_live')
  // whenever a write lane_group is ALREADY live — the running-set's single lane_group descriptor is
  // never overwritten out from under a still-open member. W2 simply waits; once gateR later resolves
  // (verdict: pass) and B's group drains and merges normally, W2 opens through the ordinary (non-
  // speculative) path, proving the fix costs no real parallelism — only the racy overwrite is removed.
  // -------------------------------------------------------------------------
  scenario(() => {
    function makeR4Repo() {
      const repoRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'd622-r4-'));
      const project = 'test-project';
      const projDir = path.join(repoRoot, 'kaola-workflow', project);
      const cacheDir = path.join(projDir, '.cache');
      fs.mkdirSync(cacheDir, { recursive: true });
      const planPath = path.join(projDir, 'workflow-plan.md');
      const plan = [
        '# Workflow Plan — test-project', '',
        '## Meta', 'labels: area:scripts', 'sink: CHANGELOG.md', 'speculative_open_policy: auto', '',
        '## Nodes', '',
        '| id | role | depends_on | declared_write_set | cardinality | shape |',
        '| --- | --- | --- | --- | --- | --- |',
        '| seed     | code-explorer | —      | —          | 1 | sequence |',
        '| A        | tdd-guide     | seed   | ar4.js     | 1 | sequence |',
        '| B        | tdd-guide     | seed   | br4.js     | 1 | sequence |',
        '| gateR    | code-reviewer | A      | —          | 1 | sequence |',
        '| W2       | tdd-guide     | gateR  | cr4.js     | 1 | sequence |',
        '| review   | code-reviewer | B,W2   | —          | 1 | sequence |',
        '| finalize | finalize      | review | —          | 1 | sequence |', '',
        '## Node Ledger', '',
        '| id | status |', '| --- | --- |',
        '| seed | complete |',
        '| A | pending |',
        '| B | pending |',
        '| gateR | pending |',
        '| W2 | pending |',
        '| review | pending |',
        '| finalize | pending |', '',
      ].join('\n') + '\n';
      fs.writeFileSync(planPath, plan);
      fs.writeFileSync(path.join(projDir, 'workflow-state.md'), '# State\n');
      const g = (args) => execFileSync('git', ['-C', repoRoot, ...args], { encoding: 'utf8', stdio: ['ignore', 'ignore', 'ignore'] });
      g(['init']); g(['config', 'user.email', 'kw@test']); g(['config', 'user.name', 'kw']); g(['config', 'commit.gpgsign', 'false']);
      const froze = freezeLegacyFixture(execFileSync, 'node', VALIDATOR, planPath, { cwd: repoRoot, encoding: 'utf8' });
      assert(JSON.parse(froze.trim().split('\n').pop()).result !== 'refuse', 'R4-REGRESSION: fixture must freeze, got ' + froze);
      fs.writeFileSync(path.join(repoRoot, '.gitignore'), '.kw/\n');
      g(['add', '-A']); g(['commit', '-m', 'init']);
      return { repoRoot, project, planPath, projDir, cacheDir };
    }

    const { repoRoot, planPath, cacheDir } = makeR4Repo();

    // (1) {A,B} co-open as a write lane group.
    const open1 = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(open1.result === 'ok' && open1.laneGroup && open1.opened.length === 2,
      'R4-REGRESSION: {A,B} co-open as a write lane group, got ' + JSON.stringify(open1));
    const originalGroupId = open1.laneGroup.group_id;
    const legA = open1.laneGroup.legs.A.legPath;
    const legB = open1.laneGroup.legs.B.legPath;
    fs.writeFileSync(path.join(legA, 'ar4.js'), '// A in-lane\n');
    fs.writeFileSync(path.join(legB, 'br4.js'), '// B in-lane\n');
    writeEvidence(cacheDir, 'A');
    writeEvidence(cacheDir, 'B');

    // Close A (non-last member) — defers to the group; gateR (depends on A only) becomes ready while
    // B (the group's last member) is still live.
    const rA = runNode(repoRoot, ['close-node', '--project', 'test-project', '--node-id', 'A', '--json'], DEFAULT);
    assert(rA.result === 'ok' && rA.barrier === 'deferred_to_group', 'R4-REGRESSION: A deferred ok, got ' + JSON.stringify(rA));
    assert(ledgerStatus(planPath, 'A') === 'complete' && ledgerStatus(planPath, 'B') === 'in_progress',
      'R4-REGRESSION: A complete, B still in_progress (the live group member)');

    // (2) gateR co-opens as a READ alongside the still-live write lane group (the #622 relaxation).
    const open2 = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(open2.result === 'ok' && open2.kind === 'read' && open2.opened.length === 1 && open2.opened[0].id === 'gateR',
      'R4-REGRESSION: gateR co-opens alongside the LIVE leg-contained write group B, got ' + JSON.stringify(open2));
    assert(ledgerStatus(planPath, 'gateR') === 'in_progress', 'R4-REGRESSION: gateR ledger flipped in_progress');
    const rsAfterGateOpen = readRS(cacheDir);
    assert(rsAfterGateOpen.lane_group && rsAfterGateOpen.lane_group.group_id === originalGroupId,
      'R4-REGRESSION: the live write lane_group survives the read co-open, got ' + JSON.stringify(rsAfterGateOpen.lane_group));

    // (3) THE REGRESSION TICK: normal frontier is empty (gateR still open blocks W2 normally, B is
    // in_progress not pending, review depends on B+W2 both incomplete) — but W2's ONLY unsatisfied dep
    // is the open gateR, so it is speculativePending. This must NOT be allowed to open and overwrite the
    // still-live {A,B} lane_group descriptor.
    const open3 = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(open3.result === 'ok' && (open3.opened || []).length === 0,
      'R4-REGRESSION: W2 must NOT speculative-open while B\'s write lane group is still live, got ' + JSON.stringify(open3));
    assert(open3.speculativeWriteExcluded && open3.speculativeWriteExcluded.reason === 'lane_group_live'
      && (open3.speculativeWriteExcluded.nodeIds || []).includes('W2'),
      'R4-REGRESSION: W2 is excluded with reason lane_group_live, got ' + JSON.stringify(open3.speculativeWriteExcluded));
    assert(ledgerStatus(planPath, 'W2') === 'pending', 'R4-REGRESSION: W2 ledger row untouched (still pending)');
    const rsAfterSpecAttempt = readRS(cacheDir);
    assert(rsAfterSpecAttempt.lane_group && rsAfterSpecAttempt.lane_group.group_id === originalGroupId,
      'R4-REGRESSION: the ORIGINAL live lane_group survives untouched — must NOT be overwritten by a new speculative group, got ' + JSON.stringify(rsAfterSpecAttempt.lane_group));
    assert(Array.isArray(rsAfterSpecAttempt.lane_group.members) && rsAfterSpecAttempt.lane_group.members.includes('B'),
      'R4-REGRESSION: B is still tracked as a lane_group member, got ' + JSON.stringify(rsAfterSpecAttempt.lane_group));
    assert(!(rsAfterSpecAttempt.nodes || []).some(n => n.id === 'W2'),
      'R4-REGRESSION: W2 never entered the running set, got ' + JSON.stringify((rsAfterSpecAttempt.nodes || []).map(n => n.id)));

    // Recovery proof: B's last-member merge is held while gateR (a read) is live (the #622 merge fence,
    // unaffected by this fix) — then, once gateR resolves and B drains/merges normally, W2 opens through
    // the ORDINARY (non-speculative) path. The fix costs no real parallelism; it only removes the race.
    const rB1 = runNode(repoRoot, ['close-node', '--project', 'test-project', '--node-id', 'B', '--json'], DEFAULT);
    assert(rB1.result === 'refuse' && rB1.reason === 'merge_awaits_read_drain',
      'R4-REGRESSION: B\'s last-member merge is HELD while gateR is live, got ' + JSON.stringify(rB1));

    let gateNonce = '';
    try { gateNonce = fs.readFileSync(path.join(cacheDir, 'barrier-base-gateR'), 'utf8').trim().slice(0, 12); } catch (_) {}
    fs.writeFileSync(path.join(cacheDir, 'gateR.md'), 'evidence-binding: gateR ' + gateNonce + '\nverdict: pass\nfindings_blocking: 0\n');
    const rGate = runNode(repoRoot, ['close-node', '--project', 'test-project', '--node-id', 'gateR', '--json'], DEFAULT);
    assert(rGate.result === 'ok', 'R4-REGRESSION: gateR closes ok once evidenced, got ' + JSON.stringify(rGate));
    assert(ledgerStatus(planPath, 'gateR') === 'complete', 'R4-REGRESSION: gateR ledger complete');

    const rB2 = runNode(repoRoot, ['close-node', '--project', 'test-project', '--node-id', 'B', '--json'], DEFAULT);
    assert(rB2.result === 'ok' && rB2.barrier === 'group_passed' && rB2.synthesized === true,
      'R4-REGRESSION: once gateR drains, B\'s retried close-node merges cleanly (group_passed), got ' + JSON.stringify(rB2));
    const headTree = G.exec(repoRoot, ['ls-tree', '-r', '--name-only', 'HEAD'], { encoding: 'utf8' }).split('\n').filter(Boolean);
    assert(headTree.includes('ar4.js') && headTree.includes('br4.js'),
      'R4-REGRESSION: both A and B in-lane files reach HEAD after the drained merge, got ' + JSON.stringify(headTree));
    const wts = worktreePaths(repoRoot);
    assert(!wts.some(p => p.indexOf(path.join('.kw', 'legs')) !== -1), 'R4-REGRESSION: A/B leg worktrees torn down on clean completion, got ' + JSON.stringify(wts));

    // W2 is now normally ready (gateR complete, no longer speculative) — it opens through the ordinary
    // path, proving the fix cost no reachable parallelism.
    const open4 = runNode(repoRoot, ['open-ready', '--project', 'test-project', '--json'], DEFAULT);
    assert(open4.result === 'ok' && (open4.opened || []).length === 1 && open4.opened[0].id === 'W2' && open4.kind === 'write',
      'R4-REGRESSION: W2 opens normally (non-speculatively) once gateR is complete, got ' + JSON.stringify(open4));

    cleanup(repoRoot);
  });
}

// ---------------------------------------------------------------------------
// #434 Fixture (a) — revert-overflow: runRevertOverflow clears outOfAllow paths.
// RED: fails because runRevertOverflow is not yet exported.
// ---------------------------------------------------------------------------
scenario(() => {
  const planNodes = [
    '| impl | implementer | — | scripts/a.js | 1 | sequence |',
    '| review | code-reviewer | impl | — | 1 | sequence |',
    '| finalize | finalize | review | — | 1 | sequence |',
  ];
  let planContent = makePlan([
    '| impl | in_progress | |',
    '| review | pending | |',
    '| finalize | pending | |',
  ], planNodes);

  // Barrier check: impl overflowed — wrote scripts/b.js (not in write set).
  // Fake a barrier result: pass on second call (after revert), fail on first.
  let barrierCallCount = 0;
  const reverted = [];
  const provenanceEntries = [];

  const result = runRevertOverflow({
    planPath: '/fake/kaola-workflow/test-project/workflow-plan.md',
    project: 'test-project',
    nodeId: 'impl',
    // Shell seam: --barrier-check returns the overflow first, then passes after revert.
    // #546 G10: commit-node's combineResults NESTS outOfAllow under barrierCheck — use that
    // REALISTIC shape (not a top-level outOfAllow) so the test exercises the production path that
    // a top-level-only read would mask as a false "barrier already clean".
    shell: (scriptPath, args) => {
      const base = path.basename(scriptPath);
      if (base === 'kaola-workflow-commit-node.js') {
        // Simulate barrier-check: first call overflowed, second call passes after revert.
        barrierCallCount++;
        if (barrierCallCount === 1) {
          return { exitCode: 1, result: 'refuse', barrierCheck: { reason: 'write_set_overflow', outOfAllow: ['scripts/b.js'] } };
        }
        return { exitCode: 0, result: 'pass', barrierCheck: { reason: null, outOfAllow: [] } };
      }
      return { exitCode: 0, result: 'pass', barrierCheck: { reason: null, outOfAllow: [] } };
    },
    // gitCheckout seam: records reverted paths.
    gitCheckout: (barrierRoot, sha, filePaths) => {
      for (const p of filePaths) reverted.push(p);
      return { exitCode: 0 };
    },
    // Batch 0: the partition probe. This fixture's overflow file EXISTS at the baseline, so the
    // whole set routes to checkout — the original #434-a narrative, now stated rather than assumed.
    presentAtBase: (barrierRoot, sha, filePaths) => filePaths.slice(),
    readFile: (f) => {
      if (f.endsWith('workflow-plan.md')) return planContent;
      if (f.endsWith('barrier-base-impl')) return 'deadbeef1234567890ab\n';
      throw new Error('ENOENT ' + f);
    },
    writeFile: (f, c) => { if (f.endsWith('workflow-plan.md')) planContent = c; },
    cacheExists: (f) => f.endsWith('barrier-base-impl'),
    appendLog: (entry) => provenanceEntries.push(entry),
  });

  assert(result !== undefined, '#434-a RED: runRevertOverflow exported (would be undefined/throw if missing)');
  assert(result && result.result === 'ok', '#434-a: revert-overflow returns ok, got ' + JSON.stringify(result));
  assert(reverted.includes('scripts/b.js'), '#434-a: outOfAllow path scripts/b.js reverted');
  assert(result.revertedPaths && result.revertedPaths.includes('scripts/b.js'),
    '#434-a: result.revertedPaths includes scripts/b.js, got ' + JSON.stringify(result));
  assert(result.barrierClearedAfterRevert === true,
    '#434-a: barrierClearedAfterRevert true after revert, got ' + JSON.stringify(result));
  assert(JSON.stringify(result.checkedOutPaths) === JSON.stringify(['scripts/b.js'])
    && JSON.stringify(result.deletedPaths) === JSON.stringify([]),
    '#434-a: a baseline-tracked overflow is reported as checked out, with an empty delete set, got ' + JSON.stringify(result));
});

// ---------------------------------------------------------------------------
// BATCH 0 — revert-overflow partitions outOfAllow against the baseline tree.
//
// THE DEFECT THIS CLOSES. `git checkout <baseSha> -- <path>` cannot restore a path that did not
// exist at baseSha, and every overflow path travelled in ONE invocation, so a single newly-created
// undeclared file made the WHOLE revert refuse `git_checkout_failed` — including the siblings that
// would have reverted cleanly. Newly-created files are the DOMINANT overflow class since test writes
// became attributable, so the discard primitive failed on exactly the case it is most reached for,
// and the `unattributed_paths` route dead-ended where it is most reached.
//
// WHAT IS PINNED, in both directions: the mixed GREEN arc (some restored, some deleted, both sets
// reported separately); the pure-delete arc that used to be a hard refusal; the fail-CLOSED probe
// (an unreadable baseline tree must never be guessed past, because guessing "absent" DELETES a file
// the baseline still holds); and the ordering guarantee that a failed restore deletes nothing.
// ---------------------------------------------------------------------------
scenario(() => {
  const planNodes = [
    '| impl | implementer | — | scripts/a.js | 1 | sequence |',
    '| review | code-reviewer | impl | — | 1 | sequence |',
    '| finalize | finalize | review | — | 1 | sequence |',
  ];
  const basePlan = () => makePlan([
    '| impl | in_progress | |',
    '| review | pending | |',
    '| finalize | pending | |',
  ], planNodes);

  // A driver that runs runRevertOverflow over a declared overflow set with declared baseline
  // membership, capturing exactly which primitive each path was handed to.
  const drive = (overflow, presentAtBase, over) => {
    let planContent = basePlan();
    const checkedOut = [];
    const removed = [];
    let barrierCalls = 0;
    const opts = Object.assign({
      planPath: '/fake/kaola-workflow/test-project/workflow-plan.md',
      project: 'test-project',
      nodeId: 'impl',
      shell: (scriptPath, args) => {
        if (path.basename(scriptPath) === 'kaola-workflow-commit-node.js') {
          barrierCalls++;
          if (barrierCalls === 1) {
            return { exitCode: 1, result: 'refuse', barrierCheck: { reason: 'write_set_overflow', outOfAllow: overflow.slice() } };
          }
          return { exitCode: 0, result: 'pass', barrierCheck: { reason: null, outOfAllow: [] } };
        }
        return { exitCode: 0, result: 'pass' };
      },
      gitCheckout: (root, sha, filePaths) => { checkedOut.push(...filePaths); return { exitCode: 0 }; },
      presentAtBase: () => presentAtBase.slice(),
      removePaths: (root, filePaths) => { removed.push(...filePaths); return { exitCode: 0, removed: filePaths.slice() }; },
      readFile: (f) => {
        if (f.endsWith('workflow-plan.md')) return planContent;
        if (f.endsWith('barrier-base-impl')) return 'deadbeef1234567890ab\n';
        throw new Error('ENOENT ' + f);
      },
      writeFile: (f, c) => { if (f.endsWith('workflow-plan.md')) planContent = c; },
      cacheExists: (f) => f.endsWith('barrier-base-impl'),
      appendLog: () => {},
    }, over || {});
    return { result: runRevertOverflow(opts), checkedOut, removed };
  };

  // (a) MIXED — one pre-existing file, one newly created. Pre-Batch-0 this refused outright.
  {
    const { result, checkedOut, removed } = drive(
      ['scripts/b.js', 'scripts/new.js'], ['scripts/b.js']);
    assert(result.result === 'ok',
      'BATCH0-REVERT-a: a mixed overflow (one tracked, one new) succeeds instead of refusing, got ' + JSON.stringify(result));
    assert(JSON.stringify(checkedOut) === JSON.stringify(['scripts/b.js']),
      'BATCH0-REVERT-a: ONLY the baseline-tracked path is handed to git checkout, got ' + JSON.stringify(checkedOut));
    assert(JSON.stringify(removed) === JSON.stringify(['scripts/new.js']),
      'BATCH0-REVERT-a: ONLY the newly-created path is handed to the delete primitive, got ' + JSON.stringify(removed));
    assert(JSON.stringify(result.checkedOutPaths) === JSON.stringify(['scripts/b.js'])
      && JSON.stringify(result.deletedPaths) === JSON.stringify(['scripts/new.js']),
      'BATCH0-REVERT-a: the two sets are REPORTED separately (restore is reversible, delete is not), got ' + JSON.stringify(result));
    assert(JSON.stringify(result.revertedPaths) === JSON.stringify(['scripts/b.js', 'scripts/new.js']),
      'BATCH0-REVERT-a: revertedPaths stays the union in outOfAllow order (existing consumers unbroken), got ' + JSON.stringify(result));
  }

  // (b) PURE DELETE — the dominant overflow class, and the exact case that used to dead-end.
  {
    const { result, checkedOut, removed } = drive(['scripts/new1.js', 'scripts/new2.js'], []);
    assert(result.result === 'ok',
      'BATCH0-REVERT-b: an all-newly-created overflow succeeds (the dead-end this batch removes), got ' + JSON.stringify(result));
    assert(checkedOut.length === 0,
      'BATCH0-REVERT-b: git checkout is not invoked at all when nothing pre-existed, got ' + JSON.stringify(checkedOut));
    assert(JSON.stringify(removed) === JSON.stringify(['scripts/new1.js', 'scripts/new2.js']),
      'BATCH0-REVERT-b: both new files are deleted, got ' + JSON.stringify(removed));
    assert(result.barrierClearedAfterRevert === true,
      'BATCH0-REVERT-b: the re-run barrier confirms the overflow cleared, got ' + JSON.stringify(result));
  }

  // (c) FAIL-CLOSED probe — an unreadable baseline tree refuses and touches NOTHING. Guessing
  //     "absent" here would delete a file the baseline still holds.
  {
    const { result, checkedOut, removed } = drive(['scripts/b.js'], [], {
      presentAtBase: () => { throw new Error('fatal: not a valid object name deadbeef'); },
    });
    assert(result.result === 'refuse' && result.reason === 'baseline_partition_unavailable',
      'BATCH0-REVERT-c: an unreadable baseline tree refuses baseline_partition_unavailable, got ' + JSON.stringify(result));
    assert(checkedOut.length === 0 && removed.length === 0,
      'BATCH0-REVERT-c: nothing is restored and nothing is deleted on the fail-closed probe');
    assert(getOperatorHint('baseline_partition_unavailable', result).length > 0,
      'BATCH0-REVERT-c: the new refusal carries an operator hint');
  }

  // (d) ORDER — a failed restore must delete NOTHING. The destructive half runs only after the
  //     reversible half has landed, so a half-applied revert can never destroy unrecoverable bytes.
  {
    const { result, checkedOut, removed } = drive(['scripts/b.js', 'scripts/new.js'], ['scripts/b.js'], {
      gitCheckout: () => ({ exitCode: 1 }),
    });
    assert(result.result === 'refuse' && result.reason === 'git_checkout_failed',
      'BATCH0-REVERT-d: a failed restore still refuses git_checkout_failed, got ' + JSON.stringify(result));
    assert(removed.length === 0,
      'BATCH0-REVERT-d: NOTHING was deleted when the restore half failed, got ' + JSON.stringify(removed));
    assert(JSON.stringify(result.deletedPaths) === JSON.stringify([]),
      'BATCH0-REVERT-d: the refusal reports an empty delete set, got ' + JSON.stringify(result));
    assert(checkedOut.length === 0, 'BATCH0-REVERT-d: the failing seam recorded no successful restore');
  }

  // (e) A FAILED DELETE is its own typed refusal, and reports what it did manage to remove.
  {
    const { result } = drive(['scripts/new1.js', 'scripts/new2.js'], [], {
      removePaths: () => ({ exitCode: 1, removed: ['scripts/new1.js'], detail: 'EACCES' }),
    });
    assert(result.result === 'refuse' && result.reason === 'overflow_delete_failed',
      'BATCH0-REVERT-e: a failed delete refuses overflow_delete_failed, got ' + JSON.stringify(result));
    assert(JSON.stringify(result.deletedPaths) === JSON.stringify(['scripts/new1.js']),
      'BATCH0-REVERT-e: the refusal reports the partial removal so the operator knows the real state, got ' + JSON.stringify(result));
  }
});

// ---------------------------------------------------------------------------
// BATCH 0 — the two DEFAULT primitives, against a REAL git repository.
//
// The seam-driven scenarios above prove the partition LOGIC. They cannot prove the primitives the
// production path actually uses, because they replace them. A partition whose probe misreports
// membership deletes files the baseline still holds, so the defaults are exercised directly here.
// ---------------------------------------------------------------------------
scenario(() => {
  const repoRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-batch0-partition-'));
  try {
    const g = (args) => execFixtureFileSync('git', ['-C', repoRoot, ...args],
      { encoding: 'utf8', stdio: ['ignore', 'pipe', 'pipe'] });
    g(['init']); g(['config', 'user.email', 'kw@test']); g(['config', 'user.name', 'kw']);
    g(['config', 'commit.gpgsign', 'false']);
    fs.mkdirSync(path.join(repoRoot, 'scripts'), { recursive: true });
    fs.writeFileSync(path.join(repoRoot, 'scripts', 'tracked.js'), 'module.exports = 1;\n');
    fs.writeFileSync(path.join(repoRoot, 'scripts', 'with space.js'), 'module.exports = 2;\n');
    g(['add', '-A']); g(['commit', '-m', 'init']);
    const baseSha = g(['rev-parse', 'HEAD']).trim();

    // A newly-created undeclared file, plus an edit to a tracked one.
    fs.writeFileSync(path.join(repoRoot, 'scripts', 'brand-new.js'), 'module.exports = 3;\n');
    fs.writeFileSync(path.join(repoRoot, 'scripts', 'tracked.js'), 'module.exports = 99;\n');

    const overflow = ['scripts/tracked.js', 'scripts/brand-new.js', 'scripts/with space.js'];
    const present = gitPresentAtBase(repoRoot, baseSha, overflow);
    assert(present.indexOf('scripts/tracked.js') >= 0 && present.indexOf('scripts/with space.js') >= 0,
      'BATCH0-PARTITION: the real probe reports baseline-tracked paths as present (incl. one with a space), got ' + JSON.stringify(present));
    assert(present.indexOf('scripts/brand-new.js') < 0,
      'BATCH0-PARTITION: the real probe reports a newly-created file as ABSENT from the baseline, got ' + JSON.stringify(present));

    const removal = removeOverflowPaths(repoRoot, ['scripts/brand-new.js']);
    assert(removal.exitCode === 0 && JSON.stringify(removal.removed) === JSON.stringify(['scripts/brand-new.js']),
      'BATCH0-PARTITION: the real delete primitive removes the new file, got ' + JSON.stringify(removal));
    assert(!fs.existsSync(path.join(repoRoot, 'scripts', 'brand-new.js')),
      'BATCH0-PARTITION: the new file is gone from the worktree');
    // Idempotent: re-removing an already-absent path is a no-op, so a crashed retry converges.
    const again = removeOverflowPaths(repoRoot, ['scripts/brand-new.js']);
    assert(again.exitCode === 0 && again.removed.length === 0,
      'BATCH0-PARTITION: removing an already-absent path is an idempotent no-op, got ' + JSON.stringify(again));
    // A DIRECTORY is never followed — the primitive refuses rather than recursing.
    fs.mkdirSync(path.join(repoRoot, 'scripts', 'adir'));
    const dir = removeOverflowPaths(repoRoot, ['scripts/adir']);
    assert(dir.exitCode !== 0 && fs.existsSync(path.join(repoRoot, 'scripts', 'adir')),
      'BATCH0-PARTITION: a directory is refused, never recursively removed, got ' + JSON.stringify(dir));
    // A bad baseline throws, which is what makes the caller fail CLOSED.
    let threw = false;
    try { gitPresentAtBase(repoRoot, '0000000000000000000000000000000000000000', ['scripts/tracked.js']); }
    catch (_) { threw = true; }
    assert(threw, 'BATCH0-PARTITION: an unresolvable baseline THROWS, so the caller refuses instead of guessing');
  } finally {
    fs.rmSync(repoRoot, { recursive: true, force: true });
  }
});

// ---------------------------------------------------------------------------
// #434 Fixture (b) — repair-node: runRepairNode reopens writer with ORIGINAL barrier-base.
// RED: fails because runRepairNode is not yet exported.
// ---------------------------------------------------------------------------
scenario(() => {
  const planNodes = [
    '| impl | implementer | — | scripts/a.js | 1 | sequence |',
    '| review | code-reviewer | impl | — | 1 | sequence |',
    '| finalize | finalize | review | — | 1 | sequence |',
  ];
  // State: impl complete (writer finished), review in_progress (reviewer found a problem).
  let planContent = makePlan([
    '| impl | complete | |',
    '| review | in_progress | |',
    '| finalize | pending | |',
  ], planNodes);

  const removedBaselines = [];
  const shelled = [];
  const reviewerEvidence = 'evidence-binding: review oldreview123\nverdict: fail\nfindings_blocking: 1\nupstream_read: impl implbase123\n';

  const result = runRepairNode({
    planPath: '/fake/kaola-workflow/test-project/workflow-plan.md',
    project: 'test-project',
    nodeId: 'impl',   // the writer node to repair
    shell: (scriptPath, args) => {
      shelled.push(path.basename(scriptPath));
      // commit-node is NOT called for repair-node (no re-snapshot)
      return { exitCode: 0, result: 'ok' };
    },
    readFile: (f) => {
      if (f.endsWith('workflow-plan.md')) return planContent;
      if (f.endsWith('review.md')) return reviewerEvidence;
      // barrier-base-impl EXISTS (original baseline to keep)
      if (f.endsWith('barrier-base-impl')) return 'originalbasehash12\n';
      throw new Error('ENOENT ' + f);
    },
    writeFile: (f, c) => { if (f.endsWith('workflow-plan.md')) planContent = c; },
    cacheExists: (f) => f.endsWith('barrier-base-impl') || f.endsWith('barrier-base-review'),
    unlink: (f) => removedBaselines.push(path.basename(f)),
  });

  assert(result !== undefined, '#434-b RED: runRepairNode exported');
  assert(result && result.result === 'ok', '#434-b: repair-node returns ok, got ' + JSON.stringify(result));
  assert(result.baselineReused === true, '#434-b: baselineReused true (original baseline kept, no re-snapshot)');
  // Writer impl must be in_progress, reviewer reset to pending
  assert(/\|\s*impl\s*\|\s*in_progress\s*\|/.test(planContent),
    '#434-b: impl reopened to in_progress');
  assert(/\|\s*review\s*\|\s*pending\s*\|/.test(planContent),
    '#434-b: review gate reset to pending');
  // Original barrier-base-impl must NOT be removed (it is REUSED, not re-snapshotted)
  assert(!removedBaselines.includes('barrier-base-impl'),
    '#434-b: barrier-base-impl NOT removed (original baseline kept), removed=' + JSON.stringify(removedBaselines));
  // Downstream baselines (review) must be deleted
  assert(removedBaselines.includes('barrier-base-review') || result.deletedDownstreamBaselines,
    '#434-b: downstream review baseline removed or tracked in deletedDownstreamBaselines');
  assert(!removedBaselines.includes('review.md'),
    '#434-b: downstream reviewer evidence is retained as the repair brief');
  // The singleton code-reviewer's review.md is retained (not purged) — contrast the #664 fan-out
  // case, which purges group receipts INTO result.evidenceRemoved. Asserted against the OBSERVED
  // return value of runRepairNode (not the local reviewerEvidence literal it was read from), so
  // this fails if a future change ever starts purging the singleton reviewer's evidence.
  assert(result.evidenceRemoved && !result.evidenceRemoved.includes('review.md'),
    '#434-b: result.evidenceRemoved must NOT include review.md — the singleton reviewer evidence' +
    ' (with its blocking verdict: fail / findings_blocking: 1 body) is retained as the repair' +
    ' brief for the reopened writer, got evidenceRemoved=' + JSON.stringify(result.evidenceRemoved));
  // commit-node must NOT be shelled (no re-snapshot)
  assert(!shelled.includes('kaola-workflow-commit-node.js'),
    '#434-b: commit-node NOT shelled for repair-node (original baseline reused, no re-snapshot)');

  // REFUSE on complete node
  const planComplete = makePlan([
    '| impl | complete | |',
    '| review | complete | |',
    '| finalize | complete | |',
  ], planNodes);
  const refuseResult = runRepairNode({
    planPath: '/fake/kaola-workflow/test-project/workflow-plan.md',
    project: 'test-project',
    nodeId: 'impl',
    shell: () => ({ exitCode: 0, result: 'ok' }),
    readFile: (f) => { if (f.endsWith('workflow-plan.md')) return planComplete; throw new Error('ENOENT ' + f); },
    writeFile: () => { throw new Error('must not write on refusal'); },
    cacheExists: () => false,
    unlink: () => {},
  });
  assert(refuseResult && refuseResult.result === 'refuse',
    '#434-b: repair-node refuses on a complete node (no writer+reviewer in_progress pair), got ' + JSON.stringify(refuseResult));
});

// ---------------------------------------------------------------------------
// #664: repair-node MIXED-shape group fold — a writer repair downstream of a COMPLETED
// {av-a, av-b} explicit adversarial-verifier fan-out group (round-1 votes already cast) PLUS
// a singleton code-reviewer gate (currently in_progress — the active flagging gate) must reset
// BOTH skeptic rows (not just one, and not zero — #664 is exactly the case where NEITHER
// individually post-dominates the writer) AND purge BOTH stale receipts, while the singleton
// reviewer's evidence is retained as the repair brief (unchanged non-group behavior, #434-b).
// This is the repair-path twin of #658 (which fixed only reopen-node's collective fold).
// ---------------------------------------------------------------------------
scenario(() => {
  const planNodes664 = [
    '| impl | tdd-guide | — | scripts/a.js | 1 | sequence |',
    '| av-a | adversarial-verifier | impl | — | 1 | fanout(red-team) |',
    '| av-b | adversarial-verifier | impl | — | 1 | fanout(red-team) |',
    '| review | code-reviewer | av-a, av-b | — | 1 | sequence |',
    '| finalize | finalize | review | — | 1 | sequence |',
  ];
  let planContent664 = makePlan([
    '| impl | complete | |',
    '| av-a | complete | |',
    '| av-b | complete | |',
    '| review | in_progress | |',
    '| finalize | pending | |',
  ], planNodes664);

  const present664 = new Set([
    'barrier-base-impl', 'barrier-base-av-a', 'barrier-base-av-b', 'barrier-base-review',
    'av-a.md', 'av-b.md', 'review.md',
  ]);
  const removed664 = [];
  const shelled664 = [];

  const result664 = runRepairNode({
    planPath: '/fake/kaola-workflow/test-project/workflow-plan.md',
    project: 'test-project',
    nodeId: 'impl',
    shell: (sp) => { shelled664.push(path.basename(sp)); return { exitCode: 0, result: 'ok' }; },
    readFile: (f) => { if (f.endsWith('workflow-plan.md')) return planContent664; throw new Error('ENOENT ' + f); },
    writeFile: (f, c) => { if (f.endsWith('workflow-plan.md')) planContent664 = c; },
    cacheExists: (f) => present664.has(path.basename(f)),
    unlink: (f) => removed664.push(path.basename(f)),
  });

  assert(result664 && result664.result === 'ok', '#664: repair-node ok, got ' + JSON.stringify(result664));
  assert(result664.baselineReused === true, '#664: baselineReused true (writer baseline kept)');
  assert(result664.gatesReset.includes('av-a') && result664.gatesReset.includes('av-b'),
    '#664: repair-node folds the WHOLE completed adversarial-verifier fan-out group (BOTH av-a and av-b), got gatesReset=' + JSON.stringify(result664.gatesReset));
  assert(result664.gatesReset.includes('review'),
    '#664 MIXED-shape: the singleton downstream gate (review) ALSO folds alongside the group, got gatesReset=' + JSON.stringify(result664.gatesReset));
  assert(/\|\s*av-a\s*\|\s*pending\s*\|/.test(planContent664),
    '#664: av-a ledger row reset to pending, got plan=' + planContent664);
  assert(/\|\s*av-b\s*\|\s*pending\s*\|/.test(planContent664),
    '#664: av-b ledger row reset to pending, got plan=' + planContent664);
  assert(/\|\s*review\s*\|\s*pending\s*\|/.test(planContent664),
    '#664: singleton review gate ALSO reset to pending, got plan=' + planContent664);
  assert(/\|\s*impl\s*\|\s*in_progress\s*\|/.test(planContent664),
    '#664: writer impl reopened to in_progress, got plan=' + planContent664);
  assert(removed664.includes('av-a.md') && removed664.includes('av-b.md'),
    '#664: BOTH stale skeptic receipts purged — the reclose requires FRESH votes, stale round-1 votes must no longer satisfy --verdict-check; got removed=' + JSON.stringify(removed664));
  assert(!removed664.includes('review.md'),
    '#664: singleton reviewer evidence retained as the repair brief (unchanged non-group behavior), got removed=' + JSON.stringify(removed664));
  assert(!removed664.includes('barrier-base-impl'),
    '#664: writer baseline NOT removed (anti-laundering invariant), got removed=' + JSON.stringify(removed664));
  assert(!shelled664.includes('kaola-workflow-commit-node.js'),
    '#664: commit-node NOT shelled for repair-node (original baseline reused)');

  // #664: a MID-VOTE (in_progress) group must NOT be collectively folded — the pre-existing
  // would_orphan_in_progress refusal stays UNCHANGED (this must pass both before and after the fix).
  const planNodes664mv = [
    '| impl | tdd-guide | — | scripts/a.js | 1 | sequence |',
    '| av-a | adversarial-verifier | impl | — | 1 | fanout(red-team) |',
    '| av-b | adversarial-verifier | impl | — | 1 | fanout(red-team) |',
    '| finalize | finalize | av-a, av-b | — | 1 | sequence |',
  ];
  const planMidVote = makePlan([
    '| impl | complete | |',
    '| av-a | in_progress | |', // mid-vote: still deciding
    '| av-b | complete | |',
    '| finalize | pending | |',
  ], planNodes664mv);
  const resultMidVote = runRepairNode({
    planPath: '/fake/kaola-workflow/test-project/workflow-plan.md',
    project: 'test-project',
    nodeId: 'impl',
    shell: () => ({ exitCode: 0, result: 'ok' }),
    readFile: (f) => { if (f.endsWith('workflow-plan.md')) return planMidVote; throw new Error('ENOENT ' + f); },
    writeFile: () => { throw new Error('must not write on refusal'); },
    cacheExists: () => false,
    unlink: () => { throw new Error('must not unlink on refusal'); },
  });
  assert(resultMidVote && resultMidVote.result === 'refuse' && resultMidVote.reason === 'would_orphan_in_progress',
    '#664: a mid-vote (in_progress) group is NOT collectively folded — would_orphan_in_progress refusal preserved UNCHANGED, got ' + JSON.stringify(resultMidVote));
  assert(resultMidVote.inProgress && resultMidVote.inProgress.includes('av-a'),
    '#664: the mid-vote member (av-a) is reported as the orphan, got ' + JSON.stringify(resultMidVote));
});

// ---------------------------------------------------------------------------
// #665 R2: repair-node's (4c) fan-out receipt purge deduped by LABEL ONLY (group.group), but the
// validator keys fan-out groups by (label, origin) — resolveAdversarialFanoutGroup (#B6) — so TWO
// independent `fanout(red-team)` groups at DIFFERENT origins are two distinct receipt sets. A plan
// with a sequential pair of same-label groups (av-a{1,2} gated directly off the writer, av-b{1,2}
// gated off av-a{1,2}) — both COMPLETE, both post-dominating the writer through the #664 collective
// fold — must purge BOTH groups' receipts, not just the first one encountered.
// ---------------------------------------------------------------------------
scenario(() => {
  const planNodes665 = [
    '| impl | tdd-guide | — | scripts/a.js | 1 | sequence |',
    '| av-a1 | adversarial-verifier | impl | — | 1 | fanout(red-team) |',
    '| av-a2 | adversarial-verifier | impl | — | 1 | fanout(red-team) |',
    '| av-b1 | adversarial-verifier | av-a1, av-a2 | — | 1 | fanout(red-team) |',
    '| av-b2 | adversarial-verifier | av-a1, av-a2 | — | 1 | fanout(red-team) |',
    '| review | code-reviewer | av-b1, av-b2 | — | 1 | sequence |',
    '| finalize | finalize | review | — | 1 | sequence |',
  ];
  let planContent665 = makePlan([
    '| impl | complete | |',
    '| av-a1 | complete | |',
    '| av-a2 | complete | |',
    '| av-b1 | complete | |',
    '| av-b2 | complete | |',
    '| review | in_progress | |',
    '| finalize | pending | |',
  ], planNodes665);

  const present665 = new Set([
    'barrier-base-impl', 'barrier-base-av-a1', 'barrier-base-av-a2',
    'barrier-base-av-b1', 'barrier-base-av-b2', 'barrier-base-review',
    'av-a1.md', 'av-a2.md', 'av-b1.md', 'av-b2.md', 'review.md',
  ]);
  const removed665 = [];

  const result665 = runRepairNode({
    planPath: '/fake/kaola-workflow/test-project/workflow-plan.md',
    project: 'test-project',
    nodeId: 'impl',
    shell: () => ({ exitCode: 0, result: 'ok' }),
    readFile: (f) => { if (f.endsWith('workflow-plan.md')) return planContent665; throw new Error('ENOENT ' + f); },
    writeFile: (f, c) => { if (f.endsWith('workflow-plan.md')) planContent665 = c; },
    cacheExists: (f) => present665.has(path.basename(f)),
    unlink: (f) => removed665.push(path.basename(f)),
  });

  assert(result665 && result665.result === 'ok', '#665 R2: repair-node ok, got ' + JSON.stringify(result665));
  assert(['av-a1', 'av-a2', 'av-b1', 'av-b2'].every(id => result665.gatesReset.includes(id)),
    '#665 R2: BOTH same-label groups (av-a{1,2} AND av-b{1,2}) fold as post-dominating gates, got gatesReset=' + JSON.stringify(result665.gatesReset));
  assert(removed665.includes('av-a1.md') && removed665.includes('av-a2.md'),
    '#665 R2: the FIRST same-label group (av-a1/av-a2) receipts are purged, got removed=' + JSON.stringify(removed665));
  assert(removed665.includes('av-b1.md') && removed665.includes('av-b2.md'),
    '#665 R2: the SECOND same-label-different-origin group (av-b1/av-b2) receipts are ALSO purged — a '
    + 'label-only dedupe would wrongly skip this group because "red-team" was already seen, got removed=' + JSON.stringify(removed665));
  assert(result665.evidenceRemoved && ['av-a1.md', 'av-a2.md', 'av-b1.md', 'av-b2.md'].every(n => result665.evidenceRemoved.includes(n)),
    '#665 R2: result.evidenceRemoved names all four member receipts, got ' + JSON.stringify(result665.evidenceRemoved));
  assert(!removed665.includes('review.md'),
    '#665 R2: the singleton reviewer evidence is retained as the repair brief (unchanged non-group behavior), got removed=' + JSON.stringify(removed665));
});

// ---------------------------------------------------------------------------
// #665 R1: repair-node's LEGACY (role-prefix, cardinality>1) fan-out receipt purge branch is wired
// through the `readdir` opt — but the `repair-node` CLI dispatch omitted it (unlike reopen-node's
// dispatch, which passes both `unlink` and `readdir`), so a resumed legacy-format plan folded the
// gate but silently skipped the receipt purge. Drives the REAL CLI subcommand (subprocess, not a
// direct runRepairNode(...) call) so the assertion actually exercises the dispatch wiring, not just
// the function body — a direct call with a hand-supplied `readdir` would pass even with the CLI
// dispatch left broken.
// ---------------------------------------------------------------------------
scenario(() => {
  const { execFileSync: exec665r1 } = require('child_process');
  const NODE_CLI_665R1 = path.join(__dirname, 'kaola-workflow-adaptive-node.js');

  const planNodes665r1 = [
    '| impl | tdd-guide | — | scripts/a.js | 1 | sequence |',
    '| av | adversarial-verifier | impl | — | 3 | fanout(legacy) |',
    '| finalize | finalize | av | — | 1 | sequence |',
  ];
  const decoyPlan665r1 = makePlan([
    '| impl | complete | |',
    '| av | in_progress | |',
    '| finalize | pending | |',
  ], planNodes665r1);
  const hash665r1 = planValidator.computePlanHash(decoyPlan665r1);
  const frozen665r1 = '<!-- plan_hash: ' + hash665r1 + ' -->\n' + decoyPlan665r1;

  const repoRoot665r1 = fs.mkdtempSync(path.join(os.tmpdir(), 'd665r1-repair-'));
  const project665r1 = 'test-project';
  const projDir665r1 = path.join(repoRoot665r1, 'kaola-workflow', project665r1);
  const cacheDir665r1 = path.join(projDir665r1, '.cache');
  fs.mkdirSync(cacheDir665r1, { recursive: true });
  const planPath665r1 = path.join(projDir665r1, 'workflow-plan.md');
  fs.writeFileSync(planPath665r1, frozen665r1);
  fs.writeFileSync(path.join(projDir665r1, 'workflow-state.md'), '# State\n');
  // Legacy round-1 role-prefix receipts + downstream/writer barrier-bases.
  fs.writeFileSync(path.join(cacheDir665r1, 'adversarial-verifier-0.md'), 'verdict: pass\n');
  fs.writeFileSync(path.join(cacheDir665r1, 'adversarial-verifier-1.md'), 'verdict: pass\n');
  fs.writeFileSync(path.join(cacheDir665r1, 'adversarial-verifier-2.md'), 'verdict: fail\n');
  fs.writeFileSync(path.join(cacheDir665r1, 'unrelated.md'), 'not a skeptic receipt\n');
  fs.writeFileSync(path.join(cacheDir665r1, 'barrier-base-impl'), 'writer-baseline\n');
  fs.writeFileSync(path.join(cacheDir665r1, 'barrier-base-av'), 'gate-baseline\n');

  const g665r1 = (a) => exec665r1('git', ['-C', repoRoot665r1, ...a], { encoding: 'utf8', stdio: ['ignore', 'ignore', 'ignore'] });
  g665r1(['init']); g665r1(['config', 'user.email', 'kw@test']); g665r1(['config', 'user.name', 'kw']); g665r1(['config', 'commit.gpgsign', 'false']);
  fs.writeFileSync(path.join(repoRoot665r1, '.gitignore'), '.kw/\n');
  g665r1(['add', '-A']); g665r1(['commit', '-m', 'init']);

  let out665r1 = {};
  try {
    // A missing required flag must map to a refusal envelope naming it — argv validation, proven
    // at the CLI because that is where argv exists.
    // spawn-class: cli-contract
    out665r1 = JSON.parse(exec665r1('node', [NODE_CLI_665R1, 'repair-node', '--project', project665r1, '--node-id', 'impl', '--json'],
      { cwd: repoRoot665r1, encoding: 'utf8' }).trim());
  } catch (err) {
    try { out665r1 = JSON.parse(String(err.stdout || '').trim()); } catch (_) { out665r1 = { execError: String(err.message || err) }; }
  }

  assert(out665r1.result === 'refuse' && (out665r1.errors || []).includes('--attempt-id required for repair-node'),
    '#665 R1 superseded: frozen-plan repair requires an authoritative attempt id, got ' + JSON.stringify(out665r1));
  assert(fs.existsSync(path.join(cacheDir665r1, 'adversarial-verifier-0.md'))
    && fs.existsSync(path.join(cacheDir665r1, 'adversarial-verifier-1.md'))
    && fs.existsSync(path.join(cacheDir665r1, 'adversarial-verifier-2.md')),
    '#665 R1 superseded: missing attempt id is a zero-mutation refusal preserving legacy receipts');
  assert(fs.existsSync(path.join(cacheDir665r1, 'unrelated.md')),
    '#665 R1: an unrelated .cache file (non-matching name) is left untouched');
  assert(fs.existsSync(path.join(cacheDir665r1, 'barrier-base-impl')),
    "#665 R1: the writer's OWN barrier-base is NEVER removed (anti-laundering invariant)");
  assert(fs.existsSync(path.join(cacheDir665r1, 'barrier-base-av')),
    '#665 R1 superseded: missing attempt id preserves downstream baseline bytes');

  try { fs.rmSync(repoRoot665r1, { recursive: true, force: true }); } catch (_) {}
});

// ---------------------------------------------------------------------------
// #434 Fixture (c) — requires_redispatch: orient emits requires_redispatch when
// an in_progress node has absent/incomplete evidence.
// RED: fails because orient does not yet emit requires_redispatch.
// ---------------------------------------------------------------------------
scenario(() => {
  const planNodes = [
    '| impl | implementer | — | scripts/a.js | 1 | sequence |',
    '| review | code-reviewer | impl | — | 1 | sequence |',
    '| finalize | finalize | review | — | 1 | sequence |',
  ];
  const planContent = makePlan([
    '| impl | in_progress | |',
    '| review | pending | |',
    '| finalize | pending | |',
  ], planNodes);

  // Case 1: evidence file ABSENT → requires_redispatch
  const orientAbsent = runOrient({
    planPath: '/fake/kaola-workflow/test-project/workflow-plan.md',
    statePath: '/fake/kaola-workflow/test-project/workflow-state.md',
    project: 'test-project',
    shell: (sp, args) => {
      if (args && args.includes('--resume-check')) return { exitCode: 0, result: 'ok', resumable: true };
      if (args && args.includes('--json') && !args.includes('--resume-check')) return { exitCode: 0, result: 'ok', readySet: [], allDone: false, readyPending: [] };
      return { exitCode: 0, result: 'ok' };
    },
    readFile: (f) => {
      if (f.endsWith('workflow-plan.md')) return planContent;
      if (f.endsWith('workflow-state.md')) return makeState();
      throw new Error('ENOENT ' + f);
    },
    cacheExists: (f) => false, // evidence absent
  });
  assert(orientAbsent.result === 'ok', '#434-c: orient ok with absent evidence, got ' + JSON.stringify(orientAbsent));
  assert(orientAbsent.requires_redispatch === true,
    '#434-c: orient emits requires_redispatch=true when evidence absent, got ' + JSON.stringify(orientAbsent));

  // Case 2: evidence file PRESENT with evidence-binding token → NO requires_redispatch
  const orientPresent = runOrient({
    planPath: '/fake/kaola-workflow/test-project/workflow-plan.md',
    statePath: '/fake/kaola-workflow/test-project/workflow-state.md',
    project: 'test-project',
    shell: (sp, args) => {
      if (args && args.includes('--resume-check')) return { exitCode: 0, result: 'ok', resumable: true };
      return { exitCode: 0, result: 'ok', readySet: [], allDone: false, readyPending: [] };
    },
    readFile: (f) => {
      if (f.endsWith('workflow-plan.md')) return planContent;
      if (f.endsWith('workflow-state.md')) return makeState();
      if (f.endsWith('impl.md')) return 'evidence-binding: impl deadbeef1234\nbuild-green: yes\n';
      throw new Error('ENOENT ' + f);
    },
    cacheExists: (f) => f.endsWith('impl.md'), // evidence present
  });
  assert(orientPresent.result === 'ok', '#434-c: orient ok with present evidence');
  assert(!orientPresent.requires_redispatch,
    '#434-c: orient does NOT set requires_redispatch when evidence present, got ' + JSON.stringify(orientPresent));
});

