// ===========================================================================
// N684-5 — the #664 fold END-TO-END through a REAL frozen plan + REAL review journal, not the
// unfrozen makePlan() shortcut the ORIGINAL #664 fixture above uses (which reaches runRepairNode with
// hasReviewJournal===false and skips the ENTIRE journal-gated preamble — a shape a real planner
// freeze can never produce, per #684's audit). Drives close-node for a REAL adversarial-verifier
// fanout(red-team) PASS group, then a REAL code-reviewer FAIL, then repair-node with the settled
// failed attempt's real attempt_id — --attempt-id/the unique-maximal proof/the digest check/the
// writer-identity check/the commit-node barrier re-verify shell-out ALL engage — asserting the exact
// #664 fold outcome (post-dominating gates folded, receipts purged with dedupe honored, singleton
// reviewer evidence retained, the attempt durably consumed).
// ===========================================================================
scenario(() => {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-684-fold-e2e-'));
  try {
    const projectDir = path.join(tmp, 'kaola-workflow', 'issue-684f');
    const cacheDir = path.join(projectDir, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    const body = makePlan([
      '| impl | complete | |', '| av-a | in_progress | |', '| av-b | in_progress | |',
      '| review | pending | |', '| finalize | pending | |',
    ], [
      '| impl | tdd-guide | — | scripts/impl684f.js | 1 | sequence |',
      '| av-a | adversarial-verifier | impl | — | 1 | fanout(red-team) |',
      '| av-b | adversarial-verifier | impl | — | 1 | fanout(red-team) |',
      '| review | code-reviewer | av-a, av-b | — | 1 | sequence |',
      '| finalize | finalize | review | CHANGELOG.md | 1 | sequence |',
    ]);
    const hash = planValidator.computePlanHash(body);
    const planPath = path.join(projectDir, 'workflow-plan.md');
    fs.writeFileSync(planPath, '<!-- plan_hash: ' + hash + ' -->\n' + body);
    const writerIdentity = { baseline: 'i'.repeat(40), anchored_ref: 'i'.repeat(40),
      open_token: 'open-impl684f', generation: 'i'.repeat(12),
      ref: 'refs/kaola-workflow/barrier/issue-684f/impl' };
    fs.writeFileSync(path.join(cacheDir, 'barrier-base-impl'), 'i'.repeat(40) + '\n');
    fs.writeFileSync(path.join(cacheDir, 'barrier-base-av-a'), 'a'.repeat(40) + '\n');
    fs.writeFileSync(path.join(cacheDir, 'barrier-base-av-b'), 'b'.repeat(40) + '\n');
    fs.writeFileSync(path.join(cacheDir, 'av-a.md'),
      'evidence-binding: av-a ' + 'a'.repeat(12) + '\nverdict: pass\nfindings_blocking: 0\n');
    fs.writeFileSync(path.join(cacheDir, 'av-b.md'),
      'evidence-binding: av-b ' + 'b'.repeat(12) + '\nverdict: pass\nfindings_blocking: 0\n');
    fs.writeFileSync(path.join(cacheDir, 'running-set.json'), JSON.stringify({ state: 'open', nodes: [
      { id: 'av-a', role: 'adversarial-verifier', kind: 'read' },
      { id: 'av-b', role: 'adversarial-verifier', kind: 'read' },
    ] }, null, 2));
    const common = { planPath, project: 'issue-684f',
      shell: () => ({ exitCode: 0, result: 'ok', ok: true, overallOk: true,
        selectorCheck: { isSelector: false, ok: true } }),
      readFile: p => fs.readFileSync(p, 'utf8'), writeFile: (p, c) => fs.writeFileSync(p, c),
      cacheExists: p => fs.existsSync(p), unlink: p => fs.unlinkSync(p), readdir: d => fs.readdirSync(d),
      computeReviewCandidateDigest: () => 'f'.repeat(64),
      captureWriterBarrierIdentity: id => id === 'impl' ? writerIdentity : null };

    // The fanout group PASSES on round 1 — av-a votes provisionally, av-b (last) certifies the group.
    const closeA = runCloseNode({ ...common, nodeId: 'av-a' });
    assert(closeA.result === 'ok' && closeA.provisional === true,
      'N684-5: setup — av-a (non-last fanout member) closes provisionally, got ' + JSON.stringify(closeA));
    const closeB = runCloseNode({ ...common, nodeId: 'av-b' });
    assert(closeB.result === 'ok' && !closeB.provisional,
      'N684-5: setup — av-b (last fanout member) certifies the group PASS, got ' + JSON.stringify(closeB));
    let plan = fs.readFileSync(planPath, 'utf8');
    const statusesAfterFanout = readLedgerStatuses(plan);
    assert(statusesAfterFanout['av-a'] === 'complete' && statusesAfterFanout['av-b'] === 'complete',
      'N684-5: setup — BOTH fanout members are complete after the group settles PASS, got '
      + JSON.stringify(statusesAfterFanout));

    // review opens (hand-advanced — the fold under test is repair-node's, not the scheduler's) and
    // settles FAIL.
    const opened = spliceLedgerNode(plan, 'review', 'in_progress', { allowFrom: ['pending'] });
    assert(opened.changed, 'N684-5: setup — review transitions to in_progress');
    fs.writeFileSync(planPath, opened.content);
    fs.writeFileSync(path.join(cacheDir, 'barrier-base-review'), 'r'.repeat(40) + '\n');
    fs.writeFileSync(path.join(cacheDir, 'review.md'),
      'evidence-binding: review ' + 'r'.repeat(12) + '\nverdict: fail\nfindings_blocking: 1\n');
    fs.writeFileSync(path.join(cacheDir, 'running-set.json'), JSON.stringify({ state: 'open', nodes: [
      { id: 'review', role: 'code-reviewer', kind: 'read' },
    ] }, null, 2));
    const closeReview = runCloseNode({ ...common, nodeId: 'review' });
    assert(closeReview.result === 'review_failed' && closeReview.lifecycle_settled === true,
      'N684-5: setup — the singleton reviewer settles FAIL with a durable attempt, got ' + JSON.stringify(closeReview));
    plan = fs.readFileSync(planPath, 'utf8');
    assert(readLedgerStatuses(plan).review === 'pending',
      'N684-5: setup — the failed reviewer folds itself back to pending');

    // The real journal-gated repair-node path: --attempt-id required, readReviewJournal, the
    // unique-maximal producer proof, verifyWriterBarrierIdentity, computeReviewCandidateDigest, and
    // the commit-node barrier re-verify shell-out ALL engage (hasReviewJournal === true throughout).
    const repaired = runRepairNode({ ...common, nodeId: 'impl', attemptId: closeReview.attempt_id });
    assert(repaired.result === 'ok' && repaired.baselineReused === true,
      '#664 (real journal): repair-node folds the mixed-shape group through the REAL journal-gated path, '
      + 'got ' + JSON.stringify(repaired));
    assert(repaired.gatesReset.includes('av-a') && repaired.gatesReset.includes('av-b')
      && repaired.gatesReset.includes('review'),
      '#664 (real journal): repair-node folds BOTH the completed fanout group AND the singleton downstream '
      + 'gate, got gatesReset=' + JSON.stringify(repaired.gatesReset));
    assert(JSON.stringify(repaired.evidenceRemoved.slice().sort()) === JSON.stringify(['av-a.md', 'av-b.md']),
      '#664 (real journal): BOTH stale skeptic receipts are purged with dedupe honored (each name exactly '
      + 'once even though the fold loop visits the group via both av-a and av-b), got '
      + JSON.stringify(repaired.evidenceRemoved));
    assert(fs.existsSync(path.join(cacheDir, 'review.md')),
      '#664 (real journal): the singleton reviewer\'s evidence is RETAINED as the repair brief, not purged');
    plan = fs.readFileSync(planPath, 'utf8');
    const finalStatuses = readLedgerStatuses(plan);
    assert(finalStatuses['av-a'] === 'pending' && finalStatuses['av-b'] === 'pending'
      && finalStatuses.review === 'pending' && finalStatuses.impl === 'in_progress',
      '#664 (real journal): av-a/av-b/review reset to pending and impl reopens to in_progress, got '
      + JSON.stringify(finalStatuses));
    const journalAfter = JSON.parse(fs.readFileSync(path.join(cacheDir, 'review-attempts.json'), 'utf8'));
    const settledAttempt = journalAfter.attempts.find(a => a.attempt_id === closeReview.attempt_id);
    assert(settledAttempt && settledAttempt.consumed_by === 'impl' && settledAttempt.repair.settled === true,
      '#664 (real journal): the repaired attempt is durably consumed by the selected writer');
  } finally { fs.rmSync(tmp, { recursive: true, force: true }); }
});

// ===========================================================================
// N684-6 — the PAIRED fixture that gives the JOURNAL-DRIVEN fold site (adaptive-node.js ~:5031-5052)
// its OWN single-mutation killer. In N684-5 that site is MUTUALLY REDUNDANT with the legacy #664
// ledger-fanout site (~:5073-5090): both fold the SAME av-a/av-b group and both purge the SAME two
// receipts, so disabling either alone leaves every N684-5 assertion green. The two sites are NOT
// equivalent, though: only the journal-driven site can attribute a COMPLETED **singleton** gate (a
// code-reviewer, not a fan-out) to this exact candidate+writer via its recorded PASS attempt, and only
// it therefore purges that singleton's stale pass receipt (the `completedJournalGates` purge at :5195,
// whose input set is computed EXCLUSIVELY by :5031-5052). The ledger-fanout site touches only
// adversarial-verifier fan-out receipts, so it can never cover this purge. A sequence-only shape
// isolates it: impl -> g_pass (PASSES, complete) -> g_fail (FAILS, folds) -> finalize. Structural
// post-domination (:5071-5072) still folds BOTH gates back to pending regardless of the journal site,
// so the KILLER lives on the receipt purge, not on gatesReset. Disabling ONLY :5031-5052 empties
// completedJournalGates and g_pass.md survives -> the evidenceRemoved assertion goes RED, with the #664
// fanout fixture and N684-5 untouched (proving the killer is single-site).
// ===========================================================================
scenario(() => {
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-684-6-singleton-'));
  try {
    const projectDir = path.join(tmp, 'kaola-workflow', 'issue-684g');
    const cacheDir = path.join(projectDir, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    const body = makePlan([
      '| impl | complete | |', '| g_pass | in_progress | |',
      '| g_fail | pending | |', '| finalize | pending | |',
    ], [
      '| impl | tdd-guide | — | scripts/impl684g.js | 1 | sequence |',
      '| g_pass | code-reviewer | impl | — | 1 | sequence |',
      '| g_fail | code-reviewer | g_pass | — | 1 | sequence |',
      '| finalize | finalize | g_fail | CHANGELOG.md | 1 | sequence |',
    ]);
    const hash = planValidator.computePlanHash(body);
    const planPath = path.join(projectDir, 'workflow-plan.md');
    fs.writeFileSync(planPath, '<!-- plan_hash: ' + hash + ' -->\n' + body);
    const writerIdentity = { baseline: 'i'.repeat(40), anchored_ref: 'i'.repeat(40),
      open_token: 'open-impl684g', generation: 'i'.repeat(12),
      ref: 'refs/kaola-workflow/barrier/issue-684g/impl' };
    fs.writeFileSync(path.join(cacheDir, 'barrier-base-impl'), 'i'.repeat(40) + '\n');
    fs.writeFileSync(path.join(cacheDir, 'barrier-base-g_pass'), 'p'.repeat(40) + '\n');
    fs.writeFileSync(path.join(cacheDir, 'g_pass.md'),
      'evidence-binding: g_pass ' + 'p'.repeat(12) + '\nverdict: pass\nfindings_blocking: 0\n');
    fs.writeFileSync(path.join(cacheDir, 'running-set.json'), JSON.stringify({ state: 'open', nodes: [
      { id: 'g_pass', role: 'code-reviewer', kind: 'read' },
    ] }, null, 2));
    const common = { planPath, project: 'issue-684g',
      shell: () => ({ exitCode: 0, result: 'ok', ok: true, overallOk: true,
        selectorCheck: { isSelector: false, ok: true } }),
      readFile: p => fs.readFileSync(p, 'utf8'), writeFile: (p, c) => fs.writeFileSync(p, c),
      cacheExists: p => fs.existsSync(p), unlink: p => fs.unlinkSync(p), readdir: d => fs.readdirSync(d),
      computeReviewCandidateDigest: () => 'f'.repeat(64),
      captureWriterBarrierIdentity: id => id === 'impl' ? writerIdentity : null };

    // g_pass — a SINGLETON code-reviewer — PASSES on this candidate, recording a durable PASS attempt
    // bound to impl. This is the receipt only the journal-driven site can attribute + purge.
    const closePass = runCloseNode({ ...common, nodeId: 'g_pass' });
    assert(closePass.result === 'ok' && !closePass.provisional && readLedgerStatuses(fs.readFileSync(planPath, 'utf8')).g_pass === 'complete',
      'N684-6: setup — the singleton g_pass certifies PASS and goes complete, got ' + JSON.stringify(closePass));

    // g_fail opens (hand-advanced) and settles FAIL — the blocker the repair consumes.
    let plan = fs.readFileSync(planPath, 'utf8');
    const opened = spliceLedgerNode(plan, 'g_fail', 'in_progress', { allowFrom: ['pending'] });
    assert(opened.changed, 'N684-6: setup — g_fail transitions to in_progress');
    fs.writeFileSync(planPath, opened.content);
    fs.writeFileSync(path.join(cacheDir, 'barrier-base-g_fail'), 'q'.repeat(40) + '\n');
    fs.writeFileSync(path.join(cacheDir, 'g_fail.md'),
      'evidence-binding: g_fail ' + 'q'.repeat(12) + '\nverdict: fail\nfindings_blocking: 1\n');
    fs.writeFileSync(path.join(cacheDir, 'running-set.json'), JSON.stringify({ state: 'open', nodes: [
      { id: 'g_fail', role: 'code-reviewer', kind: 'read' },
    ] }, null, 2));
    const closeFail = runCloseNode({ ...common, nodeId: 'g_fail' });
    assert(closeFail.result === 'review_failed' && closeFail.lifecycle_settled === true,
      'N684-6: setup — g_fail settles FAIL with a durable attempt, got ' + JSON.stringify(closeFail));

    const repaired = runRepairNode({ ...common, nodeId: 'impl', attemptId: closeFail.attempt_id });
    assert(repaired.result === 'ok' && repaired.baselineReused === true,
      'N684-6: repair-node folds the sequence chain through the REAL journal-gated path, got ' + JSON.stringify(repaired));
    // Structural post-domination folds BOTH gates regardless of the journal site — NOT the killer.
    assert(repaired.gatesReset.includes('g_pass') && repaired.gatesReset.includes('g_fail'),
      'N684-6: both post-dominating gates fold back to pending, got gatesReset=' + JSON.stringify(repaired.gatesReset));
    // THE SINGLE-SITE KILLER: g_pass's stale PASS receipt is purged ONLY via completedJournalGates,
    // whose membership is computed EXCLUSIVELY by the journal-driven fold site (:5031-5052). The
    // ledger-fanout site (:5073-5090) touches no singleton receipt, so this assertion goes RED iff the
    // journal-driven site is disabled — a killer no other fixture supplies.
    assert(repaired.evidenceRemoved.includes('g_pass.md'),
      'N684-6: the stale singleton PASS receipt g_pass.md is purged (journal-driven completedJournalGates '
      + 'site is load-bearing), got evidenceRemoved=' + JSON.stringify(repaired.evidenceRemoved));
    assert(!repaired.evidenceRemoved.includes('g_fail.md') && fs.existsSync(path.join(cacheDir, 'g_fail.md')),
      'N684-6: the failed singleton\'s evidence is RETAINED as the repair brief, not purged');
  } finally { fs.rmSync(tmp, { recursive: true, force: true }); }
});

// ===========================================================================
// #688 — fail-closed hardening of proveRebindAdmissible's ledger-status inputs (items 1+2, low,
// unreachable-today edges surfaced by the #683 adversarial campaign). Direct-call unit assertions,
// exactly as the issue's own acceptance criteria sanction (a synthetic absent-ledger call; an n/a-arm
// construction) — neither shape is reachable through the real repair-node CLI today.
//
// Fixture: one slice node `writer` (the current attempt's own producer, declares a.js) and one
// disjoint owner `other` (declares b.js) whose OWN gate is a DIFFERENT, already-repaired attempt
// (`repair.selected_writer: 'other'`). The candidate delta moves b.js (owned solely by `other`,
// disjoint from the slice) since cand and now disagree on its blob — the ONLY path P3b can ever
// attribute, and exactly the seam #688.1/2 hardens (repairWriters' ledger-status quantifier).
// ===========================================================================
scenario(() => {
  const makeProveCtx = () => ({
    nodes: [
      { id: 'writer', writeSetRaw: 'a.js' },
      { id: 'other', writeSetRaw: 'b.js' },
    ],
    attempt: {
      candidate_residue_digest: 'RESIDUE688',
      producer_bindings: { writer: {} },
      logical_gate: { key: 'gate-writer-688', members: ['writer'] },
      rebind: [],
    },
    attempts: [{
      logical_gate: { key: 'gate-other-688', members: ['other'] },
      repair: { selected_writer: 'other', settled: false },
    }],
    now: { residue_digest: 'RESIDUE688',
      declared: { 'a.js': '100644 ' + 'a'.repeat(40), 'b.js': '100644 ' + 'b'.repeat(40) } },
    cand: { digest: 'X688',
      declared: { 'a.js': '100644 ' + 'a'.repeat(40), 'b.js': '100644 ' + 'c'.repeat(40) } },
    declaredUnion: new Set(['a.js', 'b.js']),
    foreign: [],
    nodeId: 'writer',
    // NOTE: `ledgerStatuses` is deliberately OMITTED here — the synthetic absent-ledger call.
  });

  // #688.1 — a synthetic ABSENT ledger (ctx carries no `ledgerStatuses` key at all): the pre-fix
  // `(ledgerStatuses || {})[m]` fallback degrades every lookup to undefined !== 'complete' -> true,
  // i.e. admit-ALL. Fail-closed posture: an absent ledger must refuse attribution instead.
  {
    const out = proveRebindAdmissible(makeProveCtx());
    assert(out.ok === false && out.reason === 'candidate_delta_unattributed'
      && JSON.stringify(out.paths) === JSON.stringify(['b.js']),
      '#688.1: a synthetic absent ledger (ctx.ledgerStatuses omitted) fails CLOSED — refuses '
      + 'candidate_delta_unattributed on b.js instead of admit-all, got ' + JSON.stringify(out));
  }

  // #688.2 — an n/a-ARM construction: the owner gate's sole member sits at status n/a (a
  // selector-pruned arm that never re-reviews). The pre-fix quantifier `!== 'complete'` treats n/a as
  // "still live", wrongly attributing through it. Restrict to {pending, in_progress}.
  {
    const ctx = makeProveCtx();
    ctx.ledgerStatuses = { other: 'n/a' };
    const out = proveRebindAdmissible(ctx);
    assert(out.ok === false && out.reason === 'candidate_delta_unattributed'
      && JSON.stringify(out.paths) === JSON.stringify(['b.js']),
      '#688.2: an n/a owner-gate member is excluded from the liveness quantifier — refuses '
      + 'candidate_delta_unattributed on b.js, got ' + JSON.stringify(out));
  }

  // Regression controls — a genuinely LIVE owner gate (pending or in_progress) must still attribute
  // the delta via P3b exactly as before (the fix narrows the quantifier, it must not empty it).
  {
    const ctxPending = makeProveCtx();
    ctxPending.ledgerStatuses = { other: 'pending' };
    const outPending = proveRebindAdmissible(ctxPending);
    assert(outPending.ok === true
      && JSON.stringify(outPending.absorbed.map(a => a.path)) === JSON.stringify(['b.js'])
      && JSON.stringify(outPending.attributed_to) === JSON.stringify(['other']),
      '#688: (control) a genuinely pending owner gate still attributes the delta via P3b, got ' + JSON.stringify(outPending));

    const ctxInProgress = makeProveCtx();
    ctxInProgress.ledgerStatuses = { other: 'in_progress' };
    const outInProgress = proveRebindAdmissible(ctxInProgress);
    assert(outInProgress.ok === true && JSON.stringify(outInProgress.attributed_to) === JSON.stringify(['other']),
      '#688: (control) a genuinely in_progress owner gate still attributes the delta via P3b, got ' + JSON.stringify(outInProgress));
  }
});

// ===========================================================================
// #688.4 — isCanonicalBlobMap's enumeration-order check made ORDER-INSENSITIVE. JS forces
// canonical-integer object keys (e.g. "10", "2024") to enumerate FIRST, in numeric order, ahead of
// EVERY string key regardless of insertion order — so a correctly-built declared-path map containing
// a repo-root file literally named a canonical integer can fail the pre-fix native-enumeration-vs-
// lexicographic-sort comparison purely as an artifact of that forced reordering, not a real disorder.
// ===========================================================================
scenario(() => {
  const mode = '100644 ';
  // A string key that sorts (lexicographically, character-by-character) BEFORE the canonical-integer
  // key "10" (".env" starts with '.' = 0x2E, less than '1' = 0x31) — the exact shape the issue names:
  // "a repo-root file named a canonical integer (10, 2024) alongside a string-earlier path".
  const declared = { '.env': mode + 'a'.repeat(40), '10': mode + 'b'.repeat(40) };
  // Sanity: this is precisely the native-order-vs-sorted mismatch the pre-fix check choked on (JS
  // enumerates the integer-like key '10' before the string key '.env' regardless of insertion order).
  assert(JSON.stringify(Object.keys(declared)) !== JSON.stringify(Object.keys(declared).slice().sort()),
    '#688.4 fixture sanity: native enumeration order for {.env, 10} really does diverge from lexicographic sort');
  assert(isCanonicalBlobMap(declared) === true,
    '#688.4: an integer-keyed candidate_declared map ({.env, 10}) must pass isCanonicalBlobMap after the '
    + 'order-insensitive fix, got false');

  // Regression control: a genuinely malformed map (a value that is not a canonical tree-entry string)
  // must still be rejected — the fix removes the enumeration-order dependency, not the shape check.
  assert(isCanonicalBlobMap({ '.env': 'not-a-tree-entry' }) === false,
    '#688.4: (control) a non-canonical value shape is still rejected');
  assert(isCanonicalBlobMap(null) === false && isCanonicalBlobMap([]) === false && isCanonicalBlobMap('x') === false,
    '#688.4: (control) non-object/array/string inputs are still rejected');
});

// ===========================================================================
// #688.3 — a reserved node id (a literal Object.prototype key, e.g. `__proto__`) must REFUSE at
// freeze, not silently poison readLedgerStatuses' plain-object status map (a `{}` literal's
// `out['__proto__'] = status` is a silent setter no-op, never an own property — the row vanishes and
// the run wedges fail-closed). Direct-call against validatePlan (the freeze-time grammar).
// ===========================================================================
scenario(() => {
  const body688c = makePlan(
    ['| impl | pending | |', '| __proto__ | pending | |', '| finalize | pending | |'],
    [
      '| impl | tdd-guide | — | scripts/impl688c.js | 1 | sequence |',
      '| __proto__ | code-reviewer | impl | — | 1 | sequence |',
      '| finalize | finalize | __proto__ | CHANGELOG.md | 1 | sequence |',
    ]);
  const v688c = planValidator.validatePlan(body688c, {});
  assert(v688c.result === 'refuse' && v688c.reason === 'plan_invalid'
    && Array.isArray(v688c.errors) && v688c.errors.some(e => e.includes('__proto__') && e.includes('reserved')),
    '#688.3: a node id literally named `__proto__` refuses in-grammar at freeze (plan_invalid, a '
    + 'reserved-Object.prototype-key error), got ' + JSON.stringify({ result: v688c.result, reason: v688c.reason, errors: v688c.errors }));

  // Regression control: a legitimate node id (not a reserved key) still freezes clean — the fix must
  // not reject ordinary plans.
  const cleanBody688c = makePlan(
    ['| impl | pending | |', '| review | pending | |', '| finalize | pending | |'],
    [
      '| impl | tdd-guide | — | scripts/impl688c-clean.js | 1 | sequence |',
      '| review | code-reviewer | impl | — | 1 | sequence |',
      '| finalize | finalize | review | CHANGELOG.md | 1 | sequence |',
    ]);
  const vClean688c = planValidator.validatePlan(cleanBody688c, {});
  assert(vClean688c.result === 'in-grammar',
    '#688.3: (control) an ordinary node id set still freezes clean, got ' + JSON.stringify({ result: vClean688c.result, errors: vClean688c.errors }));
});

// #699: orient is the read-only projection of the active re-plan fence. It must
// short-circuit before validator/next-action/task-mirror and surface only resume.
scenario(() => {
  let shells = 0;
  let writes = 0;
  const out = runOrient({
    planPath: '/fake/kaola-workflow/issue-699/workflow-plan.md',
    statePath: '/fake/kaola-workflow/issue-699/workflow-state.md',
    project: 'issue-699',
    replanFence: {
      ok: true, fenced: true, reason: 'replan_in_progress', phase: 'child_frozen',
      transaction_id: '1'.repeat(64), legal_mutation: 'replan resume',
      transaction: {
        parent: { plan_hash: '2'.repeat(64) }, child: { plan_hash: '3'.repeat(64) },
        cas: { prepare: { result: 'match' }, pre_freeze: { result: 'match' } },
      },
    },
    shell: () => { shells++; return { exitCode: 0 }; },
    readFile: () => { throw new Error('orient fence must not read plan/state after projection'); },
    writeFile: () => { writes++; }, cacheExists: () => false,
  });
  assert(out.result === 'refuse' && out.reason === 'replan_in_progress'
    && out.replan_phase === 'child_frozen' && out.parent_plan_hash === '2'.repeat(64)
    && out.child_plan_hash === '3'.repeat(64) && out.last_cas_seam === 'pre_freeze'
    && out.resume_command === 'node scripts/kaola-workflow-replan.js resume --project issue-699 --json',
  '#699 orient fence: exact sanitized transaction orientation, got ' + JSON.stringify(out));
  assert(shells === 0 && writes === 0,
    '#699 orient fence: no validator/next-action/task-mirror/cache mutation occurs');
});

// #699: after commit, scheduler orientation keeps the current next action for
// execution while separately reporting the immutable epoch's actual first
// child node. E2 current-authority refusal precedes every shell/cache mutation.
scenario(() => {
  const plan = makePlan([
    '| child-first | complete | |',
    '| current-node | in_progress | |',
    '| finalize | pending | |',
  ], [
    '| child-first | code-explorer | — | — | 1 | sequence |',
    '| current-node | tdd-guide | child-first | scripts/current.js | 1 | sequence |',
    '| finalize | finalize | current-node | CHANGELOG.md | 1 | sequence |',
  ]);
  const committedFence = { ok: true, fenced: false, committed: true, transaction: {
    child: { plan_hash: 'a'.repeat(64), first_node_id: 'child-first', first_node_role: 'code-explorer' },
  } };
  let shellCalls = 0;
  const shell = scriptPath => {
    shellCalls++;
    if (path.basename(scriptPath) === 'kaola-workflow-plan-validator.js') return { exitCode: 0, ok: true };
    if (path.basename(scriptPath) === 'kaola-workflow-next-action.js') return { exitCode: 0, result: 'ok',
      nextNode: { id: 'current-node', role: 'tdd-guide' }, readySet: [], allDone: false };
    return { exitCode: 0, result: 'ok' };
  };
  const readFile = fpath => {
    if (fpath.endsWith('workflow-plan.md')) return plan;
    if (fpath.endsWith('workflow-state.md')) return makeState();
    throw new Error('ENOENT ' + fpath);
  };
  const oriented = runOrient({
    planPath: '/fake/kaola-workflow/issue-699/workflow-plan.md',
    statePath: '/fake/kaola-workflow/issue-699/workflow-state.md', project: 'issue-699',
    replanFence: committedFence, verifyEpochAuthority: () => ({ ok: true, authority_kind: 'planned' }),
    shell, readFile, writeFile: () => { throw new Error('orient must stay read-only'); },
    cacheExists: () => false,
  });
  assert(oriented.result === 'ok' && oriented.nextAction.nextNode.id === 'current-node'
    && oriented.epochFirstNode && oriented.epochFirstNode.id === 'child-first'
    && oriented.epochFirstNode.role === 'code-explorer',
  '#699 committed orient separates scheduler-current next action from immutable epoch first node, got '
    + JSON.stringify(oriented));

  const beforeRefusal = shellCalls;
  const refused = runOrient({
    planPath: '/fake/kaola-workflow/issue-699/workflow-plan.md',
    statePath: '/fake/kaola-workflow/issue-699/workflow-state.md', project: 'issue-699',
    replanFence: committedFence,
    verifyEpochAuthority: () => ({ ok: false, reason: 'state_planning_evidence_stale_first_node' }),
    shell, readFile, writeFile: () => { throw new Error('refusal must not write'); }, cacheExists: () => false,
  });
  assert(refused.result === 'refuse' && refused.reason === 'state_planning_evidence_stale_first_node',
    '#699 committed orient fails closed on E2 current-authority mismatch');
  assert(shellCalls === beforeRefusal,
    '#699 committed orient authority refusal occurs before validator/next-action/task-mirror shells');
});

// ---------------------------------------------------------------------------
// #847 RESIDUAL — THE DETAIL THE PURE CORE DROPS ON THE FLOOR.
//
// The committed-fence authority refusal above calls:
//
//     replanOrientation(fence, project, { detail })
//
// with a THIRD argument. This file's `replanOrientation(fence, project)` takes TWO. The detail is
// silently discarded — and `detail` is the only field in that envelope that says WHY the kernel
// record could not be read (`EACCES`, a parse error, a missing snapshot). Everything else is
// structure the operator already had.
//
// Nothing catches it today because both neighbours quietly cover for it: the handoff twin's
// `replanOrientation(fence, project, extra)` folds the third argument, and the adaptive-node CLI
// re-attaches the field by hand one line after its own call (`if (authority && authority.detail)
// out.detail = authority.detail;`), never reaching this branch at all — it resolves the authority
// upstream and hands `runOrient` a fence with `current_authority` already set. So the drop is
// live only for the pure-core seam, which is exactly the seam every scenario in this file uses,
// and it is invisible from the CLI. The two hand-written copies of one answer agreeing except
// here is what makes it a drift rather than a decision.
//
// Pinned as an OUTCOME — the detail reaches the caller — not as a signature. Deleting the third
// argument would also make the call self-consistent, and would throw away the only thing in the
// envelope worth reading; the CLI's own hand re-attachment is the evidence that the field is
// wanted, not tolerated.
// ---------------------------------------------------------------------------
scenario(() => {
  const committedFence = { ok: true, fenced: false, committed: true, transaction: {
    child: { plan_hash: 'a'.repeat(64), first_node_id: 'child-first', first_node_role: 'code-explorer' },
  } };
  const orientWith = verifyEpochAuthority => runOrient({
    planPath: '/fake/kaola-workflow/issue-847/workflow-plan.md',
    statePath: '/fake/kaola-workflow/issue-847/workflow-state.md', project: 'issue-847',
    replanFence: committedFence, verifyEpochAuthority,
    shell: () => ({ exitCode: 0 }), readFile: () => { throw new Error('ENOENT'); },
    writeFile: () => { throw new Error('an authority refusal must not write'); },
    cacheExists: () => false,
  });

  // The twin, as the control: the same helper in the handoff script folds its third argument, so
  // "carry the detail out" is an established contract here, not a new demand.
  const twin = require('./kaola-workflow-adaptive-handoff').replanOrientation(
    { ok: false, fenced: true, reason: 'current_epoch_authority_unavailable' }, 'issue-847',
    { detail: 'kernel record unreadable: EACCES' });
  assert(twin.detail === 'kernel record unreadable: EACCES',
    '#847 control: the handoff twin of this helper folds the third argument into its envelope, got '
      + JSON.stringify(twin));

  const thrown = orientWith(() => { throw new Error('kernel record unreadable: EACCES'); });
  assert(thrown.result === 'refuse' && thrown.reason === 'current_epoch_authority_unavailable',
    '#847 precondition: a throwing epoch-authority verifier refuses as unavailable, got ' + JSON.stringify(thrown));
  assert(thrown.detail === 'kernel record unreadable: EACCES',
    '#847: ...carrying the thrown message OUT. `current_epoch_authority_unavailable` is an '
      + 'anchor-read refusal whose whole diagnostic content is that message; an envelope that '
      + 'drops it tells the operator the anchor is unreadable and refuses to say why, got '
      + JSON.stringify(thrown));

  const returned = orientWith(() => ({ ok: false, reason: 'current_epoch_authority_invalid',
    detail: 'snapshot manifest digest does not match .cache/epochs/1' }));
  assert(returned.result === 'refuse' && returned.reason === 'current_epoch_authority_invalid',
    '#847 precondition: a verifier that RETURNS a refusal is projected too, got ' + JSON.stringify(returned));
  assert(returned.detail === 'snapshot manifest digest does not match .cache/epochs/1',
    '#847: ...and its detail survives the same projection — the drop is one call site, so both '
      + 'shapes that reach it lose the same field, got ' + JSON.stringify(returned));
});

// #699: a distinct review outcome may replace a live source only after the
// committed predecessor source is proven by the epoch authority and archived
// byte-for-byte. Every crash boundary converges without overwriting history.
scenario(() => {
  assert(typeof publishRepairReplanSource === 'function',
    '#699 source publication helper is exported for focused transport proof');
  if (typeof publishRepairReplanSource === 'function') {
    const crypto = require('crypto');
    const oldBytes = Buffer.from('{"attempt_id":"review:1","outcome_digest":"old"}\n');
    const nextBytes = Buffer.from('{"attempt_id":"review:2","outcome_digest":"new"}\n');
    const digest = crypto.createHash('sha256').update(oldBytes).digest('hex');
    const transactionId = '7'.repeat(64);
    const receipt = {
      transaction_id: transactionId,
      path: '.cache/replan-sources/' + digest + '.json',
      digest,
      size: oldBytes.length,
    };

    const makeFixture = label => {
      const root = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-699-source-' + label + '-'));
      const cacheDir = path.join(root, '.cache');
      const sourcePath = path.join(cacheDir, 'replan-source.json');
      fs.mkdirSync(cacheDir, { recursive: true });
      fs.writeFileSync(sourcePath, oldBytes);
      return { root, cacheDir, sourcePath };
    };
    const authority = () => ({ ok: true, source_bytes: oldBytes, receipt });
    const publish = (fx, extra) => publishRepairReplanSource(Object.assign({
      sourcePath: fx.sourcePath,
      nextBytes,
      isNextSource: bytes => Buffer.from(bytes).equals(nextBytes),
      resolveCommittedSourceAuthority: authority,
    }, extra || {}));

    for (const boundary of ['after_replan_source_archived', 'after_replan_source_unlinked',
      'after_replan_source_published']) {
      const fx = makeFixture(boundary);
      try {
        let crashed = false;
        try {
          publish(fx, { failpoint: name => { if (name === boundary) throw new Error('crash:' + name); } });
        } catch (error) { crashed = error.message === 'crash:' + boundary; }
        assert(crashed, '#699 source publication reaches crash boundary ' + boundary);
        const historyPath = path.join(fx.root, ...receipt.path.split('/'));
        assert(fs.existsSync(historyPath) && fs.readFileSync(historyPath).equals(oldBytes),
          '#699 ' + boundary + ': predecessor history is durable and byte-exact');
        const retried = publish(fx);
        assert(retried.ok === true && retried.rotated_from
          && retried.rotated_from.digest === digest
          && fs.readFileSync(fx.sourcePath).equals(nextBytes),
        '#699 ' + boundary + ': retry publishes the exact successor and returns its history link');
        assert(fs.readFileSync(historyPath).equals(oldBytes),
          '#699 ' + boundary + ': retry never overwrites predecessor history');
      } finally { fs.rmSync(fx.root, { recursive: true, force: true }); }
    }

    const conflict = makeFixture('conflict');
    try {
      fs.writeFileSync(conflict.sourcePath, Buffer.from('{"attacker":true}\n'));
      const before = fs.readFileSync(conflict.sourcePath);
      const refused = publish(conflict);
      assert(refused.ok === false && refused.reason === 'replan_source_conflict'
        && fs.readFileSync(conflict.sourcePath).equals(before),
      '#699 an unproven live source refuses without overwrite');
    } finally { fs.rmSync(conflict.root, { recursive: true, force: true }); }

    const collision = makeFixture('history-collision');
    try {
      const historyPath = path.join(collision.root, ...receipt.path.split('/'));
      fs.mkdirSync(path.dirname(historyPath), { recursive: true });
      fs.writeFileSync(historyPath, Buffer.from('tampered\n'));
      const before = fs.readFileSync(collision.sourcePath);
      const refused = publish(collision);
      assert(refused.ok === false && refused.reason === 'replan_source_history_mismatch'
        && fs.readFileSync(collision.sourcePath).equals(before),
      '#699 a colliding source-history receipt refuses before unlink/publication');
    } finally { fs.rmSync(collision.root, { recursive: true, force: true }); }
}
});
// ===========================================================================
// Reviewer contract v2 conformance corpus. This is intentionally data-driven:
// the JSON is the cross-runtime issue matrix, while these assertions prove that
// every lifecycle consumer uses the same pure schema functions.
// ===========================================================================
scenario(() => {
  const reviewSchema = require('./kaola-workflow-adaptive-schema');
  const fixture = JSON.parse(fs.readFileSync(path.join(__dirname, 'reviewer-conformance-fixtures.json'), 'utf8'));
  const requiredCoverage = [
    'issue_matrices', 'v1_v2_split', 'malformed_identity', 'mismatched_identity',
    'investigation_completion', 'change_gate_failure', 'finding_anchors',
    'finding_uid_collision', 'strict_progress', 'sequence_reducer',
    'replicated_majority_reducer', 'partitioned_all_reducer',
    'g4_common_certifier', 'validation_pass', 'validation_fail',
    'validation_inconclusive', 'validation_drift',
  ];
  for (const token of requiredCoverage) {
    assert(fixture.coverage.includes(token), 'review-v2 corpus covers ' + token);
  }

  const requiredFunctions = [
    'canonicalJson', 'deriveGateMode', 'requiredReviewTokens', 'deriveGateEffect',
    'buildReviewContext', 'validateReviewEvidenceBinding', 'normalizeFindingAnchor',
    'computeFindingUid', 'normalizeFindingSet', 'reduceReviewReceipts',
    'normalizeResolutionSet', 'deriveRepairDelta', 'validateRepairDelta',
    'assessFindingClosure', 'compareValidationObligations', 'assessReviewProgress',
  ];
  const apiReady = requiredFunctions.every(name => typeof reviewSchema[name] === 'function');
  for (const name of requiredFunctions) {
    assert(typeof reviewSchema[name] === 'function', 'review-v2 exports pure ' + name);
  }

  if (apiReady) {
    for (const row of fixture.gate_modes) {
      const node = row.plan.nodes.find(n => n.id === row.node_id);
      assert(reviewSchema.deriveGateMode(row.plan, node) === row.expected,
        'review-v2 deriveGateMode: ' + row.name);
    }

    const changePlan = fixture.gate_modes[0].plan;
    const changeNode = changePlan.nodes.find(n => n.id === 'av');
    const investigationPlan = fixture.gate_modes[1].plan;
    const investigationNode = investigationPlan.nodes.find(n => n.id === 'av');
    const baseTokens = ['evidence-binding', 'contract_version', 'review_context_hash',
      'behavior_contract_hash', 'resolved_profile_hash', 'candidate_digest', 'domain_outcome'];
    const investigationTokens = reviewSchema.requiredReviewTokens(investigationPlan, investigationNode);
    const changeTokens = reviewSchema.requiredReviewTokens(changePlan, changeNode);
    assert(baseTokens.every(t => investigationTokens.includes(t)) && investigationTokens.includes('claim_outcome'),
      'review-v2 investigation tokens derive from the shared gate classifier');
    assert(changeTokens.includes('gate_mode') && changeTokens.includes('gate_claim')
      && changeTokens.includes('gate_surface') && changeTokens.includes('gate_aggregation'),
      'review-v2 change-gate tokens derive from the shared gate classifier');

    for (const row of fixture.outcomes) {
      const got = reviewSchema.deriveGateEffect(row.role, row.gate_mode, row.domain_outcome,
        row.blocking_findings || 0);
      assert(got === row.expected_gate_effect,
        'review-v2 three-axis gate effect for ' + row.role + '/' + row.gate_mode + '/' + row.domain_outcome);
    }

    const contextInput = {
      contract_version: 2,
      behavior_contract_version: 2,
      behavior_contract_hash: '1'.repeat(64),
      plan_schema_version: 2,
      plan_hash: '2'.repeat(64),
      claim_identity_digest: '3'.repeat(64),
      epoch_lineage_id: '4'.repeat(64),
      epoch: 1,
      logical_gate: {
        key: 'gate', kind: 'sequence', members: ['av'], claim_digest: '5'.repeat(64),
        surface_digests: ['6'.repeat(64)], aggregation: 'sequence', certified_producers: ['writer'],
      },
      gate_mode: 'change_gate',
      claim_root_base: { commit: 'a'.repeat(40), digest: '7'.repeat(64) },
      candidate_digest: '8'.repeat(64),
      inherited_frontier: { digest: 'none', classes: [] },
      scope_lineage_id: '9'.repeat(64),
      review_phase: 'discovery', attempt_ordinal: 1,
      acceptance_evidence: [{ kind: 'test', digest: 'a'.repeat(64) }],
      prior_findings: [], repair_delta: null, validation_obligations: [],
    };
    const contextA = reviewSchema.buildReviewContext(contextInput);
    const contextB = reviewSchema.buildReviewContext(JSON.parse(JSON.stringify(contextInput)));
    assert(contextA.ok === true && contextA.context_hash === contextB.context_hash
      && contextA.bytes === contextB.bytes,
      'review-v2 runtime-neutral context is canonical and deterministic');
    assert(!Object.prototype.hasOwnProperty.call(contextA.context, 'resolved_profile_hash')
      && !Object.prototype.hasOwnProperty.call(contextA.context, 'runtime'),
      'review-v2 context excludes runtime/profile identity');

    const dispatchIdentity = {
      contract_version: 2, review_context_hash: contextA.context_hash,
      behavior_contract_hash: contextInput.behavior_contract_hash,
      resolved_profile_hash: 'b'.repeat(64), candidate_digest: contextInput.candidate_digest,
    };
    const boundEvidence = { ...dispatchIdentity };
    assert(reviewSchema.validateReviewEvidenceBinding(boundEvidence, dispatchIdentity, contextA.context).ok === true,
      'review-v2 exact dispatch/context/candidate/profile binding passes');
    assert(reviewSchema.validateReviewEvidenceBinding({ ...boundEvidence, candidate_digest: 'c'.repeat(64) },
      dispatchIdentity, contextA.context).reason === 'review_candidate_mismatch',
      'review-v2 stale candidate refuses before finding normalization');
    assert(reviewSchema.validateReviewEvidenceBinding({ ...boundEvidence, resolved_profile_hash: 'd'.repeat(64) },
      dispatchIdentity, contextA.context).reason === 'review_profile_mismatch',
      'review-v2 stale profile refuses before finding normalization');

    const scope = 'e'.repeat(64);
    const normalizedAnchors = fixture.anchors.map(anchor => reviewSchema.normalizeFindingAnchor(anchor));
    assert(normalizedAnchors.every(r => r.ok === true), 'review-v2 all five immutable anchor variants normalize');
    const anchorIndex = {
      object_format: 'sha1', candidate_tree_digest: '1'.repeat(64),
      parent_candidate_digest: 'b'.repeat(64),
      candidate_entries: {
        'src/a.js': { object_format: 'sha1', tree_mode: '100644',
          object_id: 'a'.repeat(40), blob_length: 12 },
        'bin/tool': { object_format: 'sha1', tree_mode: '100755', object_id: 'e'.repeat(40) },
      },
      base_entries: {
        'src/deleted.js': { object_format: 'sha1', tree_mode: '100644',
          object_id: 'c'.repeat(40), blob_length: 8 },
        'bin/tool': { object_format: 'sha1', tree_mode: '100644', object_id: 'e'.repeat(40) },
      },
      evidence_digests: ['2'.repeat(64)],
    };
    assert(reviewSchema.normalizeFindingAnchor(fixture.anchors[0], { anchor_index: anchorIndex }).ok === true,
      'review-v2 candidate range must byte-match the authoritative Git candidate index');
    assert(reviewSchema.normalizeFindingAnchor({ ...fixture.anchors[0], path: '../src/a.js' }).reason
      === 'finding_anchor_path_invalid', 'review-v2 traversal anchor refuses');
    assert(reviewSchema.normalizeFindingAnchor({ ...fixture.anchors[0], object_format: 'sha256' }).reason
      === 'finding_anchor_candidate_range_invalid', 'review-v2 object-format/object-id mismatch refuses');
    assert(reviewSchema.normalizeFindingAnchor({ ...fixture.anchors[0], end: 13 }, { anchor_index: anchorIndex }).reason
      === 'finding_anchor_candidate_mismatch', 'review-v2 byte range beyond authoritative blob length refuses');
    assert(reviewSchema.normalizeFindingAnchor({ ...fixture.anchors[1], parent_candidate_digest: 'a'.repeat(64) },
      { anchor_index: anchorIndex }).reason === 'finding_parent_candidate_mismatch',
      'review-v2 deleted range must bind the exact parent candidate');
    assert(reviewSchema.normalizeFindingAnchor(fixture.anchors[2], { anchor_index: anchorIndex }).ok === true,
      'review-v2 mode-only tree-entry change matches exact base/candidate entries');
    assert(reviewSchema.normalizeFindingAnchor({ ...fixture.anchors[3], path: 'src/a.js' },
      { anchor_index: anchorIndex }).reason === 'finding_required_absence_present',
      'review-v2 required-absence anchor refuses a present candidate path');
    assert(reviewSchema.normalizeFindingAnchor({ ...fixture.anchors[4], producer_evidence_digest: '3'.repeat(64) },
      { anchor_index: anchorIndex }).reason === 'finding_evidence_observation_unbound',
      'review-v2 evidence observation must bind an authoritative producer receipt digest');
    const uidA = reviewSchema.computeFindingUid(scope, normalizedAnchors[0].anchor);
    const uidB = reviewSchema.computeFindingUid(scope, normalizedAnchors[0].anchor);
    assert(uidA === uidB && /^[0-9a-f]{64}$/.test(uidA), 'review-v2 finding UID is canonical and proof-independent');
    const findingBase = {
      failure_class: 'correctness',
      trigger: { precondition_digest: '1'.repeat(64), input_digest: '2'.repeat(64), expected_digest: '3'.repeat(64), observed_digest: '4'.repeat(64) },
      primary_anchor: fixture.anchors[0], secondary_anchors: [], severity: 'high',
      scope: 'in_scope', action: 'fix', status: 'open', fix_role: 'tdd-guide', proof_digest: '5'.repeat(64),
    };
    const setOk = reviewSchema.normalizeFindingSet([findingBase, { ...findingBase, proof_digest: '6'.repeat(64) }], { scope_lineage_id: scope });
    assert(setOk.ok === true && setOk.findings.length === 1,
      'review-v2 identical immutable UID consolidates while proof churn cannot create identity');
    const collision = reviewSchema.normalizeFindingSet([findingBase,
      { ...findingBase, failure_class: 'security' }], { scope_lineage_id: scope });
    assert(collision.ok === false && collision.reason === 'finding_uid_collision',
      'review-v2 conflicting immutable fields at one UID refuse collision');
    // R6 — a MOVE keeps identity (primary anchor alone determines the UID; the new location rides as a
    // secondary anchor), and secondary-anchor INPUT ORDER is canonicalized to one byte-sorted set. The
    // identity baseline is findingBase's own normalizeFindingSet UID (the authoritative producer), which
    // adding secondary anchors must not change.
    const baseUid = setOk.findings[0].uid;
    const secA = { ...fixture.anchors[0], path: 'src/moved.js' };
    const secB = { ...fixture.anchors[0], start: 0, end: 2 };
    const movedForward = reviewSchema.normalizeFindingSet(
      [{ ...findingBase, secondary_anchors: [secA, secB] }], { scope_lineage_id: scope });
    const movedReversed = reviewSchema.normalizeFindingSet(
      [{ ...findingBase, secondary_anchors: [secB, secA] }], { scope_lineage_id: scope });
    assert(movedForward.ok === true && movedReversed.ok === true
      && movedForward.findings[0].uid === baseUid && movedReversed.findings[0].uid === baseUid,
      'review-v2 R6: a move keeps the primary-anchor UID; a new location is only secondary evidence');
    assert(movedForward.findings[0].secondary_anchors.length === 2
      && JSON.stringify(movedForward.findings[0].secondary_anchors)
        === JSON.stringify(movedReversed.findings[0].secondary_anchors),
      'review-v2 R6: multiple secondary anchors canonicalize to one byte-sorted order regardless of input order');

    const previousAttempt = {
      attempt_id: 'review2-gate:1', outcome: 'fail', lifecycle_settled: true,
      candidate_digest: 'a'.repeat(64),
      candidate_declared: { 'src/a.js': '100644 ' + '1'.repeat(40) },
      repair: { selected_writer: 'writer', settled: true }, consumed_by: 'writer', rebind: [],
    };
    const repairDelta = reviewSchema.deriveRepairDelta({
      previous_attempt: previousAttempt,
      current_candidate: { digest: 'b'.repeat(64),
        declared: { 'src/a.js': '100644 ' + '2'.repeat(40) },
        residue_digest: 'c'.repeat(64) },
    });
    assert(repairDelta.ok === true && repairDelta.repair_delta.paths.length === 1
      && repairDelta.repair_delta.paths[0].path === 'src/a.js',
      'review-v2 repair delta is the exact before/after declared-path partition');
    const regressionBase = { ...findingBase,
      trigger: { ...findingBase.trigger, observed_digest: '7'.repeat(64) }, status: 'open' };
    const regression = reviewSchema.normalizeFindingSet([regressionBase], { scope_lineage_id: scope });
    const priorOpenFinding = { ...setOk.findings[0], status: 'open' };
    const admitted = reviewSchema.assessFindingClosure({
      prior_findings: [priorOpenFinding],
      current_findings: [{ ...priorOpenFinding, status: 'resolved' }, regression.findings[0]],
      repair_delta: repairDelta.repair_delta, candidate_digest: 'b'.repeat(64),
    });
    assert(admitted.ok === true && admitted.scope_expanded === false
      && admitted.repair_delta_uids.length === 1,
      'review-v2 closure admits a new blocker only when an immutable anchor intersects repair delta');
    const outside = reviewSchema.normalizeFindingSet([{ ...regressionBase, primary_anchor: fixture.anchors[2] }],
      { scope_lineage_id: scope });
    const expanded = reviewSchema.assessFindingClosure({
      prior_findings: [priorOpenFinding],
      current_findings: [{ ...priorOpenFinding, status: 'open' }, outside.findings[0]],
      repair_delta: repairDelta.repair_delta, candidate_digest: 'b'.repeat(64),
    });
    assert(expanded.ok === true && expanded.scope_expanded === true && expanded.expanded_uids.length === 1,
      'review-v2 blocker outside the repair delta is classified as durable scope expansion');
    const missingPrior = reviewSchema.assessFindingClosure({
      prior_findings: [priorOpenFinding], current_findings: [],
      repair_delta: repairDelta.repair_delta, candidate_digest: 'b'.repeat(64),
    });
    assert(missingPrior.ok === false && missingPrior.reason === 'review_prior_uid_missing',
      'review-v2 closure cannot omit a prior UID');
    const boundVectorDigest = '8'.repeat(64);
    const boundEvidenceDigest = '9'.repeat(64);
    const resolutionBinding = { repair_attempt_id: previousAttempt.attempt_id, candidate_digest: 'b'.repeat(64),
      known_validation_vector_digests: [boundVectorDigest], known_evidence_digests: [boundEvidenceDigest] };
    const resolution = reviewSchema.normalizeResolutionSet([{
      uid: uidA, repair_attempt_id: previousAttempt.attempt_id,
      validation_vector_digest: boundVectorDigest, evidence_digest: boundEvidenceDigest,
      candidate_digest: 'b'.repeat(64),
    }], resolutionBinding);
    assert(resolution.ok === true && resolution.resolutions[0].uid === uidA,
      'review-v2 resolution proof is closed-shape and bound to repair plus current candidate');
    const fabricatedVector = reviewSchema.normalizeResolutionSet([{
      uid: uidA, repair_attempt_id: previousAttempt.attempt_id,
      validation_vector_digest: 'e'.repeat(64), evidence_digest: boundEvidenceDigest,
      candidate_digest: 'b'.repeat(64),
    }], resolutionBinding);
    assert(fabricatedVector.ok === false && fabricatedVector.reason === 'review_resolution_vector_unbound',
      'review-v2 a well-formed but unbound validation-vector digest fails closed (anti-laundering)');
    const fabricatedEvidence = reviewSchema.normalizeResolutionSet([{
      uid: uidA, repair_attempt_id: previousAttempt.attempt_id,
      validation_vector_digest: boundVectorDigest, evidence_digest: 'e'.repeat(64),
      candidate_digest: 'b'.repeat(64),
    }], resolutionBinding);
    assert(fabricatedEvidence.ok === false && fabricatedEvidence.reason === 'review_resolution_evidence_unbound',
      'review-v2 a well-formed but unbound evidence digest fails closed (anti-laundering)');
    const artifacts = reviewSchema.authoritativeResolutionArtifacts([
      { candidate_digest: 'b'.repeat(64), outcome: 'pass', vector_id: boundVectorDigest, receipt_sha256: boundEvidenceDigest },
      { candidate_digest: 'a'.repeat(64), outcome: 'pass', vector_id: 'c'.repeat(64), receipt_sha256: 'd'.repeat(64) },
    ], 'b'.repeat(64));
    assert(JSON.stringify(artifacts.validation_vector_digests) === JSON.stringify([boundVectorDigest])
      && JSON.stringify(artifacts.evidence_digests) === JSON.stringify([boundEvidenceDigest]),
      'review-v2 authoritative resolution artifacts admit only current-candidate pass vectors');
    assert(reviewSchema.isCanonicalBlobMap({ sha256: '100644 ' + 'a'.repeat(64) }) === true,
      'review-v2 candidate partitions accept repository-native sha256 object ids');

    for (const row of fixture.reducers) {
      const got = reviewSchema.reduceReviewReceipts(row.input);
      assert(got.complete === row.expected.complete && got.gate_effect === row.expected.gate_effect
        && got.domain_outcome === row.expected.domain_outcome,
        'review-v2 reducer: ' + row.name + ' got=' + JSON.stringify(got));
    }
    for (const row of fixture.validation) {
      const got = reviewSchema.compareValidationObligations(row.obligations, row.vectors, row.current_candidate_digest);
      assert(got.status === row.expected, 'review-v2 validation vector comparison: ' + row.name
        + ' got=' + JSON.stringify(got));
    }
    // R2 regression through the real runner: two passing vectors for the SAME command over DIFFERENT
    // candidates have different vector ids, yet an inherited obligation is satisfied by the current-candidate
    // pass. Exact vector-id equality would force every repair into non-progress.
    {
      const runner = require('./kaola-workflow-validation-runner');
      const execIdentity = { comparable: true, digest: 'a1'.repeat(32), incomparability_classes: [] };
      const buildPass = candidateDigest => runner.buildValidationVector({
        command_id: 'c0'.repeat(32), candidate_digest: candidateDigest, execution_identity: execIdentity,
        runs: [{ index: 0, exit_code: 0, signal: null, timed_out: false,
          pre_candidate_digest: candidateDigest, post_candidate_digest: candidateDigest,
          execution_identity_digest: execIdentity.digest, failure_signature_sha256: '0'.repeat(64) }],
      }, []);
      const vectorA = buildPass('a'.repeat(64));
      const vectorB = buildPass('b'.repeat(64));
      assert(vectorA.vector_id !== vectorB.vector_id && vectorA.command_id === vectorB.command_id
        && vectorA.outcome === 'pass' && vectorB.outcome === 'pass',
        'review-v2 R2: candidate-bound vectors share command_id but differ in vector_id across candidates');
      const inherited = [{ command_id: vectorA.command_id, required_pass_vector_id: vectorA.vector_id }];
      const repaired = reviewSchema.compareValidationObligations(inherited, [vectorB], 'b'.repeat(64));
      assert(repaired.status === 'pass' && repaired.matched[0].current_pass_vector_id === vectorB.vector_id
        && repaired.matched[0].required_pass_vector_id === vectorA.vector_id,
        'review-v2 R2: an inherited obligation is satisfied by a comparable current-candidate pass after repair');
      const staleOnly = reviewSchema.compareValidationObligations(inherited, [vectorA], 'b'.repeat(64));
      assert(staleOnly.status === 'drift' && staleOnly.reason === 'validation_candidate_drift',
        'review-v2 R2: a pass bound only to the prior candidate does not satisfy the current obligation');
      const missingBuild = runner.buildValidationVector({
        command_id: 'c0'.repeat(32), candidate_digest: 'b'.repeat(64), execution_identity: execIdentity,
        runs: [{ index: 0, exit_code: 1, signal: null, timed_out: false,
          pre_candidate_digest: 'b'.repeat(64), post_candidate_digest: 'b'.repeat(64),
          execution_identity_digest: execIdentity.digest, failure_signature_sha256: '1'.repeat(64) }],
      }, []);
      const failCurrent = reviewSchema.compareValidationObligations(inherited, [missingBuild], 'b'.repeat(64));
      assert(failCurrent.status === 'fail' && failCurrent.reason === 'validation_failed',
        'review-v2 R2: a failing current-candidate vector is non-progress, not accepted');
    }
    // R6 — durable, data-driven negative fixtures for the schema-2 validation policy parser. Each row is a
    // real ## Meta snippet through the REAL parseValidationPolicy; a regression in any typed refusal reds here.
    if (Array.isArray(fixture.validation_policy) && typeof planValidator.parseValidationPolicy === 'function') {
      const policyPlan = metaLines => [
        '# Workflow Plan — policy fixture', '', '## Meta',
        'plan_schema_version: 2', 'labels: area:scripts', 'validation_command: node --check lib/impl.js',
        ...metaLines, '',
        '## Nodes', '',
        '| id | role | depends_on | declared_write_set | cardinality | shape |',
        '|---|---|---|---|---|---|',
        '| a | code-explorer | — | — | 1 | sequence |',
        '| finalize | finalize | a | — | 1 | sequence |', '',
        '## Node Ledger', '', '| id | status |', '|---|---|',
        '| a | pending |', '| finalize | pending |', '',
      ].join('\n');
      for (const row of fixture.validation_policy) {
        const got = planValidator.parseValidationPolicy(policyPlan(row.meta));
        if (row.expected_ok) {
          assert(got.ok === true && got.source === 'schema-2',
            'review-v2 R6 validation policy accepts: ' + row.name + ' got=' + JSON.stringify(got));
        } else {
          assert(got.ok === false && got.reason === row.expected_reason,
            'review-v2 R6 validation policy refuses: ' + row.name + ' expected=' + row.expected_reason
              + ' got=' + JSON.stringify(got));
        }
      }
    }

    const priorUid = uidA;
    const progressResolution = { uid: priorUid, repair_attempt_id: 'repair:1',
      validation_vector_digest: '1'.repeat(64), evidence_digest: '2'.repeat(64), candidate_digest: '3'.repeat(64) };
    const progress = reviewSchema.assessReviewProgress({
      previous_open_uids: [priorUid], current_open_uids: [],
      resolutions: [progressResolution],
      known_validation_vector_digests: ['1'.repeat(64)], known_evidence_digests: ['2'.repeat(64)],
      repair_attempt_id: 'repair:1', candidate_digest: '3'.repeat(64),
      validation: { status: 'pass' }, previous_consecutive_nonprogress: 0,
    });
    assert(progress.progress === true && progress.stop_reason === null,
      'review-v2 strict progress requires resolution proof, smaller frontier, and inherited validation pass');
    const unboundProgress = reviewSchema.assessReviewProgress({
      previous_open_uids: [priorUid], current_open_uids: [],
      resolutions: [progressResolution],
      known_validation_vector_digests: ['a'.repeat(64)], known_evidence_digests: ['2'.repeat(64)],
      repair_attempt_id: 'repair:1', candidate_digest: '3'.repeat(64),
      validation: { status: 'pass' }, previous_consecutive_nonprogress: 0,
    });
    assert(unboundProgress.progress === false && unboundProgress.reason === 'review_resolution_proof_missing',
      'review-v2 a fabricated resolution digest cannot count a UID off the frontier as progress');
    const nonprogress = reviewSchema.assessReviewProgress({
      previous_open_uids: [priorUid], current_open_uids: [priorUid], resolutions: [],
      repair_attempt_id: 'repair:2', candidate_digest: '4'.repeat(64),
      before_candidate_digest: '3'.repeat(64), logical_gate_key: 'gate', scope_lineage_id: scope,
      validation: { status: 'inconclusive' }, previous_consecutive_nonprogress: 1,
    });
    assert(nonprogress.progress === false && nonprogress.stop_reason === 'review_nonconvergent'
      && nonprogress.consecutive_nonprogress === 2,
      'review-v2 two unique consecutive nonprogress repairs stop while preserving the five-repair cap');
    const replay = reviewSchema.assessReviewProgress({
      previous_open_uids: [priorUid], current_open_uids: [priorUid], resolutions: [],
      repair_attempt_id: 'repair:2', before_candidate_digest: '3'.repeat(64),
      candidate_digest: '4'.repeat(64), logical_gate_key: 'gate', scope_lineage_id: scope,
      validation: { status: 'inconclusive' }, previous_consecutive_nonprogress: 1,
      seen_idempotency_keys: [nonprogress.idempotency_key],
    });
    assert(replay.reason === 'review_progress_replay' && replay.consecutive_nonprogress === 1,
      'review-v2 crash replay cannot increment the nonprogress counter twice');
  }

  assert(typeof planValidator.resolvePlanContract === 'function', 'review-v2 validator exports resolvePlanContract');
  assert(typeof planValidator.buildPlanView === 'function', 'review-v2 validator exports buildPlanView');
  assert(typeof planValidator.parseValidationPolicy === 'function', 'review-v2 validator exports parseValidationPolicy');
  if (typeof planValidator.resolvePlanContract === 'function') {
    const legacyBody = makePlan(['| explore | pending | |', '| finalize | pending | |'], [
      '| explore | code-explorer | — | — | 1 | sequence |',
      '| finalize | finalize | explore | CHANGELOG.md | 1 | sequence |',
    ]);
    const legacyFrozen = '<!-- plan_hash: ' + planValidator.computePlanHash(legacyBody) + ' -->\n' + legacyBody;
    const legacyContract = planValidator.resolvePlanContract(legacyFrozen, { requireFrozen: true });
    assert(legacyContract.ok === true && legacyContract.plan_schema_version === 1
      && legacyContract.contract_version === 1,
      'review-v2 verified field-absent frozen plan maps explicitly to v1');
    const missingDraft = planValidator.freezePlan(legacyBody, {});
    assert(missingDraft.result === 'refuse' && missingDraft.reason === 'plan_schema_version_missing',
      'review-v2 newly frozen field-absent draft refuses before spawn');
    const v1Draft = planValidator.freezePlan(legacyBody.replace('labels:', 'plan_schema_version: 1\nlabels:'), {});
    assert(v1Draft.result === 'refuse' && v1Draft.reason === 'plan_schema_version_legacy_new',
      'review-v2 newly authored explicit v1 draft refuses before spawn');
  }
});

// #717 + #712: reviewer runtime detection + profile path resolution across install layouts.
// Every fixture is synthesized under $TMPDIR (never in the repo): the canonical support script
// and its two self-contained siblings are copied into each synthesized layout, and every probe
// runs in a subprocess so the copy's __dirname / env match a real consumer invocation (the K9
// pattern from test-kimi-edition.js). HOME always points at a hermetic temp dir so the real
// ~/.claude/agents can never leak into a probe.
scenario(() => {
  const { spawnSync } = require('child_process');
  const LAYOUT_SIBLINGS = ['kaola-workflow-adaptive-node.js', 'kaola-workflow-adaptive-schema.js',
    'kaola-workflow-codex-preflight.js'];
  const GATE_ROLES = ['code-reviewer', 'security-reviewer', 'adversarial-verifier'];
  const layoutTmp = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'kw-reviewer-layout-')));
  const seedScripts = scriptsDir => {
    fs.mkdirSync(scriptsDir, { recursive: true });
    for (const name of LAYOUT_SIBLINGS) {
      fs.copyFileSync(path.join(__dirname, name), path.join(scriptsDir, name));
    }
  };
  const probeReviewer = (scriptsDir, role, extraEnv) => {
    const script = 'const m=require(' + JSON.stringify(path.join(scriptsDir, 'kaola-workflow-adaptive-node.js')) + ');'
      + 'const r=m.resolveReviewerProfileIdentity(' + JSON.stringify(role) + ',{});'
      + 'console.log(JSON.stringify({ok:r.ok,reason:r.reason||null,runtime:r.runtime||null,'
      + 'hash:r.resolved_profile_hash||null,path:r.profile_path||null}));';
    const env = Object.assign({}, process.env);
    delete env.KAOLA_WORKFLOW_RUNTIME;
    delete env.KIMI_CODE_HOME;
    delete env.KAOLA_AGENT_DIR;
    env.HOME = path.join(layoutTmp, 'hermetic-home');
    Object.assign(env, extraEnv || {});
    // A HERMETIC probe: the runtime env vars are deleted and HOME is repointed, so what is
    // under test is resolution against a fresh environment. In-process this cannot be done
    // honestly — the parent's own HOME and require cache are already resolved.
    // spawn-class: environment
    const r = spawnSync(process.execPath, ['-e', script], { cwd: layoutTmp, env, encoding: 'utf8' });
    try { return JSON.parse(String(r.stdout).trim()); }
    catch (_) { return { ok: false, reason: 'probe_crash: ' + String(r.stderr || r.stdout).split('\n')[0] }; }
  };
  // Re-stamp a markdown profile's resolved_profile_hash after a content mutation (same zeroed-self
  // scheme the runtime verifies), so synthesized fixture profiles stay self-consistently signed.
  const resignProfile = source => {
    const matches = [...source.matchAll(/^resolved_profile_hash:\s*([0-9a-f]{64})\s*$/gm)];
    assert(matches.length === 1, '#712/#717 fixture profile carries exactly one resolved_profile_hash');
    const current = matches[0][1];
    const offset = matches[0].index + matches[0][0].indexOf(current);
    const normalized = source.slice(0, offset) + '0'.repeat(64) + source.slice(offset + 64);
    const digest = require('crypto').createHash('sha256').update(normalized).digest('hex');
    return normalized.slice(0, offset) + digest + normalized.slice(offset + 64);
  };
  try {
    fs.mkdirSync(path.join(layoutTmp, 'hermetic-home'), { recursive: true });

    // #717 — exact installed Codex plugin cache tuples for all three forge editions:
    //   plugins/cache/<marketplace>/<edition>/<version>/scripts (+ agents/<role>.toml siblings).
    for (const [marketplace, editionDir, pluginTree] of [
      ['kaolabrother-kaola-workflow', 'kaola-workflow', 'kaola-workflow'],
      ['kaolabrother-kaola-workflow', 'kaola-workflow-gitlab', 'kaola-workflow-gitlab'],
      ['kaolabrother-kaola-workflow', 'kaola-workflow-gitea', 'kaola-workflow-gitea'],
    ]) {
      const versionRoot = path.join(layoutTmp, 'codex-cache-' + editionDir,
        'plugins', 'cache', marketplace, editionDir, '4.23.1');
      const scriptsDir = path.join(versionRoot, 'scripts');
      seedScripts(scriptsDir);
      const agentsDir = path.join(versionRoot, 'agents');
      fs.mkdirSync(agentsDir, { recursive: true });
      for (const role of GATE_ROLES) {
        fs.copyFileSync(path.join(__dirname, '..', 'plugins', pluginTree, 'agents', role + '.toml'),
          path.join(agentsDir, role + '.toml'));
        const p = probeReviewer(scriptsDir, role);
        assert(p.ok === true && p.runtime === 'codex'
            && p.path === path.join(agentsDir, role + '.toml'),
          '#717[' + editionDir + ']: installed Codex cache tuple resolves ' + role
            + ' to runtime codex bound to the exact active edition TOML — got ' + JSON.stringify(p));
      }
    }

    // #717 — the source-tree codex layout keeps current behavior (regression guard).
    {
      const versionRoot = path.join(layoutTmp, 'codex-source-tree', 'plugins', 'kaola-workflow');
      const scriptsDir = path.join(versionRoot, 'scripts');
      seedScripts(scriptsDir);
      const agentsDir = path.join(versionRoot, 'agents');
      fs.mkdirSync(agentsDir, { recursive: true });
      fs.copyFileSync(path.join(__dirname, '..', 'plugins', 'kaola-workflow', 'agents', 'code-reviewer.toml'),
        path.join(agentsDir, 'code-reviewer.toml'));
      const p = probeReviewer(scriptsDir, 'code-reviewer');
      assert(p.ok === true && p.runtime === 'codex' && p.path === path.join(agentsDir, 'code-reviewer.toml'),
        '#717[source-tree]: source-tree codex layout detection is unchanged — got ' + JSON.stringify(p));
    }

    // #717 — the explicit KAOLA_WORKFLOW_RUNTIME override stays authoritative with NO path hints
    // (an unrecognizable layout resolves codex purely from the override).
    {
      const strayRoot = path.join(layoutTmp, 'override-wins');
      const scriptsDir = path.join(strayRoot, 'scripts');
      seedScripts(scriptsDir);
      const agentsDir = path.join(strayRoot, 'agents');
      fs.mkdirSync(agentsDir, { recursive: true });
      fs.copyFileSync(path.join(__dirname, '..', 'plugins', 'kaola-workflow', 'agents', 'code-reviewer.toml'),
        path.join(agentsDir, 'code-reviewer.toml'));
      const p = probeReviewer(scriptsDir, 'code-reviewer', { KAOLA_WORKFLOW_RUNTIME: 'codex' });
      assert(p.ok === true && p.runtime === 'codex' && p.path === path.join(agentsDir, 'code-reviewer.toml'),
        '#717[override]: KAOLA_WORKFLOW_RUNTIME=codex wins without any path hints — got ' + JSON.stringify(p));
      // …and over the strongest path hint (a versioned cache layout still obeys an explicit claude).
      const cacheScripts = path.join(layoutTmp, 'override-beats-cache',
        'plugins', 'cache', 'kaolabrother-kaola-workflow', 'kaola-workflow', '4.23.1', 'scripts');
      seedScripts(cacheScripts);
      const p2 = probeReviewer(cacheScripts, 'code-reviewer', { KAOLA_WORKFLOW_RUNTIME: 'claude' });
      assert(p2.ok === false && p2.reason === 'review_profile_unavailable',
        '#717[override-beats-cache]: explicit claude override wins over a codex cache layout — got ' + JSON.stringify(p2));
    }

    // #717 — an unrecognized layout with no profiles anywhere keeps falling through and fails
    // closed as review_profile_unavailable (never a loose-match wrong-runtime binding).
    {
      const scriptsDir = path.join(layoutTmp, 'mystery-layout', 'scripts');
      seedScripts(scriptsDir);
      const p = probeReviewer(scriptsDir, 'code-reviewer',
        { KAOLA_AGENT_DIR: path.join(layoutTmp, 'empty-agents') });
      assert(p.ok === false && p.reason === 'review_profile_unavailable',
        '#717[fail-closed]: unknown layout with a genuinely absent profile refuses fail-closed — got ' + JSON.stringify(p));
    }

    // #712 — claude native install: profiles at $KAOLA_AGENT_DIR/<role>.md resolve for all three
    // gate roles through the claude runtime.
    {
      const claudeHome = path.join(layoutTmp, 'claude-home');
      const scriptsDir = path.join(claudeHome, '.claude', 'kaola-workflow', 'scripts');
      seedScripts(scriptsDir);
      const nativeAgents = path.join(layoutTmp, 'claude-native-agents');
      fs.mkdirSync(nativeAgents, { recursive: true });
      for (const role of GATE_ROLES) {
        fs.copyFileSync(path.join(__dirname, '..', 'agents', role + '.md'),
          path.join(nativeAgents, role + '.md'));
        const p = probeReviewer(scriptsDir, role, { HOME: claudeHome, KAOLA_AGENT_DIR: nativeAgents });
        assert(p.ok === true && p.runtime === 'claude' && p.path === path.join(nativeAgents, role + '.md'),
          '#712[native]: claude install resolves ' + role
            + ' from the native agent dir — got ' + JSON.stringify(p));
      }
    }

    // #712 — claude native default: without KAOLA_AGENT_DIR the native location is
    // ~/.claude/agents/<role>.md (the install.sh default AGENTS_DIR).
    {
      const claudeHome = path.join(layoutTmp, 'claude-home-default');
      const scriptsDir = path.join(claudeHome, '.claude', 'kaola-workflow', 'scripts');
      seedScripts(scriptsDir);
      const nativeAgents = path.join(claudeHome, '.claude', 'agents');
      fs.mkdirSync(nativeAgents, { recursive: true });
      fs.copyFileSync(path.join(__dirname, '..', 'agents', 'code-reviewer.md'),
        path.join(nativeAgents, 'code-reviewer.md'));
      const p = probeReviewer(scriptsDir, 'code-reviewer', { HOME: claudeHome });
      assert(p.ok === true && p.runtime === 'claude' && p.path === path.join(nativeAgents, 'code-reviewer.md'),
        '#712[native-default]: claude install resolves from ~/.claude/agents without an env override — got ' + JSON.stringify(p));
    }

    // #712 — the legacy probed dir (the documented symlink workaround, and any already-linked
    // install) keeps resolving, now under the claude runtime.
    {
      const claudeHome = path.join(layoutTmp, 'claude-home-legacy');
      const scriptsDir = path.join(claudeHome, '.claude', 'kaola-workflow', 'scripts');
      seedScripts(scriptsDir);
      const legacyAgents = path.join(claudeHome, '.claude', 'kaola-workflow', 'agents');
      fs.mkdirSync(legacyAgents, { recursive: true });
      fs.copyFileSync(path.join(__dirname, '..', 'agents', 'code-reviewer.md'),
        path.join(legacyAgents, 'code-reviewer.md'));
      const p = probeReviewer(scriptsDir, 'code-reviewer', { HOME: claudeHome });
      assert(p.ok === true && p.runtime === 'claude' && p.path === path.join(legacyAgents, 'code-reviewer.md'),
        '#712[legacy]: an already-linked install keeps resolving via the legacy probed dir — got ' + JSON.stringify(p));
    }

    // #712 — self-dev keeps current behavior: the canonical <repo>/agents/<role>.md next to the
    // source checkout's scripts/ wins over a stray native-decoy profile (probe order guard).
    {
      const decoyHome = path.join(layoutTmp, 'selfdev-decoy-home');
      const decoyAgents = path.join(decoyHome, '.claude', 'agents');
      fs.mkdirSync(decoyAgents, { recursive: true });
      fs.writeFileSync(path.join(decoyAgents, 'code-reviewer.md'),
        resignProfile(fs.readFileSync(path.join(__dirname, '..', 'agents', 'code-reviewer.md'), 'utf8')
          + '\n<!-- native-decoy: must not win in self-dev -->\n'));
      const canonicalProfile = fs.realpathSync(path.join(__dirname, '..', 'agents', 'code-reviewer.md'));
      const p = probeReviewer(__dirname, 'code-reviewer', { HOME: decoyHome });
      assert(p.ok === true && p.runtime === 'claude' && p.path === canonicalProfile,
        '#712[self-dev]: self-dev binds the canonical repo profile, not the native decoy — got ' + JSON.stringify(p));
    }

    // Detection unchanged for the kimi install layout (kimi branch still fires before opencode).
    {
      const kimiHome = path.join(layoutTmp, 'kimi-home');
      const scriptsDir = path.join(kimiHome, 'kaola-workflow', 'scripts');
      seedScripts(scriptsDir);
      const skillPath = path.join(kimiHome, 'skills', 'kaola-role-code-reviewer', 'SKILL.md');
      fs.mkdirSync(path.dirname(skillPath), { recursive: true });
      fs.writeFileSync(skillPath, resignProfile(
        fs.readFileSync(path.join(__dirname, '..', 'agents', 'code-reviewer.md'), 'utf8')
          .replace(/^name: code-reviewer$/m, 'name: kaola-role-code-reviewer')));
      const p = probeReviewer(scriptsDir, 'code-reviewer', { KIMI_CODE_HOME: kimiHome });
      assert(p.ok === true && p.runtime === 'kimi' && p.path === skillPath,
        '#712/#717[kimi-unchanged]: kimi layout detection + resolution is unchanged — got ' + JSON.stringify(p));
    }

    // Detection unchanged for a real opencode install layout (<config>/kaola-workflow/scripts
    // with no .claude segment — the .claude carve-out must not swallow opencode).
    {
      const ocConfig = path.join(layoutTmp, 'opencode-config');
      const scriptsDir = path.join(ocConfig, 'kaola-workflow', 'scripts');
      seedScripts(scriptsDir);
      const ocAgents = path.join(ocConfig, 'agent');
      fs.mkdirSync(ocAgents, { recursive: true });
      fs.copyFileSync(path.join(__dirname, '..', 'agents', 'code-reviewer.md'),
        path.join(ocAgents, 'code-reviewer.md'));
      const p = probeReviewer(scriptsDir, 'code-reviewer');
      assert(p.ok === true && p.runtime === 'opencode' && p.path === path.join(ocAgents, 'code-reviewer.md'),
        '#712/#717[opencode-unchanged]: opencode layout detection + resolution is unchanged — got ' + JSON.stringify(p));
    }

    // #736 — self-dev guard: a checkout cloned into a directory literally named `kaola-workflow`
    // (the repo's own name) is structurally identical to an opencode install's
    // <config>/kaola-workflow/scripts/ layout (both are "…/kaola-workflow/scripts" with no
    // /plugins/ segment). The sibling package.json (name: kaola-workflow — the same self-dev
    // predicate the kaola_script resolvers use) must disambiguate it back to claude; a genuine
    // opencode config dir carries no such sibling repo package.json, so this guard cannot
    // swallow it.
    {
      const selfDevRoot = path.join(layoutTmp, 'kaola-workflow');
      const scriptsDir = path.join(selfDevRoot, 'scripts');
      seedScripts(scriptsDir);
      fs.writeFileSync(path.join(selfDevRoot, 'package.json'),
        JSON.stringify({ name: 'kaola-workflow' }, null, 2));
      const selfDevAgents = path.join(selfDevRoot, 'agents');
      fs.mkdirSync(selfDevAgents, { recursive: true });
      fs.copyFileSync(path.join(__dirname, '..', 'agents', 'code-reviewer.md'),
        path.join(selfDevAgents, 'code-reviewer.md'));
      const p = probeReviewer(scriptsDir, 'code-reviewer');
      assert(p.ok === true && p.runtime === 'claude' && p.path === path.join(selfDevAgents, 'code-reviewer.md'),
        '#736[selfdev-named-kaola-workflow]: a checkout dir literally named kaola-workflow with a '
          + 'sibling package.json of the same name must resolve claude (not opencode) — got ' + JSON.stringify(p));
    }
  } finally {
    fs.rmSync(layoutTmp, { recursive: true, force: true });
  }
});

// ===========================================================================
// #713 (option b) — folded-pass repair boundary, UNIT pins. When repair-node
// folds a gate whose latest attempt is a settled PASS, the fold must durably
// record its boundary tuple ON the folded attempt (the journal survives the
// `.cache/<gate>.md` purge), and deriveRepairDelta must SYNTHESIZE the delta
// from that marker instead of refusing review_repair_delta_unavailable. A
// marker-less sealed pass (a pre-fix journal) stays a hard refusal — but now
// names the sanctioned recovery (release-and-adopt or replan) in its detail.
// ===========================================================================
scenario(() => {
  const reviewSchema713 = require('./kaola-workflow-adaptive-schema');
  const sealedPassAttempt = {
    attempt_id: 'review2-gatea:1', outcome: 'pass', lifecycle_settled: true,
    candidate_digest: 'a'.repeat(64),
    candidate_declared: { 'lib/impl.js': '100644 ' + '1'.repeat(40) },
    repair: { selected_writer: null, settled: null }, consumed_by: null, rebind: [],
    fold: { repair_attempt_id: 'review2-gateb:1', selected_writer: 'writer',
      candidate_digest: 'a'.repeat(64),
      candidate_declared: { 'lib/impl.js': '100644 ' + '1'.repeat(40) } },
  };
  const repairedCandidate = { digest: 'b'.repeat(64),
    declared: { 'lib/impl.js': '100644 ' + '2'.repeat(40) }, residue_digest: 'c'.repeat(64) };
  const synthesized = reviewSchema713.deriveRepairDelta({
    previous_attempt: sealedPassAttempt, current_candidate: repairedCandidate });
  assert(synthesized.ok === true
    && synthesized.repair_delta.repair_attempt_id === 'review2-gateb:1'
    && synthesized.repair_delta.selected_writer === 'writer'
    && synthesized.repair_delta.before_candidate_digest === 'a'.repeat(64)
    && synthesized.repair_delta.after_candidate_digest === 'b'.repeat(64)
    && synthesized.repair_delta.paths.length === 1
    && synthesized.repair_delta.paths[0].path === 'lib/impl.js'
    && synthesized.repair_delta.paths[0].before === '100644 ' + '1'.repeat(40)
    && synthesized.repair_delta.paths[0].after === '100644 ' + '2'.repeat(40),
    '#713: deriveRepairDelta synthesizes the delta from a folded-pass boundary marker '
    + '(pre-fix refuses review_repair_delta_unavailable), got ' + JSON.stringify(synthesized));

  // Wedge floor (option c): a sealed pass WITHOUT a marker (a journal written before this
  // fix) still refuses — and the refusal detail names the sanctioned, documented recovery.
  const wedge = reviewSchema713.deriveRepairDelta({
    previous_attempt: { ...sealedPassAttempt, fold: undefined },
    current_candidate: repairedCandidate });
  assert(wedge.ok === false && wedge.reason === 'review_repair_delta_unavailable'
    && typeof wedge.detail === 'string' && /release-and-adopt|replan/i.test(wedge.detail),
    '#713: a marker-less sealed pass refuses with a detail naming the sanctioned recovery '
    + '(release-and-adopt or replan), got ' + JSON.stringify(wedge));

  // Fail-closed: a marker whose captured candidate disagrees with the sealed attempt is
  // tampering, never a delta source.
  const tampered = reviewSchema713.deriveRepairDelta({
    previous_attempt: { ...sealedPassAttempt,
      fold: { ...sealedPassAttempt.fold, candidate_digest: 'd'.repeat(64) } },
    current_candidate: repairedCandidate });
  assert(tampered.ok === false && tampered.reason === 'review_repair_delta_unavailable',
    '#713: a fold marker inconsistent with its sealed attempt fails closed, got ' + JSON.stringify(tampered));

  // Fold-boundary steady-state progress: the folded gate's re-certification legitimately
  // presents an UNCHANGED empty frontier (its sealed pass had no open findings). With the
  // boundary flagged, a clean frontier + validation pass is convergence, not non-progress.
  const steadyState = reviewSchema713.assessReviewProgress({
    previous_open_uids: [], current_open_uids: [], repair_delta_uids: [], resolutions: [],
    repair_attempt_id: 'review2-gateb:1', candidate_digest: 'b'.repeat(64),
    validation: { status: 'pass' }, logical_gate_key: 'gatekey', scope_lineage_id: 'scope',
    before_candidate_digest: 'a'.repeat(64), seen_idempotency_keys: [],
    previous_consecutive_nonprogress: 0, consumed_repairs: 1, fold_boundary: true });
  assert(steadyState.progress === true && steadyState.reason === null && steadyState.stop_reason === null,
    '#713: a folded-pass re-certification with a clean frontier makes progress at the fold '
    + 'boundary (pre-fix: review_frontier_nonprogress), got ' + JSON.stringify(steadyState));
  // Regression controls: WITHOUT the boundary flag the identical steady frontier stays
  // non-progress, and a boundary flag cannot launder a FAILED validation.
  const noBoundary = reviewSchema713.assessReviewProgress({
    previous_open_uids: [], current_open_uids: [], repair_delta_uids: [], resolutions: [],
    repair_attempt_id: 'review2-gateb:1', candidate_digest: 'b'.repeat(64),
    validation: { status: 'pass' }, logical_gate_key: 'gatekey', scope_lineage_id: 'scope',
    before_candidate_digest: 'a'.repeat(64), seen_idempotency_keys: [],
    previous_consecutive_nonprogress: 0, consumed_repairs: 1 });
  assert(noBoundary.progress === false,
    '#713: (control) a boundary-less steady frontier stays non-progress');
  const failedValidation = reviewSchema713.assessReviewProgress({
    previous_open_uids: [], current_open_uids: [], repair_delta_uids: [], resolutions: [],
    repair_attempt_id: 'review2-gateb:1', candidate_digest: 'b'.repeat(64),
    validation: { status: 'fail', reason: 'validation_failed' }, logical_gate_key: 'gatekey',
    scope_lineage_id: 'scope', before_candidate_digest: 'a'.repeat(64), seen_idempotency_keys: [],
    previous_consecutive_nonprogress: 0, consumed_repairs: 1, fold_boundary: true });
  assert(failedValidation.progress === false,
    '#713: (control) the fold boundary never laundered a failed validation into progress');
});

// ===========================================================================
// #714 — `## Required Agent Compliance` producer drift, UNIT pins. The splice
// must keep table rows contiguous and leave exactly one blank line before the
// following heading (the blank-before-heading used to migrate INTO the table).
// ===========================================================================
scenario(() => {
  const { spliceComplianceSection: splice714 } = require('./kaola-workflow-adaptive-schema');
  const baseSection714 = [
    '## Node Ledger', '', '| id | status |', '|---|---|', '| a | complete |', '',
    '## Required Agent Compliance', '',
    '| Requirement | Status | Evidence | Skip Reason |', '|---|---|---|---|',
    '| tdd-guide (a) | subagent-invoked | e1 | |', '',
    '## Plan Notes', '', 'operator notes', '',
  ].join('\n');
  const row714 = '| code-reviewer (b) | subagent-invoked | e2 | |';
  const spliced714 = splice714(baseSection714, row714);
  assert(spliced714.includes('| tdd-guide (a) | subagent-invoked | e1 | |\n' + row714 + '\n\n## Plan Notes'),
    '#714: splice keeps table rows contiguous with exactly one blank line before the next '
    + 'heading (pre-fix: the blank migrates INTO the table and the new row abuts the heading), got:\n' + spliced714);
  assert(!spliced714.includes('| tdd-guide (a) | subagent-invoked | e1 | |\n\n' + row714),
    '#714: no blank line splits the table after the append');
  // Control (already conforming pre-fix): a section at EOF stays contiguous with one
  // trailing newline.
  const atEof714 = [
    '## Node Ledger', '', '| id | status |', '|---|---|', '| a | complete |', '',
    '## Required Agent Compliance', '',
    '| Requirement | Status | Evidence | Skip Reason |', '|---|---|---|---|',
    '| tdd-guide (a) | subagent-invoked | e1 | |', '',
  ].join('\n');
  const splicedEof714 = splice714(atEof714, row714);
  assert(splicedEof714.endsWith('| tdd-guide (a) | subagent-invoked | e1 | |\n' + row714 + '\n'),
    '#714: (control) splice at EOF keeps rows contiguous with one trailing newline');
});

// ===========================================================================
// #714 (re-homed by #833) — the issue's round-trip. #714's three defects were all
// PRODUCER defects of the incremental append path (a blank line migrating into the
// table, a bare `code-reviewer` cell, a lost blank before the next heading), and that
// path is deleted. The round-trip therefore pins two things instead: the close cycle
// writes NO compliance bytes at all, and the ARCHIVE-TIME renderer — the only producer
// left — emits all three properties by construction over the same finished plan.
// ===========================================================================
scenario(() => {
  const planPath714 = '/fake/kaola-workflow/p714/workflow-plan.md';
  const nodes714 = [
    '| impl | tdd-guide | — | scripts/x.js | 1 | sequence |',
    '| rev | code-reviewer | impl | — | 1 | sequence |',
    '| done | finalize | rev | — | 1 | sequence |',
  ];
  const files714 = {};
  files714[planPath714] = makePlan(
    ['| impl | in_progress | |', '| rev | pending | |', '| done | pending | |'], nodes714)
    + '## Plan Notes\n\noperator notes\n';
  files714['/fake/kaola-workflow/p714/.cache/impl.md'] = 'evidence-binding: impl implnonce001\nRED: r\nred_baseline: implnonce001\n';
  files714['/fake/kaola-workflow/p714/.cache/rev.md'] = 'evidence-binding: rev revnonce0001\nReviewed the changes. LGTM.\n';
  files714['/fake/kaola-workflow/p714/.cache/done.md'] = 'evidence-binding: done donenonce001\nfinalization bookkeeping complete\n';
  const close714 = nodeId => runCloseAndOpenNext({
    planPath: planPath714, statePath: '/fake/kaola-workflow/p714/workflow-state.md',
    project: 'p714', nodeId,
    shell: (sp, args) => {
      const base = path.basename(sp);
      if (base === 'kaola-workflow-commit-node.js' && !(args || []).includes('--start')) {
        return { exitCode: 0, result: 'ok', mode: 'per-node', nodeId,
          overallOk: true, selectorCheck: { isSelector: false, ok: true } };
      }
      if (base === 'kaola-workflow-commit-node.js') {
        return { exitCode: 0, result: 'ok', mode: 'per-node-start', overallOk: true };
      }
      if (base === 'kaola-workflow-next-action.js') {
        if (nodeId === 'impl') return { exitCode: 0, result: 'ok', allDone: false,
          readySet: [{ id: 'rev', role: 'code-reviewer', model: 'sonnet', declared_write_set: '—', dependsOn: ['impl'] }],
          nextNode: { id: 'rev', role: 'code-reviewer', model: 'sonnet', declared_write_set: '—' } };
        if (nodeId === 'rev') return { exitCode: 0, result: 'ok', allDone: false,
          readySet: [{ id: 'done', role: 'finalize', model: 'sonnet', declared_write_set: '—', dependsOn: ['rev'] }],
          nextNode: { id: 'done', role: 'finalize', model: 'sonnet', declared_write_set: '—' } };
        return { exitCode: 0, result: 'ok', allDone: true, readyPending: [] };
      }
      return { exitCode: 1 };
    },
    readFile: fp => { if (fp in files714) return files714[fp]; throw new Error('ENOENT ' + fp); },
    writeFile: (fp, content) => { files714[fp] = content; },
    cacheExists: fp => fp in files714,
  });
  const w714 = close714('impl');
  assert(w714.result === 'ok', '#714: writer closes on the legacy append path, got ' + JSON.stringify(w714));
  const r714 = close714('rev');
  assert(r714.result === 'ok', '#714: code-reviewer closes on the legacy append path, got ' + JSON.stringify(r714));
  const f714 = close714('done');
  assert(f714.result === 'ok', '#714: finalize closes on the legacy append path, got ' + JSON.stringify(f714));
  const final714 = files714[planPath714];

  // #833 acceptance: the whole open/close cycle wrote NO compliance bytes.
  assert(!final714.includes('## Required Agent Compliance'),
    '#714/#833: a full 3-node open/close cycle leaves NO ## Required Agent Compliance section, got:\n'
    + final714.slice(final714.indexOf('## Node Ledger')));

  // The renderer is the only producer left; hold it to #714's three properties.
  const rendered714 = planValidator.renderAgentComplianceSection(final714, {
    readEvidence: id => files714['/fake/kaola-workflow/p714/.cache/' + id + '.md'],
  });
  assert(planValidator.computePlanHash(rendered714) === planValidator.computePlanHash(final714),
    '#714/#833: rendering the table is plan_hash-NEUTRAL');

  // Defect 2: every rendered row carries the canonical `role (node-id)` cell — never bare.
  assert(rendered714.includes('| code-reviewer (rev) | subagent-invoked |'),
    '#714: the rendered review row is `code-reviewer (rev)`, never a bare `code-reviewer` cell');
  assert(!/^\| code-reviewer \|/m.test(rendered714) && !/^\| security-reviewer \|/m.test(rendered714),
    '#714: no bare review-role cell is rendered anywhere in the table');

  // Defect 1: table rows stay contiguous — no blank line inside the table.
  const sec714 = locateSection(rendered714, 'Required Agent Compliance');
  assert(sec714.start >= 0, '#714: the rendered compliance section exists');
  const end714 = sec714.next >= 0 ? sec714.next : rendered714.length;
  const bodyLines714 = rendered714.slice(sec714.start, end714).split('\n');
  const firstRow714 = bodyLines714.findIndex(line => line.trim().startsWith('|'));
  const rowCount714 = bodyLines714.filter(line => line.trim().startsWith('|')).length;
  const tableSpan714 = bodyLines714.slice(firstRow714, firstRow714 + rowCount714);
  assert(rowCount714 === 5 && tableSpan714.every(line => line.trim() !== ''),
    '#714: header + separator + 3 node rows are contiguous — no blank line inside the table, got:\n'
    + tableSpan714.join('\n'));

  // Defect 3: exactly one blank line separates the table from the following heading.
  assert(/\| \|\n\n## Plan Notes/.test(rendered714) && !/\| \|\n## Plan Notes/.test(rendered714)
    && !/\| \|\n\n\n## Plan Notes/.test(rendered714),
    '#714: exactly one blank line separates the table from the following heading, got:\n'
    + rendered714.slice(rendered714.indexOf('## Required Agent Compliance')));
});

// ===========================================================================
// #714 (inverted by #833) — legacy bare-cell TOLERANCE. The bare `code-reviewer`
// pending row used to be MATCHED and advanced in place; nothing advances it now. The
// contract is stricter and simpler: it is left byte-identical, and the derivation —
// which keys on the node, not the cell — reports the truth regardless.
// ===========================================================================
scenario(() => {
  const planPath714b = '/fake/kaola-workflow/p714b/workflow-plan.md';
  const files714b = {};
  files714b[planPath714b] = makePlan(['| rev | in_progress | |'], [
    '| rev | code-reviewer | — | — | 1 | sequence |',
  ]) + [
    '## Required Agent Compliance', '',
    '| Requirement | Status | Evidence | Skip Reason |', '|---|---|---|---|',
    '| code-reviewer | pending | | |', '',
  ].join('\n');
  files714b['/fake/kaola-workflow/p714b/.cache/rev.md'] = 'evidence-binding: rev revnonce714b\nReviewed. LGTM.\n';
  const close714b = runCloseAndOpenNext({
    planPath: planPath714b, statePath: '/fake/kaola-workflow/p714b/workflow-state.md',
    project: 'p714b', nodeId: 'rev',
    shell: (sp, args) => {
      const base = path.basename(sp);
      if (base === 'kaola-workflow-commit-node.js') {
        return { exitCode: 0, result: 'ok', mode: 'per-node', nodeId: 'rev',
          overallOk: true, selectorCheck: { isSelector: false, ok: true } };
      }
      if (base === 'kaola-workflow-next-action.js') {
        return { exitCode: 0, result: 'ok', allDone: true, readyPending: [] };
      }
      return { exitCode: 1 };
    },
    readFile: fp => { if (fp in files714b) return files714b[fp]; throw new Error('ENOENT ' + fp); },
    writeFile: (fp, content) => { files714b[fp] = content; },
    cacheExists: fp => fp in files714b,
  });
  assert(close714b.result === 'ok', '#714: legacy bare-row close stays ok, got ' + JSON.stringify(close714b));
  const complianceBlock714b = files714b[planPath714b].slice(files714b[planPath714b].indexOf('## Required Agent Compliance'));
  assert(complianceBlock714b.includes('| code-reviewer | pending | | |'),
    '#714/#833: the legacy bare row is left BYTE-IDENTICAL (never advanced, never rewritten), got:\n'
    + complianceBlock714b);
  assert((complianceBlock714b.match(/^\| code-reviewer \|/gm) || []).length === 1
    && !complianceBlock714b.includes('| code-reviewer (rev) |'),
  '#714/#833: no row is appended alongside it either');
  const derived714b = planValidator.deriveAgentCompliance(files714b[planPath714b], {
    readEvidence: id => files714b['/fake/kaola-workflow/p714b/.cache/' + id + '.md'],
  }).rows;
  assert(derived714b.length === 1 && derived714b[0].requirement === 'code-reviewer (rev)'
    && derived714b[0].status === 'subagent-invoked'
    && derived714b[0].evidence === 'evidence-binding: rev revnonce714b',
  '#714/#833: the derivation reports the closed node correctly while the stored bare row still '
    + 'reads `pending`, got ' + JSON.stringify(derived714b));
});

// ===========================================================================
// #713 — the issue's six-step reproduction, driven end-to-end over the REAL
// CLI in a real git repo (mirrors the walkthrough's review-v2 harness):
// schema-2 serial writer → gateA (security-reviewer) → gateB (code-reviewer).
// gateA PASSES, gateB FAILS, repair-node folds gateA (purging its stale
// sealed-pass receipt), the writer repairs, and the folded-pass gateA must
// REOPEN (no review_repair_delta_unavailable), re-certify the repaired tree,
// and the sequence must drive to finalize with the claim intact (no release,
// no replan). This block doubles as #714/#833's schema-2 cycle pin: the cycle
// includes a gate re-close after repair, and the plan must come out of it with
// NO compliance bytes and a clean derived table.
// ===========================================================================
scenario(() => {
  const { spawnSync: spawn713 } = require('child_process');
  const reviewSchema713 = require('./kaola-workflow-adaptive-schema');
  const runner713 = require('./kaola-workflow-validation-runner');
  const NODE_CLI_713 = path.join(__dirname, 'kaola-workflow-adaptive-node.js');
  const VALIDATOR_CLI_713 = path.join(__dirname, 'kaola-workflow-plan-validator.js');
  const baseEnv713 = Object.fromEntries(Object.entries(process.env).filter(([k]) => !k.startsWith('KAOLA_')));
  const env713 = { ...baseEnv713, GIT_CONFIG_GLOBAL: '/dev/null', GIT_CONFIG_NOSYSTEM: '1',
    KAOLA_WORKFLOW_OFFLINE: '1' };
  // The per-scenario vehicle for the adaptive-node CLI. Every scenario drives it as a CHAIN:
  // one process writes the ledger row, the barrier baseline and the .cache evidence and EXITS,
  // and the next re-derives the whole run state from those bytes with no shared heap.
  // spawn-class: durable-handoff
  const run713 = (script, args, cwd, input) => spawn713(process.execPath, [script, ...args],
    { cwd, encoding: 'utf8', env: env713, input, timeout: 120000 });
  const lastJson713 = result => {
    const line = String(result.stdout || '').trim().split('\n').filter(row => row.trim().startsWith('{')).pop();
    return line ? JSON.parse(line) : null;
  };
  const gateEvidence713 = (nodeId, nonce, dispatch, domainOutcome, extraRows) => [
    'evidence-binding: ' + nodeId + ' ' + nonce,
    'contract_version: 2',
    'review_context_hash: ' + dispatch.review_context_hash,
    'behavior_contract_hash: ' + dispatch.behavior_contract_hash,
    'resolved_profile_hash: ' + dispatch.resolved_profile_hash,
    'candidate_digest: ' + dispatch.candidate_digest,
    'domain_outcome: ' + domainOutcome,
    'gate_claim: ' + dispatch.gate_claim,
    'gate_surface: ' + dispatch.gate_surface,
    'gate_aggregation: ' + dispatch.gate_aggregation,
    ...(extraRows || []), '',
  ].join('\n');

  const tmp713 = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'kw-713-fold-pass-')));
  try {
    G.git(tmp713, ['init', '-b', 'main'], { encoding: 'utf8', env: env713 });
    G.git(tmp713, ['config', 'user.email', 'kw@test'], { encoding: 'utf8', env: env713 });
    G.git(tmp713, ['config', 'user.name', 'kw'], { encoding: 'utf8', env: env713 });
    const project713 = 'issue-713-fold';
    const projectDir713 = path.join(tmp713, 'kaola-workflow', project713);
    const cacheDir713 = path.join(projectDir713, '.cache');
    fs.mkdirSync(cacheDir713, { recursive: true });
    fs.mkdirSync(path.join(tmp713, 'lib'), { recursive: true });
    fs.writeFileSync(path.join(tmp713, 'lib', 'impl.js'), 'module.exports = 0;\n');
    const planPath713 = path.join(projectDir713, 'workflow-plan.md');
    fs.writeFileSync(planPath713, [
      '# Workflow Plan — issue 713', '',
      '## Meta',
      'plan_form: spine', // #765: all-concrete spine — legacy dag grammar retired at freeze
      'plan_schema_version: 2',
      'labels: enhancement',
      'code_certifier: gateB',
      'security_certifier: none',
      'inherited_frontier_digest: none',
      'inherited_frontier_classes: none',
      'validation_command: node --check lib/impl.js',
      'validation_timeout_minutes: 5', '',
      '## Nodes', '',
      '| id | role | depends_on | declared_write_set | cardinality | shape | gate_claim | gate_surface | gate_aggregation | certifies |',
      '|---|---|---|---|---|---|---|---|---|---|',
      '| writer | tdd-guide | — | lib/impl.js | 1 | sequence | — | — | — | — |',
      '| gateA | security-reviewer | writer | — | 1 | sequence | security review clean | code-tree | sequence | — |',
      '| gateB | code-reviewer | gateA | — | 1 | sequence | review-change | code-tree | sequence | — |',
      '| finalize | finalize | gateB | — | 1 | sequence | — | — | — | — |', '',
      '## Design', '',
      'Decompose: writer builds lib/impl.js; gateA (security) then gateB (code) post-dominate it; finalize sinks. sequence writer→gateA→gateB: S1 — each gate consumes the prior change. Done: both gates clear and validation passes.', '',
      '## Acceptance', '',
      'A1: lib/impl.js is implemented and passes the plan\'s validation command.',
      'A2: the security gate and the code gate both clear over the produced tree.', '',
      '## Node Ledger', '',
      '| id | status |', '|---|---|',
      '| writer | pending |', '| gateA | pending |', '| gateB | pending |', '| finalize | pending |', '',
      '## Required Agent Compliance', '',
      '| Requirement | Status | Evidence | Skip Reason |', '|---|---|---|---|',
      '| tdd-guide (writer) | pending | | |', '| security-reviewer (gateA) | pending | | |',
      '| code-reviewer (gateB) | pending | | |', '| finalize (finalize) | pending | | |', '',
    ].join('\n'));
    fs.writeFileSync(path.join(projectDir713, 'workflow-state.md'), '# Workflow State\nstatus: active\n');
    const freeze713 = run713(VALIDATOR_CLI_713, [planPath713, '--freeze', '--json'], tmp713);
    assert(freeze713.status === 0 && lastJson713(freeze713) && lastJson713(freeze713).planHash,
      '#713: the schema-2 serial two-gate plan freezes: ' + freeze713.stdout + freeze713.stderr);
    const planHash713 = lastJson713(freeze713).planHash;
    G.git(tmp713, ['add', '-A'], { encoding: 'utf8', env: env713 });
    G.git(tmp713, ['commit', '-m', 'fixture'], { encoding: 'utf8', env: env713 });

    // Step 1-2: writer ships v1; gateA PASSES (its pass attempt seals).
    const openWriter713 = run713(NODE_CLI_713, ['open-next', '--project', project713, '--json'], tmp713);
    assert(openWriter713.status === 0 && lastJson713(openWriter713) && lastJson713(openWriter713).opened
      && lastJson713(openWriter713).opened.id === 'writer' && lastJson713(openWriter713).nonce,
      '#713: writer opens: ' + openWriter713.stdout + openWriter713.stderr);
    fs.writeFileSync(path.join(tmp713, 'lib', 'impl.js'), 'module.exports = 1;\n');
    let rec713 = run713(NODE_CLI_713, ['record-evidence', '--project', project713, '--node-id', 'writer',
      '--stdin', '--json'], tmp713,
      'evidence-binding: writer ' + lastJson713(openWriter713).nonce
        + '\nRED: base behavior reproduced\nred_baseline: ' + lastJson713(openWriter713).nonce + '\n');
    assert(rec713.status === 0, '#713: writer evidence records: ' + rec713.stdout + rec713.stderr);
    const closeWriter713 = run713(NODE_CLI_713, ['close-and-open-next', '--project', project713,
      '--node-id', 'writer', '--json'], tmp713);
    assert(closeWriter713.status === 0 && lastJson713(closeWriter713).opened
      && lastJson713(closeWriter713).opened.id === 'gateA',
      '#713: gateA opens after the writer close: ' + closeWriter713.stdout + closeWriter713.stderr);
    const openA1 = lastJson713(closeWriter713).opened;
    rec713 = run713(NODE_CLI_713, ['record-evidence', '--project', project713, '--node-id', 'gateA',
      '--stdin', '--json'], tmp713,
      gateEvidence713('gateA', openA1.nonce, openA1.dispatch, 'approved', ['findings_none: true']));
    assert(rec713.status === 0, '#713: gateA pass evidence records: ' + rec713.stdout + rec713.stderr);
    const closeA1 = run713(NODE_CLI_713, ['close-and-open-next', '--project', project713,
      '--node-id', 'gateA', '--json'], tmp713);
    assert(closeA1.status === 0 && lastJson713(closeA1).closed === 'gateA'
      && lastJson713(closeA1).opened && lastJson713(closeA1).opened.id === 'gateB',
      '#713: gateA seals PASS and gateB opens: ' + closeA1.stdout + closeA1.stderr);
    const openB1 = lastJson713(closeA1).opened;

    // Step 3: gateB FAILS with a legitimate blocking finding.
    // #805: a change gate's BLOCKING findings must carry a PATH-BEARING primary anchor — every in-plan
    // repair route resolves the fixer from that path, so an anchor without one commits an attempt no
    // route can act on. `candidate_range` over the writer's own declared file is the faithful shape here
    // (the defect IS in that file), and it is what makes the repair below reach `writer` by ownership
    // rather than by the ownership-absent inert fallback.
    const objectFormat713 = String(G.git(tmp713, ['rev-parse', '--show-object-format'], { encoding: 'utf8', env: env713 }).stdout).trim();
    const implObjectId713 = String(G.git(tmp713, ['hash-object', 'lib/impl.js'], { encoding: 'utf8', env: env713 }).stdout).trim();
    const implLength713 = fs.readFileSync(path.join(tmp713, 'lib', 'impl.js')).length;
    assert(/^[0-9a-f]{40,64}$/.test(implObjectId713),
      '#713 fixture: the candidate blob id for lib/impl.js resolves, got ' + JSON.stringify(implObjectId713));
    const blockingFinding713 = {
      failure_class: 'correctness',
      trigger: { precondition_digest: '1'.repeat(64), input_digest: '2'.repeat(64),
        expected_digest: '3'.repeat(64), observed_digest: '4'.repeat(64) },
      primary_anchor: { kind: 'candidate_range', path: 'lib/impl.js',
        object_format: objectFormat713, tree_mode: '100644', object_id: implObjectId713,
        start: 0, end: 1, blob_length: implLength713 },
      secondary_anchors: [], severity: 'high', scope: 'in_scope', action: 'fix',
      status: 'open', fix_role: 'tdd-guide', proof_digest: '6'.repeat(64),
    };
    rec713 = run713(NODE_CLI_713, ['record-evidence', '--project', project713, '--node-id', 'gateB',
      '--stdin', '--json'], tmp713,
      gateEvidence713('gateB', openB1.nonce, openB1.dispatch, 'changes_requested',
        ['finding_json: ' + JSON.stringify(blockingFinding713)]));
    assert(rec713.status === 0, '#713: gateB blocking evidence records: ' + rec713.stdout + rec713.stderr);
    const closeB1 = run713(NODE_CLI_713, ['close-and-open-next', '--project', project713,
      '--node-id', 'gateB', '--json'], tmp713);
    assert(lastJson713(closeB1) && lastJson713(closeB1).result === 'review_failed'
      && lastJson713(closeB1).attempt_id,
      '#713: gateB settles FAIL with a durable attempt: ' + closeB1.stdout + closeB1.stderr);
    const failedAttemptId713 = lastJson713(closeB1).attempt_id;

    // Step 4: repair-node consumes gateB's failed attempt and folds gateA back to pending,
    // purging its stale sealed-pass receipt (the fold stays conservative).
    const repair713 = run713(NODE_CLI_713, ['repair-node', '--project', project713,
      '--attempt-id', failedAttemptId713, '--node-id', 'writer', '--json'], tmp713);
    assert(repair713.status === 0 && lastJson713(repair713).result === 'ok'
      && lastJson713(repair713).baselineReused === true,
      '#713: repair-node folds the serial chain with the anti-laundering baseline reused: '
      + repair713.stdout + repair713.stderr);
    assert(lastJson713(repair713).gatesReset.includes('gateA')
      && lastJson713(repair713).gatesReset.includes('gateB'),
      '#713: both post-dominating gates fold: ' + JSON.stringify(lastJson713(repair713).gatesReset));
    assert((lastJson713(repair713).evidenceRemoved || []).includes('gateA.md')
      && !fs.existsSync(path.join(cacheDir713, 'gateA.md')),
      '#713: the fold keeps purging the stale sealed-pass receipt (a pass over the pre-repair '
      + 'tree never certifies the repaired tree)');

    // THE BOUNDARY MARKER: the folded sealed-pass attempt durably records the fold boundary
    // tuple in the journal (which survives the evidence purge).
    const journalAfterRepair713 = JSON.parse(fs.readFileSync(path.join(cacheDir713, 'review-attempts.json'), 'utf8'));
    const passAttemptA1 = journalAfterRepair713.attempts.find(a =>
      a.logical_gate && Array.isArray(a.logical_gate.members) && a.logical_gate.members.includes('gateA'));
    assert(passAttemptA1 && passAttemptA1.outcome === 'pass' && passAttemptA1.lifecycle_settled === true,
      '#713: setup — gateA\'s sealed pass attempt is durable in the journal');
    assert(passAttemptA1.fold
      && passAttemptA1.fold.repair_attempt_id === failedAttemptId713
      && passAttemptA1.fold.selected_writer === 'writer'
      && passAttemptA1.fold.candidate_digest === passAttemptA1.candidate_digest
      && reviewSchema713.canonicalJson(passAttemptA1.fold.candidate_declared)
        === reviewSchema713.canonicalJson(passAttemptA1.candidate_declared),
      '#713: the fold durably records its boundary tuple (folding attempt, selected writer, sealed '
      + 'pass candidate digest/declared) on the folded attempt — pre-fix there is no marker, got '
      + JSON.stringify(passAttemptA1.fold));

    // Step 5: the writer repairs (v2). Its close must REOPEN the folded-pass gateA — the
    // issue's wedge step (pre-fix refuses review_repair_delta_unavailable).
    fs.writeFileSync(path.join(tmp713, 'lib', 'impl.js'), 'module.exports = 2;\n');
    rec713 = run713(NODE_CLI_713, ['record-evidence', '--project', project713, '--node-id', 'writer',
      '--stdin', '--json'], tmp713,
      'evidence-binding: writer ' + lastJson713(openWriter713).nonce
        + '\nRED: gate-B regression reproduced\nred_baseline: ' + lastJson713(openWriter713).nonce + '\n');
    assert(rec713.status === 0, '#713: repaired writer evidence records: ' + rec713.stdout + rec713.stderr);
    const closeWriter2 = run713(NODE_CLI_713, ['close-and-open-next', '--project', project713,
      '--node-id', 'writer', '--json'], tmp713);
    assert(closeWriter2.status === 0 && lastJson713(closeWriter2) && lastJson713(closeWriter2).opened
      && lastJson713(closeWriter2).opened.id === 'gateA',
      '#713: the folded-pass gateA REOPENS after the repair — no review_repair_delta_unavailable '
      + 'wedge (pre-fix refuses here), got status=' + closeWriter2.status + ' out='
      + closeWriter2.stdout + closeWriter2.stderr);
    const openA2 = (lastJson713(closeWriter2) || {}).opened;
    assert(openA2 && openA2.dispatch, '#713: gateA reopened with a live v2 dispatch (no wedge)');
    const contextA2 = openA2 && openA2.dispatch
      ? JSON.parse(fs.readFileSync(path.join(projectDir713, openA2.dispatch.review_context_path), 'utf8'))
      : { review_phase: null, repair_delta: null };
    assert(contextA2.review_phase === 'closure' && contextA2.repair_delta
      && contextA2.repair_delta.repair_attempt_id === failedAttemptId713
      && contextA2.repair_delta.selected_writer === 'writer'
      && contextA2.repair_delta.paths.some(row => row.path === 'lib/impl.js'),
      '#713: the reopened gateA context synthesizes the repair delta from the fold marker '
      + '(folding attempt, folding writer, sealed-pass before, repaired after), got '
      + JSON.stringify(contextA2.repair_delta));

    // gateA re-certifies the repaired tree: approved, no findings, no resolutions (its sealed
    // pass left an empty frontier — the fold-boundary steady state must converge, not wedge).
    // Guarded: a wedged reopen (the RED state) fails the assertions above without crashing the suite.
    if (openA2 && openA2.dispatch) {
      rec713 = run713(NODE_CLI_713, ['record-evidence', '--project', project713, '--node-id', 'gateA',
        '--stdin', '--json'], tmp713,
        gateEvidence713('gateA', openA2.nonce, openA2.dispatch, 'approved', ['findings_none: true']));
      assert(rec713.status === 0, '#713: gateA re-certification evidence records: ' + rec713.stdout + rec713.stderr);
      const closeA2 = run713(NODE_CLI_713, ['close-and-open-next', '--project', project713,
        '--node-id', 'gateA', '--json'], tmp713);
      assert(closeA2.status === 0 && lastJson713(closeA2).closed === 'gateA'
        && lastJson713(closeA2).opened && lastJson713(closeA2).opened.id === 'gateB',
        '#713: the folded-pass re-certification closes PASS (fold-boundary progress) and advances '
        + 'to gateB, got ' + closeA2.stdout + closeA2.stderr);
      const openB2 = lastJson713(closeA2).opened;

      // gateB's normal closure: resolve the prior finding against the repaired candidate.
      const contextB2 = JSON.parse(fs.readFileSync(path.join(projectDir713, openB2.dispatch.review_context_path), 'utf8'));
      assert(contextB2.repair_delta && contextB2.repair_delta.repair_attempt_id === failedAttemptId713,
        '#713: gateB\'s closure context binds the consumed failed attempt (the ordinary fail path)');
      const priorUid713 = reviewSchema713.normalizeFindingSet([blockingFinding713],
        { scope_lineage_id: contextB2.scope_lineage_id }).findings[0].uid;
      const resolvedFinding713 = { ...blockingFinding713, uid: priorUid713, status: 'resolved' };
      const execIdentity713 = { comparable: true, digest: 'a2'.repeat(32), incomparability_classes: [] };
      const vector713 = runner713.buildValidationVector({
        command_id: 'c1'.repeat(32), candidate_digest: openB2.dispatch.candidate_digest,
        execution_identity: execIdentity713,
        runs: [{ index: 0, exit_code: 0, signal: null, timed_out: false,
          pre_candidate_digest: openB2.dispatch.candidate_digest,
          post_candidate_digest: openB2.dispatch.candidate_digest,
          execution_identity_digest: execIdentity713.digest, failure_signature_sha256: '0'.repeat(64) }],
      }, []);
      const vectorDir713 = path.join(cacheDir713, 'validation-vectors');
      fs.mkdirSync(vectorDir713, { recursive: true });
      fs.writeFileSync(path.join(vectorDir713, vector713.vector_id + '.json'),
        runner713.canonicalJson(vector713) + '\n');
      const resolution713 = { uid: priorUid713, repair_attempt_id: failedAttemptId713,
        validation_vector_digest: vector713.vector_id, evidence_digest: vector713.receipt_sha256,
        candidate_digest: openB2.dispatch.candidate_digest };
      rec713 = run713(NODE_CLI_713, ['record-evidence', '--project', project713, '--node-id', 'gateB',
        '--stdin', '--json'], tmp713,
        gateEvidence713('gateB', openB2.nonce, openB2.dispatch, 'approved',
          ['finding_json: ' + JSON.stringify(resolvedFinding713),
            'resolution_json: ' + JSON.stringify(resolution713)]));
      assert(rec713.status === 0, '#713: gateB closure evidence records: ' + rec713.stdout + rec713.stderr);
      const closeB2 = run713(NODE_CLI_713, ['close-and-open-next', '--project', project713,
        '--node-id', 'gateB', '--json'], tmp713);
      assert(closeB2.status === 0 && lastJson713(closeB2).closed === 'gateB'
        && lastJson713(closeB2).opened && lastJson713(closeB2).opened.id === 'finalize',
        '#713: gateB re-passes and finalize opens: ' + closeB2.stdout + closeB2.stderr);

      // Step 6 (was the dead end): drive to finalize-ready with the claim intact.
      rec713 = run713(NODE_CLI_713, ['record-evidence', '--project', project713, '--node-id', 'finalize',
        '--stdin', '--json'], tmp713,
        'evidence-binding: finalize ' + lastJson713(closeB2).opened.nonce + '\nfinalization bookkeeping complete\n');
      assert(rec713.status === 0, '#713: finalize evidence records: ' + rec713.stdout + rec713.stderr);
      const closeFin713 = run713(NODE_CLI_713, ['close-node', '--project', project713,
        '--node-id', 'finalize', '--json'], tmp713);
      assert(closeFin713.status === 0 && lastJson713(closeFin713).result === 'ok',
        '#713: finalize closes — the pass-then-later-fail sequence drives to a finalize-ready '
        + 'state without releasing the claim: ' + closeFin713.stdout + closeFin713.stderr);

      const finalJournal713 = JSON.parse(fs.readFileSync(path.join(cacheDir713, 'review-attempts.json'), 'utf8'));
      assert(finalJournal713.attempts.length === 4,
        '#713: A1 + B1 + A2 + B2 settle exactly four durable attempts, got ' + finalJournal713.attempts.length);
      const attemptA2 = finalJournal713.attempts.find(a =>
        a.logical_gate.members.includes('gateA') && a.ordinal === 2);
      assert(attemptA2 && attemptA2.outcome === 'pass' && attemptA2.lifecycle_settled === true
        && attemptA2.progress && attemptA2.progress.progress === true,
        '#713: gateA\'s re-certification attempt settles PASS with fold-boundary progress, got '
        + JSON.stringify(attemptA2 && attemptA2.progress));
      assert(reviewSchema713.validateReviewJournal(finalJournal713, planHash713, 2).ok === true,
        '#713: the fold-marked journal round-trips the strict canonicalJson V2 validator');
      const resume713 = run713(VALIDATOR_CLI_713, [planPath713, '--resume-check', '--json'], tmp713);
      assert(resume713.status === 0,
        '#713: --resume-check passes over the fold-marked journal and advanced plan: '
        + resume713.stdout + resume713.stderr);
      const finalPlan713 = fs.readFileSync(planPath713, 'utf8');
      const ledger713 = finalPlan713.slice(finalPlan713.indexOf('## Node Ledger'));
      assert(['writer', 'gateA', 'gateB', 'finalize']
        .every(id => new RegExp('\\| ' + id + ' \\| complete \\|').test(ledger713)),
        '#713: the full sequence reaches an all-complete ledger with the claim intact (no release, '
        + 'no replan), got:\n' + ledger713);
      assert(!fs.existsSync(path.join(cacheDir713, 'replan-source.json')),
        '#713: no replan escape hatch was needed to unwedge the claim');

      // #714/#833's schema-2 pin on the same cycle (an open/close/repair/re-close sequence over
      // the REAL CLI): the plan carries no compliance bytes, and the derivation reports every
      // node exactly once with nothing left pending.
      // The fixture hand-authors a pre-seeded section (a legacy schema-2 plan shape). Nothing in
      // the repair cycle may touch it: every row must still read `pending` byte-for-byte.
      assert(/\| tdd-guide \(writer\) \| pending \| \| \|/.test(finalPlan713)
        && /\| security-reviewer \(gateA\) \| pending \| \| \|/.test(finalPlan713)
        && /\| code-reviewer \(gateB\) \| pending \| \| \|/.test(finalPlan713)
        && /\| finalize \(finalize\) \| pending \| \| \|/.test(finalPlan713),
      '#713/#714/#833: a full repair cycle over the real CLI leaves the legacy stored section '
        + 'byte-identical, got:\n' + finalPlan713.slice(finalPlan713.indexOf('## Required Agent Compliance')));
      const derived713 = planValidator.deriveAgentCompliance(finalPlan713, {
        readEvidence: id => fs.readFileSync(path.join(cacheDir713, id + '.md'), 'utf8'),
      }).rows;
      assert(derived713.length === 4
        && JSON.stringify(derived713.map(r => r.requirement)) === JSON.stringify(
          ['tdd-guide (writer)', 'security-reviewer (gateA)', 'code-reviewer (gateB)', 'finalize (finalize)']),
      '#713/#714/#833: the derived table is exactly one row per node, no duplicate, no drift, got '
        + JSON.stringify(derived713.map(r => r.requirement)));
      assert(!derived713.some(r => r.status === 'pending'),
        '#713/#714/#833: no node derives pending after the completed cycle, got '
        + JSON.stringify(derived713.map(r => r.requirement + '=' + r.status)));
    }
  } finally { fs.rmSync(tmp713, { recursive: true, force: true }); }
});

// ===========================================================================
// #728 — a schema-2 change gate must never SETTLE a failed/refuted review
// attempt with an EMPTY canonical frontier.
//
// The defect (reproduced live below): an adversarial-verifier change gate may
// legally emit `domain_outcome: refuted` with no `finding_json:` row at all —
// requiredReviewTokens never asks an AV for a finding token, and the schema-1
// flat `finding: id=... scope=...` row is invisible to parseReviewEvidence. The
// attempt then settles outcome:fail with findings:[] / current_open_uids:[], and
// assessReviewProgress compares SUCCESSIVE FRONTIERS BY UID — so [] vs [] is
// `review_frontier_nonprogress`, twice over is `review_nonconvergent`, and the
// run is pushed into a replan carrying zero record of what actually failed.
//
// The invariant is bound at the AGGREGATE/SETTLEMENT seam, never at the member:
// a member receipt whose own deriveGateEffect is 'fail' but which a majority
// reduction absorbs into a PASSING aggregate must still close normally. Block A
// is that pin.
// ===========================================================================
scenario(() => {
  const { spawnSync: spawn728 } = require('child_process');
  const reviewSchema728 = require('./kaola-workflow-adaptive-schema');
  const NODE_CLI_728 = path.join(__dirname, 'kaola-workflow-adaptive-node.js');
  const VALIDATOR_CLI_728 = path.join(__dirname, 'kaola-workflow-plan-validator.js');
  const baseEnv728 = Object.fromEntries(Object.entries(process.env).filter(([k]) => !k.startsWith('KAOLA_')));
  const env728 = { ...baseEnv728, GIT_CONFIG_GLOBAL: '/dev/null', GIT_CONFIG_NOSYSTEM: '1',
    KAOLA_WORKFLOW_OFFLINE: '1' };
  const lastJson728 = result => {
    const line = String(result.stdout || '').trim().split('\n').filter(row => row.trim().startsWith('{')).pop();
    return line ? JSON.parse(line) : null;
  };

  const tmp728 = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'kw-728-empty-frontier-')));
  // The per-scenario vehicle for the adaptive-node CLI. Every scenario drives it as a CHAIN:
  // one process writes the ledger row, the barrier baseline and the .cache evidence and EXITS,
  // and the next re-derives the whole run state from those bytes with no shared heap.
  // spawn-class: durable-handoff
  const run728 = (script, args, input) => spawn728(process.execPath, [script, ...args],
    { cwd: tmp728, encoding: 'utf8', env: env728, input, timeout: 120000 });
  try {
    G.git(tmp728, ['init', '-b', 'main'], { encoding: 'utf8', env: env728 });
    G.git(tmp728, ['config', 'user.email', 'kw@test'], { encoding: 'utf8', env: env728 });
    G.git(tmp728, ['config', 'user.name', 'kw'], { encoding: 'utf8', env: env728 });

    // One frozen schema-2 project per scenario, all inside the same repo: a serial writer
    // certified by an adversarial-verifier gate (sequence or replicated_majority fan-out),
    // then a code-reviewer certifier and the sink.
    const setup728 = (project, aggregation) => {
      const avIds = aggregation === 'sequence' ? ['av-a'] : ['av-a', 'av-b', 'av-c'];
      const shape = aggregation === 'sequence' ? 'sequence' : 'fanout(red)';
      const projectDir = path.join(tmp728, 'kaola-workflow', project);
      const cacheDir = path.join(projectDir, '.cache');
      fs.mkdirSync(cacheDir, { recursive: true });
      const implPath = path.join(tmp728, project + '-impl.js');
      fs.writeFileSync(implPath, 'module.exports = 0;\n');
      const implRel = project + '-impl.js';
      const planPath = path.join(projectDir, 'workflow-plan.md');
      fs.writeFileSync(planPath, [
        '# Workflow Plan — ' + project, '',
        '## Meta',
        'plan_form: spine', // #765: all-concrete spine — legacy dag grammar retired at freeze
        'plan_schema_version: 2',
        'labels: enhancement',
        'code_certifier: codegate',
        'security_certifier: none',
        'inherited_frontier_digest: none',
        'inherited_frontier_classes: none',
        'validation_command: node --check ' + implRel,
        'validation_timeout_minutes: 5', '',
        '## Nodes', '',
        '| id | role | depends_on | declared_write_set | cardinality | shape | gate_claim | gate_surface | gate_aggregation | certifies |',
        '|---|---|---|---|---|---|---|---|---|---|',
        '| writer | tdd-guide | — | ' + implRel + ' | 1 | sequence | — | — | — | — |',
        ...avIds.map(id => '| ' + id + ' | adversarial-verifier | writer | — | 1 | ' + shape
          + ' | change is sound | code-tree | ' + aggregation + ' | writer |'),
        '| codegate | code-reviewer | ' + avIds.join(',') + ' | — | 1 | sequence | review-change | code-tree | sequence | — |',
        '| finalize | finalize | codegate | — | 1 | sequence | — | — | — | — |', '',
        '## Design', '',
        'Decompose: writer builds the impl; adversarial-verifier gate(s) fan out over it; codegate post-dominates; finalize sinks. sequence edges are gate/data dependencies (S1). Done: gates clear and validation passes.', '',
        '## Acceptance', '',
        'A1: the implementation file is produced and passes the plan\'s validation command.',
        'A2: every adversarial-verifier gate and the code gate clear over the produced tree.', '',
        '## Node Ledger', '',
        '| id | status |', '|---|---|',
        '| writer | pending |', ...avIds.map(id => '| ' + id + ' | pending |'),
        '| codegate | pending |', '| finalize | pending |', '',
        '## Required Agent Compliance', '',
        '| Requirement | Status | Evidence | Skip Reason |', '|---|---|---|---|',
        '| tdd-guide (writer) | pending | | |',
        ...avIds.map(id => '| adversarial-verifier (' + id + ') | pending | | |'),
        '| code-reviewer (codegate) | pending | | |', '| finalize (finalize) | pending | | |', '',
      ].join('\n'));
      fs.writeFileSync(path.join(projectDir, 'workflow-state.md'), '# Workflow State\nstatus: active\n');
      const freeze = run728(VALIDATOR_CLI_728, [planPath, '--freeze', '--json']);
      assert(freeze.status === 0 && lastJson728(freeze) && lastJson728(freeze).frozen === true,
        '#728: the schema-2 AV-gate plan (' + aggregation + ') freezes: ' + freeze.stdout + freeze.stderr);
      G.git(tmp728, ['add', '-A'], { encoding: 'utf8', env: env728 });
      G.git(tmp728, ['commit', '-m', 'fixture ' + project], { encoding: 'utf8', env: env728 });
      return { project, projectDir, cacheDir, planPath, implPath, avIds };
    };

    // Drives the writer and returns the opened AV dispatch map (fan-out enters a batch;
    // a sequence gate opens directly off the writer close).
    const openGate728 = (fixture, body, writerNonce) => {
      let nonce = writerNonce;
      if (!nonce) {
        const opened = run728(NODE_CLI_728, ['open-next', '--project', fixture.project, '--json']);
        assert(opened.status === 0 && lastJson728(opened) && lastJson728(opened).nonce,
          '#728: the writer opens: ' + opened.stdout + opened.stderr);
        nonce = lastJson728(opened).nonce;
      }
      fs.writeFileSync(fixture.implPath, body);
      const rec = run728(NODE_CLI_728, ['record-evidence', '--project', fixture.project,
        '--node-id', 'writer', '--stdin', '--json'],
        'evidence-binding: writer ' + nonce + '\nRED: reproduced\nred_baseline: ' + nonce + '\n');
      assert(rec.status === 0, '#728: writer evidence records: ' + rec.stdout + rec.stderr);
      const closed = run728(NODE_CLI_728, ['close-and-open-next', '--project', fixture.project,
        '--node-id', 'writer', '--json']);
      assert(closed.status === 0, '#728: the writer closes: ' + closed.stdout + closed.stderr);
      const payload = lastJson728(closed) || {};
      const map = {};
      if (payload.opened) map[payload.opened.id] = payload.opened;
      if (payload.enterBatch) {
        const batch = run728(NODE_CLI_728, ['open-ready', '--project', fixture.project, '--json']);
        assert(batch.status === 0, '#728: the AV fan-out batch opens: ' + batch.stdout + batch.stderr);
        for (const row of ((lastJson728(batch) || {}).opened || [])) map[row.id] = row;
      }
      return { map, writerNonce: nonce };
    };

    const gateEvidence728 = (opened, domainOutcome, aggregation, extraRows) => [
      'evidence-binding: ' + opened.id + ' ' + opened.nonce,
      'contract_version: 2',
      'review_context_hash: ' + opened.dispatch.review_context_hash,
      'behavior_contract_hash: ' + opened.dispatch.behavior_contract_hash,
      'resolved_profile_hash: ' + opened.dispatch.resolved_profile_hash,
      'candidate_digest: ' + opened.dispatch.candidate_digest,
      'domain_outcome: ' + domainOutcome,
      'claim_outcome: ' + domainOutcome,
      'gate_mode: change_gate',
      'gate_claim: change is sound',
      'gate_surface: code-tree',
      'gate_aggregation: ' + aggregation,
      ...(extraRows || []), '',
    ].join('\n');

    const journal728 = fixture => {
      const file = path.join(fixture.cacheDir, 'review-attempts.json');
      return fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, 'utf8')) : { attempts: [] };
    };

    // -- Block A (MANDATORY, the anti-false-block pin) -------------------------
    // replicated_majority AV fan-out: two replicas not_refuted, one indeterminate.
    // The minority's OWN deriveGateEffect is 'fail'; the reduction absorbs it into a
    // PASSING aggregate. Every replica must close normally and the gate must PASS —
    // a per-MEMBER empty-frontier refusal would hard-block this legal run, and the
    // only way to clear such a block would be for the abstaining replica to FABRICATE
    // a failure_class + four trigger digests + an anchor for a defect it could not
    // determine, planting an invented UID in the frontier of a PASSING gate.
    {
      const fx = setup728('issue-728-majority', 'replicated_majority');
      const gate = openGate728(fx, 'module.exports = 1;\n');
      const closes = fx.avIds.map((id, index) => {
        const outcome = index === 2 ? 'indeterminate' : 'not_refuted';
        const rec = run728(NODE_CLI_728, ['record-evidence', '--project', fx.project,
          '--node-id', id, '--stdin', '--json'],
          gateEvidence728(gate.map[id], outcome, 'replicated_majority'));
        assert(rec.status === 0, '#728A: ' + id + ' (' + outcome + ') evidence records: ' + rec.stdout + rec.stderr);
        return run728(NODE_CLI_728, ['close-node', '--project', fx.project, '--node-id', id, '--json']);
      });
      assert(closes.every(result => result.status === 0
        && lastJson728(result) && lastJson728(result).result === 'ok'),
        '#728A: EVERY replica of a replicated_majority AV fan-out closes normally when the '
        + 'minority abstains (indeterminate) and the majority is not_refuted — the empty-frontier '
        + 'invariant binds the AGGREGATE, never the member, got '
        + closes.map(result => String(result.stdout).trim().split('\n').pop()).join(' | '));
      const attemptsA = journal728(fx).attempts;
      assert(attemptsA.length === 1 && attemptsA[0].outcome === 'pass'
        && attemptsA[0].reducer.gate_effect === 'pass'
        && attemptsA[0].reducer.domain_outcome === 'not_refuted',
        '#728A: the absorbed minority still reduces to a PASSING aggregate, got '
        + JSON.stringify(attemptsA.map(a => ({ outcome: a.outcome, reducer: a.reducer }))));
      const minority = attemptsA[0].receipts.find(receipt => receipt.node_id === 'av-c');
      assert(minority && minority.domain_outcome === 'indeterminate' && minority.gate_effect === 'fail'
        && minority.findings.length === 0,
        '#728A: the absorbed member receipt is individually gate_effect:fail with ZERO findings and '
        + 'stays LEGAL — that member combination is exactly what a per-member refusal false-blocks, got '
        + JSON.stringify(minority && { d: minority.domain_outcome, g: minority.gate_effect, f: minority.findings }));
      assert(attemptsA[0].current_open_uids.length === 0,
        '#728A: a PASSING gate with zero findings stays legal — an empty frontier is only '
        + 'incoherent behind a FAILING aggregate (the over-refusal trap)');
      const planA = fs.readFileSync(fx.planPath, 'utf8');
      const ledgerA = planA.slice(planA.indexOf('## Node Ledger'));
      assert(fx.avIds.every(id => new RegExp('\\| ' + id + ' \\| complete \\|').test(ledgerA)),
        '#728A: the whole fan-out reaches complete (the gate PASSED, nothing folded), got:\n' + ledgerA);
    }

    // -- Block B (the defect) --------------------------------------------------
    // A refuted sequence AV change gate whose only finding is a schema-1 FLAT
    // `finding:` row (plus a `## finding-anchor-v1` prose anchor and a
    // `findings_blocking: 1` row — the exact live consumer receipt shape). The
    // canonical frontier is empty, so the settlement is verdictless and must refuse.
    {
      const fx = setup728('issue-728-flat', 'sequence');
      const gate = openGate728(fx, 'module.exports = 1;\n');
      const flatRows = [
        'finding: id=R8 scope=in_scope action=fix status=open severity=high fix_role=tdd-guide',
        'findings_blocking: 1',
        '## finding-anchor-v1',
        'the change regresses the documented behavior',
      ];
      const rec = run728(NODE_CLI_728, ['record-evidence', '--project', fx.project,
        '--node-id', 'av-a', '--stdin', '--json'],
        gateEvidence728(gate.map['av-a'], 'refuted', 'sequence', flatRows));
      assert(rec.status === 0, '#728B: the flat-row refuted evidence records: ' + rec.stdout + rec.stderr);
      const close = run728(NODE_CLI_728, ['close-node', '--project', fx.project,
        '--node-id', 'av-a', '--json']);
      const payload = lastJson728(close) || {};
      assert(payload.result === 'refuse' && payload.reason === 'review_settlement_missing_findings',
        '#728B: a FAILING aggregate (refuted) whose canonical frontier is EMPTY must be refused at '
        + 'the settlement seam — pre-fix it settles review_failed with findings:[] and poisons '
        + 'convergence, got ' + JSON.stringify(payload));
      assert(Array.isArray(payload.incoherent_members) && payload.incoherent_members.includes('av-a'),
        '#728B: the refusal names the member receipt(s) that declared a gate failure without a '
        + 'canonical finding, so the re-emit is actionable, got ' + JSON.stringify(payload.incoherent_members));
      assert(journal728(fx).attempts.length === 0,
        '#728B: NOTHING is written to the review journal — the verdictless attempt never becomes '
        + 'durable, so it can never advance the nonprogress counter, got '
        + JSON.stringify(journal728(fx).attempts.map(a => ({ o: a.outcome, u: a.current_open_uids }))));
    }

    // -- Blocks C + E (unchanged behavior + convergence) ------------------------
    // A properly-formed `finding_json:` refutation settles exactly as before, and the
    // SAME underlying finding re-presented after a repair keeps a NON-EMPTY frontier on
    // both attempts (pre-fix the flat-row equivalent yields [] then [] -> nonprogress).
    {
      const fx = setup728('issue-728-canonical', 'sequence');
      const gate = openGate728(fx, 'module.exports = 1;\n');
      // The anchor is PATH-BEARING on purpose. A BLOCKING (in_scope / fix / open) finding at a
      // FAILING change gate must name a repository path or the record seam refuses it
      // (review_finding_anchor_unroutable) — a path-less blocking finding could commit an attempt no
      // repair route can place. That gate is orthogonal to what these blocks pin (the frontier must
      // be non-empty behind a failing aggregate), so the fixture uses an anchor that satisfies both.
      const objectFormat728 = String(G.git(tmp728, ['rev-parse', '--show-object-format'], { encoding: 'utf8', env: env728 }).stdout).trim();
      const objectId728 = String(G.git(tmp728, ['hash-object', fx.implPath], { encoding: 'utf8', env: env728 }).stdout).trim();
      const finding728 = {
        failure_class: 'correctness',
        trigger: { precondition_digest: '1'.repeat(64), input_digest: '2'.repeat(64),
          expected_digest: '3'.repeat(64), observed_digest: '4'.repeat(64) },
        primary_anchor: { kind: 'candidate_range', path: fx.project + '-impl.js',
          object_format: objectFormat728, tree_mode: '100644', object_id: objectId728,
          start: 0, end: 1, blob_length: fs.readFileSync(fx.implPath).length },
        secondary_anchors: [], severity: 'high', scope: 'in_scope', action: 'fix',
        status: 'open', fix_role: 'tdd-guide', proof_digest: '6'.repeat(64),
      };
      let rec = run728(NODE_CLI_728, ['record-evidence', '--project', fx.project,
        '--node-id', 'av-a', '--stdin', '--json'],
        gateEvidence728(gate.map['av-a'], 'refuted', 'sequence',
          ['finding_json: ' + JSON.stringify(finding728)]));
      assert(rec.status === 0, '#728C: the canonical refuted evidence records: ' + rec.stdout + rec.stderr);
      const close1 = run728(NODE_CLI_728, ['close-node', '--project', fx.project,
        '--node-id', 'av-a', '--json']);
      const payload1 = lastJson728(close1) || {};
      assert(payload1.result === 'review_failed' && payload1.reason === 'review_gate_failed',
        '#728C: a properly-formed finding_json refutation still settles review_failed, byte-for-byte '
        + 'the pre-fix behavior, got ' + JSON.stringify(payload1));
      const attempt1 = journal728(fx).attempts[0];
      assert(attempt1 && attempt1.outcome === 'fail' && attempt1.current_open_uids.length === 1
        && attempt1.findings.length === 1,
        '#728C: the settled failure carries a NON-empty canonical frontier, got '
        + JSON.stringify(attempt1 && { o: attempt1.outcome, u: attempt1.current_open_uids }));

      // E: repair, re-present the SAME finding, and prove the second failed attempt is
      // also frontier-bearing — the pair a nonconvergence verdict is computed from.
      const repair = run728(NODE_CLI_728, ['repair-node', '--project', fx.project,
        '--attempt-id', attempt1.attempt_id, '--node-id', 'writer', '--json']);
      assert(repair.status === 0 && lastJson728(repair).result === 'ok',
        '#728E: repair-node consumes the failed attempt: ' + repair.stdout + repair.stderr);
      const gate2 = openGate728(fx, 'module.exports = 2;\n', gate.writerNonce);
      rec = run728(NODE_CLI_728, ['record-evidence', '--project', fx.project,
        '--node-id', 'av-a', '--stdin', '--json'],
        gateEvidence728(gate2.map['av-a'], 'refuted', 'sequence',
          ['finding_json: ' + JSON.stringify(finding728)]));
      assert(rec.status === 0, '#728E: the re-presented finding records: ' + rec.stdout + rec.stderr);
      const close2 = run728(NODE_CLI_728, ['close-node', '--project', fx.project,
        '--node-id', 'av-a', '--json']);
      assert((lastJson728(close2) || {}).result === 'review_failed',
        '#728E: the second attempt settles as a review failure: ' + close2.stdout + close2.stderr);
      const attempts = journal728(fx).attempts;
      assert(attempts.length === 2
        && attempts.every(attempt => attempt.outcome === 'fail' && attempt.current_open_uids.length === 1)
        && attempts[0].current_open_uids[0] === attempts[1].current_open_uids[0],
        '#728E: TWO successive failed attempts carrying the same underlying finding both keep a '
        + 'non-empty frontier and agree on its UID — the pre-fix flat-row path yields [] then [], '
        + 'which assessReviewProgress reads as review_frontier_nonprogress, got '
        + JSON.stringify(attempts.map(a => ({ o: a.outcome, u: a.current_open_uids }))));
      assert(reviewSchema728.validateReviewJournal(journal728(fx),
        journal728(fx).plan_hash, 2).ok === true,
        '#728E: the two-attempt journal round-trips the strict V2 validator unchanged');
    }

    // -- Block D (over-refusal trap, sequence form) -----------------------------
    // A not_refuted sequence AV change gate with zero findings PASSES. The invariant
    // must not touch it: an empty frontier is only incoherent behind a FAILING aggregate.
    {
      const fx = setup728('issue-728-clean', 'sequence');
      const gate = openGate728(fx, 'module.exports = 1;\n');
      const rec = run728(NODE_CLI_728, ['record-evidence', '--project', fx.project,
        '--node-id', 'av-a', '--stdin', '--json'],
        gateEvidence728(gate.map['av-a'], 'not_refuted', 'sequence'));
      assert(rec.status === 0, '#728D: the clean evidence records: ' + rec.stdout + rec.stderr);
      const close = run728(NODE_CLI_728, ['close-and-open-next', '--project', fx.project,
        '--node-id', 'av-a', '--json']);
      const payload = lastJson728(close) || {};
      assert(close.status === 0 && payload.result === 'ok' && payload.closed === 'av-a'
        && payload.opened && payload.opened.id === 'codegate',
        '#728D: a PASSING change gate with zero findings closes and advances, untouched by the '
        + 'empty-frontier invariant, got ' + JSON.stringify(payload));
      const attempts = journal728(fx).attempts;
      assert(attempts.length === 1 && attempts[0].outcome === 'pass'
        && attempts[0].current_open_uids.length === 0,
        '#728D: its settled attempt is a PASS with an empty frontier — legal, got '
        + JSON.stringify(attempts.map(a => ({ o: a.outcome, u: a.current_open_uids }))));
    }
  } finally { fs.rmSync(tmp728, { recursive: true, force: true }); }
});

// ===========================================================================
// #733 — a settled FAILED schema-2 review must refresh the derived task mirror.
//
// prepareSchema2ReviewClose / prepareReviewClose splice the folded ledger rows
// back to `pending`, write the plan, and RETURN — both callsites early-return past
// every `taskMirror: refreshTaskMirror(...)` in the file, so `workflow-tasks.json`
// kept reporting the pre-fold status. The mirror is fail-OPEN at write by design,
// so the refresh is wired at the mutation site and its failure is reported, never
// raised: a mirror-write fault must not roll back a correct ledger transition.
// ===========================================================================
scenario(() => {
  const { spawnSync: spawn733 } = require('child_process');
  const NODE_CLI_733 = path.join(__dirname, 'kaola-workflow-adaptive-node.js');
  const VALIDATOR_CLI_733 = path.join(__dirname, 'kaola-workflow-plan-validator.js');
  const baseEnv733 = Object.fromEntries(Object.entries(process.env).filter(([k]) => !k.startsWith('KAOLA_')));
  const env733 = { ...baseEnv733, GIT_CONFIG_GLOBAL: '/dev/null', GIT_CONFIG_NOSYSTEM: '1',
    KAOLA_WORKFLOW_OFFLINE: '1' };
  const lastJson733 = result => {
    const line = String(result.stdout || '').trim().split('\n').filter(row => row.trim().startsWith('{')).pop();
    return line ? JSON.parse(line) : null;
  };
  const tmp733 = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'kw-733-mirror-')));
  // The per-scenario vehicle for the adaptive-node CLI. Every scenario drives it as a CHAIN:
  // one process writes the ledger row, the barrier baseline and the .cache evidence and EXITS,
  // and the next re-derives the whole run state from those bytes with no shared heap.
  // spawn-class: durable-handoff
  const run733 = (args, input) => spawn733(process.execPath, [NODE_CLI_733, ...args],
    { cwd: tmp733, encoding: 'utf8', env: env733, input, timeout: 120000 });
  try {
    G.git(tmp733, ['init', '-b', 'main'], { encoding: 'utf8', env: env733 });
    G.git(tmp733, ['config', 'user.email', 'kw@test'], { encoding: 'utf8', env: env733 });
    G.git(tmp733, ['config', 'user.name', 'kw'], { encoding: 'utf8', env: env733 });

    // One frozen schema-2 project per scenario: a serial writer certified by a
    // code-reviewer sequence gate, then the sink.
    const setup733 = (project) => {
      const projectDir = path.join(tmp733, 'kaola-workflow', project);
      const cacheDir = path.join(projectDir, '.cache');
      fs.mkdirSync(cacheDir, { recursive: true });
      const implRel = project + '-impl.js';
      fs.writeFileSync(path.join(tmp733, implRel), 'module.exports = 0;\n');
      const planPath = path.join(projectDir, 'workflow-plan.md');
      fs.writeFileSync(planPath, [
        '# Workflow Plan — ' + project, '',
        '## Meta', 'plan_form: spine', 'plan_schema_version: 2', 'labels: enhancement',
        'code_certifier: codegate', 'security_certifier: none',
        'inherited_frontier_digest: none', 'inherited_frontier_classes: none',
        'validation_command: node --check ' + implRel, 'validation_timeout_minutes: 5', '',
        '## Nodes', '',
        '| id | role | depends_on | declared_write_set | cardinality | shape | gate_claim | gate_surface | gate_aggregation | certifies |',
        '|---|---|---|---|---|---|---|---|---|---|',
        '| writer | tdd-guide | — | ' + implRel + ' | 1 | sequence | — | — | — | — |',
        '| codegate | code-reviewer | writer | — | 1 | sequence | review-change | code-tree | sequence | — |',
        '| finalize | finalize | codegate | — | 1 | sequence | — | — | — | — |', '',
        '## Design', '',
        'Decompose: writer builds the impl; codegate post-dominates it; finalize sinks. sequence writer→codegate: S1 — codegate consumes the writer change. Done: gate clears and validation passes.', '',
        '## Acceptance', '',
        'A1: the implementation file is produced and passes the plan\'s validation command.',
        'A2: the code gate clears over the produced tree.', '',
        '## Node Ledger', '', '| id | status |', '|---|---|',
        '| writer | pending |', '| codegate | pending |', '| finalize | pending |', '',
        '## Required Agent Compliance', '',
        '| Requirement | Status | Evidence | Skip Reason |', '|---|---|---|---|',
        '| tdd-guide (writer) | pending | | |', '| code-reviewer (codegate) | pending | | |',
        '| finalize (finalize) | pending | | |', '',
      ].join('\n'));
      fs.writeFileSync(path.join(projectDir, 'workflow-state.md'), '# Workflow State\nstatus: active\n');
      // --freeze stamps plan_hash into workflow-plan.md and EXITS; every adaptive-node process in
      // this scenario then re-reads and re-verifies that stamp from disk.
      // spawn-class: durable-handoff
      const freeze = spawn733(process.execPath, [VALIDATOR_CLI_733, planPath, '--freeze', '--json'],
        { cwd: tmp733, encoding: 'utf8', env: env733 });
      assert(freeze.status === 0 && lastJson733(freeze) && lastJson733(freeze).frozen === true,
        '#733: the schema-2 gate plan freezes: ' + freeze.stdout + freeze.stderr);
      G.git(tmp733, ['add', '-A'], { encoding: 'utf8', env: env733 });
      G.git(tmp733, ['commit', '-m', 'fixture ' + project], { encoding: 'utf8', env: env733 });
      return { project, projectDir, cacheDir, planPath, implRel };
    };

    // Drives the writer, then settles the code gate with a blocking verdict.
    const settleFailed733 = (fx) => {
      const opened = run733(['open-next', '--project', fx.project, '--json']);
      const openNonce = (lastJson733(opened) || {}).nonce;
      assert(opened.status === 0 && openNonce, '#733: the writer opens: ' + opened.stdout + opened.stderr);
      fs.writeFileSync(path.join(tmp733, fx.implRel), 'module.exports = 1;\n');
      const rec = run733(['record-evidence', '--project', fx.project, '--node-id', 'writer',
        '--stdin', '--json'],
      'evidence-binding: writer ' + openNonce + '\nRED: reproduced\nred_baseline: ' + openNonce + '\n');
      assert(rec.status === 0, '#733: writer evidence records: ' + rec.stdout + rec.stderr);
      const closedWriter = run733(['close-and-open-next', '--project', fx.project,
        '--node-id', 'writer', '--json']);
      const gate = (lastJson733(closedWriter) || {}).opened;
      assert(closedWriter.status === 0 && gate && gate.id === 'codegate',
        '#733: the writer closes and the code gate opens: ' + closedWriter.stdout + closedWriter.stderr);
      // #805: a change gate's BLOCKING findings must carry a PATH-BEARING primary anchor — an anchor
      // with no path routes to no writer, so the attempt would commit with no reachable repair.
      // `candidate_range` over the writer's own declared file is the faithful shape (the defect IS
      // there) and binds to the real candidate blob the anchor index checks.
      const objectFormat733 = String(G.git(tmp733, ['rev-parse', '--show-object-format'], { encoding: 'utf8', env: env733 }).stdout).trim();
      const implObjectId733 = String(G.git(tmp733, ['hash-object', fx.implRel], { encoding: 'utf8', env: env733 }).stdout).trim();
      assert(/^[0-9a-f]{40,64}$/.test(implObjectId733),
        '#733 fixture: the candidate blob id for ' + fx.implRel + ' resolves, got ' + JSON.stringify(implObjectId733));
      const finding = {
        failure_class: 'correctness',
        trigger: { precondition_digest: '1'.repeat(64), input_digest: '2'.repeat(64),
          expected_digest: '3'.repeat(64), observed_digest: '4'.repeat(64) },
        primary_anchor: { kind: 'candidate_range', path: fx.implRel,
          object_format: objectFormat733, tree_mode: '100644', object_id: implObjectId733,
          start: 0, end: 1, blob_length: fs.readFileSync(path.join(tmp733, fx.implRel)).length },
        secondary_anchors: [], severity: 'high', scope: 'in_scope', action: 'fix',
        status: 'open', fix_role: 'tdd-guide', proof_digest: '6'.repeat(64),
      };
      const gateRec = run733(['record-evidence', '--project', fx.project, '--node-id', 'codegate',
        '--stdin', '--json'], [
        'evidence-binding: codegate ' + gate.nonce,
        'contract_version: 2',
        'review_context_hash: ' + gate.dispatch.review_context_hash,
        'behavior_contract_hash: ' + gate.dispatch.behavior_contract_hash,
        'resolved_profile_hash: ' + gate.dispatch.resolved_profile_hash,
        'candidate_digest: ' + gate.dispatch.candidate_digest,
        'verdict: fail', 'findings_blocking: 1',
        'domain_outcome: changes_requested', 'claim_outcome: changes_requested', 'gate_mode: change_gate',
        'gate_claim: review-change', 'gate_surface: code-tree', 'gate_aggregation: sequence',
        'finding_json: ' + JSON.stringify(finding), '',
      ].join('\n'));
      assert(gateRec.status === 0, '#733: gate evidence records: ' + gateRec.stdout + gateRec.stderr);
      return run733(['close-node', '--project', fx.project, '--node-id', 'codegate', '--json']);
    };

    // -- Pin B: the settlement refreshes the mirror, and the fold lands on disk. --
    {
      const fx = setup733('issue-733-refresh');
      const close = settleFailed733(fx);
      const payload = lastJson733(close) || {};
      assert(close.status === 0 && payload.result === 'review_failed',
        '#733-B: the failed code gate settles: ' + close.stdout + close.stderr);
      assert(payload.taskMirror && payload.taskMirror.status === 'updated',
        '#733-B: a settled FAILED review reports a REFRESHED task mirror, exactly like every other '
        + 'ledger-mutating envelope in this file — pre-fix the field was absent entirely, got '
        + JSON.stringify(payload.taskMirror));
      const mirror = JSON.parse(fs.readFileSync(path.join(fx.projectDir, 'workflow-tasks.json'), 'utf8'));
      const gateRow = mirror.tasks.find(task => task.id === 'codegate');
      assert(gateRow && gateRow.ledger_status === 'pending' && gateRow.status === 'pending',
        '#733-B: the folded gate reads `pending` in the on-disk mirror, matching the rewound ledger '
        + '— pre-fix it still reported `in_progress`, got ' + JSON.stringify(gateRow));
      const plan = fs.readFileSync(fx.planPath, 'utf8');
      const ledger = plan.slice(plan.indexOf('## Node Ledger'));
      assert(/\| codegate \| pending \|/.test(ledger),
        '#733-B: the ledger itself is rewound (the settlement is unchanged), got:\n' + ledger);
    }

    // -- Pin B (fail-open guard): a mirror-write fault must not wedge the settlement. --
    // `workflow-tasks.json` is a DIRECTORY, so the task-mirror CLI's write throws EISDIR.
    // refreshTaskMirror swallows the non-zero exit and reports `failed`; the review still
    // settles. A surface that is fail-open at write can never be fail-closed at read.
    {
      const fx = setup733('issue-733-failopen');
      fs.mkdirSync(path.join(fx.projectDir, 'workflow-tasks.json'), { recursive: true });
      const close = settleFailed733(fx);
      const payload = lastJson733(close) || {};
      assert(close.status === 0 && payload.result === 'review_failed',
        '#733-B-failopen: a mirror-write fault does NOT roll back a correct settlement: '
        + close.stdout + close.stderr);
      assert(payload.taskMirror && payload.taskMirror.status === 'failed',
        '#733-B-failopen: the fault is REPORTED on the envelope rather than raised, got '
        + JSON.stringify(payload.taskMirror));
      const plan = fs.readFileSync(fx.planPath, 'utf8');
      assert(/\| codegate \| pending \|/.test(plan.slice(plan.indexOf('## Node Ledger'))),
        '#733-B-failopen: the ledger fold still landed');
    }
  } finally { fs.rmSync(tmp733, { recursive: true, force: true }); }
});

// ---------------------------------------------------------------------------
// #727: the domain_outcome ENUM is named at BOTH ends — the open-time seeded stub and the
// close-time refusal hint — and BOTH derive from the SAME source of truth the validator uses
// (adaptive-schema's ADVERSARIAL_OUTCOMES / APPROVAL_OUTCOMES). The generic
// `<!-- domain_outcome: paste domain_outcome here -->` stub plus a hintless
// review_domain_outcome_invalid refusal made `domain_outcome: pass` (the gate EFFECT vocabulary)
// a plausible, only-discovered-at-close mistake.
// ---------------------------------------------------------------------------
scenario(() => {
  const {
    ADVERSARIAL_OUTCOMES: SCHEMA_ADVERSARIAL_OUTCOMES,
    APPROVAL_OUTCOMES: SCHEMA_APPROVAL_OUTCOMES,
  } = require('./kaola-workflow-adaptive-schema');
  const { allowedDomainOutcomes } = require('./kaola-workflow-adaptive-node');

  // (a) the single role-kind selector is EXPORTED and returns the validator's own frozen arrays —
  // not a hand-copied duplicate that can drift.
  assert(typeof allowedDomainOutcomes === 'function',
    '#727-A: allowedDomainOutcomes(role) is exported as the single role-kind enum selector');
  if (typeof allowedDomainOutcomes === 'function') {
    assert(allowedDomainOutcomes('adversarial-verifier') === SCHEMA_ADVERSARIAL_OUTCOMES,
      '#727-A: adversarial-verifier resolves to the schema ADVERSARIAL_OUTCOMES array IDENTITY (no copy)');
    assert(allowedDomainOutcomes('code-reviewer') === SCHEMA_APPROVAL_OUTCOMES
      && allowedDomainOutcomes('security-reviewer') === SCHEMA_APPROVAL_OUTCOMES,
      '#727-A: approval gates resolve to the schema APPROVAL_OUTCOMES array IDENTITY (no copy)');
  }

  // (b) OPEN END — the seeded stub names the allowed values for THAT gate's role kind.
  const tmp727 = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-727-seed-'));
  try {
    const projectDir = path.join(tmp727, 'kaola-workflow', 'issue-727');
    fs.mkdirSync(projectDir, { recursive: true });
    const planPath = path.join(projectDir, 'workflow-plan.md');
    fs.writeFileSync(planPath, '# plan\n');
    const reviewOpen = { ok: true, required_tokens: ['evidence-binding', 'contract_version',
      'review_context_hash', 'behavior_contract_hash', 'resolved_profile_hash', 'candidate_digest',
      'domain_outcome', 'gate_claim', 'gate_surface', 'gate_aggregation', 'finding_json|findings_none'] };
    seedEvidenceFile(planPath, 'gate-approval', 'nonce727aaaa', 'code-reviewer', true, reviewOpen);
    const approvalSeed = fs.readFileSync(path.join(projectDir, '.cache', 'gate-approval.md'), 'utf8');
    const approvalStub = (approvalSeed.match(/^<!--[ \t]*domain_outcome:.*-->$/m) || [''])[0];
    assert(SCHEMA_APPROVAL_OUTCOMES.every(v => approvalStub.includes(v)),
      '#727-B: the approval-gate domain_outcome stub NAMES ' + SCHEMA_APPROVAL_OUTCOMES.join('|')
      + ', got: ' + JSON.stringify(approvalStub));
    assert(!SCHEMA_ADVERSARIAL_OUTCOMES.some(v => approvalStub.includes(v)),
      '#727-B: the approval-gate stub does NOT leak the adversarial vocabulary, got: ' + JSON.stringify(approvalStub));
    assert(!/paste domain_outcome here/.test(approvalSeed),
      '#727-B: the generic "paste domain_outcome here" stub is gone for a review gate');
    // The stub comment stays NON-column-0-anchored on the token key, so it can never satisfy a
    // present-and-non-empty token check (the seeded value line remains empty).
    assert(/^domain_outcome:[ \t]*$/m.test(approvalSeed),
      '#727-B: the seeded domain_outcome VALUE line stays empty (hollow-seed guard unchanged)');

    seedEvidenceFile(planPath, 'gate-adversarial', 'nonce727bbbb', 'adversarial-verifier', true,
      { ok: true, required_tokens: ['evidence-binding', 'contract_version', 'review_context_hash',
        'behavior_contract_hash', 'resolved_profile_hash', 'candidate_digest', 'domain_outcome',
        'claim_outcome'] });
    const advSeed = fs.readFileSync(path.join(projectDir, '.cache', 'gate-adversarial.md'), 'utf8');
    const advStub = (advSeed.match(/^<!--[ \t]*domain_outcome:.*-->$/m) || [''])[0];
    assert(SCHEMA_ADVERSARIAL_OUTCOMES.every(v => advStub.includes(v)),
      '#727-B: the adversarial-verifier domain_outcome stub NAMES '
      + SCHEMA_ADVERSARIAL_OUTCOMES.join('|') + ', got: ' + JSON.stringify(advStub));
    assert(!advStub.includes('approved'),
      '#727-B: the adversarial stub does NOT leak the approval vocabulary, got: ' + JSON.stringify(advStub));

    // A NON-review role is untouched — the generic stub shape is preserved everywhere else.
    seedEvidenceFile(planPath, 'w1', 'nonce727cccc', 'implementer', true);
    const implSeed = fs.readFileSync(path.join(projectDir, '.cache', 'w1.md'), 'utf8');
    assert(/<!-- tests-green\|regression-green\|build-green\|smoke-integration -->/.test(implSeed),
      '#727-B: a non-review role keeps the generic stub shape, got:\n' + implSeed);
  } finally { fs.rmSync(tmp727, { recursive: true, force: true }); }

  // (c) CLOSE END — review_domain_outcome_invalid has a registered hint that names the enum for the
  // role kind involved (it previously fell through to the generic "run orient" fallback).
  assert(typeof OPERATOR_HINT_REGISTRY.review_domain_outcome_invalid === 'function',
    '#727-C: OPERATOR_HINT_REGISTRY.review_domain_outcome_invalid is registered');
  const hintApproval = getOperatorHint('review_domain_outcome_invalid',
    { nodeId: 'gate-approval', role: 'code-reviewer' });
  assert(SCHEMA_APPROVAL_OUTCOMES.every(v => hintApproval.includes(v))
    && !SCHEMA_ADVERSARIAL_OUTCOMES.some(v => hintApproval.includes(v)),
    '#727-C: the approval-gate hint names ' + SCHEMA_APPROVAL_OUTCOMES.join('|') + ' only, got: ' + hintApproval);
  const hintAdversarial = getOperatorHint('review_domain_outcome_invalid',
    { nodeId: 'gate-adversarial', role: 'adversarial-verifier' });
  assert(SCHEMA_ADVERSARIAL_OUTCOMES.every(v => hintAdversarial.includes(v))
    && !hintAdversarial.includes('approved'),
    '#727-C: the adversarial hint names ' + SCHEMA_ADVERSARIAL_OUTCOMES.join('|') + ' only, got: ' + hintAdversarial);
  // The observed mistake — `domain_outcome: pass` (the gate EFFECT vocabulary) — is named as such.
  assert(/pass/.test(hintApproval) && /pass/.test(hintAdversarial),
    '#727-C: both hints warn that the gate EFFECT vocabulary (pass/fail) is not a domain_outcome');
  // Role-less emit context still names BOTH enums rather than degrading to the generic fallback.
  const hintNoRole = getOperatorHint('review_domain_outcome_invalid', { nodeId: 'g' });
  assert(SCHEMA_APPROVAL_OUTCOMES.concat(SCHEMA_ADVERSARIAL_OUTCOMES).every(v => hintNoRole.includes(v))
    && !/Run orient to inspect the plan \+ ledger state and the relevant plan-run recovery card\./.test(hintNoRole),
    '#727-C: a role-less context names BOTH enums (never the generic fallback), got: ' + hintNoRole);
});

// ===========================================================================
// CLUSTER #759 — THE EXPANSION TRANSACTION.
//
// Covers the pure composition validator, the two append primitives (the whole append-at-tail
// durability story), the writer/parser round trip, the fail-closed gates on expand-open, and the
// reconcile roll-forward arm.
// ===========================================================================
scenario(() => {
  const {
    runExpandOpen, runExpandClose, rollForwardExpansions,
    validateComposition, renderExpansionRecord, appendExpansionBlock, appendLedgerRows,
  } = require('./kaola-workflow-adaptive-node');
  const validator759 = require('./kaola-workflow-plan-validator');
  const roles759 = new Set(validator759.installedRoles(process.cwd()));

  const DERIVATION = { grain: 'g', path: 'p', join: 'j', probe: 'pr', serializer: 'none' };
  const comp = units => ({ derivation: { ...DERIVATION }, units });
  const ctx759 = { point: 'm1', installedRoles: roles759 };
  const refusalOf = (composition) => {
    const r = validateComposition(composition, ctx759);
    return r.ok ? null : r.refusal.reason;
  };

  // --- (A) validateComposition: the shape rules. -----------------------------------------------
  {
    const ok = validateComposition(comp([
      { name: 'u1', role: 'code-explorer', model: 'standard', write_set: '', mode: 'co_open' },
      { name: 'u2', role: 'tdd-guide', model: 'reasoning', write_set: 'scripts/a.js', mode: 'serial', depends_on: ['u1'] },
    ]), ctx759);
    assert(ok.ok === true, '#759-A: a well-formed composition must validate, got ' + JSON.stringify(ok.refusal || ok));
    assert(ok.units[1].depends_on.length === 1 && ok.units[1].mode === 'serial',
      '#759-A: the normalized unit must keep its named serializer edge');

    // The five derivation lines are checked for PRESENCE only — never for content. Absence refuses.
    for (const k of ['grain', 'path', 'join', 'probe', 'serializer']) {
      const d = { ...DERIVATION }; delete d[k];
      const r = validateComposition({ derivation: d, units: [{ name: 'u1', role: 'code-explorer', mode: 'co_open' }] }, ctx759);
      assert(!r.ok && r.refusal.reason === 'expansion_derivation_incomplete',
        '#759-A: a missing "' + k + '" derivation line must refuse expansion_derivation_incomplete, got ' + JSON.stringify(r.refusal || r));
    }
    assert(refusalOf({ derivation: { ...DERIVATION }, units: [] }) === 'expansion_units_empty',
      '#759-A: an empty frontier refuses');
    assert(refusalOf(null) === 'expansion_composition_malformed', '#759-A: a non-object composition refuses');
    assert(refusalOf(comp([{ name: 'bad name', role: 'code-explorer', mode: 'co_open' }])) === 'expansion_unit_name_invalid',
      '#759-A: a unit name outside [A-Za-z0-9_-] refuses (it becomes a plan node id)');
    assert(refusalOf(comp([
      { name: 'u1', role: 'code-explorer', mode: 'co_open' },
      { name: 'u1', role: 'code-explorer', mode: 'co_open' },
    ])) === 'expansion_unit_name_duplicate', '#759-A: a duplicated unit name refuses');
    assert(refusalOf(comp([{ name: 'u1', role: 'not-a-role', mode: 'co_open' }])) === 'expansion_unit_role_unknown',
      '#759-A: a role outside the installed library refuses');
    for (const reserved of ['finalize', 'main-session-gate', 'expansion-point']) {
      assert(refusalOf(comp([{ name: 'u1', role: reserved, mode: 'co_open' }])) === 'expansion_unit_role_reserved',
        '#759-A: a composed unit may not take the built-in role "' + reserved + '"');
    }
    // COMPOSED REVIEW-GATE UNITS ARE REFUSED BY NAME — the hard-wedge fix.
    //
    // A composed gate unit used to be a LEGAL composition, and it made the run unrecoverable: the OPEN
    // path resolves the review-gate contract through the FREEZE view (prepareReviewOpen ->
    // validator.parseNodes, spine only) and cannot SEE a composed unit, so the gate is dispatched
    // schema-1-shaped (required_tokens [evidence-binding, verdict, findings_blocking]; no
    // contract_version, no review_context_hash); the CLOSE path resolves it through the EXECUTION view
    // (planNodesWithExpansions), DOES see the gate role, and applies the schema-2 review close. The
    // close then refuses review_context_mismatch forever, expand-close refuses scheduler_active over
    // the still-live unit, reconcile-running-set no-ops on the stable set, and the ready set is empty.
    // It is NOT "invisible and therefore fail-closed" — it is invisible at OPEN and ENFORCED at CLOSE.
    // Hence a typed COMPOSE-TIME refusal that names the unit and the role.
    for (const gate of ['code-reviewer', 'security-reviewer', 'adversarial-verifier']) {
      const r = validateComposition(comp([{ name: 'g1', role: gate, mode: 'co_open' }]), ctx759);
      assert(!r.ok && r.refusal.reason === 'expansion_unit_role_gate_unsupported',
        '#759-A: a composed "' + gate + '" unit must refuse expansion_unit_role_gate_unsupported, got '
        + JSON.stringify(r.refusal || r));
      assert(new RegExp('g1').test(r.refusal.detail) && new RegExp(gate).test(r.refusal.detail)
        && /not yet supported/.test(r.refusal.detail),
      '#759-A: the refusal must NAME the unit and the role and say composed gate units are not yet '
        + 'supported (never a silent drop), got ' + JSON.stringify(r.refusal.detail));
    }
    // The gate refusal must fire even when the role IS installed — it is a capability statement, not a
    // library lookup. (All three gate roles ship in the library, so this is the live case, and the
    // `expansion_unit_role_unknown` reason must never be what surfaces for them.)
    assert(roles759.has('code-reviewer'),
      '#759-A CONTROL: code-reviewer is an INSTALLED role, so the gate refusal is not an unknown-role artefact');
    // main-session-gate is in BOTH reserved sets; the structural reservation wins (reason unchanged).
    assert(refusalOf(comp([{ name: 'g1', role: 'main-session-gate', mode: 'co_open' }])) === 'expansion_unit_role_reserved',
      '#759-A: main-session-gate keeps its structural reason code (precedence: reserved before gate)');
    assert(refusalOf(comp([{ name: 'u1', role: 'code-explorer', mode: 'parallel' }])) === 'expansion_unit_mode_unsupported',
      '#759-A: mode is a closed vocabulary (serial|co_open)');
    assert(refusalOf(comp([{ name: 'u1', role: 'code-explorer', model: 'haiku', mode: 'co_open' }])) === 'expansion_unit_model_invalid',
      '#759-A: an out-of-vocabulary tier refuses at expansion time (the tier seam has one owner)');
    // SERIAL REQUIRES A NAMED EDGE. The recorded `serializer` line is audit evidence; the edge is the
    // only form the scheduler can enforce, so a serial mode with no edge would be decorative.
    assert(refusalOf(comp([{ name: 'u1', role: 'code-explorer', mode: 'serial' }])) === 'expansion_serial_without_edge',
      '#759-A: mode serial with no depends_on edge refuses');
    assert(refusalOf(comp([
      { name: 'u1', role: 'code-explorer', mode: 'co_open' },
      { name: 'u2', role: 'code-explorer', mode: 'serial', depends_on: ['ghost'] },
    ])) === 'expansion_unit_edge_unresolved', '#759-A: an edge naming a non-unit refuses');
    assert(refusalOf(comp([{ name: 'u1', role: 'code-explorer', mode: 'serial', depends_on: ['u1'] }])) === 'expansion_unit_edge_self',
      '#759-A: a self-edge refuses');
    assert(refusalOf(comp([
      { name: 'u1', role: 'code-explorer', mode: 'serial', depends_on: ['u2'] },
      { name: 'u2', role: 'code-explorer', mode: 'serial', depends_on: ['u1'] },
    ])) === 'expansion_unit_edge_cycle', '#759-A: a cyclic frontier refuses (it would stall forever, silently)');
    assert(refusalOf(comp([{ name: 'u1', role: 'code-explorer', mode: 'co_open', depends_on: [] },
      { name: 'u2', role: 'code-explorer', mode: 'co_open', write_set: 'a|b' }])) === 'expansion_unit_field_illegal',
      '#759-A: a "|" inside a record cell refuses (it would forge a unit column)');
    const wide = [];
    for (let i = 0; i < 13; i++) wide.push({ name: 'u' + i, role: 'code-explorer', mode: 'co_open' });
    assert(refusalOf(comp(wide)) === 'expansion_units_over_cap', '#759-A: an over-cap composition refuses');
  }

  // --- (B) appendLedgerRows: append at tail, never a rewrite. -----------------------------------
  {
    const plan = ['# Plan', '', '## Node Ledger', '', '| id | status |', '|---|---|', '| a | complete |', '| b | pending |', '',
      '## Other', '', 'tail', ''].join('\n');
    const r = appendLedgerRows(plan, ['x', 'y']);
    assert(r.ok && r.appended.length === 2, '#759-B: two new rows must append, got ' + JSON.stringify(r));
    assert(r.content.indexOf('| a | complete |') >= 0 && r.content.indexOf('| b | pending |') >= 0,
      '#759-B: existing rows must survive byte-identical');
    assert(/\| b \| pending \|\n\| x \| pending \|\n\| y \| pending \|/.test(r.content),
      '#759-B: new rows must land AFTER the last existing row, got:\n' + r.content);
    assert(r.content.indexOf('## Other') >= 0 && r.content.indexOf('tail') >= 0,
      '#759-B: the following section must be untouched');
    // Idempotent: an id that already has a row is not duplicated.
    const again = appendLedgerRows(r.content, ['x', 'y', 'z']);
    assert(again.ok && JSON.stringify(again.appended) === JSON.stringify(['z']),
      '#759-B: re-appending an existing id must be a no-op (roll-forward idempotence), got ' + JSON.stringify(again.appended));
    // A wider ledger keeps its column count so the table stays parseable.
    const wide = ['# Plan', '', '## Node Ledger', '', '| id | status | note |', '|---|---|---|', '| a | complete | x |', ''].join('\n');
    const wr = appendLedgerRows(wide, ['q']);
    assert(/\| q \| pending \| — \|/.test(wr.content), '#759-B: a wider ledger keeps its width, got:\n' + wr.content);
    // No ledger section at all is a typed failure, never a silent success.
    assert(appendLedgerRows('# Plan\n\n## Nodes\n\n| id |\n|---|\n', ['x']).ok === false,
      '#759-B: a plan with no ## Node Ledger must fail, not silently drop the rows');
  }

  // --- (C) appendExpansionBlock: creates the section, then appends strictly at the tail. --------
  {
    const base = '# Plan\n\n## Meta\n\nlabels: x\n\n## Node Ledger\n\n| id | status |\n|---|---|\n| a | pending |\n';
    const one = appendExpansionBlock(base, 'record(m1#1):\n  point: m1\n');
    assert(one.startsWith(base.replace(/\n$/, '')) || one.indexOf(base) === 0,
      '#759-C: the pre-existing plan bytes must be a PREFIX of the result (append-only)');
    assert(/## Expansion Records/.test(one), '#759-C: the section must be created when absent');
    const two = appendExpansionBlock(one, 'open(m1#1):\n  at: T\n');
    assert(two.indexOf(one) === 0, '#759-C: a second append must keep the first result as a byte prefix');
    assert(two.indexOf('record(m1#1)') < two.indexOf('open(m1#1)'),
      '#759-C: blocks must land in append order');
    // With a following section present the block still lands INSIDE Expansion Records, at its tail.
    const withTail = one + '\n## Later\n\ntail\n';
    const three = appendExpansionBlock(withTail, 'open(m1#1):\n  at: T\n');
    assert(three.indexOf('open(m1#1)') < three.indexOf('## Later'),
      '#759-C: the block must land at the tail of the section, not after the whole file');
    // APPEND AT **TAIL**, not at head — pinned on the `next >= 0` arm specifically. The two assertions
    // above are both satisfied by an implementation that splices the new block in right after the
    // heading (it is still inside the section and still before `## Later`), so neither of them can see
    // a head-insert. These two can: the pre-existing bytes must remain a byte PREFIX, and the earlier
    // block must still come first. Order in this channel is the durability story — a reader that
    // replays blocks in file order would replay an `open()` before the `record()` it proves.
    assert(three.indexOf(one.replace(/\s+$/, '')) === 0,
      '#759-C: with a following section present, the pre-existing bytes must STILL be a byte prefix '
      + '(the block appends at the section TAIL, never at its head), got:\n' + three);
    assert(three.indexOf('record(m1#1)') < three.indexOf('open(m1#1)'),
      '#759-C: append order must survive the `next >= 0` arm — record() before its own open(), got:\n' + three);
  }

  // --- (C2) parseExpansionRecords REPORTS a malformed block, never silently drops it. ------------
  // The parser's contract is explicit that a malformed block is REPORTED rather than dropped, because
  // a dropped record makes its already-opened units invisible to the ready-set derivation. The
  // no-unit-lines case is the one that reads as "harmless" and is not: without the report the record
  // parses CLEAN, and every consumer that branches on `malformed.length` (expand-open's
  // `expansion_records_malformed` gate and the reconcile roll-forward's refusal arm) waves it through.
  {
    const noUnits = ['## Expansion Records', '',
      'record(m1#1):', '  point: m1',
      '  grain: g', '  path: p', '  join: j', '  probe: pr', '  serializer: none', ''].join('\n');
    const p = validator759.parseExpansionRecords(noUnits);
    assert(p.records.length === 1, '#759-C2: the block must still be RETURNED, got ' + JSON.stringify(p.records));
    assert(p.records[0].malformed.some(m => /declares no unit lines/.test(m)),
      '#759-C2: a record with a header but NO unit lines must be reported malformed, got '
      + JSON.stringify(p.records[0].malformed));
    // CONTROL: the same block WITH a unit line parses clean, so the pin discriminates.
    const withUnit = noUnits.replace('  serializer: none\n', '  serializer: none\n  unit: a | code-explorer | — | — | co_open | —\n');
    const p2 = validator759.parseExpansionRecords(withUnit);
    assert(p2.records[0].malformed.length === 0,
      '#759-C2 CONTROL: a record WITH unit lines must parse clean, got ' + JSON.stringify(p2.records[0].malformed));
  }

  // --- (D) writer/parser round trip: exactly one writer, exactly one reader. --------------------
  {
    const units = [
      { name: 'u1', role: 'code-explorer', model: 'standard', write_set: '', mode: 'co_open', depends_on: [] },
      { name: 'u2', role: 'tdd-guide', model: '', write_set: 'scripts/a.js', mode: 'serial', depends_on: ['u1'] },
    ];
    const text = '## Expansion Records\n\n' + renderExpansionRecord('m1#1', 'm1', 'a'.repeat(64), DERIVATION, units);
    const parsed = validator759.parseExpansionRecords(text);
    assert(parsed.records.length === 1 && parsed.records[0].malformed.length === 0,
      '#759-D: the writer output must parse clean, got ' + JSON.stringify(parsed.records[0]));
    const rec = parsed.records[0];
    assert(rec.id === 'm1#1' && rec.point === 'm1' && rec.ordinal === 1, '#759-D: identity round-trips');
    assert(rec.plan_hash === 'a'.repeat(64), '#759-D: the spine hash round-trips (the review-journal binding component)');
    assert(rec.units.length === 2 && rec.units[0].id === 'm1-r1-u1' && rec.units[1].id === 'm1-r1-u2',
      '#759-D: unit ids are derived, not authored, got ' + JSON.stringify(rec.units.map(u => u.id)));
    assert(rec.units[1].mode === 'serial' && JSON.stringify(rec.units[1].dependsOnNames) === JSON.stringify(['u1']),
      '#759-D: the serializer edge round-trips');
    assert(rec.units[0].model === 'standard' && rec.units[1].model === '',
      '#759-D: an omitted tier round-trips as empty (it falls through to the role default seam)');
    for (const k of ['grain', 'path', 'join', 'probe', 'serializer']) {
      assert(rec.derivation[k] === DERIVATION[k], '#759-D: the "' + k + '" derivation line round-trips');
    }
  }

  // --- (E) expand-open gates, through injected seams (zero mutation on every refusal). ----------
  {
    const SPINE759 = (ledgerRows, tail) => ['# Plan', '',
      '## Meta', '', 'plan_form: spine', '',
      'expansion(m1):', '  milestone_goal: g', '  expected_surfaces: scripts/',
      '  join_constraints: none', '  review_class: code-reviewer', '',
      '## Nodes', '',
      '| id | role | depends_on | declared_write_set | cardinality | shape |',
      '|---|---|---|---|---|---|',
      '| probe | code-explorer | — | — | 1 | sequence |',
      '| m1 | expansion-point | probe | — | 1 | sequence |',
      '| m1-r1-u1 | code-explorer | probe | — | 1 | sequence |',
      '| done | finalize | m1, m1-r1-u1 | — | 1 | sequence |', '',
      '## Node Ledger', '', '| id | status |', '|---|---|', ...ledgerRows, '',
      ...(tail || [])].join('\n');
    const READY = ['| probe | complete |', '| m1 | pending |', '| m1-r1-u1 | pending |', '| done | pending |'];
    const NOT_READY = ['| probe | pending |', '| m1 | pending |', '| m1-r1-u1 | pending |', '| done | pending |'];

    let written = null;
    const mkOpts = (content, nodeId, composition) => ({
      planPath: '/tmp/i759/kaola-workflow/issue-759/workflow-plan.md',
      project: 'issue-759', nodeId, composition,
      shell: () => ({ exitCode: 0, ok: true, result: 'ok' }),
      readFile: () => content,
      writeFile: (_p, c) => { written = c; },
      cacheExists: () => false,
      now: () => 'T',
    });
    const expectRefuse = (content, nodeId, composition, reason, label) => {
      written = null;
      const r = runExpandOpen(mkOpts(content, nodeId, composition));
      assert(r.result === 'refuse' && r.reason === reason,
        '#759-E ' + label + ': expected refuse/' + reason + ', got ' + JSON.stringify({ result: r.result, reason: r.reason }));
      assert(written === null, '#759-E ' + label + ': a refusal must mutate NOTHING');
    };
    const GOOD = comp([{ name: 'u1', role: 'code-explorer', model: 'standard', write_set: '', mode: 'co_open' }]);

    // ADR 0013 R3 — a plan that omits `plan_form` used to be a `dag` and was refused here forever
    // (`not_a_spine_plan`) even though `spine` was the only authorable shape. `parsePlanForm` — the
    // single reader every consumer shares — now normalizes that one retired token, so the omission
    // expands exactly like the declared form. This is the R2 GREEN ARC for the retired
    // `plan_form_dag_retired`, taken at the seam that would otherwise have become its wedge: the
    // freeze wall accepts the plan, so this verb must too, or the conversion just moved the stuck
    // state downstream.
    {
      written = null;
      const undeclared = runExpandOpen(mkOpts(SPINE759(READY).replace('plan_form: spine\n', ''), 'm1', GOOD));
      const declared = runExpandOpen(mkOpts(SPINE759(READY), 'm1', GOOD));
      assert(undeclared.result === declared.result && undeclared.reason === declared.reason,
        '#759-E/ADR-0013: an undeclared plan_form must expand identically to a declared spine, got '
        + JSON.stringify({ undeclared: { result: undeclared.result, reason: undeclared.reason },
          declared: { result: declared.result, reason: declared.reason } }));
      assert(undeclared.reason !== 'not_a_spine_plan',
        '#759-E/ADR-0013: the retired form must never wedge expand-open');
    }
    expectRefuse(SPINE759(READY), null, GOOD, 'node_id_required', 'no --node-id');
    expectRefuse(SPINE759(READY), 'ghost', GOOD, 'node_not_found', 'unknown node');
    expectRefuse(SPINE759(READY), 'probe', GOOD, 'node_not_expansion_point', 'concrete node');
    expectRefuse(SPINE759(NOT_READY), 'm1', GOOD, 'expansion_point_not_ready', 'frozen deps not terminal');
    expectRefuse(SPINE759(['| probe | complete |', '| m1 | complete |', '| m1-r1-u1 | pending |', '| done | pending |']), 'm1', GOOD,
      'expansion_point_discharged', 'already discharged');
    expectRefuse(SPINE759(READY), 'm1', comp([{ name: 'u1', role: 'code-explorer', mode: 'serial' }]),
      'expansion_serial_without_edge', 'composition refusal propagates');

    // GATE DIRECTION 1 — a prior record with no open() proof routes to reconcile, never to a second
    // co-opened frontier. The record deliberately omits every optional field.
    const UNPROVEN = ['## Expansion Records', '', 'record(m1#1):', '  point: m1',
      '  grain: g', '  path: p', '  join: j', '  probe: pr', '  serializer: none',
      '  unit: a | code-explorer | — | — | co_open | —', ''];
    expectRefuse(SPINE759(READY.concat(['| m1-r1-a | complete |']), UNPROVEN), 'm1', GOOD,
      'expansion_open_incomplete', 'prior record not proven opened');

    // GATE DIRECTION 2 — a prior record whose units are not POSITIVELY terminal blocks. A unit with NO
    // ledger row at all is the load-bearing case: absence of evidence must not read as completion.
    const PROVEN = UNPROVEN.concat(['open(m1#1):', '  at: T', '']);
    expectRefuse(SPINE759(READY, PROVEN), 'm1', GOOD, 'expansion_not_settled', 'prior unit has NO ledger row');
    // A prior unit that has a row but is NOT terminal also blocks. `pending` (not `in_progress`) is
    // used deliberately: an in_progress row would trip the OUTER guard layer (serial_node_live) first,
    // which is pinned separately below — this pin is about the expansion gate itself.
    expectRefuse(SPINE759(READY.concat(['| m1-r1-a | pending |']), PROVEN), 'm1', GOOD,
      'expansion_not_settled', 'prior unit non-terminal');
    // ...and the LAYERED GUARD PROLOGUE still fences expansion like every other mutating subcommand:
    // a live serial node refuses before the transaction body is even reached.
    expectRefuse(SPINE759(READY.concat(['| m1-r1-a | in_progress |']), PROVEN), 'm1', GOOD,
      'serial_node_live', 'guard prologue layer 3 fences expansion');

    // A derived unit id that would collide with a spine node id is refused before anything is written.
    // (The fixture carries a spine node literally named `m1-r1-u1` for exactly this pin — a real
    // collision would silently share the `.cache/barrier-base-<sanitized>` key with that node.)
    expectRefuse(SPINE759(READY), 'm1', comp([{ name: 'u1', role: 'code-explorer', mode: 'co_open' }]),
      'expansion_unit_id_collision', 'id collision');

    // --- expand-close: the same fail-closed settled gate, plus the never-composed case. ---
    // #763: readFile/writeFile are now PATH-AWARE (not just content-blind) — expand-close also
    // reads/writes the point's OWN evidence file (.cache/m1.md, the efficiency-line target), a
    // SECOND file distinct from the plan. `written` stays scoped to the plan-path write ONLY, so
    // every existing assertion below (which examines the PLAN mutation) is unaffected by that
    // second write; `files` additionally captures the evidence-file write for the new #763 pin.
    const evidencePath759 = '/tmp/i759/kaola-workflow/issue-759/.cache/m1.md';
    const mkCloseOpts = (content) => {
      const planPath = '/tmp/i759/kaola-workflow/issue-759/workflow-plan.md';
      const files = {};
      return {
        planPath, project: 'issue-759', nodeId: 'm1',
        shell: () => ({ exitCode: 0, ok: true, result: 'ok' }),
        readFile: (p) => {
          if (p === planPath) return content;
          if (Object.prototype.hasOwnProperty.call(files, p)) return files[p];
          throw new Error('ENOENT: ' + p);
        },
        writeFile: (p, c) => { files[p] = c; if (p === planPath) written = c; },
        cacheExists: () => false, now: () => 'T',
        files,
      };
    };
    written = null;
    let rc = runExpandClose(mkCloseOpts(SPINE759(READY)));
    assert(rc.result === 'refuse' && rc.reason === 'expansion_never_composed' && written === null,
      '#759-E expand-close over a never-composed point must refuse with zero mutation, got ' + JSON.stringify(rc));
    written = null;
    rc = runExpandClose(mkCloseOpts(SPINE759(READY, PROVEN)));
    assert(rc.result === 'refuse' && rc.reason === 'expansion_not_settled' && written === null,
      '#759-E expand-close over a unit with no ledger row must BLOCK, got ' + JSON.stringify(rc));
    written = null;
    rc = runExpandClose(mkCloseOpts(SPINE759(READY, UNPROVEN)));
    assert(rc.result === 'refuse' && rc.reason === 'expansion_open_incomplete' && written === null,
      '#759-E expand-close over an unproven open must route to reconcile, got ' + JSON.stringify(rc));
    written = null;
    const closeOpts759 = mkCloseOpts(SPINE759(READY.concat(['| m1-r1-a | complete |']), PROVEN));
    rc = runExpandClose(closeOpts759);
    assert(rc.result === 'ok' && written !== null && /discharge\(m1\)/.test(written),
      '#759-E a fully-settled point discharges and appends a discharge block, got ' + JSON.stringify(rc));
    assert(/\| m1 \| complete \|/.test(written), '#759-E the milestone row must flip to complete');
    // #763: the efficiency evidence line lands in the point's OWN evidence file (a DIFFERENT file
    // from the plan `written` above) — one record (m1#1), one co_open unit, no re-expansion.
    assert(/expansion m1: width=1 mode=co_open serializer=none rework=0/.test(closeOpts759.files[evidencePath759] || ''),
      '#763: expand-close must append the efficiency evidence line to .cache/m1.md, got ' + JSON.stringify(closeOpts759.files[evidencePath759]));

    // --- (E2) THE FULL LAYERED GUARD PROLOGUE, pinned LAYER BY LAYER on BOTH subcommands. ---------
    //
    // Both `expand-open` and `expand-close` mutate the plan (ledger rows + the append-only channel) and
    // the running set, so both run the same layered prologue every other mutating subcommand runs:
    //   Layer 1 INTEGRITY   — a tampered/structurally-invalid frozen plan must not be partially executed.
    //   Layer 2 HALT FENCE  — a durable consent_halt exists precisely to STOP work; it is the human
    //                         escalation valve, and a subcommand that opens a whole frontier (or
    //                         discharges a milestone) must not sail through it.
    //   Layer 3 EXCLUSION   — the per-command mutual-exclusion set.
    // Only Layer 3 was pinned before (and only for expand-open), which left the tamper gate and the
    // consent valve free to be deleted from either subcommand with every suite still green. Each pin
    // below also asserts ZERO MUTATION, which is the actual guarantee a prologue makes.
    //
    // EXCLUSION SETS ARE DIFFERENT ON PURPOSE and are pinned in both directions:
    //   expand-open  excl {serial}            — like open-ready, it OWNS the running-set open.
    //   expand-close excl {serial, scheduler} — it discharges a milestone and must not race a live set.
    {
      const CACHE_DIR = '/tmp/i759/kaola-workflow/issue-759/.cache/';
      const RS_PATH = CACHE_DIR + RUNNING_SET_NAME;
      // Every write of the transaction, in order. The `written` single-slot seam above only keeps the
      // LAST write, and these seams are non-persistent (readFile always replays the ORIGINAL bytes), so
      // phase 3's proof-block write lands on the pre-phase-1 content and would hide phase 1's record.
      let writes = [];
      const LIVE_SET = JSON.stringify({ state: 'open', nodes: [{ id: 'probe', role: 'code-explorer', kind: 'read' }] });
      // A path-aware seam pair so the running-set surface can be made live independently of the plan.
      // #763: readFile/writeFile distinguish planPath from EVERY other path (including the point's own
      // evidence file, .cache/m1.md, which expand-close now also reads/writes) — `written`/`writes`
      // stay scoped to the plan mutation the assertions below actually examine; an unmodeled path
      // (the evidence file, absent here) reads as ENOENT, matching a fresh evidence file in production.
      const seams = (content, opts) => {
        const o = opts || {};
        const planPath = '/tmp/i759/kaola-workflow/issue-759/workflow-plan.md';
        return {
          planPath, project: 'issue-759',
          shell: () => (o.integrityFails ? { exitCode: 1, ok: false, reason: 'plan_hash_mismatch' } : { exitCode: 0, ok: true, result: 'ok' }),
          readFile: (fp) => {
            if (fp === RS_PATH) return (o.runningSet || '');
            if (fp === planPath) return content;
            throw new Error('ENOENT: ' + fp);
          },
          writeFile: (p, c) => { if (p === planPath) { written = c; writes.push(c); } },
          cacheExists: (fp) => (fp === RS_PATH ? !!o.runningSet : false),
          now: () => 'T',
        };
      };
      const guardCase = (label, run, expected) => {
        written = null; writes = [];
        const r = run();
        assert(r.result === 'refuse' && r.reason === expected,
          '#759-E2 ' + label + ': expected refuse/' + expected + ', got ' + JSON.stringify({ result: r.result, reason: r.reason }));
        assert(written === null, '#759-E2 ' + label + ': a guard refusal must mutate NOTHING');
      };
      const GOOD_OPEN = comp([{ name: 'z1', role: 'code-explorer', model: 'standard', write_set: '', mode: 'co_open' }]);
      // A ready, fully-settled point so NOTHING in either transaction body can be the reason a refusal
      // appears — every refusal below is attributable to the prologue alone.
      const SETTLED = SPINE759(READY.concat(['| m1-r1-a | complete |']), PROVEN);
      const HALTED = SPINE759(READY.concat(['| m1-r1-a | complete |', 'consent_halt: pending']), PROVEN);

      // Layer 1 — INTEGRITY. --resume-check non-ok ⇒ plan_integrity_failed, zero mutation, both commands.
      guardCase('expand-open integrity',
        () => runExpandOpen({ ...seams(SETTLED, { integrityFails: true }), nodeId: 'm1', composition: GOOD_OPEN }),
        'plan_integrity_failed');
      guardCase('expand-close integrity',
        () => runExpandClose({ ...seams(SETTLED, { integrityFails: true }), nodeId: 'm1' }),
        'plan_integrity_failed');

      // Layer 2 — CONSENT-HALT FENCE. A durable `consent_halt: pending` in the ledger stops both.
      guardCase('expand-open halt fence',
        () => runExpandOpen({ ...seams(HALTED), nodeId: 'm1', composition: GOOD_OPEN }), 'halt_pending');
      guardCase('expand-close halt fence',
        () => runExpandClose({ ...seams(HALTED), nodeId: 'm1' }), 'halt_pending');
      // CONTROL: with the marker removed the very same call reaches its body and succeeds — so the two
      // pins above discriminate the FENCE, not some unrelated property of the fixture.
      written = null;
      const unhalted = runExpandClose({ ...seams(SETTLED), nodeId: 'm1' });
      assert(unhalted.result === 'ok' && written !== null && /discharge\(m1\)/.test(written),
        '#759-E2 CONTROL: without the halt marker the identical expand-close must discharge, got ' + JSON.stringify(unhalted));

      // Layer 3 — EXCLUSION, pinned in BOTH directions on the running-set surface.
      guardCase('expand-close scheduler exclusion',
        () => runExpandClose({ ...seams(SETTLED, { runningSet: LIVE_SET }), nodeId: 'm1' }), 'scheduler_active');
      // ...and the DIRECTION that proves the sets differ: expand-open OWNS the running-set open, so the
      // same live set must NOT stop it. (It proceeds into the body and appends a record.)
      written = null; writes = [];
      const opened = runExpandOpen({ ...seams(SETTLED, { runningSet: LIVE_SET }), nodeId: 'm1', composition: GOOD_OPEN });
      assert(opened.result !== 'refuse' || opened.reason !== 'scheduler_active',
        '#759-E2: expand-open must NOT be excluded by a live running set — it owns the open, got '
        + JSON.stringify({ result: opened.result, reason: opened.reason }));
      assert(writes.some(c => /record\(m1#2\)/.test(c) && /\| m1-r2-z1 \| pending \|/.test(c)),
        '#759-E2: expand-open past the prologue must append its record AND the unit ledger row, got '
        + JSON.stringify(writes.map(c => c.slice(-200))));
    }
  }

  // --- (F) rollForwardExpansions is inert on a plan that has no spine form / no records. --------
  {
    const dag = ['## Meta', '', 'labels: x', '', '## Nodes', '',
      '| id | role | depends_on | declared_write_set | cardinality | shape |', '|---|---|---|---|---|---|',
      '| a | code-explorer | — | — | 1 | sequence |', '',
      '## Node Ledger', '', '| id | status |', '|---|---|', '| a | pending |', ''].join('\n');
    let touched = false;
    const out = rollForwardExpansions({
      planPath: '/tmp/i759/p.md', readFile: () => dag, writeFile: () => { touched = true; },
      shell: () => ({ exitCode: 0, ok: true, result: 'ok' }), cacheExists: () => false,
    });
    assert(out.rolledForward.length === 0 && out.refusals.length === 0 && touched === false,
      '#759-F: a dag plan must produce no roll-forward and no write, got ' + JSON.stringify(out));
    const unreadable = rollForwardExpansions({
      planPath: '/tmp/i759/p.md', readFile: () => { throw new Error('gone'); }, writeFile: () => { touched = true; },
    });
    assert(unreadable.rolledForward.length === 0, '#759-F: an unreadable plan must not throw out of reconcile');
  }

  // --- (F2) rollForwardExpansions SKIPS an already-proven record — non-vacuously. ----------------
  //
  // This is the idempotence claim, pinned where it is actually decided: the
  // `expansionRecordOpened(...) -> continue` skip inside the roll-forward loop. It has to be pinned
  // HERE rather than only through reconcile, because at the reconcile level the second run can be
  // satisfied by an unrelated early return long before the loop is reached — which makes the
  // idempotence assertion true for the wrong reason and blind to the skip being deleted.
  //
  // The fixture is a SPINE plan whose one record ALREADY carries its `open()` proof, with the seams
  // wired so the re-open would SUCCEED if it ran. Deleting the skip therefore cannot hide behind a
  // failure: the record would be reported rolledForward on a plan that needs nothing.
  {
    const opened = ['# Plan', '', '## Meta', '', 'plan_form: spine', '',
      'expansion(m1):', '  milestone_goal: g', '  expected_surfaces: scripts/',
      '  join_constraints: none', '  review_class: code-reviewer', '',
      '## Nodes', '',
      '| id | role | depends_on | declared_write_set | cardinality | shape |', '|---|---|---|---|---|---|',
      '| probe | code-explorer | — | — | 1 | sequence |',
      '| m1 | expansion-point | probe | — | 1 | sequence |',
      '| done | finalize | m1 | — | 1 | sequence |', '',
      '## Node Ledger', '', '| id | status |', '|---|---|',
      '| probe | complete |', '| m1 | pending |', '| m1-r1-a | complete |', '| done | pending |', '',
      '## Expansion Records', '',
      'record(m1#1):', '  point: m1',
      '  grain: g', '  path: p', '  join: j', '  probe: pr', '  serializer: none',
      '  unit: a | code-explorer | — | — | co_open | —', '',
      'open(m1#1):', '  at: T', ''].join('\n');
    let wrote = null;
    const out = rollForwardExpansions({
      planPath: '/tmp/i759f2/kaola-workflow/p/workflow-plan.md', project: 'p',
      readFile: () => opened, writeFile: (_p, c) => { wrote = c; },
      shell: (sp) => (path.basename(sp) === 'kaola-workflow-next-action.js'
        ? { exitCode: 0, result: 'ok', allDone: false, readyPending: [] }
        : { exitCode: 0, ok: true, result: 'ok' }),
      cacheExists: () => false, mkdirp: () => {}, now: () => 'T2',
    });
    assert(JSON.stringify(out.rolledForward) === '[]' && JSON.stringify(out.refusals) === '[]',
      '#759-F2: a record that ALREADY carries its open() proof must be SKIPPED, not re-rolled — got '
      + JSON.stringify(out));
    assert(wrote === null,
      '#759-F2: skipping must write nothing at all (no second proof block, no ledger touch), got:\n' + String(wrote));
  }
});


// ===========================================================================
// CLUSTER #761 — LOCAL RE-EXPANSION ROUTING.
//
// The keystone routing decision plus the fail-closed re-review wall. Every predicate is pinned in
// BOTH fail directions, and every optional-field predicate is pinned on an input that OMITS the
// field. The router's default-local / positive-proof-to-escalate behaviour is the exact shape prior
// siblings were rejected for getting backwards.
// ===========================================================================
scenario(() => {
  const {
    surfaceCoversFile, resolveExpansionOwnership, routeFindingReExpansion,
    assertReExpansionReviewed, buildReExpansionComposition, findingFilesFromIndexRow,
    deriveReExpansion, validateComposition,
  } = require('./kaola-workflow-adaptive-node');
  const validator761 = require('./kaola-workflow-plan-validator');
  const schema761 = require('./kaola-workflow-adaptive-schema');
  const roles761 = new Set(validator761.installedRoles(process.cwd()));

  // A spine with THREE expansion points: m1 (walled by `rev` downstream), m2 (declares review_class
  // but NO downstream gate reachable), m3 (declares an EMPTY review_class). This one fixture drives
  // the ownership, router, and re-review-wall pins.
  const SPINE761 = [
    '# Plan', '',
    '## Meta', '', 'plan_form: spine', '',
    'expansion(m1):', '  milestone_goal: g1', '  expected_surfaces: scripts/', '  join_constraints: none', '  review_class: code-reviewer', '',
    'expansion(m2):', '  milestone_goal: g2', '  expected_surfaces: docs/', '  join_constraints: none', '  review_class: code-reviewer', '',
    'expansion(m3):', '  milestone_goal: g3', '  expected_surfaces: lib/', '  join_constraints: none', '  review_class: ', '',
    '## Nodes', '',
    '| id | role | depends_on | declared_write_set | cardinality | shape |',
    '|---|---|---|---|---|---|',
    '| m1 | expansion-point | — | — | 1 | sequence |',
    '| rev | code-reviewer | m1 | — | 1 | sequence |',
    '| m2 | expansion-point | rev | — | 1 | sequence |',
    '| m3 | expansion-point | m2 | — | 1 | sequence |',
    '| done | finalize | m3 | — | 1 | sequence |', '',
    '## Node Ledger', '', '| id | status |', '|---|---|', '| m1 | pending |', '',
  ].join('\n');
  const contracts761 = validator761.parseExpansionContracts(SPINE761);
  const nodes761 = validator761.parseNodes(SPINE761);

  // --- (A) surfaceCoversFile: path-prefix containment, fail-safe to NO match. -------------------
  {
    // QUESTION: is the file inside the surface token? FAIL DIRECTION: only a positive containment matches.
    assert(surfaceCoversFile('scripts/', 'scripts/a.js') === true, '#761-A: a dir token covers a file under it');
    assert(surfaceCoversFile('scripts/a.js', 'scripts/a.js') === true, '#761-A: an exact path covers itself');
    assert(surfaceCoversFile('scripts', 'scripts/a.js') === true, '#761-A: a slash-less token covers as a dir prefix');
    assert(surfaceCoversFile('scripts', 'scripts') === true, '#761-A: a slash-less token covers the exact file too');
    assert(surfaceCoversFile('scripts', 'scriptsfoo/x') === false, '#761-A: a prefix must respect the path boundary (no scripts→scriptsfoo)');
    assert(surfaceCoversFile('scripts/', 'docs/a.js') === false, '#761-A: a non-matching file is NOT covered');
    // The OMITTED / empty inputs — a blank cell may never silently claim ownership.
    assert(surfaceCoversFile('', 'a.js') === false, '#761-A: an EMPTY surface covers nothing');
    assert(surfaceCoversFile('scripts/', '') === false, '#761-A: an EMPTY file is covered by nothing');
    assert(surfaceCoversFile('./scripts/', 'scripts/a.js') === true, '#761-A: a leading ./ is normalized off both sides');
  }

  // --- (B) resolveExpansionOwnership: surface ownership, spanning => multi-owner. ----------------
  {
    // QUESTION: which point(s) own the files? FAIL DIRECTION: an unmatched file lands in uncovered, never attributed.
    const one = resolveExpansionOwnership(['scripts/a.js'], contracts761, {});
    assert(JSON.stringify(one.owners) === '["m1"]' && JSON.stringify(one.uncoveredFiles) === '[]',
      '#761-B: a file under m1 is owned by m1 alone, got ' + JSON.stringify(one));
    const span = resolveExpansionOwnership(['scripts/a.js', 'docs/x.md'], contracts761, {});
    assert(JSON.stringify(span.owners) === '["m1","m2"]',
      '#761-B: a finding SPANNING two surfaces is owned by BOTH, got ' + JSON.stringify(span.owners));
    const none = resolveExpansionOwnership(['README.md'], contracts761, {});
    assert(JSON.stringify(none.owners) === '[]' && JSON.stringify(none.uncoveredFiles) === '["README.md"]',
      '#761-B: a file outside every surface is uncovered, never attributed, got ' + JSON.stringify(none));
    // OMITTED files — an anchorless finding yields empty owners AND empty uncovered (the router decides).
    const empty = resolveExpansionOwnership([], contracts761, {});
    assert(JSON.stringify(empty.owners) === '[]' && JSON.stringify(empty.uncoveredFiles) === '[]',
      '#761-B: no files => empty owners AND empty uncovered, got ' + JSON.stringify(empty));
    // The #762 amended-surface seam: an amendment brings a previously-uncovered file into ownership.
    const amended = resolveExpansionOwnership(['README.md'], contracts761, { m1: ['README.md'] });
    assert(JSON.stringify(amended.owners) === '["m1"]',
      '#761-B: an amended surface (the #762 seam) extends ownership, got ' + JSON.stringify(amended));
  }

  // --- (C) routeFindingReExpansion: DEFAULT LOCAL; escalate ONLY on positive proof. --------------
  {
    // QUESTION: local re-expansion, or spine replan? FAIL DIRECTION: default local; escalate ONLY on
    // positive proof the files lie outside every milestone's scope.
    const local = routeFindingReExpansion({ findingFiles: ['scripts/a.js'], contracts: contracts761 });
    assert(local.decision === 'local' && JSON.stringify(local.owners) === '["m1"]',
      '#761-C: an owned file routes LOCAL to its point, got ' + JSON.stringify(local));
    const span = routeFindingReExpansion({ findingFiles: ['scripts/a.js', 'docs/x.md'], contracts: contracts761 });
    assert(span.decision === 'local' && JSON.stringify(span.owners) === '["m1","m2"]',
      '#761-C: a spanning finding routes LOCAL to BOTH points, got ' + JSON.stringify(span));
    // POSITIVE PROOF => escalate. Files present, none owned, no surfacing point.
    const escalate = routeFindingReExpansion({ findingFiles: ['README.md'], contracts: contracts761 });
    assert(escalate.decision === 'spine_replan' && JSON.stringify(escalate.owners) === '[]',
      '#761-C: a file outside EVERY surface (no context) escalates to spine_replan — the ONLY replan trigger, got ' + JSON.stringify(escalate));
    // OUT-OF-SURFACE but a real surfacing point claims it => LOCAL (the #762 amend case), never replan.
    const oos = routeFindingReExpansion({ findingFiles: ['README.md'], contextPoint: 'm1', contracts: contracts761 });
    assert(oos.decision === 'local' && JSON.stringify(oos.owners) === '["m1"]' && JSON.stringify(oos.out_of_surface) === '["README.md"]',
      '#761-C: an out-of-surface finding at a NAMED point routes LOCAL + flags out_of_surface (never replan), got ' + JSON.stringify(oos));
    // ANCHORLESS + no context => REFUSE, fail-closed, no silent guess in EITHER direction.
    const anchorless = routeFindingReExpansion({ findingFiles: [], contracts: contracts761 });
    assert(anchorless.result === 'refuse' && anchorless.reason === 'reexpansion_owner_unresolved',
      '#761-C: an anchorless finding with NO surfacing point refuses (never a silent local pick, never a silent escalate), got ' + JSON.stringify(anchorless));
    // ANCHORLESS but a real surfacing point => LOCAL to that point (cannot furnish escalation proof).
    const anchoredCtx = routeFindingReExpansion({ findingFiles: [], contextPoint: 'm2', contracts: contracts761 });
    assert(anchoredCtx.decision === 'local' && JSON.stringify(anchoredCtx.owners) === '["m2"]',
      '#761-C: an anchorless finding at a named point routes LOCAL to it (never escalates on absence), got ' + JSON.stringify(anchoredCtx));
    // A contextPoint that is NOT a real expansion point does not rescue an outside-every-surface file.
    const ghostCtx = routeFindingReExpansion({ findingFiles: ['README.md'], contextPoint: 'not-a-point', contracts: contracts761 });
    assert(ghostCtx.decision === 'spine_replan',
      '#761-C: a bogus contextPoint cannot claim an outside file — still escalates, got ' + JSON.stringify(ghostCtx));
    // OMITTED input object entirely — must not throw, must fail-closed.
    const bare = routeFindingReExpansion({});
    assert(bare.result === 'refuse' && bare.reason === 'reexpansion_owner_unresolved',
      '#761-C: an empty input (no files, no context, no contracts) refuses, got ' + JSON.stringify(bare));
  }

  // --- (D) assertReExpansionReviewed: the FAIL-CLOSED re-review wall. -----------------------------
  {
    // QUESTION: may re-expanding this point reach the sink? FAIL DIRECTION: fail CLOSED — a point that
    // is not reviewed-before-sink refuses; never sink unreviewed.
    const ok = assertReExpansionReviewed('m1', contracts761, nodes761);
    assert(ok.result === 'ok' && JSON.stringify(ok.walled_by) === '["rev"]',
      '#761-D: a point walled by a reachable downstream gate is re-expandable, got ' + JSON.stringify(ok));
    const noGate = assertReExpansionReviewed('m2', contracts761, nodes761);
    assert(noGate.result === 'refuse' && noGate.reason === 'reexpansion_review_wall_missing',
      '#761-D: a point with a review_class but NO reachable downstream gate FAILS CLOSED, got ' + JSON.stringify(noGate));
    const emptyClass = assertReExpansionReviewed('m3', contracts761, nodes761);
    assert(emptyClass.result === 'refuse' && emptyClass.reason === 'reexpansion_review_wall_missing',
      '#761-D: a point declaring an EMPTY review_class FAILS CLOSED, got ' + JSON.stringify(emptyClass));
    const ghost = assertReExpansionReviewed('nope', contracts761, nodes761);
    assert(ghost.result === 'refuse' && ghost.reason === 'reexpansion_point_unknown',
      '#761-D: a point with no expansion contract refuses reexpansion_point_unknown, got ' + JSON.stringify(ghost));
    // OMITTED spineNodes — the wall cannot prove a downstream gate, so it FAILS CLOSED (never open).
    const noNodes = assertReExpansionReviewed('m1', contracts761, []);
    assert(noNodes.result === 'refuse' && noNodes.reason === 'reexpansion_review_wall_missing',
      '#761-D: with NO spine nodes the wall cannot see a gate and fails CLOSED, got ' + JSON.stringify(noNodes));
  }

  // --- (E) buildReExpansionComposition: a fixer frontier the SAME expand-open transaction eats. ---
  {
    const comp = buildReExpansionComposition('m1', { writeSet: ['scripts/a.js', 'scripts/b.js'], fixRole: 'implementer', briefDigest: 'deadbeef' });
    const vc = validateComposition(comp, { point: 'm1', installedRoles: roles761 });
    assert(vc.ok === true, '#761-E: the built composition must pass the #759 shape validator, got ' + JSON.stringify(vc.refusal || vc));
    assert(comp.units.length === 1 && comp.units[0].mode === 'co_open' && comp.units[0].write_set === 'scripts/a.js scripts/b.js',
      '#761-E: a single co_open fixer unit carries the owned files as its write_set, got ' + JSON.stringify(comp.units[0]));
    assert(comp.repair_brief_digest === 'deadbeef', '#761-E: the #730 brief digest is carried on the composition');
    // The re-review is NOT a composed gate — the composition must carry NO gate-role unit (respects #759).
    assert(!comp.units.some(u => schema761.REVIEW_GATE_ROLES.includes(u.role)),
      '#761-E: the composition carries NO composed gate unit — the re-review is the spine wall (respects the #759 refusal)');
    // OMITTED writeSet — a fixer with no owned files still composes (empty write_set is legal).
    const bare = buildReExpansionComposition('m1', {});
    assert(validateComposition(bare, { point: 'm1', installedRoles: roles761 }).ok === true,
      '#761-E: a fixer with no writeSet still composes clean, got ' + JSON.stringify(bare));
  }

  // --- (E2) findingFilesFromIndexRow: the #729 finding_index → files extractor. -------------------
  {
    assert(JSON.stringify(findingFilesFromIndexRow({ anchor_paths: ['scripts/a.js', 'scripts/b.js'] })) === '["scripts/a.js","scripts/b.js"]',
      '#761-E2: anchor_paths are preferred verbatim');
    assert(JSON.stringify(findingFilesFromIndexRow({ primary_anchor: { path: 'scripts/a.js' } })) === '["scripts/a.js"]',
      '#761-E2: primary_anchor.path is the fallback');
    assert(JSON.stringify(findingFilesFromIndexRow({ file: 'scripts/a.js' })) === '["scripts/a.js"]',
      '#761-E2: a flat `file` is the last fallback');
    assert(JSON.stringify(findingFilesFromIndexRow({})) === '[]', '#761-E2: an anchorless row yields no files');
    assert(JSON.stringify(findingFilesFromIndexRow(null)) === '[]', '#761-E2: a null row does not throw');
  }

  // --- (F) deriveReExpansion: the read-only DRIVER, end to end over a real spine. -----------------
  {
    // LOCAL: an owned finding on a walled point => one plan whose composition validates.
    const localFinding = { uid: 'F1', anchor_paths: ['scripts/a.js'], fix_role: 'implementer', repair_brief_digest: 'abc' };
    const d = deriveReExpansion(localFinding, SPINE761, {});
    assert(d.result === 'ok' && d.decision === 'local' && d.plans.length === 1 && d.plans[0].point === 'm1',
      '#761-F: an owned finding drives a LOCAL single-owner plan, got ' + JSON.stringify(d));
    assert(validateComposition(d.plans[0].composition, { point: 'm1', installedRoles: roles761 }).ok === true,
      '#761-F: the emitted plan composition validates');
    // WALL FAILS CLOSED through the driver: a finding owned by m2 (walled=false) refuses, no plan emitted.
    const m2Finding = { uid: 'F2', anchor_paths: ['docs/x.md'] };
    const dw = deriveReExpansion(m2Finding, SPINE761, {});
    assert(dw.result === 'refuse' && dw.reason === 'reexpansion_review_wall_missing',
      '#761-F: an owner that is not reviewed-before-sink fails the WHOLE route closed (no partial sink), got ' + JSON.stringify(dw));
    // ESCALATE through the driver.
    const outside = { uid: 'F3', anchor_paths: ['README.md'] };
    const de = deriveReExpansion(outside, SPINE761, {});
    assert(de.result === 'ok' && de.decision === 'spine_replan',
      '#761-F: an outside-every-surface finding escalates to spine_replan through the driver, got ' + JSON.stringify(de));
    // ANCHORLESS + no context refuses through the driver.
    const dr = deriveReExpansion({ uid: 'F4' }, SPINE761, {});
    assert(dr.result === 'refuse' && dr.reason === 'reexpansion_owner_unresolved',
      '#761-F: an anchorless finding with no context refuses through the driver, got ' + JSON.stringify(dr));
  }

  // --- (G) the #759 carry-forward: expansion_id is an OPTIONAL, VALIDATED review-journal field. ---
  {
    // QUESTION: is an attempt's expansion_id acceptable? FAIL DIRECTION: fail CLOSED on a
    // present-but-malformed value; PASS on absence (in-flight tolerance) and on a well-formed id.
    assert(schema761.expansionIdFieldOk({}) === true, '#761-G: an attempt that OMITS expansion_id is valid (in-flight tolerance)');
    assert(schema761.expansionIdFieldOk({ expansion_id: null }) === true, '#761-G: an explicit null (reviewed no re-expansion) is valid');
    assert(schema761.expansionIdFieldOk({ expansion_id: 'm1#2' }) === true, '#761-G: a well-formed <point>#<ordinal> is valid');
    assert(schema761.expansionIdFieldOk({ expansion_id: 'n1-milestone_a#10' }) === true, '#761-G: a point with dashes/underscores + a multi-digit ordinal is valid');
    assert(schema761.expansionIdFieldOk({ expansion_id: 'm1' }) === false, '#761-G: a value with no #ordinal fails CLOSED');
    assert(schema761.expansionIdFieldOk({ expansion_id: 'm1#0' }) === false, '#761-G: a zero ordinal fails CLOSED');
    assert(schema761.expansionIdFieldOk({ expansion_id: 'm|1#2' }) === false, '#761-G: a pipe (record-cell delimiter) fails CLOSED');
    assert(schema761.expansionIdFieldOk({ expansion_id: 'm 1#2' }) === false, '#761-G: whitespace fails CLOSED');
    assert(schema761.expansionIdFieldOk({ expansion_id: 5 }) === false, '#761-G: a non-string fails CLOSED');
    // And through the REAL journal validator: a present-but-malformed expansion_id refuses; absence passes.
    // (Build a minimal V2 journal by cloning a valid attempt shape is heavy; the field predicate above is
    // the unit of truth; its INTEGRATION into validateReviewJournalV2 (the present-malformed FAIL-CLOSED
    // arm the produced journals never reach on their own) is pinned in the walkthrough on a REAL produced
    // schema-2 journal, and verified to go RED under the guard-deletion mutant.)
    assert(typeof schema761.EXPANSION_ID_RE.test === 'function' && schema761.EXPANSION_ID_RE.test('a#1'),
      '#761-G: the exported record-id regex accepts a minimal <point>#<ordinal>');
  }
});


// ===========================================================================
// CLUSTER #761b — THE DISCHARGED-POINT RE-OPEN CASCADE + DERIVED SINK-PROGRESS.
//
// The pure cascade helpers, the three-valued fail-closed sink-progress predicate (pinned in every
// direction, including an input that OMITS the probe seam), and runReExpandOpen's three fail-closed
// gates (which return BEFORE the delegated transaction). The happy-path re-open + AC3 selectivity are
// driven end to end through the production CLI in the walkthrough.
// ===========================================================================
scenario(() => {
  const {
    wallsOfMilestone, downstreamMilestones, reExpansionFixFiles, deriveSinkProgress,
    defaultSinkProgressProbe, runReExpandOpen,
  } = require('./kaola-workflow-adaptive-node');
  const v761b = require('./kaola-workflow-plan-validator');
  // Parallel milestones (m1 scripts/, m2 docs/, m3 scripts/) under one terminal wall + sink. m3 declares
  // an EMPTY review_class (drives the wall-missing gate).
  const SPINE761b = [
    '# Plan', '', '## Meta', '', 'plan_form: spine', '',
    'expansion(m1):', '  milestone_goal: g1', '  expected_surfaces: scripts/', '  join_constraints: none', '  review_class: code-reviewer', '',
    'expansion(m2):', '  milestone_goal: g2', '  expected_surfaces: docs/', '  join_constraints: none', '  review_class: code-reviewer', '',
    'expansion(m3):', '  milestone_goal: g3', '  expected_surfaces: scripts/', '  join_constraints: none', '  review_class: ', '',
    '## Nodes', '',
    '| id | role | depends_on | declared_write_set | cardinality | shape |',
    '|---|---|---|---|---|---|',
    '| m1 | expansion-point | — | — | 1 | sequence |',
    '| m2 | expansion-point | — | — | 1 | sequence |',
    '| m3 | expansion-point | m1 | — | 1 | sequence |',
    '| wall | code-reviewer | m1, m2, m3 | — | 1 | sequence |',
    '| done | finalize | wall | — | 1 | sequence |', '',
    '## Node Ledger', '', '| id | status |', '|---|---|',
    '| m1 | ST_M1 |', '| m2 | complete |', '| m3 | complete |', '| wall | complete |', '| done | pending |', '',
  ].join('\n');
  const contracts761b = v761b.parseExpansionContracts(SPINE761b);
  const nodes761b = v761b.parseNodes(SPINE761b);

  // --- wallsOfMilestone: a milestone's OWN direct review-class dependents; empty on no review_class. ---
  assert(JSON.stringify(wallsOfMilestone('m1', contracts761b, nodes761b)) === '["wall"]',
    '#761b: m1\'s own wall is the review-class node depending directly on it, got ' + JSON.stringify(wallsOfMilestone('m1', contracts761b, nodes761b)));
  assert(JSON.stringify(wallsOfMilestone('m3', contracts761b, nodes761b)) === '[]',
    '#761b: a milestone with an EMPTY review_class has no own wall, got ' + JSON.stringify(wallsOfMilestone('m3', contracts761b, nodes761b)));

  // --- downstreamMilestones: transitive expansion-point dependents (m3 depends on m1). ---
  assert(JSON.stringify(downstreamMilestones('m1', nodes761b, 'expansion-point')) === '["m3"]',
    '#761b: m3 (depends on m1) is downstream of m1; m2 (parallel) is not, got ' + JSON.stringify(downstreamMilestones('m1', nodes761b, 'expansion-point')));
  assert(JSON.stringify(downstreamMilestones('m2', nodes761b, 'expansion-point')) === '[]',
    '#761b: nothing depends on m2, got ' + JSON.stringify(downstreamMilestones('m2', nodes761b, 'expansion-point')));

  // --- reExpansionFixFiles: composition write-set union; fallback to the finding's anchors. ---
  assert(JSON.stringify(reExpansionFixFiles({ units: [{ write_set: 'scripts/b.js scripts/a.js' }] }, null)) === '["scripts/a.js","scripts/b.js"]',
    '#761b: fix files are the union of the composition unit write sets, sorted');
  assert(JSON.stringify(reExpansionFixFiles({ units: [{ write_set: '' }] }, { anchor_paths: ['scripts/x.js'] })) === '["scripts/x.js"]',
    '#761b: with no composition write set, fall back to the finding anchors');
  assert(JSON.stringify(reExpansionFixFiles(null, null)) === '[]', '#761b: no composition + no finding ⇒ no fix files (no throw)');

  // --- deriveSinkProgress: three-valued, fail-closed. QUESTION: has the sink taken an irreversible
  //     step? FAILS to 'unknown' on any doubt; only 'pristine'/'started' are trusted verdicts. ---
  assert(deriveSinkProgress({ sinkProgressProbe: () => ({ state: 'pristine', evidence: 'e' }) }).state === 'pristine',
    '#761b: an injected pristine probe reads pristine');
  assert(deriveSinkProgress({ sinkProgressProbe: () => ({ state: 'started' }) }).state === 'started',
    '#761b: an injected started probe reads started');
  assert(deriveSinkProgress({ sinkProgressProbe: () => ({ state: 'nonsense' }) }).state === 'unknown',
    '#761b: an unclassifiable probe verdict FAILS CLOSED to unknown');
  assert(deriveSinkProgress({ sinkProgressProbe: () => { throw new Error('boom'); } }).state === 'unknown',
    '#761b: a THROWING probe FAILS CLOSED to unknown (never pristine)');
  // OMITTED probe seam + a workflow-state that names NO branch ⇒ the default probe cannot derive ⇒ unknown.
  assert(deriveSinkProgress({ planPath: '/x/workflow-plan.md', readFile: () => 'project: x\n' }).state === 'unknown',
    '#761b: the DEFAULT probe with no branch pointer fails closed to unknown (never a false pristine)');
  assert(defaultSinkProgressProbe({ planPath: '/x/workflow-plan.md', readFile: () => 'branch: wf/none-exists-761b\n', repoRoot: process.cwd() }).state !== undefined,
    '#761b: the default probe returns a classifiable state over a real repo');

  // --- runReExpandOpen GATES (each returns BEFORE the delegated transaction; every mutation seam is a
  //     no-op so a refusal proves zero mutation). ---
  const reOpts = (st, extra) => ({
    planPath: '/x/workflow-plan.md', nodeId: 'm1', composition: { derivation: {}, units: [] },
    readFile: (p) => String(p).endsWith('workflow-state.md') ? 'branch: wf/x\n' : SPINE761b.replace('ST_M1', st),
    writeFile: () => { throw new Error('a refused re-open must not write'); },
    cacheExists: () => false, shell: () => ({ exitCode: 0, ok: true }),
    sinkProgressProbe: () => ({ state: 'pristine' }), ...extra,
  });
  // GATE 1 — a non-discharged (pending) owner refuses reexpansion_point_not_discharged.
  {
    const r = runReExpandOpen(reOpts('pending'));
    assert(r.result === 'refuse' && r.reason === 'reexpansion_point_not_discharged',
      '#761b GATE1: a pending (never-discharged) point refuses reexpansion_point_not_discharged, got ' + JSON.stringify(r));
  }
  // GATE 3 — a discharged owner + a STARTED sink refuses reexpansion_after_sink_started.
  {
    const r = runReExpandOpen(reOpts('complete', { sinkProgressProbe: () => ({ state: 'started', evidence: 'origin/x exists' }) }));
    assert(r.result === 'refuse' && r.reason === 'reexpansion_after_sink_started' && r.sink_progress === 'started',
      '#761b GATE3: a re-expansion after the sink started refuses reexpansion_after_sink_started, got ' + JSON.stringify(r));
  }
  // GATE 3 fail-closed — an UNKNOWN sink (probe throws) also refuses (never admits on doubt).
  {
    const r = runReExpandOpen(reOpts('complete', { sinkProgressProbe: () => { throw new Error('x'); } }));
    assert(r.result === 'refuse' && r.reason === 'reexpansion_after_sink_started' && r.sink_progress === 'unknown',
      '#761b GATE3: an UNKNOWN sink state fails closed (refuse), got ' + JSON.stringify(r));
  }
  // GATE 2 — a discharged owner whose review_class names no reachable downstream gate refuses the wall.
  //          (Target m3: it declares an EMPTY review_class, so the re-review wall is missing.)
  {
    const spineM3 = SPINE761b.replace('| m3 | complete |', '| m3 | ST_M3 |');
    const r = runReExpandOpen({
      planPath: '/x/workflow-plan.md', nodeId: 'm3', composition: { derivation: {}, units: [] },
      readFile: (p) => String(p).endsWith('workflow-state.md') ? 'branch: wf/x\n' : spineM3.replace('ST_M1', 'complete').replace('ST_M3', 'complete'),
      writeFile: () => { throw new Error('a refused re-open must not write'); },
      cacheExists: () => false, shell: () => ({ exitCode: 0, ok: true }),
      sinkProgressProbe: () => ({ state: 'pristine' }),
    });
    assert(r.result === 'refuse' && r.reason === 'reexpansion_review_wall_missing',
      '#761b GATE2: re-opening a point with no reachable review wall fails CLOSED, got ' + JSON.stringify(r));
  }
});


// ===========================================================================
// CLUSTER #761c — RETIRE-AS-PRIMARY: the spine-plan router precheck each legacy escalation site
// consults FIRST. Proves BOTH directions: an interior finding routes LOCAL (a route_local_reexpansion
// directive, NOT dependent_producer_replay_required / would_orphan / would_strand / replan), and a
// genuine spine-shape-change finding (and a legacy DAG plan) returns null so the retained family runs.
// ===========================================================================
scenario(() => {
  const { spineReExpansionFirst, findingFilesFromAttempt } = require('./kaola-workflow-adaptive-node');
  const SPINE761c = [
    '# Plan', '', '## Meta', '', 'plan_form: spine', '',
    'expansion(m1):', '  milestone_goal: g', '  expected_surfaces: scripts/', '  join_constraints: none', '  review_class: code-reviewer', '',
    '## Nodes', '', '| id | role | depends_on | declared_write_set | cardinality | shape |', '|---|---|---|---|---|---|',
    '| m1 | expansion-point | — | — | 1 | sequence |', '| wall | code-reviewer | m1 | — | 1 | sequence |',
    '| done | finalize | wall | — | 1 | sequence |', '',
    '## Node Ledger', '', '| id | status |', '|---|---|', '| m1 | complete |', '| wall | complete |', '| done | pending |', '',
  ].join('\n');
  // A genuine legacy DAG: no expansion contract and no expansion point, which is what "DAG" MEANS
  // structurally. It is deliberately no longer built by flipping the `plan_form` token — ADR 0013 R3
  // normalizes that one retired token in the shared reader, so the discriminator can no longer stand
  // in for the shape. The invariant under test is unchanged and is the one that was always load
  // bearing: a plan with nothing to re-expand is inert, so the legacy escalation families run
  // byte-identically. Keying it on the token instead would have been testing the spelling.
  const DAG761c = SPINE761c
    .replace(/expansion\(m1\):[\s\S]*?review_class: code-reviewer\n\n/, '')
    .replace('| m1 | expansion-point |', '| m1 | implementer |');

  // INTERIOR finding routes LOCAL — the retire-as-primary win.
  const interior = spineReExpansionFirst(SPINE761c, ['scripts/x.js']);
  assert(interior && interior.result === 'route_local_reexpansion' && JSON.stringify(interior.owners) === '["m1"]',
    '#761c: an interior finding on a SPINE plan routes to route_local_reexpansion(m1) — NOT the legacy replay/replan escalation, got ' + JSON.stringify(interior));
  // SPINE-CHANGE finding (outside every milestone surface) returns null ⇒ the retained family escalates.
  assert(spineReExpansionFirst(SPINE761c, ['README.md']) === null,
    '#761c: a finding outside every milestone surface returns null so the SPINE-CHANGE (replan) family still fires');
  // A plan with nothing to re-expand is INERT ⇒ the legacy families are byte-identical.
  assert(spineReExpansionFirst(DAG761c, ['scripts/x.js']) === null,
    '#761c: a plan carrying no expansion contract returns null (inert) — dependent_producer_replay_required / would_orphan / would_strand unchanged');
  // Anchorless finding is not a local route (the router refuses; the precheck passes through).
  assert(spineReExpansionFirst(SPINE761c, []) === null,
    '#761c: an anchorless finding is not a local route (precheck passes through to the existing path)');
  // Malformed content never throws.
  assert(spineReExpansionFirst('not a plan', ['scripts/x.js']) === null, '#761c: unparseable content returns null (never throws)');

  // findingFilesFromAttempt over the REAL route_candidates attempt shape (primary_anchor / file /
  // anchor_paths), resolved rows excluded, unreadable shapes ⇒ [].
  assert(JSON.stringify(findingFilesFromAttempt({ route_candidates: [{ status: 'open', primary_anchor: { path: 'scripts/y.js' } }] })) === '["scripts/y.js"]',
    '#761c: findingFilesFromAttempt reads route_candidates primary_anchor.path');
  assert(JSON.stringify(findingFilesFromAttempt({ route_candidates: [{ status: 'resolved', primary_anchor: { path: 'scripts/skip.js' } }] })) === '[]',
    '#761c: findingFilesFromAttempt excludes RESOLVED rows');
  assert(JSON.stringify(findingFilesFromAttempt(null)) === '[]', '#761c: findingFilesFromAttempt(null) ⇒ [] (no throw)');
  // The wired combination: an attempt whose still-open finding lands in a milestone surface routes local.
  const wiredFiles = findingFilesFromAttempt({ route_candidates: [{ status: 'open', primary_anchor: { path: 'scripts/impl.js' } }] });
  const wired = spineReExpansionFirst(SPINE761c, wiredFiles);
  assert(wired && wired.result === 'route_local_reexpansion',
    '#761c: an attempt finding under a milestone surface routes local through the SAME precheck the escalation sites call, got ' + JSON.stringify(wired));
});

// ===========================================================================
// CLUSTER #805 — A GATE FINDING MUST BE ROUTABLE, AND ITS PATH MUST REACH THE ROUTER.
//
// The dead end: a change-gate finding on a `complete` writer with no reachable in-plan repair. Its
// root cause is the ANCHOR — an `evidence_observation` primary anchor carries NO path, and every
// in-plan repair route resolves its fixer FROM that path, so such a finding could be COMMITTED and
// then placed nowhere. The end-to-end proof runs through the production CLIs in the walkthrough
// (testReviewerContractV2Conformance: the unroutable variant refused before any attempt exists, then
// the same finding re-anchored on a path resolving to its writer and repairing in place with zero
// epochs). These are the unit-level pins on the pieces that proof composes.
//
// (D) additionally pins `findingFilesFromAttempt` as ROW-ONLY: it deliberately does NOT join the
// attempt's canonical findings, because making the schema-2 paths reach the spine router produces a
// `route_local_reexpansion` directive that is not executable while the attempt is unresolved.
// ===========================================================================
scenario(() => {
  const schema805 = require('./kaola-workflow-adaptive-schema');
  const { findingOwnershipSummary, findingFilesFromAttempt } = require('./kaola-workflow-adaptive-node');

  // --- (A) ROUTABLE_FINDING_ANCHOR_KINDS is DERIVED, never a second hand-kept list. ---
  {
    assert(JSON.stringify(schema805.ROUTABLE_FINDING_ANCHOR_KINDS)
      === JSON.stringify(schema805.FINDING_ANCHOR_KINDS.filter(schema805.findingAnchorCarriesPath)),
    '#805-A: the routable set must be DERIVED from the anchor-kind vocabulary through the ONE '
      + 'path-bearing predicate — a second hand-kept list is how the reviewer-facing stub and the '
      + 'enforcing gate drift, got ' + JSON.stringify(schema805.ROUTABLE_FINDING_ANCHOR_KINDS));
    assert(!schema805.ROUTABLE_FINDING_ANCHOR_KINDS.includes('evidence_observation')
      && schema805.ROUTABLE_FINDING_ANCHOR_KINDS.length === schema805.FINDING_ANCHOR_KINDS.length - 1,
    '#805-A: evidence_observation is the one kind that carries no path, got '
      + JSON.stringify(schema805.ROUTABLE_FINDING_ANCHOR_KINDS));
    for (const kind of schema805.FINDING_ANCHOR_KINDS) {
      assert(schema805.findingAnchorCarriesPath(kind) === (kind !== 'evidence_observation'),
        '#805-A: the predicate must agree with the vocabulary for "' + kind + '"');
    }
  }

  // --- (B) the open-time seeded gate stub STATES the routable kinds (the same way the outcome enum
  // is already surfaced), so a reviewer learns the rule before spending the review, not at close. ---
  {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-805-seed-'));
    try {
      fs.mkdirSync(path.join(tmp, '.cache'), { recursive: true });
      const planPath = path.join(tmp, 'workflow-plan.md');
      fs.writeFileSync(planPath, [
        '## Nodes',
        '| id | role | depends_on | declared_write_set | cardinality | shape |',
        '| --- | --- | --- | --- | --- | --- |',
        '| gate | code-reviewer | — | — | 1 | sequence |',
        '## Node Ledger', '| id | status |', '| --- | --- |', '| gate | in_progress |',
      ].join('\n'));
      // The findings token class only exists on a SCHEMA-2 gate open, so the seed is driven by the
      // real `requiredReviewTokens` selector — the same one the close-time validator reads — rather
      // than by the schema-1 role registry (which carries verdict/findings_blocking and no findings
      // JSON at all). Seeding through the selector is what makes this pin about the live gate stub.
      const gateTokens = schema805.requiredReviewTokens(
        { nodes: [{ id: 'gate', role: 'code-reviewer' }] }, { id: 'gate', role: 'code-reviewer' });
      assert(gateTokens.includes('finding_json|findings_none'),
        '#805-B PRECONDITION: a schema-2 change gate carries the findings token class, got ' + JSON.stringify(gateTokens));
      seedEvidenceFile(planPath, 'gate', 'abcdef123456', 'code-reviewer', false,
        { required_tokens: gateTokens });
      const seeded = fs.readFileSync(path.join(tmp, '.cache', 'gate.md'), 'utf8');
      assert(/PATH-BEARING primary_anchor\.kind/.test(seeded),
        '#805-B: the change-gate stub must state the routability rule, got:\n' + seeded);
      for (const kind of schema805.ROUTABLE_FINDING_ANCHOR_KINDS) {
        assert(seeded.includes(kind), '#805-B: the stub must name the routable kind "' + kind + '"');
      }
      assert(!seeded.includes('<!-- a BLOCKING finding') || !/^\s*finding_json:.*PATH-BEARING/m.test(seeded),
        '#805-B: the note must NOT sit on a column-0 token line — the hollow-seed and finding parsers '
        + 'are fence-blind and match at column 0, got:\n' + seeded);
      assert(/^finding_json: $/m.test(seeded),
        '#805-B: the token line itself is still seeded EMPTY (anti-fabrication), got:\n' + seeded);
      // CONTROL — a DIFFERENT alternative token class must NOT attract the note. Without this the
      // assertions above are satisfied by an implementation that decorates every alternative class.
      fs.rmSync(path.join(tmp, '.cache', 'gate.md'));
      seedEvidenceFile(planPath, 'gate', 'abcdef123456', 'implementer', false,
        { required_tokens: ['evidence-binding', 'non_tdd_reason', 'regression-green|build-green|smoke-integration'] });
      const other = fs.readFileSync(path.join(tmp, '.cache', 'gate.md'), 'utf8');
      assert(/<!-- regression-green\|build-green\|smoke-integration -->/.test(other),
        '#805-B CONTROL: the other alternative class still renders its own header, got:\n' + other);
      assert(!/PATH-BEARING/.test(other),
        '#805-B CONTROL: the routability note is scoped to the FINDINGS class, not every alternative '
        + 'token class, got:\n' + other);
    } finally { fs.rmSync(tmp, { recursive: true, force: true }); }
  }

  // --- (C) the ownership summary names WHY ownership is empty, in the finding's own vocabulary. ---
  {
    const anchorless = {
      findings: [{ uid: 'u1', primary_anchor: { kind: 'evidence_observation' } }],
      route_candidates: [{ finding_id: 'u1', id: 'u1', status: 'open', ownership_candidates: [] }],
    };
    const own1 = findingOwnershipSummary(anchorless, 'writer');
    assert(JSON.stringify(own1.unroutableAnchorKinds) === JSON.stringify(['evidence_observation']),
      '#805-C: an unowned finding whose anchor kind carries no path must be reported as such — that is '
      + 'the difference between "fix the anchor" and "spend an epoch", got ' + JSON.stringify(own1.unroutableAnchorKinds));
    const pathed = {
      findings: [{ uid: 'u1', primary_anchor: { kind: 'candidate_range', path: 'scripts/nowhere.js' } }],
      route_candidates: [{ finding_id: 'u1', id: 'u1', status: 'open', ownership_candidates: [] }],
    };
    assert(JSON.stringify(findingOwnershipSummary(pathed, 'writer').unroutableAnchorKinds) === '[]',
      '#805-C: an unowned finding whose anchor DOES name a path is a genuine scope expansion, not an '
      + 'anchor defect — it must NOT be reported as an unroutable kind');
    const owned = {
      findings: [{ uid: 'u1', primary_anchor: { kind: 'evidence_observation' } }],
      route_candidates: [{ finding_id: 'u1', id: 'u1', status: 'open', ownership_candidates: ['writer'] }],
    };
    assert(JSON.stringify(findingOwnershipSummary(owned, 'writer').unroutableAnchorKinds) === '[]',
      '#805-C: an OWNED row is not an ownership failure, whatever its anchor kind');
    assert(JSON.stringify(findingOwnershipSummary(null, 'writer').unroutableAnchorKinds) === '[]',
      '#805-C: a null attempt is total, never a throw');
  }

  // --- (D) findingFilesFromAttempt is ROW-ONLY — a DELIBERATE hold, pinned so it stays deliberate. ---
  {
    // A REAL schema-2 attempt shape: the route row carries ownership + status and NO anchors; the paths
    // live only on the canonical finding record. So this returns [] for a schema-2 attempt, the spine
    // local-re-expansion precheck cannot place the finding, and the request falls through to the replan
    // family. That LOOKS like an obvious one-line fix (join the canonical findings by uid) and must not
    // be taken in isolation: with the paths joined in, `repair-node` returns `route_local_reexpansion`,
    // and the named `reexpand-open` then HALF-COMMITS (it appends its record + unit ledger row) before
    // the review-journal fence refuses `review_attempt_unresolved` — leaving the plan wedged, which is
    // strictly worse than the working-if-expensive replan exit. Settling the attempt from the
    // re-expansion side needs the `repair.selected_writer` / `consumed_by` pair the journal validator
    // requires and an expansion point cannot supply. This pin exists to make that a decision, not an
    // oversight: change it only together with the lane that can settle the attempt.
    const schema2Attempt = {
      findings: [{ uid: 'u1', primary_anchor: { kind: 'candidate_range', path: 'scripts/impl.js' },
        secondary_anchors: [{ kind: 'tree_entry_change', path: 'scripts/other.js' }] }],
      route_candidates: [{ source_node: 'gate', finding_id: 'u1', id: 'u1', status: 'open',
        scope: 'in_scope', action: 'fix', severity: 'high', fix_role: null,
        ownership_candidates: [], owning_node: null, raw: 'uid=u1' }],
    };
    assert(JSON.stringify(findingFilesFromAttempt(schema2Attempt)) === '[]',
      '#805-D: a schema-2 route row carries no anchors, so this stays [] BY DESIGN until the local '
      + 're-expansion route can settle the attempt it repairs, got '
      + JSON.stringify(findingFilesFromAttempt(schema2Attempt)));
    // Schema-1 flat rows (files on the row itself) resolve, and that path is what the spine router
    // actually consumes today — unchanged.
    assert(JSON.stringify(findingFilesFromAttempt({ route_candidates: [{ status: 'open', file: 'scripts/one.js' }] }))
      === JSON.stringify(['scripts/one.js']),
    '#805-D CONTROL: a schema-1 flat row still resolves from the row itself, so the pin above is about '
      + 'the schema-2 projection specifically and not a dead function');
    assert(JSON.stringify(findingFilesFromAttempt({ route_candidates: [{ status: 'resolved', file: 'scripts/one.js' }] })) === '[]',
      '#805-D: only STILL-OPEN rows contribute files');
  }
});

// ===========================================================================
// CLUSTER #807 — EXPANSION RESHAPES THE PRESENTED TASK LIST.
//
// Expansion is the one lifecycle step that changes the run's SHAPE, and two channels used to hide it:
//   D1 expand-open returned transitions ONLY for the units its FIRST frontier happened to open, so a
//      composed-but-downstream unit was announced to nobody — the operator's list kept showing the
//      frozen spine.
//   D2 expand-close MUTATED the ledger (point -> complete) yet returned taskTransitions:[] and never
//      refreshed the durable mirror — the ONE ledger-mutating subcommand that skipped the
//      mutation-time task-mirror contract every other one honors.
//
// Driven through the REAL runExpandOpen / runExpandClose against a real temp tree, with only
// next-action's ready set mocked (that is what decides which composed units the frontier opens).
// ===========================================================================
scenario(() => {
  const { runExpandOpen, runExpandClose } = require('./kaola-workflow-adaptive-node');

  const DERIV807 = { grain: 'g', path: 'p', join: 'j', probe: 'pr', serializer: 'none' };
  const PLAN807 = (rows, tail) => ['# Plan — 807', '',
    '## Meta', '', 'plan_form: spine', '',
    'expansion(m1):', '  milestone_goal: g', '  expected_surfaces: scripts/',
    '  join_constraints: none', '  review_class: code-reviewer', '',
    '## Nodes', '',
    '| id | role | depends_on | declared_write_set | cardinality | shape |',
    '|---|---|---|---|---|---|',
    '| probe | code-explorer | — | — | 1 | sequence |',
    '| m1 | expansion-point | probe | — | 1 | sequence |',
    '| wall | code-reviewer | m1 | — | 1 | sequence |',
    '| done | finalize | wall | — | 1 | sequence |', '',
    '## Node Ledger', '', '| id | status |', '|---|---|', ...rows, '',
    ...(tail || [])].join('\n');
  const READY807 = ['| probe | complete |', '| m1 | pending |', '| wall | pending |', '| done | pending |'];

  // THREE composed units; the frontier opens exactly TWO (u3 is serial behind u1, so next-action does
  // not offer it). This is the shape the defect hid: u3 exists in the ledger and in the durable mirror,
  // and used to be announced through NO transition at all.
  const COMP807 = { derivation: { ...DERIV807 }, units: [
    { name: 'u1', role: 'code-explorer', model: 'standard', write_set: '', mode: 'co_open' },
    { name: 'u2', role: 'code-explorer', model: 'standard', write_set: '', mode: 'co_open' },
    { name: 'u3', role: 'code-explorer', model: 'standard', write_set: '', mode: 'serial', depends_on: ['u1'] },
  ] };
  const OPENED807 = ['m1-r1-u1', 'm1-r1-u2'];
  const COMPOSED807 = ['m1-r1-u1', 'm1-r1-u2', 'm1-r1-u3'];

  const mk807 = (planText, readyIds) => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-807-'));
    const projectDir = path.join(tmp, 'kaola-workflow', 'issue-807');
    fs.mkdirSync(path.join(projectDir, '.cache'), { recursive: true });
    const planPath = path.join(projectDir, 'workflow-plan.md');
    fs.writeFileSync(planPath, planText);
    const mirrorCalls = [];
    return {
      tmp, planPath,
      mirrorCalls,
      opts: {
        planPath, project: 'issue-807',
        shell: (scriptPath, args) => {
          const base = path.basename(String(scriptPath));
          if (base === 'kaola-workflow-next-action.js') {
            return { exitCode: 0, result: 'ok', allDone: false,
              readyPending: (readyIds || []).map(id => ({ id, role: 'code-explorer',
                declared_write_set: '—', model: 'standard', kind: 'read' })) };
          }
          if (base === 'kaola-workflow-task-mirror.js') {
            mirrorCalls.push(args);
            return { exitCode: 0, result: 'ok' };
          }
          return { exitCode: 0, ok: true, result: 'ok', recordBase: { base: 'b'.repeat(40) } };
        },
        readFile: p => fs.readFileSync(p, 'utf8'),
        writeFile: (p, c) => fs.writeFileSync(p, c),
        cacheExists: p => fs.existsSync(p),
        mkdirp: d => { try { fs.mkdirSync(d, { recursive: true }); } catch (_) {} },
        unlink: p => { try { fs.unlinkSync(p); } catch (_) {} },
        now: () => 'T',
      },
      cleanup: () => fs.rmSync(tmp, { recursive: true, force: true }),
    };
  };

  // --- D1: one transition per COMPOSED unit — 2 in_progress (opened) + 1 pending (not yet). ---
  {
    const f = mk807(PLAN807(READY807), OPENED807);
    try {
      const r = runExpandOpen({ ...f.opts, nodeId: 'm1', composition: COMP807 });
      assert(r.result === 'ok', '#807-D1: the 3-unit expansion must commit, got ' + JSON.stringify({ result: r.result, reason: r.reason }));
      assert(JSON.stringify((r.opened || []).map(n => n.id)) === JSON.stringify(OPENED807),
        '#807-D1 PRECONDITION: the frontier must open exactly 2 of the 3 composed units, got '
        + JSON.stringify((r.opened || []).map(n => n.id)));
      const t = r.taskTransitions || [];
      assert(t.length === 3,
        '#807-D1: expand-open must return one transition per COMPOSED unit (3), not only the opened ones — got '
        + t.length + ': ' + JSON.stringify(t));
      assert(JSON.stringify(t.map(x => x.id).slice().sort()) === JSON.stringify(COMPOSED807.slice().sort()),
        '#807-D1: the transition set must name exactly the composed unit ids, got ' + JSON.stringify(t.map(x => x.id)));
      const byId = new Map(t.map(x => [x.id, x]));
      for (const id of OPENED807) {
        assert(byId.get(id) && byId.get(id).ledger_status === 'in_progress' && byId.get(id).status === 'in_progress',
          '#807-D1: an OPENED unit must transition in_progress, got ' + JSON.stringify(byId.get(id)));
      }
      assert(byId.get('m1-r1-u3') && byId.get('m1-r1-u3').ledger_status === 'pending'
        && byId.get('m1-r1-u3').status === 'pending',
      '#807-D1: a COMPOSED-but-unopened unit must transition pending (an id absent from the visible list '
        + 'is thereby an INSERT), got ' + JSON.stringify(byId.get('m1-r1-u3')));
      // The transition channel and the durable ledger must name the SAME unit ids.
      const statuses = readLedgerStatuses(fs.readFileSync(f.planPath, 'utf8'));
      for (const id of COMPOSED807) {
        assert(Object.prototype.hasOwnProperty.call(statuses, id),
          '#807-D1: every announced unit id must exist in the durable ledger, missing ' + id);
      }
    } finally { f.cleanup(); }
  }

  // --- D1b: a WIDER open still emits exactly one transition per unit (no duplicates). ---
  {
    const f = mk807(PLAN807(READY807), COMPOSED807);
    try {
      const r = runExpandOpen({ ...f.opts, nodeId: 'm1',
        composition: { derivation: { ...DERIV807 }, units: COMP807.units.map(u => ({ ...u, mode: 'co_open', depends_on: [] })) } });
      assert(r.result === 'ok', '#807-D1b: the all-open expansion must commit, got ' + JSON.stringify(r.reason));
      const ids = (r.taskTransitions || []).map(x => x.id);
      assert(ids.length === 3 && new Set(ids).size === 3,
        '#807-D1b: a frontier that opens EVERY composed unit must still emit exactly 3 distinct transitions '
        + '(the pending top-up must not duplicate an already-emitted id), got ' + JSON.stringify(ids));
      assert((r.taskTransitions || []).every(x => x.ledger_status === 'in_progress'),
        '#807-D1b: with every unit opened, every transition is in_progress, got ' + JSON.stringify(r.taskTransitions));
    } finally { f.cleanup(); }
  }

  // --- D2: expand-close returns the point's own `complete` transition AND refreshes the mirror. ---
  {
    const UNIT_ROWS = ['| m1-r1-a | complete |'];
    const RECORD = ['## Expansion Records', '', 'record(m1#1):', '  point: m1',
      '  grain: g', '  path: p', '  join: j', '  probe: pr', '  serializer: none',
      '  unit: a | code-explorer | — | — | co_open | —', '', 'open(m1#1):', '  at: T', ''];
    const f = mk807(PLAN807(READY807.concat(UNIT_ROWS), RECORD), []);
    try {
      const r = runExpandClose({ ...f.opts, nodeId: 'm1' });
      assert(r.result === 'ok' && JSON.stringify(r.discharged) === JSON.stringify(['m1#1']),
        '#807-D2: a fully-settled point must discharge, got ' + JSON.stringify({ result: r.result, reason: r.reason }));
      assert(JSON.stringify(r.taskTransitions) === JSON.stringify([
        { id: 'm1', status: 'completed', ledger_status: 'complete', reason: 'expand-close' }]),
      '#807-D2: expand-close MUTATES the ledger, so it must return the point\'s own complete transition '
        + '(the mutation-time mirror contract every other ledger-mutating subcommand honors), got '
        + JSON.stringify(r.taskTransitions));
      assert(r.taskMirror && r.taskMirror.status === 'updated'
        && r.taskMirror.path === 'kaola-workflow/issue-807/workflow-tasks.json',
      '#807-D2: expand-close must refresh the durable task mirror after its plan write, got '
        + JSON.stringify(r.taskMirror));
      assert(f.mirrorCalls.length === 1,
        '#807-D2: exactly ONE mirror refresh per discharge, got ' + f.mirrorCalls.length);
      assert(/\| m1 \| complete \|/.test(fs.readFileSync(f.planPath, 'utf8')),
        '#807-D2 CONTROL: the discharge really did move the ledger row');
    } finally { f.cleanup(); }
  }

  // --- D2b: the alreadyDischarged EARLY RETURN emits NOTHING — no mutation happened. ---
  {
    const DISCHARGED = ['| probe | complete |', '| m1 | complete |', '| wall | pending |', '| done | pending |'];
    const f = mk807(PLAN807(DISCHARGED), []);
    try {
      const before = fs.readFileSync(f.planPath, 'utf8');
      const r = runExpandClose({ ...f.opts, nodeId: 'm1' });
      assert(r.result === 'ok' && r.alreadyDischarged === true,
        '#807-D2b: a point already complete short-circuits, got ' + JSON.stringify(r));
      assert(JSON.stringify(r.taskTransitions) === '[]',
        '#807-D2b: the alreadyDischarged branch mutated NOTHING, so it must emit NO transition, got '
        + JSON.stringify(r.taskTransitions));
      assert(!Object.prototype.hasOwnProperty.call(r, 'taskMirror') && f.mirrorCalls.length === 0,
        '#807-D2b: no mutation ⇒ no mirror refresh (the contract is mutation-TIME sync, not call-time), got '
        + JSON.stringify({ mirror: r.taskMirror, calls: f.mirrorCalls.length }));
      assert(fs.readFileSync(f.planPath, 'utf8') === before,
        '#807-D2b: the early return is byte-zero-mutation on the plan');
    } finally { f.cleanup(); }
  }

  // --- D2c (#759-gap, SUBTRACTED by #833): a pre-fix discharge left the milestone's pre-seeded
  //     compliance row `pending` forever, and the archive authority refused
  //     `state_compliance_progress_invalid` over it — so expand-close carried a REPAIR VERB whose
  //     only job was to flip that one cell. Both the refusal and the repair are gone: the derived
  //     table reads the milestone's LEDGER row, which already says `complete`. The pin inverts to
  //     the stronger property — the alreadyDischarged re-entry is byte-zero-mutation even with a
  //     stale stored row present, and the derivation reports the milestone discharged anyway. ---
  {
    const DISCHARGED = ['| probe | complete |', '| m1 | complete |', '| wall | pending |', '| done | pending |'];
    const COMPLIANCE = ['## Required Agent Compliance', '',
      '| Requirement | Status | Evidence | Skip Reason |',
      '| --- | --- | --- | --- |',
      '| expansion-point (m1) | pending | | |', ''];
    const f = mk807(PLAN807(DISCHARGED, COMPLIANCE), []);
    try {
      const before = fs.readFileSync(f.planPath, 'utf8');
      const r = runExpandClose({ ...f.opts, nodeId: 'm1' });
      assert(r.result === 'ok' && r.alreadyDischarged === true,
        '#759-gap-D2c: the re-entry still short-circuits ok, got ' + JSON.stringify(r));
      assert(JSON.stringify(r.taskTransitions) === '[]'
        && !Object.prototype.hasOwnProperty.call(r, 'taskMirror') && f.mirrorCalls.length === 0,
      '#759-gap-D2c: no ledger row moved — no transition, no mirror refresh, got '
        + JSON.stringify({ transitions: r.taskTransitions, mirror: r.taskMirror, calls: f.mirrorCalls.length }));
      const after = fs.readFileSync(f.planPath, 'utf8');
      assert(after === before,
        '#759-gap-D2c/#833: the re-entry is byte-zero-mutation even with a STALE pending compliance '
        + 'row present — the repair verb is gone, got:\n'
        + (after.split('\n').filter(l => l.includes('expansion-point (m1)')).join('\n') || '<row missing>'));
      assert(/\| expansion-point \(m1\) \| pending \|/.test(after),
        '#759-gap-D2c/#833 (non-vacuity): the stale stored row is still `pending`, so the assertion '
        + 'above is about tolerance and not about a row someone flipped');
      const derivedM1 = planValidator.deriveAgentCompliance(after).rows.find(row => row.node_id === 'm1');
      assert(derivedM1 && derivedM1.status === 'main-session-direct',
        '#759-gap-D2c/#833: the discharged milestone DERIVES main-session-direct from its complete '
        + 'ledger row regardless of the stale stored cell, got ' + JSON.stringify(derivedM1));
      const r2 = runExpandClose({ ...f.opts, nodeId: 'm1' });
      assert(r2.result === 'ok' && r2.alreadyDischarged === true
        && fs.readFileSync(f.planPath, 'utf8') === before,
      '#759-gap-D2c: a second re-entry is byte-zero-mutation too');
    } finally { f.cleanup(); }
  }
});

// ===========================================================================
// CLUSTER #807-F — NO LEDGER ROW MOVES UNANNOUNCED.
//
// The #807 shape channel fixed expand-open/expand-close, but three sibling paths still moved rows the
// presented task list never heard about — and the FIRST of them is a defect the #807 fix itself created:
//
//   F1 reexpand-open's `_reactivate` cascade flips the OWNER milestone, its post-dominating review
//      wall, any re-verified downstream milestone, and the sink from `complete` -> `pending`, and built
//      a transition for NONE of them. Pre-#807 the milestone was never marked completed in the first
//      place, so the cascade could not contradict the list; post-#807 the operator marks it completed at
//      discharge and the re-open silently un-completes it in the LEDGER ONLY. A list reading
//      "milestone done, review passed" over a run that has re-opened both is worse than a stale list.
//   F2 the DOCUMENTED crash recovery (reconcile-running-set -> re-orient) announced nothing:
//      rollForwardExpansions re-opened the frontier through runOpenReady — which builds real
//      `in_progress` transitions — and every reconcile arm then threw them away with taskTransitions: [].
//   F4 every plan-run surface says to insert a newly-announced unit "in record order", which no runtime
//      could follow from a frontier-order-first array.
//
// The F1/F2 assertions are written as a LEDGER DIFF, not a hand-listed expectation: read the ledger
// before and after, and require that every row that MOVED is named in taskTransitions. That is the
// property, and it cannot rot as the cascade grows new arms.
// ===========================================================================
scenario(() => {
  const { runReExpandOpen, runExpandOpen, runReconcileRunningSet } = require('./kaola-workflow-adaptive-node');

  const DERIV = { grain: 'g', path: 'p', join: 'j', probe: 'pr', serializer: 'none' };
  // m1 (owner, discharged) -> m2 (downstream milestone, discharged) -> wall (review, complete) -> done
  // (sink, complete). Re-opening m1 must move m1, m2, wall and done — four rows, zero of them announced
  // before this fix.
  const PLAN807F = (rows, tail) => ['# Plan — 807F', '',
    '## Meta', '', 'plan_form: spine', '',
    'expansion(m1):', '  milestone_goal: g1', '  expected_surfaces: scripts/',
    '  join_constraints: none', '  review_class: code-reviewer', '',
    'expansion(m2):', '  milestone_goal: g2', '  expected_surfaces: scripts/',
    '  join_constraints: none', '  review_class: code-reviewer', '',
    '## Nodes', '',
    '| id | role | depends_on | declared_write_set | cardinality | shape |',
    '|---|---|---|---|---|---|',
    '| m1 | expansion-point | — | — | 1 | sequence |',
    '| m2 | expansion-point | m1 | — | 1 | sequence |',
    '| wall | code-reviewer | m1, m2 | — | 1 | sequence |',
    '| done | finalize | wall | — | 1 | sequence |', '',
    '## Node Ledger', '', '| id | status |', '|---|---|', ...rows, '',
    ...(tail || [])].join('\n');

  const RECORD = (id, point, units) => ['record(' + id + '):', '  point: ' + point,
    '  grain: g', '  path: p', '  join: j', '  probe: pr', '  serializer: none',
    ...units.map(u => '  unit: ' + u + ' | code-explorer | — | — | co_open | —')];

  const mk = (planText, readyIds) => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-807f-'));
    const projectDir = path.join(tmp, 'kaola-workflow', 'issue-807f');
    fs.mkdirSync(path.join(projectDir, '.cache'), { recursive: true });
    const planPath = path.join(projectDir, 'workflow-plan.md');
    fs.writeFileSync(planPath, planText);
    fs.writeFileSync(path.join(projectDir, 'workflow-state.md'), 'project: issue-807f\nbranch: wf/807f\n');
    return {
      tmp, planPath, projectDir,
      opts: {
        planPath, project: 'issue-807f',
        shell: (scriptPath, args) => {
          const base = path.basename(String(scriptPath));
          if (base === 'kaola-workflow-next-action.js') {
            return { exitCode: 0, result: 'ok', allDone: false,
              readyPending: (readyIds || []).map(id => ({ id, role: 'code-explorer',
                declared_write_set: '—', model: 'standard', kind: 'read' })) };
          }
          if (base === 'kaola-workflow-task-mirror.js') return { exitCode: 0, result: 'ok' };
          return { exitCode: 0, ok: true, result: 'ok', recordBase: { base: 'b'.repeat(40) } };
        },
        readFile: p => fs.readFileSync(p, 'utf8'),
        writeFile: (p, c) => fs.writeFileSync(p, c),
        cacheExists: p => fs.existsSync(p),
        mkdirp: d => { try { fs.mkdirSync(d, { recursive: true }); } catch (_) {} },
        unlink: p => { try { fs.unlinkSync(p); } catch (_) {} },
        now: () => 'T',
        sinkProgressProbe: () => ({ state: 'pristine', evidence: 'test' }),
      },
      cleanup: () => fs.rmSync(tmp, { recursive: true, force: true }),
    };
  };

  // movedRows(before, after) — the ids whose ledger status CHANGED. The authority both F1 and F2 are
  // judged against; a hand-listed expectation would go stale the moment the cascade grows an arm.
  const movedRows = (before, after) => {
    const b = readLedgerStatuses(before);
    const a = readLedgerStatuses(after);
    return Object.keys(a).filter(id => b[id] !== a[id]).sort();
  };

  // --- F1: the re-open cascade announces EVERY row it moves. ---
  {
    const SETTLED = ['| m1 | complete |', '| m2 | complete |', '| wall | complete |', '| done | complete |',
      '| m1-r1-a | complete |', '| m2-r1-a | complete |'];
    const TAIL = ['## Expansion Records', '',
      ...RECORD('m1#1', 'm1', ['a']), '', 'open(m1#1):', '  at: T', '',
      ...RECORD('m2#1', 'm2', ['a']), '', 'open(m2#1):', '  at: T', ''];
    const f = mk(PLAN807F(SETTLED, TAIL), ['m1-r2-fix']);
    try {
      const before = fs.readFileSync(f.planPath, 'utf8');
      const r = runReExpandOpen({ ...f.opts, nodeId: 'm1',
        composition: { derivation: { ...DERIV }, units: [
          { name: 'fix', role: 'code-explorer', model: 'standard', write_set: 'scripts/a.js', mode: 'co_open' }] } });
      assert(r.result === 'ok' && r.reopened === true,
        '#807-F1 PRECONDITION: the re-open must commit, got ' + JSON.stringify({ result: r.result, reason: r.reason, detail: r.detail }));
      const after = fs.readFileSync(f.planPath, 'utf8');
      const moved = movedRows(before, after);
      // PRECONDITION: the cascade really did un-complete the owner + its wall (the rows the operator's
      // list is asserting are done). If this ever stops being true the test below proves nothing.
      for (const id of ['m1', 'wall']) {
        assert(moved.includes(id),
          '#807-F1 PRECONDITION: the cascade must move ' + id + ' off complete, moved=' + JSON.stringify(moved));
      }
      const announced = new Set((r.taskTransitions || []).map(t => t.id));
      const silent = moved.filter(id => !announced.has(id));
      assert(silent.length === 0,
        '#807-F1: every ledger row the re-open cascade MOVES must be announced through taskTransitions — '
        + 'moved ' + JSON.stringify(moved) + ' but announced ' + JSON.stringify(Array.from(announced))
        + ', so ' + JSON.stringify(silent) + ' moved silently');
      // And the announcement must carry the row's REAL new status, not merely name the id.
      const st = readLedgerStatuses(after);
      for (const t of (r.taskTransitions || [])) {
        if (!Object.prototype.hasOwnProperty.call(st, t.id)) continue;
        assert(t.ledger_status === st[t.id],
          '#807-F1: transition for ' + t.id + ' claims ' + t.ledger_status + ' but the ledger says '
          + st[t.id]);
      }
      // The newly composed fixer unit is still announced (the #807 shape channel is intact).
      assert(announced.has('m1-r2-fix'),
        '#807-F1 CONTROL: the composed fixer unit is still announced, got ' + JSON.stringify(Array.from(announced)));
    } finally { f.cleanup(); }
  }

  // --- F2: crash recovery announces the frontier it rolls forward. ---
  // A record appended by Phase 1 whose `open()` proof never landed, and NO running set at all — the
  // `no_running_set` arm, the most common shape of that crash.
  {
    const ROWS = ['| m1 | pending |', '| m2 | pending |', '| wall | pending |', '| done | pending |',
      '| m1-r1-a | pending |', '| m1-r1-b | pending |'];
    const TAIL = ['## Expansion Records', '', ...RECORD('m1#1', 'm1', ['a', 'b']), ''];
    const f = mk(PLAN807F(ROWS, TAIL), ['m1-r1-a']);
    try {
      const before = fs.readFileSync(f.planPath, 'utf8');
      const r = runReconcileRunningSet({ ...f.opts });
      assert(r.result === 'ok' && JSON.stringify(r.expansionsRolledForward) === '["m1#1"]',
        '#807-F2 PRECONDITION: the unproven record must roll forward, got ' + JSON.stringify({ result: r.result, reason: r.reason, rolled: r.expansionsRolledForward }));
      const after = fs.readFileSync(f.planPath, 'utf8');
      const moved = movedRows(before, after);
      assert(moved.includes('m1-r1-a'),
        '#807-F2 PRECONDITION: the roll-forward must open a unit, moved=' + JSON.stringify(moved));
      const announced = new Set((r.taskTransitions || []).map(t => t.id));
      const silent = moved.filter(id => !announced.has(id));
      assert(silent.length === 0,
        '#807-F2: reconcile-running-set is the DOCUMENTED crash recovery, so the units its roll-forward '
        + 're-opens must be announced — moved ' + JSON.stringify(moved) + ', announced '
        + JSON.stringify(Array.from(announced)));
      // The composed-but-unopened sibling is a `pending` INSERT, exactly as a first-try expand-open emits.
      const byId = new Map((r.taskTransitions || []).map(t => [t.id, t]));
      assert(byId.get('m1-r1-a') && byId.get('m1-r1-a').ledger_status === 'in_progress',
        '#807-F2: the re-opened unit is announced in_progress, got ' + JSON.stringify(byId.get('m1-r1-a')));
      assert(byId.get('m1-r1-b') && byId.get('m1-r1-b').ledger_status === 'pending',
        '#807-F2: the composed-but-unopened sibling is announced as a pending INSERT (recovery presents '
        + 'the same SHAPE a first-try expansion does), got ' + JSON.stringify(byId.get('m1-r1-b')));
    } finally { f.cleanup(); }
  }

  // --- F2b: a stable plan still emits nothing (the roll-forward is a no-op ⇒ no phantom transitions). ---
  {
    const ROWS = ['| m1 | complete |', '| m2 | pending |', '| wall | pending |', '| done | pending |',
      '| m1-r1-a | complete |'];
    const TAIL = ['## Expansion Records', '', ...RECORD('m1#1', 'm1', ['a']), '', 'open(m1#1):', '  at: T', ''];
    const f = mk(PLAN807F(ROWS, TAIL), []);
    try {
      const r = runReconcileRunningSet({ ...f.opts });
      assert(r.result === 'ok' && JSON.stringify(r.taskTransitions) === '[]',
        '#807-F2b: a fully-proven, stable plan rolls nothing forward, so it must announce NOTHING, got '
        + JSON.stringify(r.taskTransitions));
    } finally { f.cleanup(); }
  }

  // --- F4: the unit transitions arrive IN RECORD ORDER, so "insert in record order" is followable. ---
  // The frontier opens u2 and u3 while u1 waits behind an unmet edge; frontier order would be
  // [u2, u3, u1], which no runtime can turn into a record-ordered insert.
  {
    const ROWS = ['| m1 | pending |', '| m2 | pending |', '| wall | pending |', '| done | pending |'];
    const f = mk(PLAN807F(ROWS, ['## Expansion Records', '']), ['m1-r1-u2', 'm1-r1-u3']);
    try {
      const r = runExpandOpen({ ...f.opts, nodeId: 'm1', composition: { derivation: { ...DERIV }, units: [
        { name: 'u1', role: 'code-explorer', model: 'standard', write_set: '', mode: 'serial', depends_on: ['u2'] },
        { name: 'u2', role: 'code-explorer', model: 'standard', write_set: '', mode: 'co_open' },
        { name: 'u3', role: 'code-explorer', model: 'standard', write_set: '', mode: 'co_open' },
      ] } });
      assert(r.result === 'ok', '#807-F4 PRECONDITION: the expansion must commit, got ' + JSON.stringify(r.reason));
      assert(JSON.stringify((r.opened || []).map(n => n.id)) === JSON.stringify(['m1-r1-u2', 'm1-r1-u3']),
        '#807-F4 PRECONDITION: the frontier opens u2/u3 and leaves u1 behind, got ' + JSON.stringify((r.opened || []).map(n => n.id)));
      assert(JSON.stringify((r.taskTransitions || []).map(t => t.id))
        === JSON.stringify(['m1-r1-u1', 'm1-r1-u2', 'm1-r1-u3']),
      '#807-F4: every plan-run surface tells the operator to insert a newly-announced unit "in record '
        + 'order", so the emitted unit transitions must BE in record order — got '
        + JSON.stringify((r.taskTransitions || []).map(t => t.id)));
    } finally { f.cleanup(); }
  }
});

// ===========================================================================
// T-SEED-ATOMIC (#776): seedEvidenceFile's durable writes are crash-atomic AND
// the forceRotate path FAILS LOUD instead of returning success-shaped metadata.
//
// The rotation write exists SOLELY to discard a prior attempt's body so a stale
// `verdict: pass` cannot survive into a new open (the anti-replay guard). Its
// pre-fix shape was a bare fs.writeFileSync inside a whole-body `catch (_)` that
// returns success-shaped metadata — so ANY write failure (ENOSPC/EIO/EROFS) left
// the stale body byte-intact under a still-valid binding and reported success.
// ===========================================================================
scenario(() => {
  const isRoot776 = typeof process.getuid === 'function' && process.getuid() === 0;
  const STALE_BODY = 'evidence-binding: rot-node abcdef123456\nverdict: pass\nfindings_blocking: 0\nRED: stale red\nGREEN: stale green\n';

  const mkSeedFixture = (nodeId) => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-seed776-'));
    const projectDir = path.join(tmp, 'kaola-workflow', 'issue-776');
    const cacheDir = path.join(projectDir, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    const planPath = path.join(projectDir, 'workflow-plan.md');
    fs.writeFileSync(planPath, '# dummy plan\n', 'utf8');
    const cachePath = path.join(cacheDir, nodeId + '.md');
    return { tmp, planPath, cacheDir, cachePath };
  };

  // (a) FAIL LOUD: an UNRECOVERABLE rotation write (read-only .cache dir + read-only
  //     body — the EROFS/ENOSPC analogue) must return a failure-shaped result, NOT
  //     success-shaped metadata over a surviving stale `verdict: pass` body.
  if (!isRoot776) {
    const f = mkSeedFixture('rot-node');
    let r776a = null;
    try {
      fs.writeFileSync(f.cachePath, STALE_BODY, 'utf8');
      fs.chmodSync(f.cachePath, 0o400);
      fs.chmodSync(f.cacheDir, 0o500);
      r776a = seedEvidenceFile(f.planPath, 'rot-node', 'abcdef123456', 'tdd-guide', true);
    } finally {
      try { fs.chmodSync(f.cacheDir, 0o700); } catch (_) {}
      try { fs.chmodSync(f.cachePath, 0o600); } catch (_) {}
    }
    assert(r776a && r776a.ok === false && r776a.reason === 'evidence_seed_failed',
      'T-SEED-ATOMIC-a: an unrecoverable forceRotate write returns {ok:false, reason:evidence_seed_failed}, got '
      + JSON.stringify(r776a));
    assert(r776a && r776a.nonce_rotated !== true,
      'T-SEED-ATOMIC-a: a failed rotation NEVER claims nonce_rotated:true, got ' + JSON.stringify(r776a));
    assert(typeof r776a.detail === 'string' && r776a.detail.length > 0,
      'T-SEED-ATOMIC-a: the failure carries the underlying write error detail, got ' + JSON.stringify(r776a));
    fs.rmSync(f.tmp, { recursive: true, force: true });
  }

  // (b) ATOMICITY: a write-protected BODY in a writable .cache dir is exactly the
  //     case a bare writeFileSync cannot rotate (EACCES on the O_TRUNC open) but an
  //     atomic tmp+rename CAN. The stale `verdict: pass` body must not survive.
  if (!isRoot776) {
    const f = mkSeedFixture('rot-node');
    let r776b = null;
    try {
      fs.writeFileSync(f.cachePath, STALE_BODY, 'utf8');
      fs.chmodSync(f.cachePath, 0o400);
      r776b = seedEvidenceFile(f.planPath, 'rot-node', 'newnonce9999', 'tdd-guide', true);
    } finally {
      try { fs.chmodSync(f.cachePath, 0o600); } catch (_) {}
    }
    const after776b = fs.existsSync(f.cachePath) ? fs.readFileSync(f.cachePath, 'utf8') : '';
    assert(r776b && r776b.ok !== false && r776b.nonce_rotated === true,
      'T-SEED-ATOMIC-b: an atomic replace rotates over a write-protected body, got ' + JSON.stringify(r776b));
    assert(!/verdict:\s*pass/.test(after776b) && !/GREEN: stale green/.test(after776b),
      'T-SEED-ATOMIC-b: the stale `verdict: pass` body does NOT survive the rotation, got ' + JSON.stringify(after776b));
    assert(after776b.split('\n')[0] === 'evidence-binding: rot-node newnonce9999',
      'T-SEED-ATOMIC-b: line 1 carries the fresh binding, got ' + JSON.stringify(after776b.split('\n')[0]));
    fs.rmSync(f.tmp, { recursive: true, force: true });
  }

  // (c) UNPARSEABLE LINE 1 ⇒ RE-SEED. An existing file whose line-1 binding cannot be
  //     parsed (torn by the pre-fix bare write, or clobbered) is NOT "already seeded":
  //     treating it as seeded wedges the node forever (close always refuses
  //     evidence_unbound). It must be re-seeded even with forceRotate FALSE.
  {
    const f = mkSeedFixture('torn-node');
    fs.writeFileSync(f.cachePath, 'evidence-bind', 'utf8');   // truncated header — no parseable binding
    const r776c = seedEvidenceFile(f.planPath, 'torn-node', 'freshnonce12', 'tdd-guide', false);
    const after776c = fs.readFileSync(f.cachePath, 'utf8');
    assert(after776c.split('\n')[0] === 'evidence-binding: torn-node freshnonce12',
      'T-SEED-ATOMIC-c: an unparseable line-1 body is RE-SEEDED (not treated as already-seeded), got '
      + JSON.stringify(after776c.split('\n')[0]));
    assert(r776c && r776c.ok !== false,
      'T-SEED-ATOMIC-c: the re-seed is success-shaped, got ' + JSON.stringify(r776c));
    fs.rmSync(f.tmp, { recursive: true, force: true });
  }

  // (d) INVARIANCE: a genuine crash-resume (line-1 binding parses AND matches the
  //     requested nonce) still PRESERVES the in-progress body. The (c) widening must
  //     not turn every re-open into a body-destroying re-seed.
  {
    const f = mkSeedFixture('resume-node');
    const inProgress = 'evidence-binding: resume-node keepnonce123\nRED: real red output\nred_baseline: keepnonce123\n';
    fs.writeFileSync(f.cachePath, inProgress, 'utf8');
    const r776d = seedEvidenceFile(f.planPath, 'resume-node', 'keepnonce123', 'tdd-guide', false);
    assert(r776d && r776d.nonce_rotated === false && fs.readFileSync(f.cachePath, 'utf8') === inProgress,
      'T-SEED-ATOMIC-d: a same-nonce crash-resume is byte-preserving, got ' + JSON.stringify(r776d));
    fs.rmSync(f.tmp, { recursive: true, force: true });
  }

  // (e) INVARIANCE: forceRotate=false on an unreachable path stays ADVISORY (never
  //     throws, never fail-shaped) — the open path must not be bricked by a seed hiccup.
  {
    let threw776e = false;
    let r776e = null;
    try { r776e = seedEvidenceFile('/no/such/path/workflow-plan.md', 'nx', 'nonce', 'unknown-role', false); }
    catch (_) { threw776e = true; }
    assert(!threw776e && r776e && r776e.ok !== false && Array.isArray(r776e.required_tokens),
      'T-SEED-ATOMIC-e: a NON-rotating seed failure stays advisory (success-shaped, no throw), got '
      + JSON.stringify(r776e));
  }
});

// ===========================================================================
// T-REPAIR-REPLAY (#776): runRepairNode must REFUSE when the evidence rotation
// fails, instead of appending the repair brief onto a stale `verdict: pass` body.
//
// This is the complete anti-replay bypass. In repair the nonce is UNCHANGED by
// design (baselineReused:true — readNonce derives it from the REUSED
// barrier-base), so a swallowed rotation failure leaves a VALID nonce on a stale
// pass body: checkEvidenceShape's expectedNonce passes, the stale verdict passes,
// and the brief is appended on top — laundering it into "fresh seed + brief".
// ===========================================================================
scenario(() => {
  const tmp776r = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-repair776-'));
  try {
    const projectDir = path.join(tmp776r, 'kaola-workflow', 'issue-776r');
    const cacheDir = path.join(projectDir, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    const body = makePlan([
      '| writer | complete | |', '| review | in_progress | |', '| done | pending | |',
    ], [
      '| writer | tdd-guide | — | scripts/writer.js | 1 | sequence |',
      '| review | code-reviewer | writer | — | 1 | sequence |',
      '| done | finalize | review | CHANGELOG.md | 1 | sequence |',
    ]);
    const hash = planValidator.computePlanHash(body);
    const planPath = path.join(projectDir, 'workflow-plan.md');
    const journalPath = path.join(cacheDir, 'review-attempts.json');
    const writerBaseline = 'w'.repeat(40);
    const identity = { baseline: writerBaseline, anchored_ref: writerBaseline,
      open_token: 'writer-open-token', generation: writerBaseline.slice(0, 12),
      ref: 'refs/kaola-workflow/barrier/issue-776r/writer' };
    fs.writeFileSync(planPath, '<!-- plan_hash: ' + hash + ' -->\n' + body);
    fs.writeFileSync(path.join(cacheDir, 'barrier-base-writer'), writerBaseline + '\n');
    fs.writeFileSync(path.join(cacheDir, 'barrier-base-review'), 'rrrrrrrrrrrr-rest\n');
    fs.writeFileSync(path.join(cacheDir, 'review.md'),
      'evidence-binding: review rrrrrrrrrrrr\nverdict: fail\nfindings_blocking: 1\n');
    fs.writeFileSync(path.join(cacheDir, 'running-set.json'), JSON.stringify({ state: 'open',
      nodes: [{ id: 'review', role: 'code-reviewer', kind: 'read' }] }));
    // The stale PRIOR-ATTEMPT body the rotation exists to destroy. Its binding nonce is
    // the writer's REUSED baseline generation — i.e. a VALID nonce for the repair open.
    const writerEvidence = path.join(cacheDir, 'writer.md');
    const stalePass = 'evidence-binding: writer ' + writerBaseline.slice(0, 12)
      + '\nRED: prior attempt red\nGREEN: prior attempt green\nverdict: pass\nfindings_blocking: 0\n';
    fs.writeFileSync(writerEvidence, stalePass, 'utf8');
    const common = { planPath, project: 'issue-776r',
      shell: () => ({ exitCode: 0, result: 'ok', ok: true, overallOk: true,
        selectorCheck: { isSelector: false, ok: true } }),
      readFile: p => fs.readFileSync(p, 'utf8'), writeFile: (p, c) => fs.writeFileSync(p, c),
      cacheExists: p => fs.existsSync(p), unlink: p => fs.unlinkSync(p), readdir: d => fs.readdirSync(d),
      computeReviewCandidateDigest: () => '7'.repeat(64), captureWriterBarrierIdentity: () => identity };

    const closed = runCloseNode({ ...common, nodeId: 'review' });
    const journal = JSON.parse(fs.readFileSync(journalPath, 'utf8'));
    const attempt = journal.attempts[0];
    assert(closed.result === 'review_failed' && attempt,
      'T-REPAIR-REPLAY: the failing review produces a repairable attempt, got ' + JSON.stringify(closed));

    // Fault injection: the FIRST durable write targeting the writer's evidence file
    // throws (ENOSPC). One-shot + path-scoped, so the repair's own subsequent append
    // (the laundering step) is left free to succeed — which is exactly what the
    // pre-fix code does and what the fix must prevent.
    const origWrite776 = fs.writeFileSync;
    const origOpen776 = fs.openSync;
    const tmpPrefix776 = path.join(cacheDir, '.writer.md.');
    let shots776 = 1;
    const enospc776 = () => { const e = new Error('T-776 injected fault: ENOSPC on evidence rotation'); e.code = 'ENOSPC'; return e; };
    fs.writeFileSync = function (p, ...rest) {
      if (shots776 > 0 && typeof p === 'string' && p === writerEvidence) { shots776--; throw enospc776(); }
      return origWrite776.apply(fs, [p, ...rest]);
    };
    fs.openSync = function (p, ...rest) {
      if (shots776 > 0 && typeof p === 'string' && p.startsWith(tmpPrefix776)) { shots776--; throw enospc776(); }
      return origOpen776.apply(fs, [p, ...rest]);
    };
    let repaired776 = null;
    let threw776 = null;
    try { repaired776 = runRepairNode({ ...common, nodeId: 'writer', attemptId: attempt.attempt_id }); }
    catch (err) { threw776 = err; }
    finally { fs.writeFileSync = origWrite776; fs.openSync = origOpen776; }

    assert(shots776 === 0, 'T-REPAIR-REPLAY: the injected rotation fault actually fired (test is not vacuous)');
    assert(!threw776, 'T-REPAIR-REPLAY: the refusal is a typed return, never a raw throw, got ' + (threw776 && threw776.message));
    assert(repaired776 && repaired776.result === 'refuse' && repaired776.reason === 'evidence_seed_failed',
      'T-REPAIR-REPLAY: a failed evidence rotation REFUSES the repair, got ' + JSON.stringify(repaired776));
    const after776 = fs.existsSync(writerEvidence) ? fs.readFileSync(writerEvidence, 'utf8') : '';
    assert(!/verdict:\s*pass/.test(after776),
      'T-REPAIR-REPLAY: the stale `verdict: pass` body never survives a failed rotation, got ' + JSON.stringify(after776));
    assert(!/repair brief/i.test(after776) && !/finding/i.test(after776),
      'T-REPAIR-REPLAY: the repair brief is NEVER appended onto a stale body, got ' + JSON.stringify(after776));
  } finally { fs.rmSync(tmp776r, { recursive: true, force: true }); }
});

// ===========================================================================
// T-REOPEN-SEEDFAIL (#776): runReopenNode refuses on the same failure signal.
// Reopen's whole contract is "a NEW nonce over a FRESH body" — handing the node
// back out over an evidence file we could not rewrite breaks it.
// ===========================================================================
scenario(() => {
  const tmp776o = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-reopen776-'));
  try {
    const projectDir = path.join(tmp776o, 'kaola-workflow', 'issue-776o');
    const cacheDir = path.join(projectDir, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    const planPath = path.join(projectDir, 'workflow-plan.md');
    const nodes776o = [
      '| impl | tdd-guide | — | scripts/impl.js | 1 | sequence |',
      '| review | code-reviewer | impl | — | 1 | sequence |',
      '| finalize | finalize | review | CHANGELOG.md | 1 | sequence |',
    ];
    fs.writeFileSync(planPath, makePlan(['| impl | complete | |', '| review | complete | |',
      '| finalize | pending | |'], nodes776o));
    const implEvidence = path.join(cacheDir, 'impl.md');
    fs.writeFileSync(implEvidence,
      'evidence-binding: impl oldnonce1234\nRED: prior red\nGREEN: prior green\nverdict: pass\n', 'utf8');

    const origWrite776o = fs.writeFileSync;
    const origOpen776o = fs.openSync;
    const tmpPrefix776o = path.join(cacheDir, '.impl.md.');
    let shots776o = 1;
    const eio776o = () => { const e = new Error('T-776 injected fault: EIO on evidence rotation'); e.code = 'EIO'; return e; };
    fs.writeFileSync = function (p, ...rest) {
      if (shots776o > 0 && typeof p === 'string' && p === implEvidence) { shots776o--; throw eio776o(); }
      return origWrite776o.apply(fs, [p, ...rest]);
    };
    fs.openSync = function (p, ...rest) {
      if (shots776o > 0 && typeof p === 'string' && p.startsWith(tmpPrefix776o)) { shots776o--; throw eio776o(); }
      return origOpen776o.apply(fs, [p, ...rest]);
    };
    let reopened776 = null;
    try {
      reopened776 = runReopenNode({
        planPath, project: 'issue-776o', nodeId: 'impl',
        shell: () => ({ exitCode: 0, result: 'ok', recordBase: { base: 'a'.repeat(40) } }),
        readFile: p => origWrite776o && fs.readFileSync(p, 'utf8'),
        writeFile: (p, c) => origWrite776o.apply(fs, [p, c]),
        cacheExists: p => fs.existsSync(p), unlink: () => {}, readdir: () => [],
      });
    } finally { fs.writeFileSync = origWrite776o; fs.openSync = origOpen776o; }

    assert(shots776o === 0, 'T-REOPEN-SEEDFAIL: the injected rotation fault actually fired (test is not vacuous)');
    assert(reopened776 && reopened776.result === 'refuse' && reopened776.reason === 'evidence_seed_failed',
      'T-REOPEN-SEEDFAIL: reopen refuses when the evidence rotation fails, got ' + JSON.stringify(reopened776));
    const afterReopen776 = fs.existsSync(implEvidence) ? fs.readFileSync(implEvidence, 'utf8') : '';
    assert(!/verdict:\s*pass/.test(afterReopen776),
      'T-REOPEN-SEEDFAIL: the stale body does not survive the failed rotation, got ' + JSON.stringify(afterReopen776));
  } finally { fs.rmSync(tmp776o, { recursive: true, force: true }); }
});


// ===========================================================================
// #783 — freeze-view vs execution-view family, the two review-lifecycle sites. Post-#765 the planner
// authors plan_form: spine always; a milestone that opens writes its production files through EXPANSION
// UNITS, which live in `## Expansion Records` + `## Node Ledger` but NEVER `## Nodes`.
//   :1837 (validateSchema2ReviewEvidence) — a GENUINE execution-state defect: the review candidate
//         partition + anchor producer cone are recorded at ONE review event over the CURRENT accumulated
//         write set, so a composed unit's legitimate write must not read as undeclared residue. Fixed to
//         the EXECUTION view (parseNodesFromContent), pinned so a mutation reverting it reddens the pin.
//   :4706 (reviewJournalV2MatchesPlan) — VERIFIED NOT A DEFECT (stays the FREEZE view). This matcher
//         re-validates a HISTORICAL journal attempt against the plan; its producer re-derivation must be
//         INVARIANT across execution-time growth or a settled attempt stops matching once a milestone
//         re-expands. The shipped #756 re-expansion epoch-transition wedge
//         (simulate-workflow-walkthrough testReExpansionEpochTransition756) proves it: an
//         execution-view swap there makes a discovery attempt's producer_bindings=[] mismatch the
//         re-derived ["m1-r2-fx"] (a fixer unit that POSTDATES the attempt), spuriously refusing
//         review_journal_repair_identity_mismatch and short-circuiting the sanctioned epoch-transition
//         escalation. So :4706 is pinned to STAY parseNodes, a fourth refuted sibling.
// The build below carries a REAL `## Expansion Records` block (renderExpansionRecord output) so the two
// node views genuinely disagree — a `## Nodes`-only spine would prove nothing.
scenario(() => {
  const { renderExpansionRecord } = require('./kaola-workflow-adaptive-node');
  const NODE_ROWS_783 = [
    '| probe | code-explorer | — | — | 1 | sequence |',
    '| m1 | expansion-point | probe | — | 1 | sequence |',
    '| wall | code-reviewer | m1 | — | 1 | sequence |',
    '| done | finalize | wall | CHANGELOG.md | 1 | sequence |',
  ];
  const LEDGER_783 = ['| probe | complete | |', '| m1 | in_progress | |',
    '| wall | pending | |', '| done | pending | |'];
  const spinePlan = makePlan(LEDGER_783, NODE_ROWS_783);
  // A REAL record block: one composed writer unit u1 on m1 declaring lib/composed.js.
  const record = renderExpansionRecord('m1#1', 'm1', 'a'.repeat(64),
    { grain: 'g', path: 'p', join: 'j', probe: 'pr', serializer: 'none present — co-open' },
    [{ name: 'u1', role: 'implementer', model: 'standard', write_set: 'lib/composed.js', mode: 'co_open',
      depends_on: [] }]);
  const recordsPlan = spinePlan + '\n## Expansion Records\n\n' + record + 'open(m1#1):\n  at: 2026-07-24T00:00:00.000Z\n';

  // The two node views genuinely disagree: the composed unit and its declared write live ONLY in the
  // EXECUTION view. This is the exact input that :1837 records IMMUTABLY as the candidate residue digest
  // and that :4706 re-derives producer bindings over — misread by the freeze view, the unit's legitimate
  // write is misclassified as review residue / its producer cone is under-derived.
  const freezeNodes = planValidator.parseNodes(recordsPlan);
  const execNodes = planValidator.planNodesWithExpansions(recordsPlan);
  assert(!freezeNodes.some(n => n.id === 'm1-r1-u1'),
    '#783 review-fixture: the FREEZE view (parseNodes) misses the composed unit');
  const execUnit = execNodes.find(n => n.id === 'm1-r1-u1');
  assert(execUnit && Array.from(execUnit.writeSet || []).includes('lib/composed.js'),
    '#783 review-fixture: the EXECUTION view carries the composed unit with its declared write lib/composed.js');
  const freezeUnion = new Set();
  for (const n of freezeNodes) for (const p of (n.writeSet || [])) freezeUnion.add(p);
  const execUnion = new Set();
  for (const n of execNodes) for (const p of (n.writeSet || [])) execUnion.add(p);
  assert(!freezeUnion.has('lib/composed.js') && execUnion.has('lib/composed.js'),
    '#783 :1837: the declared-write UNION the review candidate partition ranges over includes the unit '
    + 'write only on the execution view (freeze=' + JSON.stringify([...freezeUnion]) + ' exec='
    + JSON.stringify([...execUnion]) + ') — read by the freeze view it becomes false residue');

  // :4706 — reviewJournalV2MatchesPlan's producer re-derivation MUST stay invariant across execution-time
  // growth. Demonstrate the growth that breaks an execution-view read: re-expanding m1 (ordinal 2) appends
  // a SECOND fixer unit the wall now post-dominates, so the execution-view producer set GROWS while a
  // historical journal attempt's recorded bindings do not.
  const record2 = renderExpansionRecord('m1#2', 'm1', 'a'.repeat(64),
    { grain: 'g', path: 'p', join: 'j', probe: 'pr', serializer: 'none present — co-open' },
    [{ name: 'u2', role: 'implementer', model: 'standard', write_set: 'lib/companion.js', mode: 'co_open',
      depends_on: [] }]);
  const reExpandedPlan = recordsPlan + record2 + 'open(m1#2):\n  at: 2026-07-24T01:00:00.000Z\n';
  const execIdsBefore = planValidator.planNodesWithExpansions(recordsPlan).map(n => n.id);
  const execIdsAfter = planValidator.planNodesWithExpansions(reExpandedPlan).map(n => n.id);
  assert(execIdsAfter.includes('m1-r2-u2') && !execIdsBefore.includes('m1-r2-u2'),
    '#783 :4706: a re-expansion GROWS the execution view (m1-r2-u2 appears) — so an execution-view '
    + 'producer re-derivation of a HISTORICAL journal attempt would spuriously grow and mismatch, which '
    + 'is why :4706 must stay the FREEZE view (the spine is invariant across re-expansion)');
  assert(planValidator.parseNodes(reExpandedPlan).map(n => n.id).join(',') === 'probe,m1,wall,done',
    '#783 :4706: the FREEZE view stays invariant across the re-expansion — the stable identity a settled '
    + 'journal attempt is matched against');

  // Source pins.
  const nodeSrc = fs.readFileSync(path.join(__dirname, 'kaola-workflow-adaptive-node.js'), 'utf8');
  const v2Fn = nodeSrc.slice(nodeSrc.indexOf('function validateSchema2ReviewEvidence('),
    nodeSrc.indexOf('function validateSchema2ReviewEvidence(') + 6000);
  assert(/const reviewNodes = parseNodesFromContent\(planContent\);/.test(v2Fn),
    '#783 :1837 pin: the review candidate partition + anchor cone range over the EXECUTION view '
    + '(parseNodesFromContent) — reverting to validator.parseNodes reddens this');
  const journalFn = nodeSrc.slice(nodeSrc.indexOf('function reviewJournalV2MatchesPlan('),
    nodeSrc.indexOf('const byId = new Map(nodes.map(node => [node.id, node]));',
      nodeSrc.indexOf('function reviewJournalV2MatchesPlan(')));
  assert(/const nodes = validator\.parseNodes\(planContent\);/.test(journalFn),
    '#783 :4706 pin (VERIFIED NOT A DEFECT): reviewJournalV2MatchesPlan STAYS the FREEZE view '
    + '(validator.parseNodes) — an execution-view swap regresses the shipped #756 re-expansion '
    + 'epoch-transition wedge (testReExpansionEpochTransition756)');
});

// ===========================================================================
// #804 — the `--parallel-safe` verdict must never be LAUNDERED. ONE shared classifier for BOTH call
// sites (tryFormLaneGroup / selectSpeculativeWriteGroup), EXACTLY ONE bounded re-probe on an
// indeterminate verdict, and a CLASSIFIED serialDegradeReason on the normal site's degrade.
// Direct unit calls against the injectable shell seam — the probe never reads the plan, so no fixture
// repo is needed and no real git is touched.
// ===========================================================================
scenario(() => {
  const ADAPT = require('./kaola-workflow-adaptive-node');
  const P = '/p/workflow-plan.md';
  const twoWrites = [{ id: 'w1', declared_write_set: 'a.js' }, { id: 'w2', declared_write_set: 'b.js' }];
  // A counting shell: records every --parallel-safe invocation and replays a scripted verdict list
  // (the last entry repeats once exhausted).
  function scriptedShell(verdicts) {
    const calls = [];
    const shell = (scriptPath, args) => {
      if ((args || []).includes('--parallel-safe')) {
        calls.push((args || []).slice());
        return verdicts[Math.min(calls.length - 1, verdicts.length - 1)];
      }
      return { exitCode: 0, result: 'ok' };
    };
    return { shell, calls };
  }
  const OK = { exitCode: 0, result: 'ok' };
  const OVERLAP = { exitCode: 1, result: 'refuse', overlapping: [{ a: 'w1', b: 'w2' }] };
  const CRASH = { exitCode: 1 };                       // no result, no overlapping array
  const GARBLED = { exitCode: 0, result: 'refuse' };   // non-ok shape with no overlapping array

  // ---- D1: the classifier is ONE function with three outcomes -------------------------------------
  assert(ADAPT.classifyParallelSafeVerdict(OK).kind === 'ok', '#804-D1: a clean verdict classifies ok');
  assert(ADAPT.classifyParallelSafeVerdict(OVERLAP).kind === 'overlap',
    '#804-D1: a non-ok verdict carrying a well-formed overlapping array is a real overlap REPORT');
  assert(ADAPT.classifyParallelSafeVerdict({ exitCode: 1, result: 'refuse', overlapping: [] }).kind === 'overlap',
    '#804-D1: an EMPTY overlapping array is still a delivered report (the field presence is the signal)');
  assert(ADAPT.classifyParallelSafeVerdict(CRASH).kind === 'indeterminate',
    '#804-D1: a crashed prover delivered NO verdict — indeterminate, not a proven overlap');
  assert(ADAPT.classifyParallelSafeVerdict(GARBLED).kind === 'indeterminate',
    '#804-D1: a garbled non-ok shape without the array is indeterminate too');

  // ---- D2 at tryFormLaneGroup: exactly ONE re-probe, two outcomes, no loop ------------------------
  {
    const { shell, calls } = scriptedShell([CRASH]);
    const grp = ADAPT.tryFormLaneGroup(twoWrites, P, shell, false);
    assert(grp.ok === false && grp.reason === 'parallel_safe_indeterminate',
      '#804-D2a: a twice-indeterminate prover fails CLOSED labeled parallel_safe_indeterminate (never laundered into overlapping_write_sets), got ' + JSON.stringify(grp));
    assert(calls.length === 2 && grp.probes === 2,
      '#804-D2a: EXACTLY two probe invocations (one re-probe, no retry loop), got ' + calls.length);
  }
  {
    // The repair is OBSERVABLE: a transient first fault + a clean second probe forms the group.
    const { shell, calls } = scriptedShell([CRASH, OK]);
    const grp = ADAPT.tryFormLaneGroup(twoWrites, P, shell, false);
    assert(grp.ok === true && grp.members.join(',') === 'w1,w2',
      '#804-D2b: a transient first fault repaired by the single re-probe forms the group, got ' + JSON.stringify(grp));
    assert(calls.length === 2 && grp.probes === 2, '#804-D2b: exactly two probes, got ' + calls.length);
  }
  {
    // A PROVEN overlap never re-probes — the prover delivered a verdict; re-asking is pure waste.
    const { shell, calls } = scriptedShell([OVERLAP]);
    const grp = ADAPT.tryFormLaneGroup(twoWrites, P, shell, false);
    assert(grp.ok === false && grp.reason === 'overlapping_write_sets',
      '#804-D2c: a proven overlap keeps the legitimate overlapping_write_sets serializer, got ' + JSON.stringify(grp));
    assert(calls.length === 1 && grp.probes === 1, '#804-D2c: a PROVEN overlap NEVER re-probes, got ' + calls.length);
  }
  {
    const { shell, calls } = scriptedShell([OK]);
    const grp = ADAPT.tryFormLaneGroup(twoWrites, P, shell, false);
    assert(grp.ok === true && calls.length === 1 && grp.probes === 1, '#804-D2d: a clean verdict never re-probes, got ' + calls.length);
  }

  // ---- D2 at selectSpeculativeWriteGroup: the SAME helper, so identical counts --------------------
  {
    const { shell, calls } = scriptedShell([CRASH]);
    const sel = ADAPT.selectSpeculativeWriteGroup(twoWrites, [], P, shell, false, null);
    assert(sel.excludedReason === 'parallel_safe_indeterminate' && sel.chosen.length === 0,
      '#804-D2e: the speculative selector fails closed on a twice-indeterminate verdict, got ' + JSON.stringify({ r: sel.excludedReason, chosen: sel.chosen.length }));
    assert(calls.length === 2 && sel.probes === 2, '#804-D2e: exactly two probes at the speculative site too, got ' + calls.length);
  }
  {
    const { shell, calls } = scriptedShell([CRASH, OK]);
    const sel = ADAPT.selectSpeculativeWriteGroup(twoWrites, [], P, shell, false, null);
    assert(sel.chosen.length === 2 && sel.excluded.length === 0,
      '#804-D2f: a transient fault repaired by the re-probe selects both candidates, got ' + JSON.stringify(sel.chosen.map(n => n.id)));
    assert(calls.length === 2 && sel.probes === 2, '#804-D2f: exactly two probes, got ' + calls.length);
  }
  {
    const { shell, calls } = scriptedShell([OVERLAP]);
    const sel = ADAPT.selectSpeculativeWriteGroup(twoWrites, [], P, shell, false, null);
    assert(sel.excludedReason === 'overlaps_live_writer' && calls.length === 1 && sel.probes === 1,
      '#804-D2g: a proven overlap at the speculative site keeps its label and NEVER re-probes, got ' + JSON.stringify({ r: sel.excludedReason, calls: calls.length }));
  }
});

// ---------------------------------------------------------------------------
// #804-D3 — the NORMAL co-open site's serial degrade carries the CLASSIFIED cause. Before this,
// "label absent" was shared by four causes and therefore distinguished nothing. Direct runOpenReady
// unit calls with a CLEAN stubbed parent (so the seam checkpoint never fires) and no running set.
// ---------------------------------------------------------------------------
scenario(() => {
  const plan = makePlan(['| w1 | pending | |', '| w2 | pending | |'], [
    '| w1 | implementer | — | scripts/a.js | 1 | sequence |',
    '| w2 | implementer | — | scripts/b.js | 1 | sequence |',
  ]);
  const nextAction = (base) => {
    if (base === 'kaola-workflow-next-action.js') {
      return { exitCode: 0, result: 'ok', allDone: false, readyPending: [
        { id: 'w1', role: 'implementer', declared_write_set: 'scripts/a.js' },
        { id: 'w2', role: 'implementer', declared_write_set: 'scripts/b.js' },
      ] };
    }
    if (base === 'kaola-workflow-commit-node.js') return { exitCode: 0, result: 'ok' };
    return { exitCode: 1, result: 'refuse' };
  };
  function runWith(parallelSafeVerdicts) {
    let psCalls = 0;
    const validatorStub = (base, args) => {
      if (args.includes('--resume-check')) return { exitCode: 0, ok: true };
      if (args.includes('--parent-clean-check')) return { exitCode: 0, result: 'pass' };
      if (args.includes('--parallel-safe')) {
        const v = parallelSafeVerdicts[Math.min(psCalls, parallelSafeVerdicts.length - 1)];
        psCalls++;
        return v;
      }
      return { exitCode: 0, result: 'ok' };
    };
    const h = rsHarness({ [RS_PLAN_PATH]: plan }, nextAction, validatorStub);
    const r = runOpenReady({ planPath: RS_PLAN_PATH, project: 'p', max: null, fanoutCapReadonly: 8,
      shell: h.shell, readFile: h.readFile, writeFile: h.writeFile, cacheExists: h.cacheExists, mkdirp: h.mkdirp });
    return { r, psCalls: () => psCalls };
  }
  // A twice-indeterminate prover degrades to serial, LABELED, after exactly two probes.
  {
    const { r, psCalls } = runWith([{ exitCode: 1 }]);
    assert(r.result === 'ok' && r.opened.length === 1 && !r.laneGroup,
      '#804-D3a: a twice-indeterminate prover degrades to a single serial write, got ' + JSON.stringify({ opened: r.opened && r.opened.map(n => n.id), laneGroup: r.laneGroup }));
    assert(r.serialDegradeReason === 'parallel_safe_indeterminate',
      '#804-D3a: the degrade is labeled parallel_safe_indeterminate, NOT laundered into overlapping_write_sets, got ' + JSON.stringify(r.serialDegradeReason));
    assert(psCalls() === 2, '#804-D3a: exactly two --parallel-safe invocations, got ' + psCalls());
  }
  // A PROVEN overlap degrades to serial with the legitimate serializer label, after ONE probe.
  {
    const { r, psCalls } = runWith([{ exitCode: 1, result: 'refuse', overlapping: [{ a: 'w1', b: 'w2' }] }]);
    assert(r.result === 'ok' && r.opened.length === 1 && !r.laneGroup, '#804-D3b: a proven overlap degrades to serial');
    assert(r.serialDegradeReason === 'overlapping_write_sets',
      '#804-D3b: the degrade is labeled overlapping_write_sets, got ' + JSON.stringify(r.serialDegradeReason));
    assert(psCalls() === 1, '#804-D3b: a PROVEN overlap NEVER re-probes, got ' + psCalls());
  }
  // A transient first fault + a clean second probe yields an OK verdict — the repair is observable at
  // the scheduler level. Pinned under KAOLA_FANOUT_CAP=1 so the frontier degrades on the OPERATOR cap
  // instead of forming a real lane group: a formed group provisions REAL leg worktrees, which a
  // direct-call test must never do (the io-shim trap). That the group attempt SUCCEEDED is proven by
  // the absence of any prover-caused degrade label alongside the two probe invocations; the co-open
  // itself is covered by #804-D2b (unit) and the real-git #802 scenarios.
  {
    const savedCap = process.env.KAOLA_FANOUT_CAP;
    process.env.KAOLA_FANOUT_CAP = '1';
    try {
      const { r, psCalls } = runWith([{ exitCode: 1 }, { exitCode: 0, result: 'ok' }]);
      assert(r.result === 'ok' && r.opened.length === 1 && !r.laneGroup,
        '#804-D3c: the capped frontier opens serially, got ' + JSON.stringify({ result: r.result, opened: r.opened && r.opened.map(n => n.id) }));
      assert(r.serialDegradeReason === undefined,
        '#804-D3c: a REPAIRED transient fault leaves NO prover degrade label — the cap degraded it, not the prover, got ' + JSON.stringify(r.serialDegradeReason));
      assert(psCalls() === 2, '#804-D3c: exactly two probes (the single re-probe fired), got ' + psCalls());
    } finally {
      if (savedCap === undefined) delete process.env.KAOLA_FANOUT_CAP;
      else process.env.KAOLA_FANOUT_CAP = savedCap;
    }
  }
  // The <2 write-cap ceiling is an OPERATOR cap — ordinary serial, deliberately UNLABELED.
  {
    const savedCap = process.env.KAOLA_FANOUT_CAP;
    process.env.KAOLA_FANOUT_CAP = '1';
    try {
      const { r, psCalls } = runWith([{ exitCode: 0, result: 'ok' }]);
      assert(r.result === 'ok' && r.opened.length === 1 && !r.laneGroup, '#804-D3d: a cap of 1 degrades to serial');
      assert(r.serialDegradeReason === undefined,
        '#804-D3d: the operator cap degrade stays UNLABELED (ordinary serial, not a degrade cause), got ' + JSON.stringify(r.serialDegradeReason));
      assert(psCalls() === 1, '#804-D3d: a clean verdict never re-probes, got ' + psCalls());
    } finally {
      if (savedCap === undefined) delete process.env.KAOLA_FANOUT_CAP;
      else process.env.KAOLA_FANOUT_CAP = savedCap;
    }
  }
});

// ===========================================================================
// #805 R1 — THE ROUTABILITY GATE IS KEYED ON GATE FAILURE, NOT ON ONE ROLE'S OUTCOME TOKEN.
//
// The shipped guard read `gateMode === 'change_gate' && domainOutcome === 'changes_requested'`.
// `changes_requested` belongs to APPROVAL_OUTCOMES; an adversarial-verifier speaks
// ADVERSARIAL_OUTCOMES (refuted | not_refuted | indeterminate), so the second conjunct was
// UNSATISFIABLE for it and an AV change gate carrying a blocking, path-less finding sailed straight
// past the guard into the exact dead end #805 exists to close (`ownership_candidates: []`,
// `owning_node: null`; repair-node → repair_requires_replan, reopen-node → review_attempt_unresolved,
// re-record → evidence_generation_stale). The guard now reads the DERIVED gate effect, which is the
// one place (role, mode, outcome) is mapped to pass/fail/none — so it is role-agnostic by
// construction and an approval gate's behavior is byte-unchanged.
//
// These blocks drive the PRODUCTION CLI end to end. Block A must be RED before the fix (the AV close
// succeeds and commits a receipt + a settled journal attempt) and GREEN after.
// ===========================================================================
scenario(() => {
  const { spawnSync: spawn805 } = require('child_process');
  const NODE_CLI = path.join(__dirname, 'kaola-workflow-adaptive-node.js');
  const VALIDATOR_CLI = path.join(__dirname, 'kaola-workflow-plan-validator.js');
  const schema805r1 = require('./kaola-workflow-adaptive-schema');
  const baseEnv = Object.fromEntries(Object.entries(process.env).filter(([k]) => !k.startsWith('KAOLA_')));
  const env805 = { ...baseEnv, GIT_CONFIG_GLOBAL: '/dev/null', GIT_CONFIG_NOSYSTEM: '1',
    KAOLA_WORKFLOW_OFFLINE: '1' };
  const lastJson = result => {
    const line = String(result.stdout || '').trim().split('\n').filter(row => row.trim().startsWith('{')).pop();
    return line ? JSON.parse(line) : null;
  };
  const tmp805 = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'kw-805r1-')));
  // The per-scenario vehicle for the adaptive-node CLI. Every scenario drives it as a CHAIN:
  // one process writes the ledger row, the barrier baseline and the .cache evidence and EXITS,
  // and the next re-derives the whole run state from those bytes with no shared heap.
  // spawn-class: durable-handoff
  const run805 = (args, input) => spawn805(process.execPath, [NODE_CLI, ...args],
    { cwd: tmp805, encoding: 'utf8', env: env805, input, timeout: 120000 });
  try {
    G.git(tmp805, ['init', '-b', 'main'], { encoding: 'utf8', env: env805 });
    G.git(tmp805, ['config', 'user.email', 'kw@test'], { encoding: 'utf8', env: env805 });
    G.git(tmp805, ['config', 'user.name', 'kw'], { encoding: 'utf8', env: env805 });

    // One frozen schema-2 project per scenario, all in one repo: a serial writer certified by a
    // SEQUENCE adversarial-verifier CHANGE gate (it `certifies` the writer, which is what makes
    // deriveGateMode resolve change_gate), then the code certifier and the sink.
    const setup = (project) => {
      const projectDir = path.join(tmp805, 'kaola-workflow', project);
      const cacheDir = path.join(projectDir, '.cache');
      fs.mkdirSync(cacheDir, { recursive: true });
      const implRel = project + '-impl.js';
      fs.writeFileSync(path.join(tmp805, implRel), 'module.exports = 0;\n');
      const planPath = path.join(projectDir, 'workflow-plan.md');
      fs.writeFileSync(planPath, [
        '# Workflow Plan — ' + project, '',
        '## Meta', 'plan_form: spine', 'plan_schema_version: 2', 'labels: enhancement',
        'code_certifier: codegate', 'security_certifier: none',
        'inherited_frontier_digest: none', 'inherited_frontier_classes: none',
        'validation_command: node --check ' + implRel, 'validation_timeout_minutes: 5', '',
        '## Nodes', '',
        '| id | role | depends_on | declared_write_set | cardinality | shape | gate_claim | gate_surface | gate_aggregation | certifies |',
        '|---|---|---|---|---|---|---|---|---|---|',
        '| writer | tdd-guide | — | ' + implRel + ' | 1 | sequence | — | — | — | — |',
        '| av-a | adversarial-verifier | writer | — | 1 | sequence | change is sound | code-tree | sequence | writer |',
        '| codegate | code-reviewer | av-a | — | 1 | sequence | review-change | code-tree | sequence | — |',
        '| finalize | finalize | codegate | — | 1 | sequence | — | — | — | — |', '',
        '## Design', '',
        'Decompose: writer builds the impl; av-a falsifies it as a change gate; codegate post-dominates; '
          + 'finalize sinks. sequence edges are gate/data dependencies (S1). Done: gates clear and validation passes.', '',
        '## Acceptance', '',
        'A1: the implementation file is produced and passes the recorded validation command.',
        'A2: the adversarial change gate and the code gate both clear over the produced tree.', '',
        '## Node Ledger', '', '| id | status |', '|---|---|',
        '| writer | pending |', '| av-a | pending |', '| codegate | pending |', '| finalize | pending |', '',
        '## Required Agent Compliance', '',
        '| Requirement | Status | Evidence | Skip Reason |', '|---|---|---|---|',
        '| tdd-guide (writer) | pending | | |', '| adversarial-verifier (av-a) | pending | | |',
        '| code-reviewer (codegate) | pending | | |', '| finalize (finalize) | pending | | |', '',
      ].join('\n'));
      fs.writeFileSync(path.join(projectDir, 'workflow-state.md'), '# Workflow State\nstatus: active\n');
      // --freeze stamps plan_hash into workflow-plan.md and EXITS; every adaptive-node process in
      // this scenario then re-reads and re-verifies that stamp from disk.
      // spawn-class: durable-handoff
      const freeze = spawn805(process.execPath, [VALIDATOR_CLI, planPath, '--freeze', '--json'],
        { cwd: tmp805, encoding: 'utf8', env: env805 });
      assert(freeze.status === 0 && lastJson(freeze) && lastJson(freeze).frozen === true,
        '#805-R1 fixture: the AV change-gate plan freezes: ' + freeze.stdout + freeze.stderr);
      G.git(tmp805, ['add', '-A'], { encoding: 'utf8', env: env805 });
      G.git(tmp805, ['commit', '-m', 'fixture ' + project], { encoding: 'utf8', env: env805 });
      return { project, projectDir, cacheDir, planPath, implRel };
    };

    // Drives the writer and returns the opened AV gate payload.
    const openGate = (fx) => {
      const opened = run805(['open-next', '--project', fx.project, '--json']);
      assert(opened.status === 0 && lastJson(opened) && lastJson(opened).nonce,
        '#805-R1 fixture: the writer opens: ' + opened.stdout + opened.stderr);
      fs.writeFileSync(path.join(tmp805, fx.implRel), 'module.exports = 1;\n');
      const rec = run805(['record-evidence', '--project', fx.project, '--node-id', 'writer', '--stdin', '--json'],
        'evidence-binding: writer ' + lastJson(opened).nonce + '\nRED: reproduced\nred_baseline: '
        + lastJson(opened).nonce + '\nGREEN: passes\n');
      assert(rec.status === 0, '#805-R1 fixture: writer evidence records: ' + rec.stdout + rec.stderr);
      const closed = run805(['close-and-open-next', '--project', fx.project, '--node-id', 'writer', '--json']);
      assert(closed.status === 0 && lastJson(closed) && lastJson(closed).opened
        && lastJson(closed).opened.id === 'av-a',
        '#805-R1 fixture: the AV change gate opens off the writer close: ' + closed.stdout + closed.stderr);
      return lastJson(closed).opened;
    };

    const gateEvidence = (opened, domainOutcome, extraRows) => [
      'evidence-binding: av-a ' + opened.nonce,
      'contract_version: 2',
      'review_context_hash: ' + opened.dispatch.review_context_hash,
      'behavior_contract_hash: ' + opened.dispatch.behavior_contract_hash,
      'resolved_profile_hash: ' + opened.dispatch.resolved_profile_hash,
      'candidate_digest: ' + opened.dispatch.candidate_digest,
      'domain_outcome: ' + domainOutcome,
      'claim_outcome: ' + domainOutcome,
      'gate_mode: change_gate',
      'gate_claim: change is sound',
      'gate_surface: code-tree',
      'gate_aggregation: sequence',
      ...(extraRows || []), '',
    ].join('\n');

    const anchorlessFinding = (cacheDir, key) => ({
      failure_class: 'correctness',
      trigger: { precondition_digest: '1'.repeat(64), input_digest: '2'.repeat(64),
        expected_digest: '3'.repeat(64), observed_digest: '4'.repeat(64) },
      primary_anchor: { kind: 'evidence_observation',
        producer_evidence_digest: schema805r1.sha256Hex(fs.readFileSync(path.join(cacheDir, 'writer.md'), 'utf8')),
        observation_key: key },
      secondary_anchors: [], severity: 'high', scope: 'in_scope', action: 'fix',
      status: 'open', fix_role: 'tdd-guide', proof_digest: '6'.repeat(64),
    });

    const journalOf = fx => {
      const file = path.join(fx.cacheDir, 'review-attempts.json');
      return fs.existsSync(file) ? JSON.parse(fs.readFileSync(file, 'utf8')) : { attempts: [] };
    };

    // -- Block A (THE DEFECT) — `refuted` is a gate FAILURE and must be gated ------------------
    // RED at the old predicate: `refuted` is not `changes_requested`, so the guard never fired, the
    // close SUCCEEDED (result review_failed), and a receipt + a settled, unrepairable attempt landed.
    for (const outcome of ['refuted', 'indeterminate']) {
      const fx = setup('issue-805r1-' + outcome);
      const opened = openGate(fx);
      const rec = run805(['record-evidence', '--project', fx.project, '--node-id', 'av-a', '--stdin', '--json'],
        gateEvidence(opened, outcome,
          ['finding_json: ' + JSON.stringify(anchorlessFinding(fx.cacheDir, 'writer:805r1-' + outcome))]));
      assert(rec.status === 0,
        '#805-R1A: record-evidence stays a verbatim transport for the unroutable bytes: ' + rec.stdout + rec.stderr);
      const close = run805(['close-node', '--project', fx.project, '--node-id', 'av-a', '--json']);
      const payload = lastJson(close) || {};
      assert(close.status !== 0 && payload.reason === 'review_finding_anchor_unroutable',
        '#805-R1A: an adversarial-verifier CHANGE gate settling ' + outcome + ' on a BLOCKING finding '
        + 'whose primary anchor carries no path must refuse review_finding_anchor_unroutable — keying '
        + 'the guard on the APPROVAL token made it unsatisfiable for this role, got ' + JSON.stringify(payload));
      assert(JSON.stringify(payload.anchor_kinds) === JSON.stringify(['evidence_observation'])
        && Array.isArray(payload.routable_anchor_kinds)
        && !payload.routable_anchor_kinds.includes('evidence_observation'),
      '#805-R1A: the refusal names the offending kind and the routable set, got ' + JSON.stringify(payload));
      assert(typeof payload.operator_hint === 'string' && /re-anchor/i.test(payload.operator_hint)
        && !/requested changes/i.test(payload.operator_hint),
      '#805-R1A: the hint is worded off the derived gate FAILURE, not the approval vocabulary this '
        + 'role does not speak, got ' + JSON.stringify(payload.operator_hint));
      assert(!fs.existsSync(path.join(fx.cacheDir, 'review-receipts'))
        && !fs.existsSync(path.join(fx.cacheDir, 'review-attempts.json')),
      '#805-R1A: refused BEFORE any receipt or journal attempt exists, so the unrepairable-attempt '
        + 'cycle can never form (' + outcome + ')');
    }

    // -- Block B — the SAME gate is admitted once the blocking finding names a path ---------------
    // Also pins the population scoping: a NON-blocking (deferred) row may still anchor on
    // evidence_observation, exactly as the reviewer contract promises.
    {
      const fx = setup('issue-805r1-admitted');
      const opened = openGate(fx);
      const objectFormat = String(G.git(tmp805, ['rev-parse', '--show-object-format'], { encoding: 'utf8', env: env805 }).stdout).trim();
      const objectId = String(G.git(tmp805, ['hash-object', fx.implRel], { encoding: 'utf8', env: env805 }).stdout).trim();
      const implBytes = fs.readFileSync(path.join(tmp805, fx.implRel));
      const routable = { ...anchorlessFinding(fx.cacheDir, 'writer:805r1-unused'),
        primary_anchor: { kind: 'candidate_range', path: fx.implRel, object_format: objectFormat,
          tree_mode: '100644', object_id: objectId, start: 0, end: 1, blob_length: implBytes.length } };
      const deferred = { ...anchorlessFinding(fx.cacheDir, 'writer:805r1-observation'),
        severity: 'low', status: 'deferred' };
      const rec = run805(['record-evidence', '--project', fx.project, '--node-id', 'av-a', '--stdin', '--json'],
        gateEvidence(opened, 'refuted', ['finding_json: ' + JSON.stringify(routable),
          'finding_json: ' + JSON.stringify(deferred)]));
      assert(rec.status === 0, '#805-R1B: the mixed evidence records: ' + rec.stdout + rec.stderr);
      const close = run805(['close-node', '--project', fx.project, '--node-id', 'av-a', '--json']);
      const payload = lastJson(close) || {};
      assert(payload.result === 'review_failed',
        '#805-R1B: a refuted AV change gate whose BLOCKING finding names a path settles normally — the '
        + 'guard must narrow to the repair-responsible population, never to every open row, got '
        + JSON.stringify(payload));
      const attempt = journalOf(fx).attempts[0];
      assert(attempt && attempt.outcome === 'fail' && attempt.current_findings.length === 2,
        '#805-R1B: both rows persist on the settled attempt, got '
        + JSON.stringify(attempt && { o: attempt.outcome, n: attempt.current_findings.length }));
      assert(attempt.current_findings.some(f => f.primary_anchor.kind === 'evidence_observation'),
        '#805-R1B: evidence_observation stays LEGAL on a non-blocking row at a change gate — nothing '
        + 'was removed from the reviewer vocabulary, got '
        + JSON.stringify(attempt.current_findings.map(f => f.primary_anchor.kind)));
    }

    // -- Block C (R1.3) — the open-time stub states the anchor-kind rule to THIS reviewer too -----
    // The note used to ride on the `finding_json|findings_none` token class, and requiredReviewTokens
    // never asks an adversarial-verifier for one — so the single role whose change gate most naturally
    // anchors on producer evidence was the only role never shown the rule it would be judged by.
    {
      const fx = setup('issue-805r1-stub');
      const opened = openGate(fx);
      assert(!opened.required_tokens.some(t => String(t).startsWith('finding_json')),
        '#805-R1C PRECONDITION: an AV gate carries NO findings token class, got '
        + JSON.stringify(opened.required_tokens));
      const seeded = fs.readFileSync(path.join(fx.cacheDir, 'av-a.md'), 'utf8');
      assert(/PATH-BEARING primary_anchor\.kind/.test(seeded),
        '#805-R1C: the AV change-gate stub must state the routability rule it will be judged by, got:\n' + seeded);
      for (const kind of schema805r1.ROUTABLE_FINDING_ANCHOR_KINDS) {
        assert(seeded.includes(kind), '#805-R1C: the AV stub must name the routable kind "' + kind + '"');
      }
      assert(!/^finding_json:/m.test(seeded),
        '#805-R1C: stating the rule must NOT seed a findings token the AV contract does not require '
        + '(that would change required_tokens and the close-time shape check), got:\n' + seeded);
      // CONTROL — investigation mode produces no repair obligation, so the rule does not bind there
      // and printing it would be false guidance.
      const investigation = path.join(fx.cacheDir, 'investigation-probe.md');
      fs.rmSync(investigation, { force: true });
      seedEvidenceFile(fx.planPath, 'investigation-probe', 'abcdef123456', 'adversarial-verifier', false,
        { required_tokens: opened.required_tokens, review_gate: true, gate_mode: 'investigation' });
      assert(!/PATH-BEARING/.test(fs.readFileSync(investigation, 'utf8')),
        '#805-R1C CONTROL: an INVESTIGATION-mode gate carries no repair obligation, so it must not be '
        + 'told a change-gate routability rule');
    }
  } finally { fs.rmSync(tmp805, { recursive: true, force: true }); }
});

// substitute-role (#798) — the same-kind, superset-proven dispatch swap. Covers the happy path,
// the plan/plan_hash byte-identity claim (substitution is dispatch metadata, never plan mutation),
// idempotent replay across a crash between record and dispatch, the dispatch-card fold-in, and each
// of the five typed refusals.
scenario(() => {
  const { runSubstituteRole, activeRoleSubstitution, buildDispatch } = require('./kaola-workflow-adaptive-node');

  const makePlan = (role, status) => [
    '# Workflow Plan', '',
    '## Meta', 'plan_form: spine', 'plan_hash: deadbeefdeadbeef', '',
    '## Nodes', '',
    '| id | role | model | depends_on | shape | declared_write_set | cardinality |',
    '| --- | --- | --- | --- | --- | --- | --- |',
    '| n1 | ' + role + ' | standard | — | sequence | — | 1 |',
    '| n2 | code-reviewer | standard | n1 | sequence | — | 1 |',
    '| sink | finalize | — | n2 | sequence | — | 1 |', '',
    '## Node Ledger', '', '| id | status |', '| --- | --- |',
    '| n1 | ' + status + ' |', '| n2 | pending |', '| sink | pending |', '',
  ].join('\n');

  const fixture = (role, status, evidence) => {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-subrole-'));
    const proj = path.join(dir, 'kaola-workflow', 'p1');
    fs.mkdirSync(path.join(proj, '.cache'), { recursive: true });
    const planPath = path.join(proj, 'workflow-plan.md');
    fs.writeFileSync(planPath, makePlan(role || 'code-explorer', status || 'pending'), 'utf8');
    if (evidence != null) fs.writeFileSync(path.join(proj, '.cache', 'n1.md'), evidence, 'utf8');
    return { proj, planPath };
  };

  // Happy path: code-explorer -> investigator is a proven superset, same kind, same token contract.
  {
    const f = fixture();
    const before = fs.readFileSync(f.planPath, 'utf8');
    const r = runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1');
    assert(r.result === 'ok' && r.from_role === 'code-explorer' && r.to_role === 'investigator',
      '#798: code-explorer -> investigator must substitute, got ' + JSON.stringify(r));
    assert(fs.readFileSync(f.planPath, 'utf8') === before,
      '#798: the frozen plan (and its plan_hash) must stay BYTE-IDENTICAL after a substitution');
    const store = JSON.parse(fs.readFileSync(path.join(f.proj, '.cache', 'role-substitutions.json'), 'utf8'));
    assert(store.substitutions.length === 1, '#798: exactly one durable record, got ' + store.substitutions.length);
    assert(activeRoleSubstitution(path.join(f.proj, '.cache'), p => fs.readFileSync(p, 'utf8'), 'n1').to_role === 'investigator',
      '#798: the record must read back as the active substitution');

    // Crash between record and dispatch ⇒ re-running the identical command is a no-op.
    const again = runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1');
    assert(again.result === 'ok' && again.idempotent === true, '#798: replay must be idempotent, got ' + JSON.stringify(again));
    const store2 = JSON.parse(fs.readFileSync(path.join(f.proj, '.cache', 'role-substitutions.json'), 'utf8'));
    assert(store2.substitutions.length === 1, '#798: replay must not append a second record');

    const d = buildDispatch({ id: 'n1', role: 'code-explorer', model: 'standard', declared_write_set: '—' },
      { planPath: f.planPath, evidence_file: '.cache/n1.md', nonce: 'abc123' });
    assert(d.agent_type === 'investigator', '#798: card agent_type must be the SUBSTITUTE, got ' + d.agent_type);
    assert(d.agent_type_frozen === 'code-explorer', '#798: card must state the frozen role, got ' + d.agent_type_frozen);
    assert(d.role_substituted === true, '#798: card must flag the substitution');
    assert(typeof d.role_substitution_basis === 'string' && d.role_substitution_basis.length > 0,
      '#798: card must carry the substitution basis');
  }

  // No record on file ⇒ the dispatch card is byte-identical to a pre-substitution card.
  {
    const f = fixture();
    const d = buildDispatch({ id: 'n1', role: 'code-explorer', model: 'standard', declared_write_set: '—' },
      { planPath: f.planPath, evidence_file: '.cache/n1.md', nonce: 'abc123' });
    assert(d.agent_type === 'code-explorer' && !('agent_type_frozen' in d) && !('role_substituted' in d),
      '#798: an unsubstituted card must gain NO substitution keys, got ' + JSON.stringify(Object.keys(d)));
  }

  // The five typed refusals.
  {
    const f = fixture();
    const r = runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'no-such-role' }, 'p1');
    assert(r.result === 'refuse' && r.reason === 'substitute_unknown_role', '#798: unknown target must refuse, got ' + JSON.stringify(r));
    assert(!fs.existsSync(path.join(f.proj, '.cache', 'role-substitutions.json')), '#798: a refusal must write NO record');
  }
  {
    const f = fixture();
    const r = runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'code-reviewer' }, 'p1');
    assert(r.result === 'refuse' && r.reason === 'substitute_kind_mismatch',
      '#798: producer -> gate must refuse kind_mismatch, got ' + JSON.stringify(r));
  }
  {
    const f = fixture('investigator');
    const r = runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'code-explorer' }, 'p1');
    assert(r.result === 'refuse' && r.reason === 'substitute_not_superset' && (r.missing_tools || []).includes('Bash'),
      '#798: dropping Bash must refuse not_superset naming the tool, got ' + JSON.stringify(r));
  }
  {
    const f = fixture();
    const r = runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'code-architect' }, 'p1');
    assert(r.result === 'refuse' && r.reason === 'substitute_token_contract_mismatch',
      '#798: differing evidence contracts must refuse, got ' + JSON.stringify(r));
  }
  {
    const f = fixture('code-explorer', 'complete');
    const r = runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1');
    assert(r.result === 'refuse' && r.reason === 'substitute_node_closed',
      '#798: a complete row must refuse node_closed, got ' + JSON.stringify(r));
  }
  {
    const f = fixture('code-explorer', 'in_progress', 'evidence-binding: n1 abc123\nfindings: already delivered\n');
    const r = runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1');
    assert(r.result === 'refuse' && r.reason === 'substitute_node_closed',
      '#798: a recorded deliverable must refuse node_closed, got ' + JSON.stringify(r));
  }
  // A SEEDED-but-valueless evidence file is not a deliverable and must stay substitutable.
  // NOTE: this hand-written two-line shape is NOT what `seedEvidenceFile` emits — the real opener
  // seed carries an `<!-- token: paste token here -->` comment line per stub token. The
  // production-seed variant of this same claim lives in the #819 block below, driven by the shipped
  // seeder rather than by a fixture that flatters the guard.
  {
    const f = fixture('code-explorer', 'in_progress', 'evidence-binding: n1 abc123\nfindings:\n');
    const before = fs.readFileSync(path.join(f.proj, '.cache', 'n1.md'), 'utf8');
    const r = runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1');
    assert(r.result === 'ok', '#798: a seed-only evidence file must remain substitutable, got ' + JSON.stringify(r));
    assert(r.evidence_reset === false,
      '#819-T3: an untouched seed carries nothing to destroy, so the ok return must say so explicitly '
      + '(evidence_reset:false) rather than leave the reset state unstated, got ' + JSON.stringify(r.evidence_reset));
    assert(fs.readFileSync(path.join(f.proj, '.cache', 'n1.md'), 'utf8') === before,
      '#819-T3: a swap that resets nothing must leave the evidence bytes BYTE-IDENTICAL');
  }
});

// ---------------------------------------------------------------------------
// #819 — capability_gap recovery. Three seams the recovery path must clear, and one guard that must
// survive it:
//   (a) a returning role that self-persisted a gap must not wedge the swap behind P5 — while a role
//       that delivered real work still must, or the change is indistinguishable from deleting P5;
//   (b) a substituted node must present a FRESH dispatch identity, stable across an idempotent replay;
//   (c) a swap to the role already frozen is a no-op that must never be recorded.
// Fixture helpers are lifted to file scope because several scenarios below share them; each scenario
// still owns and removes its own temp dirs.
// ---------------------------------------------------------------------------

// The barrier baseline a reset resolves its nonce from. `readNonce` takes the first 12 characters of
// `.cache/barrier-base-<node>`, so the evidence binding below and this file agree by construction.
const SUBROLE_SHA = 'abc123abc123deadbeefcafe0123456789abcdef';
const SUBROLE_NONCE = SUBROLE_SHA.slice(0, 12);

// The REFERENCE gap body: the bytes a real gapping role wrote, not an idealised marker. Its typed
// marker is the column-0 `delegation_outcome: capability_gap` line the role emitted unprompted; the
// only `capability_gap` PHRASE sits indented inside another token's value, and every content-bearing
// token value is empty. A classifier keyed on a column-0 `capability_gap:` key alone does not fire here.
const SUBROLE_GAP_BODY = [
  'evidence-binding: n1 ' + SUBROLE_NONCE,
  'findings:',
  '  outcome: "capability_gap: local text-file read capability -- the dispatch forbids executing commands"',
  '  facts:',
  '    - "AGENTS.md requires CLAUDE.md to be read in full before repository action."',
  '  validation_commands: []',
  'delegation_outcome: capability_gap',
  '<!-- findings: paste findings here -->',
  'findings: ',
  '',
].join('\n');

// The other typed marker: the column-0 key every role profile mandates as the compact summary return.
const SUBROLE_GAP_BODY_KEYED = 'evidence-binding: n1 ' + SUBROLE_NONCE
  + '\ncapability_gap: shell execution -- required to run the repository test suite\n';

// The same reference body with its column-0 marker removed, so the ONLY `capability_gap` occurrence
// left is the indented one inside a value. Prose, not a marker.
const SUBROLE_GAP_BODY_INDENTED_ONLY = SUBROLE_GAP_BODY.replace('delegation_outcome: capability_gap\n', '');

const SUBROLE_DELIVERABLE_BODY = 'evidence-binding: n1 ' + SUBROLE_NONCE + '\nfindings: already delivered\n';

// The forgery: a real deliverable with the gap marker stamped on top. Relabeling work must not launder it.
const SUBROLE_FORGED_BODY = [
  'evidence-binding: n1 ' + SUBROLE_NONCE,
  'findings: the frozen role delivered a full inventory of both seams and every pin standing on them',
  'delegation_outcome: capability_gap',
  '',
].join('\n');

function subrolePlan(role, status) {
  return [
    '# Workflow Plan', '',
    '## Meta', 'plan_form: spine', 'plan_hash: deadbeefdeadbeef', '',
    '## Nodes', '',
    '| id | role | model | depends_on | shape | declared_write_set | cardinality |',
    '| --- | --- | --- | --- | --- | --- | --- |',
    '| n1 | ' + role + ' | standard | — | sequence | — | 1 |',
    '| n2 | code-reviewer | standard | n1 | sequence | — | 1 |',
    '| sink | finalize | — | n2 | sequence | — | 1 |', '',
    '## Node Ledger', '', '| id | status |', '| --- | --- |',
    '| n1 | ' + status + ' |', '| n2 | pending |', '| sink | pending |', '',
  ].join('\n');
}

// opts: { role, status, evidence, baseline:false }. The barrier baseline is written by DEFAULT — the
// existing #798 fixture writes none, so `readNonce` returns null there and any reset would refuse for
// the wrong reason.
function subroleFixture(opts) {
  const o = opts || {};
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-819-'));
  const proj = path.join(dir, 'kaola-workflow', 'p1');
  const cache = path.join(proj, '.cache');
  fs.mkdirSync(cache, { recursive: true });
  const planPath = path.join(proj, 'workflow-plan.md');
  fs.writeFileSync(planPath, subrolePlan(o.role || 'code-explorer', o.status || 'in_progress'), 'utf8');
  if (o.baseline !== false) fs.writeFileSync(path.join(cache, 'barrier-base-n1'), SUBROLE_SHA + '\n', 'utf8');
  if (o.evidence != null) fs.writeFileSync(path.join(cache, 'n1.md'), o.evidence, 'utf8');
  const evidencePath = path.join(cache, 'n1.md');
  const storePath = path.join(cache, 'role-substitutions.json');
  return {
    dir, proj, cache, planPath, evidencePath, storePath,
    read: () => (fs.existsSync(evidencePath) ? fs.readFileSync(evidencePath, 'utf8') : null),
    rows: () => (fs.existsSync(storePath)
      ? (JSON.parse(fs.readFileSync(storePath, 'utf8')).substitutions || []) : null),
  };
}

// A RED-by-design assertion must FAIL, never THROW. shardLib.runScenario does not catch, so an
// exception out of a not-yet-existing export would abort the whole process and hide every other
// signal this suite is supposed to hand the implementer.
function subroleCall(label, fn) {
  try {
    const value = fn();
    return (value && typeof value === 'object') ? value : { __value: value };
  } catch (e) {
    assert(false, label + ' threw instead of returning: ' + String((e && e.message) || e));
    return {};
  }
}

// #819-T1/T3b/T8/T9/T12 — the recovery path: a gap body resets and swaps, the opener's own seed is
// left alone, both crash windows resume, and an unresolvable reset refuses rather than improvising.
scenario(() => {
  const { runSubstituteRole, seedEvidenceFile } = require('./kaola-workflow-adaptive-node');
  const dirs = [];
  try {
    // T1 — the recovery this whole issue exists for.
    {
      const f = subroleFixture({ evidence: SUBROLE_GAP_BODY });
      dirs.push(f.dir);
      const line1Before = f.read().split('\n')[0];
      const r = subroleCall('#819-T1 substitute-role on a gap body',
        () => runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1'));
      assert(r.result === 'ok',
        '#819-T1: a self-persisted capability_gap body is exactly the state substitution exists to '
        + 'serve and must NOT wedge the swap, got ' + JSON.stringify(r));
      assert(r.evidence_reset === true,
        '#819-T1: the ok return must report evidence_reset:true so a destroyed body is on the record, '
        + 'got ' + JSON.stringify(r.evidence_reset));
      assert(r.idempotent === false, '#819-T1: a first swap is not a replay, got ' + JSON.stringify(r.idempotent));
      const rows = f.rows();
      assert(rows && rows.length === 1 && rows[0].to_role === 'investigator',
        '#819-T1: exactly one active record naming the target, got ' + JSON.stringify(rows));
      const after = f.read();
      // The post-condition: the evidence file is at its binding-PRESERVING seeded state, reached with
      // no hand intervention. Line 1 preserved is the load-bearing half (see T13).
      assert(after != null && after.split('\n')[0] === line1Before,
        '#819-T1: line 1 must be BYTE-IDENTICAL across the reset — the nonce IS the barrier baseline '
        + 'prefix, so rotating it re-snapshots the worktree mid-node; got ' + JSON.stringify(after && after.split('\n')[0]));
      // Expected bytes are computed by the SHIPPED seeder, not transcribed, so this cannot drift.
      const g = subroleFixture({}); dirs.push(g.dir);
      seedEvidenceFile(g.planPath, 'n1', SUBROLE_NONCE, 'investigator', false, null);
      assert(after === g.read(),
        '#819-T1: the file must be re-seeded to a FRESH seed for the dispatch target at the same nonce.\n'
        + 'got:      ' + JSON.stringify(after) + '\nexpected: ' + JSON.stringify(g.read()));
      assert(!/capability_gap/.test(String(after)),
        '#819-T1: no trace of the gap body may survive the reset, got:\n' + after);
    }

    // T3b — the DE-VACUUMED seed-only case. The #798 block's two-line fixture is a shape
    // `seedEvidenceFile` never emits: the real opener seed carries an `<!-- token: paste … -->`
    // comment line per stub token, and `hasEvidenceBodyBelowHeader` counts any non-token line as a
    // body. So the opener's OWN scaffold refuses the swap — on a node that has merely been OPENED,
    // with no dispatch and no gap. This is the case a role hits when it gaps and (as its profile and
    // the routing prose both instruct) writes NOTHING to the evidence file, which is the compliant
    // path, so recovery is unreachable unless the scaffold is recognised as the seed it is.
    {
      const f = subroleFixture({}); dirs.push(f.dir);
      seedEvidenceFile(f.planPath, 'n1', SUBROLE_NONCE, 'code-explorer', false, null);
      const before = f.read();
      assert(/^<!-- findings: paste findings here -->$/m.test(String(before)),
        '#819-T3b: the fixture must be the REAL opener seed (comment scaffold), got:\n' + before);
      const r = subroleCall('#819-T3b substitute-role on the production seed',
        () => runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1'));
      assert(r.result === 'ok',
        '#819-T3b: the opener\'s OWN seed scaffold is not a deliverable — a node that has merely been '
        + 'opened must stay substitutable, got ' + JSON.stringify(r));
      assert(r.evidence_reset === false,
        '#819-T3b: an untouched seed carries nothing to destroy, got ' + JSON.stringify(r.evidence_reset));
      assert(f.read() === before, '#819-T3b: and its bytes must be left alone');
    }

    // T8 — crash window {seeded body, record}: re-running the IDENTICAL command is a no-op.
    {
      const f = subroleFixture({ evidence: SUBROLE_GAP_BODY }); dirs.push(f.dir);
      subroleCall('#819-T8 first swap',
        () => runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1'));
      const afterFirst = f.read();
      const again = subroleCall('#819-T8 replay',
        () => runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1'));
      assert(again.result === 'ok' && again.idempotent === true,
        '#819-T8: the replay must be idempotent, got ' + JSON.stringify(again));
      assert(again.evidence_reset === false,
        '#819-T8: a replay re-classifies the re-seeded body as seeded and must NOT reset a second '
        + 'time, got ' + JSON.stringify(again.evidence_reset));
      assert((f.rows() || []).length === 1, '#819-T8: a replay must not append a second record');
      assert(f.read() === afterFirst, '#819-T8: a replay must leave the evidence bytes untouched');
    }

    // T8-w1 — crash window {seeded body, NO record}: the reset landed, the record did not. Re-running
    // the identical command completes it. No hand patch is reachable anywhere in the path.
    {
      const f = subroleFixture({ evidence: SUBROLE_GAP_BODY }); dirs.push(f.dir);
      subroleCall('#819-T8-w1 first swap',
        () => runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1'));
      const afterReset = f.read();
      fs.rmSync(f.storePath, { force: true });
      const resumed = subroleCall('#819-T8-w1 resume',
        () => runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1'));
      assert(resumed.result === 'ok' && resumed.evidence_reset === false,
        '#819-T8-w1: the re-seeded body re-classifies as seeded, so the resume records without a '
        + 'second reset, got ' + JSON.stringify(resumed));
      assert((f.rows() || []).length === 1, '#819-T8-w1: the resume must leave exactly one record');
      assert(f.read() === afterReset, '#819-T8-w1: the resume must not touch the evidence bytes again');
    }

    // T9 — a gap body with no resolvable baseline nonce refuses; it never falls back to an empty nonce.
    {
      const f = subroleFixture({ evidence: SUBROLE_GAP_BODY, baseline: false }); dirs.push(f.dir);
      const before = f.read();
      const r = subroleCall('#819-T9 substitute with no barrier baseline',
        () => runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1'));
      assert(r.result === 'refuse' && r.reason === 'substitute_evidence_reset_failed',
        '#819-T9: no resolvable binding nonce must refuse rather than re-seed at an empty binding '
        + '(which the close gate can only refuse), got ' + JSON.stringify(r));
      assert(f.read() === before, '#819-T9: a refused reset must leave the evidence bytes intact');
      assert(f.rows() === null, '#819-T9: a refused reset must write NO record');
    }

    // T12 — the ledger arm is untouched and still runs FIRST: a complete row refuses regardless of body.
    {
      const f = subroleFixture({ status: 'complete', evidence: SUBROLE_GAP_BODY }); dirs.push(f.dir);
      const before = f.read();
      const r = subroleCall('#819-T12 complete row with a gap body',
        () => runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1'));
      assert(r.result === 'refuse' && r.reason === 'substitute_node_closed' && r.status === 'complete',
        '#819-T12: a complete row must still refuse node_closed even with a gap body, got ' + JSON.stringify(r));
      assert(/node status is "complete"/.test(String(r.detail || '')),
        '#819-T12: the LEDGER-STATUS arm must be the one that decided — its detail proves P5a still '
        + 'runs before the body classification, got ' + JSON.stringify(r.detail));
      assert(f.read() === before, '#819-T12: nothing may be reset on a closed row');
      assert(f.rows() === null, '#819-T12: nothing may be recorded on a closed row');
    }

    // T12b — the ORDERING pin. A complete row carrying a DELIVERABLE is refusable by either arm, so
    // only the `detail` says which one decided. On a gap body both orderings still refuse, which is
    // why that case alone cannot pin the sequence.
    {
      const f = subroleFixture({ status: 'complete', evidence: SUBROLE_DELIVERABLE_BODY }); dirs.push(f.dir);
      const r = subroleCall('#819-T12b ordering',
        () => runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1'));
      assert(r.result === 'refuse' && r.reason === 'substitute_node_closed', '#819-T12b: must refuse, got '
        + JSON.stringify(r));
      assert(/node status is "complete"/.test(String(r.detail || '')),
        '#819-T12b: the LEDGER arm must decide first — a detail naming the evidence body instead proves '
        + 'the body classification was hoisted above the status check, got ' + JSON.stringify(r.detail));
    }
  } finally {
    for (const d of dirs) fs.rmSync(d, { recursive: true, force: true });
  }
});

// #819-T2/T2b/T2c/T10 — the CONTROL half. Without these the change is indistinguishable from
// deleting P5, and every refusal must stay a byte-for-byte no-op on disk.
scenario(() => {
  const { runSubstituteRole } = require('./kaola-workflow-adaptive-node');
  const dirs = [];
  try {
    // T2 — a genuine deliverable still refuses.
    {
      const f = subroleFixture({ evidence: SUBROLE_DELIVERABLE_BODY }); dirs.push(f.dir);
      const before = f.read();
      const r = subroleCall('#819-T2 deliverable',
        () => runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1'));
      assert(r.result === 'refuse' && r.reason === 'substitute_node_closed',
        '#819-T2: a recorded deliverable must still refuse node_closed, got ' + JSON.stringify(r));
      assert(f.read() === before, '#819-T2: a refused swap must not touch the deliverable');
      assert(f.rows() === null, '#819-T2: a refused swap must write NO record');
    }

    // T2b — the FORGERY control. Stamping the gap marker onto real work must not launder it: a body
    // is a gap only when it ALSO withholds every content-bearing token value its contract demands.
    {
      const f = subroleFixture({ evidence: SUBROLE_FORGED_BODY }); dirs.push(f.dir);
      const before = f.read();
      const r = subroleCall('#819-T2b forged marker over real findings',
        () => runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1'));
      assert(r.result === 'refuse' && r.reason === 'substitute_node_closed',
        '#819-T2b: a typed gap marker over a NON-EMPTY required token is a deliverable, not a gap — '
        + 'a returning role must not be able to relabel its own work into a reset, got ' + JSON.stringify(r));
      assert(f.read() === before, '#819-T2b: the forged body must survive byte-for-byte');
    }

    // T2c — the ANCHORING control. The sole `capability_gap` occurrence sits indented inside another
    // token's value: that is prose, not a marker, and the body degrades to today's refusal. Deliberately
    // fail-closed — an unanchored substring search would admit it and reset a body nobody typed a
    // marker for. Every required token value here is EMPTY, which is what makes the anchoring the only
    // thing standing between this body and an `ok`.
    {
      const f = subroleFixture({ evidence: SUBROLE_GAP_BODY_INDENTED_ONLY }); dirs.push(f.dir);
      const before = f.read();
      assert(!/^capability_gap:/m.test(String(before)) && !/^delegation_outcome:/m.test(String(before))
        && /capability_gap/.test(String(before)),
        '#819-T2c: the fixture must carry the phrase ONLY inside an indented value, got:\n' + before);
      const r = subroleCall('#819-T2c indented-only marker',
        () => runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1'));
      assert(r.result === 'refuse' && r.reason === 'substitute_node_closed',
        '#819-T2c: a marker must be COLUMN-0 anchored like every other token key; an occurrence '
        + 'nested in another token\'s value is prose, got ' + JSON.stringify(r));
      assert(f.read() === before, '#819-T2c: a refused swap must not reset');
      assert(f.rows() === null, '#819-T2c: a refused swap must write NO record');
    }

    // T10 — EVERY guard is pure: a refused call is a byte-for-byte no-op on disk. Each row below
    // carries a real barrier baseline AND (except P5b, whose whole point is a deliverable) a gap body,
    // so a reset hoisted above the guard block would fire and this table would catch it.
    {
      const guards = [
        { label: 'P0 self-substitution', role: 'code-explorer', status: 'in_progress', body: SUBROLE_GAP_BODY, to: 'code-explorer', reason: 'substitute_self_noop' },
        { label: 'P1 unknown target', role: 'code-explorer', status: 'in_progress', body: SUBROLE_GAP_BODY, to: 'no-such-role', reason: 'substitute_unknown_role' },
        { label: 'P2 kind mismatch', role: 'code-explorer', status: 'in_progress', body: SUBROLE_GAP_BODY, to: 'code-reviewer', reason: 'substitute_kind_mismatch' },
        { label: 'P3 not a superset', role: 'investigator', status: 'in_progress', body: SUBROLE_GAP_BODY, to: 'code-explorer', reason: 'substitute_not_superset' },
        { label: 'P4 token contract', role: 'code-explorer', status: 'in_progress', body: SUBROLE_GAP_BODY, to: 'code-architect', reason: 'substitute_token_contract_mismatch' },
        { label: 'P5a ledger closed', role: 'code-explorer', status: 'complete', body: SUBROLE_GAP_BODY, to: 'investigator', reason: 'substitute_node_closed' },
        { label: 'P5b deliverable', role: 'code-explorer', status: 'in_progress', body: SUBROLE_DELIVERABLE_BODY, to: 'investigator', reason: 'substitute_node_closed' },
      ];
      for (const g of guards) {
        const f = subroleFixture({ role: g.role, status: g.status, evidence: g.body }); dirs.push(f.dir);
        const before = f.read();
        const planBefore = fs.readFileSync(f.planPath, 'utf8');
        const r = subroleCall('#819-T10 ' + g.label,
          () => runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: g.to }, 'p1'));
        assert(r.result === 'refuse' && r.reason === g.reason,
          '#819-T10 ' + g.label + ': must refuse ' + g.reason + ', got ' + JSON.stringify(r));
        assert(f.read() === before,
          '#819-T10 ' + g.label + ': a refusal must leave the evidence file BYTE-IDENTICAL — every '
          + 'side effect belongs in the commit phase, after the last guard');
        assert(f.rows() === null,
          '#819-T10 ' + g.label + ': a refusal must write NO substitutions file');
        assert(fs.readFileSync(f.planPath, 'utf8') === planBefore,
          '#819-T10 ' + g.label + ': the frozen plan must stay BYTE-IDENTICAL');
      }
    }
  } finally {
    for (const d of dirs) fs.rmSync(d, { recursive: true, force: true });
  }
});

// #819-T4/T5/T6/T11 — the dispatch identity. A substituted node must present an identity the runtime
// has not already consumed; an unsubstituted one must present exactly today's card.
scenario(() => {
  const { runSubstituteRole, buildDispatch, codexTaskNameForNode, sanitizeCodexTaskName } =
    require('./kaola-workflow-adaptive-node');
  const { ROLE_CAPABILITY_MANIFEST } = require('./kaola-workflow-adaptive-schema');
  const dirs = [];
  const nodeInfo = { id: 'n1', role: 'code-explorer', model: 'standard', declared_write_set: '—' };
  try {
    // T4/T5 — distinct after a substitution, and stable across an idempotent replay. The fixture is a
    // PENDING node with no evidence file, so a failure here is attributable to the derivation alone
    // and never to P5.
    {
      const f = subroleFixture({ status: 'pending' }); dirs.push(f.dir);
      const ctx = { planPath: f.planPath, evidence_file: '.cache/n1.md', nonce: SUBROLE_NONCE };
      const pre = subroleCall('#819-T4 pre-substitution card', () => buildDispatch(nodeInfo, ctx));
      assert(pre.codex_task_name === 'n1_code_explorer',
        '#819-T4: with nothing on record the identity is the frozen one, got ' + JSON.stringify(pre.codex_task_name));

      const r = subroleCall('#819-T4 substitute',
        () => runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1'));
      assert(r.result === 'ok', '#819-T4: fixture precondition — the swap must succeed, got ' + JSON.stringify(r));

      const post = subroleCall('#819-T4 post-substitution card', () => buildDispatch(nodeInfo, ctx));
      assert(post.agent_type === 'investigator',
        '#819-T4: the card must dispatch the SUBSTITUTE, got ' + JSON.stringify(post.agent_type));
      assert(post.agent_type_frozen === 'code-explorer',
        '#819-T4: the card must still state what the plan froze, got ' + JSON.stringify(post.agent_type_frozen));
      assert(post.codex_task_name === 'n1_investigator',
        '#819-T4: the task identity must be derived from the DISPATCH TARGET (the card\'s agent_type), '
        + 'not the plan\'s frozen role cell, got ' + JSON.stringify(post.codex_task_name));
      assert(post.codex_task_name !== pre.codex_task_name,
        '#819-T4: a substituted node must present a FRESH identity — re-presenting the one the runtime '
        + 'already consumed is the failure that wedged the recovery');

      const again = subroleCall('#819-T5 replay',
        () => runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1'));
      assert(again.result === 'ok' && again.idempotent === true,
        '#819-T5: the replay must be idempotent, got ' + JSON.stringify(again));
      assert((f.rows() || []).length === 1, '#819-T5: the replay must not append a second record');
      const post2 = subroleCall('#819-T5 post-replay card', () => buildDispatch(nodeInfo, ctx));
      assert(post2.codex_task_name === post.codex_task_name,
        '#819-T5: the identity is a pure function of (node id, active to_role) — a counter, timestamp, '
        + 'or record ts as an input would break crash-resume, got ' + JSON.stringify(post2.codex_task_name)
        + ' vs ' + JSON.stringify(post.codex_task_name));
    }

    // T4b — the derivation itself, without a fixture. The shipped library admits exactly ONE legal
    // substitution (code-explorer -> investigator), so a second target is only reachable here.
    {
      assert(codexTaskNameForNode({ id: 'n1-explore', role: 'code-explorer' }) === 'n1_explore_code_explorer',
        '#819-T4b: the one-argument call is unchanged, got '
        + JSON.stringify(codexTaskNameForNode({ id: 'n1-explore', role: 'code-explorer' })));
      const two = subroleCall('#819-T4b two-argument derivation',
        () => ({ v: codexTaskNameForNode({ id: 'n1-explore', role: 'code-explorer' }, 'investigator') }));
      assert(two.v === 'n1_explore_investigator',
        '#819-T4b: an explicit dispatch role must override the frozen cell, got ' + JSON.stringify(two.v));
      const wide = subroleCall('#819-T4b a wider target',
        () => ({ v: codexTaskNameForNode({ id: 'n1-explore', role: 'code-explorer' }, 'knowledge-lookup') }));
      assert(wide.v === 'n1_explore_knowledge_lookup',
        '#819-T4b: the derivation must follow ANY dispatch target, got ' + JSON.stringify(wide.v));
      for (const empty of [null, undefined, '']) {
        const back = subroleCall('#819-T4b fallback ' + JSON.stringify(empty),
          () => ({ v: codexTaskNameForNode({ id: 'n1-explore', role: 'code-explorer' }, empty) }));
        assert(back.v === 'n1_explore_code_explorer',
          '#819-T4b: an absent dispatch role must fall back to the frozen cell so every existing '
          + 'one-argument caller is byte-unchanged, got ' + JSON.stringify(back.v));
      }
    }

    // T6 — no record on file ⇒ the card is byte-identical to the pre-change golden. The key list is
    // the MEASURED baseline key set at this commit; an unconditionally attached key reds here.
    {
      const GOLDEN_DISPATCH_KEYS = [
        'agent_type', 'codex_dispatch_mode', 'codex_model', 'codex_model_source',
        'codex_profile_compatible', 'codex_profile_mode', 'codex_profile_tier',
        'codex_reasoning_effort', 'codex_reasoning_effort_source', 'codex_task_name',
        'declared_write_set', 'evidence_file', 'forge_rider', 'guards', 'model', 'model_display',
        'node_id', 'nonce', 'opencode_variant', 'opencode_variant_source', 'required_tokens',
        'role', 'wait_budget_minutes', 'wait_budget_source', 'working_dir',
      ];
      const f = subroleFixture({ status: 'pending' }); dirs.push(f.dir);
      const d = subroleCall('#819-T6 unsubstituted card', () => buildDispatch(nodeInfo,
        { planPath: f.planPath, evidence_file: '.cache/n1.md', nonce: SUBROLE_NONCE }));
      assert(d.agent_type === 'code-explorer' && d.role === 'code-explorer',
        '#819-T6: an unsubstituted card dispatches the frozen role, got ' + JSON.stringify(d.agent_type));
      assert(d.codex_task_name === 'n1_code_explorer',
        '#819-T6: the unsubstituted identity must be BYTE-IDENTICAL to today\'s — a suffix appended '
        + 'unconditionally would break the walkthrough pin that owns this derivation, got '
        + JSON.stringify(d.codex_task_name));
      assert(JSON.stringify(Object.keys(d).sort()) === JSON.stringify(GOLDEN_DISPATCH_KEYS),
        '#819-T6: the unsubstituted card must gain NO new key.\ngot:      '
        + JSON.stringify(Object.keys(d).sort()) + '\nexpected: ' + JSON.stringify(GOLDEN_DISPATCH_KEYS));
      for (const k of ['agent_type_frozen', 'role_substituted', 'role_substitution_basis', 'evidence_reset']) {
        assert(!(k in d), '#819-T6: an unsubstituted card must not carry "' + k + '"');
      }
    }

    // T11 — a STANDING invariant, not a #819 regression: the sanitizer must stay injective over the
    // installed library, or two roles would collapse to one task identity and the freshness T4 buys
    // would be silently undone. Its mutation is "add a colliding role name" — it guards a FUTURE
    // change, and it passes both before and after this issue's fix by design.
    {
      const roles = Object.keys(ROLE_CAPABILITY_MANIFEST);
      const names = roles.map(sanitizeCodexTaskName);
      assert(new Set(names).size === roles.length,
        '#819-T11: sanitizeCodexTaskName must be injective over ROLE_CAPABILITY_MANIFEST ('
        + roles.length + ' roles -> ' + new Set(names).size + ' distinct names)');
    }
  } finally {
    for (const d of dirs) fs.rmSync(d, { recursive: true, force: true });
  }
});

// #819-T7/T7b — a swap to the role already frozen is a no-op with a durable footprint: it records a
// row that means nothing and destroys the one property the dispatch identity depends on.
scenario(() => {
  const { runSubstituteRole, buildDispatch } = require('./kaola-workflow-adaptive-node');
  const dirs = [];
  try {
    // T7 — fresh, nothing on record.
    {
      const f = subroleFixture({ status: 'pending' }); dirs.push(f.dir);
      const r = subroleCall('#819-T7 self-substitution',
        () => runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'code-explorer' }, 'p1'));
      assert(r.result === 'refuse' && r.reason === 'substitute_self_noop',
        '#819-T7: a swap to the frozen role must refuse substitute_self_noop, got ' + JSON.stringify(r));
      assert(r.from_role === 'code-explorer' && r.to_role === 'code-explorer',
        '#819-T7: the refusal must name both roles, got ' + JSON.stringify(r));
      assert(!fs.existsSync(f.storePath),
        '#819-T7: a self-substitution must write NO record — the residue is a card that flags a '
        + 'substitution while redirecting nothing');
    }

    // T7b — the observed REVERT case: an active record to investigator, then back to the frozen role.
    // P0 must sit BEFORE the idempotent-replay branch, or a legacy self-row on disk replays to ok forever.
    {
      const f = subroleFixture({ status: 'pending' }); dirs.push(f.dir);
      const first = subroleCall('#819-T7b forward swap',
        () => runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1'));
      assert(first.result === 'ok', '#819-T7b: fixture precondition — the forward swap must succeed, got '
        + JSON.stringify(first));
      const r = subroleCall('#819-T7b revert',
        () => runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'code-explorer' }, 'p1'));
      assert(r.result === 'refuse' && r.reason === 'substitute_self_noop',
        '#819-T7b: reverting to the frozen role is still a self-substitution, got ' + JSON.stringify(r));
      assert((f.rows() || []).length === 1,
        '#819-T7b: the refused revert must not append a second row, got ' + JSON.stringify(f.rows()));
      const d = subroleCall('#819-T7b card after the refused revert', () => buildDispatch(
        { id: 'n1', role: 'code-explorer', model: 'standard', declared_write_set: '—' },
        { planPath: f.planPath, evidence_file: '.cache/n1.md', nonce: SUBROLE_NONCE }));
      assert(d.agent_type === 'investigator' && d.codex_task_name === 'n1_investigator',
        '#819-T7b: the surviving record still governs the card, got '
        + JSON.stringify({ agent_type: d.agent_type, codex_task_name: d.codex_task_name }));
    }
  } finally {
    for (const d of dirs) fs.rmSync(d, { recursive: true, force: true });
  }
});

// #819-T8b — the reset is atomic and FAILS LOUD. An unwritable .cache must refuse, never report
// success over a surviving body.
scenario(() => {
  const { runSubstituteRole } = require('./kaola-workflow-adaptive-node');
  // Running as root defeats the permission bit; skip rather than pass vacuously.
  if (process.getuid && process.getuid() === 0) {
    assert(true, '#819-T8b: SKIPPED — running as uid 0, where chmod 0o555 does not deny writes');
    return;
  }
  const dirs = [];
  try {
    const f = subroleFixture({ evidence: SUBROLE_GAP_BODY }); dirs.push(f.dir);
    const before = f.read();
    let r;
    try {
      fs.chmodSync(f.cache, 0o555);
      r = subroleCall('#819-T8b unwritable .cache',
        () => runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1'));
    } finally {
      fs.chmodSync(f.cache, 0o755);
    }
    assert(r.result === 'refuse' && r.reason === 'substitute_evidence_reset_failed',
      '#819-T8b: a re-seed that cannot complete atomically must refuse — an atomic replace leaves the '
      + 'PRIOR file byte-intact on failure, so swallowing it would report success over a surviving '
      + 'gap body, got ' + JSON.stringify(r));
    assert(f.rows() === null, '#819-T8b: a failed reset must write NO record');
    // The prior body survives (the atomic replace never landed) or was unlinked by the fail-loud arm,
    // leaving the fail-closed `evidence_unbound` residue. Either is admissible; a PARTIAL rewrite is not.
    const after = f.read();
    assert(after === null || after === before,
      '#819-T8b: the evidence file must be either byte-intact or absent — never a torn prefix, got:\n' + after);
  } finally {
    for (const d of dirs) fs.rmSync(d, { recursive: true, force: true });
  }
});

// #819-U1/U2 — the classifier as a unit, and the two operator hints. `substitute-role` today ships
// five refusal codes with NO hint at all, so both new codes inherit the generic "Run orient" line —
// which actively misdirects, and misdirecting the orchestrator into improvisation is the failure this
// issue is about.
scenario(() => {
  const mod = require('./kaola-workflow-adaptive-node');
  const { OPERATOR_HINT_REGISTRY, getOperatorHint, seedEvidenceFile } = mod;
  const dirs = [];
  try {
    assert(typeof mod.classifyEvidenceBody === 'function',
      '#819-U1: classifyEvidenceBody must be EXPORTED so the three-way classification can be pinned '
      + 'directly rather than only through runSubstituteRole\'s outcome, got '
      + typeof mod.classifyEvidenceBody);
    if (typeof mod.classifyEvidenceBody === 'function') {
      const classify = mod.classifyEvidenceBody;
      const f = subroleFixture({}); dirs.push(f.dir);
      seedEvidenceFile(f.planPath, 'n1', SUBROLE_NONCE, 'code-explorer', false, null);
      const cases = [
        ['absent file', '', 'seeded'],
        ['header only', 'evidence-binding: n1 ' + SUBROLE_NONCE + '\n', 'seeded'],
        ['production seed', f.read(), 'seeded'],
        ['reference gap body', SUBROLE_GAP_BODY, 'capability_gap'],
        ['column-0 capability_gap key', SUBROLE_GAP_BODY_KEYED, 'capability_gap'],
        ['indented-only occurrence', SUBROLE_GAP_BODY_INDENTED_ONLY, 'deliverable'],
        ['forged marker over real work', SUBROLE_FORGED_BODY, 'deliverable'],
        ['plain deliverable', SUBROLE_DELIVERABLE_BODY, 'deliverable'],
      ];
      for (const [label, body, want] of cases) {
        const got = subroleCall('#819-U1 ' + label, () => ({ v: classify(body, 'code-explorer') }));
        assert(got.v === want,
          '#819-U1 ' + label + ': expected "' + want + '", got ' + JSON.stringify(got.v));
      }
    }

    for (const code of ['substitute_self_noop', 'substitute_evidence_reset_failed']) {
      assert(typeof OPERATOR_HINT_REGISTRY[code] === 'function',
        '#819-U2: ' + code + ' must carry an operator hint, got ' + typeof OPERATOR_HINT_REGISTRY[code]);
      const hint = String(getOperatorHint(code,
        { nodeId: 'n1', to_role: 'code-explorer', detail: 'no resolvable binding nonce' }) || '');
      assert(!/Run orient/.test(hint),
        '#819-U2: ' + code + ' must not fall through to the generic "Run orient" hint, got ' + JSON.stringify(hint));
      assert(/write-halt/.test(hint),
        '#819-U2: ' + code + ' must name the escalation, got ' + JSON.stringify(hint));
    }
    const resetHint = String(getOperatorHint('substitute_evidence_reset_failed', { nodeId: 'n1' }) || '');
    assert(/hand-edit/i.test(resetHint),
      '#819-U2: the reset-failure hint must forbid the hand patch this issue was filed over, got '
      + JSON.stringify(resetHint));
  } finally {
    for (const d of dirs) fs.rmSync(d, { recursive: true, force: true });
  }
});

// #822 — classifyEvidenceBody fails CLOSED on a vacuous anti-forgery contract. The capability_gap
// classification requires BOTH a typed column-0 marker AND "no content-bearing token in the role's
// ROLE_TOKEN_REGISTRY row carries a value" — but for a role with NO registry row at all the second
// conjunct is vacuous: the loop has nothing to iterate, so pre-fix ANY marker-bearing body for such
// a role classified capability_gap regardless of the work it carried (a marker could launder real
// work into a reset). The shipped row-less roles are workflow-planner, finalize, expansion-point.
// Post-fix, "no token contract" is NOT "no delivered work": the body is not classifiable as a gap,
// so it stands as a deliverable and the swap is refused. (This is latent end-to-end today —
// substitute-role's P2 admits only kind:producer, and no row-less role is a producer — so the pin
// sits at the classifier unit, exactly where the issue names the obligation.)
scenario(() => {
  const mod = require('./kaola-workflow-adaptive-node');
  const classify = mod.classifyEvidenceBody;
  assert(typeof classify === 'function', '#822: classifyEvidenceBody is exported, got ' + typeof classify);
  if (typeof classify !== 'function') return;
  const ROWLESS_ROLES = ['workflow-planner', 'finalize', 'expansion-point'];
  for (const role of ROWLESS_ROLES) {
    // Fixture premise, mutation-proven: if a future change GIVES this role a content-bearing registry
    // row, the vacuous-contract path no longer applies to it and this fixture must be re-authored —
    // fail loudly here rather than silently assert the wrong contract.
    assert(!ROLE_TOKEN_REGISTRY[role],
      '#822: fixture premise — ' + role + ' has NO ROLE_TOKEN_REGISTRY row (a new content row retires this fixture)');
    // The laundering vector: real delivered content with a typed gap marker stamped on top. Pre-fix
    // this classified capability_gap via the vacuous conjunct, laundering the work into a reset.
    const markerOverWork = 'evidence-binding: n1 ' + SUBROLE_NONCE + '\n'
      + 'summary: ' + role + ' delivered a full account of the run and every artifact it touched\n'
      + 'delegation_outcome: capability_gap\n';
    assert(classify(markerOverWork, role) === 'deliverable',
      '#822: ' + role + ' marker-over-work must classify deliverable — a marker must NOT launder real '
      + 'work into a gap for a row-less role (pre-fix: capability_gap via the vacuous conjunct), got '
      + JSON.stringify(classify(markerOverWork, role)));
    // The marker-ONLY body: "no token contract" is not "no delivered work" — fail closed to
    // deliverable (the swap is refused) rather than classify a gap the anti-forgery half never measured.
    const markerOnly = 'evidence-binding: n1 ' + SUBROLE_NONCE + '\ndelegation_outcome: capability_gap\n';
    assert(classify(markerOnly, role) === 'deliverable',
      '#822: ' + role + ' marker-only body fails CLOSED to deliverable (pre-fix: capability_gap), got '
      + JSON.stringify(classify(markerOnly, role)));
    const keyedOnly = 'evidence-binding: n1 ' + SUBROLE_NONCE + '\ncapability_gap: required capability unavailable to this role\n';
    assert(classify(keyedOnly, role) === 'deliverable',
      '#822: ' + role + ' column-0 capability_gap key fails CLOSED to deliverable, got '
      + JSON.stringify(classify(keyedOnly, role)));
    // The unchanged arms: an empty/seed body stays seeded; a marker-free content body stays a deliverable.
    assert(classify('', role) === 'seeded',
      '#822: ' + role + ' empty body stays seeded, got ' + JSON.stringify(classify('', role)));
    assert(classify('evidence-binding: n1 ' + SUBROLE_NONCE + '\nsummary: plain delivered work\n', role) === 'deliverable',
      '#822: ' + role + ' marker-free content body stays deliverable');
  }
  // The guard is NOT de-fanged for row-bearing roles: the reference gap body still classifies
  // capability_gap and the forged marker still classifies deliverable (the #819-U1 contract stands).
  assert(classify(SUBROLE_GAP_BODY, 'code-explorer') === 'capability_gap',
    '#822: a row-bearing role\'s genuine gap still classifies capability_gap — the fail-closed is '
    + 'scoped to the vacuous contract, got ' + JSON.stringify(classify(SUBROLE_GAP_BODY, 'code-explorer')));
  assert(classify(SUBROLE_FORGED_BODY, 'code-explorer') === 'deliverable',
    '#822: the row-bearing anti-forgery arm still stands (a forged marker over real findings is a deliverable)');
});

// #819-T13 — THE END-TO-END PROOF, and the only assertion that tests the "preserve, do not rotate"
// decision against the real close gate. Gap body -> substitute -> the substitute delivers -> close.
// Rotating the nonce in the reset trades one wedge (substitution refused) for another (close refuses
// evidence_stale), which no unit-level assertion above would catch.
scenario(() => {
  const { runSubstituteRole, runCloseNode, checkEvidenceShape } = require('./kaola-workflow-adaptive-node');
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-819-e2e-'));
  try {
    const projectDir = path.join(tmp, 'kaola-workflow', 'issue-819');
    const cacheDir = path.join(projectDir, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    const body = makePlan(
      ['| n1 | in_progress | |', '| review | pending | |', '| done | pending | |'],
      ['| n1 | code-explorer | — | — | 1 | sequence |',
        '| review | code-reviewer | n1 | — | 1 | sequence |',
        '| done | finalize | review | CHANGELOG.md | 1 | sequence |']);
    const planPath = path.join(projectDir, 'workflow-plan.md');
    fs.writeFileSync(planPath, '<!-- plan_hash: ' + planValidator.computePlanHash(body) + ' -->\n' + body);
    fs.writeFileSync(path.join(cacheDir, 'barrier-base-n1'), SUBROLE_SHA + '\n');
    const evidencePath = path.join(cacheDir, 'n1.md');
    fs.writeFileSync(evidencePath, SUBROLE_GAP_BODY);

    const swap = subroleCall('#819-T13 substitute',
      () => runSubstituteRole({ planPath, nodeId: 'n1', toRole: 'investigator' }, 'issue-819'));
    assert(swap.result === 'ok' && swap.evidence_reset === true,
      '#819-T13: the gap body must reset and swap, got ' + JSON.stringify(swap));

    // The substitute now does the work, writing into the file the reset left behind — no hand patch.
    const reseeded = fs.readFileSync(evidencePath, 'utf8');
    assert(!/capability_gap/.test(reseeded) && /^findings: *$/m.test(reseeded),
      '#819-T13: the re-seeded file must be a CLEAN empty stub for the substitute to fill — the gap '
      + 'body\'s own empty `findings:` line would satisfy a bare stub probe, so the absence of the gap '
      + 'is what proves the reset ran, got:\n' + reseeded);
    fs.writeFileSync(evidencePath,
      reseeded.replace(/^findings: *$/m, 'findings: real work delivered by the substituted role'));

    // The close gate binds evidence to THIS open's nonce. Preserve ⇒ ok; rotate ⇒ evidence_stale.
    const shape = checkEvidenceShape('code-explorer', 'n1', fs.readFileSync(evidencePath, 'utf8'),
      { expectedNonce: SUBROLE_NONCE, expectedNodeId: 'n1' });
    assert(shape.ok === true,
      '#819-T13: the substitute\'s evidence must close against the binding the OPEN recorded — a '
      + 'rotated nonce would refuse evidence_stale and trade one wedge for another, got '
      + JSON.stringify(shape));

    const common = {
      planPath, project: 'issue-819',
      shell: () => ({ exitCode: 0, result: 'ok', ok: true, overallOk: true, selectorCheck: { isSelector: false, ok: true } }),
      readFile: p => fs.readFileSync(p, 'utf8'), writeFile: (p, c) => fs.writeFileSync(p, c),
      cacheExists: p => fs.existsSync(p), unlink: p => fs.unlinkSync(p), readdir: d => fs.readdirSync(d),
    };
    const closed = subroleCall('#819-T13 close', () => runCloseNode({ ...common, nodeId: 'n1' }));
    assert(closed.result === 'ok' && closed.closed === 'n1',
      '#819-T13: the node must CLOSE after the substituted role delivers — the recovery is only real '
      + 'if the run can finish, got ' + JSON.stringify(closed));

    const after = fs.readFileSync(planPath, 'utf8');
    // #833: the substitution used to be COPIED into the close-time compliance row. The row is gone;
    // the record it copied FROM — `.cache/role-substitutions.json` — was always the durable one, so
    // assert against that. Copying it into the plan was the duplication this issue subtracts.
    const substitutions = JSON.parse(fs.readFileSync(path.join(cacheDir, 'role-substitutions.json'), 'utf8'));
    const record = (substitutions.substitutions || []).find(row => row.node_id === 'n1');
    assert(record && record.from_role === 'code-explorer' && record.to_role === 'investigator',
      '#819-T13: the durable record must say WHAT ACTUALLY RAN, got ' + JSON.stringify(record));
    assert(record && /manifest superset/.test(String(record.basis)),
      '#819-T13: and the basis that made it legal, got ' + JSON.stringify(record && record.basis));
    assert(!after.includes('## Required Agent Compliance'),
      '#819-T13/#833: the close copies none of it into the plan');
    assert(/^\| n1 \| complete \|/m.test(after),
      '#819-T13: the ledger row must be complete');
  } finally {
    fs.rmSync(tmp, { recursive: true, force: true });
  }
});

// ---------------------------------------------------------------------------
// #841 — the RE-ISSUED DISPATCH CARD. #819 shipped the DERIVATION half (codexTaskNameForNode follows
// the dispatch target, pinned by T4/T4b above) but never its DELIVERY. `buildDispatch` runs at exactly
// three sites, all openers, and every one of them resolves its target from the readySet — an
// `in_progress` row is not in it, so after a MID-NODE substitution no code path rebuilds the card.
// `orient` stays silent too (the reset preserves the binding header, so requires_redispatch is false),
// and the only card on disk is the envelope the CONSUMED open wrote.
//
// That leaves the orchestrator with two moves, and the plan-run surfaces forbid both: re-present the
// consumed identity from the stale envelope (the runtime rejects it — the v2 task name is already
// taken), or hand-derive the new one, which is the improvisation "NEVER improvise a task name" names.
//
// ACCEPTANCE: a substitution re-issues the card MECHANICALLY. `substitute-role`'s ok payload carries
// the card-grade spawn fields for the dispatch target, and every one of them agrees with the card
// `buildDispatch` builds for the same node once the record exists — so the two can never drift and the
// orchestrator never has to author a spawn parameter.
//
// The tests below deliberately do NOT repeat #819-T13's shortcut of modelling re-dispatch as a direct
// evidence write: that bypasses the card layer entirely, which is why the shipped suite is green over
// this gap. Here the second spawn is driven from the emitted card and from nothing else.
// ---------------------------------------------------------------------------

// The spawn parameters an orchestrator may not improvise: the identity trio the plan-run prose names
// by key (`agent_type` to dispatch, `agent_type_frozen` for what the plan froze, `role_substituted`),
// the substitution basis, the derived task identity + dispatch mode, and every tier-derived spawn
// parameter (effort, Codex profile, wait budget, opencode variant). Expected VALUES are never
// transcribed here — each is compared against `buildDispatch`'s own output for the same node.
const REISSUED_CARD_KEYS = [
  'agent_type', 'agent_type_frozen', 'role_substituted', 'role_substitution_basis',
  'codex_task_name', 'codex_dispatch_mode',
  'codex_model', 'codex_model_source', 'codex_reasoning_effort', 'codex_reasoning_effort_source',
  'codex_profile_mode', 'codex_profile_tier', 'codex_profile_compatible',
  'wait_budget_minutes', 'wait_budget_source',
  'opencode_variant', 'opencode_variant_source',
];

// #841-A/B/C — the payload contract, on the exact row the issue is about: a node already `in_progress`
// whose dispatched role self-persisted a capability_gap. Fresh record, idempotent replay, and the
// refusal arm.
scenario(() => {
  const { runSubstituteRole, buildDispatch } = require('./kaola-workflow-adaptive-node');
  const dirs = [];
  const nodeInfo = { id: 'n1', role: 'code-explorer', model: 'standard', declared_write_set: '—' };
  try {
    // A — the fresh record.
    {
      const f = subroleFixture({ status: 'in_progress', evidence: SUBROLE_GAP_BODY }); dirs.push(f.dir);
      const ctx = { planPath: f.planPath, evidence_file: '.cache/n1.md', nonce: SUBROLE_NONCE };

      // The identity the runtime has ALREADY consumed — the card the open emitted, built by the
      // shipped opener logic rather than transcribed.
      const consumedCard = subroleCall('#841-A consumed card', () => buildDispatch(nodeInfo, ctx));
      assert(consumedCard.codex_task_name === 'n1_code_explorer',
        '#841-A: fixture precondition — the pre-substitution identity is the frozen one, got '
        + JSON.stringify(consumedCard.codex_task_name));

      const swap = subroleCall('#841-A substitute mid-node',
        () => runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1'));
      assert(swap.result === 'ok' && swap.evidence_reset === true,
        '#841-A: fixture precondition — the mid-node gap body must reset and swap, got ' + JSON.stringify(swap));

      // The card the three openers WOULD emit now that the record exists. This is the single source of
      // truth for every expected value below; the payload must not be able to drift from it.
      const reference = subroleCall('#841-A reference card', () => buildDispatch(nodeInfo, ctx));

      assert(typeof swap.codex_task_name === 'string' && swap.codex_task_name !== '',
        '#841-A: the ok payload must RE-ISSUE the dispatch identity — with no codex_task_name on the '
        + 'payload and no opener able to reach an in_progress row, the orchestrator has nothing to '
        + 'spawn from but the consumed envelope or an improvised name, got '
        + JSON.stringify(swap.codex_task_name));
      assert(swap.codex_task_name !== consumedCard.codex_task_name,
        '#841-A: the re-issued identity must be FRESH — re-presenting the consumed one is the spawn '
        + 'failure this issue exists for, got ' + JSON.stringify(swap.codex_task_name));
      assert(swap.codex_task_name === reference.codex_task_name,
        '#841-A: the re-issued identity must be the one buildDispatch derives for the dispatch target, '
        + 'so the payload and the openers can never disagree.\ngot:      '
        + JSON.stringify(swap.codex_task_name) + '\nexpected: ' + JSON.stringify(reference.codex_task_name));

      for (const k of REISSUED_CARD_KEYS) {
        assert(Object.prototype.hasOwnProperty.call(swap, k),
          '#841-A: the ok payload is missing the card-grade spawn field "' + k + '" — the plan-run '
          + 'mandate forbids improvising a task name, omitting agent_type, or dropping the effort '
          + 'tier, so every one of them has to be ON the re-issued card. payload keys: '
          + JSON.stringify(Object.keys(swap).sort()));
        assert(JSON.stringify(swap[k]) === JSON.stringify(reference[k]),
          '#841-A: "' + k + '" must equal what buildDispatch emits for this node.\ngot:      '
          + JSON.stringify(swap[k]) + '\nexpected: ' + JSON.stringify(reference[k]));
      }
      assert(swap.role_substitution_basis === swap.basis,
        '#841-A: the card\'s basis and the record\'s basis are one value, got '
        + JSON.stringify(swap.role_substitution_basis) + ' vs ' + JSON.stringify(swap.basis));

      // Nothing the payload and the card share may disagree — an extra card-named key carrying a
      // different value would be a second, contradicting source of spawn truth.
      for (const k of Object.keys(swap)) {
        if (!Object.prototype.hasOwnProperty.call(reference, k)) continue;
        assert(JSON.stringify(swap[k]) === JSON.stringify(reference[k]),
          '#841-A: the payload and the dispatch card disagree on "' + k + '": '
          + JSON.stringify(swap[k]) + ' vs ' + JSON.stringify(reference[k]));
      }

      // B — the crash-resume replay hands back the SAME card. An orchestrator that lost the payload
      // between the record and the spawn re-runs the identical command; a replay that answered with
      // less than the first call would leave it in exactly the improvisation this issue closes.
      const replay = subroleCall('#841-B replay',
        () => runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'investigator' }, 'p1'));
      assert(replay.result === 'ok' && replay.idempotent === true,
        '#841-B: fixture precondition — the second identical call is an idempotent replay, got '
        + JSON.stringify(replay));
      for (const k of REISSUED_CARD_KEYS) {
        assert(Object.prototype.hasOwnProperty.call(replay, k),
          '#841-B: the idempotent-replay return must carry "' + k + '" too — a crash between the '
          + 'record and the spawn is resumed by re-running this command, and that resume must yield a '
          + 'dispatchable card. replay keys: ' + JSON.stringify(Object.keys(replay).sort()));
        assert(JSON.stringify(replay[k]) === JSON.stringify(swap[k]),
          '#841-B: "' + k + '" must be identical across the replay (the card is a pure function of the '
          + 'node and the active record — a counter or timestamp input would break crash-resume).\n'
          + 'got:      ' + JSON.stringify(replay[k]) + '\nexpected: ' + JSON.stringify(swap[k]));
      }
    }

    // C — the guard the #819 pin owns, restated for the payload: nothing about re-issuing a card may
    // reach a node with no substitution on record, and a REFUSED swap must not hand out a card at all
    // (a dispatchable card behind a refusal is a spawn the workflow never authorised).
    {
      // The MEASURED key set of an unsubstituted card at this commit — the same golden list #819-T6
      // pins, restated here so a fix that leaks a key into buildDispatch reds in its own issue's suite.
      const GOLDEN_DISPATCH_KEYS = [
        'agent_type', 'codex_dispatch_mode', 'codex_model', 'codex_model_source',
        'codex_profile_compatible', 'codex_profile_mode', 'codex_profile_tier',
        'codex_reasoning_effort', 'codex_reasoning_effort_source', 'codex_task_name',
        'declared_write_set', 'evidence_file', 'forge_rider', 'guards', 'model', 'model_display',
        'node_id', 'nonce', 'opencode_variant', 'opencode_variant_source', 'required_tokens',
        'role', 'wait_budget_minutes', 'wait_budget_source', 'working_dir',
      ];
      const f = subroleFixture({ status: 'in_progress', evidence: SUBROLE_GAP_BODY }); dirs.push(f.dir);
      const d = subroleCall('#841-C unsubstituted card', () => buildDispatch(nodeInfo,
        { planPath: f.planPath, evidence_file: '.cache/n1.md', nonce: SUBROLE_NONCE }));
      assert(JSON.stringify(Object.keys(d).sort()) === JSON.stringify(GOLDEN_DISPATCH_KEYS),
        '#841-C: an unsubstituted card must stay BYTE-IDENTICAL — re-issuing a card for a substituted '
        + 'node may not add a key to the card of a node that has none.\ngot:      '
        + JSON.stringify(Object.keys(d).sort()) + '\nexpected: ' + JSON.stringify(GOLDEN_DISPATCH_KEYS));
      assert(d.codex_task_name === 'n1_code_explorer',
        '#841-C: and its identity is unchanged, got ' + JSON.stringify(d.codex_task_name));

      const refused = subroleCall('#841-C refused swap',
        () => runSubstituteRole({ planPath: f.planPath, nodeId: 'n1', toRole: 'code-explorer' }, 'p1'));
      assert(refused.result === 'refuse' && refused.reason === 'substitute_self_noop',
        '#841-C: fixture precondition — a swap to the frozen role refuses, got ' + JSON.stringify(refused));
      for (const k of ['codex_task_name', 'agent_type', 'role_substituted', 'role_substitution_basis']) {
        assert(!Object.prototype.hasOwnProperty.call(refused, k),
          '#841-C: a REFUSED swap must carry no card field ("' + k + '" present) — nothing was recorded, '
          + 'so a card handed back here would be a spawn identity for a substitution that never happened');
      }
    }
  } finally {
    for (const d of dirs) fs.rmSync(d, { recursive: true, force: true });
  }
});

// #841-D — THE END-TO-END PROOF, driven THROUGH the card layer. #819-T13 proves the same recovery can
// close, but it models re-dispatch as a direct write into the evidence file, so the dispatch identity
// is never asked for and the gap this issue names cannot show up there. Here the second spawn takes
// every parameter from the re-issued card, against a runtime model where a v2 task name may be
// consumed exactly once — which is what makes the stale card mechanically detectable rather than a
// matter of prose.
scenario(() => {
  const { runSubstituteRole, runCloseNode, buildDispatch } = require('./kaola-workflow-adaptive-node');
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-841-e2e-'));
  try {
    const projectDir = path.join(tmp, 'kaola-workflow', 'issue-841');
    const cacheDir = path.join(projectDir, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    const body = makePlan(
      ['| n1 | in_progress | |', '| review | pending | |', '| done | pending | |'],
      ['| n1 | code-explorer | — | — | 1 | sequence |',
        '| review | code-reviewer | n1 | — | 1 | sequence |',
        '| done | finalize | review | CHANGELOG.md | 1 | sequence |']);
    const planPath = path.join(projectDir, 'workflow-plan.md');
    fs.writeFileSync(planPath, '<!-- plan_hash: ' + planValidator.computePlanHash(body) + ' -->\n' + body);
    fs.writeFileSync(path.join(cacheDir, 'barrier-base-n1'), SUBROLE_SHA + '\n');
    const evidencePath = path.join(cacheDir, 'n1.md');

    // The node exactly as the frozen plan declares it, so the reference card below is built from the
    // plan rather than from a hand-written stand-in.
    const parsed = planValidator.planNodesWithExpansions(fs.readFileSync(planPath, 'utf8'))
      .find(n => n.id === 'n1');
    assert(!!parsed && parsed.role === 'code-explorer',
      '#841-D: fixture precondition — n1 parses out of the frozen plan, got ' + JSON.stringify(parsed && parsed.role));
    const nodeInfo = {
      id: parsed.id, role: parsed.role, model: parsed.model, declared_write_set: parsed.writeSetRaw,
    };
    const ctx = { planPath, evidence_file: '.cache/n1.md', nonce: SUBROLE_NONCE };

    // The runtime model: a v2 task identity may be consumed exactly ONCE. Re-presenting a consumed
    // name is the observed "already exists" spawn failure; an absent name is the improvisation the
    // plan-run surfaces forbid. Both are refusals here, so neither can pass silently.
    const consumed = new Set();
    const spawn = (taskName, agentType) => {
      if (typeof taskName !== 'string' || taskName === '') {
        return { ok: false, error: 'no task name on the card; improvising one is forbidden' };
      }
      if (!agentType) return { ok: false, error: 'no agent_type on the card' };
      if (consumed.has(taskName)) return { ok: false, error: 'task "' + taskName + '" already exists' };
      consumed.add(taskName);
      return { ok: true, task_name: taskName, agent_type: agentType };
    };

    // 1. The open dispatches the frozen role and CONSUMES its identity, and the CLI caches the whole
    //    envelope at .cache/<op>-envelope.json — the only card that will exist on disk from here on.
    const openCard = subroleCall('#841-D open card', () => buildDispatch(nodeInfo, ctx));
    const first = spawn(openCard.codex_task_name, openCard.agent_type);
    assert(first.ok === true && first.agent_type === 'code-explorer',
      '#841-D: fixture precondition — the first spawn consumes the frozen identity, got ' + JSON.stringify(first));
    fs.writeFileSync(path.join(cacheDir, 'open-next-envelope.json'),
      JSON.stringify({ result: 'ok', opened: 'n1', dispatch: openCard }) + '\n');

    // 2. The dispatched role hits a capability gap and self-persists it.
    fs.writeFileSync(evidencePath, SUBROLE_GAP_BODY);
    const swap = subroleCall('#841-D substitute',
      () => runSubstituteRole({ planPath, nodeId: 'n1', toRole: 'investigator' }, 'issue-841'));
    assert(swap.result === 'ok' && swap.evidence_reset === true,
      '#841-D: fixture precondition — the gap body resets and swaps, got ' + JSON.stringify(swap));

    // 3. "Go get the card first" sends the orchestrator to the cached envelope — which still holds the
    //    identity the runtime consumed in step 1. This is the dead end, and it must stay one.
    const onDisk = JSON.parse(fs.readFileSync(path.join(cacheDir, 'open-next-envelope.json'), 'utf8')).dispatch;
    const stale = spawn(onDisk.codex_task_name, onDisk.agent_type);
    assert(stale.ok === false && /already exists/.test(stale.error),
      '#841-D: fixture premise — the only card on disk still carries the CONSUMED identity, so obeying '
      + '"every spawn parameter comes from the dispatch card" re-presents it and the spawn fails, got '
      + JSON.stringify(stale));
    assert(onDisk.agent_type === 'code-explorer',
      '#841-D: fixture premise — and it still names the role that just gapped, got ' + JSON.stringify(onDisk.agent_type));

    // 4. THE ACCEPTANCE. The re-issued card comes off the substitution's own return, and the second
    //    spawn takes every parameter from it. No name is derived anywhere in this test.
    const reissued = spawn(swap.codex_task_name, swap.agent_type);
    assert(reissued.ok === true,
      '#841-D: the substitution must hand back a spawnable card — with no codex_task_name/agent_type '
      + 'on the payload, no opener able to re-card an in_progress row, and a stale envelope on disk, '
      + 'the re-dispatch has no non-improvised source at all. spawn said: ' + JSON.stringify(reissued.error)
      + '; payload keys: ' + JSON.stringify(Object.keys(swap).sort()));
    assert(reissued.agent_type === 'investigator',
      '#841-D: the re-issued card must dispatch the SUBSTITUTE, got ' + JSON.stringify(reissued.agent_type));
    assert(reissued.task_name !== openCard.codex_task_name,
      '#841-D: under a fresh identity, not the consumed one, got ' + JSON.stringify(reissued.task_name));
    const reference = subroleCall('#841-D reference card', () => buildDispatch(nodeInfo, ctx));
    assert(swap.codex_task_name === reference.codex_task_name
      && swap.agent_type === reference.agent_type
      && swap.agent_type_frozen === reference.agent_type_frozen
      && swap.role_substituted === reference.role_substituted,
      '#841-D: and it must be the SAME card the openers would build now that the record exists.\n'
      + 'got:      ' + JSON.stringify({ codex_task_name: swap.codex_task_name, agent_type: swap.agent_type,
        agent_type_frozen: swap.agent_type_frozen, role_substituted: swap.role_substituted })
      + '\nexpected: ' + JSON.stringify({ codex_task_name: reference.codex_task_name, agent_type: reference.agent_type,
        agent_type_frozen: reference.agent_type_frozen, role_substituted: reference.role_substituted }));

    // 5. The spawned substitute delivers into the file the reset left behind, and the run finishes.
    const reseeded = fs.readFileSync(evidencePath, 'utf8');
    fs.writeFileSync(evidencePath,
      reseeded.replace(/^findings: *$/m, 'findings: delivered by the role spawned from the re-issued card ('
        + (reissued.agent_type || 'NO agent_type ON THE CARD') + ' as '
        + (reissued.task_name || 'NO task name ON THE CARD') + ')'));
    const closed = subroleCall('#841-D close', () => runCloseNode({
      planPath, project: 'issue-841', nodeId: 'n1',
      shell: () => ({ exitCode: 0, result: 'ok', ok: true, overallOk: true, selectorCheck: { isSelector: false, ok: true } }),
      readFile: p => fs.readFileSync(p, 'utf8'), writeFile: (p, c) => fs.writeFileSync(p, c),
      cacheExists: p => fs.existsSync(p), unlink: p => fs.unlinkSync(p), readdir: d => fs.readdirSync(d),
    }));
    assert(closed.result === 'ok' && closed.closed === 'n1',
      '#841-D: the node must close after the CARD-DISPATCHED substitute delivers — the recovery is '
      + 'only real if the run reaches the end of it, got ' + JSON.stringify(closed));
    const after = fs.readFileSync(planPath, 'utf8');
    const subs841 = JSON.parse(fs.readFileSync(path.join(cacheDir, 'role-substitutions.json'), 'utf8'));
    const rec841 = (subs841.substitutions || []).find(row => row.node_id === 'n1');
    assert(rec841 && rec841.from_role === 'code-explorer' && rec841.to_role === 'investigator',
      '#841-D/#833: and the durable substitution record still says what actually ran, got '
      + JSON.stringify(rec841));
    assert(!after.includes('## Required Agent Compliance'),
      '#841-D/#833: with nothing copied into the plan');
  } finally {
    fs.rmSync(tmp, { recursive: true, force: true });
  }
});

// ===========================================================================
// #836 — refuse on missing MEANING, not on serialization.
//
// The evidence checker used to demand a byte-exact serialization the producing agent could not
// see at write time: a column-0 token key with a NON-WHITESPACE value ON THE SAME LINE. A value
// that wrapped onto the next line, a token indented by a leading space, or the documented
// presence-only `findings_none` written without a colon were all refused even though the
// information was present and correct. Each refusal cost a triage + a re-dispatch that changed
// zero product state.
//
// The contract these scenarios pin:
//   (1) A token key whose value is EMPTY on its own line is satisfied by the IMMEDIATELY FOLLOWING
//       line when that line is a genuine continuation — non-blank, not an `<!-- ... -->` comment,
//       and not itself a `<name>:` key line. Only the immediately following line: no skipping
//       forward past blanks, comments, or empty sibling keys.
//   (2) A token is recognised anywhere in the body, including with leading whitespace — the
//       column-0 anchor is dropped for the CONTENT tokens.
//   (3) The documented bare-token form `findings_none` (the token alone on a line, no colon) is
//       normalised to its canonical value, not refused.
//   (4) Absence stays FAIL-CLOSED. An untouched open-time seed, an empty value with no
//       continuation, a bare token that is NOT the documented presence-only one, and a body with
//       no token at all all still refuse exactly as before.
// ===========================================================================

// ---------------------------------------------------------------------------
// #836-T1: checkEvidenceShape accepts a WRAPPED value for every content-token branch
// (tdd-guide / implementer / metric-optimizer / generic registry), and an INDENTED token line.
// This is refusal reproduction (A): `tests-green:` with the value on the next line.
// ---------------------------------------------------------------------------
scenario(() => {
  const NONCE = 'abc123def456';
  const bindTo = (id) => 'evidence-binding: ' + id + ' ' + NONCE + '\n';
  const optsFor = (id) => ({ expectedNonce: NONCE, expectedNodeId: id });

  // (A) THE REPRODUCTION. The implementer verification tier wrapped onto the next line.
  const wrappedTier = bindTo('impl-x')
    + 'tests-green:\n'
    + 'node scripts/test-adaptive-node.js — 4118 assertions green\n';
  const rWrapped = checkEvidenceShape('implementer', 'impl-x', wrappedTier, optsFor('impl-x'));
  assert(rWrapped.ok === true,
    '#836-T1a: implementer `tests-green:` with the value WRAPPED onto the next line must close — '
    + 'the meaning is present, only the serialization differed, got ' + JSON.stringify(rWrapped));

  // The same wrap with trailing whitespace after the colon (what an editor actually leaves behind).
  const wrappedTierWs = bindTo('impl-x')
    + 'tests-green:   \n'
    + 'node scripts/test-adaptive-node.js — 4118 assertions green\n';
  assert(checkEvidenceShape('implementer', 'impl-x', wrappedTierWs, optsFor('impl-x')).ok === true,
    '#836-T1b: trailing whitespace after the colon must not defeat the wrapped value');

  // (B) An INDENTED token line (the column-0 anchor is dropped for content tokens).
  const indentedTier = bindTo('impl-x') + '  tests-green: 4118 assertions green\n';
  assert(checkEvidenceShape('implementer', 'impl-x', indentedTier, optsFor('impl-x')).ok === true,
    '#836-T1c: an indented `tests-green:` token must be recognised — the token is accepted anywhere '
    + 'in the evidence body, got ' + JSON.stringify(checkEvidenceShape('implementer', 'impl-x', indentedTier, optsFor('impl-x'))));

  // (C) tdd-guide RED — the same prose-valued token, same wrap.
  const wrappedRed = bindTo('tdd-x')
    + 'RED:\n'
    + 'the new assertion fails on the recorded baseline\n'
    + 'red_baseline: ' + NONCE + '\n';
  assert(checkEvidenceShape('tdd-guide', 'tdd-x', wrappedRed, optsFor('tdd-x')).ok === true,
    '#836-T1d: tdd-guide RED wrapped onto the next line must close, got '
    + JSON.stringify(checkEvidenceShape('tdd-guide', 'tdd-x', wrappedRed, optsFor('tdd-x'))));

  // (D) metric-optimizer — every D6 token wrapped.
  const wrappedD6 = bindTo('opt-x')
    + 'metric_baseline:\n412ms\n'
    + 'metric_final:\n118ms\n'
    + 'iterations_used:\n3\n'
    + 'regression-green:\nnpm test green\n';
  assert(checkEvidenceShape('metric-optimizer', 'opt-x', wrappedD6, optsFor('opt-x')).ok === true,
    '#836-T1e: metric-optimizer D6 tokens wrapped onto the next line must close, got '
    + JSON.stringify(checkEvidenceShape('metric-optimizer', 'opt-x', wrappedD6, optsFor('opt-x'))));

  // (E) generic registry branch — the nonce-bound full-row enforcement.
  const wrappedGeneric = bindTo('explore-x') + 'findings:\nmapped the affected files\n';
  assert(checkEvidenceShape('code-explorer', 'explore-x', wrappedGeneric, optsFor('explore-x')).ok === true,
    '#836-T1f: a generic registry token wrapped onto the next line must close, got '
    + JSON.stringify(checkEvidenceShape('code-explorer', 'explore-x', wrappedGeneric, optsFor('explore-x'))));
});

// ---------------------------------------------------------------------------
// #836-T2: ABSENCE STAYS FAIL-CLOSED. The wrap tolerance is a continuation rule, not a licence to
// treat any nearby text as a value. The untouched OPEN-TIME SEED — the exact bytes seedEvidenceFile
// writes — must still refuse for every branch, and so must an empty value at end-of-file, an empty
// value followed by a blank line, and a body carrying no token at all.
// ---------------------------------------------------------------------------
scenario(() => {
  const NONCE = 'abc123def456';
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-836-seed-'));
  try {
    const planPath = path.join(tmp, 'workflow-plan.md');
    const rows = [
      ['s-tdd', 'tdd-guide', 'RED'],
      ['s-impl', 'implementer', 'change-type'],
      ['s-opt', 'metric-optimizer', 'metric_baseline'],
      ['s-explore', 'code-explorer', 'findings'],
      ['s-lookup', 'knowledge-lookup', 'findings'],
      ['s-arch', 'code-architect', 'files_to_create|files_to_modify'],
    ];
    fs.writeFileSync(planPath, [
      '## Nodes',
      '| id | role | depends_on | declared_write_set | cardinality | shape |',
      '| --- | --- | --- | --- | --- | --- |',
      ...rows.map(([id, role]) => '| ' + id + ' | ' + role + ' | — | — | 1 | sequence |'),
      '## Node Ledger',
      '| id | status |', '| --- | --- |',
      ...rows.map(([id]) => '| ' + id + ' | in_progress |'),
    ].join('\n'));

    for (const [id, role, expectedClass] of rows) {
      seedEvidenceFile(planPath, id, NONCE, role, false);
      const seeded = fs.readFileSync(path.join(tmp, '.cache', id + '.md'), 'utf8');
      const verdict = checkEvidenceShape(role, id, seeded,
        { expectedNonce: NONCE, expectedNodeId: id });
      assert(verdict.ok === false && verdict.kind === 'shape' && verdict.missingTokenClass === expectedClass,
        '#836-T2-seed: the untouched open-time seed for ' + role + ' must STILL refuse '
        + expectedClass + ' — an empty key followed by an `<!-- ... -->` comment or by EOF is not a '
        + 'wrapped value, got ' + JSON.stringify(verdict));
    }
  } finally {
    try { fs.rmSync(tmp, { recursive: true, force: true }); } catch (_) {}
  }

  const bind = 'evidence-binding: impl-x ' + NONCE + '\n';
  const opts = { expectedNonce: NONCE, expectedNodeId: 'impl-x' };

  // Empty value at END OF FILE — there is no following line to continue onto.
  const eof = checkEvidenceShape('implementer', 'impl-x', bind + 'tests-green: ', opts);
  assert(eof.ok === false && eof.missingTokenClass === 'change-type',
    '#836-T2a: an empty tier value at end-of-file still refuses, got ' + JSON.stringify(eof));

  // Empty value followed by a BLANK line — a blank line is not a continuation.
  const blank = checkEvidenceShape('implementer', 'impl-x', bind + 'tests-green:\n\n4118 green\n', opts);
  assert(blank.ok === false && blank.missingTokenClass === 'change-type',
    '#836-T2b: an empty tier value followed by a blank line still refuses — the continuation is the '
    + 'IMMEDIATELY following line only, got ' + JSON.stringify(blank));

  // Empty value followed by ANOTHER key line — a sibling key is not this token's value.
  const sibling = checkEvidenceShape('code-explorer', 'explore-x',
    'evidence-binding: explore-x ' + NONCE + '\nfindings:\nsources: docs/api.md\n',
    { expectedNonce: NONCE, expectedNodeId: 'explore-x' });
  assert(sibling.ok === false && sibling.missingTokenClass === 'findings',
    '#836-T2c: an empty token followed by a sibling `key:` line still refuses — a key line is never '
    + 'consumed as the previous token\'s wrapped value, got ' + JSON.stringify(sibling));

  // No token at all — the original genuine absence.
  const none = checkEvidenceShape('implementer', 'impl-x', bind + 'I changed some files.\n', opts);
  assert(none.ok === false && none.kind === 'shape' && none.missingTokenClass === 'change-type',
    '#836-T2d: a body with no verification tier at all still refuses change-type, got ' + JSON.stringify(none));

  // A BARE colon-less content token is NOT the documented presence-only form and must still refuse.
  // (T6b-bare / T7e-bare pin the same thing; restated here so the #836 loosening cannot be read as
  // a licence to canonicalise every bare token — only `findings_none` carries that documented form.)
  const bareTier = checkEvidenceShape('implementer', 'impl-x', bind + 'build-green\n', opts);
  assert(bareTier.ok === false && bareTier.missingTokenClass === 'change-type',
    '#836-T2e: a bare colon-less `build-green` is still refused — the bare-token normalisation is '
    + 'scoped to the documented presence-only token, got ' + JSON.stringify(bareTier));
  const bareRed = checkEvidenceShape('tdd-guide', 'tdd-x', 'RED\nred_baseline: ' + NONCE + '\n');
  assert(bareRed.ok === false && bareRed.missingTokenClass === 'RED',
    '#836-T2f: a bare colon-less `RED` is still refused, got ' + JSON.stringify(bareRed));

  // The anti-replay binding header is NOT a content token and keeps its exact two-field shape.
  const wrappedBinding = checkEvidenceShape('implementer', 'impl-x',
    'evidence-binding:\nimpl-x ' + NONCE + '\ntests-green: 4118 green\n', opts);
  assert(wrappedBinding.ok === false && wrappedBinding.missingTokenClass === 'evidence-binding',
    '#836-T2g: the evidence-binding anti-replay header stays byte-exact — the wrap tolerance covers '
    + 'CONTENT tokens, never the identity header, got ' + JSON.stringify(wrappedBinding));
});

// ---------------------------------------------------------------------------
// #836-T3: the END-TO-END reproduction. runVerifyEvidence (the same checkEvidenceShape call the
// close paths make, reason `evidence_shape_failed`) accepts the wrapped tier off disk, and still
// refuses a body that genuinely carries no tier.
// ---------------------------------------------------------------------------
scenario(() => {
  const NONCE = 'abcdef123456';
  const mkFixture = (body) => {
    const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-836-verify-'));
    const cacheDir = path.join(tmp, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    fs.writeFileSync(path.join(cacheDir, 'barrier-base-n1-impl'), NONCE + 'extra');
    fs.writeFileSync(path.join(cacheDir, 'n1-impl.md'), body);
    const planPath = path.join(tmp, 'workflow-plan.md');
    fs.writeFileSync(planPath, [
      '## Nodes',
      '| id | role | depends_on | declared_write_set | cardinality | shape |',
      '| --- | --- | --- | --- | --- | --- |',
      '| n1-impl | implementer | — | scripts/foo.js | 1 | sequence |',
      '## Node Ledger',
      '| id | status |', '| --- | --- |', '| n1-impl | in_progress |',
    ].join('\n'));
    return { tmp, planPath };
  };
  const verify = (planPath) => runVerifyEvidence({
    planPath, project: 'issue-836', nodeId: 'n1-impl',
    readFile: (p) => fs.readFileSync(p, 'utf8'),
    cacheExists: (p) => fs.existsSync(p),
  });

  const good = mkFixture('evidence-binding: n1-impl ' + NONCE + '\ntests-green:\n'
    + 'node scripts/test-adaptive-node.js — 4118 assertions green\n');
  try {
    const r = verify(good.planPath);
    assert(r.result === 'ok',
      '#836-T3a: END-TO-END — a wrapped `tests-green` value must no longer raise '
      + 'evidence_shape_failed; the round-trip that cost a 5.9m re-dispatch is gone, got ' + JSON.stringify(r));
  } finally { try { fs.rmSync(good.tmp, { recursive: true, force: true }); } catch (_) {} }

  const bad = mkFixture('evidence-binding: n1-impl ' + NONCE + '\nI changed some files.\n');
  try {
    const r = verify(bad.planPath);
    assert(r.result === 'refuse' && r.reason === 'evidence_shape_failed' && r.missingTokenClass === 'change-type',
      '#836-T3b: END-TO-END control — a body with no tier at all still refuses '
      + 'evidence_shape_failed/change-type (absence stays fail-closed), got ' + JSON.stringify(r));
  } finally { try { fs.rmSync(bad.tmp, { recursive: true, force: true }); } catch (_) {} }
});

// ---------------------------------------------------------------------------
// #836-T4: evidenceTokenValue — the reader behind the schema-2 review required-token loop
// (`review_evidence_token_missing`). This is refusal reproduction (B): a reviewer wrote the bare
// documented `findings_none` with no colon and the gate refused a correct, complete review.
// ---------------------------------------------------------------------------
scenario(() => {
  assert(typeof evidenceTokenValue === 'function',
    '#836-T4-export: evidenceTokenValue must be exported so the review token contract is pinnable '
    + 'directly (the required-token loop is otherwise reachable only through a full schema-2 '
    + 'review-context fixture), got ' + typeof evidenceTokenValue);
  if (typeof evidenceTokenValue !== 'function') return;

  const nonEmpty = (v) => v !== null && v !== undefined && String(v).trim() !== '';

  // (B) THE REPRODUCTION — the bare documented presence-only token, alone on its line.
  assert(nonEmpty(evidenceTokenValue('domain_outcome: approved\nfindings_none\n', 'findings_none')),
    '#836-T4a: a BARE `findings_none` (no colon) must resolve to its canonical value — the '
    + 'documented presence-only form carries its meaning in its presence, got '
    + JSON.stringify(evidenceTokenValue('domain_outcome: approved\nfindings_none\n', 'findings_none')));

  // Indented and trailing-whitespace variants of the same bare form.
  assert(nonEmpty(evidenceTokenValue('  findings_none  \n', 'findings_none')),
    '#836-T4b: an indented / whitespace-padded bare `findings_none` resolves too, got '
    + JSON.stringify(evidenceTokenValue('  findings_none  \n', 'findings_none')));

  // The colon form is unchanged (back-compat with every shipped fixture).
  assert(evidenceTokenValue('findings_none: true\n', 'findings_none') === 'true',
    '#836-T4c: the canonical `findings_none: true` form is unchanged, got '
    + JSON.stringify(evidenceTokenValue('findings_none: true\n', 'findings_none')));

  // WRAPPED value — the same continuation rule the shape checker uses.
  assert(evidenceTokenValue('gate_claim:\nthe code candidate is approved\n', 'gate_claim')
    === 'the code candidate is approved',
  '#836-T4d: a review token value wrapped onto the next line resolves to that value, got '
    + JSON.stringify(evidenceTokenValue('gate_claim:\nthe code candidate is approved\n', 'gate_claim')));

  // INDENTED token line.
  assert(evidenceTokenValue('    domain_outcome: approved\n', 'domain_outcome') === 'approved',
    '#836-T4e: an indented review token resolves — the token is read anywhere in the body, got '
    + JSON.stringify(evidenceTokenValue('    domain_outcome: approved\n', 'domain_outcome')));

  // last-match-wins is preserved (a corrected re-statement still wins).
  assert(evidenceTokenValue('domain_outcome: rejected\ndomain_outcome: approved\n', 'domain_outcome')
    === 'approved',
  '#836-T4f: last-match-wins is preserved, got '
    + JSON.stringify(evidenceTokenValue('domain_outcome: rejected\ndomain_outcome: approved\n', 'domain_outcome')));

  // ---- FAIL-CLOSED ----
  // Genuine absence.
  assert(!nonEmpty(evidenceTokenValue('domain_outcome: approved\n', 'findings_none')),
    '#836-T4g: a body that never mentions the token still yields no value (absence stays '
    + 'fail-closed), got ' + JSON.stringify(evidenceTokenValue('domain_outcome: approved\n', 'findings_none')));

  // A bare token that is NOT the documented presence-only form carries no value.
  assert(!nonEmpty(evidenceTokenValue('finding_json\n', 'finding_json')),
    '#836-T4h: a bare `finding_json` is NOT canonicalisable — its meaning IS its JSON payload, got '
    + JSON.stringify(evidenceTokenValue('finding_json\n', 'finding_json')));
  assert(!nonEmpty(evidenceTokenValue('gate_claim\n', 'gate_claim')),
    '#836-T4i: a bare `gate_claim` carries no value, got '
    + JSON.stringify(evidenceTokenValue('gate_claim\n', 'gate_claim')));

  // The bare form must be the WHOLE line — a mention inside prose is not a token.
  assert(!nonEmpty(evidenceTokenValue('we recorded findings_none for this gate\n', 'findings_none')),
    '#836-T4j: a prose mention of the token is not the bare token form, got '
    + JSON.stringify(evidenceTokenValue('we recorded findings_none for this gate\n', 'findings_none')));
  assert(!nonEmpty(evidenceTokenValue('no_findings_none_here\n', 'findings_none')),
    '#836-T4k: the bare-token match is word-exact, not a substring, got '
    + JSON.stringify(evidenceTokenValue('no_findings_none_here\n', 'findings_none')));

  // An empty token whose next line is a sibling KEY must stay empty, and the sibling must be read
  // as its own token — the continuation must never swallow the next key.
  const twoKeys = 'gate_claim:\ngate_surface: full code candidate\n';
  assert(!nonEmpty(evidenceTokenValue(twoKeys, 'gate_claim')),
    '#836-T4l: an empty token followed by a sibling key stays EMPTY, got '
    + JSON.stringify(evidenceTokenValue(twoKeys, 'gate_claim')));
  assert(evidenceTokenValue(twoKeys, 'gate_surface') === 'full code candidate',
    '#836-T4m: and the sibling key still reads as its own token, got '
    + JSON.stringify(evidenceTokenValue(twoKeys, 'gate_surface')));

  // An empty token at end-of-file, and one followed by a comment, stay empty.
  assert(!nonEmpty(evidenceTokenValue('gate_claim:\n', 'gate_claim')),
    '#836-T4n: an empty token at end-of-file stays empty');
  assert(!nonEmpty(evidenceTokenValue('gate_claim:\n<!-- gate_claim: paste here -->\n', 'gate_claim')),
    '#836-T4o: an empty token followed by an `<!-- ... -->` seed comment stays empty, got '
    + JSON.stringify(evidenceTokenValue('gate_claim:\n<!-- gate_claim: paste here -->\n', 'gate_claim')));
});

// ---------------------------------------------------------------------------
// #836-T5: the WRITER normalises on record. Where a canonical serialization genuinely matters
// (machine-read receipts), record-evidence rewrites the token into canonical form instead of a
// later reader refusing after the fact. An already-canonical body is written BYTE-IDENTICAL, and a
// key that is not an evidence token is never touched.
// ---------------------------------------------------------------------------
scenario(() => {
  const record = (nodeId, stdinContent) => {
    const written = {};
    const result = runRecordEvidence({
      planPath: '/fake/kaola-workflow/issue-836/workflow-plan.md',
      statePath: '/fake/kaola-workflow/issue-836/workflow-state.md',
      project: 'issue-836', nodeId, stdinContent,
      writeFile: (p, c) => { written[p] = c; },
      mkdirp: () => {},
    });
    const key = Object.keys(written).find(k => k.includes('.cache/' + nodeId + '.md'));
    return { result, body: key === undefined ? null : written[key] };
  };

  // A wrapped tier is persisted CANONICAL — one line, `token: value`.
  const wrapped = record('impl-core', 'tests-green:\n4118 assertions green\n');
  assert(wrapped.result.result === 'ok', '#836-T5a: record-evidence accepts the wrapped body');
  assert(wrapped.body !== null && /^tests-green: 4118 assertions green$/m.test(wrapped.body),
    '#836-T5a: record-evidence must persist the wrapped token in canonical one-line form, got '
    + JSON.stringify(wrapped.body));
  assert(wrapped.body !== null && !/^tests-green:[ \t]*$/m.test(wrapped.body),
    '#836-T5b: the dangling empty `tests-green:` line must not survive the normalisation, got '
    + JSON.stringify(wrapped.body));

  // The bare documented presence-only token is persisted with its canonical value.
  const bare = record('review-gate', 'domain_outcome: approved\nfindings_none\n');
  assert(bare.result.result === 'ok', '#836-T5c: record-evidence accepts the bare-token body');
  assert(bare.body !== null && /^findings_none: true$/m.test(bare.body),
    '#836-T5c: a bare `findings_none` must be persisted as the canonical `findings_none: true`, got '
    + JSON.stringify(bare.body));

  // An already-canonical body is written byte-identical — normalisation is a no-op, never a rewrite.
  const canonical = 'evidence-binding: impl-core deadbeef1234\ntests-green: 4118 assertions green\n';
  const untouched = record('impl-core', canonical);
  assert(untouched.body === canonical,
    '#836-T5d: an already-canonical body is written byte-identical, got ' + JSON.stringify(untouched.body));

  // A key that is not an evidence token is never rewritten — the normaliser is token-scoped, not a
  // blanket line-joiner over the agent's prose.
  const prose = 'evidence-binding: impl-core deadbeef1234\ntests-green: 4118 green\nSummary:\nrewrote the matcher\n';
  const proseOut = record('impl-core', prose);
  assert(proseOut.body === prose,
    '#836-T5e: a non-token `key:` line and its following prose line are left exactly as written, got '
    + JSON.stringify(proseOut.body));
});

// ---------------------------------------------------------------------------
// #836-T6: ARCHIVED-CORPUS NON-REGRESSION — no existing green evidence file becomes refused.
//
// The guard is structural rather than a frozen list: `baselineShapeGreen` is a verbatim copy of the
// pre-#836 matchers (the 3-arg / no-nonce call shape, which is what an archived artifact is read
// under). For EVERY archived evidence file that the OLD checker accepted, the shipped checker must
// still accept it. The loosening may only ever ADD acceptances, never remove one.
// ---------------------------------------------------------------------------
scenario(() => {
  const { DELEGATION_OUTCOME_VOCABULARY } = require('./kaola-workflow-adaptive-schema');
  const esc = (s) => String(s).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');

  // Verbatim pre-#836 semantics: column-0 token key, non-whitespace value on the SAME line.
  function baselineShapeGreen(role, content) {
    const c = content || '';
    const dm = c.match(/^delegation_outcome:[ \t]*(\S+)[ \t]*$/m);
    if (dm && !DELEGATION_OUTCOME_VOCABULARY.includes(dm[1].toLowerCase())) return false;
    if (role === 'main-session-gate') {
      if (!c.trim()) return false;
      const vm = c.match(/^verdict:[ \t]*([A-Za-z-]+)[ \t]*$/gm);
      const last = vm ? vm[vm.length - 1].replace(/^verdict:[ \t]*/, '').trim().toLowerCase() : null;
      if (last !== 'pass' && last !== 'fail') return false;
      return /^instrumentation:[ \t]*(\S+)[ \t]*$/m.test(c);
    }
    if (c.trim().startsWith('n/a')) return true;
    if (role === 'tdd-guide') return !!c && /^RED:[ \t]*(\S.*)$/m.test(c);
    if (role === 'implementer') {
      return !!c && /^(?:tests-green|regression-green|build-green|smoke-integration):[ \t]*(\S.*)$/m.test(c);
    }
    if (role === 'metric-optimizer') {
      return !!c && ['metric_baseline', 'metric_final', 'iterations_used', 'regression-green']
        .every(t => new RegExp('^' + t + ':[ \\t]*(\\S.*)$', 'm').test(c));
    }
    if (!c.trim()) return false;
    const row = (ROLE_TOKEN_REGISTRY && ROLE_TOKEN_REGISTRY[role]) || null;
    if (row) {
      for (const tokenClass of row) {
        if (tokenClass === 'evidence-binding') continue;
        const alts = tokenClass.split('|');
        if (!alts.some(a => new RegExp('^' + esc(a) + ':', 'm').test(c))) continue;
        if (!alts.some(a => new RegExp('^' + esc(a) + ':[ \\t]*(\\S.*)$', 'm').test(c))) return false;
      }
    }
    return true;
  }

  const archiveDir = path.join(__dirname, '..', 'kaola-workflow', 'archive');
  if (!fs.existsSync(archiveDir)) {
    assert(false, '#836-T6: the archived-run corpus is missing at ' + archiveDir
      + ' — the "no green file becomes refused" proof cannot go vacuous');
    return;
  }

  let scanned = 0;
  let baselineGreen = 0;
  const regressions = [];
  for (const project of fs.readdirSync(archiveDir).sort()) {
    const planPath = path.join(archiveDir, project, 'workflow-plan.md');
    if (!fs.existsSync(planPath)) continue;
    let nodes;
    try { nodes = planValidator.parseNodes(fs.readFileSync(planPath, 'utf8')); } catch (_) { continue; }
    if (!Array.isArray(nodes)) continue;
    for (const node of nodes) {
      const cachePath = path.join(archiveDir, project, '.cache', node.id + '.md');
      if (!fs.existsSync(cachePath)) continue;
      const content = fs.readFileSync(cachePath, 'utf8');
      scanned++;
      if (!baselineShapeGreen(node.role, content)) continue;
      baselineGreen++;
      let verdict;
      try { verdict = checkEvidenceShape(node.role, node.id, content); }
      catch (error) { verdict = { ok: false, missingTokenClass: 'threw:' + error.message }; }
      if (verdict.ok !== true && regressions.length < 12) {
        regressions.push(project + '/' + node.id + ' (' + node.role + ') → ' + verdict.missingTokenClass);
      } else if (verdict.ok !== true) {
        regressions.push('…');
      }
    }
  }

  assert(scanned >= 900,
    '#836-T6a: the archived corpus must be non-trivially populated so this proof cannot pass '
    + 'vacuously — scanned ' + scanned + ' evidence files');
  assert(baselineGreen >= 900,
    '#836-T6b: the archived corpus must contain a large green population — ' + baselineGreen
    + ' of ' + scanned + ' were accepted by the pre-#836 matchers');
  assert(regressions.length === 0,
    '#836-T6c: NO existing green archived evidence file may become refused — ' + regressions.length
    + ' regressed: ' + regressions.slice(0, 12).join('; '));
});

// ===========================================================================
// #838-PASS-INVARIANT — the premise the re-plan entry predicate leans on, made checkable.
//
// The shape_refutation entry may proceed over a journal whose attempts all settled PASSED. That
// is only sound because a settled PASS is STRUCTURALLY not a repair authority: the journal
// validator refuses any pass attempt that names a repair writer, a consumer, or a rebind. If that
// ever loosened, "an all-passed journal carries nothing to consume" would silently become false
// and the entry would be dodging a live authority. Pinned bidirectionally — the clean pass is
// accepted, each of the three repair-authority shapes is refused — so this is a proof, not a claim.
// ===========================================================================
scenario(() => {
  const crypto = require('crypto');
  const hash = 'a'.repeat(64);
  const gate = canonicalLogicalGateIdentity({ kind: 'sequence', id: 'review', origin: ['writer'], members: ['review'] });
  const generations = [{ member: 'review', nonce: 'passnonce1234' }];
  const candidate = 'b'.repeat(64);
  const body = 'evidence-binding: review passnonce1234\nverdict: pass\nfindings_blocking: 0\n';
  const passAttempt = {
    attempt_id: 'review:1', ordinal: 1, plan_hash: hash, logical_gate: gate,
    transaction_key: crypto.createHash('sha256').update(JSON.stringify({ plan_hash: hash,
      logical_gate_key: gate.key, candidate_digest: candidate, generations })).digest('hex'),
    candidate_digest: candidate, candidate_declared: {}, candidate_residue_digest: 'd'.repeat(64),
    generations, settlement_command: 'close-node', outcome: 'pass', reason: null,
    receipts: [{ node_id: 'review', generation: 'passnonce1234', body,
      receipt_sha256: crypto.createHash('sha256').update(body).digest('hex'),
      effective_pass: true, verdict: 'pass', findings_blocking: 0 }],
    findings: [], route_candidates: [], lifecycle_settled: true,
    repair: { selected_writer: null, settled: null }, rebind: [], consumed_by: null,
  };
  const journalOf = attempt => ({ schema_version: 1, plan_hash: hash, attempts: [attempt] });

  assert(validateReviewJournal(journalOf(passAttempt), hash).ok === true,
    '#838-PASS-INVARIANT: a settled PASS with no repair authority is a valid journal: '
      + JSON.stringify(validateReviewJournal(journalOf(passAttempt), hash)));

  const withWriter = validateReviewJournal(journalOf({ ...passAttempt,
    repair: { selected_writer: 'writer', settled: null } }), hash);
  assert(withWriter.ok === false,
    '#838-PASS-INVARIANT: a PASS naming a repair writer must be refused, got ' + JSON.stringify(withWriter));

  const withConsumer = validateReviewJournal(journalOf({ ...passAttempt, consumed_by: 'writer' }), hash);
  assert(withConsumer.ok === false,
    '#838-PASS-INVARIANT: a PASS naming a consumer must be refused, got ' + JSON.stringify(withConsumer));

  const withRebind = validateReviewJournal(journalOf({ ...passAttempt,
    repair: { selected_writer: 'writer', settled: true },
    producer_bindings: { writer: { baseline: 'c'.repeat(40), anchored_ref: 'c'.repeat(40),
      open_token: 'c'.repeat(40), generation: 'ccccccccccccc', ref: 'refs/kaola-workflow/barrier/x/writer' } },
    rebind: [{ generation: 1, base_before: 'c'.repeat(40), base_after: 'e'.repeat(40),
      candidate_digest: candidate, candidate_declared: {}, producer_bindings: {}, absorbed: [],
      attributed_to: [], settled: true, aborted: false }] }), hash);
  assert(withRebind.ok === false,
    '#838-PASS-INVARIANT: a PASS carrying a rebind must be refused, got ' + JSON.stringify(withRebind));
});

// ===========================================================================
// #838-ROUTE — the deviation-route table. A barrier/ledger refusal that fires because the
// intended action falls OUTSIDE the frozen shape must NAME the legal verb in a typed `route:`
// field; leaving the operator to infer it from prose is what turns a recoverable refusal into a
// dead end. The routes are stamped at the ONE emit-time decorator (decorateOperatorHint), so a
// new emit site inherits its route for free and none of the many close_transition_disallowed /
// node_not_in_ledger emit sites has to be touched.
//
// The mapping is DERIVED from the barrier reason precedence the plan validator already owns, so
// the two can never drift:
//   write_set_overflow | write_set_granularity | lockfile_write | mirror_write | count_bump
//                              -> revert-overflow   (discard the out-of-set writes)
//   unattributed_write         -> amend-surface     (attribute + re-review them instead)
//   sensitive_write_unreviewed -> shape_refutation  (the legal cure is ADDING a security-reviewer
//                                                    gate, which is a spine change, not a node fix)
//   foreign_archive            -> NO route          (never legal under any verb)
//
// The negative arms are load-bearing: a `route` field that is always present carries no
// information. Enforcement must be bidirectional or the field is decoration.
// ===========================================================================
scenario(() => {
  const routed = [
    { reason: 'write_set_overflow', route: 'revert-overflow' },
    { reason: 'write_set_granularity', route: 'revert-overflow' },
    { reason: 'lockfile_write', route: 'revert-overflow' },
    { reason: 'mirror_write', route: 'revert-overflow' },
    { reason: 'count_bump', route: 'revert-overflow' },
    { reason: 'unattributed_write', route: 'amend-surface' },
    { reason: 'sensitive_write_unreviewed', route: 'shape_refutation' },
  ];
  for (const tc of routed) {
    const out = decorateOperatorHint({ result: 'refuse', reason: tc.reason, nodeId: 'w1' });
    assert(out.route === tc.route,
      '#838-ROUTE[' + tc.reason + ']: the out-of-shape refusal must carry route "' + tc.route
        + '", got ' + JSON.stringify(out.route));
    assert(typeof out.operator_hint === 'string' && out.operator_hint.length > 0,
      '#838-ROUTE[' + tc.reason + ']: ...alongside the operator hint, which is unchanged');
  }

  // NEGATIVE 1 — foreign_archive has no legal verb: writing another run's archive is never
  // curable by revert-overflow, amend-surface, or a reshape. It must carry NO route.
  const archive = decorateOperatorHint({ result: 'refuse', reason: 'foreign_archive', nodeId: 'w1' });
  assert(archive.route === undefined,
    '#838-ROUTE: foreign_archive names no legal verb and must carry NO route, got '
      + JSON.stringify(archive.route));

  // NEGATIVE 2 — a refusal that is not an out-of-shape deviation at all gains nothing.
  const unrelated = decorateOperatorHint({ result: 'refuse', reason: 'plan_missing' });
  assert(unrelated.route === undefined,
    '#838-ROUTE: a non-deviation refusal must carry NO route, got ' + JSON.stringify(unrelated.route));

  // NEGATIVE 3 — a success envelope gains neither a hint nor a route. Presence of either is
  // itself the "there is a next step" signal.
  const okEnv = decorateOperatorHint({ result: 'ok', nodeId: 'n1' });
  assert(okEnv.route === undefined && okEnv.operator_hint === undefined,
    '#838-ROUTE: a success envelope must gain neither operator_hint nor route');

  // IDEMPOTENT — exactly like operator_hint: a route a callee already decided is never
  // overwritten by the table (the callee knows the concrete situation; the table is the default).
  const preset = decorateOperatorHint({ result: 'refuse', reason: 'write_set_overflow',
    nodeId: 'w1', route: 'reexpand-open' });
  assert(preset.route === 'reexpand-open',
    '#838-ROUTE: an existing route must not be overwritten, got ' + JSON.stringify(preset.route));
});

// ===========================================================================
// #835 — THE EXPANSION POINT IS OFF THE SERIAL-OPEN SURFACE.
//
// An expansion point holds NO work of its own: it is opened by the `expand-open` TRANSACTION, which
// composes and opens its whole frontier, and it is never dispatched as an agent. next-action already
// keeps it off `readyPending` and `speculativePending` for exactly that reason — but `nextNode` was
// literally `readySet[0]`, and BOTH serial open doors (`open-next`'s fallthrough and
// `close-and-open-next`'s fused advance) open whatever `nextNode` names. So the serial path opened the
// container, and then `expand-open` / `open-ready` / `expand-close` each refused `serial_node_live`
// over the point's OWN in_progress row — a wedge with no governed reset.
//
// The subtraction is ONE classification at the source, replacing three compensating exclusions:
//   * `nextNode` is drawn from the SERIAL-OPENABLE projection of readySet (points removed).
//     `readySet` / `allDone` / the stall refusal are UNCHANGED — pinned in scripts/test-next-action.js.
//   * `open-next` refuses a point BY CONSTRUCTION even when one is named explicitly; `expand-open`
//     stays the single entry.
//   * The three `_serialExclude` CALL SITES and the container-detection block are DELETED, so a point
//     whose row is somehow in_progress fences the guard like any other live serial node.
//
// The `serialExclude` MECHANISM itself is NOT deleted: `runReExpandOpen` still passes the SINK id
// through it so a discharged-point re-open is not refused over the very sink it invalidates. Both
// directions are pinned below — the call sites go, the plumbing stays.
// ===========================================================================
scenario(() => {
  const { runExpandOpen, runExpandClose } = require('./kaola-workflow-adaptive-node');
  const realNextAction835 = require('./kaola-workflow-next-action').computeNextAction;

  // --- (A) THE TWO SERIAL OPEN DOORS, driven through the REAL next-action. ----------------------
  // The next-action shell seam DELEGATES to the real computeNextAction over the live plan bytes, so
  // these are integration pins over the actual aggregator, not a hand-authored frontier.
  const NODES835 = [
    '| w1 | tdd-guide | — | scripts/x.js | 1 | sequence |',
    '| m1 | expansion-point | w1 | — | 1 | sequence |',
    '| done | finalize | m1 | CHANGELOG.md | 1 | sequence |',
  ];
  const STATE835 = '/p/workflow-state.md';
  // The ledger row for `id`, isolated from the same-id `## Nodes` row so a failure diagnostic quotes
  // the status that actually moved.
  const ledgerRow835 = (planText, id) => (String(planText).split('\n')
    .find(l => new RegExp('^\\| ' + id + ' \\| (pending|in_progress|complete|n/a) ').test(l)) || '<no ledger row>');
  const seamsA835 = (ledgerRows, extraFiles) => {
    const files = Object.assign({ [RS_PLAN_PATH]: makePlan(ledgerRows, NODES835), [STATE835]: makeState() },
      extraFiles || {});
    return {
      files,
      planPath: RS_PLAN_PATH, statePath: STATE835, project: 'p',
      shell: (sp) => {
        const b = path.basename(sp);
        if (b === 'kaola-workflow-next-action.js') {
          return Object.assign({ exitCode: 0 },
            realNextAction835(files[RS_PLAN_PATH], { resolveModel: () => 'sonnet' }));
        }
        if (b === 'kaola-workflow-commit-node.js') return { exitCode: 0, result: 'ok', selectorCheck: {} };
        return { exitCode: 0, ok: true, result: 'ok' };
      },
      readFile: (fp) => { if (fp in files) return files[fp]; throw new Error('ENOENT ' + fp); },
      writeFile: (fp, c) => { files[fp] = c; },
      cacheExists: (fp) => fp in files,
      mkdirp: () => {},
    };
  };

  // A1 — open-next with NO --node-id and the point the ONLY ready node. The serial door must not open
  // it, and must not mutate the ledger or record a baseline for it.
  {
    const h = seamsA835(['| w1 | complete | |', '| m1 | pending | |', '| done | pending | |']);
    const r = runOpenNext({ planPath: h.planPath, statePath: h.statePath, project: h.project, nodeId: null,
      shell: h.shell, readFile: h.readFile, writeFile: h.writeFile, cacheExists: h.cacheExists });
    assert(!(r.opened && r.opened.id === 'm1'),
      '#835-A1: open-next must NEVER serial-open an expansion point — expand-open is the single '
      + 'entry, got ' + JSON.stringify({ result: r.result, reason: r.reason, opened: r.opened }));
    assert(r.result === 'refuse' && ['no_ready_node', 'expansion_point_not_openable'].includes(r.reason),
      '#835-A1: with nothing serial-openable left, open-next must return a TYPED refusal (the caller '
      + 'routes to expand-open off expansionPending), got ' + JSON.stringify({ result: r.result, reason: r.reason }));
    assert(/\| m1 \| pending \|/.test(h.files[RS_PLAN_PATH]),
      '#835-A1: ZERO MUTATION — the point ledger row must still be pending, got '
      + JSON.stringify(ledgerRow835(h.files[RS_PLAN_PATH], 'm1')));
  }

  // A2 — open-next asked for the point BY NAME. "Cannot open a point by construction" has to hold on
  // the explicit path too, or the fix is only a next-action ordering accident.
  {
    const h = seamsA835(['| w1 | complete | |', '| m1 | pending | |', '| done | pending | |']);
    const r = runOpenNext({ planPath: h.planPath, statePath: h.statePath, project: h.project, nodeId: 'm1',
      shell: h.shell, readFile: h.readFile, writeFile: h.writeFile, cacheExists: h.cacheExists });
    assert(r.result === 'refuse' && r.reason === 'expansion_point_not_openable',
      '#835-A2: `open-next --node-id <point>` must refuse with the typed reason '
      + 'expansion_point_not_openable, got ' + JSON.stringify({ result: r.result, reason: r.reason, opened: r.opened }));
    assert(/\| m1 \| pending \|/.test(h.files[RS_PLAN_PATH]),
      '#835-A2: ZERO MUTATION on the refusal');
  }

  // A3 CONTROL — the refusal is scoped to the POINT. A concrete node named by --node-id still opens,
  // so A2 discriminates the role rather than the explicit-target path as a whole.
  {
    const h = seamsA835(['| w1 | pending | |', '| m1 | pending | |', '| done | pending | |']);
    const r = runOpenNext({ planPath: h.planPath, statePath: h.statePath, project: h.project, nodeId: 'w1',
      shell: h.shell, readFile: h.readFile, writeFile: h.writeFile, cacheExists: h.cacheExists });
    assert(r.result === 'ok' && r.opened && r.opened.id === 'w1',
      '#835-A3 CONTROL: a concrete node still opens through the same door, got '
      + JSON.stringify({ result: r.result, reason: r.reason, opened: r.opened }));
  }

  // A4 — THE FUSED ADVANCE. Closing the node the point depends on must NOT advance INTO the point.
  // This is the exact production sequence that produced the wedge.
  {
    const h = seamsA835(['| w1 | in_progress | |', '| m1 | pending | |', '| done | pending | |'], {
      '/p/.cache/w1.md': 'RED: failing assertion before implementation\n'
        + 'GREEN: assertion passes after implementation\nthe test ran',
    });
    const r = runCloseAndOpenNext({ planPath: h.planPath, statePath: h.statePath, project: h.project,
      nodeId: 'w1', shell: h.shell, readFile: h.readFile, writeFile: h.writeFile, cacheExists: h.cacheExists });
    assert(r.result === 'ok' && r.closed === 'w1',
      '#835-A4 FIXTURE: the predecessor still closes normally, got ' + JSON.stringify(r));
    assert(!(r.opened && r.opened.id === 'm1'),
      '#835-A4: the fused advance must NEVER open the expansion point, got '
      + JSON.stringify({ opened: r.opened, reason: r.reason }));
    assert(r.opened === null && r.reason === 'frontier_blocked',
      '#835-A4: ...it reports the CLOSED-ONLY envelope with the already-shipped `frontier_blocked` '
      + 'marker — the exact word the plan-run skeleton documents for "a spine whose ready expansion '
      + 'points are never driven opens nothing, returns frontier_blocked" — so the executor routes to '
      + 'expand-open, got ' + JSON.stringify({ opened: r.opened, reason: r.reason }));
    assert(/\| m1 \| pending \|/.test(h.files[RS_PLAN_PATH]),
      '#835-A4: the point ledger row must still be pending after the advance, got '
      + JSON.stringify(ledgerRow835(h.files[RS_PLAN_PATH], 'm1')));
  }

  // --- (B) THE THREE EXCLUSIONS ARE GONE, and the MECHANISM they used still works. ---------------
  // Fixtures are the #759 injected-seam shape: nothing touches disk, and every refusal below is
  // attributable to the guard prologue alone (the point is ready and its prior record is settled).
  const PLAN835B = '/tmp/i835/kaola-workflow/issue-835/workflow-plan.md';
  const RS835B = '/tmp/i835/kaola-workflow/issue-835/.cache/' + RUNNING_SET_NAME;
  const SPINE835B = (ledgerRows) => ['# Plan', '',
    '## Meta', '', 'plan_form: spine', '',
    'expansion(m1):', '  milestone_goal: g', '  expected_surfaces: scripts/',
    '  join_constraints: none', '  review_class: code-reviewer', '',
    '## Nodes', '',
    '| id | role | depends_on | declared_write_set | cardinality | shape |',
    '|---|---|---|---|---|---|',
    '| probe | code-explorer | — | — | 1 | sequence |',
    '| m1 | expansion-point | probe | — | 1 | sequence |',
    '| done | finalize | m1 | — | 1 | sequence |', '',
    '## Node Ledger', '', '| id | status |', '|---|---|', ...ledgerRows, '',
    '## Expansion Records', '',
    'record(m1#1):', '  point: m1',
    '  grain: g', '  path: p', '  join: j', '  probe: pr', '  serializer: none',
    '  unit: a | code-explorer | — | — | co_open | —', '',
    'open(m1#1):', '  at: T', ''].join('\n');
  const COMP835 = {
    derivation: { grain: 'g', path: 'p', join: 'j', probe: 'pr', serializer: 'none' },
    units: [{ name: 'z1', role: 'code-explorer', model: 'standard', write_set: '', mode: 'co_open' }],
  };
  const seamsB835 = (content) => {
    const writes = [];
    return {
      planPath: PLAN835B, project: 'issue-835', writes,
      shell: () => ({ exitCode: 0, ok: true, result: 'ok' }),
      readFile: (fp) => {
        if (fp === RS835B) return '';
        if (fp === PLAN835B) return content;
        throw new Error('ENOENT: ' + fp);
      },
      writeFile: (fp, c) => { if (fp === PLAN835B) writes.push(c); },
      cacheExists: () => false, mkdirp: () => {}, now: () => 'T',
    };
  };
  // The point's OWN row is live; every other row is settled. Pre-subtraction the three call sites
  // excluded exactly this id, so the guard waved the transaction through.
  const POINT_LIVE835 = SPINE835B(['| probe | complete |', '| m1 | in_progress |',
    '| m1-r1-a | complete |', '| done | pending |']);
  // A PEER row is live and the point is pending — the shape the surviving mechanism serves.
  const PEER_LIVE835 = SPINE835B(['| probe | complete |', '| m1 | pending |',
    '| m1-r1-a | complete |', '| done | in_progress |']);

  // B1 — expand-open (site 2 deleted).
  {
    const s = seamsB835(POINT_LIVE835);
    const r = runExpandOpen({ ...s, nodeId: 'm1', composition: COMP835 });
    assert(r.result === 'refuse' && r.reason === 'serial_node_live',
      '#835-B1: with the point exclusion DELETED, expand-open over a live point row refuses like any '
      + 'other live serial node — the guard is back to its simple form, got '
      + JSON.stringify({ result: r.result, reason: r.reason }));
    assert(s.writes.length === 0, '#835-B1: a guard refusal must mutate NOTHING');
  }

  // B2 — expand-close (site 3 deleted).
  {
    const s = seamsB835(POINT_LIVE835);
    const r = runExpandClose({ ...s, nodeId: 'm1' });
    assert(r.result === 'refuse' && r.reason === 'serial_node_live',
      '#835-B2: with the point exclusion DELETED, expand-close over a live point row refuses too, got '
      + JSON.stringify({ result: r.result, reason: r.reason }));
    assert(s.writes.length === 0, '#835-B2: a guard refusal must mutate NOTHING');
  }

  // B3 — open-ready (site 1 deleted: the container-detection block that re-derived the exclusion
  // itself, for the top-up call that arrives with no `_serialExclude` on opts).
  {
    const s = seamsB835(POINT_LIVE835);
    const r = runOpenReady({ ...s, max: null, fanoutCapReadonly: 8 });
    assert(r.result === 'refuse' && r.reason === 'serial_node_live',
      '#835-B3: with the container-detection block DELETED, open-ready refuses over a live point row, '
      + 'got ' + JSON.stringify({ result: r.result, reason: r.reason }));
    assert(s.writes.length === 0, '#835-B3: a guard refusal must mutate NOTHING');
  }

  // B4 — THE MECHANISM SURVIVES. `runReExpandOpen` forwards the SINK id through `_serialExclude` so a
  // discharged-point re-open is not refused over the very sink it is invalidating. Deleting the
  // parameter (rather than the three call sites) would break re-expansion, so pin it directly.
  {
    const s = seamsB835(PEER_LIVE835);
    const r = runExpandOpen({ ...s, nodeId: 'm1', composition: COMP835, _serialExclude: ['done'] });
    assert(!(r.result === 'refuse' && r.reason === 'serial_node_live'),
      '#835-B4: an explicitly-passed `_serialExclude` must STILL suppress the named id — this is the '
      + 're-expansion path and it must not be collateral damage, got '
      + JSON.stringify({ result: r.result, reason: r.reason }));
  }

  // B5 CONTROL — the same fixture WITHOUT `_serialExclude` still refuses, so B4 is not vacuous and no
  // OTHER live serial node is being silently waved through.
  {
    const s = seamsB835(PEER_LIVE835);
    const r = runExpandOpen({ ...s, nodeId: 'm1', composition: COMP835 });
    assert(r.result === 'refuse' && r.reason === 'serial_node_live',
      '#835-B5 CONTROL: a live PEER serial node still refuses expand-open when nothing excludes it, '
      + 'got ' + JSON.stringify({ result: r.result, reason: r.reason }));
  }

  // --- (C) DELETED, NOT BYPASSED — source pins on both directions of the subtraction. ------------
  {
    const src835 = fs.readFileSync(path.join(__dirname, 'kaola-workflow-adaptive-node.js'), 'utf8');
    const bodyOf835 = (name) => {
      const start = src835.indexOf('\nfunction ' + name + '(');
      if (start < 0) return '';
      const end = src835.indexOf('\nfunction ', start + 1);
      return src835.slice(start, end < 0 ? src835.length : end);
    };
    const openReady835 = bodyOf835('runOpenReady');
    const expandOpen835 = bodyOf835('runExpandOpen');
    const expandClose835 = bodyOf835('runExpandClose');
    const reExpand835 = bodyOf835('runReExpandOpen');
    const prologue835 = bodyOf835('mutationGuardPrologue');
    assert(openReady835 && expandOpen835 && expandClose835 && reExpand835 && prologue835,
      '#835-C FIXTURE: every function body slice resolved');

    // GONE — the three call sites.
    assert(!/const containers = Object\.keys\(ledger\)/.test(openReady835),
      '#835-C1: runOpenReady no longer re-derives an expansion-point container exclusion (site 1 '
      + 'DELETED, not bypassed)');
    assert(!/\.concat\(containers\)/.test(openReady835),
      '#835-C1: ...and nothing concats a container list onto the serial exclusion');
    assert(!/opts\._serialExclude = /.test(expandOpen835),
      '#835-C2: runExpandOpen no longer writes its own node id onto opts._serialExclude (site 2 DELETED)');
    assert(!/opts\._serialExclude = /.test(expandClose835),
      '#835-C3: runExpandClose no longer writes its own node id onto opts._serialExclude (site 3 DELETED)');

    // SURVIVES — the mechanism and its one real caller.
    assert(/function coordinationRefusal\(coord, excl, serialExclude\)/.test(src835),
      '#835-C4: coordinationRefusal KEEPS its serialExclude parameter — the mechanism is not the '
      + 'compensation, only the three call sites were');
    assert(/cfg\.serialExclude/.test(prologue835),
      '#835-C4: mutationGuardPrologue still forwards cfg.serialExclude to the coordination layer');
    assert(/_serialExclude: sinkNode/.test(reExpand835),
      '#835-C4: runReExpandOpen still forwards the SINK id through _serialExclude — the surviving '
      + 'caller the subtraction must not break');
  }
});

// ===========================================================================
// #826 — THE FINALIZE DEVIATION ROUTE: a sink-owned final-fix lane with a typed
// attribution gate.
//
// THE TRAP BEING REMOVED. Finalization is the one phase where the orchestrator has LESS freedom
// than mid-run. The finalize prose prescribes a fix lane for a failed final validation; the fix
// lands; and the finalize attribution sweep then REFUSES it `unattributed_change`, because the
// sweep credits exactly two sources — the narrow allowband and `complete`-node declared write
// sets. On the planner's ordinary all-concrete spine every sanctioned exit is closed BY
// CONSTRUCTION (`amend-surface` wants an expansion-point row that shape has none of;
// `reopen-node` refuses `would_orphan_in_progress` over the live sink; re-plan wants a FAILED
// review attempt when every review PASSED; `revert-overflow` discards a new file rather than attributing it). The
// prescription manufactures the very refusal that blocks it.
//
// THE SHAPE OF THE FIX. Zero regulation on HOW the fix is produced (inline, or dispatched to
// whichever role fits — no justifier, no approval, no mandated mode); FULL regulation at the ONE
// commitment point where the fix enters the candidate: a new `final-fix-commit` verb writing a
// digest-bound, sink-owned register at `.cache/final-fixes.json`, which the sweep then reads as
// its THIRD attributed source.
//
// THE SCOPE WALL IS HARD, AND IT STAYS HARD. A finalize-time fix that touches PRODUCTION behavior
// is REFUSED `final_fix_production_surface`. There is no receipt, register field, or verifier that
// admits it — not "admitted behind a settled PASS", refused.
//
// WHY (R4, and it is the whole reason this is not an arbitrary restriction). ADR 0013's R4 is the
// meaning-vs-form discriminator: auto-remedy applies only to a NON-CANONICAL FORM of CORRECT
// CONTENT. A behavior change arriving after every reviewer is discharged is not bad form — it is a
// DEVIATION THAT IS ITSELF EVIDENCE, evidence that the certification standing over this candidate no
// longer describes it. Admitting it behind a re-certification receipt would LAUNDER that signal:
// the finalize register would become a place where a fact about the run ("this shipped uncertified
// work") is converted into a receipt saying the opposite. R4 always beats R3, so the deviation is
// reported, never repaired. Building the receipt would add exactly the re-certification machinery
// R4 exists to prevent, and would soften the one wall the ADR names as load-bearing.
//
// THE WALL IS NOT A DEAD END — THAT IS WHAT THE ROUTE IS FOR. The refusal carries a typed exit
// (`route`), so the trap the issue complained about is removed BY THE ROUTE, not by widening the
// scope. If no authority in the frozen plan can certify the change, the SHAPE is what is refuted,
// and re-plan is the recorded exit. Validation-apparatus paths (tests, fixtures, build/tooling glue,
// allowband docs) keep the cheap path: the bound green rerun receipt alone. The lane is not deleted;
// only the production widening is.
//
// WHAT THESE TESTS PIN, in priority order:
//   (A) every typed refusal, each ZERO-WRITE — the register must not exist, and the frozen plan /
//       git state must be byte-identical, after a refused call; INCLUDING that a production surface
//       refuses IDENTICALLY whether or not the submission carries a re-certification receipt (a
//       receipt cannot change a verdict nothing consults);
//   (B) the pure predicate the wall rests on — the surface CLASSIFIER, conservative by default (an
//       unrecognized path is production, a mixed entry is production as a whole) — plus the ABSENCE
//       of any re-certification verifier and the presence of the typed exit;
//   (C) the sweep's third source + the `route:` deviation fields, INCLUDING the negatives — a
//       register nobody can forge (any out-of-band edit, and any PRODUCTION-class entry however
//       well-formed, refuses its OWN typed reason rather than laundering the path), and NO
//       `final-fix-commit` route once the sink has pushed.
//
// THE PRISTINE (pre-push) BOUNDARY IS THE LANE'S HARD CLOSE and is pinned in both directions.
// After push the record is immutable history; recovery is a follow-up issue, never a rewrite.
// ===========================================================================
{
  const { execFileSync: exec826 } = require('child_process');
  const NODE_CLI_826 = path.join(__dirname, 'kaola-workflow-adaptive-node.js');
  const VALIDATOR_826 = path.join(__dirname, 'kaola-workflow-plan-validator.js');
  const REGISTER_REL_826 = path.join('kaola-workflow', 'issue-826', '.cache', 'final-fixes.json');

  // A minimal, REAL finalize fixture: a three-node all-concrete spine (writer → review → sink) with
  // the writer + review DISCHARGED and the sink LIVE (`in_progress`) — the exact state finalization
  // runs in. Committed on a feature branch so `git diff <base>...HEAD` is a real, non-empty branch
  // diff (the attribution sweep is vacuous when base === HEAD). No remote is created, so
  // `origin/<branch>` is unresolved and the sink reads PRISTINE.
  function makeFinalFixRepo826(opts) {
    opts = opts || {};
    const repoRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-826-finalfix-'));
    const project = 'issue-826';
    const projDir = path.join(repoRoot, 'kaola-workflow', project);
    const cacheDir = path.join(projDir, '.cache');
    fs.mkdirSync(cacheDir, { recursive: true });
    const planPath = path.join(projDir, 'workflow-plan.md');
    const body = [
      '# Workflow Plan — issue-826', '',
      '## Meta', 'labels: area:scripts', 'sink: CHANGELOG.md', '',
      '## Nodes', '',
      '| id | role | depends_on | declared_write_set | cardinality | shape |',
      '| --- | --- | --- | --- | --- | --- |',
      '| impl     | tdd-guide     | —      | src/app.js | 1 | sequence |',
      '| review   | code-reviewer | impl   | —          | 1 | sequence |',
      '| finalize | finalize      | review | —          | 1 | sequence |', '',
      '## Node Ledger', '',
      '| id | status |', '| --- | --- |',
      '| impl | complete |',
      '| review | complete |',
      '| finalize | ' + (opts.sinkStatus || 'in_progress') + ' |', '',
    ].join('\n') + '\n';
    fs.writeFileSync(planPath, body);
    const g = (args) => exec826('git',
      ['-C', repoRoot, '-c', 'user.email=kw@test', '-c', 'user.name=kw', '-c', 'commit.gpgsign=false', ...args],
      { encoding: 'utf8', stdio: ['ignore', 'pipe', 'ignore'] });
    g(['init']);
    g(['config', 'user.email', 'kw@test']);
    g(['config', 'user.name', 'kw']);
    g(['config', 'commit.gpgsign', 'false']);
    const froze = freezeLegacyFixture(exec826, 'node', VALIDATOR_826, planPath, { cwd: repoRoot, encoding: 'utf8' });
    assert(JSON.parse(froze.trim().split('\n').pop()).result !== 'refuse',
      '#826 FIXTURE: the finalize spine must freeze, got ' + froze);
    fs.writeFileSync(path.join(repoRoot, '.gitignore'), '.kw/\n');
    g(['add', '-A']);
    g(['commit', '-m', 'init']);
    const base = g(['rev-parse', '--abbrev-ref', 'HEAD']).trim();
    const branch = 'workflow/issue-826';
    g(['checkout', '-q', '-b', branch]);
    // The sink-progress probe resolves the run's branch from workflow-state.md (NEVER git HEAD — the
    // sink runs main-session-direct from the MAIN root). `noBranchPointer` removes it, which is the
    // three-valued probe's UNKNOWN input.
    fs.writeFileSync(path.join(projDir, 'workflow-state.md'),
      '# State\n' + (opts.noBranchPointer ? '' : 'branch: ' + branch + '\n'));
    // The writer's declared production file (attributed by `impl` being complete) + whatever extra
    // paths the scenario wants on the branch UNATTRIBUTED.
    fs.mkdirSync(path.join(repoRoot, 'src'), { recursive: true });
    fs.writeFileSync(path.join(repoRoot, 'src', 'app.js'), '// impl work\n');
    for (const extra of (opts.extraFiles || [])) {
      fs.mkdirSync(path.dirname(path.join(repoRoot, extra.path)), { recursive: true });
      fs.writeFileSync(path.join(repoRoot, extra.path), extra.body);
    }
    g(['add', '-A']);
    g(['commit', '-m', 'run work']);
    if (opts.sinkPushed) g(['update-ref', 'refs/remotes/origin/' + branch, 'HEAD']);
    return { repoRoot, project, projDir, cacheDir, planPath, base, branch, g };
  }
  function cleanup826(root) { try { fs.rmSync(root, { recursive: true, force: true }); } catch (_) {} }
  function runNode826(repoRoot, subArgs, stdin) {
    try {
      // The per-scenario vehicle for the adaptive-node CLI. Every scenario drives it as a CHAIN:
      // one process writes the ledger row, the barrier baseline and the .cache evidence and EXITS,
      // and the next re-derives the whole run state from those bytes with no shared heap.
      // spawn-class: durable-handoff
      const out = exec826('node', [NODE_CLI_826, ...subArgs],
        { cwd: repoRoot, encoding: 'utf8', input: stdin == null ? '' : stdin });
      return { exitCode: 0, ...JSON.parse(out.trim().split('\n').pop()) };
    } catch (e) {
      const status = (e.status == null) ? 1 : e.status;
      try { return { exitCode: status, ...JSON.parse(String(e.stdout || '').trim().split('\n').pop()) }; }
      catch (_) { return { exitCode: status, result: 'crash', raw: String(e.stdout || '') + String(e.stderr || '') }; }
    }
  }
  function candidateHash826(repoRoot, planPath) {
    // A fresh process recomputes the candidate hash over the on-disk tree; the value is written
    // into final-validation.md for the finalize-check process below to re-read.
    // spawn-class: durable-handoff
    const out = exec826('node', [VALIDATOR_826, planPath, '--candidate-hash', '--json'],
      { cwd: repoRoot, encoding: 'utf8' });
    return JSON.parse(out.trim().split('\n').pop()).validated_candidate_hash;
  }
  // The CONSUMER-mode (no package.json) finalize validation gate the sweep sits behind. Seeded AFTER
  // the tree settles so the recorded binding covers the tree --finalize-check recomputes over.
  function seedFinalValidation826(repoRoot, cacheDir, planPath) {
    fs.writeFileSync(path.join(cacheDir, 'final-validation.md'),
      'verdict: pass\nfindings_blocking: 0\nvalidated_candidate_hash: '
      + candidateHash826(repoRoot, planPath) + '\n');
  }
  // The EXACT subprocess cmdFinalize shells before any irreversible finalize side effect.
  function finalizeCheck826(repoRoot, planPath, base) {
    try {
      // The EXACT subprocess cmdFinalize shells before any irreversible finalize side effect: a
      // fresh process re-derives the verdict from durable state alone.
      // spawn-class: durable-handoff
      const out = exec826('node', [VALIDATOR_826, planPath, '--finalize-check', '--json', '--base', base],
        { cwd: repoRoot, encoding: 'utf8' });
      return { exitCode: 0, ...JSON.parse(out.trim().split('\n').pop()) };
    } catch (e) {
      const status = (e.status == null) ? 1 : e.status;
      try { return { exitCode: status, ...JSON.parse(String(e.stdout || '').trim().split('\n').pop()) }; }
      catch (_) { return { exitCode: status, result: 'crash', raw: String(e.stdout || '') + String(e.stderr || '') }; }
    }
  }
  function setLedger826(planPath, id, status) {
    const txt = fs.readFileSync(planPath, 'utf8');
    const start = txt.indexOf('## Node Ledger');
    const head = txt.slice(0, start), tail = txt.slice(start);
    const re = new RegExp('^(\\|\\s*' + id + '\\s*\\|\\s*)\\S+(\\s*\\|)', 'm');
    fs.writeFileSync(planPath, head + tail.replace(re, '$1' + status + '$2'));
  }
  function registerPath826(fx) { return path.join(fx.cacheDir, 'final-fixes.json'); }
  function readRegister826(fx) {
    try { return JSON.parse(fs.readFileSync(registerPath826(fx), 'utf8')); } catch (_) { return null; }
  }
  // A ZERO-WRITE witness: the frozen plan bytes, the register bytes (or its ABSENCE), the git HEAD
  // and the porcelain worktree status. A refused final-fix-commit must leave all four identical.
  function witness826(fx) {
    let register = null;
    try { register = fs.readFileSync(registerPath826(fx), 'utf8'); } catch (_) { register = null; }
    let status = '';
    try { status = fx.g(['status', '--porcelain']); } catch (_) { status = '(git status failed)'; }
    let head = '';
    try { head = fx.g(['rev-parse', 'HEAD']).trim(); } catch (_) { head = '(head unresolved)'; }
    return { plan: fs.readFileSync(fx.planPath, 'utf8'), register, status, head };
  }
  function assertZeroWrite826(fx, before, label) {
    const after = witness826(fx);
    assert(after.plan === before.plan, label + ': the frozen plan is byte-identical after the refusal');
    assert(after.register === before.register,
      label + ': the final-fix register is untouched (was ' + (before.register === null ? 'ABSENT' : 'present')
      + ', now ' + (after.register === null ? 'ABSENT' : 'present') + ')');
    assert(after.head === before.head, label + ': git HEAD did not move');
    assert(after.status === before.status, label + ': the worktree is unchanged');
  }
  // The stdin entry the verb records. One fix = one entry: the EXACT failed validation command, the
  // fix commit, the touched paths, and the green rerun receipt binding the two.
  function fixEntry826(fx, over) {
    const head = fx.g(['rev-parse', 'HEAD']).trim();
    const cmd = 'node scripts/test-final-fix-826.js';
    return Object.assign({
      failed_command: cmd,
      fix_commit: head,
      files: ['scripts/test-final-fix-826.js'],
      rerun: { command: cmd, exit_code: 0, candidate_hash: candidateHash826(fx.repoRoot, fx.planPath) },
      role: 'tdd-guide',
    }, over || {});
  }
  function finalFix826(fx, entry) {
    return runNode826(fx.repoRoot, ['final-fix-commit', '--project', fx.project, '--json', '--stdin'],
      JSON.stringify(entry));
  }
  const APPARATUS_FILE_826 = { path: 'scripts/test-final-fix-826.js', body: '// stale-test correction\n' };

  // -------------------------------------------------------------------------
  // #826-A — THE REFUSAL LADDER. THREE typed refusals, precedence-ordered, every one ZERO-WRITE.
  //   RUNG 1 is no longer one of them: `final_fix_sink_not_live` is converted to an advise under
  //     ADR 0013 R1/R3 and lives in the #826-ADV block below. A1 is deleted with it — see there.
  //   A2-A5 + A8 pin the lane's structural walls and are unaffected by the scope question.
  //   A6-A7 pin the SCOPE wall, and are RED against the shipped widened form: today a production
  //     surface refuses with a `recertification:` state that says which receipt would open it, and
  //     the two submissions (with / without a receipt) produce DIFFERENT refusals — which is the
  //     shipped code telling the operator that the right receipt is the cure.
  //   GREEN: each precondition names its own reason, a refused call is a pure no-op, and the scope
  //     wall is unconditional — a receipt is not consulted, so it cannot change the verdict.
  // -------------------------------------------------------------------------

  // A1 — DELETED, not moved. It ran this exact fixture and this exact call and asserted
  // `exitCode === 1 && result === 'refuse' && reason === 'final_fix_sink_not_live'` plus
  // assertZeroWrite826. Every one of those properties is now pinned by #826-ADV1 (the shape, and the
  // non-zero exit kept at its exact value) and #826-ADV2 (register absent + the same zero-write
  // witness) — on the same fixture, from the same call — except the two clauses the conversion
  // reverses. Nothing survived that was not already asserted twice, so keeping a trimmed A1 would be
  // a second name for ADV1 rather than a second proof.

  // A2 — AFTER THE SINK STARTED (the pristine boundary, the lane's HARD CLOSE). `origin/<branch>`
  // exists ⇒ the sink has pushed ⇒ the record is immutable history. Recovery after this point is a
  // follow-up issue, never a history rewrite. This one must STAY refused forever.
  scenario(() => {
    const fx = makeFinalFixRepo826({ sinkPushed: true, extraFiles: [APPARATUS_FILE_826] });
    const before = witness826(fx);
    const r = finalFix826(fx, fixEntry826(fx));
    assert(r.exitCode === 1 && r.result === 'refuse' && r.reason === 'final_fix_after_sink_started',
      '#826-A2: a pushed sink closes the lane with final_fix_after_sink_started, got '
      + JSON.stringify({ result: r.result, reason: r.reason }));
    assert(r.sink_progress === 'started',
      '#826-A2: the refusal reports the DERIVED sink progress that closed it, got '
      + JSON.stringify(r.sink_progress));
    assertZeroWrite826(fx, before, '#826-A2');
    cleanup826(fx.repoRoot);
  });

  // A2b — FAIL-CLOSED ON UNKNOWN. The sink-progress predicate is THREE-valued and only `pristine`
  // admits. With no `branch:` pointer the probe cannot derive anything, and the dangerous direction
  // (a false `pristine` after a push, which would rewrite a shipped run) is the one that must never
  // happen — so doubt collapses to a refusal, not an admission.
  scenario(() => {
    const fx = makeFinalFixRepo826({ noBranchPointer: true, extraFiles: [APPARATUS_FILE_826] });
    const before = witness826(fx);
    const r = finalFix826(fx, fixEntry826(fx));
    assert(r.exitCode === 1 && r.result === 'refuse' && r.reason === 'final_fix_after_sink_started',
      '#826-A2b: an UNDERIVABLE sink progress fails CLOSED onto the same wall, got '
      + JSON.stringify({ result: r.result, reason: r.reason }));
    assert(r.sink_progress === 'unknown',
      '#826-A2b: ...and says so — `unknown`, not a laundered `started`, got ' + JSON.stringify(r.sink_progress));
    assertZeroWrite826(fx, before, '#826-A2b');
    cleanup826(fx.repoRoot);
  });

  // A3 — NO GREEN RERUN. The register's whole claim is "this fix makes the failed validation pass";
  // a non-zero rerun exit code is that claim being false on its face.
  scenario(() => {
    const fx = makeFinalFixRepo826({ extraFiles: [APPARATUS_FILE_826] });
    const before = witness826(fx);
    const entry = fixEntry826(fx);
    entry.rerun.exit_code = 1;
    const r = finalFix826(fx, entry);
    assert(r.exitCode === 1 && r.result === 'refuse' && r.reason === 'final_fix_unverified',
      '#826-A3: a RED rerun receipt refuses final_fix_unverified, got '
      + JSON.stringify({ result: r.result, reason: r.reason }));
    assertZeroWrite826(fx, before, '#826-A3');
    cleanup826(fx.repoRoot);
  });

  // A4 — THE RERUN MUST BIND THE EXACT FAILED COMMAND. A receipt for some OTHER (easier) command is
  // the classic rubber stamp: it proves something passed, never that the thing that failed passes.
  scenario(() => {
    const fx = makeFinalFixRepo826({ extraFiles: [APPARATUS_FILE_826] });
    const before = witness826(fx);
    const entry = fixEntry826(fx);
    entry.rerun.command = 'node --version';
    const r = finalFix826(fx, entry);
    assert(r.exitCode === 1 && r.result === 'refuse' && r.reason === 'final_fix_unverified',
      '#826-A4: a rerun receipt for a DIFFERENT command refuses final_fix_unverified, got '
      + JSON.stringify({ result: r.result, reason: r.reason }));
    assertZeroWrite826(fx, before, '#826-A4');
    cleanup826(fx.repoRoot);
  });

  // A5 — THE RERUN MUST BIND THE POST-FIX CANDIDATE. The receipt is recorded against a candidate
  // hash; if the tree has moved since, the green run no longer describes what is about to ship. This
  // is the "digest-bound" half of the register — without it the entry is a note, not evidence.
  scenario(() => {
    const fx = makeFinalFixRepo826({ extraFiles: [APPARATUS_FILE_826] });
    const entry = fixEntry826(fx);          // hash captured HERE...
    fs.writeFileSync(path.join(fx.repoRoot, 'src', 'app.js'), '// impl work, moved on\n'); // ...tree moves
    const before = witness826(fx);
    const r = finalFix826(fx, entry);
    assert(r.exitCode === 1 && r.result === 'refuse' && r.reason === 'final_fix_unverified',
      '#826-A5: a rerun receipt bound to a STALE candidate refuses final_fix_unverified, got '
      + JSON.stringify({ result: r.result, reason: r.reason }));
    assertZeroWrite826(fx, before, '#826-A5');
    cleanup826(fx.repoRoot);
  });

  // A6 — PRODUCTION SURFACE: THE HARD WALL. A finalize-time fix that touches production behavior is
  // REFUSED, zero-write. Under R4 that change is a DEVIATION THAT IS ITSELF EVIDENCE — evidence that
  // the standing certification no longer describes the candidate — so it is REPORTED, never repaired,
  // and never converted into an admission. The refusal names the production path(s) that triggered it
  // and carries the typed exit, so the wall is a fork in the road rather than a dead end.
  scenario(() => {
    const fx = makeFinalFixRepo826({ extraFiles: [APPARATUS_FILE_826] });
    const before = witness826(fx);
    const entry = fixEntry826(fx, { files: ['src/app.js'] });
    const r = finalFix826(fx, entry);
    assert(r.exitCode === 1 && r.result === 'refuse' && r.reason === 'final_fix_production_surface',
      '#826-A6: a production-surface entry refuses final_fix_production_surface, got '
      + JSON.stringify({ result: r.result, reason: r.reason }));
    assert(Array.isArray(r.production_paths) && r.production_paths.includes('src/app.js'),
      '#826-A6: ...and names the production path(s) that triggered it, got '
      + JSON.stringify(r.production_paths));
    // THE WALL IS UNCONDITIONAL: there is no re-certification state to report, because no receipt
    // state can change this verdict. A `recertification` discriminator on the refusal is the residue
    // of the widening — it tells the operator a receipt is the cure, which is exactly the laundering
    // R4 forbids.
    assert(!('recertification' in r),
      '#826-A6: the refusal carries NO re-certification discriminator — a behavior change is a '
      + 'deviation that is itself evidence, so there is no receipt state that could open this wall '
      + 'and none to report, got ' + JSON.stringify(r.recertification));
    // ...and the hard wall is NOT a dead end: the refusal names the recorded exit.
    assert(r.route === 'shape_refutation',
      '#826-A6: the refusal carries the typed exit — if no authority in the frozen plan can certify '
      + 'the change, the SHAPE is refuted and re-plan is the recorded route, got ' + JSON.stringify(r.route));
    assertZeroWrite826(fx, before, '#826-A6');
    cleanup826(fx.repoRoot);
  });

  // A7 — A RECEIPT CHANGES NOTHING. The reversal's whole content: the wall is not "production is
  // admitted behind a bound re-certification receipt", it is "production is refused". So the SAME fix
  // submitted WITH a well-formed re-certification receipt must produce a BYTE-IDENTICAL refusal —
  // same reason, same paths, same route, same operator prose. A verdict that varies with the receipt
  // is a verdict that CONSULTS the receipt, and a receipt that can move the verdict is a register
  // that launders the deviation into an admission.
  //
  // The stray `recertification` key is deliberately NOT a shape fault: complaining about the receipt
  // binding (RUNG 3) would tell the operator the wrong thing — that a better receipt is the cure. The
  // outermost structural wall is the verdict (see A8).
  scenario(() => {
    const fx = makeFinalFixRepo826({ extraFiles: [APPARATUS_FILE_826] });
    const before = witness826(fx);
    const bare = finalFix826(fx, fixEntry826(fx, { files: ['src/app.js'] }));
    const withReceipt = finalFix826(fx, fixEntry826(fx, {
      files: ['src/app.js'],
      recertification: { attempt_id: 'review2-deadbeefdeadbeef:9', candidate_digest: 'a'.repeat(64) },
    }));
    assert(withReceipt.exitCode === 1 && withReceipt.result === 'refuse'
      && withReceipt.reason === 'final_fix_production_surface',
      '#826-A7: a production-surface entry carrying a re-certification receipt is refused just the '
      + 'same — there is no receipt that admits it, got '
      + JSON.stringify({ result: withReceipt.result, reason: withReceipt.reason }));
    assert(!('recertification' in withReceipt),
      '#826-A7: ...and the refusal still reports no receipt state, got '
      + JSON.stringify(withReceipt.recertification));
    const shape = (x) => JSON.stringify({
      result: x.result, reason: x.reason, production_paths: x.production_paths,
      route: x.route, detail: x.detail, operator_hint: x.operator_hint,
    });
    assert(shape(bare) === shape(withReceipt),
      '#826-A7: the refusal is IDENTICAL with and without a receipt — a verdict that varies with the '
      + 'receipt is one that consults it, and consulting it is the first half of laundering a '
      + 'deviation into an admission.\n  without: ' + shape(bare) + '\n  with:    ' + shape(withReceipt));
    assertZeroWrite826(fx, before, '#826-A7');
    cleanup826(fx.repoRoot);
  });

  // A8 — PRECEDENCE, over the REFUSING walls. The ladder is precedence-ordered so an operator is
  // told the OUTERMOST fault first. With RUNG 1 converted to an advise (see #826-ADV below) the
  // outermost REFUSING wall for a dead sink + a red rerun is the receipt, not the sink: an advise
  // does not lead a refusal. The ordering claim itself is unchanged —
  // after_sink_started > unverified > production_surface.
  scenario(() => {
    const fx = makeFinalFixRepo826({ sinkStatus: 'pending', extraFiles: [APPARATUS_FILE_826] });
    const entry = fixEntry826(fx, { files: ['src/app.js'] });
    entry.rerun.exit_code = 1;
    const r = finalFix826(fx, entry);
    assert(r.reason === 'final_fix_unverified',
      '#826-A8: the outermost REFUSING wall is the emitted reason. A non-live sink is an advise and '
      + 'cannot lead a refusal, so a dead sink + a red rerun leads with the receipt fault, got '
      + JSON.stringify(r.reason));
    cleanup826(fx.repoRoot);
  });

  // -------------------------------------------------------------------------
  // #826-ADV — RUNG 1 IS CONVERTED: `final_fix_sink_not_live` becomes an ADVISE carrying a route.
  //
  // WHY THE SHAPE IS DETERMINED, not discretionary. ADR 0013 R1 admits a typed refusal at exactly
  // three loci — L1 kernel-write integrity (a write that factually did not take), L2 the sink (content
  // reaching mainline), A3 the consent valve. "the terminal finalize row is not in_progress" is none
  // of them: nothing was written, nothing is reaching mainline, no human values call is pending. It is
  // a WRONG-VERB-FOR-STATE condition, which R1 says ships as an advisory or a tool. R3 then fixes the
  // shape: the remedy is mechanical and the refusal already spells it out in prose, which is the
  // definition of a missing tool wearing a uniform. R4 does not bound it — an unopened sink is a
  // STATE, not evidence of tampering, and nothing here is auto-repaired. #826's own first comment
  // asked for exactly this ("it ships as an advise answer carrying a route:, which also keeps this
  // issue's own 'deviation routes, never traps' promise symmetric"); neither D-826-01 nor the
  // route-contract commit answered the proposal, so this is unaddressed silence, not an override.
  //
  // THE TWO LOAD-BEARING PINS are ADV2 and ADV6, and neither is about the advise's own wording:
  //   ADV2 — the advise MUST NOT ADMIT. The lane is sink-OWNED; with no live sink there is no sink to
  //     own the register. The lazy conversion is to delete the `fail(...)` call, which drops the token
  //     AND drops the guard: with every other precondition met, `reasons` is then empty and the pass
  //     falls straight through to the APPEND. That would write a register entry for a run that is not
  //     in finalization — strictly worse than the refusal it replaced.
  //   ADV6 — the conversion must not reach the other three walls. `final_fix_production_surface` in
  //     particular is the hard scope wall DIR-2 deliberately re-pinned; #826 §3 requires a
  //     production-behavior fix to refuse FLATLY, with no receipt and no admission.
  // -------------------------------------------------------------------------

  // ADV1 — THE SHAPE. Not a refusal, and the retired token is gone from the arm entirely: absent from
  // the lead `reason` AND from the report-all `reasons` list, so it cannot survive as a demoted
  // refusal riding in the payload.
  scenario(() => {
    const fx = makeFinalFixRepo826({ sinkStatus: 'pending', extraFiles: [APPARATUS_FILE_826] });
    const r = finalFix826(fx, fixEntry826(fx));
    assert(r.result !== 'refuse',
      '#826-ADV1: a sink that is not live is an ADVISE, not a refusal — R1 admits a refusal only at '
      + 'L1/L2/A3 and a wrong-verb-for-state condition is none of them, got '
      + JSON.stringify({ result: r.result, exitCode: r.exitCode, reason: r.reason }));
    // THE EXIT CODE STAYS NON-ZERO, and is pinned to its exact current value so a later
    // "simplification" to 0 has to fail here first. The work did NOT happen: nothing was recorded.
    // A caller reading exit 0 would be entitled to believe the fix was committed to the register,
    // and every existing caller of `final-fix-commit` was written against a non-zero exit for this
    // arm. What R1/R3 require is that we stop MINTING A REFUSAL CODE where a named exit suffices —
    // not that the arm start reporting success. The subtraction is one code out of the census.
    assert(r.exitCode === 1,
      '#826-ADV1: ...and the advise keeps its NON-ZERO exit — the fix was not recorded, so exit 0 '
      + 'would tell every caller the opposite of what happened, got ' + JSON.stringify(r.exitCode));
    assert(r.reason !== 'final_fix_sink_not_live'
      && !(Array.isArray(r.reasons) && r.reasons.indexOf('final_fix_sink_not_live') !== -1),
      '#826-ADV1: ...and the retired code is gone from the arm — not the lead reason, and not riding '
      + 'in the reasons list either, got ' + JSON.stringify({ reason: r.reason, reasons: r.reasons }));
    cleanup826(fx.repoRoot);
  });

  // ADV2 — THE ADVISE STILL DOES NOT ADMIT. The one thing the refusal was actually protecting: no
  // register, no plan mutation, no commit. GREEN today (a refusal is zero-write by construction) and
  // deliberately kept, because after the conversion it is the ONLY thing standing between a
  // deleted `fail(...)` and a register entry appended for a run with no sink to own it.
  scenario(() => {
    const fx = makeFinalFixRepo826({ sinkStatus: 'pending', extraFiles: [APPARATUS_FILE_826] });
    const before = witness826(fx);
    finalFix826(fx, fixEntry826(fx));
    assert(readRegister826(fx) === null,
      '#826-ADV2: the advise must NOT create the register — the lane is sink-owned, and with no live '
      + 'sink there is no sink to own it. An advise that admits is worse than the refusal it replaced.');
    assertZeroWrite826(fx, before, '#826-ADV2');
    cleanup826(fx.repoRoot);
  });

  // ADV3 — THE DIAGNOSTICS SURVIVE THE CONVERSION. `sink_node` / `sink_status` still reach the caller,
  // and `checks.sink` still reports the observed status rather than the optimistic 'live' default.
  // An advise that drops the facts the refusal carried is a downgrade wearing an upgrade's name.
  scenario(() => {
    const fx = makeFinalFixRepo826({ sinkStatus: 'pending', extraFiles: [APPARATUS_FILE_826] });
    const r = finalFix826(fx, fixEntry826(fx));
    assert(r.sink_node === 'finalize' && r.sink_status === 'pending',
      '#826-ADV3: the answer still names the sink row and its observed status, got '
      + JSON.stringify({ sink_node: r.sink_node, sink_status: r.sink_status }));
    assert(r.checks && r.checks.sink === 'pending',
      '#826-ADV3: ...and `checks.sink` reports the observed status, not the `live` default, got '
      + JSON.stringify(r.checks));
    cleanup826(fx.repoRoot);
  });

  // ADV4 — THE TYPED ROUTE, on the branch where the remedy is REACHABLE. The route is conditional,
  // and this fixture is the keepable half: the sink is `pending` with every dependency `complete`, so
  // it is the next serially-openable node and `open-next` opens it. MEASURED rather than assumed —
  // `computeNextAction` on this exact ledger returns nextNode `finalize` (and returns `impl` once the
  // dependencies are pending, which is the OTHER branch, pinned by ADV9).
  // Shape follows the sibling idiom `inGrammar(script, verb, args)` -> { verb, script, args }; prose
  // is commentary and the route is the machine-readable exit (R5). Pinned structurally, not by verb
  // name, so the implementer still chooses — but a route object that names no verb is not a route.
  scenario(() => {
    const fx = makeFinalFixRepo826({ sinkStatus: 'pending', extraFiles: [APPARATUS_FILE_826] });
    const { computeNextAction } = require('./kaola-workflow-next-action');
    const na = computeNextAction(fs.readFileSync(fx.planPath, 'utf8'));
    assert(na.nextNode && na.nextNode.id === 'finalize',
      '#826-ADV4 precondition: this fixture is the KEEPABLE branch — the sink is the next '
      + 'serially-openable node, so a route at the open verb is a promise that can be kept, got '
      + JSON.stringify(na.nextNode && na.nextNode.id));
    const r = finalFix826(fx, fixEntry826(fx));
    const route = r.route || r.refusal_route || null;
    assert(route && typeof route === 'object' && typeof route.verb === 'string' && route.verb.trim(),
      '#826-ADV4: on the reachable branch the advise carries a TYPED route naming its exit, shaped '
      + 'like every sibling route ({ verb, script, args } — see SINK_FINDING_ROUTE_BY_KIND), got '
      + JSON.stringify(route));
    cleanup826(fx.repoRoot);
  });

  // ADV9 — THE UNREACHABLE BRANCH, and the honest dead end (D3/D6, RULING 2). Same non-live sink,
  // but its dependencies are NOT complete, so the sink is not openable from here: `computeNextAction`
  // hands back `impl`, and an `open-next` route would open some other node while the operator was
  // told it opens the sink. That is #847 in friendlier words — a refusal, or an advise, pointing at a
  // verb that cannot accept the work. The project already answered this class by WITHDRAWING the
  // offer rather than printing one the verb would refuse, so the answer here is NO ROUTE plus prose
  // that names the state which closed it, and the two branches must be distinguishable so a caller
  // can tell "you can open the sink now" from "you cannot".
  scenario(() => {
    const fx = makeFinalFixRepo826({ sinkStatus: 'pending', extraFiles: [APPARATUS_FILE_826] });
    setLedger826(fx.planPath, 'impl', 'pending');
    setLedger826(fx.planPath, 'review', 'pending');
    const { computeNextAction } = require('./kaola-workflow-next-action');
    const na = computeNextAction(fs.readFileSync(fx.planPath, 'utf8'));
    assert(na.nextNode && na.nextNode.id !== 'finalize',
      '#826-ADV9 precondition: with dependencies pending the sink is NOT the next openable node, so '
      + 'no open verb can keep a promise about it, got ' + JSON.stringify(na.nextNode && na.nextNode.id));
    const before = witness826(fx);
    const r = finalFix826(fx, fixEntry826(fx));
    assert(r.result !== 'refuse' && r.exitCode === 1,
      '#826-ADV9: still an ADVISE with a non-zero exit — the branch changes the ROUTE, never the '
      + 'shape, got ' + JSON.stringify({ result: r.result, exitCode: r.exitCode, reason: r.reason }));
    const route9 = r.route || r.refusal_route || null;
    assert(route9 === null || (route9 && typeof route9.verb === 'string'
      && !/open-next|open-ready|expand-open/.test(route9.verb)),
      '#826-ADV9: with the sink unopenable the advise must NOT promise an open verb. Silence is the '
      + 'floor when no verb can accept the work — an honest dead end that explains itself beats a '
      + 'route that could only refuse, got ' + JSON.stringify(route9));
    assert(typeof r.detail === 'string' && /pending|not in_progress|dependenc/i.test(r.detail),
      '#826-ADV9: ...and the prose names the state that closed the exit, so the dead end explains '
      + 'itself rather than merely stopping, got ' + JSON.stringify(r.detail));
    assertZeroWrite826(fx, before, '#826-ADV9');
    cleanup826(fx.repoRoot);
  });

  // ADV5 — THE DEAD-END SEAM (D3/D6). "A route is a promise the verb will accept the work; offering
  // one that cannot be cleared is worse than silence." Two sink states reach this arm and they are NOT
  // interchangeable: a `pending` sink can be opened, and a run whose plan carries no unique terminal
  // finalize node has no sink to open AT ALL — `finalizeSinkStatus` returns `{ id: null }` for it
  // (adaptive-schema: `list.length !== 1` -> id null). Telling that operator to "open the sink first"
  // is the unkeepable promise the doctrine forbids, so the two cases must not collapse into one
  // answer. Driven in-process through the exported `runFinalFixCommit`, because a plan with no
  // finalize row cannot be frozen and so cannot be built as a CLI fixture.
  scenario(() => {
    const { runFinalFixCommit } = require('./kaola-workflow-adaptive-node');
    const sinkless = [
      '# Workflow Plan — issue-826-adv5', '',
      '## Meta', 'labels: area:scripts', 'sink: CHANGELOG.md', '',
      '## Nodes', '',
      '| id | role | depends_on | declared_write_set | cardinality | shape |',
      '| --- | --- | --- | --- | --- | --- |',
      '| impl | tdd-guide | — | src/app.js | 1 | sequence |', '',
      '## Node Ledger', '', '| id | status |', '| --- | --- |', '| impl | complete |', '',
    ].join('\n') + '\n';
    let wrote = false;
    const r = runFinalFixCommit({
      planPath: '/nonexistent/kaola-workflow/issue-826-adv5/workflow-plan.md',
      project: 'issue-826-adv5',
      entry: { failed_command: 'x', fix_commit: 'HEAD', files: ['scripts/test-x.js'],
        rerun: { command: 'x', exit_code: 0, candidate_hash: 'f'.repeat(64) } },
      readFile: (p) => (String(p).endsWith('workflow-plan.md') ? sinkless : null),
      writeFile: () => { wrote = true; },
    });
    assert(wrote === false,
      '#826-ADV5: a plan with no unique terminal finalize node must write NOTHING — there is no sink '
      + 'to own a register entry, so this is the same admit-guard ADV2 pins from the CLI side.');
    assert(r && r.sink_node == null,
      '#826-ADV5: ...and the answer reports that there is no sink row at all (sink_node null), rather '
      + 'than naming one, got ' + JSON.stringify({ sink_node: r && r.sink_node, sink_status: r && r.sink_status }));
    const route5 = (r && (r.route || r.refusal_route)) || null;
    assert(route5 === null || (route5 && typeof route5.verb === 'string' && !/open-next|expand-open/.test(route5.verb)),
      '#826-ADV5: with NO sink node the answer must not route at an open-the-sink verb — that promise '
      + 'cannot be kept, and D3/D6 makes silence the floor. Either a null route with the reason stated, '
      + 'or a verb that genuinely accepts the work; never a verb that could only refuse, got '
      + JSON.stringify(route5));
    assert(typeof (r && r.detail) === 'string' && /finalize node|no unique|no sink/i.test(r.detail),
      '#826-ADV5: ...and the two prose cases stay distinguishable — "the plan has no unique terminal '
      + 'finalize node" must not collapse into "the sink is not in_progress", got '
      + JSON.stringify(r && r.detail));
  });

  // ADV6 — NO DRIFT INTO THE OTHER THREE WALLS. A non-live sink AND a production-surface fix: the
  // answer is still a REFUSAL, led by the scope wall. DIR-2 re-pinned that wall deliberately and #826
  // §3 requires a production-behavior fix to refuse flatly, so demoting RUNG 1 must not soften it, and
  // an advise must not out-rank a refusal in the composite.
  scenario(() => {
    const fx = makeFinalFixRepo826({ sinkStatus: 'pending', extraFiles: [APPARATUS_FILE_826] });
    const before = witness826(fx);
    const r = finalFix826(fx, fixEntry826(fx, { files: ['src/app.js'] }));
    assert(r.result === 'refuse' && r.exitCode === 1 && r.reason === 'final_fix_production_surface',
      '#826-ADV6: a production surface still REFUSES, and now leads the composite because the sink '
      + 'advise cannot lead a refusal, got ' + JSON.stringify({ result: r.result, reason: r.reason }));
    assertZeroWrite826(fx, before, '#826-ADV6');
    cleanup826(fx.repoRoot);
  });

  // ADV7 — REPORT-ALL SURVIVES. The composite still reports every unmet wall in one pass, and the
  // demoted arm does not vanish from the answer: the retired token leaves `reasons`, while the sink
  // FACT stays observable in `checks`. Losing the fact would trade one round-trip for a blind spot.
  scenario(() => {
    const fx = makeFinalFixRepo826({ sinkStatus: 'pending', extraFiles: [APPARATUS_FILE_826] });
    const r = finalFix826(fx, fixEntry826(fx, { files: ['src/app.js'] }));
    assert(Array.isArray(r.reasons) && r.reasons.indexOf('final_fix_production_surface') !== -1,
      '#826-ADV7: the composite still lists every unmet REFUSING wall, got ' + JSON.stringify(r.reasons));
    assert(Array.isArray(r.reasons) && r.reasons.indexOf('final_fix_sink_not_live') === -1,
      '#826-ADV7: ...and the retired token is not among them — an advise is not a refusal, got '
      + JSON.stringify(r.reasons));
    assert(r.checks && r.checks.sink === 'pending',
      '#826-ADV7: ...while the sink FACT survives in checks, so demoting the token costs no '
      + 'information, got ' + JSON.stringify(r.checks));
    cleanup826(fx.repoRoot);
  });

  // ADV8 — THE R2 GREEN ARC, walked from the advised state. Every M3 conversion ships one: a pin that
  // the now-legal path COMPLETES, not merely that the refusal is gone. Advise on a pending sink, take
  // the mechanical remedy the advise names, re-run: the lane admits and records. This is what makes
  // the route a promise rather than a label.
  scenario(() => {
    const fx = makeFinalFixRepo826({ sinkStatus: 'pending', extraFiles: [APPARATUS_FILE_826] });
    const advised = finalFix826(fx, fixEntry826(fx));
    assert(advised.result !== 'refuse',
      '#826-ADV8 precondition: the pending-sink call advises rather than refuses, got '
      + JSON.stringify({ result: advised.result, reason: advised.reason }));
    assert(readRegister826(fx) === null, '#826-ADV8 precondition: nothing was recorded by the advise');
    setLedger826(fx.planPath, 'finalize', 'in_progress');
    const r = finalFix826(fx, fixEntry826(fx));
    assert(r.exitCode === 0 && r.result === 'ok',
      '#826-ADV8: once the sink IS live the same submission is ADMITTED — the advise pointed at a '
      + 'remedy that actually clears it, got ' + JSON.stringify({ result: r.result, reason: r.reason }));
    const reg = readRegister826(fx) || {};
    assert(Array.isArray(reg.entries) && reg.entries.length === 1,
      '#826-ADV8: ...and exactly one entry is recorded on the far side of the arc, got '
      + JSON.stringify(reg.entries));
    cleanup826(fx.repoRoot);
  });

  // -------------------------------------------------------------------------
  // #826-B — THE ADMITTING PATHS + THE REGISTER. The lane has to actually WORK, or it is just a
  // fifth way to be refused. These pin the cheap (validation-apparatus) path end to end and the
  // register's recorded shape.
  // -------------------------------------------------------------------------

  // B1 — THE CHEAP PATH ADMITS. A stale-test correction is validation APPARATUS: it repairs the
  // thing that JUDGES the product, so the standing certification over the product is untouched and
  // the bound green rerun receipt is its whole oracle. No re-review, no consent, no justifier.
  scenario(() => {
    const fx = makeFinalFixRepo826({ extraFiles: [APPARATUS_FILE_826] });
    const r = finalFix826(fx, fixEntry826(fx));
    assert(r.exitCode === 0 && r.result === 'ok',
      '#826-B1: a validation-apparatus fix with a bound green rerun receipt is ADMITTED, got '
      + JSON.stringify({ result: r.result, reason: r.reason, errors: r.errors }));
    assert(r.surface_class === 'validation-apparatus',
      '#826-B1: ...and is recorded as validation-apparatus, got ' + JSON.stringify(r.surface_class));
    const reg = readRegister826(fx) || {};
    assert(Array.isArray(reg.entries) && reg.entries.length === 1,
      '#826-B1: the sink-owned register exists at .cache/final-fixes.json with exactly one entry, got '
      + JSON.stringify(reg.entries));
    const e = (Array.isArray(reg.entries) && reg.entries[0]) || {};
    assert(e.failed_command === 'node scripts/test-final-fix-826.js',
      '#826-B1: the entry records the EXACT failed validation command, got ' + JSON.stringify(e.failed_command));
    assert(Array.isArray(e.files) && e.files.length === 1 && e.files[0] === 'scripts/test-final-fix-826.js',
      '#826-B1: the entry records the touched paths, got ' + JSON.stringify(e.files));
    assert(typeof e.fix_commit === 'string' && /^[0-9a-f]{7,40}$/.test(e.fix_commit),
      '#826-B1: the entry records the fix commit, got ' + JSON.stringify(e.fix_commit));
    assert(e.rerun && e.rerun.exit_code === 0 && /^[0-9a-f]{64}$/.test(String(e.rerun.candidate_hash || '')),
      '#826-B1: the entry records the green rerun receipt + its candidate binding, got ' + JSON.stringify(e.rerun));
    // NO RE-CERTIFICATION FIELD SURVIVES IN THE RECORD. The register's entry schema carries no slot
    // for a receipt that admits a production surface — a dead `recertification: null` is the residue
    // of the widening, and a slot is the thing a later change fills back in.
    assert(!('recertification' in e),
      '#826-B1: the recorded entry carries NO recertification slot — the register holds apparatus '
      + 'fixes only, and a receipt field is the seam a production widening would grow back through, '
      + 'got ' + JSON.stringify(e.recertification));
    assert(typeof reg.digest === 'string' && /^[0-9a-f]{64}$/.test(reg.digest),
      '#826-B1: the register is DIGEST-BOUND, got ' + JSON.stringify(reg.digest));
    assert(typeof reg.plan_hash === 'string' && /^[0-9a-f]{64}$/.test(reg.plan_hash),
      '#826-B1: the register is bound to the frozen plan it belongs to, got ' + JSON.stringify(reg.plan_hash));
    cleanup826(fx.repoRoot);
  });

  // B2 — NO CAP ON ENTRIES. Each entry carries its own green rerun receipt, and that receipt IS the
  // natural bound; a second independent final-fix appends a second entry rather than refusing.
  scenario(() => {
    const second = { path: 'scripts/test-final-fix-826b.js', body: '// second stale-test correction\n' };
    const fx = makeFinalFixRepo826({ extraFiles: [APPARATUS_FILE_826, second] });
    const first = finalFix826(fx, fixEntry826(fx));
    assert(first.result === 'ok', '#826-B2 precondition: the first fix records, got ' + JSON.stringify(first));
    const cmd2 = 'node scripts/test-final-fix-826b.js';
    const r = finalFix826(fx, fixEntry826(fx, {
      failed_command: cmd2,
      files: [second.path],
      rerun: { command: cmd2, exit_code: 0, candidate_hash: candidateHash826(fx.repoRoot, fx.planPath) },
    }));
    assert(r.exitCode === 0 && r.result === 'ok',
      '#826-B2: a SECOND final-fix is admitted — the lane has no per-run cap, got '
      + JSON.stringify({ result: r.result, reason: r.reason }));
    const reg = readRegister826(fx) || {};
    assert(Array.isArray(reg.entries) && reg.entries.length === 2,
      '#826-B2: both entries are retained, got ' + JSON.stringify(reg.entries && reg.entries.length));
    const files = (Array.isArray(reg.entries) ? reg.entries : []).flatMap(x => x.files || []).sort();
    assert(files.join(',') === 'scripts/test-final-fix-826.js,scripts/test-final-fix-826b.js',
      '#826-B2: ...each with its own paths, got ' + JSON.stringify(files));
    cleanup826(fx.repoRoot);
  });

  // -------------------------------------------------------------------------
  // #826-C — THE PREDICATE THE WALL RESTS ON, AND THE ABSENCE OF THE ONE IT DOES NOT. Exported and
  // tested directly: the classifier decides WHICH SIDE of the wall a path is on, and nothing else
  // decides whether the wall opens — because it does not open.
  // -------------------------------------------------------------------------

  // C1 — THE SURFACE CLASSIFIER. Apparatus = the machinery that JUDGES the product (tests, fixtures,
  // build/tooling glue, allowband docs). Everything else is production. The load-bearing property is
  // the DEFAULT: a path the classifier does not recognize is PRODUCTION, so an unanticipated surface
  // fails toward the HARD WALL rather than through the cheap path. This property predates the
  // widening and survives its reversal unchanged — it is what makes "production is refused" a
  // statement about every path, not just the ones somebody thought of.
  scenario(() => {
    const mod = require('./kaola-workflow-adaptive-node');
    const classify = mod.classifyFinalFixSurface;
    assert(typeof classify === 'function',
      '#826-C1: classifyFinalFixSurface is exported for direct coverage, got ' + typeof classify);
    if (typeof classify !== 'function') return;
    const cls = (paths) => classify(paths, 'issue-826');
    for (const p of ['scripts/test-adaptive-node.js', 'scripts/simulate-workflow-walkthrough.js',
      'test/fixtures/sample.json', 'src/__tests__/app.test.js', 'package.json',
      'docs/api.md', 'CHANGELOG.md', 'README.md']) {
      const r = cls([p]);
      assert(r && r.surface_class === 'validation-apparatus'
        && Array.isArray(r.production) && r.production.length === 0,
        '#826-C1: "' + p + '" is validation APPARATUS (it judges the product, or is allowband docs), got '
        + JSON.stringify(r));
    }
    for (const p of ['src/app.js', 'scripts/kaola-workflow-adaptive-node.js', 'lib/router.ts']) {
      const r = cls([p]);
      assert(r && r.surface_class === 'production' && (r.production || []).includes(p),
        '#826-C1: "' + p + '" is PRODUCTION behavior, got ' + JSON.stringify(r));
    }
    // CONSERVATIVE DEFAULT — the whole safety argument. An unrecognized surface is production.
    const odd = cls(['vendor/opaque.bin']);
    assert(odd && odd.surface_class === 'production' && (odd.production || []).includes('vendor/opaque.bin'),
      '#826-C1: an UNRECOGNIZED path defaults to PRODUCTION (fail toward the hard wall, never through '
      + 'the cheap path), got ' + JSON.stringify(odd));
    // MIXED — one production path in the set makes the whole ENTRY production. Classes do not net out.
    const mixed = cls(['scripts/test-adaptive-node.js', 'src/app.js']);
    assert(mixed && mixed.surface_class === 'production' && (mixed.production || []).join(',') === 'src/app.js',
      '#826-C1: a mixed entry is PRODUCTION and names only the production member, got ' + JSON.stringify(mixed));
  });

  // C2 — THERE IS NO RE-CERTIFICATION MACHINERY, AND THE WALL HAS A TYPED EXIT INSTEAD.
  //
  // The wall protects a STANDING CERTIFICATION, and under R4 a behavior change arriving after every
  // reviewer is discharged is a deviation that is ITSELF EVIDENCE — evidence the certification no
  // longer describes the candidate. A verifier that could turn that evidence into an admission is
  // precisely the laundering R4 exists to prevent, so the verifier must not exist AT ALL: a dormant
  // one is a loaded seam, and the register-side gate below is what a forged entry actually meets.
  //
  // What replaces it is not a softer receipt but a ROUTE. The original complaint was that the lane
  // DEAD-ENDS; the route contract removes dead ends by construction, so the hard wall names its exit
  // (re-plan on a refuted shape) and the operator is never stranded.
  scenario(() => {
    const mod = require('./kaola-workflow-adaptive-node');
    const schema826 = require('./kaola-workflow-adaptive-schema');

    // (a) THE VERIFIER IS GONE. Not "always refuses" — ABSENT. A receipt verifier that still exists
    // is a mechanism whose only purpose is to open this wall, one edit away from doing so.
    assert(mod.verifyFinalFixRecertification === undefined,
      '#826-C2a: no re-certification verifier is exported — admitting a production fix behind a '
      + 'receipt would launder a deviation that is itself evidence into a certification, which is '
      + 'exactly the machinery R4 exists to prevent, got ' + typeof mod.verifyFinalFixRecertification);

    // (b) THE REGISTER CANNOT CARRY A PRODUCTION ENTRY — receipt or no receipt. This is the shared
    // authority the sweep reads, so it is where a forged or laundered entry has to be stopped. A
    // well-formed production entry with a perfectly bound receipt is the exact shape the widening
    // used to admit; it must not verify.
    const PLAN_HASH_826 = 'a'.repeat(64);
    const classify826 = (files) => planValidator.classifyFinalFixSurface(files, 'issue-826');
    const regEntry826 = (over) => Object.assign({
      ordinal: 1,
      failed_command: 'node scripts/test-final-fix-826.js',
      fix_commit: 'abcdef1234567',
      files: ['src/smuggled.js'],
      surface_class: 'production',
      rerun: { command: 'node scripts/test-final-fix-826.js', exit_code: 0, candidate_hash: 'b'.repeat(64) },
      role: 'tdd-guide',
      recorded_at: '2026-01-01T00:00:00.000Z',
    }, over || {});
    const sealed = (entry) => {
      const reg = { schema_version: schema826.FINAL_FIX_REGISTER_SCHEMA_VERSION,
        plan_hash: PLAN_HASH_826, entries: [entry] };
      reg.digest = schema826.computeFinalFixRegisterDigest(reg);   // an HONEST digest — not a tamper test
      return reg;
    };
    const withReceipt = schema826.verifyFinalFixRegister(
      sealed(regEntry826({ recertification: { attempt_id: 'review2-abcdef0123456789:1',
        candidate_digest: 'c'.repeat(64) } })), PLAN_HASH_826, classify826);
    assert(withReceipt && withReceipt.ok === false,
      '#826-C2b: a PRODUCTION register entry does not verify even with a perfectly bound '
      + 're-certification receipt — the register is the sweep\'s shared authority, and an entry it '
      + 'accepts becomes an attributed path no reviewer ever certified, got ' + JSON.stringify(withReceipt));
    assert(!Array.isArray(withReceipt && withReceipt.files)
      || !withReceipt.files.includes('src/smuggled.js'),
      '#826-C2b: ...and it attributes nothing on the way out, got ' + JSON.stringify(withReceipt));
    const noReceipt = schema826.verifyFinalFixRegister(
      sealed(regEntry826()), PLAN_HASH_826, classify826);
    assert(noReceipt && noReceipt.ok === false,
      '#826-C2b: a PRODUCTION register entry does not verify without one either — the class is the '
      + 'fault, not the paperwork, got ' + JSON.stringify(noReceipt));

    // (c) THE APPARATUS ENTRY STILL VERIFIES. The lane is not deleted — only the production widening
    // is. Without this, "refuse everything" would satisfy (b) and the cheap path would be gone.
    const apparatus = schema826.verifyFinalFixRegister(sealed(regEntry826({
      files: ['scripts/test-final-fix-826.js'], surface_class: 'validation-apparatus',
    })), PLAN_HASH_826, classify826);
    assert(apparatus && apparatus.ok === true
      && (apparatus.files || []).includes('scripts/test-final-fix-826.js'),
      '#826-C2c: a validation-apparatus entry still verifies and still attributes its paths — the '
      + 'cheap path survives; repairing the JUDGE does not move the product, so the standing '
      + 'certification still holds, got ' + JSON.stringify(apparatus));

    // (d) THE TYPED EXIT EXISTS AND RESOLVES. The wall is only defensible because it is not a dead
    // end: the refusal routes to the re-plan that refutes the shape. Pinned at the ONE source the
    // emitted `route` token is derived from, in both the structured and the legacy-token form.
    const routed = schema826.SINK_FINDING_ROUTE_BY_KIND.final_fix_production_surface;
    assert(routed && routed.route && routed.route.script === 'replan'
      && routed.route.verb === 'shape-refutation',
      '#826-C2d: the finding routes to `replan shape-refutation` — no authority in the frozen plan '
      + 'can certify a post-discharge behavior change, so the SHAPE is what is refuted, got '
      + JSON.stringify(routed));
    assert(JSON.stringify(schema826.resolveSinkFindingRoute({ kind: 'final_fix_production_surface' }))
      === JSON.stringify(routed.route),
      '#826-C2d: ...and the per-finding resolver REACHES it (an exit nothing resolves is a dead end '
      + 'with a table entry), got '
      + JSON.stringify(schema826.resolveSinkFindingRoute({ kind: 'final_fix_production_surface' })));
    assert(schema826.deriveDeviationRoutes().final_fix_production_surface === 'shape_refutation',
      '#826-C2d: ...and the emitted bare-verb token stays `shape_refutation`, got '
      + JSON.stringify(schema826.deriveDeviationRoutes().final_fix_production_surface));

    // (e) THE OPERATOR PROSE MUST NOT SELL A RETIRED CURE. The hint is the operator-facing half of
    // the contract: telling them to obtain a receipt and cite it in `recertification` points at a
    // field the entry schema no longer has and a lane that no longer opens. Naming the RETIRED FIELD
    // TOKENS is the precise test — prose about why re-certification is refused stays legal.
    const hint826 = getOperatorHint('final_fix_production_surface',
      { production_paths: ['src/app.js'], route: 'shape_refutation' });
    assert(typeof hint826 === 'string' && hint826.length > 0,
      '#826-C2e: the refusal has an operator hint, got ' + JSON.stringify(hint826));
    assert(!/`recertification`/.test(hint826) && !/attempt_id/.test(hint826),
      '#826-C2e: the hint does not instruct the operator to cite a re-certification receipt — that '
      + 'names a retired entry field and a cure that does not exist, got ' + JSON.stringify(hint826));
    assert(/refut/i.test(hint826),
      '#826-C2e: ...it names the exit instead, so the hard wall reads as a fork rather than a dead '
      + 'end, got ' + JSON.stringify(hint826));
  });

  // -------------------------------------------------------------------------
  // #826-D — THE SWEEP'S THIRD SOURCE + THE DEVIATION ROUTES. A changed path is attributed iff it is
  // in the allowband, OR in a `complete` node's declared write set, OR in a VERIFIED final-fix
  // register entry. And an out-of-shape refusal names the ONE legal recorded verb that resolves it,
  // so finalization stops being a dead end.
  // -------------------------------------------------------------------------

  // D1 — THE ROUND TRIP. Control → route → record → pass, over the EXACT `--finalize-check`
  // subprocess cmdFinalize shells before any irreversible side effect.
  //   CONTROL (passes today): the prescribed test-only fix is refused `unattributed_change`.
  //   RED: that refusal carries no `route`, so the orchestrator is told what is wrong and nothing
  //     about how to land it — the measured 40-minute dead end.
  //   RED: after recording the fix there is still no third source, so the identical sweep refuses again.
  scenario(() => {
    const fx = makeFinalFixRepo826({ extraFiles: [APPARATUS_FILE_826] });
    seedFinalValidation826(fx.repoRoot, fx.cacheDir, fx.planPath);
    const control = finalizeCheck826(fx.repoRoot, fx.planPath, fx.base);
    assert(control.result === 'refuse' && control.reason === 'unattributed_change'
      && (control.unattributed || []).includes('scripts/test-final-fix-826.js'),
      '#826-D1 CONTROL: the prescribed finalize fix is refused unattributed_change today, got '
      + JSON.stringify({ reason: control.reason, unattributed: control.unattributed }));
    assert(control.route === 'final-fix-commit',
      '#826-D1: with the sink LIVE and PRISTINE the refusal is a FORK, not a dead end — it names '
      + 'the one recorded verb that lands the same decision, got ' + JSON.stringify(control.route));
    const rec = finalFix826(fx, fixEntry826(fx));
    assert(rec.result === 'ok',
      '#826-D1: the fix records into the sink-owned register, got ' + JSON.stringify({ result: rec.result, reason: rec.reason }));
    seedFinalValidation826(fx.repoRoot, fx.cacheDir, fx.planPath);
    const after = finalizeCheck826(fx.repoRoot, fx.planPath, fx.base);
    assert(after.exitCode === 0 && after.result === 'pass',
      '#826-D1: the SAME sweep now PASSES — the verified register is the THIRD attributed source, got '
      + JSON.stringify({ result: after.result, reason: after.reason, unattributed: after.unattributed }));
    cleanup826(fx.repoRoot);
  });

  // D2 — THE REGISTER IS NOT A LAUNDERING PRIMITIVE. A hand-widened register must NOT attribute the
  // smuggled path, and must NOT be reported as `unattributed_change` either — that reason's
  // documented operator response is to DELETE the file, which is a lie about the real fault (the
  // same argument the sealed-parent-epoch lineage already makes). It gets its own typed reason.
  scenario(() => {
    const fx = makeFinalFixRepo826({
      extraFiles: [APPARATUS_FILE_826, { path: 'src/smuggled.js', body: '// never reviewed\n' }],
    });
    const rec = finalFix826(fx, fixEntry826(fx));
    assert(rec.result === 'ok', '#826-D2 precondition: the apparatus fix records, got ' + JSON.stringify(rec));
    // Hand-widen the register OUT OF BAND, exactly as an operator "helping" the sweep along would.
    // Falls back to a WHOLLY FORGED register when the verb has not shipped yet, so this scenario
    // measures the sweep's laundering wall rather than crashing on the missing precondition.
    const reg = readRegister826(fx) || { schema_version: 1, plan_hash: 'e'.repeat(64),
      entries: [{ ordinal: 1, files: [] }], digest: 'f'.repeat(64) };
    reg.entries[0].files = (reg.entries[0].files || []).concat(['src/smuggled.js']);
    fs.writeFileSync(registerPath826(fx), JSON.stringify(reg, null, 2) + '\n');
    seedFinalValidation826(fx.repoRoot, fx.cacheDir, fx.planPath);
    const r = finalizeCheck826(fx.repoRoot, fx.planPath, fx.base);
    assert(r.exitCode === 1 && r.result === 'refuse' && r.reason === 'final_fix_register_unverified',
      '#826-D2: an out-of-band register edit refuses final_fix_register_unverified — never a silent '
      + 'attribution, got ' + JSON.stringify({ result: r.result, reason: r.reason }));
    assert(!(r.unattributed || []).includes('src/smuggled.js'),
      '#826-D2: ...and is NOT mislabelled unattributed_change (whose cure would delete the file), got '
      + JSON.stringify(r.unattributed));
    cleanup826(fx.repoRoot);
  });

  // D2b — AND A *WELL-FORMED* PRODUCTION ENTRY IS THE SAME LAUNDERING, WEARING A RECEIPT. D2 breaks
  // the digest, so it is caught as tampering. This one is honest in every mechanical respect — right
  // schema, right plan_hash, recomputed digest, green rerun receipt bound to the exact failed command,
  // a bound re-certification receipt — and it is the shape the widening produced LEGITIMATELY. It
  // must STILL refuse, because the fault is not the paperwork: attributing `src/smuggled.js` here
  // would let the sink ship production behavior no reviewing authority ever saw, with a register
  // entry standing in for the certification. That is a deviation being laundered into a receipt,
  // which R4 forbids outright — the deviation is itself the evidence, and evidence is reported, not
  // repaired. This is the CORE of the reversal: the register may widen the attributed set only over
  // the validation APPARATUS, never over the product.
  scenario(() => {
    // The smuggled production file is the ONLY unattributed path on the branch, so the register entry
    // is the single thing standing between it and a PASSING sweep. Nothing else can mask the verdict.
    const fx = makeFinalFixRepo826({
      extraFiles: [{ path: 'src/smuggled.js', body: '// never reviewed\n' }],
    });
    const schema826 = require('./kaola-workflow-adaptive-schema');
    const planHash = (/<!--\s*plan_hash:\s*([0-9a-f]{64})\s*-->/
      .exec(fs.readFileSync(fx.planPath, 'utf8')) || [])[1];
    const cmd = 'node scripts/test-final-fix-826.js';
    const reg = {
      schema_version: schema826.FINAL_FIX_REGISTER_SCHEMA_VERSION,
      plan_hash: planHash,
      entries: [{
        ordinal: 1,
        failed_command: cmd,
        fix_commit: fx.g(['rev-parse', 'HEAD']).trim(),
        files: ['src/smuggled.js'],
        surface_class: 'production',
        rerun: { command: cmd, exit_code: 0, candidate_hash: candidateHash826(fx.repoRoot, fx.planPath) },
        recertification: { attempt_id: 'review2-abcdef0123456789:1', candidate_digest: 'c'.repeat(64) },
        role: 'tdd-guide',
        recorded_at: '2026-01-01T00:00:00.000Z',
      }],
    };
    reg.digest = schema826.computeFinalFixRegisterDigest(reg);   // HONEST digest: nothing here is tampered
    fs.writeFileSync(registerPath826(fx), JSON.stringify(reg, null, 2) + '\n');
    seedFinalValidation826(fx.repoRoot, fx.cacheDir, fx.planPath);
    const r = finalizeCheck826(fx.repoRoot, fx.planPath, fx.base);
    assert(r.exitCode === 1 && r.result === 'refuse',
      '#826-D2b: a PRODUCTION register entry does not let the sweep pass — a finalize register may '
      + 'never stand in for a certification over the product, got '
      + JSON.stringify({ exitCode: r.exitCode, result: r.result, reason: r.reason }));
    assert(r.reason === 'final_fix_register_unverified',
      '#826-D2b: ...and it refuses with the register\'s own typed reason, got ' + JSON.stringify(r.reason));
    assert(!(r.unattributed || []).includes('src/smuggled.js'),
      '#826-D2b: ...NOT mislabelled unattributed_change, whose documented cure (delete the file) '
      + 'answers a different fault than the one being reported, got ' + JSON.stringify(r.unattributed));
    cleanup826(fx.repoRoot);
  });

  // D3 — NO ROUTE WHEN THE LANE IS SHUT. The `route:` field is a promise the verb will accept the
  // work; offering it after the sink has PUSHED would send the orchestrator at a refusal it can
  // never clear. Same sweep, same refusal — no route.
  scenario(() => {
    const fx = makeFinalFixRepo826({ sinkPushed: true, extraFiles: [APPARATUS_FILE_826] });
    seedFinalValidation826(fx.repoRoot, fx.cacheDir, fx.planPath);
    const r = finalizeCheck826(fx.repoRoot, fx.planPath, fx.base);
    assert(r.result === 'refuse' && r.reason === 'unattributed_change',
      '#826-D3 precondition: still unattributed_change, got ' + JSON.stringify(r.reason));
    assert(r.route !== 'final-fix-commit',
      '#826-D3: after the sink has PUSHED the lane is closed, so the refusal offers NO '
      + 'final-fix-commit route, got ' + JSON.stringify(r.route));
    cleanup826(fx.repoRoot);
  });

  // D4 — SAME, FOR A SINK THAT IS NOT LIVE. A `pending` sink is not finalization at all; the fix
  // belongs to the ordinary in-plan path, so the finalize route must not be advertised.
  scenario(() => {
    const fx = makeFinalFixRepo826({ sinkStatus: 'pending', extraFiles: [APPARATUS_FILE_826] });
    seedFinalValidation826(fx.repoRoot, fx.cacheDir, fx.planPath);
    const r = finalizeCheck826(fx.repoRoot, fx.planPath, fx.base);
    assert(r.result === 'refuse' && r.reason === 'unattributed_change',
      '#826-D4 precondition: still unattributed_change, got ' + JSON.stringify(r.reason));
    assert(r.route !== 'final-fix-commit',
      '#826-D4: a sink that is not in_progress offers NO final-fix-commit route, got '
      + JSON.stringify(r.route));
    cleanup826(fx.repoRoot);
  });

  // D5 — THE OTHER TWO TRAPS GET THE SAME FORK. `reopen-node` in finalize context is the refusal
  // that cost the measured 40 minutes: the tail review is `complete`, the sink is `in_progress` and
  // is NOT a post-dominating gate, so the reopen refuses `would_orphan_in_progress` — with no exit
  // named. It carries the route now.
  //   CONTROL (passes today): the refusal fires and names the sink.
  scenario(() => {
    const fx = makeFinalFixRepo826({ extraFiles: [APPARATUS_FILE_826] });
    const r = runNode826(fx.repoRoot, ['reopen-node', '--project', fx.project, '--node-id', 'review', '--json']);
    assert(r.exitCode === 1 && r.reason === 'would_orphan_in_progress'
      && (r.inProgress || []).includes('finalize'),
      '#826-D5 CONTROL: reopening the tail review over a live sink refuses would_orphan_in_progress, got '
      + JSON.stringify({ reason: r.reason, inProgress: r.inProgress }));
    assert(r.route === 'final-fix-commit',
      '#826-D5: fired in FINALIZE context (sink live + pristine) the refusal names the recorded '
      + 'lane instead of dead-ending, got ' + JSON.stringify(r.route));
    cleanup826(fx.repoRoot);
  });

  // D6 — AND THAT ROUTE IS CONTEXT-BOUND, NOT A BLANKET TABLE ROW. The same refusal fired with the
  // sink already PUSHED must NOT advertise a lane that would only refuse
  // `final_fix_after_sink_started`. A static DEVIATION_ROUTES row keyed on the reason alone would
  // fail this; the emit site has to decide.
  scenario(() => {
    const fx = makeFinalFixRepo826({ sinkPushed: true, extraFiles: [APPARATUS_FILE_826] });
    const r = runNode826(fx.repoRoot, ['reopen-node', '--project', fx.project, '--node-id', 'review', '--json']);
    assert(r.reason === 'would_orphan_in_progress',
      '#826-D6 precondition: the same refusal fires, got ' + JSON.stringify(r.reason));
    assert(r.route !== 'final-fix-commit',
      '#826-D6: a pushed sink withdraws the route — the deviation route is CONTEXT-bound, not a '
      + 'blanket reason→verb row, got ' + JSON.stringify(r.route));
    cleanup826(fx.repoRoot);
  });

  // D7 — THE SAME CLAUSE, FOR A LANE THAT IS OPEN BUT CANNOT ACCEPT THE WORK. D3/D6 withdraw the
  // offer because the lane is SHUT. This withdraws it for the other way the promise fails: the lane
  // is live and pristine, but every unattributed path is PRODUCTION, so `final-fix-commit` meets the
  // hard scope wall on arrival and refuses `final_fix_production_surface` whatever paperwork it
  // carries. Following the advertised route would land on a refusal that verb can never clear — and
  // a route is a promise the verb will accept the work, so offering one that cannot be cleared is
  // worse than silence. The refusal's own prose (attribute the paths, or remove them) is what
  // survives, exactly as it does over a pushed sink.
  scenario(() => {
    const fx = makeFinalFixRepo826({
      extraFiles: [{ path: 'src/prod-extra.js', body: '// undeclared production\n' }],
    });
    seedFinalValidation826(fx.repoRoot, fx.cacheDir, fx.planPath);
    const r = finalizeCheck826(fx.repoRoot, fx.planPath, fx.base);
    assert(r.result === 'refuse' && r.reason === 'unattributed_change'
      && (r.unattributed || []).includes('src/prod-extra.js'),
      '#826-D7 precondition: an undeclared PRODUCTION path is refused unattributed_change with the '
      + 'sink live and pristine, got ' + JSON.stringify({ reason: r.reason, unattributed: r.unattributed }));
    assert(r.route !== 'final-fix-commit',
      '#826-D7: with the unattributed set ENTIRELY production the lane could only refuse '
      + 'final_fix_production_surface, so the offer is withdrawn rather than made falsely, got '
      + JSON.stringify(r.route));
    cleanup826(fx.repoRoot);
  });

  // D8 — AND THE WITHDRAWAL IS NARROW, NOT BLANKET. A MIXED set keeps the offer: the lane genuinely
  // accepts the apparatus members, so the promise is keepable for the part it names. Without this,
  // "withdraw whenever any production path is present" would satisfy D7 while deleting the lane's
  // whole purpose on precisely the runs that need it.
  scenario(() => {
    const fx = makeFinalFixRepo826({
      extraFiles: [APPARATUS_FILE_826, { path: 'src/prod-extra.js', body: '// undeclared production\n' }],
    });
    seedFinalValidation826(fx.repoRoot, fx.cacheDir, fx.planPath);
    const r = finalizeCheck826(fx.repoRoot, fx.planPath, fx.base);
    assert(r.result === 'refuse' && r.reason === 'unattributed_change',
      '#826-D8 precondition: still unattributed_change, got ' + JSON.stringify(r.reason));
    assert(r.route === 'final-fix-commit',
      '#826-D8: a MIXED unattributed set KEEPS the offer — the lane accepts the apparatus members, '
      + 'so the promise is keepable for what it names, got ' + JSON.stringify(r.route));
    cleanup826(fx.repoRoot);
  });

  // D9 — AND THE HARD WALL'S OWN REFUSAL NAMES EXACTLY ONE EXIT. The envelope is stamped twice: the
  // bare `route:` token from the derived deviation table, and the structured `refusal_route` from the
  // kernel family resolver. They are two RENDERINGS of one exit; before this pin the second read
  // `claim finalize --check`, the sink_verdict family's fixed re-read verb — which cannot clear a
  // refusal that is ZERO-WRITE and therefore was never written into any verdict to be re-read. Two
  // answers to "follow the typed route" is one answer too many.
  scenario(() => {
    const fx = makeFinalFixRepo826({ extraFiles: [APPARATUS_FILE_826] });
    const r = finalFix826(fx, fixEntry826(fx, { files: ['src/app.js'] }));
    assert(r.reason === 'final_fix_production_surface',
      '#826-D9 precondition: the production surface refuses, got ' + JSON.stringify(r.reason));
    assert(r.route === 'shape_refutation',
      '#826-D9: the bare route token is the refuted shape, got ' + JSON.stringify(r.route));
    assert(r.refusal_route && r.refusal_route.script === 'replan'
      && r.refusal_route.verb === 'shape-refutation',
      '#826-D9: ...and the STRUCTURED route names the same exit — a family-level re-read verb on a '
      + 'finding a re-read can never clear is a second, contradicting answer, got '
      + JSON.stringify(r.refusal_route));
    // R4 rides on the envelope: this is the one deviation the ADR names as never-repairable, and a
    // family-level `auto_remediable: true` could not say so.
    assert(r.auto_remediable === false,
      '#826-D9: ...and the refusal is stamped NOT auto-remediable — a behavior change arriving after '
      + 'every reviewer is discharged is a deviation that is itself evidence, and evidence is '
      + 'reported, never repaired, got ' + JSON.stringify(r.auto_remediable));
    cleanup826(fx.repoRoot);
  });
}

// ===========================================================================
// #846 — STANDING CONSENT CLASSES. The subtraction: a granted consent records a CLASS with run
// scope, and repeat instances WITHIN that scope proceed on the standing grant and are LOGGED,
// rather than re-asked. The valve itself is untouched — this removes re-asking, not consent.
//
// THE REAL MECHANISM these pins bind to (nothing here is invented):
//   * `write-halt --project P --node-id N --reason consent` is the A3 valve raise. It writes
//     `escalated_to_full: consent` into workflow-state.md and the durable `consent_halt: pending`
//     marker into the plan's `## Node Ledger` (readDurableConsentHalt is the section-scoped probe).
//   * `clear-halt --project P --reason consent` is the script-owned inverse — the human's "yes".
//   * `orient` is the read-only successor surface: a process with ZERO context reads the run's
//     position from it. It already reports `consentHalt`; it is where a successor must be able to
//     see the standing grants and their applications (A1).
//
// THE SURFACE THESE PINS FIX (one new flag, one new envelope field, one new orient field — and
// ZERO new refusal codes, because a consent interaction is the A3 valve and is already a
// legitimate locus under ADR 0013 R1):
//   * `write-halt ... --reason consent --consent-class <action>:<target>` names the class.
//       - covered by a live standing grant  -> NO halt is written; the envelope carries
//         `standing_grant: true` and the application is journaled.
//       - not covered                       -> the halt is written exactly as today; the envelope
//         carries `standing_grant: false` and the class rides the pending request.
//     `standing_grant` is ALWAYS present and boolean: the valve must state, every single time,
//     whether it spoke on a standing grant or put the question. A missing field is the invisible
//     application the issue's third design answer exists to forbid.
//   * `clear-halt --reason consent` grants exactly the class the PENDING halt recorded, and echoes
//     it as `standing_grant_recorded`. Deliberately NO class flag at clear time: the human answered
//     the question that was asked, so the grant cannot be widened past the question.
//   * `orient` reports `consentGrants: [{ class, applications }]` — always an array.
//
// SCOPE (decided in the issue; these pins do not re-open it):
//   1. class identity = ACTION + TARGET;  2. lifetime = the CLAIM (re-plan epoch, discard+restart,
//   new candidate digest all revoke);  3. EVERY application is journaled;  4. a brand-new class
//   ALWAYS asks.
//
// Every fixture is a real on-disk project (git repo + frozen plan + a VALID schema-2 epoch state
// block) driven through the REAL CLI in SEPARATE PROCESSES. That is deliberate and load-bearing:
// an in-memory grant cache would satisfy nothing here, because no two calls in these scenarios
// share a heap. spawn-class: durable-handoff
// ===========================================================================
{
  const { execFileSync: exec846, spawnSync: spawn846 } = require('child_process');
  const schema846 = require('./kaola-workflow-adaptive-schema');
  const NODE_CLI_846 = path.join(__dirname, 'kaola-workflow-adaptive-node.js');

  // The measured class from the issue: the same question asked THREE times in one run, the second
  // wait alone costing 33 minutes.
  const CLASS_846 = 'patch-installed-tooling:~/.claude/agents';
  // Same ACTION, different TARGET. Design answer 1 says this is a DIFFERENT class.
  const OTHER_TARGET_846 = 'patch-installed-tooling:~/.codex/agents';
  // Different ACTION entirely — a brand-new class.
  const OTHER_ACTION_846 = 'delete-worktree:~/.claude/agents';

  const planBody846 = (design) => [
    '# Workflow Plan — issue-846', '',
    '## Meta', 'plan_form: spine', 'labels: area:scripts', 'sink: CHANGELOG.md', '',
    '## Nodes', '',
    '| id | role | depends_on | declared_write_set | cardinality | shape |',
    '| --- | --- | --- | --- | --- | --- |',
    '| impl-core | tdd-guide | — | scripts/x.js | 1 | sequence |',
    '| review | code-reviewer | impl-core | — | 1 | sequence |',
    '| finalize | finalize | review | — | 1 | sequence |', '',
    '## Node Briefs', '', '### impl-core', 'Patch the installed tooling.', '',
    '## Design', '', design, '',
    '## Node Ledger', '',
    '| id | status |', '| --- | --- |',
    '| impl-core | in_progress |', '| review | pending |', '| finalize | pending |', '',
  ].join('\n') + '\n';
  const DESIGN_A_846 = 'Decompose the frozen spine into concrete role nodes; every sequence edge is '
    + 'a real data dependency (S1) and the review gate post-dominates the writer.';
  const DESIGN_B_846 = 'Re-planned after the review gate refuted the original shape: the writer is '
    + 'split and the gate re-anchored on the merged parent.';

  const lineage846 = (repoRoot, sessionMarker, head, tree) => schema846.buildEpochLineage({
    repository_id: 'kw/fixture-846', issue_numbers: [846], primary_issue: 846,
    closure_policy: 'all', branch: 'wf/846', worktree_path: repoRoot,
    claim_ts: '2026-07-29T00:00:00Z', session_marker: sessionMarker,
  }, { object_format: 'sha1', commit: head, tree, branch: 'wf/846' });

  function makeConsentRepo846() {
    const repoRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'kw-846-consent-'));
    const project = 'issue-846';
    const projDir = path.join(repoRoot, 'kaola-workflow', project);
    fs.mkdirSync(path.join(projDir, '.cache'), { recursive: true });
    const planPath = path.join(projDir, 'workflow-plan.md');
    const statePath = path.join(projDir, 'workflow-state.md');
    const body = planBody846(DESIGN_A_846);
    const hash = planValidator.computePlanHash(body);
    fs.writeFileSync(planPath, '<!-- plan_hash: ' + hash + ' -->\n' + body);
    const g = (a) => exec846('git', ['-C', repoRoot, ...a],
      { encoding: 'utf8', stdio: ['ignore', 'ignore', 'ignore'] });
    g(['init']); g(['config', 'user.email', 'kw@test']); g(['config', 'user.name', 'kw']);
    g(['config', 'commit.gpgsign', 'false']);
    fs.writeFileSync(path.join(repoRoot, 'README.md'), '# fixture-846\n');
    g(['add', '-A']); g(['commit', '-m', 'init']);
    const head = exec846('git', ['-C', repoRoot, 'rev-parse', 'HEAD'], { encoding: 'utf8' }).trim();
    const tree = exec846('git', ['-C', repoRoot, 'rev-parse', 'HEAD^{tree}'], { encoding: 'utf8' }).trim();
    const lin = lineage846(repoRoot, 'sess-A-846', head, tree);
    let s = 'name: issue-846\nstatus: in_progress\nbranch: wf/846\nissue_number: 846\n';
    s = schema846.writeEpochStateBlock(s, {
      epoch_schema_version: 2, claim_repository_id: 'kw/fixture-846',
      claim_identity_digest: lin.claim_identity_digest,
      claim_root_object_format: 'sha1', claim_root_base_commit: head, claim_root_base_tree: tree,
      claim_root_base_digest: lin.claim_root_base_digest,
      epoch_lineage_id: lin.epoch_lineage_id,
      plan_epoch: 1, active_plan_hash: hash,
      automatic_review_replans: 0, authorized_epoch_ceiling: 2,
      replan_status: 'none', replan_transaction_id: 'none',
    });
    fs.writeFileSync(statePath, s);
    return { repoRoot, project, projDir, planPath, statePath, hash, head, tree };
  }

  // ONE process per call. Nothing is carried between calls but bytes on disk. The RAW form is the
  // primitive because #858 asks what the process DID, not only what it printed: a run that dies
  // before emitting anything has an empty envelope, and an empty envelope is indistinguishable
  // from a quiet success unless the exit status is read alongside it.
  // spawn-class: durable-handoff
  function run846Raw(fx, args, opts) {
    const o = opts || {};
    const argv = (o.preload ? ['--require', o.preload] : []).concat([NODE_CLI_846], args);
    const env = o.env ? Object.assign({}, process.env, o.env) : process.env;
    const r = spawn846(process.execPath, argv, { cwd: fx.repoRoot, encoding: 'utf8', env });
    let out = {};
    try { out = JSON.parse(String(r.stdout || '').trim().split('\n').pop()); } catch (_) {}
    return { envelope: out, status: r.status, stdout: String(r.stdout || ''), stderr: String(r.stderr || '') };
  }
  const run846 = (fx, args, opts) => run846Raw(fx, args, opts).envelope;
  const askArgs846 = (fx, cls, reason) => ['write-halt', '--project', fx.project,
    '--node-id', 'impl-core', '--reason', reason || 'consent',
    ...(cls ? ['--consent-class', cls] : []), '--json'];
  const ask846 = (fx, cls, reason) => run846(fx, askArgs846(fx, cls, reason));
  const clear846 = (fx) => run846(fx, ['clear-halt', '--project', fx.project, '--reason', 'consent', '--json']);
  const orient846 = (fx) => run846(fx, ['orient', '--project', fx.project, '--json']);
  const patchState846 = (fx, values) => fs.writeFileSync(fx.statePath,
    schema846.writeEpochStateBlock(fs.readFileSync(fx.statePath, 'utf8'), values));
  const haltMarker846 = (fx) => readDurableConsentHalt(fs.readFileSync(fx.planPath, 'utf8'));
  const escalated846 = (fx) => /^escalated_to_full:/m.test(fs.readFileSync(fx.statePath, 'utf8'));
  const liveGrant846 = (o, cls) => (Array.isArray(o.consentGrants) ? o.consentGrants : [])
    .find(g => g && g.class === cls && g.revoked !== true) || null;
  const cleanup846 = (fx) => { try { fs.rmSync(fx.repoRoot, { recursive: true, force: true }); } catch (_) {} };
  // Grant CLASS_846 the way a real run does: ask, then have the human clear. Returns the
  // clear-halt envelope so a scenario can assert on the grant record itself.
  const grant846 = (fx, cls) => { ask846(fx, cls || CLASS_846); return clear846(fx); };

  const store846 = (fx) => path.join(fx.projDir, '.cache', schema846.CONSENT_GRANTS_NAME);
  // The journal AS EVENTS, in order — the durable record the fold is computed from. Null when
  // there is no store at all, which is a different fact from an empty journal.
  const journal846 = (fx) => {
    try { return (JSON.parse(fs.readFileSync(store846(fx), 'utf8')).journal || []).map(e => e.event); }
    catch (_) { return null; }
  };

  // #858 — THE STORE-WRITE FAULT INJECTOR. The consent store persists through
  // writeFileAtomicReplace, whose last step renames a temp file onto .cache/consent-grants.json;
  // failing THAT rename is the read-only mount / full disk / permissions change / interrupted
  // mount the defect names, and it is surgical — the scheduler lock, the plan write and the state
  // write all rename normally in the same process, so nothing but the consent store is disturbed.
  //
  // `failFirst: 1` is a TRANSIENT fault: the revocation write fails and a later write in the same
  // process succeeds. That distinction is load-bearing rather than incidental — under a PERSISTENT
  // fault the second write fails too and the process dies either way, so the swallowed revocation
  // is invisible; it is exactly the recoverable fault that let a stale grant be honoured quietly.
  //
  // Every attempt is logged, so a scenario can assert a write was never even ATTEMPTED. That is
  // what "zero-write no-op" has to mean here: "the write did not happen" is also true of a write
  // that was attempted and thrown out of, and those are opposite facts.
  function armStoreFault846(fx, failFirst) {
    const preload = path.join(fx.repoRoot, 'consent-store-fault.js');
    const attempts = path.join(fx.repoRoot, 'consent-store-attempts.log');
    fs.writeFileSync(preload, [
      'const fs = require("fs"); const p = require("path");',
      'const real = fs.renameSync; let seen = 0;',
      'fs.renameSync = function (from, to) {',
      '  if (p.basename(String(to)) === "consent-grants.json") {',
      '    seen += 1;',
      '    const n = parseInt(process.env.KW858_FAIL_FIRST, 10);',
      '    const willFail = (n === 0) || (seen <= n);',
      '    try { fs.appendFileSync(process.env.KW858_ATTEMPTS, seen + " " + willFail + "\\n"); } catch (e) {}',
      '    if (willFail) { const e = new Error("EACCES rename onto the consent store"); e.code = "EACCES"; throw e; }',
      '  }',
      '  return real.apply(fs, arguments);',
      '};',
    ].join('\n') + '\n');
    return {
      preload,
      env: { KW858_FAIL_FIRST: String(failFirst), KW858_ATTEMPTS: attempts },
      attempts: () => {
        try { return fs.readFileSync(attempts, 'utf8').trim().split('\n').filter(Boolean).length; }
        catch (_) { return 0; }
      },
    };
  }

  // -------------------------------------------------------------------------
  // #846-A — THE SUBTRACTION ITSELF, end to end, across four separate processes.
  // Ask -> yes -> the SAME question is never put again inside the claim; each application is
  // journaled and a zero-context successor can read both the grant and its application count.
  // -------------------------------------------------------------------------
  scenario(() => {
    const fx = makeConsentRepo846();

    // A1. A brand-new class ALWAYS asks (design answer 4). The valve is untouched for anything
    // ungranted: the durable marker and the state cause line land exactly as they do today. What is
    // new is that the request NAMES its class, and the envelope SAYS it did not ride a grant.
    const a1 = ask846(fx, CLASS_846);
    assert(a1.result === 'ok' && a1.halt === 'written',
      '#846-A1: an ungranted class still raises the valve, got ' + JSON.stringify({ result: a1.result, halt: a1.halt }));
    assert(haltMarker846(fx) === true && escalated846(fx) === true,
      '#846-A1: ...with the real durable markers (ledger consent_halt + escalated_to_full), got '
      + JSON.stringify({ marker: haltMarker846(fx), escalated: escalated846(fx) }));
    assert(a1.standing_grant === false,
      '#846-A1: ...and the envelope states, in so many words, that NO standing grant answered this '
      + 'question. A valve that is silent about which of the two things it did is a valve whose '
      + 'applications cannot be audited, got ' + JSON.stringify(a1.standing_grant));
    assert(a1.consent_class === CLASS_846,
      '#846-A1: ...and the pending request carries the class, which is the ONLY thing clear-halt can '
      + 'later grant — a grant that is not the answer to the question asked is a widened grant, got '
      + JSON.stringify(a1.consent_class));

    // A2. The human says yes. clear-halt grants exactly the class the pending halt recorded. There
    // is deliberately NO class flag here: the grant is the answer to the question that was put.
    const a2 = clear846(fx);
    assert(a2.result === 'ok' && a2.halt === 'cleared',
      '#846-A2: clear-halt(consent) still clears the halt, got ' + JSON.stringify({ result: a2.result, halt: a2.halt }));
    assert(a2.standing_grant_recorded === CLASS_846,
      '#846-A2: ...and records the standing grant for the class that was ASKED — not one supplied at '
      + 'clear time, which is how a grant would widen past the question the human saw, got '
      + JSON.stringify(a2.standing_grant_recorded));
    assert(haltMarker846(fx) === false && escalated846(fx) === false,
      '#846-A2: ...and the halt is genuinely gone, got '
      + JSON.stringify({ marker: haltMarker846(fx), escalated: escalated846(fx) }));

    // A3. THE 33 MINUTES. A FRESH PROCESS — no heap, no cache, nothing but the bytes on disk —
    // asks the identical question and is NOT stopped. This is the whole issue.
    const a3 = ask846(fx, CLASS_846);
    assert(a3.result === 'ok' && a3.standing_grant === true,
      '#846-A3: the SAME class inside the SAME claim proceeds on the standing grant instead of '
      + 'putting the question a second time, got ' + JSON.stringify({ result: a3.result, standing_grant: a3.standing_grant, halt: a3.halt }));
    assert(a3.consent_class === CLASS_846,
      '#846-A3: ...naming the class it rode, got ' + JSON.stringify(a3.consent_class));
    assert(a3.halt !== 'written' && haltMarker846(fx) === false && escalated846(fx) === false,
      '#846-A3: ...and NOTHING halts — no ledger consent_halt marker, no escalated_to_full cause '
      + 'line. A "standing grant" that still writes the halt has subtracted nothing, got '
      + JSON.stringify({ halt: a3.halt, marker: haltMarker846(fx), escalated: escalated846(fx) }));

    // A4. Third time (the issue measured three). Still no question.
    const a4 = ask846(fx, CLASS_846);
    assert(a4.standing_grant === true && haltMarker846(fx) === false,
      '#846-A4: and the third instance too — the grant does not decay after one use, got '
      + JSON.stringify({ standing_grant: a4.standing_grant, marker: haltMarker846(fx) }));

    // A5. DESIGN ANSWER 3: every APPLICATION is journaled, not just the grant — and the journal is
    // durable, because the successor that reads it here shares nothing with the processes that
    // wrote it. A standing grant applied invisibly is indistinguishable from no valve at all.
    const a5 = orient846(fx);
    assert(a5.result === 'ok' && Array.isArray(a5.consentGrants),
      '#846-A5: orient — the zero-context successor surface — reports the standing grants as an '
      + 'array, got ' + JSON.stringify({ result: a5.result, consentGrants: a5.consentGrants }));
    const g5 = liveGrant846(a5, CLASS_846);
    assert(g5 !== null,
      '#846-A5: ...including the grant made in an earlier process (A1: a successor with zero context '
      + 'sees the same grants; an in-memory cache satisfies nothing here), got '
      + JSON.stringify(a5.consentGrants));
    assert(g5 && g5.applications === 2,
      '#846-A5: ...and the count of APPLICATIONS, so "logged, not re-asked" is auditable rather than '
      + 'merely quieter. Two applications rode this grant (A3, A4), got '
      + JSON.stringify(g5 && g5.applications));

    cleanup846(fx);
  });

  // -------------------------------------------------------------------------
  // #846-B — SAME ACTION, DIFFERENT TARGET STILL ASKS. Design answer 1 rejected the action verb
  // alone precisely so a grant cannot leak to a target the human never saw when they said yes.
  // The live-grant control runs FIRST so this negative can never pass merely because no grant
  // exists at all.
  // -------------------------------------------------------------------------
  scenario(() => {
    const fx = makeConsentRepo846();
    grant846(fx, CLASS_846);
    const control = ask846(fx, CLASS_846);
    assert(control.standing_grant === true,
      '#846-B control: the grant for ' + CLASS_846 + ' is live before the negative is tested, got '
      + JSON.stringify(control.standing_grant));

    const b = ask846(fx, OTHER_TARGET_846);
    assert(b.standing_grant === false,
      '#846-B: a request whose ACTION matches the grant but whose TARGET does not is a DIFFERENT '
      + 'class and must still put the question — a grant that covered it would authorize a target '
      + 'the human never saw, got ' + JSON.stringify(b.standing_grant));
    assert(b.halt === 'written' && haltMarker846(fx) === true && escalated846(fx) === true,
      '#846-B: ...and the valve genuinely halts, got '
      + JSON.stringify({ halt: b.halt, marker: haltMarker846(fx), escalated: escalated846(fx) }));
    assert(b.consent_class === OTHER_TARGET_846,
      '#846-B: ...for the target actually requested, got ' + JSON.stringify(b.consent_class));
    cleanup846(fx);
  });

  // -------------------------------------------------------------------------
  // #846-C — A BRAND-NEW CLASS ALWAYS ASKS (design answer 4). Nothing in this issue widens WHAT
  // may be consented to; it changes only how often the same question is put.
  // -------------------------------------------------------------------------
  scenario(() => {
    const fx = makeConsentRepo846();
    grant846(fx, CLASS_846);
    const control = ask846(fx, CLASS_846);
    assert(control.standing_grant === true,
      '#846-C control: the grant is live before the negative is tested, got ' + JSON.stringify(control.standing_grant));

    const c = ask846(fx, OTHER_ACTION_846);
    assert(c.standing_grant === false && c.halt === 'written' && haltMarker846(fx) === true,
      '#846-C: an ungranted class is untouched by any other class\'s grant — the valve is whole for '
      + 'everything nobody has said yes to, got '
      + JSON.stringify({ standing_grant: c.standing_grant, halt: c.halt, marker: haltMarker846(fx) }));
    cleanup846(fx);
  });

  // -------------------------------------------------------------------------
  // #846-D — A RE-PLAN EPOCH REVOKES, AND THE HUMAN CAN ANSWER AGAIN. Design answer 2: the grant
  // lives for the CLAIM and dies on re-plan, because the plan the human consented under no longer
  // exists. Driven the way an activation actually moves the position record: new plan bytes (new
  // plan_hash), plan_epoch advanced, active_plan_hash re-pointed.
  //
  // WHAT REVOCATION IS, AND WHAT IT IS NOT. It ends the GRANT — the answer given under the vanished
  // plan — not the CLASS. The issue's scope answer is "the next request asks again"; a rule that
  // also refused to honour the answer to that fresh question would be a second, undecided rule, and
  // it would make the whole subtraction inert after the first re-plan (re-plans are routine here),
  // handing back the 33 minutes of dead wall-clock the issue exists to remove. So the pin runs the
  // full round trip: revoke, ask, ANSWER, and the answer stands exactly as A2's does — with its
  // application tally restarted, so no pre-re-plan count is silently carried across the epoch.
  // -------------------------------------------------------------------------
  scenario(() => {
    const fx = makeConsentRepo846();
    grant846(fx, CLASS_846);
    const control = ask846(fx, CLASS_846);
    assert(control.standing_grant === true,
      '#846-D control: the grant is live under the PARENT epoch, got ' + JSON.stringify(control.standing_grant));

    const bodyB = planBody846(DESIGN_B_846);
    const hashB = planValidator.computePlanHash(bodyB);
    assert(hashB !== fx.hash, '#846-D control: the child epoch is genuinely a different plan');
    fs.writeFileSync(fx.planPath, '<!-- plan_hash: ' + hashB + ' -->\n' + bodyB);
    patchState846(fx, { plan_epoch: 2, active_plan_hash: hashB });

    const d = ask846(fx, CLASS_846);
    assert(d.standing_grant === false,
      '#846-D: after the epoch advances, the standing grant is REVOKED and the next request asks '
      + 'again — consent given under a plan that has been rewritten is not consent to the rewrite, '
      + 'got ' + JSON.stringify(d.standing_grant));
    assert(d.halt === 'written' && readDurableConsentHalt(fs.readFileSync(fx.planPath, 'utf8')) === true,
      '#846-D: ...and the valve really halts, got ' + JSON.stringify(d.halt));

    // ...and the human ANSWERS that question, under the plan actually in front of them. This is a
    // grant made afresh under the CHILD epoch, not the parent's grant surviving: it is the same
    // ask -> yes the run has always done, and clear-halt records exactly the class that was asked.
    const yes = clear846(fx);
    assert(yes.standing_grant_recorded === CLASS_846,
      '#846-D: ...and clearing that halt records a grant for the class asked under the CHILD epoch — '
      + 'revocation ends the answer given under the vanished plan, not the human\'s standing to '
      + 'answer the question the new plan puts, got ' + JSON.stringify(yes.standing_grant_recorded));
    const d2 = ask846(fx, CLASS_846);
    assert(d2.standing_grant === true,
      '#846-D: ...so the NEXT instance rides the fresh grant. A grant that is refused for the rest '
      + 'of the claim makes the subtraction inert after the first re-plan and hands the 33 minutes '
      + 'straight back, got ' + JSON.stringify({ standing_grant: d2.standing_grant, halt: d2.halt }));
    const g = liveGrant846(orient846(fx), CLASS_846);
    assert(g && g.applications === 1,
      '#846-D: ...counted from ZERO — one application (d2) rode the child-epoch grant. Carrying the '
      + 'parent epoch\'s tally forward would let the journal report applications of a grant that no '
      + 'longer exists, got ' + JSON.stringify(g));
    cleanup846(fx);
  });

  // -------------------------------------------------------------------------
  // #846-E — A DISCARD+RESTART REVOKES. A restart mints a new claim identity (a new session
  // marker/claim_ts re-derives claim_identity_digest, and with it epoch_lineage_id). The grant is
  // scoped to the CLAIM, so it does not cross that boundary.
  // -------------------------------------------------------------------------
  scenario(() => {
    const fx = makeConsentRepo846();
    grant846(fx, CLASS_846);
    const control = ask846(fx, CLASS_846);
    assert(control.standing_grant === true,
      '#846-E control: the grant is live under the ORIGINAL claim, got ' + JSON.stringify(control.standing_grant));

    const restarted = lineage846(fx.repoRoot, 'sess-B-846-restarted', fx.head, fx.tree);
    assert(restarted.epoch_lineage_id !== undefined && restarted.claim_identity_digest !== undefined,
      '#846-E control: the restarted claim has its own lineage');
    patchState846(fx, {
      claim_identity_digest: restarted.claim_identity_digest,
      epoch_lineage_id: restarted.epoch_lineage_id,
    });

    const e = ask846(fx, CLASS_846);
    assert(e.standing_grant === false && e.halt === 'written',
      '#846-E: a discard+restart is a NEW claim, and a grant made by the previous claim does not '
      + 'answer for it — the next request asks again, got '
      + JSON.stringify({ standing_grant: e.standing_grant, halt: e.halt }));
    cleanup846(fx);
  });

  // -------------------------------------------------------------------------
  // #846-F — A NEW CANDIDATE DIGEST REVOKES, AND THE REVOCATION DOES NOT UNDO ITSELF.
  //
  // WHY THIS IS THE ONLY NON-VACUOUS FORM OF THAT TRIGGER. While `replan_status: candidate_changed`
  // stands, the project is replan-FENCED: the fence in the CLI prologue refuses every mutating verb
  // (and orient) before any body runs, so "it asks while the candidate is changed" is already true
  // by construction and pins nothing. The entire content of the trigger is what happens AFTER the
  // fence lifts — the fork is discarded, `replan_status` returns to `none`, and the epoch, claim and
  // plan hash are all exactly what they were. An implementation that merely COMPARES a recorded
  // scope binding against the current one resurrects the grant here, silently, and the human is
  // never asked about the candidate they never saw. Revocation must be durable, not derived.
  // -------------------------------------------------------------------------
  scenario(() => {
    const fx = makeConsentRepo846();
    grant846(fx, CLASS_846);
    const control = ask846(fx, CLASS_846);
    assert(control.standing_grant === true,
      '#846-F control: the grant is live before the candidate moves, got ' + JSON.stringify(control.standing_grant));

    // The fork observes a changed candidate at a CAS seam and records it in the position record.
    patchState846(fx, { replan_status: 'candidate_changed', replan_transaction_id: 'tx-846-cc' });
    const fenced = ask846(fx, CLASS_846);
    assert(fenced.standing_grant !== true,
      '#846-F: while the candidate change stands the project is fenced, and no standing grant may '
      + 'be applied through it, got ' + JSON.stringify({ result: fenced.result, reason: fenced.reason, standing_grant: fenced.standing_grant }));

    // The fork is discarded. Epoch, claim identity and plan hash are byte-identical to the state the
    // grant was made under — the ONLY thing that happened is that the candidate moved.
    patchState846(fx, { replan_status: 'none', replan_transaction_id: 'none' });
    const f = ask846(fx, CLASS_846);
    assert(f.result === 'ok',
      '#846-F precondition: the project is unfenced again, got ' + JSON.stringify({ result: f.result, reason: f.reason }));
    assert(f.standing_grant === false,
      '#846-F: a new candidate digest REVOKES the standing grant, and restoring the surrounding '
      + 'state does not bring it back. A grant that returns from the dead the moment the scalars '
      + 'match again is not a revocation, got ' + JSON.stringify(f.standing_grant));
    assert(f.halt === 'written' && haltMarker846(fx) === true,
      '#846-F: ...so the next request genuinely asks, got '
      + JSON.stringify({ halt: f.halt, marker: haltMarker846(fx) }));
    cleanup846(fx);
  });

  // -------------------------------------------------------------------------
  // #846-G — A GRANT NEVER WIDENS *WHAT* MAY BE CONSENTED TO, ONLY HOW OFTEN THE QUESTION IS PUT.
  // A standing CONSENT grant is not standing authority over the other halt reasons. `security` and
  // `integrity` are different questions — and `integrity` is the R4 halt, where the deviation IS
  // the evidence and clear-halt does not even accept it.
  // -------------------------------------------------------------------------
  scenario(() => {
    const fx = makeConsentRepo846();
    grant846(fx, CLASS_846);
    const control = ask846(fx, CLASS_846);
    assert(control.standing_grant === true,
      '#846-G control: the consent grant is live, got ' + JSON.stringify(control.standing_grant));

    const sec = ask846(fx, CLASS_846, 'security');
    assert(sec.standing_grant === false,
      '#846-G: a standing CONSENT grant does not answer a SECURITY halt for the same class — the '
      + 'grant changes how often one question is put, never which questions may be skipped, got '
      + JSON.stringify(sec.standing_grant));
    assert(sec.halt === 'written' && Array.isArray(sec.markers)
      && sec.markers.includes('escalated_to_full:security'),
      '#846-G: ...and the security halt lands with its own cause marker, got ' + JSON.stringify(sec.markers));
    clear846(fx);

    const integ = ask846(fx, CLASS_846, 'integrity');
    assert(integ.standing_grant === false && integ.halt === 'written',
      '#846-G: ...and least of all the R4 integrity halt, whose whole point is that the deviation is '
      + 'itself evidence and is never auto-cleared, got '
      + JSON.stringify({ standing_grant: integ.standing_grant, halt: integ.halt }));
    cleanup846(fx);
  });

  // -------------------------------------------------------------------------
  // #846-H — THE CLASSLESS VALVE IS BYTE-FOR-BYTE THE VALVE WE HAVE. A consent halt raised without
  // a class grants nothing and is re-asked forever, exactly as today. Opting in is what records a
  // grant; nothing is granted by omission.
  // -------------------------------------------------------------------------
  scenario(() => {
    const fx = makeConsentRepo846();
    const h1 = ask846(fx, null);
    assert(h1.result === 'ok' && h1.halt === 'written' && haltMarker846(fx) === true,
      '#846-H: a classless consent halt behaves exactly as today, got '
      + JSON.stringify({ result: h1.result, halt: h1.halt, marker: haltMarker846(fx) }));
    assert(h1.standing_grant === false,
      '#846-H: ...and still SAYS no standing grant answered it — the field is unconditional, so a '
      + 'reader never has to infer from absence, got ' + JSON.stringify(h1.standing_grant));

    const h2 = clear846(fx);
    assert(h2.result === 'ok' && (h2.standing_grant_recorded == null),
      '#846-H: clearing a classless halt records NO grant — a grant by omission would authorize a '
      + 'class nobody named, got ' + JSON.stringify(h2.standing_grant_recorded));

    const h3 = orient846(fx);
    assert(h3.result === 'ok' && Array.isArray(h3.consentGrants) && h3.consentGrants.length === 0,
      '#846-H: ...and the successor reads an EMPTY grant set, not a missing one, got '
      + JSON.stringify(h3.consentGrants));

    const h4 = ask846(fx, null);
    assert(h4.halt === 'written' && haltMarker846(fx) === true,
      '#846-H: ...so the same classless question is put again, forever, got '
      + JSON.stringify({ halt: h4.halt, marker: haltMarker846(fx) }));
    cleanup846(fx);
  });

  // -------------------------------------------------------------------------
  // #846-I — TWO CLASSES PENDING AT ONCE: A CLASSLESS CLEAR GRANTS NEITHER.
  //
  // `write-halt` is deliberately NOT halt-fenced — it IS the valve, so it has to stay raisable while
  // a halt already stands. Two DIFFERENT classes can therefore be outstanding at the same moment (any
  // fan-out whose legs gate different classes reaches this, and so does a crash-resume that re-derives
  // a different class), while the durable `consent_halt: pending` marker is CLASSLESS and is written
  // once. One marker then stands for TWO questions, and nothing on disk says which of them the human
  // was shown or which they answered.
  //
  // THE DANGEROUS DIRECTION, exactly: the human approves X and REFUSES Y; the orchestrator clears the
  // one halt after handling X; a grant minted for Y suppresses every future Y question for the rest of
  // the claim. A human's "no" has been recorded as a standing "yes" — a machine deciding a value call,
  // inside the one subsystem whose entire purpose is routing value calls to a human.
  //
  // A discharge that is not unambiguous is not a discharge: with more than one class pending, NOTHING
  // is granted. That degrade is SAFE by construction — it is precisely the behavior of the valve
  // before standing grants existed (ask every time) — and it needs no refusal code and no new flag.
  // Two shapes that are NOT the repair: a `--consent-class` flag on `clear-halt` would let the answer
  // be re-stated at clear time, which is the one thing a classless clear makes structurally
  // impossible; and REFUSING the second raise would fence the valve against itself.
  // -------------------------------------------------------------------------
  scenario(() => {
    const fx = makeConsentRepo846();
    const i1 = ask846(fx, CLASS_846);
    assert(i1.halt === 'written' && i1.standing_grant === false,
      '#846-I precondition: the first class raises the valve, got '
      + JSON.stringify({ halt: i1.halt, standing_grant: i1.standing_grant }));

    const i2 = ask846(fx, OTHER_ACTION_846);
    assert(i2.result === 'ok' && i2.halt === 'written',
      '#846-I precondition: a SECOND, different class raises while the first is still pending. The '
      + 'valve does not fence itself — write-halt must stay raisable while a halt stands — so this '
      + 'state is reachable in a real run rather than hypothetical, and refusing the second raise is '
      + 'not the repair, got ' + JSON.stringify({ result: i2.result, reason: i2.reason, halt: i2.halt }));

    // The human answers ONE of the two. `clear-halt` carries no class, by design.
    const i3 = clear846(fx);
    assert(i3.result === 'ok' && i3.halt === 'cleared',
      '#846-I: the clear itself still succeeds — ambiguity is answered by granting nothing, never by '
      + 'refusing to clear, which would strand the run behind a halt it cannot lift, got '
      + JSON.stringify({ result: i3.result, reason: i3.reason, halt: i3.halt }));
    assert(i3.standing_grant_recorded == null,
      '#846-I: ...and with TWO classes pending it records NO standing grant. One classless marker '
      + 'stood for two questions, so nothing on disk says which one the human saw; minting a grant '
      + 'for the LAST-RAISED class turns "yes to X, no to Y" into a standing yes to Y, got '
      + JSON.stringify(i3.standing_grant_recorded));

    const i4 = orient846(fx);
    assert(Array.isArray(i4.consentGrants) && i4.consentGrants.length === 0,
      '#846-I: ...and the zero-context successor is shown no live grant at all, got '
      + JSON.stringify(i4.consentGrants));

    const i5 = ask846(fx, OTHER_ACTION_846);
    assert(i5.standing_grant === false && i5.halt === 'written' && haltMarker846(fx) === true,
      '#846-I: ...so the LAST-RAISED class — the one an operator who approved only the first never '
      + 'consented to — still puts its question, got '
      + JSON.stringify({ standing_grant: i5.standing_grant, halt: i5.halt, marker: haltMarker846(fx) }));

    const i6 = ask846(fx, CLASS_846);
    assert(i6.standing_grant === false,
      '#846-I: ...and so does the FIRST. Resolving the ambiguity by granting the EARLIEST pending '
      + 'class instead is the same defect with the arrow reversed, got '
      + JSON.stringify(i6.standing_grant));
    cleanup846(fx);
  });

  // -------------------------------------------------------------------------
  // #846-J — AMBIGUITY IS NOT A DEAD END. Granting nothing when two classes are pending withholds an
  // answer the human never gave; it must not withhold their ability to give one. The question is put
  // again, and the next answer — to a single, unambiguous pending question — is recorded exactly as
  // #846-A2's is. A run that could never obtain a grant again once two classes had overlapped would
  // be a permanent stuck state manufactured by the repair itself.
  // -------------------------------------------------------------------------
  scenario(() => {
    const fx = makeConsentRepo846();
    ask846(fx, CLASS_846);
    ask846(fx, OTHER_ACTION_846);
    const amb = clear846(fx);
    assert(amb.result === 'ok',
      '#846-J precondition: the ambiguous discharge clears, got '
      + JSON.stringify({ result: amb.result, reason: amb.reason }));

    const j1 = ask846(fx, CLASS_846);
    assert(j1.result === 'ok' && j1.halt === 'written' && j1.standing_grant === false,
      '#846-J: the class puts its question again, got '
      + JSON.stringify({ result: j1.result, halt: j1.halt, standing_grant: j1.standing_grant }));
    const j2 = clear846(fx);
    assert(j2.standing_grant_recorded === CLASS_846,
      '#846-J: ...and THIS discharge is unambiguous — exactly one class pending — so the human\'s '
      + 'answer is recorded normally. Nothing about an earlier overlap disqualifies a later, clean '
      + 'question, got ' + JSON.stringify(j2.standing_grant_recorded));
    const j3 = ask846(fx, CLASS_846);
    assert(j3.standing_grant === true && j3.halt !== 'written',
      '#846-J: ...so the next instance rides it, got '
      + JSON.stringify({ standing_grant: j3.standing_grant, halt: j3.halt }));
    cleanup846(fx);
  });

  // -------------------------------------------------------------------------
  // #846-K — THE SAME CLASS RAISED TWICE IS STILL ONE QUESTION. What makes a discharge ambiguous is
  // two DIFFERENT classes outstanding, never two raises. The issue's own measured case is the
  // IDENTICAL question raised three times; if a repeat raise counted as a second pending request, the
  // discharge would be "ambiguous" exactly where the subtraction was measured and the whole mechanism
  // would be inert. What is pending is a SET of classes, not a tally of raises.
  // -------------------------------------------------------------------------
  scenario(() => {
    const fx = makeConsentRepo846();
    const k1 = ask846(fx, CLASS_846);
    const k2 = ask846(fx, CLASS_846);
    assert(k1.halt === 'written' && k2.result === 'ok' && k2.standing_grant === false,
      '#846-K precondition: the same class is raised twice before anyone answers, got '
      + JSON.stringify({ first: k1.halt, second: k2.result, standing_grant: k2.standing_grant }));
    const k3 = clear846(fx);
    assert(k3.standing_grant_recorded === CLASS_846,
      '#846-K: one class pending — however many times it was raised — is ONE question, and the '
      + 'human\'s yes answers it, got ' + JSON.stringify(k3.standing_grant_recorded));
    const k4 = ask846(fx, CLASS_846);
    assert(k4.standing_grant === true && k4.halt !== 'written',
      '#846-K: ...so the grant is live and the next instance rides it — the issue\'s measured case, '
      + 'end to end, got ' + JSON.stringify({ standing_grant: k4.standing_grant, halt: k4.halt }));
    cleanup846(fx);
  });

  // Targets are paths, hosts and URLs, so a colon INSIDE the target is ordinary: this is the action
  // `deploy` on the host:port `db.prod:5432`, not a three-part class.
  const HOSTPORT_846 = 'deploy:db.prod:5432';

  // -------------------------------------------------------------------------
  // #846-L — THE CLASS KEY DOES NOT LEAK ACROSS A COLON. A class is an ACTION and a TARGET, and the
  // separator is not private to the separator: `db.prod:5432`, `C:\...` and `https://...` all carry
  // colons of their own. Whatever the key is made of, four things hold — a multi-colon target matches
  // only itself; the action plus a PREFIX of the target is a different class; a bare action with no
  // target is a different class again, which can neither ride an action:target grant nor be ridden by
  // one; and the class an operator reads back is the one they typed, so what `orient` shows them
  // matches what they would pass to `--consent-class`.
  //
  // Two SPELLINGS of one path stay distinct too. That is not an oversight to be normalized away:
  // asking twice about one directory costs one question, whereas collapsing two spellings hands a
  // grant to a path the human never read.
  // -------------------------------------------------------------------------
  scenario(() => {
    const fx = makeConsentRepo846();
    grant846(fx, HOSTPORT_846);
    assert(ask846(fx, HOSTPORT_846).standing_grant === true,
      '#846-L control: the grant for ' + HOSTPORT_846 + ' is live, and a target that itself contains '
      + 'a colon matches itself');
    assert(ask846(fx, 'deploy:db.prod').standing_grant === false,
      '#846-L: the action plus a PREFIX of the granted target is a DIFFERENT class — splitting at the '
      + 'wrong colon would widen a grant for one host:port into a grant for the whole host');
    assert(ask846(fx, 'deploy:db.prod:5433').standing_grant === false,
      '#846-L: ...and a different port is a different target');
    assert(ask846(fx, 'deploy').standing_grant === false,
      '#846-L: ...and the bare action rides nothing: a grant for one target is never authority over '
      + 'the action itself');

    const fx2 = makeConsentRepo846();
    grant846(fx2, 'deploy');
    assert(ask846(fx2, 'deploy').standing_grant === true,
      '#846-L control: a targetless class can be granted and rides itself');
    assert(ask846(fx2, 'deploy:db.prod').standing_grant === false,
      '#846-L: ...and answers for no target — the same leak, inverted');
    const o2 = orient846(fx2);
    assert(liveGrant846(o2, 'deploy') !== null,
      '#846-L: ...and the successor reads the class back EXACTLY as the operator named it, not '
      + 're-serialized from its parts, got ' + JSON.stringify(o2.consentGrants));

    const fx3 = makeConsentRepo846();
    grant846(fx3, CLASS_846);
    assert(ask846(fx3, CLASS_846 + '/').standing_grant === false
      && ask846(fx3, 'patch-installed-tooling:~/.claude/./agents').standing_grant === false,
      '#846-L: two spellings of one path are two classes and both ask again');
    cleanup846(fx); cleanup846(fx2); cleanup846(fx3);
  });

  // -------------------------------------------------------------------------
  // #846-M — NO CLAIM IDENTITY, NO STANDING GRANT. A grant's lifetime is THE CLAIM, and that binding
  // is a digest over the position record. Every field in the digest falls back to the literal token
  // `none` when it is absent — and `none` is ALSO exactly what the schema writes for an identity
  // field it does not have. So a state that cannot identify its claim does not fail to bind: it binds
  // to a shared constant that no boundary can move, and the grant then outlives the very boundaries
  // (#846-D/E/F) that exist to end it, silently and with no reader able to tell.
  //
  // Fail SAFE, not fail closed. Where the scope cannot be identified there is simply nothing for a
  // grant to be bound to, so none is recorded and none is live: the valve just asks, exactly as it
  // did before standing grants existed. No refusal, no halt of its own, nothing for an operator to
  // clear — the run is never worse off than the day before this feature landed.
  //
  // AND NOTE WHICH `none` IS WHICH. `replan_status: none` and `replan_transaction_id: none` are the
  // REAL values on every healthy run — see the control. Reading the token as "unavailable" wherever
  // it appears would make the subtraction inert on every run there is.
  // -------------------------------------------------------------------------
  scenario(() => {
    const ctl = makeConsentRepo846();
    grant846(ctl, CLASS_846);
    assert(ask846(ctl, CLASS_846).standing_grant === true,
      '#846-M control: an ordinary claim — whose replan_status and replan_transaction_id ARE the '
      + 'literal token "none" — grants and rides normally. Scope identity being unavailable means the '
      + 'CLAIM cannot be identified, never "the token none appears in the position record"');
    cleanup846(ctl);

    const fx = makeConsentRepo846();
    // The claim-identifying fields are gone. An absent field is recorded as `none`, which is the same
    // thing the digest would have substituted for it anyway — that is the whole failure.
    patchState846(fx, { claim_identity_digest: '', epoch_lineage_id: '' });
    const m1 = ask846(fx, CLASS_846);
    assert(m1.result === 'ok' && m1.halt === 'written' && m1.standing_grant === false,
      '#846-M: with no claim identity the valve still ASKS — it does not refuse, and it raises no '
      + 'halt of its own. Fail safe, not fail closed, got '
      + JSON.stringify({ result: m1.result, reason: m1.reason, halt: m1.halt, standing_grant: m1.standing_grant }));
    const m2 = clear846(fx);
    assert(m2.result === 'ok' && m2.standing_grant_recorded == null,
      '#846-M: ...and the answer discharges THAT question and nothing further: with nothing to bind '
      + 'it to, no standing grant is recorded. A grant bound to a shared constant is a grant that no '
      + 'discard, restart or epoch can revoke, got '
      + JSON.stringify({ result: m2.result, recorded: m2.standing_grant_recorded }));
    const m3 = ask846(fx, CLASS_846);
    assert(m3.standing_grant === false && m3.halt === 'written' && haltMarker846(fx) === true,
      '#846-M: ...so the next instance asks again, got '
      + JSON.stringify({ standing_grant: m3.standing_grant, halt: m3.halt, marker: haltMarker846(fx) }));
    const m4 = orient846(fx);
    assert(Array.isArray(m4.consentGrants) && m4.consentGrants.length === 0,
      '#846-M: ...and the successor is never shown a grant the valve will not honour, got '
      + JSON.stringify(m4.consentGrants));
    cleanup846(fx);
  });

  // -------------------------------------------------------------------------
  // #846-N — ...AND THE SAME WHERE THERE IS NO POSITION RECORD AT ALL. #846-M blanks the two
  // claim-identity fields; here the epoch block is absent entirely, the shape that collapses EVERY
  // field to its fallback at once. That is one digest shared by every state in that condition, so the
  // stamp recorded alongside a grant is evidence of nothing. Same verdict, same reason: nothing to
  // bind to, so nothing is granted and the valve asks.
  // -------------------------------------------------------------------------
  scenario(() => {
    const fx = makeConsentRepo846();
    fs.writeFileSync(fx.statePath,
      'name: issue-846\nstatus: in_progress\nbranch: wf/846\nissue_number: 846\n');
    const n1 = ask846(fx, CLASS_846);
    assert(n1.result === 'ok' && n1.halt === 'written',
      '#846-N: the valve asks, got '
      + JSON.stringify({ result: n1.result, reason: n1.reason, halt: n1.halt }));
    const n2 = clear846(fx);
    assert(n2.result === 'ok' && n2.standing_grant_recorded == null,
      '#846-N: ...and records no standing grant, got '
      + JSON.stringify({ result: n2.result, recorded: n2.standing_grant_recorded }));
    const n3 = ask846(fx, CLASS_846);
    assert(n3.standing_grant === false && n3.halt === 'written',
      '#846-N: ...so it asks again, got '
      + JSON.stringify({ standing_grant: n3.standing_grant, halt: n3.halt }));
    cleanup846(fx);
  });

  // -------------------------------------------------------------------------
  // #846-O — A PENDING QUESTION DOES NOT SURVIVE A SCOPE MOVE. What keeps a grant narrow is the
  // PENDING request and nothing else: `clear-halt` can only ever mint the class a raise recorded, and
  // the revoking sync drops that record when the scope moves. So the only thing clearable after a
  // boundary is a question raised AFTER it — under the plan actually in front of the human.
  //
  // This is pinned here because it is the property most easily lost while REWRITING what `pending`
  // holds (#846-I). A pending record that outlived the boundary would let a discharge mint a grant
  // for a question put under a plan that no longer exists — the human answering one thing and the
  // machine recording consent under another, which is #846-I's defect arriving by a second road.
  // -------------------------------------------------------------------------
  scenario(() => {
    const fx = makeConsentRepo846();
    const o1 = ask846(fx, CLASS_846);
    assert(o1.halt === 'written' && o1.standing_grant === false,
      '#846-O precondition: the question is raised under the CURRENT scope, got '
      + JSON.stringify({ halt: o1.halt, standing_grant: o1.standing_grant }));

    // The scope moves while the question is still outstanding.
    patchState846(fx, { plan_epoch: 2 });

    const o2 = clear846(fx);
    assert(o2.result === 'ok' && o2.standing_grant_recorded == null,
      '#846-O: a discharge arriving after the move grants NOTHING — the pending request went with the '
      + 'scope it was raised under, got '
      + JSON.stringify({ result: o2.result, recorded: o2.standing_grant_recorded }));
    const o3 = ask846(fx, CLASS_846);
    assert(o3.standing_grant === false && o3.halt === 'written',
      '#846-O: ...so the class asks again under the new scope, got '
      + JSON.stringify({ standing_grant: o3.standing_grant, halt: o3.halt }));
    cleanup846(fx);
  });

  // -------------------------------------------------------------------------
  // #846-P (#858) — A REVOCATION THAT DID NOT PERSIST IS NOT A REVOCATION. The scope-move sync
  // journals `revoked` for every live class and WRITES the store; that write is the revocation and
  // nothing else is. If it fails, the journal on disk still ends at `granted`, the fold still
  // returns `live`, and the grant lookup that runs moments later in the SAME invocation rides it —
  // so a yes given under one plan, epoch and claim is spent under the ones the moved stamp existed
  // to end. Nobody is asked, and the only trace is an application entry that looks exactly like a
  // legitimate one.
  //
  // The two controls are what make this a measurement rather than a restatement: with the store
  // write LANDING the same scope move revokes and the valve asks (so the revocation itself works),
  // and with no move at all the grant is ridden (so the grant really is live and really would be
  // spent). Between them, the only variable left in the third arm is whether the write landed.
  // -------------------------------------------------------------------------
  scenario(() => {
    // Control 1 — the grant is live, and a live grant IS spent without asking.
    const fx = makeConsentRepo846();
    grant846(fx);
    const p0 = ask846(fx, CLASS_846);
    assert(p0.standing_grant === true && p0.halt === 'not_raised' && p0.applications === 1,
      '#846-P control 1: an unmoved scope rides the grant — this is the outcome the failed '
      + 'revocation must not be able to produce, got '
      + JSON.stringify({ standing_grant: p0.standing_grant, halt: p0.halt, applications: p0.applications }));

    // Control 2 — the same scope move with the store write LANDING: revoked, and the valve asks.
    const ctl = makeConsentRepo846();
    grant846(ctl);
    patchState846(ctl, { plan_epoch: 2 });
    const c1 = ask846(ctl, CLASS_846);
    assert(c1.standing_grant === false && c1.halt === 'written',
      '#846-P control 2: with the write landing, the moved scope revokes and the human is asked, '
      + 'got ' + JSON.stringify({ standing_grant: c1.standing_grant, halt: c1.halt }));
    assert(String(journal846(ctl)) === 'granted,revoked',
      '#846-P control 2: ...and the DURABLE record says so — the journal ends at revoked, got '
      + JSON.stringify(journal846(ctl)));
    cleanup846(ctl);

    // The case — the identical scope move, with the revocation write forced to fail.
    patchState846(fx, { plan_epoch: 2 });
    const beforeBytes = fs.readFileSync(store846(fx), 'utf8');
    const beforeEvents = journal846(fx);
    const fault = armStoreFault846(fx, 1);
    const p1 = run846Raw(fx, askArgs846(fx, CLASS_846), fault);

    assert(fault.attempts() >= 1,
      '#846-P vacuity guard: the injected fault must actually have been reached — a scenario whose '
      + 'injector never fired proves nothing, got ' + fault.attempts() + ' attempts');
    assert(p1.envelope.standing_grant !== true,
      '#846-P: the invocation must NOT speak on a grant whose revocation did not persist. This is '
      + 'the whole defect: pre-fix this arm answered standing_grant: true, halt: not_raised, and a '
      + 'human\'s yes was spent under a plan they never saw, got '
      + JSON.stringify({ result: p1.envelope.result, halt: p1.envelope.halt,
        standing_grant: p1.envelope.standing_grant, applications: p1.envelope.applications }));
    assert(p1.status !== 0,
      '#846-P: ...and it does not report success. A failed kernel-adjacent write that exits 0 is '
      + 'indistinguishable to every caller from one that landed, got exit ' + p1.status);
    assert(String(journal846(fx)) === String(beforeEvents),
      '#846-P: ...and the journal gains NOTHING — no application is recorded against a grant this '
      + 'run could not revoke, got ' + JSON.stringify(journal846(fx))
      + ' from ' + JSON.stringify(beforeEvents));
    assert(fs.readFileSync(store846(fx), 'utf8') === beforeBytes,
      '#846-P: ...and the store on disk is byte-unchanged: the failed write left no half-applied '
      + 'residue behind it');

    // Nothing was consumed. Once the fault clears, the SAME pending revocation still happens —
    // the failure deferred the revocation, it did not spend it.
    const p2 = ask846(fx, CLASS_846);
    assert(p2.standing_grant === false && p2.halt === 'written',
      '#846-P: the next invocation without the fault revokes and asks — a swallowed failure that '
      + 'ALSO consumed the revocation would leave the grant live forever, got '
      + JSON.stringify({ standing_grant: p2.standing_grant, halt: p2.halt }));
    assert((journal846(fx) || []).includes('revoked'),
      '#846-P: ...and the durable journal finally carries the revocation, got '
      + JSON.stringify(journal846(fx)));
    cleanup846(fx);
  });

  // -------------------------------------------------------------------------
  // #846-Q (#858) — AND A PROJECT THAT NEVER USED THE VALVE IS UNTOUCHED BY ANY OF IT. The
  // revocation sync runs in the guard prologue of `orient` and every replan-guarded mutation, so
  // the cost of it existing is paid by every run there is. With no journal it reads null and
  // returns before any write — which is why the store-write fault, armed to fail EVERY write, is
  // never even reached. Zero attempts, not zero successful writes: a write attempted and thrown
  // out of would satisfy "the file did not change" while being the exact opposite fact.
  //
  // The final arm is the vacuity guard, and it is not decoration: the three assertions above are
  // all satisfiable by an injector that failed to install, and this scenario cannot borrow #846-P's
  // proof because the two do not run together under a sharded suite.
  // -------------------------------------------------------------------------
  scenario(() => {
    const fx = makeConsentRepo846();
    const fault = armStoreFault846(fx, 0);
    assert(fs.existsSync(store846(fx)) === false,
      '#846-Q precondition: a fresh project has no consent journal at all');

    // The read-only successor surface, a guarded mutation, and its inverse — all under a fault
    // that fails every consent-store write there is.
    const q1 = run846Raw(fx, ['orient', '--project', fx.project, '--json'], fault);
    const q2 = run846Raw(fx, askArgs846(fx, null, 'security'), fault);
    const q3 = run846Raw(fx, ['clear-halt', '--project', fx.project, '--reason', 'security', '--json'], fault);

    assert(q1.status === 0 && q2.status === 0 && q3.status === 0,
      '#846-Q: every one of them completes normally, got exits '
      + JSON.stringify([q1.status, q2.status, q3.status]));
    assert(q1.envelope.result === 'ok' && Array.isArray(q1.envelope.consentGrants)
      && q1.envelope.consentGrants.length === 0 && q2.envelope.halt === 'written',
      '#846-Q: ...with their ordinary outcomes — orient reports an empty grant list and the halt '
      + 'lands, got ' + JSON.stringify({ orient: q1.envelope.consentGrants, halt: q2.envelope.halt }));
    assert(fault.attempts() === 0,
      '#846-Q: ...and not one write onto the consent store was ATTEMPTED across all three, got '
      + fault.attempts());
    assert(fs.existsSync(store846(fx)) === false,
      '#846-Q: ...so the store is still not there. The valve costs nothing until a human says yes');

    // Vacuity guard — the injector IS live in this process shape. Raising an ungranted class
    // records the pending request, which is a real consent-store write, and it must be caught.
    const q4 = run846Raw(fx, askArgs846(fx, CLASS_846), fault);
    assert(fault.attempts() >= 1 && q4.status !== 0,
      '#846-Q vacuity guard: the same armed fault DOES bite the moment the valve actually writes — '
      + 'the zero above is the code\'s early return, not a dead injector, got '
      + JSON.stringify({ attempts: fault.attempts(), exit: q4.status }));
    cleanup846(fx);
  });

  // -------------------------------------------------------------------------
  // #846-R (#858) — THE READ HALF IS UNCHANGED. An absent, empty or unparseable store still reads
  // as null and still returns before any write, so none of the above tightens what happens to a
  // corrupt journal: it is not repaired, not rewritten, and not treated as an integrity event.
  // -------------------------------------------------------------------------
  scenario(() => {
    for (const bytes of ['{ not json', '{"scope":"x"}', '', '[]']) {
      const fx = makeConsentRepo846();
      fs.writeFileSync(store846(fx), bytes);
      patchState846(fx, { plan_epoch: 2 });          // the scope HAS moved
      const fault = armStoreFault846(fx, 0);
      const r1 = run846Raw(fx, ['orient', '--project', fx.project, '--json'], fault);
      assert(r1.status === 0 && r1.envelope.result === 'ok',
        '#846-R: an unreadable store is not an integrity event — orient still answers, got '
        + JSON.stringify({ exit: r1.status, result: r1.envelope.result, bytes: bytes }));
      assert(fault.attempts() === 0 && fs.readFileSync(store846(fx), 'utf8') === bytes,
        '#846-R: ...and nothing is written over it, not even under a moved scope stamp, got '
        + JSON.stringify({ attempts: fault.attempts(), bytes: bytes }));
      cleanup846(fx);
    }
  });
}

shardLib.reportCoverage('test-adaptive-node', SHARD, scenarioCount, scenariosRun, passed, failed);
spawnCensus.report();

if (failed > 0) {
  console.error('adaptive-node tests FAILED (' + failed + ' failures, ' + passed + ' passed)');
  process.exitCode = 1;
} else {
  console.log('adaptive-node tests passed (' + passed + ' assertions)');
}
